(function(){if(!window.__hermes_register_book)return;window.__hermes_register_book("lucian-2-e", [{"sp": "HDR", "t": "Χάρων ἢ Ἐπισκοποῦντες"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> τί γελᾷς, ὦ Χάρων; ἢ τί τὸ πορθμεῖον ἀπολιπὼν δεῦρο ἀνελήλυθας εἰς τὴν ἡμετέραν οὐ πάνυ εἰωθὼς ἐπιχωριάζειν τοῖς ἄνω πράγμασιν;", "st": "23.1"}, {"sp": "N", "t": "<em>Χάρων.<\/em> ἐπεθύμησα, ὦ Ἑρμῆ, ἰδεῖν ὁποῖά ἐστι τὰ ἐν τῷ βίῳ καὶ ἃ πράττουσιν οἱ ἄνθρωποι ἐν αὐτῷ ἢ τίνων στερούμενοι πάντες οἰμώζουσι κατιόντες παρ’ ἡμᾶς· οὐδεὶς γὰρ αὐτῶν ἀδακρυτὶ διέπλευσεν. αἰτησάμενος οὖν παρὰ τοῦ Ἅιδου καὶ αὐτὸς ὥσπερ ὁ Θετταλὸς ἐκεῖνος νεανίσκος μίαν ἡμέραν λιπόνεως γενέσθαι ἀνελήλυθα ἐς τὸ φῶς, καί μοι δοκῶ εἰς δέον ἐντετυχηκέναι σοι· ξεναγήσεις γὰρ εὖ οἶδ’ ὅτι με συμπερινοστῶν καὶ δείξεις ἕκαστα ὡς ἂν εἰδὼς ἅπαντα.", "st": "23.1"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> οὐ σχολή μοι, ὦ πορθμεῦ· ἀπέρχομαι γάρ τι διακονησόμενος τῷ ἄνω Διὶ τῶν ἀνθρωπικῶν· ὁ δὲ ὀξύθυμός τέ ἐστι καὶ δέδια μὴ βραδύναντά με ὅλον ὑμέτερον ἐάσῃ εἶναι παραδοὺς τῷ ζόφῳ, ἢ ὅπερ τὸν Ἥφαιστον πρῴην ἐποίησε, ῥίψῃ κἀμὲ τεταγὼν τοῦ ποδὸς ἀπὸ τοῦ θεσπεσίου βηλοῦ, ὡς ὑποσκάζων γέλωτα παρέχοιμι καὶ αὐτὸς οἰνοχοῶν.", "st": "23.1"}, {"sp": "N", "t": "<em>Χάρων.<\/em> περιόψει οὖν με ἄλλως πλανώμενον ὑπὲρ γῆς, καὶ ταῦτα ἑταῖρος καὶ σύμπλους καὶ συνδιάκτορος ὤν; καὶ μὴν καλῶς εἶχεν, ὦ Μαίας παῖ, ἐκείνων γοῦν σε μεμνῆσθαι, ὅτι μηδεπώποτέ σε ἢ ἀντλεῖν ἐκέλευσα ἢ πρόσκωπον εἶναι· ἀλλὰ σὺ μὲν ῥέγκεις ἐπὶ τοῦ καταστρώματος ἐκταθεὶς ὤμους οὕτω καρτεροὺς ἔχων, ἢ εἴ τινα λάλον νεκρὸν εὕροις, ἐκείνῳ παρ’ ὅλον τὸν πλοῦν διαλέγῃ· ἐγὼ δὲ πρεσβύτης ὢν τὴν δικωπίαν ἐρέττω μόνος. ἀλλὰ πρὸς τοῦ πατρός, ὦ φίλτατον Ἑρμάδιον, μὴ καταλίπῃς με, περιήγησαι δὲ τὰ ἐν τῷ βίῳ ἅπαντα, ὥς τι καὶ ἰδὼν ἐπανέλθοιμι· ὡς ἤν με σὺ ἀφῇς, οὐδὲν τῶν τυφλῶν διοίσω· καθάπερ γὰρ ἐκεῖνοι σφάλλονται καὶ διολισθάνουσιν ἐν τῷ σκότῳ, οὕτω δὴ κἀγώ σοι ἔμπαλιν ἀμβλυώττω πρὸς τὸ φῶς. ἀλλὰ δός, ὦ Κυλλήνιε, ἐς ἀεὶ μεμνησομένῳ τὴν χάριν.", "st": "23.1"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> τοῦτο τὸ πρᾶγμα πληγῶν αἴτιον καταστήσεταί μοι· ὁρῶ γοῦν ἤδη τὸν μισθὸν τῆς περιηγήσεως οὐκ ἀκόνδυλον παντάπασιν ἡμῖν ἐσόμενον. ὑπουργητέον δὲ ὅμως· τί γὰρ ἂν καὶ πάθοι τις, ὁπότε φίλος τις ὢν βιάζοιτο;", "st": "23.2"}, {"sp": "N", "t": "πάντα μὲν οὖν σε ἰδεῖν καθ’ ἕκαστον ἀκριβῶς ἀμήχανόν ἐστιν, ὦ πορθμεῦ· πολλῶν γὰρ ἂν ἐτῶν ἡ διατριβὴ γένοιτο. εἶτα ἐμὲ μὲν κηρύττεσθαι δεήσει καθάπερ ἀποδράντα ὑπὸ τοῦ Διός, σὲ δὲ καὶ αὐτὸν κωλύσει ἐνεργεῖν τὰ τοῦ Θανάτου ἔργα καὶ τὴν Πλούτωνος ἀρχὴν ζημιοῦν μὴ νεκραγωγοῦντα πολλοῦ τοῦ χρόνου· κᾆτα ὁ τελώνης Αἰακὸς ἀγανακτήσει μηδ’ ὀβολὸν ἐμπολῶν. ὡς δὲ τὰ κεφάλαια τῶν γιγνομένων ἴδοις, τοῦτο ἤδη σκεπτέον.", "st": "23.2"}, {"sp": "N", "t": "<em>Χάρων.<\/em> αὐτός, ὦ Ἑρμῆ, ἐπινόει τὸ βέλτιστον· ἐγὼ δὲ οὐδὲν οἶδα τῶν ὑπὲρ γῆς ξένος ὤν.", "st": "23.2"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> τὸ μὲν ὅλον, ὦ Χάρων, ὑψηλοῦ τινος ἡμῖν δεῖ χωρίου, ὡς ἀπ’ ἐκείνου πάντα κατίδοις· σοὶ δὲ εἰ μὲν ἐς τὸν οὐρανὸν ἀνελθεῖν δυνατὸν ἦν, οὐκ ἂν ἐκάμνομεν· ἐκ περιωπῆς γὰρ ἂν ἀκριβῶς ἅπαντα καθεώρας. ἐπεὶ δὲ οὐ θέμις εἰδώλοις ἀεὶ συνόντα ἐπιβατεύειν τῶν βασιλείων τοῦ Διός, ὥρα ἡμῖν ὑψηλόν τι ὄρος περισκοπεῖν.", "st": "23.2"}, {"sp": "N", "t": "<em>Χάρων.<\/em> οἶσθα, ὦ Ἑρμῆ, ἅπερ εἴωθα λέγειν ἐγὼ πρὸς ὑμᾶς, ἐπειδὰν πλέωμεν; ὁπόταν γὰρ τὸ πνεῦμα καταιγίσαν πλαγίᾳ τῇ ὀθόνῃ ἐμπέσῃ καὶ τὸ κῦμα ὑψηλὸν ἀρθῇ, τότε ὑμεῖς μὲν ὑπ’ ἀγνοίας κελεύετε τὴν ὀθόνην στεῖλαι ἢ ἐνδοῦναι ὀλίγον τοῦ ποδὸς ἢ συνεκδραμεῖν τῷ πνεύματι, ἐγὼ δὲ τὴν ἡσυχίαν ἄγειν παρακελεύομαι ὑμῖν· αὐτὸς γὰρ εἰδέναι τὸ βέλτιον. κατὰ ταὐτὰ δὴ καὶ σὺ πρᾶττε ὁπόσα καλῶς ἔχειν νομίζεις κυβερνήτης νῦν γε ὤν· ἐγὼ δέ, ὥσπερ ἐπιβάταις νόμος, σιωπῇ καθεδοῦμαι πάντα πειθόμενος κελεύοντί σοι.", "st": "23.3"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> ὀρθῶς λέγεις· αὐτὸς γὰρ εἴσομαι τί ποιητέον καὶ ἐξευρήσω τὴν ἱκανὴν σκοπήν. ἆρ’ οὖν ὁ Καύκασος ἐπιτήδειος ἢ ὁ Παρνασσὸς ἢ ὑψηλότερος ἀμφοῖν ὁ Ὄλυμπος ἐκεινοσί; καίτοι οὐ φαῦλον ὃ ἀνεμνήσθην ἐς τὸν Ὄλυμπον ἀπιδών· συγκαμεῖν δέ τι καὶ ὑπουργῆσαι καὶ σὲ δεῖ.", "st": "23.3"}, {"sp": "N", "t": "<em>Χάρων.<\/em> πρόσταττε· ὑπουργήσω γὰρ ὅσα δυνατά.", "st": "23.3"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> Ὅμηρος ὁ ποιητής φησι τοὺς Ἀλωέως υἱέας, δύο καὶ αὐτοὺς ὄντας, ἔτι παῖδας ἐθελῆσαί ποτε τὴν Ὄσσαν ἐκ βάθρων ἀνασπάσαντας ἐπιθεῖναι τῷ Ὀλύμπῳ, εἶτα τὸ Πήλιον ἐπ’ αὐτῇ, ἱκανὴν ταύτην κλίμακα ἕξειν οἰομένους καὶ πρόσβασιν ἐπὶ τὸν οὐρανόν. ἐκείνω μὲν οὖν τὼ μειρακίω, ἀτασθάλω γὰρ ἤστην, δίκας ἐτισάτην· νὼ δὲ — οὐ γὰρ ἐπὶ κακῷ τῶν θεῶν ταῦτα βουλεύομεν — τί οὐχὶ οἰκοδομοῦμεν καὶ αὐτοὶ κατὰ τὰ αὐτὰ ἐπικυλινδοῦντες ἐπάλληλα τὰ ὄρη, ὡς ἔχοιμεν ἀφ’ ὑψηλοτέρου ἀκριβεστέραν τὴν σκοπήν;", "st": "23.3"}, {"sp": "N", "t": "<em>Χάρων.<\/em> καὶ δυνησόμεθα, ὦ Ἑρμῆ, δύ’ ὄντες ἀναθέσθαι ἀράμενοι τὸ Πήλιον ἢ τὴν Ὄσσαν;", "st": "23.4"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> διὰ τί δ’ οὐκ ἄν, ὦ Χάρων; ἢ ἀξιοῖς ἡμᾶς ἀγεννεστέρους εἶναι τοῖν βρεφυλλίοιν ἐκείνοιν, καὶ ταῦτα θεοὺς ὑπάρχοντας;", "st": "23.4"}, {"sp": "N", "t": "<em>Χάρων.<\/em> οὔκ, ἀλλὰ τὸ πρᾶγμα δοκεῖ μοι ἀπίθανόν τινα τὴν μεγαλουργίαν ἔχειν.", "st": "23.4"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> εἰκότως· ἰδιώτης γὰρ εἶ, ὦ Χάρων, καὶ ἥκιστα ποιητικός· ὁ δὲ γεννάδας Ὅμηρος ἀπὸ δυοῖν στίχοιν αὐτίκα ἡμῖν ἀμβατὸν ἐποίησε τὸν οὐρανόν, οὕτω ῥᾳδίως συνθεὶς τὰ ὄρη. καὶ θαυμάζω εἴ σοι ταῦτα τεράστια εἶναι δοκεῖ τὸν Ἄτλαντα δηλαδὴ εἰδότι, ὃς τὸν πόλον αὐτὸν εἷς ὢν φέρει ἀνέχων ἡμᾶς ἅπαντας. ἀκούεις δέ γε ἴσως καὶ τοῦ ἀδελφοῦ τοῦ ἐμοῦ πέρι τοῦ Ἡρακλέους, ὡς διαδέξαιτό ποτε αὐτὸς ἐκεῖνος τὸν Ἄτλαντα, καὶ ἀναπαύσειε πρὸς ὀλίγον τοῦ ἄχθους ὑποθεὶς ἑαυτὸν τῷ φορτίῳ.", "st": "23.4"}, {"sp": "N", "t": "<em>Χάρων.<\/em> ἀκούω καὶ ταῦτα· εἰ δὲ ἀληθῆ ἔστιν, σὺ ἄν, ὦ Ἑρμῆ, καὶ οἱ ποιηταὶ εἰδείητε.", "st": "23.4"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> ἀληθέστατα, ὦ Χάρων. ἢ τίνος γὰρ ἕνεκα σοφοὶ ἄνδρες ἐψεύδοντο ἄν; ὥστε ἀναμοχλεύωμεν τὴν Ὄσσαν πρῶτον, ὥσπερ ἡμῖν ὑφηγεῖται τὸ ἔπος καὶ ὁ ἀρχιτέκτων Ὅμηρος,<br>αὐτὰρ ἐπ’ Ὄσσῃ<br>Πήλιον εἰνοσίφυλλον.<br>ὁρᾷς ὅπως ῥᾳδίως ἅμα καὶ ποιητικῶς ἐξειργασάμεθα; φέρ’ οὖν ἀναβὰς ἴδω, εἰ καὶ ταῦτα ἱκανὰ ἢ ἐποικοδομεῖν ἔτι δεήσει.", "st": "23.4"}, {"sp": "N", "t": "παπαῖ, κάτω ἔτι ἐσμὲν ἐν ὑπωρείᾳ τοῦ οὐρανοῦ· ἀπὸ μὲν γὰρ τῶν ἑῴων μόγις Ἰωνία καὶ Λυδία φαίνεται, ἀπὸ δὲ τῆς ἑσπέρας οὐ πλέον Ἰταλίας καὶ Σικελίας, ἀπὸ δὲ τῶν ἀρκτῴων τὰ ἐπὶ τάδε τοῦ Ἴστρου μόνον, κἀκεῖθεν ἡ Κρήτη οὐ πάνυ σαφῶς. μετακινητέα ἡμῖν, ὦ πορθμεῦ, καὶ ἡ Οἴτη, ὡς ἔοικεν, εἶτα ὁ Παρνασσὸς ἐπὶ πᾶσιν.", "st": "23.5"}, {"sp": "N", "t": "<em>Χάρων.<\/em> οὕτω ποιῶμεν. ὅρα μόνον μὴ λεπτότερον ἐξεργασώμεθα τὸ ἔργον ἀπομηκύναντες πέρα τοῦ πιθανοῦ, εἶτα συγκαταρριφέντες αὐτῷ πικρᾶς τῆς Ὁμήρου οἰκοδομικῆς πειραθῶμεν συντριβέντες τῶν κρανίων.", "st": "23.5"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> θάρρει· ἀσφαλῶς γὰρ ἕξει ἅπαντα. μετατίθει τὴν Οἴτην· ἐπικυλινδείσθω ὁ Παρνασσός. ἰδοὺ δή, ἐπάνειμι αὖθις· εὖ ἔχει· πάντα ὁρῶ· ἀνάβαινε ἤδη καὶ σύ.", "st": "23.5"}, {"sp": "N", "t": "<em>Χάρων.<\/em> ὄρεξον, ὦ Ἑρμῆ, τὴν χεῖρα· οὐ γὰρ ἐπὶ μικράν με ταύτην μηχανὴν ἀναβιβάζεις.", "st": "23.5"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> εἴ γε καὶ ἰδεῖν ἐθέλεις, ὦ Χάρων, ἅπαντα· οὐκ ἔνι δὲ ἄμφω καὶ ἀσφαλῆ καὶ φιλοθεάμονα εἶναι. ἀλλ’ ἔχου μου τῆς δεξιᾶς καὶ φείδου μὴ κατὰ τοῦ ὀλισθηροῦ πατεῖν. εὖ γε, ἀνελήλυθας καὶ σύ· καὶ ἐπείπερ δικόρυμβος ὁ Παρνασσός ἐστι, μίαν ἑκάτερος ἄκραν ἀπολαβόμενοι καθεζώμεθα· σὺ δέ μοι ἤδη ἐν κύκλῳ περιβλέπων ἐπισκόπει ἅπαντα.", "st": "23.5"}, {"sp": "N", "t": "<em>Χάρων.<\/em> ὁρῶ γῆν πολλὴν καὶ λίμνην τινὰ μεγάλην περιρρέουσαν καὶ ὄρη καὶ ποταμοὺς τοῦ Κωκυτοῦ καὶ Πυριφλεγέθοντος μείζονας καὶ ἀνθρώπους πάνυ σμικροὺς καί τινας φωλεοὺς αὐτῶν.", "st": "23.6"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> πόλεις ἐκεῖναί εἰσιν οὓς φωλεοὺς εἶναι νομίζεις.", "st": "23.6"}, {"sp": "N", "t": "<em>Χάρων.<\/em> οἶσθα οὖν, ὦ Ἑρμῆ, ὡς οὐδὲν ἡμῖν πέπρακται, ἀλλὰ μάτην τὸν Παρνασσὸν αὐτῇ Κασταλίᾳ καὶ τὴν Οἴτην καὶ τὰ ἄλλα ὄρη μετεκινήσαμεν;", "st": "23.6"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> ὅτι τί;", "st": "23.6"}, {"sp": "N", "t": "<em>Χάρων.<\/em> οὐδὲν ἀκριβὲς ἐγὼ γοῦν ἀπὸ τοῦ ὑψηλοῦ ὁρῶ· ἐδεόμην δὲ οὐ πόλεις καὶ ὄρη αὐτὸ μόνον ὥσπερ ἐν γραφαῖς ὁρᾶν, ἀλλὰ τοὺς ἀνθρώπους αὐτοὺς καὶ ἃ πράττουσι καὶ οἷα λέγουσιν. ὥσπερ ὅτε με τὸ πρῶτον ἐντυχὼν εἶδες γελῶντα καὶ ἤρου γε ὅ τι γελῴην, ἀκούσας τινὸς ἥσθην εἰς ὑπερβολήν.", "st": "23.6"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> τί δὲ τοῦτο ἦν;", "st": "23.6"}, {"sp": "N", "t": "<em>Χάρων.<\/em> ἐπὶ δεῖπνον, οἶμαι, κληθείς τις ὑπό τινος τῶν φίλων ἐς τὴν ὑστεραίαν, “μάλιστα ἥξω,” ἔφη, καὶ μεταξὺ λέγοντος ἀπὸ τοῦ τέγους κεραμὶς ἐμπεσοῦσα οὐκ οἶδ’ ὅτου κινήσαντος ἀπέκτεινεν αὐτόν. ἐγέλασα οὖν οὐκ ἐπιτελέσαντος τὴν ὑπόσχεσιν. ἔοικα δὲ καὶ νῦν ὑποκαταβήσεσθαι, ὡς μᾶλλον βλέποιμι καὶ ἀκούοιμι.", "st": "23.6"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> ἔχ’ ἀτρέμα· καὶ τοῦτο γὰρ ἐγὼ ἰάσομαί σοι καὶ ὀξυδερκέστατον ἐν βραχεῖ σε ἀποφανῶ παρ’ Ὁμήρου τινὰ καὶ πρὸς τοῦτο ἐπῳδὴν λαβών, κἀπειδὰν εἴπω τὰ ἔπη, μέμνησο μηκέτι ἀμβλυώττειν, ἀλλὰ σαφῶς πάντα ὁρᾶν.", "st": "23.7"}, {"sp": "N", "t": "<em>Χάρων.<\/em> λέγε μόνον.", "st": "23.7"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> ἀχλὺν δ’ αὖ τοι ἀπ’ ὀφθαλμῶν ἕλον, ἣ πρὶν ἐπῆεν,<br>ὄφρ’ εὖ γινώσκοις ἠμὲν θεὸν ἠδὲ καὶ ἄνδρα.<br>τί ἐστιν; ἤδη ὁρᾷς;", "st": "23.7"}, {"sp": "N", "t": "<em>Χάρων.<\/em> ὑπερφυῶς γε· τυφλὸς ὁ Λυγκεὺς ἐκεῖνος ὡς πρὸς ἐμέ· ὥστε σὺ τὸ ἐπὶ τούτῳ προσδίδασκέ με καὶ ἀποκρίνου ἐρωτῶντι. ἀλλὰ βούλει κατὰ τὸν Ὅμηρον κἀγὼ ἔρωμαί σε, ὡς μάθῃς οὐδ’ αὐτὸν ἀμελέτητον ὄντα με τῶν Ὁμήρου;", "st": "23.7"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> καὶ πόθεν σὺ ἔχεις τι τῶν ἐκείνου εἰδέναι, ναύτης ἀεὶ καὶ πρόσκωπος ὤν;", "st": "23.7"}, {"sp": "N", "t": "<em>Χάρων.<\/em> ὁρᾷς, ὀνειδιστικὸν τοῦτο εἰς τὴν τέχνην. ἐγὼ δὲ ὁπότε διεπόρθμευον αὐτὸν ἀποθανόντα, πολλὰ ῥαψῳδοῦντος ἀκούσας ἐνίων ἔτι μέμνημαι· καίτοι χειμὼν ἡμᾶς οὐ μικρὸς τότε κατελάμβανεν. ἐπεὶ γὰρ ἤρξατο ᾄδειν οὐ πάνυ αἴσιόν τινα ᾠδὴν τοῖς πλέουσιν, ὡς ὁ Ποσειδῶν συνήγαγε τὰς νεφέλας καὶ ἐτάραξε τὸν πόντον ὥσπερ τορύνην τινὰ ἐμβαλὼν τὴν τρίαιναν καὶ πάσας τὰς θυέλλας ὠρόθυνε καὶ ἄλλα πολλά, κυκῶν τὴν θάλατταν ὑπὸ τῶν ἐπῶν, χειμὼν ἄφνω καὶ γνόφος ἐμπεσὼν ὀλίγου δεῖν περιέτρεψεν ἡμῖν τὴν ναῦν· ὅτε περ καὶ ναυτιάσας ἐκεῖνος ἀπήμεσε τῶν ῥαψῳδιῶν τὰς πολλὰς αὐτῇ Σκύλλῃ καὶ Χαρύβδει καὶ Κύκλωπι. οὐ χαλεπὸν οὖν ἦν ἐκ τοσούτου ἐμέτου ὀλίγα γοῦν διαφυλάττειν.", "st": "23.7"}, {"sp": "N", "t": "εἰπὲ γάρ μοι·<br>τίς τ’ ἄρ’ ὅδ’ ἐστὶ πάχιστος ἀνὴρ ἠΰς τε μέγας τε,<br>ἔξοχος ἀνθρώπων κεφαλὴν καὶ εὐρέας ὤμους;", "st": "23.8"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> Μίλων οὗτος ὁ ἐκ Κρότωνος ἀθλητής. ἐπικροτοῦσι δ’ αὐτῷ οἱ Ἕλληνες, ὅτι τὸν ταῦρον ἀράμενος φέρει διὰ τοῦ σταδίου μέσου.", "st": "23.8"}, {"sp": "N", "t": "<em>Χάρων.<\/em> καὶ πόσῳ δικαιότερον ἂν ἐμέ, ὦ Ἑρμῆ, ἐπαινοῖεν, ὃς αὐτόν σοι τὸν Μίλωνα μετ’ ὀλίγοι συλλαβὼν ἐνθήσομαι ἐς τὸ σκαφίδιον, ὁπόταν ἥκῃ πρὸς ἡμᾶς ὑπὸ τοῦ ἀμαχωτάτου τῶν ἀνταγωνιστῶν καταπαλαισθεὶς τοῦ Θανάτου, μηδὲ συνεὶς ὅπως αὐτὸν ὑποσκελίζει; κᾆτα οἰμώξεται ἡμῖν δηλαδὴ μεμνημένος τῶν στεφάνων τούτων καὶ τοῦ κρότου· νῦν δὲ μέγα φρονεῖ θαυμαζόμενος ἐπὶ τῇ τοῦ ταύρου φορᾷ. τί δ’ οὖν; οἰηθῶμεν ἄρα ἐλπίζειν αὐτὸν καὶ τεθνήξεσθαί ποτε;", "st": "23.8"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> πόθεν ἐκεῖνος θανάτου νῦν μνημονεύσειεν ἂν ἐν ἀκμῇ τοσαύτῃ;", "st": "23.8"}, {"sp": "N", "t": "<em>Χάρων.<\/em> ἔα τοῦτον οὐκ εἰς μακρὰν γέλωτα ἡμῖν παρέξοντα ὁπόταν πλέῃ, μηδ’ ἐμπίδα οὐχ ὅπως ταῦρον ἔτι ἄρασθαι δυνάμενος.", "st": "23.8"}, {"sp": "N", "t": "σὺ δέ μοι ἐκεῖνο εἰπέ,<br>τίς τ’ ἄρ’ ὅδ’ ἄλλος ὁ σεμνὸς ἀνήρ;<br>οὐχ Ἕλλην, ὡς ἔοικεν, ἀπὸ γοῦν τῆς στολῆς.", "st": "23.9"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> Κῦρος, ὦ Χάρων, ὁ Καμβύσου, ὃς τὴν ἀρχὴν πάλαι Μήδων ἐχόντων νῦν Περσῶν ἤδη ἐποίησεν εἶναι· καὶ Ἀσσυρίων δ’ ἔναγχος οὗτος ἐκράτησε καὶ Βαβυλῶνα παρεστήσατο καὶ νῦν ἐλασείοντι ἐπὶ Λυδίαν ἔοικεν, ὡς καθελὼν τὸν Κροῖσον ἄρχοι ἁπάντων.", "st": "23.9"}, {"sp": "N", "t": "<em>Χάρων.<\/em> ὁ Κροῖσος δὲ ποῦ ποτε κἀκεῖνός ἐστιν;", "st": "23.9"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> ἐκεῖσε ἀπόβλεψον ἐς τὴν μεγάλην ἀκρόπολιν, τὴν τὸ τριπλοῦν τεῖχος· Σάρδεις ἐκεῖναι, καὶ τὸν Κροῖσον αὐτὸν ὁρᾷς ἤδη ἐπὶ κλίνης χρυσῆς καθήμενον, Σόλωνι τῷ Ἀθηναίῳ διαλεγόμενον. βούλει ἀκούσωμεν αὐτῶν ὅ τι καὶ λέγουσι;", "st": "23.9"}, {"sp": "N", "t": "<em>Χάρων.<\/em> πάνυ μὲν οὖν.", "st": "23.9"}, {"sp": "N", "t": "<em>Κροῖσος.<\/em> ὦ ξένε Ἀθηναῖε, εἶδες γάρ μου τὸν πλοῦτον καὶ τοὺς θησαυροὺς καὶ ὅσος ἄσημος χρυσός ἐστιν ἡμῖν καὶ τὴν ἄλλην πολυτέλειαν, εἰπέ μοι, τίνα ἡγῇ τῶν ἁπάντων ἀνθρώπων εὐδαιμονέστατον εἶναι.", "st": "23.10"}, {"sp": "N", "t": "<em>Χάρων.<\/em> τί ἄρα ὁ Σόλων ἐρεῖ;", "st": "23.10"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> θάρρει· οὐδὲν ἀγεννές, ὦ Χάρων.", "st": "23.10"}, {"sp": "N", "t": "<em>Σόλων.<\/em> ὦ Κροῖσε, ὀλίγοι μὲν οἱ εὐδαίμονες· ἐγὼ δὲ ὧν οἶδα Κλέοβιν καὶ Βίτωνα ἡγοῦμαι εὐδαιμονεστάτους γενέσθαι, τοὺς τῆς ἱερείας παῖδας τῆς Ἀργόθεν, τοὺς ἅμα πρῴην ἀποθανόντας, ἐπεὶ τὴν μητέρα ὑποδύντες εἵλκυσαν ἐπὶ τῆς ἀπήνης ἄχρι πρὸς τὸ ἱερόν.", "st": "23.10"}, {"sp": "N", "t": "<em>Κροῖσος.<\/em> ἔστω· ἐχέτωσαν ἐκεῖνοι τὰ πρῶτα τῆς εὐδαιμονίας. ὁ δεύτερος δὲ τίς ἂν εἴη;", "st": "23.10"}, {"sp": "N", "t": "<em>Σόλων.<\/em> Τέλλος ὁ Ἀθηναῖος, ὃς εὖ τ’ ἐβίω καὶ ἀπέθανεν ὑπὲρ τῆς πατρίδος.", "st": "23.10"}, {"sp": "N", "t": "<em>Κροῖσος.<\/em> ἐγὼ δέ, ὦ κάθαρμα, οὔ σοι δοκῶ εὐδαίμων εἶναι;", "st": "23.10"}, {"sp": "N", "t": "<em>Σόλων.<\/em> οὐδέπω οἶδα, ὦ Κροῖσε, ἢν μὴ πρὸς τὸ τέλος ἀφίκῃ τοῦ βίου· ὁ γὰρ θάνατος ἀκριβὴς ἔλεγχος τῶν τοιούτων καὶ τὸ ἄχρι πρὸς τὸ τέρμα εὐδαιμόνως διαβιῶναι.", "st": "23.10"}, {"sp": "N", "t": "<em>Χάρων.<\/em> κάλλιστα, ὦ Σόλων, ὅτι ἡμῶν οὐκ ἐπιλέλησαι, ἀλλὰ παρὰ τὸ πορθμεῖον αὐτὸ ἀξιοῖς γίγνεσθαι τὴν περὶ τῶν τοιούτων κρίσιν.", "st": "23.10"}, {"sp": "N", "t": "ἀλλὰ τίνας ἐκείνους ὁ Κροῖσος ἐκπέμπει ἢ τί ἐπὶ τῶν ὤμων φέρουσι;", "st": "23.11"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> πλίνθους τῷ Πυθίῳ χρυσᾶς ἀνατίθησι μισθὸν τῶν χρησμῶν ὑφ’ ὧν καὶ ἀπολεῖται μικρὸν ὕστερον· φιλόμαντις δὲ ἁνὴρ ἐκτόπως.", "st": "23.11"}, {"sp": "N", "t": "<em>Χάρων.<\/em> ἐκεῖνο γάρ ἐστιν ὁ χρυσός, τὸ λαμπρὸν ὃ ἀποστίλβει, τὸ ὕπωχρον μετ’ ἐρυθήματος; νῦν γὰρ πρῶτον εἶδον, ἀκούων ἀεί.", "st": "23.11"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> ἐκεῖνο, ὦ Χάρων, τὸ ἀοίδιμον ὄνομα καὶ περιμάχητον.", "st": "23.11"}, {"sp": "N", "t": "<em>Χάρων.<\/em> καὶ μὴν οὐχ ὁρῶ ὅ τι τὸ ἀγαθὸν αὐτῷ πρόσεστιν, εἰ μὴ ἄρα ἕν τι μόνον, ὅτι βαρύνονται οἱ φέροντες αὐτό.", "st": "23.11"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> οὐ γὰρ οἶσθα ὅσοι πόλεμοι διὰ τοῦτο καὶ ἐπιβουλαὶ καὶ λῃστήρια καὶ ἐπιορκίαι καὶ φόνοι καὶ δεσμὰ καὶ ἐμπορίαι καὶ δουλεῖαι;", "st": "23.11"}, {"sp": "N", "t": "<em>Χάρων.<\/em> διὰ τοῦτο, ὦ Ἑρμῆ, τὸ μὴ πολὺ τοῦ χαλκοῦ διαφέρον; οἶδα γὰρ τὸν χαλκόν, ὀβολόν, ὡς οἶσθα, παρὰ τῶν καταπλεόντων ἑκάστου ἐκλέγων.", "st": "23.11"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> ναί· ἀλλὰ ὁ χαλκὸς μὲν πολύς, ὥστε οὐ πάνυ σπουδάζεται ὑπ’ αὐτῶν· τοῦτον δὲ ὀλίγον ἐκ πολλοῦ τοῦ βάθους οἱ μεταλλεύοντες ἀνορύττουσι· πλὴν ἀλλὰ ἐκ τῆς γῆς καὶ οὗτος ὥσπερ ὁ μόλυβδος καὶ τὰ ἄλλα.", "st": "23.11"}, {"sp": "N", "t": "<em>Χάρων.<\/em> δεινήν τινα λέγεις τῶν ἀνθρώπων τὴν ἀβελτερίαν, οἳ τοσοῦτον ἔρωτα ἐρῶσιν ὠχροῦ καὶ βαρέος κτήματος.", "st": "23.11"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> ἀλλὰ οὐ Σόλων γε ἐκεῖνος, ὦ Χάρων, ἐρᾶν αὐτοῦ φαίνεται, ὅς, ὡς ὁρᾷς, καταγελᾷ τοῦ Κροίσου καὶ τῆς μεγαλαυχίας τοῦ βαρβάρου, καί μοι δοκεῖν ἐρέσθαι τι βούλεται αὐτόν· ἐπακούσωμεν οὖν.", "st": "23.11"}, {"sp": "N", "t": "<em>Σόλων.<\/em> εἰπέ μοι, ὦ Κροῖσε, οἴει γάρ τι δεῖσθαι τῶν πλίνθων τούτων τὸν Πύθιον;", "st": "23.12"}, {"sp": "N", "t": "<em>Κροῖσος.<\/em> νὴ Δί’· οὐ γάρ ἐστιν αὐτῷ ἐν Δελφοῖς ἀνάθημα οὐδὲν τοιοῦτον.", "st": "23.12"}, {"sp": "N", "t": "<em>Σόλων.<\/em> οὐκοῦν μακάριον οἴει τὸν θεὸν ἀποφανεῖν, εἰ κτήσαιτο σὺν τοῖς ἄλλοις καὶ πλίνθους χρυσᾶς;", "st": "23.12"}, {"sp": "N", "t": "<em>Κροῖσος.<\/em> πῶς γὰρ οὔ;", "st": "23.12"}, {"sp": "N", "t": "<em>Σόλων.<\/em> πολλήν μοι λέγεις, ὦ Κροῖσε, πενίαν ἐν τῷ οὐρανῷ, εἰ ἐκ Λυδίας μεταστέλλεσθαι τὸ χρυσίον δεήσει αὐτούς, ἢν ἐπιθυμήσωσι.", "st": "23.12"}, {"sp": "N", "t": "<em>Κροῖσος.<\/em> ποῦ γὰρ τοσοῦτος ἂν γίνοιτο χρυσὸς ὅσος παρ’ ἡμῖν;", "st": "23.12"}, {"sp": "N", "t": "<em>Σόλων.<\/em> εἰπέ μοι, σίδηρος δὲ φύεται ἐν Λυδίᾳ;", "st": "23.12"}, {"sp": "N", "t": "<em>Κροῖσος.<\/em> οὐ πάνυ τι.", "st": "23.12"}, {"sp": "N", "t": "<em>Σόλων.<\/em> τοῦ βελτίονος ἄρα ἐνδεεῖς ἐστε.", "st": "23.12"}, {"sp": "N", "t": "<em>Κροῖσος.<\/em> πῶς ἀμείνων ὁ σίδηρος χρυσίου;", "st": "23.12"}, {"sp": "N", "t": "<em>Σόλων.<\/em> ἢν ἀποκρίνῃ μηδὲν ἀγανακτῶν, μάθοις ἄν.", "st": "23.12"}, {"sp": "N", "t": "<em>Κροῖσος.<\/em> ἐρώτα, ὦ Σόλων.", "st": "23.12"}, {"sp": "N", "t": "<em>Σόλων.<\/em> πότεροι ἀμείνους, οἱ σώζοντές τινας ἢ οἱ σωζόμενοι πρὸς αὐτῶν;", "st": "23.12"}, {"sp": "N", "t": "<em>Κροῖσος.<\/em> οἱ σώζοντες δηλαδή.", "st": "23.12"}, {"sp": "N", "t": "<em>Σόλων.<\/em> ἆρ’ οὖν, ἢν Κῦρος, ὡς λογοποιοῦσι τινες, ἐπίῃ Λυδοῖς, χρυσᾶς μαχαίρας σὺ ποιήσῃ τῷ στρατῷ, ἢ ὁ σίδηρος ἀναγκαῖος τότε;", "st": "23.12"}, {"sp": "N", "t": "<em>Κροῖσος.<\/em> ὁ σίδηρος δῆλον ὅτι.", "st": "23.12"}, {"sp": "N", "t": "<em>Σόλων.<\/em> καὶ εἴ γε τοῦτον μὴ παρασκευάσαιο, οἴχοιτο ἄν σοι ὁ χρυσὸς ἐς Πέρσας αἰχμάλωτος.", "st": "23.12"}, {"sp": "N", "t": "<em>Κροῖσος.<\/em> εὐφήμει, ἄνθρωπε.", "st": "23.12"}, {"sp": "N", "t": "<em>Σόλων.<\/em> μὴ γένοιτο μὲν οὕτω ταῦτα· φαίνῃ δ’ οὖν ἀμείνω τοῦ χρυσοῦ τὸν σίδηρον ὁμολογῶν.", "st": "23.12"}, {"sp": "N", "t": "<em>Κροῖσος.<\/em> οὐκοῦν καὶ τῷ θεῷ σιδηρᾶς πλίνθους κελεύεις ἀνατιθέναι με, τὸν δὲ χρυσὸν ὀπίσω αὖθις ἀνακαλεῖν;", "st": "23.12"}, {"sp": "N", "t": "<em>Σόλων.<\/em> οὐδὲ σιδήρου ἐκεῖνός γε δεήσεται, ἀλλ’ ἤν τε χαλκὸν ἤν τε χρυσὸν ἀναθῇς, ἄλλοις μέν ποτε κτῆμα καὶ ἕρμαιον ἔσῃ ἀνατεθεικώς, Φωκεῦσιν ἢ Βοιωτοῖς ἢ Δελφοῖς αὐτοῖς ἤ τινι τυράννῳ ἢ λῃστῇ, τῷ δὲ θεῷ ὀλίγον μέλει τῶν σῶν χρυσοποιιῶν.", "st": "23.12"}, {"sp": "N", "t": "<em>Κροῖσος.<\/em> ἀεὶ σύ μου τῷ πλούτῳ προσπολεμεῖς καὶ φθονεῖς.", "st": "23.12"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> οὐ φέρει ὁ Λυδός, ὦ Χάρων, τὴν παρρησίαν καὶ τὴν ἀλήθειαν τῶν λόγων, ἀλλὰ ξένον αὐτῷ δοκεῖ τὸ πρᾶγμα, πένης ἄνθρωπος οὐχ ὑποπτήσσων, τὸ δὲ παριστάμενον ἐλευθέρως λέγων. μεμνήσεται δ’ οὖν μικρὸν ὕστερον τοῦ Σόλωνος, ὅταν αὐτὸν δέῃ ἁλόντα ἐπὶ τὴν πυρὰν ὑπὸ τοῦ Κύρου ἀναχθῆναι· ἤκουσα γὰρ τῆς Κλωθοῦς πρῴην ἀναγινωσκούσης τὰ ἑκάστῳ ἐπικεκλωσμένα, ἐν οἷς καὶ ταῦτα ἐγέγραπτο, Κροῖσον μὲν ἁλῶναι ὑπὸ Κύρου, Κῦρον δὲ αὐτὸν ὑπ’ ἐκεινησὶ τῆς Μασσαγέτιδος ἀποθανεῖν. ὁρᾷς τὴν Σκυθίδα, τὴν ἐπὶ τοῦ ἵππου τούτου τοῦ λευκοῦ ἐξελαύνουσαν;", "st": "23.13"}, {"sp": "N", "t": "<em>Χάρων.<\/em> νὴ Δία.", "st": "23.13"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> Τόμυρις ἐκείνη ἐστί, καὶ τὴν κεφαλήν γε ἀποτεμοῦσα τοῦ Κύρου αὕτη ἐς ἀσκὸν ἐμβαλεῖ πλήρη αἵματος. ὁρᾷς δὲ καὶ τὸν υἱὸν αὐτοῦ τὸν νεανίσκον; Καμβύσης ἐκεῖνός ἐστιν· οὗτος βασιλεύσει μετὰ τὸν πατέρα καὶ μυρία σφαλεὶς ἔν τε Λιβύῃ καὶ Αἰθιοπίᾳ τὸ τελευταῖον μανεὶς ἀποθανεῖται ἀποκτείνας τὸν Ἆπιν.", "st": "23.13"}, {"sp": "N", "t": "<em>Χάρων.<\/em> ὢ πολλοῦ γέλωτος. ἀλλὰ νῦν τίς ἂν αὐτοὺς προσβλέψειεν οὕτως ὑπερφρονοῦντας τῶν ἄλλων; ἢ τίς ἂν πιστεύσειεν ὡς μετ’ ὀλίγον οὗτος μὲν αἰχμάλωτος ἔσται, οὗτος δὲ τὴν κεφαλὴν ἕξει ἐν ἀσκῷ αἵματος;", "st": "23.13"}, {"sp": "N", "t": "ἐκεῖνος δὲ τίς ἐστιν, ὦ Ἑρμῆ, ὁ τὴν πορφυρᾶν ἐφεστρίδα ἐμπεπορπημένος, ὁ τὸ διάδημα, ᾧ τὸν δακτύλιον ὁ μάγειρος ἀναδίδωσι τὸν ἰχθὺν ἀνατεμών,<br>νήσῳ ἐν ἀμφιρύτῃ; βασιλεὺς δέ τις εὔχεται εἶναι.", "st": "23.14"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> εὖ γε παρῳδεῖς, ὦ Χάρων. ἀλλὰ Πολυκράτην ὁρᾷς τὸν Σαμίων τύραννον πανευδαίμονα ἡγούμενον εἶναι· ἀτὰρ καὶ οὗτος αὐτὸς ὑπὸ τοῦ παρεστῶτος οἰκέτου Μαιανδρίου προδοθεὶς Ὀροίτῃ τῷ σατράπῃ ἀνασκολοπισθήσεται ἅθλιος ἐκπεσὼν τῆς εὐδαιμονίας ἐν ἀκαρεῖ τοῦ χρόνου· καὶ ταῦτα γὰρ τῆς Κλωθοῦς ἐπήκουσα.", "st": "23.14"}, {"sp": "N", "t": "<em>Χάρων.<\/em> ἄγαμαι Κλωθοῦς γεννικῆς· καῖε αὐτούς, ὦ βελτίστη, καὶ τὰς κεφαλὰς ἀπότεμνε καὶ ἀνασκολόπιζε, ὡς εἰδῶσιν ἄνθρωποι ὄντες· ἐν τοσούτῳ δὲ ἐπαιρέσθων ὡς ἂν ἀφ’ ὑψηλοτέρου ἀλγεινότερον καταπεσούμενοι. ἐγὼ δὲ γελάσομαι τότε γνωρίσας αὐτῶν ἕκαστον γυμνὸν ἐν τῷ σκαφιδίῳ μήτε τὴν πορφυρίδα μήτε τιάραν ἢ κλίνην χρυσῆν κομίζοντας.", "st": "23.14"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> καὶ τὰ μὲν τούτων ὧδε ἕξει. τὴν δὲ πληθὺν ὁρᾷς, ὦ Χάρων, τοὺς πλέοντας αὐτῶν, τοὺς πολεμοῦντας, τοὺς δικαζομένους, τοὺς γεωργοῦντας, τοὺς δανείζοντας, τοὺς προσαιτοῦντας;", "st": "23.15"}, {"sp": "N", "t": "<em>Χάρων.<\/em> ὁρῶ ποικίλην τινὰ τὴν διατριβὴν καὶ μεστὸν ταραχῆς τὸν βίον καὶ τὰς πόλεις γε αὐτῶν ἐοικυίας τοῖς σμήνεσιν, ἐν οἷς ἅπας μὲν ἴδιόν τι κέντρον ἔχει καὶ τὸν πλησίον κεντεῖ, ὀλίγοι δέ τινες ὥσπερ σφῆκες ἄγουσι καὶ φέρουσι τὸ ὑποδεέστερον. ὁ δὲ περιπετόμενος αὐτοὺς ἐκ τἀφανοῦς οὗτος ὄχλος τίνες εἰσίν;", "st": "23.15"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> ἐλπίδες, ὦ Χάρων, καὶ δείματα καὶ ἄγνοιαι καὶ ἡδοναὶ καὶ φιλαργυρίαι καὶ ὀργαὶ καὶ μίση καὶ τὰ τοιαῦτα. τούτων δὲ ἡ ἄγνοια μὲν κάτω συναναμέμικται αὐτοῖς καὶ συμπολιτεύεται, καὶ νὴ Δία καὶ τὸ μῖσος καὶ ὀργὴ καὶ ζηλοτυπία καὶ ἀμαθία καὶ ἀπορία καὶ φιλαργυρία, ὁ φόβος δὲ καὶ αἱ ἐλπίδες ὑπεράνω πετόμενοι ὁ μὲν ἐμπίπτων ἐκπλήττει ἐνίοτε καὶ ὑποπτήσσειν ποιεῖ, αἱ δ’ ἐλπίδες ὑπὲρ κεφαλῆς αἰωρούμεναι, ὁπόταν μάλιστα οἴηταί τις ἐπιλήψεσθαι αὐτῶν, ἀναπτάμεναι οἴχονται κεχηνότας αὐτοὺς ἀπολιποῦσαι, ὅπερ καὶ τὸν Τάνταλον κάτω πάσχοντα ὁρᾷς ὑπὸ τοῦ ὕδατος.", "st": "23.15"}, {"sp": "N", "t": "ἢν δὲ ἀτενίσῃς, κατόψει καὶ τὰς Μοίρας ἄνω ἐπικλωθούσας ἑκάστῳ τὸν ἄτρακτον, ἀφ’ οὗ ἠρτῆσθαι συμβέβηκεν ἅπαντας ἐκ λεπτῶν νημάτων. ὁρᾷς καθάπερ ἀράχνιά τινα καταβαίνοντα ἐφ’ ἕκαστον ἀπὸ τῶν ἀτράκτων;", "st": "23.16"}, {"sp": "N", "t": "<em>Χάρων.<\/em> ὁρῶ πάνυ λεπτὸν ἑκάστῳ νῆμα, ἐπιπεπλεγμένον γε τὰ πολλά, τοῦτο μὲν ἐκείνῳ, ἐκεῖνο δὲ ἄλλῳ.", "st": "23.16"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> εἰκότως, ὦ πορθμεῦ· εἵμαρται γὰρ ἐκείνῳ μὲν ὑπὸ τούτου φονευθῆναι, τούτῳ δὲ ὑπ’ ἄλλου, καὶ κληρονομῆσαί γε τοῦτον μὲν ἐκείνου, ὅτου ἂν ᾖ μικρότερον τὸ νῆμα, ἐκεῖνον δὲ αὖ τούτου· τοιόνδε γάρ τι ἡ ἐπιπλοκὴ δηλοῖ. ὁρᾷς δ’ οὖν ἀπὸ λεπτοῦ κρεμαμένους ἅπαντας· καὶ οὗτος μὲν ἀνασπασθεὶς ἄνω μετέωρός ἐστι καὶ μετὰ μικρὸν καταπεσών, ἀπορραγέντος τοῦ λίνου ἐπειδὰν μηκέτι ἀντέχῃ πρὸς τὸ βάρος, μέγαν τὸν ψόφον ἐργάσεται, οὗτος δὲ ὀλίγον ἀπὸ γῆς αἰωρούμενος, ἢν καὶ πέσῃ, ἀψοφητὶ κείσεται, μόλις καὶ τοῖς γείτοσιν ἐξακουσθέντος τοῦ πτώματος.", "st": "23.16"}, {"sp": "N", "t": "<em>Χάρων.<\/em> παγγέλοια ταῦτα, ὦ Ἑρμῆ.", "st": "23.16"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> καὶ μὴν οὐδ’ εἰπεῖν ἔχοις ἂν κατὰ τὴν ἀξίαν ὅπως ἐστὶ καταγέλαστα, ὦ Χάρων, καὶ μάλιστα αἱ ἄγαν σπουδαὶ αὐτῶν καὶ τὸ μεταξὺ τῶν ἐλπίδων οἴχεσθαι ἀναρπάστους γινομένους ὑπὸ τοῦ βελτίστου Θανάτου. ἄγγελοι δὲ καὶ ὑπηρέται αὐτοῦ μάλα πολλοί, ὡς ὁρᾷς, ἠπίαλοι καὶ πυρετοὶ καὶ φθόαι καὶ περιπλευμονίαι καὶ ξίφη καὶ λῃστήρια καὶ κώνεια καὶ δικασταὶ καὶ τύραννοι· καὶ τούτων οὐδὲν ὅλως αὐτοὺς εἰσέρχεται, ἔστ’ ἂν εὖ πράττωσιν, ὅταν δὲ σφαλῶσι, πολὺ τὸ ὀττοτοῖ καὶ αἰαῖ καὶ οἴμοι. εἰ δὲ εὐθὺς ἐξ ἀρχῆς ἐνενόουν ὅτι θνητοί τέ εἰσιν αὐτοὶ καὶ ὀλίγον τοῦτον χρόνον ἐπιδημήσαντες τῷ βίῳ ἀπίασιν ὥσπερ ἐξ ὀνείρατος πάντα ὑπὲρ γῆς ἀφέντες, ἔζων τε ἂν σωφρονέστερον καὶ ἧττον ἠνιῶντο ἀποθανόντες· νῦν δὲ εἰς ἀεὶ ἐλπίσαντες χρήσεσθαι τοῖς παροῦσιν, ἐπειδὰν ἐπιστὰς ὁ ὑπηρέτης καλῇ καὶ ἀπάγῃ πεδήσας τῷ πυρετῷ ἢ τῇ φθόῃ, ἀγανακτοῦσι πρὸς τὴν ἀγωγὴν οὔποτε προσδοκήσαντες ἀποσπασθήσεσθαι αὐτῶν. ἢ τί γὰρ οὐκ ἂν ποιήσειεν ἐκεῖνος ὁ τὴν οἰκίαν σπουδῇ οἰκοδομούμενος καὶ τοὺς ἐργάτας ἐπισπέρχων, εἰ μάθοι ὅτι ἡ μὲν ἕξει τέλος αὐτῷ, ὁ δὲ ἄρτι ἐπιθεὶς τὸν ὄροφον ἄπεισι τῷ κληρονόμῳ καταλιπὼν ἀπολαύειν αὐτῆς, αὐτὸς μηδὲ δειπνήσας ἅθλιος ἐν αὐτῇ; ἐκεῖνος μὲν γὰρ ὁ χαίρων ὅτι ἄρρενα παῖδα τέτοκεν αὐτῷ ἡ γυνή, καὶ τοὺς φίλους διὰ τοῦτο ἑστιῶν καὶ τοὔνομα τοῦ πατρὸς τιθέμενος, εἰ ἠπίστατο ὡς ἑπτέτης γενόμενος ὁ παῖς τεθνήξεται, ἆρα ἄν σοι δοκεῖ χαίρειν ἐπ’ αὐτῷ γεννωμένῳ; ἀλλὰ τὸ αἴτιον, ὅτι τὸν μὲν εὐτυχοῦντα ἐπὶ τῷ παιδὶ ἐκεῖνον ὁρᾷ τὸν τοῦ ἀθλητοῦ πατέρα τοῦ Ὀλύμπια νενικηκότος, τὸν γείτονα δὲ τὸν ἐκκομίζοντα τὸ παιδίον οὐχ ὁρᾷ οὐδὲ οἶδεν ἀφ’ οἵας αὐτῷ κρόκης ἐκρέματο. τοὺς μὲν γὰρ περὶ τῶν ὅρων διαφερομένους ὁρᾷς, ὅσοι εἰσί, καὶ τοὺς συναγείροντας τὰ χρήματα, εἶτα, πρὶν ἀπολαῦσαι αὐτῶν, καλουμένους ὑφ’ ὧν εἶπον τῶν ἀγγέλων τε καὶ ὑπηρετῶν.", "st": "23.17"}, {"sp": "N", "t": "<em>Χάρων.<\/em> ὁρῶ ταῦτα πάντα καὶ πρὸς ἐμαυτόν γε ἐννοῶ ὅ τι τὸ ἡδὺ αὐτοῖς παρὰ τὸν βίον ἢ τί ἐκεῖνό ἐστιν, οὗ στερούμενοι ἀγανακτοῦσιν. ἢν γοῦν τοὺς βασιλέας αὐτῶν ἴδῃ τις, οἵπερ εὐδαιμονέστατοι εἶναι δοκοῦσιν, ἔξω τοῦ ἀβεβαίου ὡς φὴς καὶ ἀμφιβόλου τῆς τύχης, πλείω τῶν ἡδέων τὰ ἀνιαρὰ εὑρήσει προσόντα αὐτοῖς, φόβους καὶ ταραχὰς καὶ μίση καὶ ἐπιβουλὰς καὶ ὀργὰς καὶ κολακείας· τούτοις γὰρ ἅπαντες σύνεισιν. ἐῶ πένθη καὶ νόσους καὶ πάθη ἐξ ἰσοτιμίας δηλαδὴ ἄρχοντα αὐτῶν· ὅπου δὲ τὰ τούτων πονηρά, λογίζεσθαι καιρὸς οἷα τὰ τῶν ἰδιωτῶν ἂν εἴη.", "st": "23.18"}, {"sp": "N", "t": "ἐθέλω δ’ οὖν σοι, ὦ Ἑρμῆ, εἰπεῖν, ᾧτινι ἐοικέναι μοι ἔδοξαν οἱ ἄνθρωποι καὶ ὁ βίος ἅπας αὐτῶν. ἤδη ποτὲ πομφόλυγας ἐν ὕδατι ἐθεάσω ὑπὸ κρουνῷ τινι καταράττοντι ἀνισταμένας; τὰς φυσαλλίδας λέγω, ἀφ’ ὧν συναγείρεται ὁ ἀφρός· ἐκείνων τοίνυν τινὲς μὲν μικραί εἰσι καὶ αὐτίκα ἐκραγεῖσαι ἀπέσβησαν, αἱ δ’ ἐπὶ πλέον διαρκοῦσι· καὶ προσχωρουσῶν αὐταῖς τῶν ἄλλων αὗται ὑπερφυσώμεναι ἐς μέγιστον ὄγκον αἴρονται, ἔπειτα μέντοι κἀκεῖναι πάντως ἐξερράγησάν ποτε· οὐ γὰρ οἷόν τε ἄλλως γενέσθαι. τοῦτό ἐστιν ὁ ἀνθρώπου βίος· ἅπαντες ὑπὸ πνεύματος ἐμπεφυσημένοι οἱ μὲν μείζους, οἱ δὲ ἐλάττους· καὶ οἱ μὲν ὀλιγοχρόνιον ἔχουσι καὶ ὠκύμορον τὸ φύσημα, οἱ δὲ ἅμα τῷ συστῆναι ἐπαύσαντο· πᾶσι δ’ οὖν ἀπορραγῆναι ἀναγκαῖον.", "st": "23.19"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> οὐδὲν χεῖρον σὺ τοῦ Ὁμήρου εἴκασας, ὦ Χάρων, ὃς φύλλοις τὸ γένος αὐτῶν ὁμοιοῖ.", "st": "23.19"}, {"sp": "N", "t": "<em>Χάρων.<\/em> καὶ τοιοῦτοι ὄντες, ὦ Ἑρμῆ, ὁρᾷς οἷα ποιοῦσι καὶ ὡς φιλοτιμοῦνται πρὸς ἀλλήλους ἀρχῶν πέρι καὶ τιμῶν καὶ κτήσεων ἁμιλλώμενοι, ἅπερ ἅπαντα καταλιπόντας αὐτοὺς δεήσει ἕνα ὀβολὸν ἔχοντας ἥκειν παρ’ ἡμᾶς. βούλει οὖν, ἐπείπερ ἐφ’ ὑψηλοῦ ἐσμέν, ἀναβοήσας παμμέγεθες παραινέσω αὐτοῖς ἀπέχεσθαι μὲν τῶν ματαίων πόνων, ζῆν δὲ ἀεὶ τὸν θάνατον πρὸ ὀφθαλμῶν ἔχοντας, λέγων, “ὦ μάταιοι, τί ἐσπουδάκατε περὶ ταῦτα; παύσασθε κάμνοντες· οὐ γὰρ εἰς ἀεὶ βιώσεσθε· οὐδὲν τῶν ἐνταῦθα σεμνῶν ἀΐδιόν ἐστιν, οὐδ’ ἂν ἀπαγάγοι τις αὐτῶν τι σὺν αὑτῷ ἀποθανών, ἀλλ’ ἀνάγκη τὸν μὲν γυμνὸν οἴχεσθαι, τὴν οἰκίαν δὲ καὶ τὸν ἀγρὸν καὶ τὸ χρυσίον ἀεὶ ἄλλων εἶναι καὶ μεταβάλλειν τοὺς δεσπότας.” εἰ ταῦτα καὶ τὰ τοιαῦτα ἐξ ἐπηκόου ἐμβοήσαιμι αὐτοῖς, οὐκ ἂν οἴει μεγάλα ὠφεληθῆναι τὸν βίον καὶ σωφρονεστέρους ἂν γενέσθαι παρὰ πολύ;", "st": "23.20"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> ὦ μακάριε, οὐκ οἶσθα ὅπως αὐτοὺς ἡ ἄγνοια καὶ ἡ ἀπάτη διατεθείκασιν, ὡς μηδ’ ἂν τρυπάνῳ ἔτι διανοιχθῆναι αὐτοῖς τὰ ὦτα, τοσούτῳ κηρῷ ἔβυσαν αὐτά, οἷόν περ ὁ Ὀδυσσεὺς τοὺς ἑταίρους ἔδρασε δέει τῆς Σειρήνων ἀκροάσεως. πόθεν οὖν ἂν ἐκεῖνοι δυνηθεῖεν ἀκοῦσαι, ἢν καὶ σὺ κεκραγὼς διαρραγῇς; ὅπερ γὰρ παρ’ ὑμῖν ἡ Λήθη δύναται, τοῦτο ἐνταῦθα ἡ ἄγνοια ἐργάζεται. πλὴν ἀλλὰ εἰσὶν αὐτῶν ὀλίγοι οὐ παραδεδεγμένοι τὸν κηρὸν ἐς τὰ ὦτα, πρὸς τὴν ἀλήθειαν ἀποκλίνοντες, ὀξὺ δεδορκότες ἐς τὰ πράγματα καὶ κατεγνωκότες οἷά ἐστιν.", "st": "23.21"}, {"sp": "N", "t": "<em>Χάρων.<\/em> οὐκοῦν ἐκείνοις γοῦν ἐμβοήσωμεν.", "st": "23.21"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> περιττὸν καὶ τοῦτο, λέγειν πρὸς αὐτοὺς ἃ ἴσασιν. ὁρᾷς ὅπως ἀποσπάσαντες τῶν πολλῶν καταγελῶσι τῶν γιγνομένων καὶ οὐδαμῆ οὐδαμῶς ἀρέσκονται αὐτοῖς, ἀλλὰ δῆλοί εἰσι δρασμὸν ἤδη βουλεύοντες παρ’ ὑμᾶς ἀπὸ τοῦ βίου. καὶ γὰρ καὶ μισοῦνται ἐλέγχοντες αὐτῶν τὰς ἀμαθίας.", "st": "23.21"}, {"sp": "N", "t": "<em>Χάρων.<\/em> εὖ γε, ὦ γεννάδαι· πλὴν πάνυ ὀλίγοι εἰσίν, ὦ Ἑρμῆ.", "st": "23.21"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> ἱκανοὶ καὶ οὗτοι. ἀλλὰ κατίωμεν ἤδη.", "st": "23.21"}, {"sp": "N", "t": "<em>Χάρων.<\/em> Ἓν ἔτι ἐπόθουν, ὦ Ἑρμῆ, εἰδέναι, καί μοι δείξας αὐτὸ ἐντελῆ ἔσῃ τὴν περιήγησιν πεποιημένος, τὰς ἀποθήκας τῶν σωμάτων, ἵνα κατορύττουσι, θεάσασθαι.", "st": "23.22"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> ἠρία, ὦ Χάρων, καὶ τύμβους καὶ τάφους καλοῦσι τὰ τοιαῦτα. πλὴν τὰ πρὸ τῶν πόλεων ἐκεῖνα τὰ χώματα ὁρᾷς καὶ τὰς στήλας καὶ πυραμίδας; ἐκεῖνα πάντα νεκροδοχεῖα καὶ σωματοφυλάκιά ἐστιν.", "st": "23.22"}, {"sp": "N", "t": "<em>Χάρων.<\/em> τί οὖν ἐκεῖνοι στεφανοῦσι τοὺς λίθους καὶ χρίουσι μύρῳ; οἱ δὲ καὶ πυρὰν νήσαντες πρὸ τῶν χωμάτων καὶ βόθρον τινὰ ὀρύξαντες καίουσί τε ταυτὶ τὰ πολυτελῆ δεῖπνα καὶ εἰς τὰ ὀρύγματα οἶνον καὶ μελίκρατον, ὡς γοῦν εἰκάσαι, ἐγχέουσιν;", "st": "23.22"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> οὐκ οἶδα, ὦ πορθμεῦ, τί ταῦτα πρὸς τοὺς ἐν Ἅιδου· πεπιστεύκασι δ’ οὖν τὰς ψυχὰς ἀναπεμπομένας κάτωθεν δειπνεῖν μὲν ὡς οἷόν τε περιπετομένας τὴν κνῖσαν καὶ τὸν καπνόν, πίνειν δὲ ἀπὸ τοῦ βόθρου τὸ μελίκρατον.", "st": "23.22"}, {"sp": "N", "t": "<em>Χάρων.<\/em> ἐκείνους ἔτι πίνειν ἢ ἐσθίειν, ὧν τὰ κρανία ξηρότατα; καίτοι γελοῖός εἰμι σοὶ λέγων ταῦτα ὁσημέραι κατάγοντι αὐτούς. οἶσθα οὖν εἰ δύναιντ’ ἂν ἔτι ἀνελθεῖν ἅπαξ ὑποχθόνιοι γενόμενοι. ἐπεί τοι καὶ παγγέλοια ἄν, ὦ Ἑρμῆ, ἔπασχον, οὐκ ὀλίγα πράγματα ἔχων, εἰ ἔδει μὴ κατάγειν μόνον αὐτούς, ἀλλὰ καὶ αὖθις ἀνάγειν πιομένους. ὦ μάταιοι, τῆς ἀνοίας, οὐκ εἰδότες ἡλίκοις ὅροις διακέκριται τὰ νεκρῶν καὶ τὰ ζώντων πράγματα καὶ οἷα τὰ παρ’ ἡμῖν ἐστι καὶ ὅτι<br>κάτθαν’ ὁμῶς ὅ τ’ ἄτυμβος ἀνὴρ ὅς τ’ ἔλλαχε τύμβου,<br>ἐν δὲ ἰῇ τιμῇ Ἶρος κρείων τ’ Ἀγαμέμνων·<br>Θερσίτῃ δ’ ἶσος Θέτιδος παῖς ἠϋκόμοιο<br>πάντες δ’ εἰσὶν ὁμῶς νεκύων ἀμενηνὰ κάρηνα,<br>γυμνοί τε ξηροί τε κατ’ ἀσφοδελὸν λειμῶνα.", "st": "23.22"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> Ἡράκλεις, ὡς πολὺν τὸν Ὅμηρον ἐπαντλεῖς. ἀλλ’ ἐπείπερ ἀνέμνησας, ἐθέλω σοι δεῖξαι τὸν τοῦ Ἀχιλλέως τάφον. ὁρᾷς τὸν ἐπὶ τῇ θαλάττῃ; Σίγειον μὲν ἐκεῖθέν ἐστι τὸ Τρωϊκόν· ἀντικρὺ δὲ ὁ Αἴας τέθαπται ἐν τῷ Ῥοιτείῳ.", "st": "23.23"}, {"sp": "N", "t": "<em>Χάρων.<\/em> οὐ μεγάλοι, ὦ Ἑρμῆ, οἱ τάφοι. τὰς πόλεις δὲ τὰς ἐπισήμους δεῖξόν μοι ἤδη, ἃς κάτω ἀκούομεν, τὴν Νίνον τὴν Σαρδαναπάλλου καὶ Βαβυλῶνα καὶ Μυκήνας καὶ Κλεωνὰς καὶ τὴν Ἴλιον αὐτήν· πολλοὺς γοῦν μέμνημαι διαπορθμεύσας ἐκεῖθεν, ὡς δέκα ὅλων ἐτῶν μὴ νεωλκῆσαι μηδὲ διαψῦξαι τὸ σκαφίδιον.", "st": "23.23"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> ἡ Νίνος μέν, ὦ πορθμεῦ, ἀπόλωλεν ἤδη καὶ οὐδὲ ἴχνος ἔτι λοιπὸν αὐτῆς, οὐδ’ ἂν εἴποις ὅπου ποτὲ ἦν· ἡ Βαβυλὼν δέ σοι ἐκείνη ἐστὶν ἡ εὔπυργος, ἡ τὸν μέγαν περίβολον, οὐ μετὰ πολὺ καὶ αὐτὴ ζητηθησομένη ὥσπερ ἡ Νίνος· Μυκήνας δὲ καὶ Κλεωνὰς αἰσχύνομαι δεῖξαί σοι, καὶ μάλιστα τὸ Ἴλιον. ἀποπνίξεις γὰρ εὖ οἶδ’ ὅτι τὸν Ὅμηρον κατελθὼν ἐπὶ τῇ μεγαληγορίᾳ τῶν ἐπῶν. πλὴν ἀλλὰ πάλαι μὲν ἦσαν εὐδαίμονες, νῦν δὲ τεθνᾶσι καὶ αὗται· ἀποθνήσκουσι γάρ, ὦ πορθμεῦ, καὶ πόλεις ὥσπερ ἄνθρωποι, καὶ τὸ παραδοξότατον, καὶ ποταμοὶ ὅλοι· Ἰνάχου γοῦν οὐδὲ τάφος ἔτι ἐν Ἄργει καταλείπεται.", "st": "23.23"}, {"sp": "N", "t": "<em>Χάρων.<\/em> παπαὶ τῶν ἐπαίνων, Ὅμηρε, καὶ τῶν ὀνομάτων, Ἴλιος ἱρὴ καὶ εὐρυάγυια καὶ ἐϋκτίμεναι Κλεωναί.", "st": "23.23"}, {"sp": "N", "t": "ἀλλὰ μεταξὺ λόγων, τίνες ἐκεῖνοί εἰσιν οἱ πολεμοῦντες ἢ ὑπὲρ τίνος ἀλλήλους φονεύουσιν;", "st": "23.24"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> Ἀργείους ὁρᾷς, ὦ Χάρων, καὶ Λακεδαιμονίους καὶ τὸν ἡμιθνῆτα ἐκεῖνον στρατηγὸν Ὀθρυάδαν τὸν ἐπιγράφοντα τὸ τρόπαιον τῷ αὑτοῦ αἵματι.", "st": "23.24"}, {"sp": "N", "t": "<em>Χάρων.<\/em> ὑπὲρ τίνος δ’ αὐτοῖς, ὦ Ἑρμῆ, ὁ πόλεμος;", "st": "23.24"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> ὑπὲρ τοῦ πεδίου αὐτοῦ, ἐν ᾧ μάχονται.", "st": "23.24"}, {"sp": "N", "t": "<em>Χάρων.<\/em> ὢ τῆς ἀνοίας, οἵ γε οὐκ ἴσασιν ὅτι, κἂν ὅλην τὴν Πελοπόννησον ἕκαστος αὐτῶν κτήσωνται, μόγις ἂν ποδιαῖον λάβοιεν τόπον παρὰ τοῦ Αἰακοῦ· τὸ δὲ πεδίον τοῦτο ἄλλοτε ἄλλοι γεωργήσουσι πολλάκις ἐκ βάθρων τὸ τρόπαιον ἀνασπάσαντες τῷ ἀρότρῳ.", "st": "23.24"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> οὕτω μὲν ταῦτα ἔσται· ἡμεῖς δὲ καταβάντες ἤδη καὶ κατὰ χώραν εὐθετήσαντες αὖθις τὰ ὄρη ἀπαλλαττώμεθα, ἐγὼ μὲν καθ’ ἃ ἐστάλην, σὺ δὲ ἐπὶ τὸ πορθμεῖον· ἥξω δέ σοι καὶ αὐτὸς μετ’ ὀλίγον νεκροστολῶν.", "st": "23.24"}, {"sp": "N", "t": "<em>Χάρων.<\/em> εὖ γε ἐποίησας, ὦ Ἑρμῆ· εὐεργέτης εἰς ἀεὶ ἀναγεγράψῃ, ὠνάμην γάρ τι διὰ σὲ τῆς ἀποδημίας. — οἷά ἐστι τὰ τῶν κακοδαιμόνων ἀνθρώπων πράγματα — βασιλεῖς, πλίνθοι χρυσαῖ, ἐπιτύμβια, μάχαι· Χάρωνος δὲ οὐδεὶς λόγος.", "st": "23.24"}, {"sp": "HDR", "t": "Βίων Πρᾶσις"}, {"sp": "N", "t": "<em>Ζεύς.<\/em> σὺ μὲν διατίθει τὰ βάθρα καὶ παρασκεύαζε τὸν τόπον τοῖς ἀφικνουμένοις, σὺ δὲ στῆσον ἑξῆς παραγαγὼν τοὺς βίους, ἀλλὰ κοσμήσας πρότερον, ὡς εὐπρόσωποι φανοῦνται καὶ ὅτι πλείστους ἐπάξονται· σὺ δέ, ὦ Ἑρμῆ, κήρυττε καὶ συγκάλει.", "st": "24.1"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> ἀγαθῇ τύχῃ τοὺς ὠνητὰς ἤδη παρεῖναι πρὸς τὸ πωλητήριον. ἀποκηρύξομεν δὲ βίους φιλοσόφους παντὸς εἴδους καὶ προαιρέσεων ποικίλων. εἰ δέ τις τὸ παραυτίκα μὴ ἔχει τἀργύριον καταβαλέσθαι, εἰς νέωτα ἐκτίσει καταστήσας ἐγγυητήν.", "st": "24.1"}, {"sp": "N", "t": "<em>Ζεύς.<\/em> πολλοὶ συνίασιν· ὥστε χρὴ μὴ διατρίβειν μηδὲ κατέχειν αὐτούς. πωλῶμεν οὖν.", "st": "24.1"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> τίνα πρῶτον ἐθέλεις παραγάγωμεν;", "st": "24.2"}, {"sp": "N", "t": "<em>Ζεύς.<\/em> τουτονὶ τὸν κομήτην, τὸν Ἰωνικόν, ἐπεὶ καὶ σεμνός τις εἶναι φαίνεται.", "st": "24.2"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> οὗτος ὁ Πυθαγορικὸς κατάβηθι καὶ πάρεχε σεαυτὸν ἀναθεωρεῖσθαι τοῖς συνειλεγμένοις.", "st": "24.2"}, {"sp": "N", "t": "<em>Ζεύς.<\/em> κήρυττε δή.", "st": "24.2"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> τὸν ἄριστον βίον πωλῶ, τὸν σεμνότατον. τίς ὠνήσεται; τίς ὑπὲρ ἄνθρωπον εἶναι βούλεται; τίς εἰδέναι τὴν τοῦ παντὸς ἁρμονίαν καὶ ἀναβιῶναι πάλιν;", "st": "24.2"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> τὸ μὲν εἶδος οὐκ ἀγεννής. τί δὲ μάλιστα οἶδεν;", "st": "24.2"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> ἀριθμητικήν, ἀστρονομίαν, τερατείαν, γεωμετρίαν, μουσικήν, γοητείαν. μάντιν ἄκρον βλέπεις.", "st": "24.2"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> ἔξεστιν αὐτὸν ἀνακρίνειν;", "st": "24.2"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> ἀνάκρινε ἀγαθῇ τύχῃ.", "st": "24.2"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> ποδαπὸς εἶ σύ;", "st": "24.3"}, {"sp": "N", "t": "<em>Πυθαγόρας.<\/em> Σάμιος.", "st": "24.3"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> ποῦ δὲ ἐπαιδεύθης;", "st": "24.3"}, {"sp": "N", "t": "<em>Πυθαγόρας.<\/em> ἐν Αἰγύπτῳ παρὰ τοῖς ἐκεῖ σοφοῖσι.", "st": "24.3"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> φέρε δέ, ἢν πρίωμαί σε, τί με διδάξει;", "st": "24.3"}, {"sp": "N", "t": "<em>Πυθαγόρας.<\/em> διδάξομαι μὲν οὐδέν, ἀναμνήσω δέ.", "st": "24.3"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> πῶς ἀναμνήσεις;", "st": "24.3"}, {"sp": "N", "t": "<em>Πυθαγόρας.<\/em> καθαρὴν πρότερον τὴν ψυχὴν ἐργασάμενος καὶ τὸν ἐπ’ αὐτῇ ῥύπον ἐκκλύσας.", "st": "24.3"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> καὶ δὴ νόμισον ἤδη ἐκκεκαθάρθαι με, τις ὁ τρόπος τῆς ἀναμνήσεως;", "st": "24.3"}, {"sp": "N", "t": "<em>Πυθαγόρας.<\/em> τὸ μὲν πρῶτον ἡσυχίη μακρὴ καὶ ἀφωνίη καὶ πέντε ὅλων ἐτέων λαλέειν μηδέν.", "st": "24.3"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> ὥρα σοι, ὦ βέλτιστε, τὸν Κροίσου παῖδα παιδεύειν· ἐγὼ γὰρ λάλος, οὐκ ἀνδριὰς εἶναι βούλομαι. τί δὲ μετὰ τὴν σιωπὴν ὅμως καὶ τὴν πενταετίαν;", "st": "24.3"}, {"sp": "N", "t": "<em>Πυθαγόρας.<\/em> Μουσουργίῃ καὶ γεωμετρίῃ ἐνασκήσεαι.", "st": "24.3"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> χάριεν λέγεις, εἰ πρῶτόν με κιθαρῳδὸν γενόμενον κᾆτα εἶναι σοφὸν χρή.", "st": "24.3"}, {"sp": "N", "t": "<em>Πυθαγόρας.<\/em> εἶτ’ ἐπὶ τουτέοισιν ἀριθμέειν.", "st": "24.4"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> οἶδα καὶ νῦν ἀριθμεῖν.", "st": "24.4"}, {"sp": "N", "t": "<em>Πυθαγόρας.<\/em> πῶς ἀριθμέεις;", "st": "24.4"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> ἕν, δύο, τρία, τέτταρα.", "st": "24.4"}, {"sp": "N", "t": "<em>Πυθαγόρας.<\/em> ὁρᾷς; ἃ σὺ δοκέεις τέσσαρα, ταῦτα δέκα ἐστὶ καὶ τρίγωνον ἐντελὲς καὶ ἡμέτερον ὅρκιον.", "st": "24.4"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> οὐ μὰ τὸν μέγιστον τοίνυν ὅρκον τὰ τέτταρα, οὔποτε θειοτέρους λόγους ἤκουσα οὐδὲ μᾶλλον ἱερούς.", "st": "24.4"}, {"sp": "N", "t": "<em>Πυθαγόρας.<\/em> μετὰ δέ, ὦ ξεῖνε, εἴσεαι γῆς τε πέρι καὶ ἠέρος καὶ ὕδατος καὶ πυρὸς ἥτις αὐτέοισιν ἡ φορὴ καὶ ὁκοῖα ἐόντα μορφὴν ὅκως κινέονται.", "st": "24.4"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> μορφὴν γὰρ ἔχει τὸ πῦρ ἢ ἀὴρ ἢ ὕδωρ;", "st": "24.4"}, {"sp": "N", "t": "<em>Πυθαγόρας.<\/em> καὶ μάλα ἐμφανέα· οὐ γὰρ οἷά τε ἀμορφίῃ καὶ ἀσχημοσύνῃ κινέεσθαι. καὶ ἐπὶ τουτέοισι δὲ γνώσεαι τὸν θεὸν ἀριθμὸν ἐόντα καὶ νόον καὶ ἁρμονίην.", "st": "24.4"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> θαυμάσια λέγεις.", "st": "24.4"}, {"sp": "N", "t": "<em>Πυθαγόρας.<\/em> πρὸς δὲ τοῖσδεσι τοῖσιν εἰρημένοισι καὶ σεωυτὸν ἕνα δοκέοντα ἄλλον ὁρεόμενον καὶ ἄλλον ἐόντα εἴσεαι.", "st": "24.5"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> τί φής; ἄλλος εἰμὶ καὶ οὐχ οὗτος ὅσπερ νῦν πρὸς σὲ διαλέγομαι;", "st": "24.5"}, {"sp": "N", "t": "<em>Πυθαγόρας.<\/em> νῦν μὲν οὗτος, πάλαι δὲ ἐν ἄλλῳ σώματι καὶ ἐν ἄλλῳ οὐνόματι ἐφαντάζεο· χρόνῳ δὲ αὖτις ἐς ἄλλον μεταβήσεαι.", "st": "24.5"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> τοῦτο φής, ἀθάνατον ἔσεσθαί με ἀλλαττόμενον ἐς μορφὰς πλείονας;", "st": "24.5"}, {"sp": "N", "t": "ἀλλὰ τάδε μὲν ἱκανῶς. τὰ δ’ ἀμφὶ δίαιταν ὁποῖός τις εἶ;", "st": "24.6"}, {"sp": "N", "t": "<em>Πυθαγόρας.<\/em> ἐμψυχήϊον μὲν οὐδὲ ἓν σιτέομαι, τὰ δὲ ἄλλα πλὴν κυάμων.", "st": "24.6"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> τίνος ἕνεκα; ἢ μυσάττῃ τοὺς κυάμους;", "st": "24.6"}, {"sp": "N", "t": "<em>Πυθαγόρας.<\/em> οὔκ, ἀλλὰ ἱροί εἰσι καὶ θωυμαστὴ αὐτέων ἡ φύσις· πρῶτον μὲν γὰρ τὸ πᾶν γονή εἰσι, καὶ ἢν ἀποδύσῃς κύαμον ἔτι χλωρὸν ἐόντα, ὄψεαι τοῖσιν ἀνδρείοισι μορίοισιν ἐμφερέα τὴν φυήν· ἑψηθέντα δὲ ἢν ἀφῇς ἐς τὴν σεληναίην νυξὶ μεμετρημένῃσιν, αἷμα ποιήσεις. τὸ δὲ μέζον, Ἀθηναίοισι νόμος κυάμοισι τὰς ἀρχὰς αἱρέεσθαι.", "st": "24.6"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> καλῶς πάντα ἔφης καὶ ἱεροπρεπῶς. ἀλλὰ ἀπόδυθι, καὶ γυμνὸν γάρ σε ἰδεῖν βούλομαι. ὦ Ἡράκλεις, χρυσοῦς αὐτῷ ὁ μηρός ἐστι. θεός, οὐ βροτός τις εἶναι φαίνεται· ὥστε ὠνήσομαι πάντως αὐτόν. πόσου τοῦτον ἀποκηρύττεις;", "st": "24.6"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> δέκα μνῶν.", "st": "24.6"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> ἔχω τοσούτου λαβών.", "st": "24.6"}, {"sp": "N", "t": "<em>Ζεύς.<\/em> γράφε τοῦ ὠνησαμένου τοὔνομα καὶ ὅθεν ἐστίν.", "st": "24.6"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> Ἰταλιώτης, ὦ Ζεῦ, δοκεῖ τις εἶναι τῶν ἀμφὶ Κρότωνα καὶ Τάραντα καὶ τὴν ταύτῃ Ἑλλάδα· καίτοι οὐχ εἷς, ἀλλὰ τριακόσιοι σχεδὸν ἐώνηνται κατὰ κοινὸν αὐτόν.", "st": "24.6"}, {"sp": "N", "t": "<em>Ζεύς.<\/em> Ἀπαγέτωσαν· ἄλλον παράγωμεν.", "st": "24.6"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> βούλει τὸν αὐχμῶντα ἐκεῖνον, τὸν Ποντικόν;", "st": "24.7"}, {"sp": "N", "t": "<em>Ζεύς.<\/em> πάνυ μὲν οὖν.", "st": "24.7"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> οὗτος ὁ τὴν πήραν ἐξηρτημένος, ὁ ἐξωμίας, ἐλθὲ καὶ περίιθι ἐν κύκλῳ τὸ συνέδριον. βίον ἀνδρικὸν πωλῶ, βίον ἄριστον καὶ γεννικόν, βίον ἐλεύθερον· τίς ὠνήσεται;", "st": "24.7"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> ὁ κῆρυξ πῶς ἔφης σύ; πωλεῖς τὸν ἐλεύθερον;", "st": "24.7"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> ἔγωγε.", "st": "24.7"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> εἶτ’ οὐ δέδιας μή σοι δικάσηται ἀνδραποδισμοῦ ἢ καὶ προκαλέσηταί σε εἰς Ἄρειον πάγον;", "st": "24.7"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> οὐδὲν αὐτῷ μέλει τῆς πράσεως· οἴεται γὰρ εἶναι παντάπασιν ἐλεύθερος.", "st": "24.7"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> τί δ’ ἄν τις αὐτῷ χρήσαιτο ῥυπῶντι καὶ οὕτω κακοδαιμόνως διακειμένῳ; πλὴν εἰ μὴ σκαπανέα γε καὶ ὑδροφόρον αὐτὸν ἀποδεικτέον.", "st": "24.7"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> οὐ μόνον, ἀλλὰ καὶ ἢν θυρωρὸν αὐτὸν ἐπιστήσῃς, πολὺ πιστοτέρῳ χρήσῃ τῶν κυνῶν. ἀμέλει κύων αὐτῷ καὶ τὸ ὄνομα.", "st": "24.7"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> ποδαπὸς δέ ἐστιν ἢ τίνα τὴν ἄσκησιν ἐπαγγέλλεται;", "st": "24.7"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> αὐτὸν ἐροῦ· κάλλιον γὰρ οὕτω ποιεῖν.", "st": "24.7"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> δέδια τὸ σκυθρωπὸν αὐτοῦ καὶ κατηφές, μή με ὑλακτήσῃ προσελθόντα ἢ καὶ νὴ Δία δάκῃ γε. οὐχ ὁρᾷς ὡς διῆρται τὸ ξύλον καὶ συνέσπακε τὰς ὀφρῦς καὶ ἀπειλητικόν τι καὶ χολῶδες ὑποβλέπει;", "st": "24.7"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> μὴ δέδιθι· τιθασὸς γάρ ἐστι.", "st": "24.7"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> τὸ πρῶτον, ὦ βέλτιστε, ποδαπὸς εἶ;", "st": "24.8"}, {"sp": "N", "t": "<em>Διογένης.<\/em> παντοδαπός.", "st": "24.8"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> πῶς λέγεις;", "st": "24.8"}, {"sp": "N", "t": "<em>Διογένης.<\/em> τοῦ κόσμου πολίτην ὁρᾷς.", "st": "24.8"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> ζηλοῖς δὲ δὴ τίνα;", "st": "24.8"}, {"sp": "N", "t": "<em>Διογένης.<\/em> τὸν Ἡρακλέα.", "st": "24.8"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> τί οὖν οὐχὶ καὶ λεοντῆν ἀμπέχῃ; τὸ μὲν γὰρ ξύλον ἔοικας αὐτῷ.", "st": "24.8"}, {"sp": "N", "t": "<em>Διογένης.<\/em> τουτί μοι λεοντῆ, τὸ τριβώνιον. στρατεύομαι δὲ ὥσπερ ἐκεῖνος ἐπὶ τὰς ἡδονάς, οὐ κελευστός, ἀλλὰ ἑκούσιος, ἐκκαθᾶραι τὸν βίον προαιρούμενος.", "st": "24.8"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> εὖ γε τῆς προαιρέσεως. ἀλλὰ τί μάλιστα εἰδέναι σε φῶμεν; ἢ τίνα τὴν τέχνην ἔχεις;", "st": "24.8"}, {"sp": "N", "t": "<em>Διογένης.<\/em> ἐλευθερωτής εἰμι τῶν ἀνθρώπων καὶ ἰατρὸς τῶν παθῶν· τὸ δὲ ὅλον ἀληθείας καὶ παρρησίας προφήτης εἶναι βούλομαι.", "st": "24.8"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> εὖ γε, ὦ προφῆτα· ἢν δὲ πρίωμαί σε, τίνα με τὸν τρόπον διασκήσεις;", "st": "24.9"}, {"sp": "N", "t": "<em>Διογένης.<\/em> πρῶτον μὲν παραλαβών σε καὶ ἀποδύσας τὴν τρυφὴν καὶ ἀπορίᾳ συγκατακλείσας τριβώνιον περιβαλῶ, μετὰ δὲ πονεῖν καὶ κάμνειν καταναγκάσω χαμαὶ καθεύδοντα καὶ ὕδωρ πίνοντα καὶ ὧν ἔτυχεν ἐμπιμπλάμενον, τὰ δὲ χρήματα, ἢν ἔχῃς, ἐμοὶ πειθόμενος εἰς τὴν θάλατταν φέρων ἐμβαλεῖς, γάμου δὲ ἀμελήσεις καὶ παίδων καὶ πατρίδος, καὶ πάντα σοι ταῦτα λῆρος ἔσται, καὶ τὴν πατρῴαν οἰκίαν ἀπολιπὼν ἢ τάφον οἰκήσεις ἢ πυργίον ἔρημον ἢ καὶ πίθον· ἡ πήρα δέ σοι θέρμων ἔσται μεστὴ καὶ ὀπισθογράφων βιβλίων· καὶ οὕτως ἔχων εὐδαιμονέστερος εἶναι φήσεις τοῦ μεγάλου βασιλέως. ἢν μαστιγοῖ δέ τις ἢ στρεβλοῖ, τούτων οὐδὲν ἀνιαρὸν ἡγήσῃ.", "st": "24.9"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> πῶς τοῦτο φὴς τὸ μὴ ἀλγεῖν μαστιγούμενον; οὐ γὰρ χελώνης ἢ καράβου τὸ δέρμα περιβέβλημαι.", "st": "24.9"}, {"sp": "N", "t": "<em>Διογένης.<\/em> τὸ Εὐριπίδειον ἐκεῖνο ζηλώσεις μικρὸν ἐναλλάξας.", "st": "24.9"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> τὸ ποῖον;", "st": "24.9"}, {"sp": "N", "t": "<em>Διογένης.<\/em> ἡ φρήν σοι ἀλγήσει, ἡ δὲ γλῶσσα ἔσται ἀνάλγητος.", "st": "24.9"}, {"sp": "N", "t": "ἃ δὲ μάλιστα δεῖ προσεῖναι, ταῦτά ἐστιν· ἰταμὸν χρὴ εἶναι καὶ θρασὺν καὶ λοιδορεῖσθαι πᾶσιν ἑξῆς καὶ βασιλεῦσι καὶ ἰδιώταις· οὕτω γὰρ ἀποβλέψονταί σε καὶ ἀνδρεῖον ὑπολήψονται. βάρβαρος δὲ ἡ φωνὴ ἔστω καὶ ἀπηχὲς τὸ φθέγμα καὶ ἀτεχνῶς ὅμοιον κυνί, καὶ πρόσωπον δὲ ἐντεταμένον καὶ βάδισμα τοιούτῳ προσώπῳ πρέπον, καὶ ὅλως θηριώδη τὰ πάντα καὶ ἄγρια. αἰδὼς δὲ καὶ ἐπιείκεια καὶ μετριότης ἀπέστω, καὶ τὸ ἐρυθριᾶν ἀπόξυσον τοῦ προσώπου παντελῶς. δίωκε δὲ τὰ πολυανθρωπότατα τῶν χωρίων, καὶ ἐν αὐτοῖς τούτοις μόνος καὶ ἀκοινώνητος εἶναι θέλε μὴ φίλον, μὴ ξένον προσιέμενος· κατάλυσις γὰρ τὰ τοιαῦτα τῆς ἀρχῆς. ἐν ὄψει δὲ πάντων, ἃ μηδὲ ἰδίᾳ ποιήσειεν ἄν τις, θαρρῶν ποίει, καὶ τῶν ἀφροδισίων αἱροῦ τὰ γελοιότερα, καὶ τέλος, ἤν σοι δοκῇ, πολύποδα ὠμὸν ἢ σηπίαν φαγὼν ἀπόθανε. ταύτην σοι τὴν εὐδαιμονίαν προξενοῦμεν.", "st": "24.10"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> ἄπαγε· μιαρὰ γὰρ καὶ οὐκ ἀνθρώπινα λέγεις.", "st": "24.11"}, {"sp": "N", "t": "<em>Διογένης.<\/em> ἀλλὰ ῥᾷστά γε, ὦ οὗτος, καὶ πᾶσιν εὐχερῆ μετελθεῖν· οὐ γάρ σοι δεήσει παιδείας καὶ λόγων καὶ λήρων, ἀλλ’ ἐπίτομος αὕτη σοι πρὸς δόξαν ἡ ὁδός· κἂν ἰδιώτης ᾖς, ἤτοι σκυτοδέψης ἢ ταριχοπώλης ἢ τέκτων ἢ τραπεζίτης, οὐδέν σε κωλύσει θαυμαστὸν εἴναι, ἢν μόνον ἡ ἀναίδεια καὶ τὸ θράσος παρῇ καὶ λοιδορεῖσθαι καλῶς ἐκμάθῃς.", "st": "24.11"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> πρὸς ταῦτα μὲν οὐ δέομαί σου. ναύτης δ’ ἂν ἴσως ἢ κηπουρὸς ἐν καιρῷ γένοιο, καὶ ταῦτα, ἢν ἐθέλῃ σε ἀποδόσθαι οὑτοσὶ τὸ μέγιστον δύ’ ὀβολῶν.", "st": "24.11"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> ἔχε λαβών· καὶ γὰρ ἄσμενοι ἀπαλλαξόμεθα ἐνοχλοῦντος αὐτοῦ καὶ βοῶντος καὶ ἅπαντας ἁπαξαπλῶς ὑβρίζοντος καὶ ἀγορεύοντος κακῶς.", "st": "24.11"}, {"sp": "N", "t": "<em>Ζεύς.<\/em> ἄλλον κάλει τὸν Κυρηναῖον, τὸν ἐν τῇ πορφυρίδι, τὸν ἐστεφανωμένον.", "st": "24.12"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> ἄγε δή, πρόσεχε πᾶς· πολυτελὲς τὸ χρῆμα καὶ πλουσίων δεόμενον. βίος οὗτος ἥδιστος, βίος τρισμακάριστος. τίς ἐπιθυμεῖ τρυφῆς; τίς ὠνεῖται τὸν ἁβρότατον;", "st": "24.12"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> ἐλθὲ σὺ καὶ λέγε ἅπερ εἰδὼς τυγχάνεις· ὠνήσομαι γάρ σε, ἢν ὠφέλιμος ᾖς.", "st": "24.12"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> μὴ ἐνόχλει αὐτόν, ὦ βέλτιστε, μηδὲ ἀνάκρινε· μεθύει γάρ. ὥστε οὐκ ἂν ἀποκρίναιτό σοι, τὴν γλῶτταν, ὡς ὁρᾷς, διολισθάνων.", "st": "24.12"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> καὶ τίς ἂν εὖ φρονῶν πρίαιτο διεφθαρμένον οὕτω καὶ ἀκόλαστον ἀνδράποδον; ὅσον δὲ καὶ ἀποπνεῖ μύρων, ὡς δὲ καὶ σφαλερὸν βαδίζει καὶ παράφορον. ἀλλὰ κἂν σύ γε, ὦ Ἑρμῆ, λέγε ὁποῖα πρόσεστιν αὐτῷ καὶ ἃ μετιὼν τυγχάνει.", "st": "24.12"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> τὸ μὲν ὅλον, συμβιῶναι δεξιὸς καὶ συμπιεῖν ἱκανὸς καὶ κωμάσαι μετὰ αὐλητρίδος ἐπιτήδειος ἐρῶντι καὶ ἀσώτῳ δεσπότῃ· τὰ ἄλλα δὲ πεμμάτων ἐπιστήμων καὶ ὀψοποιὸς ἐμπειρότατος, καὶ ὅλως σοφιστὴς ἡδυπαθείας. ἐπαιδεύθη μὲν οὖν Ἀθήνησιν, ἐδούλευσε δὲ καὶ περὶ Σικελίαν τοῖς τυράννοις καὶ σφόδρα εὐδοκίμει παρ’ αὐτοῖς. τὸ δὲ κεφάλαιον τῆς προαιρέσεως, ἁπάντων καταφρονεῖν, ἅπασι χρῆσθαι, πανταχόθεν ἐρανίζεσθαι τὴν ἡδονήν.", "st": "24.12"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> ὥρα σοι ἄλλον περιβλέπειν τῶν πλουσίων τούτων καὶ πολυχρημάτων· ἐγὼ μὲν γὰρ οὐκ ἐπιτήδειος ἱλαρὸν ὠνεῖσθαι βίον.", "st": "24.12"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> Ἄπρατος ἔοικεν ἡμῖν οὗτος, ὦ Ζεῦ, μένειν.", "st": "24.12"}, {"sp": "N", "t": "<em>Ζεύς.<\/em> Μετάστησον· ἄλλον παράγε· μᾶλλον δὲ τὼ δύο τούτω, τὸν γελῶντα τὸν Ἀβδηρόθεν καὶ τὸν κλάοντα τὸν ἐξ Ἐφέσου· ἅμα γὰρ αὐτὼ πεπρᾶσθαι βούλομαι.", "st": "24.13"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> κατάβητον ἐς τὸ μέσον. τὼ ἀρίστω βίω πωλῶ, τὼ σοφωτάτω πάντων ἀποκηρύττομεν.", "st": "24.13"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> ὦ Ζεῦ τῆς ἐναντιότητος. ὁ μὲν οὐ διαλείπει γελῶν, ὁ δέ τινα ἔοικε πενθεῖν· δακρύει γοῦν τὸ παράπαν. τί ταῦτα, ὦ οὗτος; τί γελᾷς;", "st": "24.13"}, {"sp": "N", "t": "<em>Δημόκριτος.<\/em> ἐρωτᾷς; ὅτι μοι γελοῖα πάντα δοκέει τὰ πρήγματα ὑμέων καὶ αὐτοὶ ὑμέες.", "st": "24.13"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> πῶς λέγεις; καταγελᾷς ἡμῶν ἁπάντων καὶ παρ’ οὐδὲν τίθεσαι τὰ ἡμέτερα πράγματα;", "st": "24.13"}, {"sp": "N", "t": "<em>Δημόκριτος.<\/em> ὧδε ἔχει· σπουδαῖον γὰρ ἐν αὐτέοισιν οὐδέν, κενεὰ δὲ πάντα καὶ ἀτόμων φορὴ καὶ ἀπειρίη.", "st": "24.13"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> οὐ μὲν οὖν, ἀλλὰ σὺ κενὸς ὡς ἀληθῶς καὶ ἄπειρος.", "st": "24.13"}, {"sp": "N", "t": "ὢ τῆς ὕβρεως, οὐ παύσῃ γελῶν; σὺ δὲ τί κλάεις, ὦ βέλτιστε; πολὺ γὰρ οἶμαι κάλλιον σοὶ προσλαλεῖν.", "st": "24.14"}, {"sp": "N", "t": "<em>Ἡράκλειτος.<\/em> ἡγέομαι γάρ, ὦ ξεῖνε, τὰ ἀνθρωπήϊα πρήγματα ὀϊζυρὰ καὶ δακρυώδεα καὶ οὐδὲν αὐτέων ὅ τι μὴ ἐπικήριον· τὸ δὴ οἰκτείρω τε σφέας καὶ ὀδύρομαι, καὶ τὰ μὲν παρεόντα οὐ δοκέω μεγάλα, τὰ δὲ ὑστέρῳ χρόνῳ ἐσόμενα πάμπαν ἀνιηρά, λέγω δὲ τὰς ἐκπυρώσιας καὶ τὴν τοῦ ὅλου συμφορήν· ταῦτα ὀδύρομαι καὶ ὅτι ἔμπεδον οὐδέν, ἀλλ’ ὅκως ἐς κυκεῶνα τὰ πάντα συνειλέονται καί ἐστι τὠυτὸ τέρψις ἀτερψίη, γνῶσις ἀγνωσίη, μέγα μικρόν, ἄνω κάτω περιχωρέοντα καὶ ἀμειβόμενα ἐν τῇ τοῦ αἰῶνος παιδιῇ.", "st": "24.14"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> τί γὰρ ὁ αἰών ἐστι;", "st": "24.14"}, {"sp": "N", "t": "<em>Ἡράκλειτος.<\/em> παῖς παίζων, πεσσεύων, διαφερόμενος, συμφερόμενος.", "st": "24.14"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> τί δὲ ἄνθρωποι;", "st": "24.14"}, {"sp": "N", "t": "<em>Ἡράκλειτος.<\/em> θεοὶ θνητοί.", "st": "24.14"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> τί δὲ θεοί;", "st": "24.14"}, {"sp": "N", "t": "<em>Ἡράκλειτος.<\/em> ἄνθρωποι ἀθάνατοι.", "st": "24.14"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> αἰνίγματα λέγεις, ὦ οὗτος, ἢ γρίφους συντίθης; ἀτεχνῶς γὰρ ὥσπερ ὁ Λοξίας οὐδὲν ἀποσαφεῖς.", "st": "24.14"}, {"sp": "N", "t": "<em>Ἡράκλειτος.<\/em> οὐδὲν γάρ μοι μέλει ὑμέων.", "st": "24.14"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> τοιγαροῦν οὐδὲ ὠνήσεταί σέ τις εὖ φρονῶν.", "st": "24.14"}, {"sp": "N", "t": "<em>Ἡράκλειτος.<\/em> ἐγὼ δὲ κέλομαι πᾶσιν ἡβηδὸν οἰμώζειν, τοῖσιν ὠνεομένοισι καὶ τοῖσιν οὐκ ὠνεομένοισι.", "st": "24.14"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> τουτὶ τὸ κακὸν οὐ πόρρω μελαγχολίας ἐστίν· οὐδέτερον δὲ ὅμως αὐτῶν ἔγωγε ὠνήσομαι.", "st": "24.14"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> ἄπρατοι καὶ οὗτοι μένουσιν.", "st": "24.14"}, {"sp": "N", "t": "<em>Ζεύς.<\/em> ἄλλον ἀποκήρυττε.", "st": "24.14"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> βούλει τὸν Ἀθηναῖον ἐκεῖνον, τὸν στωμύλον;", "st": "24.15"}, {"sp": "N", "t": "<em>Ζεύς.<\/em> πάνυ μὲν οὖν.", "st": "24.15"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> δεῦρο ἐλθὲ σύ. βίον ἀγαθὸν καὶ συνετὸν ἀποκηρύττομεν. τίς ὠνεῖται τὸν ἱερώτατον;", "st": "24.15"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> εἰπέ μοι, τί μάλιστα εἰδὼς τυγχάνεις;", "st": "24.15"}, {"sp": "N", "t": "<em>Σωκράτης.<\/em> παιδεραστής εἰμι καὶ σοφὸς τὰ ἐρωτικά.", "st": "24.15"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> πῶς οὖν ἐγὼ πρίωμαί σε; παιδαγωγοῦ γὰρ ἐδεόμην τῷ παιδὶ καλῷ ὄντι μοι.", "st": "24.15"}, {"sp": "N", "t": "<em>Σωκράτης.<\/em> τίς δ’ ἂν ἐπιτηδειότερος ἐμοῦ γένοιτο συνεῖναι καλῷ; καὶ γὰρ οὐ τῶν σωμάτων ἐραστής εἰμι, τὴν ψυχὴν δὲ ἡγοῦμαι καλήν. ἀμέλει κἂν ὑπὸ ταὐτὸν ἱμάτιόν μοι κατακέωνται, ἀκούσει αὐτῶν λεγόντων μηδὲν ὑπ’ ἐμοῦ δεινὸν παθεῖν.", "st": "24.15"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> ἄπιστα λέγεις, τὸ παιδεραστὴν ὄντα μὴ πέρα τῆς ψυχῆς πολυπραγμονεῖν, καὶ ταῦτα ἐπ’ ἐξουσίας, ὑπὸ τῷ αὐτῷ ἱματίῳ κατακείμενον.", "st": "24.15"}, {"sp": "N", "t": "<em>Σωκράτης.<\/em> καὶ μὴν ὀμνύω γέ σοι τὸν κύνα καὶ τὴν πλάτανον οὕτω ταῦτα ἔχειν.", "st": "24.16"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> Ἡράκλεις τῆς ἀτοπίας τῶν θεῶν.", "st": "24.16"}, {"sp": "N", "t": "<em>Σωκράτης.<\/em> τί σὺ λέγεις; οὐ δοκεῖ σοι ὁ κύων εἶναι θεός; οὐχ ὁρᾷς τὸν Ἄνουβιν ἐν Αἰγύπτῳ ὅσος; καὶ τὸν ἐν οὐρανῷ Σείριον καὶ τὸν παρὰ τοῖς κάτω Κέρβερον;", "st": "24.16"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> Εὖ λέγεις, ἐγὼ δὲ διημάρτανον. ἀλλὰ τίνα βιοῖς τὸν τρόπον;", "st": "24.17"}, {"sp": "N", "t": "<em>Σωκράτης.<\/em> οἰκῶ μὲν ἐμαυτῷ τινα πόλιν ἀναπλάσας, χρῶμαι δὲ πολιτείᾳ ξένῃ καὶ νόμους νομίζω τοὺς ἐμούς.", "st": "24.17"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> ἓν ἐβουλόμην ἀκοῦσαι τῶν δογμάτων.", "st": "24.17"}, {"sp": "N", "t": "<em>Σωκράτης.<\/em> ἄκουε δὴ τὸ μέγιστον, ὃ περὶ τῶν γυναικῶν μοι δοκεῖ· μηδεμίαν αὐτῶν μηδενὸς εἶναι μόνου, παντὶ δὲ μετεῖναι τῷ βουλομένῳ τοῦ γάμου.", "st": "24.17"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> τοῦτο φής, ἀνῃρῆσθαι τοὺς περὶ μοιχείας νόμους;", "st": "24.17"}, {"sp": "N", "t": "<em>Σωκράτης.<\/em> νὴ Δία, καὶ ἁπλῶς γε πᾶσαν τὴν περὶ τὰ τοιαῦτα μικρολογίαν.", "st": "24.17"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> τί δὲ περὶ τῶν ἐν ὥρᾳ παίδων σοι δοκεῖ;", "st": "24.17"}, {"sp": "N", "t": "<em>Σωκράτης.<\/em> καὶ οὗτοι ἔσονται τοῖς ἀρίστοις ἆθλον φιλῆσαι λαμπρόν τι καὶ νεανικὸν ἐργασαμένοις.", "st": "24.17"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> βαβαὶ τῆς φιλοδωρίας. τῆς δὲ σοφίας τί σοι τὸ κεφάλαιον;", "st": "24.18"}, {"sp": "N", "t": "<em>Σωκράτης.<\/em> αἱ ἰδέαι καὶ τὰ τῶν ὄντων παραδείγματα· ὁπόσα γὰρ δὴ ὁρᾷς, τὴν γῆν, τὰ ἐπὶ γῆς, τὸν οὐρανόν, τὴν θάλατταν, ἁπάντων τούτων εἰκόνες ἀφανεῖς ἑστᾶσιν ἔξω τῶν ὅλων.", "st": "24.18"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> ποῦ δὲ ἑστᾶσιν;", "st": "24.18"}, {"sp": "N", "t": "<em>Σωκράτης.<\/em> οὐδαμοῦ· εἰ γάρ που εἶεν, οὐκ ἂν εἶεν.", "st": "24.18"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> οὐχ ὁρῶ ταῦθ’ ἅπερ λέγεις τὰ παραδείγματα.", "st": "24.18"}, {"sp": "N", "t": "<em>Σωκράτης.<\/em> εἰκότως· τυφλὸς γὰρ εἶ τῆς ψυχῆς τὸν ὀφθαλμόν. ἐγὼ δὲ πάντων ὁρῶ εἰκόνας καὶ σὲ ἀφανῆ κἀμὲ ἄλλον, καὶ ὅλως διπλᾶ πάντα.", "st": "24.18"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> τοιγαροῦν ὠνητέος εἶ σοφὸς καὶ ὀξυδερκής τις ὤν. φέρε ἴδω τί καὶ πράξεις με ὑπὲρ αὐτοῦ σύ;", "st": "24.18"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> δὸς δύο τάλαντα.", "st": "24.18"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> Ὠνησάμην ὅσου φής. τἀργύριον μέντοι εἰς αὖθις καταβαλῶ.", "st": "24.18"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> τί σοι τοὔνομα;", "st": "24.19"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> Δίων Συρακούσιος.", "st": "24.19"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> ἄγε λαβὼν ἀγαθῇ τύχῃ. τὸν Ἐπικούρειον σὲ ἤδη καλῶ. τίς ὠνήσεται τοῦτον; ἔστι μὲν τοῦ γελῶντος ἐκείνου μαθητὴς καὶ τοῦ μεθύοντος, οὓς μικρῷ πρόσθεν ἀπεκηρύττομεν. ἓν δὲ πλέον οἶδεν αὐτῶν, παρ’ ὅσον δυσσεβέστερος τυγχάνει· τὰ δὲ ἄλλα ἡδὺς καὶ λιχνείᾳ φίλος.", "st": "24.19"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> τίς ἡ τιμή;", "st": "24.19"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> δύο μναῖ.", "st": "24.19"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> λάμβανε· τὸ δεῖνα δέ, ὅπως εἰδῶ, τίσι χαίρει τῶν ἐδεσμάτων;", "st": "24.19"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> τὰ γλυκέα σιτεῖται καὶ τὰ μελιτώδη καὶ μάλιστά γε τὰς ἰσχάδας.", "st": "24.19"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> χαλεπὸν οὐδέν· ὠνησόμεθα γὰρ αὐτῷ παλάθας τῶν Καρικῶν.", "st": "24.19"}, {"sp": "N", "t": "<em>Ζεύς.<\/em> ἄλλον κάλει, τὸν ἐν χρῷ κουρίαν ἐκεῖνον, τὸν σκυθρωπόν, τὸν ἀπὸ τῆς στοᾶς.", "st": "24.20"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> εὖ λέγεις· ἐοίκασι γὰρ πολύ τι πλῆθος αὐτὸν περιμένειν τῶν ἐπὶ τὴν ἀγορὰν ἀπηντηκότων. αὐτὴν τὴν ἀρετὴν πωλῶ, τῶν βίων τὸν τελειότατον. τίς ἅπαντα μόνος εἰδέναι θέλει;", "st": "24.20"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> πῶς τοῦτο φής;", "st": "24.20"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> ὅτι μόνος οὗτος σοφός, μόνος καλός, μόνος δίκαιος ἀνδρεῖος βασιλεὺς ῥήτωρ πλούσιος νομοθέτης καὶ τὰ ἄλλα ὁπόσα ἐστίν.", "st": "24.20"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> οὐκοῦν καὶ μάγειρος μόνος, καὶ νὴ Δία γε σκυτοδέψης ἢ τέκτων καὶ τὰ τοιαῦτα;", "st": "24.20"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> ἔοικεν.", "st": "24.20"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> ἐλθέ, ὦγαθέ, καὶ λέγε πρὸς τὸν ὠνητὴν ἐμὲ ποῖός τις εἶ, καὶ πρῶτον εἰ οὐκ ἄχθῃ πιπρασκόμενος καὶ δοῦλος ὤν.", "st": "24.21"}, {"sp": "N", "t": "<em>Χρύσιππος.<\/em> οὐδαμῶς· οὐ γὰρ ἐφ’ ἡμῖν ταῦτά ἐστιν. ἃ δὲ οὐκ ἐφ’ ἡμῖν, ἀδιάφορα εἶναι συμβέβηκεν.", "st": "24.21"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> οὐ μανθάνω ᾗ καὶ λέγεις.", "st": "24.21"}, {"sp": "N", "t": "<em>Χρύσιππος.<\/em> τί φής; οὐ μανθάνεις ὅτι τῶν τοιούτων τὰ μέν ἐστι προηγμένα, τὰ δ’ ἀνάπαλιν ἀποπροηγμένα;", "st": "24.21"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> οὐδὲ νῦν μανθάνω.", "st": "24.21"}, {"sp": "N", "t": "<em>Χρύσιππος.<\/em> εἰκότως· οὐ γὰρ εἶ συνήθης τοῖς ἡμετέροις ὀνόμασιν οὐδὲ τὴν καταληπτικὴν φαντασίαν ἔχεις, ὁ δὲ σπουδαῖος ὁ τὴν λογικὴν θεωρίαν ἐκμαθὼν οὐ μόνον ταῦτα οἶδεν, ἀλλὰ καὶ σύμβαμα καὶ παρασύμβαμα ὁποῖα καὶ ὁπόσον ἀλλήλων διαφέρει.", "st": "24.21"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> πρὸς τῆς σοφίας, μὴ φθονήσῃς κἂν τοῦτο εἰπεῖν, τί τὸ σύμβαμα καὶ τὸ παρασύμβαμα· καὶ γὰρ οὐκ οἶδ’ ὅπως ἐπλήγην ὑπὸ τοῦ ῥυθμοῦ τῶν ὀνομάτων.", "st": "24.21"}, {"sp": "N", "t": "<em>Χρύσιππος.<\/em> ἀλλ’ οὐδεὶς φθόνος· ἢν γάρ τις χωλὸς ὢν αὐτῷ ἐκείνῳ τῷ χωλῷ ποδὶ προσπταίσας λίθῳ τραῦμα ἐξ ἀφανοῦς λάβῃ, ὁ τοιοῦτος εἶχε μὲν δήπου σύμβαμα τὴν χωλείαν, τὸ τραῦμα δὲ παρασύμβαμα προσέλαβεν.", "st": "24.21"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> ὢ τῆς ἀγχινοίας· τί δὲ ἄλλο μάλιστα φὴς εἰδέναι;", "st": "24.22"}, {"sp": "N", "t": "<em>Χρύσιππος.<\/em> τὰς τῶν λόγων πλεκτάνας αἷς συμποδίζω τοὺς προσομιλοῦντας καὶ ἀποφράττω καὶ σιωπᾶν ποιῶ, φιμὸν ἀτεχνῶς αὐτοῖς περιτιθείς· ὄνομα δὲ τῇ δυνάμει ταύτῃ ὁ ἀοίδιμος συλλογισμός.", "st": "24.22"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> Ἡράκλεις, ἄμαχόν τινα καὶ βίαιον λέγεις.", "st": "24.22"}, {"sp": "N", "t": "<em>Χρύσιππος.<\/em> σκόπει γοῦν· ἔστι σοι παιδίον;", "st": "24.22"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> τί μήν;", "st": "24.22"}, {"sp": "N", "t": "<em>Χρύσιππος.<\/em> τοῦτο ἤν πως κροκόδειλος ἁρπάσῃ πλησίον τοῦ ποταμοῦ πλαζόμενον εὑρών, κᾆτά σοι ἀποδώσειν ὑπισχνῆται αὐτό, ἢν εἴπῃς τἀληθὲς ὅ τι δέδοκται αὐτῷ περὶ τῆς ἀποδόσεως τοῦ βρέφους, τί φήσεις αὐτὸν ἐγνωκέναι;", "st": "24.22"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> δυσαπόκριτον ἐρωτᾷς. ἀπορῶ γὰρ ὁπότερον εἰπὼν ἀπολάβοιμι. ἀλλὰ σὺ πρὸς Διὸς ἀποκρινάμενος ἀνάσωσαί μοι τὸ παιδίον, μὴ καὶ φθάσῃ αὐτὸ καταπιών.", "st": "24.22"}, {"sp": "N", "t": "<em>Χρύσιππος.<\/em> θάρρει· καὶ ἄλλα γάρ σε διδάξομαι θαυμασιώτερα.", "st": "24.22"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> τὰ ποῖα;", "st": "24.22"}, {"sp": "N", "t": "<em>Χρύσιππος.<\/em> τὸν θερίζοντα καὶ τὸν κυριεύοντα καὶ ἐπὶ πᾶσι τὴν Ἠλέκτραν καὶ τὸν ἐγκεκαλυμμένον.", "st": "24.22"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> τίνα τοῦτον τὸν ἐγκεκαλυμμένον ἢ τίνα τὴν Ἠλέκτραν λέγεις;", "st": "24.22"}, {"sp": "N", "t": "<em>Χρύσιππος.<\/em> Ἠλέκτραν μὲν ἐκείνην τὴν πάνυ, τὴν Ἀγαμέμνονος, ἣ τὰ αὐτὰ οἶδέ τε ἅμα καὶ οὐκ οἶδε· παρεστῶτος γὰρ αὐτῇ τοῦ Ὀρέστου ἔτι ἀγνῶτος οἶδε μὲν Ὀρέστην, ὅτι ἀδελφὸς αὐτῆς, ὅτι δὲ οὗτος Ὀρέστης ἀγνοεῖ. τὸν δ’ αὖ ἐγκεκαλυμμένον καὶ πάνυ θαυμαστὸν ἀκούσῃ λόγον· ἀπόκριναι γάρ μοι, τὸν πατέρα οἶσθα τὸν σεαυτοῦ;", "st": "24.22"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> ναί.", "st": "24.22"}, {"sp": "N", "t": "<em>Χρύσιππος.<\/em> τί οὖν; ἤν σοι παραστήσας τινὰ ἐγκεκαλυμμένον ἔρωμαι, τοῦτον οἶσθα; τί φήσεις;", "st": "24.22"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> δηλαδὴ ἀγνοεῖν.", "st": "24.22"}, {"sp": "N", "t": "<em>Χρύσιππος.<\/em> ἀλλὰ μὴν αὐτὸς οὗτος ἦν ὁ πατὴρ ὁ σός· ὥστε εἰ τοῦτον ἀγνοεῖς, δῆλος εἶ τὸν πατέρα τὸν σὸν ἀγνοῶν.", "st": "24.23"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> οὐ μὲν οὖν· ἀλλ’ ἀποκαλύψας αὐτὸν εἴσομαι τὴν ἀλήθειαν. ὅμως δ’ οὖν τί σοι τῆς σοφίας τὸ τέλος, ἢ τί πράξεις πρὸς τὸ ἀκρότατον τῆς ἀρετῆς ἀφικόμενος;", "st": "24.23"}, {"sp": "N", "t": "<em>Χρύσιππος.<\/em> περὶ τὰ πρῶτα κατὰ φύσιν τότε γενήσομαι, λέγω δὲ πλοῦτον, ὑγίειαν καὶ τὰ τοιαῦτα. πρότερον δὲ ἀνάγκη πολλὰ προπονῆσαι λεπτογράφοις βιβλίοις παραθήγοντα τὴν ὄψιν καὶ σχόλια συναγείροντα καὶ σολοικισμῶν ἐμπιπλάμενον καὶ ἀτόπων ῥημάτων· καὶ τὸ κεφάλαιον, οὐ θέμις γενέσθαι σοφόν, ἢν μὴ τρὶς ἐφεξῆς τοῦ ἐλλεβόρου πίῃς.", "st": "24.23"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> γενναῖά σου ταῦτα καὶ δεινῶς ἀνδρικά. τὸ δὲ Γνίφωνα εἶναι καὶ τοκογλύφον — καὶ γὰρ τάδε ὁρῶ σοι προσόντα — τί φῶμεν, ἀνδρὸς ἤδη πεπωκότος τὸν ἐλλέβορον καὶ τελείου πρὸς ἀρετήν;", "st": "24.23"}, {"sp": "N", "t": "<em>Χρύσιππος.<\/em> ναί· μόνῳ γοῦν τὸ δανείζειν πρέποι ἂν τῷ σοφῷ· ἐπεὶ γὰρ ἴδιον αὐτοῦ συλλογίζεσθαι, τὸ δανείζειν δὲ καὶ λογίζεσθαι τοὺς τόκους πλησίον εἶναι δοκεῖ τῷ συλλογίζεσθαι, μόνου ἂν εἴη τοῦ σπουδαίου καθάπερ ἐκεῖνο καὶ τοῦτο, καὶ οὐ μόνον γε ἁπλοῦς, ὥσπερ οἱ ἄλλοι, τοὺς τόκους, ἀλλὰ καὶ τούτων ἑτέρους τόκους λαμβάνειν· ἢ γὰρ ἀγνοεῖς ὅτι τῶν τόκων οἱ μέν εἰσι πρῶτοί τινες, οἱ δὲ δεύτεροι, καθάπερ αὐτῶν ἐκείνων ἀπόγονοι; ὁρᾷς δὲ δὴ καὶ τὸν συλλογισμὸν ὁποῖά φησιν· εἰ τὸν πρῶτον τόκον λήψεται, λήψεται καὶ τὸν δεύτερον· ἀλλὰ μὴν τὸν πρῶτον λήψεται, λήψεται ἄρα καὶ τὸν δεύτερον.", "st": "24.23"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> οὐκοῦν καὶ μισθῶν πέρι τὰ αὐτὰ φῶμεν, οὓς σὺ λαμβάνεις ἐπὶ τῇ σοφίᾳ παρὰ τῶν νέων, καὶ δῆλον ὅτι μόνος ὁ σπουδαῖος μισθὸν ἐπὶ τῇ ἀρετῇ λήψεται;", "st": "24.24"}, {"sp": "N", "t": "<em>Χρύσιππος.<\/em> μανθάνεις· οὐ γὰρ ἐμαυτοῦ ἕνεκα λαμβάνω, τοῦ δὲ διδόντος αὐτοῦ χάριν· ἐπεὶ γάρ ἐστιν ὁ μέν τις ἐκχύτης, ὁ δὲ περιεκτικός, ἐμαυτὸν μὲν ἀσκῶ εἶναι περιεκτικόν, τὸν δὲ μαθητὴν ἐκχύτην.", "st": "24.24"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> καὶ μὴν τοὐναντίον ἐχρῆν τὸν νέον μὲν εἶναι περιεκτικόν, σὲ δὲ τὸν μόνον πλούσιον ἐκχύτην.", "st": "24.24"}, {"sp": "N", "t": "<em>Χρύσιππος.<\/em> σκώπτεις, ὦ οὗτος. ἀλλ’ ὅρα μή σε ἀποτοξεύσω τῷ ἀναποδείκτῳ συλλογισμῷ.", "st": "24.24"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> καὶ τί δεινὸν ἀπὸ τοῦ βέλους;", "st": "24.24"}, {"sp": "N", "t": "<em>Χρύσιππος.<\/em> ἀπορία καὶ σιωπὴ καὶ διαστραφῆναι τὴν διάνοιαν.", "st": "24.24"}, {"sp": "N", "t": "ὃ δὲ μέγιστον, ἢν ἐθέλω, τάχιστά σε ἀποδείξω λίθον.", "st": "24.25"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> πῶς λίθον; οὐ γὰρ Περσεὺς σύ, ὦ βέλτιστε, εἶναί μοι δοκεῖς.", "st": "24.25"}, {"sp": "N", "t": "<em>Χρύσιππος.<\/em> ὧδέ πως· ὁ λίθος σῶμά ἐστι;", "st": "24.25"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> ναί.", "st": "24.25"}, {"sp": "N", "t": "<em>Χρύσιππος.<\/em> τί δέ; τὸ ζῷον οὐ σῶμα;", "st": "24.25"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> ναί.", "st": "24.25"}, {"sp": "N", "t": "<em>Χρύσιππος.<\/em> σὺ δὲ ζῷον;", "st": "24.25"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> ἔοικα γοῦν.", "st": "24.25"}, {"sp": "N", "t": "<em>Χρύσιππος.<\/em> λίθος ἄρα εἶ σῶμα ὤν.", "st": "24.25"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> μηδαμῶς. ἀλλ’ ἀνάλυσόν με πρὸς τοῦ Διὸς καὶ ἐξ ὑπαρχῆς ποίησον ἄνθρωπον.", "st": "24.25"}, {"sp": "N", "t": "<em>Χρύσιππος.<\/em> οὐ χαλεπόν· ἀλλ’ ἔμπαλιν ἴσθι ἄνθρωπος. εἰπὲ γάρ μοι, πᾶν σῶμα ζῷον;", "st": "24.25"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> οὔ.", "st": "24.25"}, {"sp": "N", "t": "<em>Χρύσιππος.<\/em> τί δέ; λίθος ζῷον;", "st": "24.25"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> οὔ.", "st": "24.25"}, {"sp": "N", "t": "<em>Χρύσιππος.<\/em> σὺ δὲ σῶμα εἶ;", "st": "24.25"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> ναί.", "st": "24.25"}, {"sp": "N", "t": "<em>Χρύσιππος.<\/em> σῶμα δὲ ὢν ζῷον εἶ;", "st": "24.25"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> ναί.", "st": "24.25"}, {"sp": "N", "t": "<em>Χρύσιππος.<\/em> οὐκ ἄρα λίθος εἶ ζῷόν γε ὤν.", "st": "24.25"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> εὖ γε ἐποίησας, ὡς ἤδη μου τὰ σκέλη καθάπερ τῆς Νιόβης ἀπεψύχετο καὶ πάγια ἦν. ἀλλὰ ὠνήσομαί γε σέ. πόσον ὑπὲρ αὐτοῦ καταβαλῶ;", "st": "24.25"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> μνᾶς δώδεκα.", "st": "24.25"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> λάμβανε.", "st": "24.25"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> μόνος δὲ αὐτὸν ἐώνησαι;", "st": "24.25"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> μὰ Δί’, ἀλλ’ οὗτοι πάντες οὓς ὁρᾷς.", "st": "24.25"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> πολλοί γε καὶ τοὺς ὤμους καρτεροὶ καὶ τοῦ θερίζοντος ἄξιοι.", "st": "24.25"}, {"sp": "N", "t": "<em>Ζεύς.<\/em> μὴ διάτριβε· ἄλλον κάλει τὸν Περιπατητικόν.", "st": "24.26"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> σέ φημι, τὸν καλόν, τὸν πλούσιον. ἄγε δή, ὠνήσασθε τὸν συνετώτατον, τὸν ἅπαντα ὅλως ἐπιστάμενον.", "st": "24.26"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> ποῖος δέ τις ἐστί;", "st": "24.26"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> μέτριος, ἐπιεικής, ἁρμόδιος τῷ βίῳ, τὸ δὲ μέγιστον, διπλοῦς.", "st": "24.26"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> πῶς λέγεις;", "st": "24.26"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> ἄλλος μὲν ὁ ἔκτοσθεν φαινόμενος, ἄλλος δὲ ὁ ἔντοσθεν εἶναι δοκεῖ· ὥστε ἢν πρίῃ αὐτόν, μέμνησο τὸν μὲν ἐξωτερικόν, τὸν δὲ ἐσωτερικὸν καλεῖν.", "st": "24.26"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> τί δὲ γινώσκει μάλιστα;", "st": "24.26"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> τρία εἶναι τὰ ἀγαθά, ἐν ψυχῇ, ἐν σώματι, ἐν τοῖς ἐκτός.", "st": "24.26"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> ἀνθρώπινα φρονεῖ. πόσου δέ ἐστιν;", "st": "24.26"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> εἴκοσι μνῶν.", "st": "24.26"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> πολλοῦ λέγεις.", "st": "24.26"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> οὔκ, ὦ μακάριε· καὶ γὰρ αὐτὸς ἔχειν τι ἀργύριον δοκεῖ, ὥστε οὐκ ἂν φθάνοις ὠνούμενος. ἔτι δὲ εἴσῃ αὐτίκα μάλα παρ’ αὐτοῦ πόσον μὲν ὁ κώνωψ βιοῖ τὸν χρόνον, ἐφ’ ὁπόσον δὲ βάθος ἡ θάλαττα ὑπὸ τοῦ ἡλίου καταλάμπεται, καὶ ὁποία τίς ἐστιν ἡ ψυχὴ τῶν ὀστρείων.", "st": "24.26"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> Ἡράκλεις τῆς ἀκριβολογίας.", "st": "24.26"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> τί δὲ εἰ ἀκούσειας ἄλλα πολλῷ τούτων ὀξυδερκέστερα, γονῆς τε πέρι καὶ γενέσεως καὶ τῆς ἐν ταῖς μήτραις τῶν ἐμβρύων πλαστικῆς, καὶ ὡς ἄνθρωπος μὲν γελαστικόν, ὄνος δὲ οὐ γελαστικὸν οὐδὲ τεκταινόμενον οὐδὲ πλωϊζόμενον;", "st": "24.26"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> πάνσεμνα φὴς καὶ ὀνησιφόρα τὰ μαθήματα, ὥστε ὠνοῦμαι αὐτὸν τῶν εἴκοσιν.", "st": "24.26"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> εἶεν.", "st": "24.27"}, {"sp": "N", "t": "<em>Ζεύς.<\/em> τίς λοιπὸς ἡμῖν;", "st": "24.27"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> καταλείπεται ὁ Σκεπτικὸς οὗτος. σὺ ὁ Πυρρίας πρόσιθι καὶ ἀποκηρύττου κατὰ τάχος. ἤδη μὲν ὑπορρέουσιν οἱ πολλοὶ καὶ ἐν ὀλίγοις ἡ πρᾶσις ἔσται. ὅμως δὲ τίς καὶ τοῦτον ὠνήσεται;", "st": "24.27"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> ἔγωγε. ἀλλὰ πρῶτον εἰπέ μοι, σὺ τί ἐπίστασαι;", "st": "24.27"}, {"sp": "N", "t": "<em>Πύρρων.<\/em> οὐδέν.", "st": "24.27"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> πῶς τοῦτο ἔφησθα;", "st": "24.27"}, {"sp": "N", "t": "<em>Πύρρων.<\/em> ὅτι οὐδὲν ὅλως εἶναί μοι δοκεῖ.", "st": "24.27"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> οὐδὲ ἡμεῖς ἄρα ἐσμέν τινες;", "st": "24.27"}, {"sp": "N", "t": "<em>Πύρρων.<\/em> οὐδὲ τοῦτο οἶδα.", "st": "24.27"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> οὐδὲ ὅτι σύ τις ὢν τυγχάνεις;", "st": "24.27"}, {"sp": "N", "t": "<em>Πύρρων.<\/em> πολὺ μᾶλλον ἔτι τοῦτο ἀγνοῶ.", "st": "24.27"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> ὢ τῆς ἀπορίας. τί δέ σοι τὰ σταθμία ταυτὶ βούλεται;", "st": "24.27"}, {"sp": "N", "t": "<em>Πύρρων.<\/em> ζυγοστατῶ ἐν αὐτοῖς τοὺς λόγους καὶ πρὸς τὸ ἴσον ἀπευθύνω, καὶ ἐπειδὰν ἀκριβῶς ὁμοίους τε καὶ ἰσοβαρεῖς ἴδω, τότε δὴ τότε ἀγνοῶ τὸν ἀληθέστερον.", "st": "24.27"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> τῶν ἄλλων δὲ τί ἂν πράττοις ἐμμελῶς;", "st": "24.27"}, {"sp": "N", "t": "<em>Πύρρων.<\/em> τὰ πάντα πλὴν δραπέτην μεταδιώκειν.", "st": "24.27"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> τί δὲ τοῦτό σοι ἀδύνατον;", "st": "24.27"}, {"sp": "N", "t": "<em>Πύρρων.<\/em> ὅτι, ὦγαθέ, οὐ καταλαμβάνω.", "st": "24.27"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> εἰκότως· βραδὺς γὰρ καὶ νωθής τις εἶναι δοκεῖς. ἀλλὰ τί σοι τὸ τέλος τῆς ἐπιστάσεως;", "st": "24.27"}, {"sp": "N", "t": "<em>Πύρρων.<\/em> ἡ ἀμαθία καὶ τὸ μήτε ἀκούειν μήτε ὁρᾶν.", "st": "24.27"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> οὐκοῦν καὶ τὸ τυφλὸς ἅμα καὶ κωφὸς εἶναι λέγεις;", "st": "24.27"}, {"sp": "N", "t": "<em>Πύρρων.<\/em> καὶ ἄκριτός γε προσέτι καὶ ἀναίσθητος καὶ ὅλως τοῦ σκώληκος οὐδὲν διαφέρων.", "st": "24.27"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> ὠνητέος εἶ διὰ ταῦτα. πόσου τοῦτον ἄξιον χρὴ φάναι;", "st": "24.27"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> μνᾶς Ἀττικῆς·", "st": "24.27"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> λάμβανε. τί φής, ὦ οὗτος; ἐώνημαι σε;", "st": "24.27"}, {"sp": "N", "t": "<em>Πύρρων.<\/em> ἄδηλον.", "st": "24.27"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> μηδαμῶς· ἐώνημαι γὰρ καὶ τἀργύριον κατέβαλον.", "st": "24.27"}, {"sp": "N", "t": "<em>Πύρρων.<\/em> ἐπέχω περὶ τούτου καὶ διασκέπτομαι.", "st": "24.27"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> καὶ μὴν ἀκολούθει μοι, καθάπερ χρὴ ἐμὸν οἰκέτην.", "st": "24.27"}, {"sp": "N", "t": "<em>Πύρρων.<\/em> τίς οἶδεν εἰ ἀληθῆ ταῦτα φής;", "st": "24.27"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> ὁ κῆρυξ καὶ ἡ μνᾶ καὶ οἱ παρόντες.", "st": "24.27"}, {"sp": "N", "t": "<em>Πύρρων.<\/em> πάρεισι γὰρ ἡμῖν τινες;", "st": "24.27"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> ἀλλ’ ἔγωγέ σε ἤδη ἐμβαλὼν ἐς τὸν μυλῶνα πείσω εἶναι δεσπότης κατὰ τὸν χείρω λόγον.", "st": "24.27"}, {"sp": "N", "t": "<em>Πύρρων.<\/em> ἔπεχε περὶ τούτου.", "st": "24.27"}, {"sp": "N", "t": "<em>Ἀγοράστης.<\/em> μὰ Δί’, ἀλλ’ ἤδη γε ἀπεφηνάμην.", "st": "24.27"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> σὺ μὲν παῦσαι ἀντιτείνων καὶ ἀκολούθει τῷ πριαμένῳ, ὑμᾶς δὲ εἰς αὔριον παρακαλοῦμεν· ἀποκηρύξειν γὰρ τοὺς ἰδιώτας καὶ βαναύσους καὶ ἀγοραίους βίους μέλλομεν.", "st": "24.27"}, {"sp": "HDR", "t": "Ἀναβιοῦντες ἢ Ἁλιεύς"}, {"sp": "N", "t": "<em>Σωκράτης.<\/em> βάλλε βάλλε τὸν κατάρατον ἀφθόνοις τοῖς λίθοις· ἐπίβαλλε τῶν βώλων· προσεπίβαλλε καὶ τῶν ὀστράκων· παῖε τοῖς ξύλοις τὸν ἀλιτήριον· ὅρα μὴ διαφύγῃ· καὶ σὺ βάλλε, ὦ Πλάτων· καὶ σύ, ὦ Χρύσιππε, καὶ σὺ δέ, καὶ πάντες ἅμα· συνασπίσωμεν ἐπ’ αὐτόν,<br>ὡς πήρη πήρῃφιν ἀρήγῃ, βάκτρα δὲ βάκτροις,<br>κοινὸς γὰρ πολέμιος, καὶ οὐκ ἔστιν ἡμῶν ὅντινα οὐχ ὕβρικε. σὺ δέ, ὦ Διόγενες, εἴ ποτε καὶ ἄλλοτε, χρῶ τῷ ξύλῳ· μηδὲ ἀνῆτε· διδότω τὴν ἀξίαν βλάσφημος ὤν. τί τοῦτο; κεκμήκατε, ὦ Ἐπίκουρε καὶ Ἀρίστιππε; καὶ μὴν οὐκ ἐχρῆν.<br>ἀνέρες ἔστε, σοφοί, μνήσασθε δὲ θούριδος ὀργῆς.", "st": "25.1"}, {"sp": "N", "t": "Ἀριστότελες, ἐπισπούδασον· ἔτι θᾶττον. εὖ ἔχει· ἑάλωκεν τὸ θηρίον. εἰλήφαμέν σε, ὦ μιαρέ. εἴσῃ γοῦν αὐτίκα οὕστινας ἡμᾶς ὄντας ἐκακηγόρεις. τῷ τρόπῳ δέ τις αὐτὸν καὶ μετέλθῃ; ποικίλον γάρ τινα θάνατον ἐπινοῶμεν κατ’ αὐτοῦ πᾶσιν ἡμῖν ἐξαρκέσαι δυνάμενον· καθ’ ἕκαστον γοῦν ἑπτάκις δίκαιός ἐστιν ἀπολωλέναι.", "st": "25.2"}, {"sp": "N", "t": "<em>Φιλόσοφος.<\/em> ἐμοὶ μὲν ἀνασκολοπισθῆναι δοκεῖ αὐτόν.", "st": "25.2"}, {"sp": "N", "t": "<em>Ἄλλος.<\/em> νὴ Δία, μαστιγωθέντα γε πρότερον.", "st": "25.2"}, {"sp": "N", "t": "<em>Ἄλλος.<\/em> πολὺ πρότερον τοὺς ὀφθαλμοὺς ἐκκεκολάφθω.", "st": "25.2"}, {"sp": "N", "t": "<em>Ἄλλος.<\/em> τὴν γλῶτταν αὐτὴν ἔτι πολὺ πρότερον ἀποτετμήσθω.", "st": "25.2"}, {"sp": "N", "t": "<em>Σωκράτης.<\/em> σοὶ δὲ τί, Ἐμπεδόκλεις, δοκεῖ;", "st": "25.2"}, {"sp": "N", "t": "<em>Ἐμπεδοκλῆς.<\/em> εἰς τοὺς κρατῆρας ἐμπεσεῖν αὐτόν, ὡς μάθῃ μὴ λοιδορεῖσθαι τοῖς κρείττοσιν.", "st": "25.2"}, {"sp": "N", "t": "<em>Πλάτων.<\/em> καὶ μὴν ἄριστον ἦν καθάπερ τινὰ Πενθέα ἢ Ὀρφέα<br>λακιστὸν ἐν πέτραισιν εὑρέσθαι μόρον,<br>ἵνα ἂν καὶ τὸ μέρος αὐτοῦ ἕκαστος ἔχων ἀπηλλάττετο.", "st": "25.2"}, {"sp": "N", "t": "<em>Παρρησιάδης.<\/em> μηδαμῶς· ἀλλὰ πρὸς Ἱκεσίου φείσασθέ μου.", "st": "25.3"}, {"sp": "N", "t": "<em>Πλάτων.<\/em> Ἄραρεν· οὐκ ἂν ἀφεθείης ἔτι. ὁρᾷς δὲ δὴ καὶ τὸν Ὅμηρον ἅ φησιν,<br>ὡς οὐκ ἔστι λέουσι καὶ ἀνδράσιν ὅρκια πιστά.", "st": "25.3"}, {"sp": "N", "t": "<em>Παρρησιάδης.<\/em> καὶ μὴν καθ’ Ὅμηρον ὑμᾶς καὶ αὐτὸς ἱκετεύσω· αἰδέσεσθε γὰρ ἴσως τὰ ἔπη καὶ οὐ παρόψεσθε ῥαψῳδήσαντά με·<br>ζωγρεῖτ’ οὐ κακὸν ἄνδρα καὶ ἄξια δέχθε ἄποινα,<br>χαλκόν τε χρυσόν τε, τὰ δὴ φιλέουσι σοφοί περ.", "st": "25.3"}, {"sp": "N", "t": "<em>Πλάτων.<\/em> ἀλλ’ οὐδὲ ἡμεῖς ἀπορήσομεν πρὸς σὲ Ὁμηρικῆς ἀντιλογίας. ἄκουε γοῦν·<br>μὴ δή μοι φύξιν γε, κακηγόρε, βάλλεο θυμῷ<br>χρυσόν περ λέξας, ἐπεὶ ἵκεο χεῖρας ἐς ἀμάς.", "st": "25.3"}, {"sp": "N", "t": "<em>Παρρησιάδης.<\/em> οἴμοι τῶν κακῶν. ὁ μὲν Ὅμηρος ἡμῖν ἄπρακτος, ἡ μεγίστη ἐλπίς. ἐπὶ τὸν Εὐριπίδην δή μοι καταφευκτέον· τάχα γὰρ ἂν ἐκεῖνος σώσειέ με.<br>μὴ κτεῖνε· τὸν ἱκέτην γὰρ οὐ θέμις κτανεῖν.", "st": "25.3"}, {"sp": "N", "t": "<em>Πλάτων.<\/em> τί δέ; οὐχὶ κἀκεῖνα Εὐριπίδου ἐστίν,<br>οὐ δεινὰ πάσχειν δεινὰ τοὺς εἰργασμένους;", "st": "25.3"}, {"sp": "N", "t": "<em>Παρρησιάδης.<\/em> νῦν οὖν ἕκατι ῥημάτων κτενεῖτέ με;", "st": "25.3"}, {"sp": "N", "t": "<em>Πλάτων.<\/em> νὴ Δία· φησὶ γοῦν ἐκεῖνος αὐτός,<br>ἀχαλίνων στομάτων<br>ἀνόμου τ’ ἀφροσύνας<br>τὸ τέλος δυστυχία.", "st": "25.3"}, {"sp": "N", "t": "<em>Παρρησιάδης.<\/em> οὐκοῦν ἐπεὶ δέδοκται πάντως ἀποκτιννύναι καὶ οὐδεμία μηχανὴ τὸ διαφυγεῖν με, φέρε τοῦτο γοῦν εἴπατέ μοι, τίνες ὄντες ἢ τί πεπονθότες ἀνήκεστον πρὸς ἡμῶν ἀμείλικτα ὀργίζεσθε καὶ ἐπὶ θανάτῳ συνειλήφατε;", "st": "25.4"}, {"sp": "N", "t": "<em>Πλάτων.<\/em> ἅτινα μὲν εἴργασαι ἡμᾶς τὰ δεινά, σεαυτὸν ἐρώτα, ὦ κάκιστε, καὶ τοὺς καλοὺς ἐκείνους σου λόγους ἐν οἷς φιλοσοφίαν τε αὐτὴν κακῶς ἠγόρευες καὶ εἰς ἡμᾶς ὕβριζες, ὥσπερ ἐξ ἀγορᾶς ἀποκηρύττων σοφοὺς ἄνδρας, καὶ τὸ μέγιστον, ἐλευθέρους· ἐφ’ οἷς ἀγανακτήσαντες ἀνεληλύθαμεν ἐπὶ σὲ παραιτησάμενοι πρὸς ὀλίγον τὸν Ἀϊδωνέα, Χρύσιππος οὑτοσὶ καὶ Ἐπίκουρος καὶ ὁ Πλάτων ἐγὼ καὶ Ἀριστοτέλης ἐκεῖνος καὶ ὁ σιωπῶν οὗτος Πυθαγόρας καὶ Διογένης καὶ ἅπαντες ὁπόσους διέσυρες ἐν τοῖς λόγοις.", "st": "25.4"}, {"sp": "N", "t": "<em>Παρρησιάδης.<\/em> ἀνέπνευσα· οὐ γὰρ ἀποκτενεῖτέ με, ἢν μάθητε ὁποῖος ἐγὼ περὶ ὑμᾶς ἐγενόμην· ὥστε ἀπορρίψατε τοὺς λίθους, μᾶλλον δὲ φυλάττετε. χρήσεσθε γὰρ αὐτοῖς κατὰ τῶν ἀξίων.", "st": "25.5"}, {"sp": "N", "t": "<em>Πλάτων.<\/em> ληρεῖς. σὲ δὲ χρὴ τήμερον ἀπολωλέναι, καὶ ἤδη γε<br>λάϊνον ἕσσο χιτῶνα κακῶν ἕνεχ’ ὅσσα ἔοργας.", "st": "25.5"}, {"sp": "N", "t": "<em>Παρρησιάδης.<\/em> καὶ μήν, Ὢ ἄριστοι, ὃν ἐχρῆν μόνον ἐξ ἁπάντων ἐπαινεῖν οἰκεῖόν τε ὑμῖν ὄντα καὶ εὔνουν καὶ ὁμογνώμονα καί, εἰ μὴ φορτικὸν εἰπεῖν, κηδεμόνα τῶν ἐπιτηδευμάτων εὖ ἴστε ἀποκτενοῦντες, ἢν ἐμὲ ἀποκτείνητε τοσαῦτα ὑπὲρ ὑμῶν πεπονηκότα. ὁρᾶτε οὖν μὴ κατὰ τοὺς πολλοὺς τῶν νῦν φιλοσόφων αὐτοὶ ποιεῖτε, ἀχάριστοι καὶ ὀργίλοι καὶ ἀγνώμονες φαινόμενοι πρὸς ἄνδρα εὐεργέτην.", "st": "25.5"}, {"sp": "N", "t": "<em>Πλάτων.<\/em> Ὢ τῆς ἀναισχυντίας. καὶ χάριν σοι τῆς κακηγορίας προσοφείλομεν; οὕτως ἀνδραπόδοις ὡς ἀληθῶς οἴει διαλέγεσθαι; ἢ καὶ εὐεργεσίαν καταλογιῇ πρὸς ἡμᾶς ἐπὶ τῇ τοσαύτῃ ὕβρει καὶ παροινίᾳ τῶν λόγων;", "st": "25.5"}, {"sp": "N", "t": "<em>Παρρησιάδης.<\/em> ποῦ γὰρ ἐγὼ ὑμᾶς ἢ πότε ὕβρικα, ὃς ἀεὶ φιλοσοφίαν τε θαυμάζων διατετέλεκα καὶ ὑμᾶς αὐτοὺς ὑπερεπαινῶν καὶ τοῖς λόγοις οἷς καταλελοίπατε ὁμιλῶν; αὐτὰ γοῦν ἅ φημι ταῦτα, πόθεν ἄλλοθεν ἢ παρ’ ὑμῶν λαβὼν καὶ κατὰ τὴν μέλιτταν ἀπανθισάμενος ἐπιδείκνυμαι τοῖς ἀνθρώποις; οἱ δὲ ἐπαινοῦσι καὶ γνωρίζουσιν ἕκαστον τὸ ἄνθος ὅθεν καὶ παρ’ ὅτου καὶ ὅπως ἀνελεξάμην, καὶ λόγῳ μὲν ἐμὲ ζηλοῦσι τῆς ἀνθολογίας, τὸ δ’ ἀληθὲς ὑμᾶς καὶ τὸν λειμῶνα τὸν ὑμέτερον, οἳ τοιαῦτα ἐξηνθήκατε ποικίλα καὶ πολυειδῆ τὰς βαφάς, εἴ τις ἀναλέξασθαί τε αὐτὰ ἐπίσταιτο καὶ ἀναπλέξαι καὶ ἁρμόσαι, ὡς μὴ ἀπᾴδειν θάτερον θατέρου. ἔσθ’ ὅστις οὖν ταῦτα εὖ πεπονθὼς παρ’ ὑμῶν κακῶς ἂν εἰπεῖν ἐπιχειρήσειεν εὐεργέτας ἄνδρας, ἀφ’ ὧν εἶναί τις ἔδοξεν; ἐκτὸς εἰ μὴ κατὰ τὸν Θάμυριν ἢ τὸν Εὔρυτον εἴη τὴν φύσιν, ὡς ταῖς Μούσαις ἀντᾴδειν, παρ’ ὧν εἴληφε τὴν ᾠδήν, ἢ τῷ Ἀπόλλωνι ἐριδαίνειν ἐναντία τοξεύων, καὶ ταῦτα δοτῆρι ὄντι τῆς τοξικῆς.", "st": "25.6"}, {"sp": "N", "t": "<em>Πλάτων.<\/em> τοῦτο μέν, ὦ γενναῖε, κατὰ τοὺς ῥήτορας εἴρηταί σοι· ἐναντιώτατον δ’ οὖν ἐστι τῷ πράγματι καὶ χαλεπωτέραν σου ἐπιδείκνυσι τὴν τόλμαν, εἴ γε τῇ ἀδικίᾳ καὶ ἀχαριστία πρόσεστιν, ὃς παρ’ ἡμῶν τὰ τοξεύματα, ὡς φής, λαβὼν καθ’ ἡμῶν ἐτόξευες, ἕνα τοῦτον ὑποθέμενος τὸν σκοπόν, ἅπαντας ἡμᾶς ἀγορεύειν κακῶς· τοιαῦτα παρὰ σοῦ ἀπειλήφαμεν ἀνθ’ ὧν σοι τὸν λειμῶνα ἐκεῖνον ἀναπετάσαντες οὐκ ἐκωλύομεν δρέπεσθαι καὶ τὸ προκόλπιον ἐμπλησάμενον ἀπελθεῖν· ὥστε διά γε τοῦτο μάλιστα δίκαιος ἂν εἴης ἀποθανεῖν.", "st": "25.7"}, {"sp": "N", "t": "<em>Παρρησιάδης.<\/em> ὁρᾶτε· πρὸς ὀργὴν ἀκούετε καὶ οὐδὲν τῶν δικαίων προσίεσθε. καίτοι οὐκ ἂν ᾠήθην ποτὲ ὡς ὀργὴ Πλάτωνος ἢ Χρυσίππου ἢ Ἀριστοτέλους ἢ τῶν ἄλλων ὑμῶν καθίκοιτο ἄν, ἀλλά μοι ἐδοκεῖτε μόνοι δὴ πόρρω εἶναι τοῦ τοιούτου. πλὴν ἀλλὰ μὴ ἄκριτόν γε, ὦ θαυμάσιοι, μηδὲ πρὸ δίκης ἀποκτείνητέ με. ὑμέτερον γοῦν καὶ τοῦτο ἦν, μὴ βίᾳ μηδὲ κατὰ τὸ ἰσχυρότερον πολιτεύεσθαι, δίκῃ δὲ τὰ διάφορα λύεσθαι διδόντας λόγον καὶ δεχομένους ἐν τῷ μέρει. ὥστε δικαστὴν ἑλόμενοι κατηγορήσατε μὲν ὑμεῖς ἢ ἅμα πάντες ἢ ὅντινα ἂν χειροτονήσητε ὑπὲρ ἁπάντων, ἐγὼ δὲ ἀπολογήσομαι πρὸς τὰ ἐγκλήματα. κᾆτα ἢν μέν τι ἀδικῶν φαίνωμαι καὶ τοῦτο περὶ ἐμοῦ γνῷ τὸ δικαστήριον, ὑφέξω δηλαδὴ τὴν ἀξίαν· ὑμεῖς δὲ βίαιον οὐδὲν τολμήσετε· ἢν δὲ τὰς εὐθύνας ὑποσχὼν καθαρὸς ὑμῖν καὶ ἀνεπίληπτος εὑρίσκωμαι, ἀφήσουσί με οἱ δικασταί, ὑμεῖς δὲ εἰς τοὺς ἐξαπατήσαντας ὑμᾶς καὶ παροξύναντας καθ’ ἡμῶν τὴν ὀργὴν τρέψετε.", "st": "25.8"}, {"sp": "N", "t": "<em>Πλάτων.<\/em> τοῦτ’ ἐκεῖνο· εἰς πεδίον τὸν ἵππον, ὡς παρακρουσάμενος τοὺς δικαστὰς ἀπέλθῃς. φασὶ γοῦν ῥήτορά σε καὶ δικανικόν τινα εἶναι καὶ πανοῦργον ἐν τοῖς λόγοις. τίνα δὲ καὶ δικαστὴν ἐθέλεις γενέσθαι, ὅντινα μὴ σὺ δωροδοκήσας, οἷα πολλὰ ποιεῖτε, ἄδικα πείσεις ὑπὲρ σοῦ ψηφίσασθαι;", "st": "25.9"}, {"sp": "N", "t": "<em>Παρρησιάδης.<\/em> θαρρεῖτε τούτου γε ἕνεκα· οὐδένα τοιοῦτον διαιτητὴν ὕποπτον ἢ ἀμφίβολον ἀξιώσαιμ’ ἂν γενέσθαι καὶ ὅστις ἀποδώσεταί μοι τὴν ψῆφον. ὁρᾶτε γοῦν, τὴν Φιλοσοφίαν αὐτὴν μεθ’ ὑμῶν ποιοῦμαι δικάστριαν ἔγωγε.", "st": "25.9"}, {"sp": "N", "t": "<em>Πλάτων.<\/em> καὶ τίς ἂν κατηγορήσειεν, εἴ γε ἡμεῖς δικάσομεν;", "st": "25.9"}, {"sp": "N", "t": "<em>Παρρησιάδης.<\/em> οἱ αὐτοὶ κατηγορεῖτε καὶ δικάζετε· οὐδὲν οὐδὲ τοῦτο δέδια. τοσοῦτον ὑπερφέρω τοῖς δικαίοις καὶ ἐκ περιουσίας ἀπολογήσεσθαι ὑπολαμβάνω.", "st": "25.9"}, {"sp": "N", "t": "<em>Πλάτων.<\/em> τί ποιοῦμεν, ὦ Πυθαγόρα καὶ Σώκρατες; ἔοικε γὰρ ἁνὴρ οὐκ ἄλογα προκαλεῖσθαι δικάζεσθαι ἀξιῶν.", "st": "25.10"}, {"sp": "N", "t": "<em>Σωκράτης.<\/em> τί δὲ ἄλλο ἢ βαδίζωμεν ἐπὶ τὸ δικαστήριον καὶ τὴν Φιλοσοφίαν παραλαβόντες ἀκούσωμεν ὅ τι καὶ ἀπολογήσεται· τὸ πρὸ δίκης γὰρ οὐχ ἡμέτερον, ἀλλὰ δεινῶς ἰδιωτικόν, ὀργίλων τινῶν ἀνθρώπων καὶ τὸ δίκαιον ἐν τῇ χειρὶ τιθεμένων. παρέξομεν οὖν ἀφορμὰς τοῖς κακηγορεῖν ἐθέλουσιν καταλεύσαντες ἄνδρα μηδὲ ἀπολογησάμενον ὑπὲρ ἑαυτοῦ, καὶ ταῦτα δικαιοσύνῃ χαίρειν αὐτοὶ λέγοντες. ἢ τί ἂν εἴποιμεν Ἀνύτον καὶ Μελήτου πέρι, τῶν ἐμοῦ κατηγορησάντων, ἢ τῶν τότε δικαστῶν, εἰ οὗτος τεθνήξεται μηδὲ τὸ παράπαν ὕδατος μεταλαβών;", "st": "25.10"}, {"sp": "N", "t": "<em>Πλάτων.<\/em> ἄριστα παραινεῖς, ὦ Σώκρατες· ὥστε ἀπίωμεν ἐπὶ τὴν Φιλοσοφίαν. ἡ δὲ δικασάτω, καὶ ἡμεῖς ἀγαπήσομεν οἷς ἂν ἐκείνη διαγνῷ.", "st": "25.10"}, {"sp": "N", "t": "<em>Παρρησιάδης.<\/em> εὖ γε, ὦ σοφώτατοι, ἀμείνω ταῦτα καὶ νομιμώτερα. τοὺς μέντοι λίθους φυλάττετε, ὡς ἔφην· δεήσει γὰρ αὐτῶν μικρὸν ὕστερον ἐν τῷ δικαστηρίῳ.", "st": "25.11"}, {"sp": "N", "t": "ποῦ δὲ τὴν Φιλοσοφίαν εὕροι τις ἄν; οὐ γὰρ οἶδα ἔνθα οἰκεῖ· καίτοι πάνυ πολὺν ἐπλανήθην χρόνον ἀναζητῶν τὴν οἰκίαν, ὡς συγγενοίμην αὐτῇ. εἶτα ἐντυγχάνων ἄν τισι τριβώνια περιβεβλημένοις καὶ πώγωνας βαθεῖς καθειμένοις παρ’ αὐτῆς ἐκείνης ἥκειν φάσκουσιν, οἰόμενος εἰδέναι αὐτοὺς ἀνηρώτων· οἱ δὲ πολὺ μᾶλλον ἐμοῦ ἀγνοοῦντες ἢ οὐδὲν ὅλως ἀπεκρίναντό μοι, ὡς μὴ ἐλέγχοιντο οὐκ εἰδότες, ἢ ἄλλην θύραν ἀντ’ ἄλλης ἐπεδείκνυον. οὐδέπω γοῦν καὶ τήμερον ἐξευρεῖν δεδύνημαι τὴν οἰκίαν.", "st": "25.11"}, {"sp": "N", "t": "πολλάκις δὲ ἢ αὐτὸς εἰκάσας ἢ ξεναγήσαντός τινος ἧκον ἂν ἐπί τινας θύρας βεβαίως ἐλπίσας τότε γοῦν εὑρηκέναι, τεκμαιρόμενος τῷ πλήθει τῶν εἰσιόντων τε καὶ ἐξιόντων, ἁπάντων σκυθρωπῶν καὶ τὰ σχήματα εὐσταλῶν καὶ φροντιστικῶν τὴν πρόσοψιν· μετὰ τούτων οὖν συμπαραβυσθεὶς καὶ αὐτὸς εἰσῆλθον ἄν. εἶτα ἑώρων γύναιόν τι οὐχ ἁπλοϊκόν, εἰ καὶ ὅτι μάλιστα εἰς τὸ ἀφελὲς καὶ ἀκόσμητον ἑαυτὴν ἐπερρύθμιζεν, ἀλλὰ κατεφάνη μοι αὐτίκα οὐδὲ τὸ ἄνετον δοκοῦν τῆς κόμης ἀκαλλώπιστον ἐῶσα οὐδὲ τοῦ ἱματίου τὴν ἀναβολὴν ἀνεπιτηδεύτως περιστέλλουσα· πρόδηλος δὲ ἦν κοσμουμένη αὐτοῖς καὶ πρὸς εὐπρέπειαν τῷ ἀθεραπεύτῳ δοκοῦντι προσχρωμένη. ὑπεφαίνετο δέ τι καὶ ψιμύθιον καὶ φῦκος, καὶ τὰ ῥήματα πάνυ ἑταιρικά, καὶ ἐπαινουμένη ὑπὸ τῶν ἐραστῶν εἰς κάλλος ἔχαιρε, καὶ εἰ δοίη τις προχείρως ἐδέχετο, καὶ τοὺς πλουσιωτέρους ἂν παρακαθισαμένη πλησίον τοὺς πένητας τῶν ἐραστῶν οὐδὲ προσέβλεπεν. πολλάκις δὲ καὶ γυμνωθείσης αὐτῆς κατὰ τὸ ἀκούσιον ἑώρων περιδέραια χρυσᾶ τῶν κλοιῶν παχύτερα. ταῦτα ἰδὼν ἐπὶ πόδα ἂν εὐθὺς ἀνέστρεφον, οἰκτείρας δηλαδὴ τοὺς κακοδαίμονας ἐκείνους ἑλκομένους πρὸς αὐτῆς οὐ τῆς ῥινὸς ἀλλὰ τοῦ πώγωνος καὶ κατὰ τὸν Ἰξίονα εἰδώλῳ ἀντὶ τῆς Ἥρας συνόντας.", "st": "25.12"}, {"sp": "N", "t": "<em>Πλάτων.<\/em> τοῦτο μὲν ὀρθῶς ἔλεξας· οὐ γὰρ πρόδηλος οὐδὲ πᾶσι γνώριμος ἡ θύρα. πλὴν ἀλλὰ οὐδὲν δεήσει βαδίζειν ἐπὶ τὴν οἰκίαν· ἐνταῦθα γὰρ ἐν Κεραμεικῷ ὑπομενοῦμεν αὐτήν. ἡ δὲ ἤδη που ἀφίξεται ἐπανιοῦσα ἐξ Ἀκαδημίας, ὡς περιπατήσειε καὶ ἐν τῇ Ποικίλῃ· τοῦτο γὰρ ὁσημέραι ποιεῖν ἔθος αὐτῇ· μᾶλλον δὲ ἤδη πρόσεισιν. ὁρᾷς τὴν κόσμιον, τὴν ἀπὸ τοῦ σχήματος, τὴν προσηνῆ τὸ βλέμμα, τὴν ἐπὶ συννοίας ἠρέμα βαδίζουσαν;", "st": "25.13"}, {"sp": "N", "t": "<em>Παρρησιάδης.<\/em> πολλὰς ὁμοίας ὁρῶ τό γε σχῆμα καὶ τὸ βάδισμα καὶ τὴν ἀναβολήν. καίτοι μία πάντως ἥ γε ἀληθὴς Φιλοσοφία καὶ ἐν αὐταῖς.", "st": "25.13"}, {"sp": "N", "t": "<em>Πλάτων.<\/em> εὖ λέγεις. ἀλλὰ δηλώσει ἥτις ἐστὶ φθεγξαμένη μόνον.", "st": "25.13"}, {"sp": "N", "t": "<em>Φιλοσοφία.<\/em> παπαῖ· τί Πλάτων καὶ Χρύσιππος ἄνω καὶ Ἀριστοτέλης καὶ οἱ λοιποὶ ἅπαντες, αὐτὰ δὴ τὰ κεφάλαιά μου τῶν μαθημάτων; τί αὖθις εἰς τὸν βίον; ἆρά τι ὑμᾶς ἐλύπει τῶν κάτω; ὀργιζομένοις γοῦν ἐοίκατε. καὶ τίνα τοῦτον συλλαβόντες ἄγετε; ἦ που τυμβωρύχος τις ἢ ἀνδροφόνος ἢ ἱερόσυλός ἐστιν;", "st": "25.14"}, {"sp": "N", "t": "<em>Πλάτων.<\/em> νὴ Δία, ὦ Φιλοσοφία, πάντων γε ἱεροσύλων ἀσεβέστατος, ὃς τὴν ἱερωτάτην σὲ κακῶς ἀγορεύειν ἐπεχείρησεν καὶ ἡμᾶς ἅπαντας, ὁπόσοι τι παρὰ σοῦ μαθόντες τοῖς μεθ’ ἡμᾶς καταλελοίπαμεν.", "st": "25.14"}, {"sp": "N", "t": "<em>Φιλοσοφία.<\/em> εἶτα ἠγανακτήσατε λοιδορησαμένου τινός, καὶ ταῦτα εἰδότες ἐμέ, οἷα πρὸς τῆς Κωμῳδίας ἀκούουσα ἐν Διονυσίοις ὅμως φίλην τε αὐτὴν ἥγημαι καὶ οὔτε ἐδικασάμην οὔτε ᾐτιασάμην προσελθοῦσα, ἐφίημι δὲ παίζειν τὰ εἰκότα καὶ τὰ συνήθη τῇ ἑορτῇ; οἶδα γὰρ ὡς οὐκ ἄν τι ὑπὸ σκώμματος χεῖρον γένοιτο, ἀλλὰ τοὐναντίον ὅπερ ἂν ᾖ καλόν, ὥσπερ τὸ χρυσίον ἀποσμώμενον τοῖς κόμμασι, λαμπρότερον ἀποστίλβει καὶ φανερώτερον γίγνεται. ὑμεῖς δὲ οὐκ οἶδα ὅπως ὀργίλοι καὶ ἀγανακτικοὶ γεγόνατε. τί δ’ οὖν αὐτὸν ἄγχετε;", "st": "25.14"}, {"sp": "N", "t": "<em>Πλάτων.<\/em> μίαν ἡμέραν ταύτην παραιτησάμενοι ἥκομεν ἐπ’ αὐτὸν ὡς ὑπόσχῃ τὴν ἀξίαν ὧν δέδρακεν. φῆμαι γὰρ ἡμῖν διήγγελλον οἷα ἔλεγεν εἰς τὰ πλήθη καθ’ ἡμῶν.", "st": "25.14"}, {"sp": "N", "t": "<em>Φιλοσοφία.<\/em> εἶτα πρὸ δίκης οὐδὲ ἀπολογησάμενον ἀποκτενεῖτε; δῆλος γοῦν ἐστιν εἰπεῖν τι θέλων.", "st": "25.15"}, {"sp": "N", "t": "<em>Πλάτων.<\/em> οὔκ, ἀλλ’ ἐπὶ σὲ τὸ πᾶν ἀνεβαλόμεθα, καὶ σοὶ ὅτι ἂν δοκῇ, τοῦτο ποιήσῃ τέλος τῆς δίκης.", "st": "25.15"}, {"sp": "N", "t": "<em>Φιλοσοφία.<\/em> τί φὴς σύ;", "st": "25.15"}, {"sp": "N", "t": "<em>Παρρησιάδης.<\/em> τοῦτο αὐτό, ὦ δέσποινα Φιλοσοφία, ἥπερ καὶ μόνη τἀληθὲς ἂν ἐξευρεῖν δύναιο· μόλις γοῦν εὑρόμην πολλὰ ἱκετεύσας τὸ σοὶ φυλαχθῆναι τὴν δίκην.", "st": "25.15"}, {"sp": "N", "t": "<em>Πλάτων.<\/em> νῦν, ὦ κατάρατε, δέσποιναν αὐτὴν καλεῖς; πρῴην δὲ τὸ ἀτιμότατον Φιλοσοφίαν ἀπέφαινες ἐν τοσούτῳ θεάτρῳ ἀποκηρύττων κατὰ μέρη δύ’ ὀβολῶν ἕκαστον εἶδος αὐτῆς τῶν λόγων.", "st": "25.15"}, {"sp": "N", "t": "<em>Φιλοσοφία.<\/em> ὁρᾶτε μὴ οὐ Φιλοσοφίαν οὗτός γε ἀλλὰ γόητας ἄνδρας ἐπὶ τῷ ἡμετέρῳ ὀνόματι πολλὰ καὶ μιαρὰ πράττοντας ἠγόρευεν κακῶς.", "st": "25.15"}, {"sp": "N", "t": "<em>Παρρησιάδης.<\/em> εἴσῃ αὐτίκα, ἢν ἐθέλῃς ἀπολογουμένου ἀκούειν μόνον.", "st": "25.15"}, {"sp": "N", "t": "<em>Φιλοσοφία.<\/em> ἀπίωμεν εἰς Ἄρειον πάγον, μᾶλλον δὲ εἰς τὴν ἀκρόπολιν αὐτήν, ὡς ἂν ἐκ περιωπῆς ἅμα καταφανείη πάντα ἐν τῇ πόλει.", "st": "25.15"}, {"sp": "N", "t": "ὑμεῖς δέ, ὦ φίλαι, ἐν τῇ Ποικίλῃ τέως περιπατήσατε· ἥξω γὰρ ὑμῖν ἐκδικάσασα τὴν δίκην.", "st": "25.16"}, {"sp": "N", "t": "<em>Παρρησιάδης.<\/em> τίνες δέ εἰσιν, ὦ Φιλοσοφία; πάνυ γάρ μοι κόσμιαι καὶ αὗται δοκοῦσιν.", "st": "25.16"}, {"sp": "N", "t": "<em>Φιλοσοφία.<\/em> ἀρετὴ μὲν ἡ ἀνδρώδης αὕτη, Σωφροσύνη δὲ ἐκείνη καὶ Δικαιοσύνη ἡ παρ’ αὐτήν. ἡ προηγουμένη δὲ Παιδεία, ἡ ἀμυδρὰ δὲ καὶ ἀσαφὴς τὸ χρῶμα ἡ Ἀλήθειά ἐστιν.", "st": "25.16"}, {"sp": "N", "t": "<em>Παρρησιάδης.<\/em> οὐχ ὁρῶ ἥντινα καὶ λέγεις.", "st": "25.16"}, {"sp": "N", "t": "<em>Φιλοσοφία.<\/em> τὴν ἀκαλλώπιστον ἐκείνην οὐχ ὁρᾷς, τὴν γυμνήν, τὴν ὑποφεύγουσαν ἀεὶ καὶ διολισθάνουσαν;", "st": "25.16"}, {"sp": "N", "t": "<em>Παρρησιάδης.<\/em> ὁρῶ νῦν μόλις. ἀλλὰ τί οὐχὶ καὶ ταύτας ἄγεις, ὡς πλῆρες γένοιτο καὶ ἐντελὲς τὸ συνέδριον; τὴν Ἀλήθειαν δέ γε καὶ συνήγορον ἀναβιβάσασθαι πρὸς τὴν δίκην βούλομαι.", "st": "25.16"}, {"sp": "N", "t": "<em>Φιλοσοφία.<\/em> νὴ Δία, ἀκολουθήσατε καὶ ὑμεῖς· οὐ βαρὺ γὰρ μίαν δικάσαι δίκην, καὶ ταῦτα περὶ τῶν ἡμετέρων ἐσομένην.", "st": "25.16"}, {"sp": "N", "t": "<em>Ἀλήθεια.<\/em> ἄπιτε ὑμεῖς· ἐγὼ γὰρ οὐδὲν δέομαι ἀκούειν ἃ πάλαι οἶδα ὁποῖά ἐστιν.", "st": "25.17"}, {"sp": "N", "t": "<em>Φιλοσοφία.<\/em> ἀλλ’ ἡμῖν, ὦ Ἀλήθεια, ἐν δέοντι συνδικάζοις ἂν καὶ καταμηνύοις ἕκαστα.", "st": "25.17"}, {"sp": "N", "t": "<em>Ἀλήθεια.<\/em> οὐκοῦν ἐπάγωμαι καὶ τὼ θεραπαινιδίω τούτω εὐνοϊκοτάτω μοι ὄντε;", "st": "25.17"}, {"sp": "N", "t": "<em>Φιλοσοφία.<\/em> καὶ μάλα ὁπόσας ἂν ἐθέλῃς.", "st": "25.17"}, {"sp": "N", "t": "<em>Ἀλήθεια.<\/em> ἕπεσθον, ὦ Ἐλευθερία καὶ Παρρησία, μεθ’ ἡμῶν, ὡς τὸν δείλαιον τουτονὶ ἀνθρωπίσκον ἐραστὴν ἡμέτερον ὄντα καὶ κινδυνεύοντα ἐπὶ μηδεμιᾷ προφάσει δικαίᾳ σῶσαι δυνηθῶμεν. σὺ δέ, ὦ Ἔλεγχε, αὐτοῦ περίμεινον.", "st": "25.17"}, {"sp": "N", "t": "<em>Παρρησιάδης.<\/em> μηδαμῶς, ὦ δέσποινα, ἡκέτω δὲ καὶ οὗτος, εἰ καί τις ἄλλος· οὐ γὰρ τοῖς τυχοῦσι θηρίοις προσπολεμῆσαι δεήσει με, ἀλλ’ ἀλαζόσιν ἀνθρώποις καὶ δυσελέγκτοις, ἀεί τινας ἀποφυγὰς εὑρισκομένοις, ὥστε ἀναγκαῖος ὁ Ἔλεγχος.", "st": "25.17"}, {"sp": "N", "t": "<em>Ἔλεγχος.<\/em> ἀναγκαιότατος μὲν οὖν· ἄμεινον δέ, εἰ καὶ τὴν Ἀπόδειξιν παραλάβοις.", "st": "25.17"}, {"sp": "N", "t": "<em>Ἀλήθεια.<\/em> ἕπεσθε πάντες, ἐπείπερ ἀναγκαῖοι δοκεῖτε πρὸς τὴν δίκην.", "st": "25.17"}, {"sp": "N", "t": "<em>Πλάτων.<\/em> ὁρᾷς; προσεταιρίζεται καθ’ ἡμῶν, ὦ Φιλοσοφία, τὴν Ἀλήθειαν.", "st": "25.18"}, {"sp": "N", "t": "<em>Φιλοσοφία.<\/em> εἶτα δέδιτε, ὦ Πλάτων καὶ Χρύσιππε καὶ Ἀριστότελες, μή τι ψεύσηται ὑπὲρ αὐτοῦ Ἀλήθεια οὖσα;", "st": "25.18"}, {"sp": "N", "t": "<em>Πλάτων.<\/em> οὐ τοῦτο, ἀλλὰ δεινῶς πανοῦργός ἐστιν καὶ κολακικός· ὥστε παραπείσει αὐτήν.", "st": "25.18"}, {"sp": "N", "t": "<em>Φιλοσοφία.<\/em> θαρρεῖτε· οὐδὲν μὴ γένηται ἄδικον, Δικαιοσύνης ταύτης συμπαρούσης.", "st": "25.18"}, {"sp": "N", "t": "ἀνίωμεν οὖν. ἀλλὰ εἰπέ μοι σύ, τί σοι τοὔνομα;", "st": "25.19"}, {"sp": "N", "t": "<em>Παρρησιάδης.<\/em> ἐμοί; Παρρησιάδης Ἀληθίωνος τοῦ Ἐλεγξικλέους.", "st": "25.19"}, {"sp": "N", "t": "<em>Φιλοσοφία.<\/em> πατρὶς δέ;", "st": "25.19"}, {"sp": "N", "t": "<em>Παρρησιάδης.<\/em> Σύρος, ὦ Φιλοσοφία, τῶν Ἐπευφρατιδίων. ἀλλὰ τί τοῦτο; καὶ γὰρ τούτων τινὰς οἶδα τῶν ἀντιδίκων μου οὐχ ἧττον ἐμοῦ βαρβάρους τὸ γένος· ὁ τρόπος δὲ καὶ ἡ παιδεία οὐ κατὰ Σολέας ἢ Κυπρίους ἢ Βαβυλωνίους ἢ Σταγειρίτας. καίτοι πρός γε σὲ οὐδὲν ἂν ἔλαττον γένοιτο οὐδ’ εἰ τὴν φωνὴν βάρβαρος εἴη τις, εἴπερ ἡ γνώμη ὀρθὴ καὶ δικαία φαίνοιτο οὖσα.", "st": "25.19"}, {"sp": "N", "t": "<em>Φιλοσοφία.<\/em> εὖ λέγεις· ἄλλως γοῦν ἠρόμην. ἡ τέχνη δέ σοι τίς; ἄξιον γὰρ ἐπίστασθαι τοῦτό γε.", "st": "25.20"}, {"sp": "N", "t": "<em>Παρρησιάδης.<\/em> μισαλαζών εἰμι καὶ μισογόης καὶ μισοψευδὴς καὶ μισότυφος καὶ μισῶ πᾶν τὸ τοιουτῶδες εἶδος τῶν μιαρῶν ἀνθρώπων· πάνυ δὲ πολλοί εἰσιν, ὡς οἶσθα.", "st": "25.20"}, {"sp": "N", "t": "<em>Φιλοσοφία.<\/em> Ἡράκλεις, πολυμισῆ τινα μέτει τὴν τέχνην.", "st": "25.20"}, {"sp": "N", "t": "<em>Παρρησιάδης.<\/em> εὖ λέγεις· ὁρᾷς γοῦν ὁπόσοις ἀπεχθάνομαι καὶ ὡς κινδυνεύω δι’ αὐτήν.", "st": "25.20"}, {"sp": "N", "t": "οὐ μὴν ἀλλὰ καὶ τὴν ἐναντίαν αὐτῇ πάνυ ἀκριβῶς οἶδα, λέγω δὲ τὴν ἀπὸ τοῦ φιλο τὴν ἀρχὴν ἔχουσαν· φιλαλήθης τε γὰρ καὶ φιλόκαλος καὶ φιλαπλοϊκὸς καὶ ὅσα τῷ φιλεῖσθαι συγγενῆ. πλὴν ἀλλ’ ὀλίγοι πάνυ ταύτης ἄξιοι τῆς τέχνης, οἱ δὲ ὑπὸ τῇ ἐναντίᾳ ταττόμενοι καὶ τῷ μίσει οἰκειότεροι πεντακισμύριοι. κινδυνεύω τοιγαροῦν τὴν μὲν ὑπ’ ἀργίας ἀπομαθεῖν ἤδη, τὴν δὲ πάνυ ἠκριβωκέναι.", "st": "25.20"}, {"sp": "N", "t": "<em>Φιλοσοφία.<\/em> καὶ μὴν οὐκ ἐχρῆν· τοῦ γὰρ αὐτοῦ καὶ τάδε, φασί, καὶ τάδε· ὥστε μὴ διαίρει τὼ τέχνα· μία γὰρ ἐστὸν δύ’ εἶναι δοκούσα.", "st": "25.20"}, {"sp": "N", "t": "<em>Παρρησιάδης.<\/em> ἄμεινον σὺ ταῦτα οἶσθα, ὦ Φιλοσοφία. τὸ μέντοι ἐμὸν τοιοῦτόν ἐστιν, οἷον τοὺς μὲν πονηροὺς μισεῖν, ἐπαινεῖν δὲ τοὺς χρηστοὺς καὶ φιλεῖν.", "st": "25.20"}, {"sp": "N", "t": "<em>Φιλοσοφία.<\/em> ἄγε δή, πάρεσμεν γὰρ ἔνθα ἐχρῆν, ἐνταῦθά που ἐν τῷ προνάῳ τῆς Πολιάδος δικάσωμεν. ἡ Ἱέρεια διάθες ἡμῖν τὰ βάθρα, ἡμεῖς δὲ ἐν τοσούτῳ προσκυνήσωμεν τὴν θεόν.", "st": "25.21"}, {"sp": "N", "t": "<em>Παρρησιάδης.<\/em> ὦ Πολιάς, ἐλθέ μοι κατὰ τῶν ἀλαζόνων σύμμαχος ἀναμνησθεῖσα ὁπόσα ἐπιορκούντων ὁσημέραι ἀκούεις αὐτῶν· καὶ ἃ πράττουσι δὲ μόνη ὁρᾷς ἅτε δὴ ἐπὶ σκοπῆς οἰκοῦσα. νῦν καιρὸς ἀμύνασθαι αὐτούς. ἐμὲ δὲ ἤν που κρατούμενον ἴδῃς καὶ πλείους ὦσιν αἱ μέλαιναι, σὺ προσθεῖσα τὴν σεαυτῆς σῶζέ με.", "st": "25.21"}, {"sp": "N", "t": "<em>Φιλοσοφία.<\/em> Εἶεν· ἡμεῖς μὲν ὑμῖν καὶ δὴ καθήμεθα ἕτοιμοι ἀκούειν τῶν λόγων, ὑμεῖς δὲ προελόμενοί τινα ἐξ ἁπάντων, ὅστις ἄριστα κατηγορῆσαι ἂν δοκεῖ, συνείρετε τὴν κατηγορίαν καὶ διελέγχετε· πάντας γὰρ ἅμα λέγειν ἀμήχανον. σὺ δέ, ὦ Παρρησιάδη, ἀπολογήσῃ τὸ μετὰ τοῦτο.", "st": "25.22"}, {"sp": "N", "t": "<em>Πλάτων.<\/em> τίς οὖν ὁ ἐπιτηδειότατος ἐξ ἡμῶν ἂν γένοιτο πρὸς τὴν δίκην;", "st": "25.22"}, {"sp": "N", "t": "<em>Χρύσιππος.<\/em> σύ, ὦ Πλάτων. ἥ τε γὰρ μεγαλόνοια θαυμαστὴ καὶ ἡ καλλιφωνία δεινῶς Ἀττικὴ καὶ τὸ κεχαρισμένον καὶ πειθοῦς μεστὸν ἥ τε σύνεσις καὶ τὸ ἀκριβὲς καὶ τὸ ἐπαγωγὸν ἐν καιρῷ τῶν ἀποδείξεων, πάντα ταῦτά σοι ἀθρόα πρόσεστιν· ὥστε τὴν προηγορίαν δέχου καὶ ὑπὲρ ἁπάντων εἰπὲ τὰ εἰκότα. νῦν ἀναμνήσθητι πάντων ἐκείνων καὶ συμφόρει εἰς τὸ αὐτό, εἴ τί σοι πρὸς Γοργίαν ἢ Πῶλον ἢ Πρόδικον ἢ Ἱππίαν εἴρηται· δεινότερος οὗτός ἐστιν. ἐπίπαττε οὖν καὶ τῆς εἰρωνείας καὶ τὰ κομψὰ ἐκεῖνα καὶ συνεχῆ ἐρώτα, κἄν σοι δοκῇ, κἀκεῖνό που παράβυσον, ὡς “ὁ μέγας ἐν οὐρανῷ Ζεὺς πτηνὸν ἅρμα ἐλαύνων” ἀγανακτήσειεν ἄν, εἰ μὴ οὗτος ὑπόσχοι τὴν δίκην.", "st": "25.22"}, {"sp": "N", "t": "<em>Πλάτων.<\/em> μηδαμῶς, ἀλλά τινα τῶν σφοδροτέρων προχειρισώμεθα, Διογένη τοῦτον ἢ Ἀντισθένη ἢ Κράτητα ἢ καὶ σέ, ὦ Χρύσιππε· οὐ γὰρ δὴ κάλλους ἐν τῷ παρόντι καὶ δεινότητος συγγραφικῆς ὁ καιρός, ἀλλά τινος ἐλεγκτικῆς καὶ δικανικῆς παρασκευῆς· ῥήτωρ δὲ ὁ Παρρησιάδης ἐστίν.", "st": "25.23"}, {"sp": "N", "t": "<em>Διογένης.<\/em> ἀλλ’ ἐγὼ αὐτοῦ κατηγορήσω· οὐδὲ γὰρ πάνυ μακρῶν οἶμαι τῶν λόγων δεήσεσθαι. καὶ ἄλλως ὑπὲρ ἅπαντας ὕβρισμαι δύ’ ὀβολῶν πρῴην ἀποκεκηρυγμένος.", "st": "25.23"}, {"sp": "N", "t": "<em>Πλάτων.<\/em> ὁ Διογένης, ὦ Φιλοσοφία, ἐρεῖ τὸν λόγον ὑπὲρ ἁπάντων. μέμνησο δέ, ὦ γενναῖε, μὴ τὰ σεαυτοῦ μόνον πρεσβεύειν ἐν τῇ κατηγορίᾳ, τὰ κοινὰ δὲ ὁρᾶν· εἰ γάρ τι καὶ πρὸς ἀλλήλους διαφερόμεθα ἐν τοῖς δόγμασι, σὺ δὲ τοῦτο μὲν μὴ ἐξέταζε, μηδὲ ὅστις ἐστὶν ὁ ἀληθέστερος νῦν λέγε, ὅλως δὲ ὑπὲρ Φιλοσοφίας αὐτῆς ἀγανάκτει περιυβρισμένης καὶ κακῶς ἀκουούσης ἐν τοῖς Παρρησιάδου λόγοις, καὶ τὰς προαιρέσεις ἀφείς, ἐν αἷς διαλλάττομεν, ὃ κοινὸν ἅπαντες ἔχομεν, τοῦτο ὑπερμάχει. ὅρα· σὲ μόνον προεστησάμεθα καὶ ἐν σοὶ τὰ πάντα ἡμῶν νῦν κινδυνεύεται, ἢ σεμνότατα δόξαι ἢ τοιαῦτα πιστευθῆναι οἷα οὗτος ἀπέφηνε.", "st": "25.23"}, {"sp": "N", "t": "<em>Διογένης.<\/em> θαρρεῖτε, οὐδὲν ἐλλείψομεν· ὑπὲρ ἁπάντων ἐρῶ. κἂν ἡ Φιλοσοφία δὲ πρὸς τοὺς λόγους ἐπικλασθεῖσα — φύσει γὰρ ἥμερος καὶ πρᾶός ἐστιν — ἀφεῖναι διαβουλεύηται αὐτόν, ἀλλ’ οὐ τὰ ἐμὰ ἐνδεήσει· δείξω γὰρ αὐτῷ ὅτι μὴ μάτην ξυλοφοροῦμεν.", "st": "25.24"}, {"sp": "N", "t": "<em>Φιλοσοφία.<\/em> τοῦτο μὲν μηδαμῶς, ἀλλὰ τῷ λόγῳ μᾶλλον· ἄμεινον γὰρ ἤπερ τῷ ξύλῳ. μὴ μέλλε δ’ οὖν. ἤδη γὰρ ἐγκέχυται τὸ ὕδωρ καὶ πρὸς σὲ τὸ δικαστήριον ἀποβλέπει.", "st": "25.24"}, {"sp": "N", "t": "<em>Παρρησιάδης.<\/em> οἱ λοιποὶ καθιζέτωσαν, ὦ Φιλοσοφία, καὶ ψηφοφορείτωσαν μεθ’ ὑμῶν, Διογένης δὲ κατηγορείτω μόνος.", "st": "25.24"}, {"sp": "N", "t": "<em>Φιλοσοφία.<\/em> οὐ δέδιας οὖν μή σου καταψηφίσωνται;", "st": "25.24"}, {"sp": "N", "t": "<em>Παρρησιάδης.<\/em> οὐδαμῶς· πλείοσι γοῦν κρατῆσαι βούλομαι.", "st": "25.24"}, {"sp": "N", "t": "<em>Φιλοσοφία.<\/em> γενναῖά σου ταῦτα· καθίσατε δ’ οὖν. σὺ δέ, ὦ Διόγενες, λέγε.", "st": "25.24"}, {"sp": "N", "t": "<em>Διογένης.<\/em> οἷοι μὲν ἡμεῖς ἄνδρες ἐγενόμεθα παρὰ τὸν βίον, ὦ Φιλοσοφία, πάνυ ἀκριβῶς οἶσθα καὶ οὐδὲν δεῖ λόγων· ἵνα γὰρ τὸ κατ’ ἐμὲ σιωπήσω, ἀλλὰ Πυθαγόραν τοῦτον καὶ Πλάτωνα καὶ Ἀριστοτέλη καὶ Χρύσιππον καὶ τοὺς ἄλλους τίς οὐκ οἶδεν ὅσα εἰς τὸν βίον καλὰ εἰσεκομίσαντο; ἃ δὲ τοιούτους ὄντας ἡμᾶς ὁ τρισκατάρατος οὑτοσὶ Παρρησιάδης ὕβρικεν ἤδη ἐρῶ.", "st": "25.25"}, {"sp": "N", "t": "ῥήτωρ γάρ τις, ὥς φασιν, ὤν, ἀπολιπὼν τὰ δικαστήρια καὶ τὰς ἐν ἐκείνοις εὐδοκιμήσεις, ὁπόσον ἢ δεινότητος ἢ ἀκμῆς ἐπεπόριστο ἐν τοῖς λόγοις, τοῦτο πᾶν ἐφ’ ἡμᾶς συσκευασάμενος οὐ παύεται αὐτὸς μὲν ἀγορεύων κακῶς γόητας καὶ ἀπατεῶνας ἀποκαλῶν, τὰ πλήθη δὲ ἀναπείθων καταγελᾶν ἡμῶν καὶ καταφρονεῖν ὡς τὸ μηδὲν ὄντων· μᾶλλον δὲ καὶ μισεῖσθαι πρὸς τῶν πολλῶν ἤδη πεποίηκεν αὐτούς τε ἡμᾶς καὶ σὲ τὴν Φιλοσοφίαν, φληνάφους καὶ λήρους ἀποκαλῶν τὰ σὰ καὶ τὰ σπουδαιότατα ὧν ἡμᾶς ἐπαίδευσας ἐπὶ χλευασμῷ διεξιών, ὥστε αὐτὸν μὲν κροτεῖσθαι καὶ ἐπαινεῖσθαι πρὸς τῶν θεατῶν, ἡμᾶς δὲ ὑβρίζεσθαι. φύσει γὰρ τοιοῦτόν ἐστιν ὁ πολὺς λεώς, χαίρουσι τοῖς ἀποσκώπτουσιν καὶ λοιδορουμένοις, καὶ μάλισθ’ ὅταν τὰ σεμνότατα εἶναι δοκοῦντα διασύρηται, ὥσπερ ἀμέλει καὶ πάλαι ἔχαιρον Ἀριστοφάνει καὶ Εὐπόλιδι Σωκράτη τουτονὶ ἐπὶ χλευασίᾳ παράγουσιν ἐπὶ τὴν σκηνὴν καὶ κωμῳδοῦσιν ἀλλοκότους τινὰς περὶ αὐτοῦ κωμῳδίας.", "st": "25.25"}, {"sp": "N", "t": "καίτοι ἐκεῖνοι μὲν καθ’ ἑνὸς ἀνδρὸς ἐτόλμων τοιαῦτα, καὶ ἐν Διονυσίοις ἐφειμένον αὐτὸ ἔδρων, καὶ τὸ σκῶμμα ἐδόκει μέρος τι τῆς ἑορτῆς, καὶ<br>ὁ θεὸς ἴσως ἔχαιρε φιλόγελώς τις ὤν.", "st": "25.25"}, {"sp": "N", "t": "ὁ δὲ τοὺς ἀρίστους συγκαλῶν, ἐκ πολλοῦ φροντίσας καὶ παρασκευασάμενος καὶ βλασφημίας τινὰς εἰς παχὺ βιβλίον ἐγγράψας, μεγάλῃ τῇ φωνῇ ἀγορεύει κακῶς Πλάτωνα, Πυθαγόραν, Ἀριστοτέλη τοῦτον, Χρύσιππον ἐκεῖνον, ἐμὲ καὶ ὅλως ἅπαντας οὔτε ἑορτῆς ἐφιείσης οὔτε ἰδίᾳ τι πρὸς ἡμῶν παθών· εἶχε γὰρ ἄν τινα συγγνώμην αὐτῷ τὸ πρᾶγμα, εἰ ἀμυνόμενος, ἀλλὰ μὴ ἄρχων αὐτὸς ἔδρα.", "st": "25.26"}, {"sp": "N", "t": "ὃ δὲ πάντων δεινότατον, ὅτι τοιαῦτα ποιῶν καὶ τὸ σὸν ὄνομα, ὦ Φιλοσοφία, ὑποδύεται καὶ ὑπελθὼν τὸν Διάλογον ἡμέτερον οἰκέτην ὄντα, τούτῳ συναγωνιστῇ καὶ ὑποκριτῇ χρῆται καθ’ ἡμῶν, ἔτι καὶ Μένιππον ἀναπείσας ἑταῖρον ἡμῶν ἄνδρα συγκωμῳδεῖν αὐτῷ τὰ πολλά, ὃς μόνος οὐ πάρεστιν οὐδὲ κατηγορεῖ μεθ’ ἡμῶν, προδοὺς τὸ κοινόν.", "st": "25.26"}, {"sp": "N", "t": "ἀνθ’ ὧν ἁπάντων ἄξιόν ἐστιν ὑποσχεῖν αὐτὸν τὴν δίκην. ἢ τί γὰρ ἂν εἰπεῖν ἔχοι τὰ σεμνότατα διασύρας ἐπὶ τοσούτων μαρτύρων; χρήσιμον γοῦν καὶ πρὸς ἐκείνους τὸ τοιοῦτον, εἰ θεάσαιντο αὐτὸν κολασθέντα, ὡς μηδὲ ἄλλος τις ἔτι καταφρονοίη Φιλοσοφίας· ἐπεὶ τό γε τὴν ἡσυχίαν ἄγειν καὶ ὑβριζόμενον ἀνέχεσθαι οὐ μετριότητος, ἀλλὰ ἀνανδρίας καὶ εὐηθείας εἰκότως ἂν νομίζοιτο. τὰ μὲν γὰρ τελευταῖα τίνι φορητά; ὃς καθάπερ τὰ ἀνδράποδα παραγαγὼν ἡμᾶς ἐπὶ τὸ πωλητήριον καὶ κήρυκα ἐπιστήσας ἀπημπόλησεν, ὥς φασιν, τοὺς μὲν ἐπὶ πολλῷ, ἐνίους δὲ μνᾶς Ἀττικῆς, ἐμὲ δὲ ὁ παμπονηρότατος οὗτος δύ’ ὀβολῶν· οἱ παρόντες δὲ ἐγέλων.", "st": "25.27"}, {"sp": "N", "t": "ἀνθ’ ὧν αὐτοί τε ἀνεληλύθαμεν ἀγανακτήσαντες καὶ σὲ ἀξιοῦμεν τιμωρήσειν ἡμῖν τὰ ἔσχατα ὑβρισμένοις.", "st": "25.27"}, {"sp": "N", "t": "<em>Πλάτων.<\/em> εὖ γε, ὦ Διόγενες, ὑπὲρ ἁπάντων καλῶς ὁπόσα ἐχρῆν ἅπαντα εἴρηκας.", "st": "25.28"}, {"sp": "N", "t": "<em>Φιλοσοφία.<\/em> παύσασθε ἐπαινοῦντες· ἔγχει τῷ ἀπολογουμένῳ. σὺ δὲ ὁ Παρρησιάδης λέγε ἤδη ἐν τῷ μέρει· σοὶ γὰρ τὸ νῦν ῥεῖ. μὴ μέλλε οὖν.", "st": "25.28"}, {"sp": "N", "t": "<em>Παρρησιάδης.<\/em> οὐ πάντα μου, ὦ Φιλοσοφία, κατηγόρησε Διογένης, ἀλλὰ τὰ πλείω καὶ ὅσα ἦν χαλεπώτερα οὐκ οἶδα ὅ τι παθὼν παρέλιπεν. ἐγὼ δὲ τοσούτου δέω ἔξαρνος γενέσθαι ὡς οὐκ εἶπον αὐτά, ἢ ἀπολογίαν τινὰ μεμελετηκὼς ἀφῖχθαι, ὥστε καὶ εἴ τινα ἢ αὐτὸς ἀπεσιώπησεν ἢ ἐγὼ μὴ πρότερον ἔφθην εἰρηκώς, νῦν προσθήσειν μοι δοκῶ. οὕτως γὰρ ἂν μάθοις οὕστινας ἀπεκήρυττον καὶ κακῶς ἠγόρευον ἀλαζόνας καὶ γόητας ἀποκαλῶν. καί μοι μόνον τοῦτο παραφυλάττετε, εἰ ἀληθῆ περὶ αὐτῶν ἐρῶ. εἰ δέ τι βλάσφημον ἢ τραχὺ φαίνοιτο ἔχων ὁ λόγος, οὐ τὸν διελέγχοντα ἐμέ, ἀλλ’ ἐκείνους ἂν οἶμαι δικαιότερον αἰτιάσαισθε, τοιαῦτα ποιοῦντας.", "st": "25.29"}, {"sp": "N", "t": "ἐγὼ γὰρ ἐπειδὴ τάχιστα συνεῖδον ὁπόσα τοῖς ῥητορεύουσιν ἀναγκαῖον τὰ δυσχερῆ προσεῖναι, ἀπάτην καὶ ψεῦδος καὶ θρασύτητα καὶ βοὴν καὶ ὠθισμοὺς καὶ μυρία ἄλλα, ταῦτα μέν, ὥσπερ εἰκὸς ἦν, ἀπέφυγον, ἐπὶ δὲ τὰ σά, ὦ Φιλοσοφία, καλὰ ὁρμήσας ἠξίουν ὁπόσον ἔτι μοι λοιπὸν τοῦ βίου καθάπερ ἐκ ζάλης καὶ κλύδωνος εἰς εὔδιόν τινα λιμένα ἐσπλεύσας ὑπὸ σοὶ σκεπόμενος καταβιῶναι.", "st": "25.29"}, {"sp": "N", "t": "κἀπειδὴ μόνον παρέκυψα εἰς τὰ ὑμέτερα, σὲ μέν, ὥσπερ ἀναγκαῖον ἦν, καὶ τούσδε ἅπαντας ἐθαύμαζον ἀρίστου βίου νομοθέτας ὄντας καὶ τοῖς ἐπ’ αὐτὸν ἐπειγομένοις χεῖρα ὀρέγοντας, τὰ κάλλιστα καὶ συμφορώτατα παραινοῦντας, εἴ τις μὴ παραβαίνοι αὐτὰ μηδὲ διολισθάνοι, ἀλλ’ ἀτενὲς ἀποβλέπων εἰς τοὺς κανόνας οὓς προτεθείκατε, πρὸς τούτους ῥυθμίζοι καὶ ἀπευθύνοι τὸν ἑαυτοῦ βίον, ὅπερ νὴ Δία καὶ τῶν καθ’ ὑμᾶς αὐτοὺς ὀλίγοι ποιοῦσιν.", "st": "25.30"}, {"sp": "N", "t": "ὁρῶν δὲ πολλοὺς οὐκ ἔρωτι φιλοσοφίας ἐχομένους ἀλλὰ δόξης μόνον τῆς ἀπὸ τοῦ πράγματος ἐφιεμένους, καὶ τὰ μὲν πρόχειρα ταῦτα καὶ δημόσια καὶ ὁπόσα παντὶ μιμεῖσθαι ῥᾴδιον εὖ μάλα ἐοικότας ἀγαθοῖς ἀνδράσι, τὸ γένειον λέγω καὶ τὸ βάδισμα καὶ τὴν ἀναβολήν, ἐπὶ δὲ τοῦ βίου καὶ τῶν πραγμάτων ἀντιφθεγγομένους τῷ σχήματι καὶ τἀναντία ὑμῖν ἐπιτηδεύοντας καὶ διαφθείροντας τὸ ἀξίωμα τῆς ὑποσχέσεως, ἠγανάκτουν, καὶ τὸ πρᾶγμα ὅμοιον ἐδόκει μοι καθάπερ ἂν εἴ τις ὑποκριτὴς τραγῳδίας μαλθακὸς αὐτὸς ὢν καὶ γυναικεῖος Ἀχιλλέα ἢ Θησέα ἢ καὶ τὸν Ἡρακλέα ὑποκρίνοιτο αὐτὸν μήτε βαδίζων μήτε βοῶν ἡρωϊκόν, ἀλλὰ θρυπτόμενος ὑπὸ τηλικούτῳ προσωπείῳ, ὃν οὐδ’ ἂν ἡ Ἑλένη ποτὲ ἢ Πολυξένη ἀνάσχοιντο πέρα τοῦ μετρίου αὐταῖς προσεοικότα, οὐχ ὅπως ὁ Ἡρακλῆς ὁ Καλλίνικος, ἀλλά μοι δοκεῖ τάχιστ’ ἂν ἐπιτρῖψαι τῷ ῥοπάλῳ παίων τοῦτον αὐτόν τε καὶ τὸ προσωπεῖον, οὕτως ἀτίμως κατατεθηλυμμένος πρὸς αὐτοῦ.", "st": "25.31"}, {"sp": "N", "t": "τοιαῦτα καὶ αὐτὸς ὑμᾶς πάσχοντας ὑπ’ ἐκείνων ὁρῶν οὐκ ἤνεγκα τὴν αἰσχύνην τῆς ὑποκρίσεως, εἰ πίθηκοι ὄντες ἐτόλμησαν ἡρώων προσωπεῖα περιθέσθαι ἢ τὸν ἐν Κύμῃ ὄνον μιμήσασθαι, ὃς λεοντῆν περιβαλόμενος ἠξίου λέων αὐτὸς εἶναι, πρὸς ἀγνοοῦντας τοὺς Κυμαίους ὀγκώμενος μάλα τραχὺ καὶ καταπληκτικόν, ἄχρι δή τις αὐτὸν ξένος καὶ λέοντα ἰδὼν καὶ ὄνον πολλάκις ἤλεγξε καὶ ἀπεδίωξε παίων τοῖς ξύλοις.", "st": "25.32"}, {"sp": "N", "t": "Ὃ δὲ μάλιστά μοι δεινόν, ὦ Φιλοσοφία, κατεφαίνετο, τοῦτο ἦν· οἱ γὰρ ἄνθρωποι εἴ τινα τούτων ἑώρων πονηρὸν ἢ ἄσχημον ἢ ἀσελγές τι ἐπιτηδεύοντα, οὐκ ἔστιν ὅστις οὐ Φιλοσοφίαν αὐτὴν ᾐτιᾶτο καὶ τὸν Χρύσιππον εὐθὺς ἢ Πλάτωνα ἢ Πυθαγόραν ἢ ὅτου ἐπώνυμον αὑτὸν ὁ διαμαρτάνων ἐκεῖνος ἐποιεῖτο καὶ οὗ τοὺς λόγους ἐμιμεῖτο· καὶ ἀπὸ τοῦ κακῶς βιοῦντος πονηρὰ περὶ ὑμῶν εἴκαζον τῶν πρὸ πολλοῦ τεθνηκότων· οὐ γὰρ παρὰ ζῶντας ὑμᾶς ἡ ἐξέτασις αὐτοῦ ἐγίγνετο, ἀλλ’ ὑμεῖς μὲν ἐκποδών, ἐκεῖνον δὲ ἑώρων σαφῶς ἅπαντες δεινὰ καὶ ἄσεμνα ἐπιτηδεύοντα, ὥστε ἐρήμην ἡλίσκεσθε μετ’ αὐτοῦ καὶ ἐπὶ τὴν ὁμοίαν διαβολὴν συγκατεσπᾶσθε.", "st": "25.32"}, {"sp": "N", "t": "ταῦτα οὐκ ἤνεγκα ὁρῶν ἔγωγε, ἀλλ’ ἤλεγχον αὐτοὺς καὶ διέκρινον ἀφ’ ὑμῶν· ὑμεῖς δέ, τιμᾶν ἐπὶ τούτοις δέον, εἰς δικαστήριόν με ἄγετε. οὐκοῦν ἤν τινα καὶ τῶν μεμυημένων ἰδὼν ἐξαγορεύοντα ταῖν θεαῖν τὰ ἀπόρρητα καὶ ἐξορχούμενον ἀγανακτήσω καὶ διελέγξω, ἐμὲ τὸν ἀσεβοῦντα ἡγήσεσθε εἶναι; ἀλλ’ οὐ δίκαιον. ἐπεὶ καὶ οἱ ἀθλοθέται μαστιγοῦν εἰώθασιν, ἤν τις ὑποκριτὴς Ἀθηνᾶν ἢ Ποσειδῶνα ἢ τὸν Δία ὑποδεδυκὼς μὴ καλῶς ὑποκρίνηται μηδὲ κατ’ ἀξίαν τῶν θεῶν, καὶ οὐ δή που ὀργίζονται αὐτοῖς ἐκεῖνοι, διότι τὸν περικείμενον αὐτῶν τὰ προσωπεῖα καὶ τὸ σχῆμα ἐνδεδυκότα ἐπέτρεψαν παίειν τοῖς μαστιγοφόροις, ἀλλὰ καὶ ἥδοιντ’ ἄν, οἶμαι, μᾶλλον μαστιγουμένῳ· οἰκέτην μὲν γάρ τινα ἢ ἄγγελον μὴ δεξιῶς ὑποκρίνασθαι μικρὸν τὸ πταῖσμα, τὸν Δία δὲ ἢ τὸν Ἡρακλέα μὴ κατ’ ἀξίαν ἐπιδείξασθαι τοῖς θεαταῖς, ἀποτρόπαιον ὡς αἰσχρόν.", "st": "25.33"}, {"sp": "N", "t": "καὶ γὰρ αὖ καὶ τόδε πάντων ἀτοπώτατόν ἐστιν, ὅτι τοὺς μὲν λόγους ὑμῶν πάνυ ἀκριβοῦσιν οἱ πολλοὶ αὐτῶν, καθάπερ δὲ ἐπὶ τοῦτο μόνον ἀναγιγνώσκοντες αὐτοὺς καὶ μελετῶντες, ὡς τἀναντία ἐπιτηδεύοιεν, οὕτως βιοῦσιν. τὸ μὲν γὰρ βιβλίον χρημάτων φησὶ δεῖν καταφρονεῖν καὶ δόξης καὶ μόνον τὸ καλὸν ἀγαθὸν οἴεσθαι καὶ ἀόργητον εἶναι καὶ τῶν λαμπρῶν τούτων ὑπερορᾶν καὶ ἐξ ἰσοτιμίας αὐτοῖς διαλέγεσθαι, καλά, ὦ θεοί, καὶ σοφὰ καὶ θαυμάσια λέγον ὡς ἀληθῶς. οἱ δὲ καὶ αὐτὰ ταῦτα ἐπὶ μισθῷ διδάσκουσιν καὶ τοὺς πλουσίους τεθήπασιν καὶ πρὸς τὸ ἀργύριον κεχήνασιν, ὀργιλώτεροι μὲν τῶν κυνιδίων ὄντες, δειλότεροι δὲ τῶν λαγωῶν, κολακικώτεροι δὲ τῶν πιθήκων, ἀσελγέστεροι δὲ τῶν ὄνων, ἁρπακτικώτεροι δὲ τῶν γαλῶν, φιλονεικότεροι δὲ τῶν ἀλεκτρυόνων. τοιγαροῦν γέλωτα ὀφλισκάνουσιν ὠθιζόμενοι ἐπ’ αὐτὰ καὶ περὶ τὰς τῶν πλουσίων πυλῶνας ἀλλήλους παραγκωνιζόμενοι καὶ δεῖπνα πολυάνθρωπα δειπνοῦντες καὶ ἐν αὐτοῖς τούτοις ἐπαινοῦντες φορτικῶς καὶ πέρα τοῦ καλῶς ἔχοντος ἐμφορούμενοι καὶ μεμψίμοιροι φαινόμενοι καὶ ἐπὶ τῆς κύλικος ἀτερπῆ καὶ ἀπῳδὰ φιλοσοφοῦντες καὶ τὸν ἄκρατον οὐ φέροντες· οἱ ἰδιῶται δὲ ὁπόσοι πάρεισιν, γελῶσι δηλαδὴ καὶ καταπτύουσιν φιλοσοφίας, εἰ τοιαῦτα καθάρματα ἐκτρέφει.", "st": "25.34"}, {"sp": "N", "t": "τὸ δὲ πάντων αἴσχιστον, ὅτι μηδενὸς δεῖσθαι λέγων ἕκαστος αὐτῶν, ἀλλὰ μόνον πλούσιον εἶναι τὸν σοφὸν κεκραγὼς μικρὸν ὕστερον προσελθὼν αἰτεῖ καὶ ἀγανακτεῖ μὴ λαβών, ὅμοιον ὡς εἴ τις ἐν βασιλικῷ σχήματι ὀρθὴν τιάραν ἔχων καὶ διάδημα καὶ τὰ ἄλλα ὅσα βασιλείας γνωρίσματα προσαιτοίη τῶν ὑποδεεστέρων δεόμενος.", "st": "25.35"}, {"sp": "N", "t": "ὅταν μὲν οὖν λαβεῖν αὐτοὺς δέῃ, πολὺς ὁ περὶ τοῦ κοινωνικὸν εἶναι δεῖν λόγος καὶ ὡς ἀδιάφορον ὁ πλοῦτος καί, “τί γὰρ τὸ χρυσίον ἢ τἀργύριον, οὐδὲν τῶν ἐν τοῖς αἰγιαλοῖς ψήφων διαφέρον;” ὅταν δέ τις ἐπικουρίας δεόμενος ἑταῖρος ἐκ παλαιοῦ καὶ φίλος ἀπὸ πολλῶν ὀλίγα αἰτῇ προσελθών, σιωπὴ καὶ ἀπορία καὶ ἀμαθία καὶ παλινῳδία τῶν δογμάτων πρὸς τὸ ἐναντίον· οἱ δὲ πολλοὶ περὶ φιλίας ἐκεῖνοι λόγοι καὶ ἡ ἀρετὴ καὶ τὸ καλὸν οὐκ οἶδα ὅποι ποτὲ οἴχεται ταῦτα ἀποπτάμενα πάντα, πτερόεντα ὡς ἀληθῶς ἔπη, μάτην ὁσημέραι πρὸς αὐτῶν ἐν ταῖς διατριβαῖς σκιαμαχούμενα.", "st": "25.35"}, {"sp": "N", "t": "μέχρι γὰρ τούτου φίλος ἕκαστος αὐτῶν, εἰς ὅσον ἂν μὴ ἀργύριον ἢ χρυσίον ᾖ προκείμενον ἐν τῷ μέσῳ· ἢν δέ τις ὀβολὸν ἐπιδείξῃ μόνον, λέλυται μὲν ἡ εἰρήνη, ἄσπονδα δὲ κἀκήρυκτα πάντα, καὶ τὰ βιβλία ἐξαλήλιπται καὶ ἡ ἀρετὴ πέφευγεν. οἷόν τι καὶ οἱ κύνες πάσχουσιν ἐπειδάν τις ὀστοῦν εἰς μέσους αὐτοὺς ἐμβάλῃ· ἀναπηδήσαντες δάκνουσιν ἀλλήλους καὶ τὸν προαρπάσαντα τὸ ὀστοῦν ὑλακτοῦσιν.", "st": "25.36"}, {"sp": "N", "t": "λέγεται δὲ καὶ βασιλεύς τις Αἰγύπτιος πιθήκους ποτὲ πυρριχίζειν διδάξαι καὶ τὰ θηρία — μιμηλότατα δέ ἐστι τῶν ἀνθρωπίνων — ἐκμαθεῖν τάχιστα καὶ ὀρχεῖσθαι ἁλουργίδας ἀμπεχόμενα καὶ προσωπεῖα περικείμενα, καὶ μέχρι γε πολλοῦ εὐδοκιμεῖν τὴν θέαν, ἄχρι δὴ θεατής τις ἀστεῖος κάρυα ὑπὸ κόλπου ἔχων ἀφῆκεν εἰς τὸ μέσον· οἱ δὲ πίθηκοι ἰδόντες καὶ ἐκλαθόμενοι τῆς ὀρχήσεως, τοῦθ’ ὅπερ ἦσαν, πίθηκοι ἐγένοντο ἀντὶ πυρριχιστῶν καὶ συνέτριβον τὰ προσωπεῖα καὶ τὴν ἐσθῆτα κατερρήγνυον καὶ ἐμάχοντο περὶ τῆς ὀπώρας πρὸς ἀλλήλους, τὸ δὲ σύνταγμα τῆς πυρρίχης διελέλυτο καὶ κατεγελᾶτο ὑπὸ τοῦ θεάτρου.", "st": "25.36"}, {"sp": "N", "t": "τοιαῦτα καὶ οὗτοι ποιοῦσιν, καὶ ἔγωγε τοὺς τοιούτους κακῶς ἠγόρευον καὶ οὔποτε παύσομαι διελέγχων καὶ κωμῳδῶν, περὶ ὑμῶν δὲ ἢ τῶν ὑμῖν παραπλησίων — εἰσὶ γάρ, εἰσί τινες ὡς ἀληθῶς φιλοσοφίαν ζηλοῦντες καὶ τοῖς ὑμετέροις νόμοις ἐμμένοντες — μὴ οὕτως μανείην ἔγωγε ὡς βλάσφημον εἰπεῖν τι ἢ σκαιόν. ἢ τί γὰρ ἂν εἰπεῖν ἔχοιμι; τί γὰρ ὑμῖν τοιοῦτον βεβίωται; τοὺς δὲ ἀλαζόνας ἐκείνους καὶ θεοῖς ἐχθροὺς ἄξιον οἶμαι μισεῖν. ἢ σὺ γάρ, ὦ Πυθαγόρα καὶ Πλάτων καὶ Χρύσιππε καὶ Ἀριστότελες, τί φατε; προσήκειν ὑμῖν τοὺς τοιούτους ἢ οἰκεῖόν τι καὶ συγγενὲς ἐπιδείκνυσθαι τῷ βίῳ; νὴ Δῐ Ἡρακλῆς, φασίν, καὶ πίθηκος. ἢ διότι πώγωνας ἔχουσι καὶ φιλοσοφεῖν φάσκουσι καὶ σκυθρωποί εἰσι, διὰ τοῦτο χρὴ ὑμῖν εἰκάζειν αὐτούς; ἀλλὰ ἤνεγκα ἄν, εἰ πιθανοὶ γοῦν ἦσαν καὶ ἐπὶ τῆς ὑποκρίσεως αὐτῆς· νῦν δὲ θᾶττον ἂν γὺψ ἀηδόνα μιμήσαιτο ἢ οὗτοι φιλοσόφους.", "st": "25.37"}, {"sp": "N", "t": "εἴρηκα ὑπὲρ ἐμαυτοῦ ὁπόσα εἶχον. σὺ δέ, ὦ Ἀλήθεια, μαρτύρει πρὸς αὐτοὺς εἰ ἀληθῆ ἐστιν.", "st": "25.37"}, {"sp": "N", "t": "<em>Φιλοσοφία.<\/em> μετάστηθι, ὦ Παρρησιάδη· ἔτι πορρωτέρω. τί ποιῶμεν ἡμεῖς; πῶς ὑμῖν εἰρηκέναι ἁνὴρ ἔδοξεν;", "st": "25.38"}, {"sp": "N", "t": "<em>Ἀλήθεια.<\/em> ἐγὼ μέν, ὦ Φιλοσοφία, μεταξὺ λέγοντος αὐτοῦ κατὰ τῆς γῆς δῦναι εὐχόμην· οὕτως ἀληθῆ πάντα εἶπεν. ἐγνώριζον γοῦν ἀκούουσα ἕκαστον τῶν ποιούντων αὐτὰ καὶ ἐφήρμοζον μεταξὺ τοῖς λεγομένοις, τοῦτο μὲν εἰς τόνδε, τοῦτο δὲ ὁ δεῖνα ποιεῖ· καὶ ὅλως ἔδειξε τοὺς ἄνδρας ἐναργῶς καθάπερ ἐπί τινος γραφῆς τὰ πάντα προσεοικότας, οὐ τὰ σώματα μόνον ἀλλὰ καὶ τὰς ψυχὰς αὐτὰς εἰς τὸ ἀκριβέστατον ἀπεικάσας.", "st": "25.38"}, {"sp": "N", "t": "<em>Ἀρετή.<\/em> κἀγὼ πάνυ ἠρυθρίασα ἡ Ἀρετή.", "st": "25.38"}, {"sp": "N", "t": "<em>Φιλοσοφία.<\/em> ὑμεῖς δὲ τί φατέ;", "st": "25.38"}, {"sp": "N", "t": "<em>Πλάτων.<\/em> τί δὲ ἄλλο ἢ ἀφεῖσθαι αὐτὸν τοῦ ἐγκλήματος καὶ φίλον ἡμῖν καὶ εὐεργέτην ἀναγεγράφθαι; τὸ γοῦν τῶν Ἰλιέων ἀτεχνῶς πεπόνθαμεν· τραγῳδόν τινα τοῦτον ἐφ’ ἡμᾶς κεκινήκαμεν ᾀσόμενον τὰς Φρυγῶν συμφοράς. ᾀδέτω δ’ οὖν καὶ τοὺς θεοῖς ἐχθροὺς ἐκτραγῳδείτω.", "st": "25.38"}, {"sp": "N", "t": "<em>Διογένης.<\/em> καὶ αὐτός, ὦ Φιλοσοφία, πάνυ ἐπαινῶ τὸν ἄνδρα καὶ ἀνατίθεμαι τὰ κατηγορούμενα καὶ φίλον ποιοῦμαι αὐτὸν γενναῖον ὄντα.", "st": "25.38"}, {"sp": "N", "t": "<em>Φιλοσοφία.<\/em> εὖ ἔχει· πρόσιθι Παρρησιάδη· ἀφίεμέν σε τῆς αἰτίας, καὶ ἁπάσαις κρατεῖς, καὶ τὸ λοιπὸν ἴσθι ἡμέτερος ὤν.", "st": "25.39"}, {"sp": "N", "t": "<em>Παρρησιάδης.<\/em> προσεκύνησα τήν γε πρώτην· μᾶλλον δέ, τραγικώτερον αὐτὸ ποιήσειν μοι δοκῶ· σεμνότερον γάρ·<br>ὦ μέγα σεμνὴ Νίκη, τὸν ἐμὸν<br>βίοτον κατέχοις<br>καὶ μὴ λήγοις στεφανοῦσα.", "st": "25.39"}, {"sp": "N", "t": "<em>Ἀρετή.<\/em> οὐκοῦν δευτέρου κρατῆρος ἤδη καταρχώμεθα· προσκαλῶμεν κἀκείνους, ὡς δίκην ὑπόσχωσιν ἀνθ’ ὧν εἰς ἡμᾶς ὑβρίζουσι· κατηγορήσει δὲ Παρρησιάδης ἑκάστου.", "st": "25.39"}, {"sp": "N", "t": "<em>Φιλοσοφία.<\/em> ὀρθῶς, ὦ Ἀρετή, ἔλεξας. ὥστε σύ, παῖ Συλλογισμέ, κατακύψας εἰς τὸ ἄστυ προσκήρυττε τοὺς φιλοσόφους.", "st": "25.39"}, {"sp": "N", "t": "<em>Συλλογισμός.<\/em> ἄκουε, σίγα· τοὺς φιλοσόφους ἥκειν εἰς ἀκρόπολιν ἀπολογησομένους ἐπὶ τῆς Ἀρετῆς καὶ Φιλοσοφίας καὶ Δίκης.", "st": "25.40"}, {"sp": "N", "t": "<em>Παρρησιάδης.<\/em> ὁρᾷς; ὀλίγοι ἀνίασι γνωρίσαντες τὸ κήρυγμα, καὶ ἄλλως δεδίασι τὴν Δίκην· οἱ πολλοὶ δὲ αὐτῶν οὐδὲ σχολὴν ἄγουσιν ἀμφὶ τοὺς πλουσίους ἔχοντες. εἰ δὲ βούλει πάντας ἥκειν, κατὰ τάδε, ὦ Συλλογισμέ, κήρυττε —", "st": "25.40"}, {"sp": "N", "t": "<em>Συλλογισμός.<\/em> Μηδαμῶς, ἀλλὰ σύ, ὦ Παρρησιάδη, προσκάλει καθ’ ὅ τι σοι δοκεῖ.", "st": "25.40"}, {"sp": "N", "t": "<em>Παρρησιάδης.<\/em> οὐδὲν τόδε χαλεπόν. ἄκουε, σίγα. ὅσοι φιλόσοφοι εἶναι λέγουσιν καὶ ὅσοι προσήκειν αὐτοῖς οἴονται τοῦ ὀνόματος, ἥκειν εἰς ἀκρόπολιν ἐπὶ τὴν διανομήν. δύο μναῖ ἑκάστῳ δοθήσονται καὶ σησαμαῖος πλακοῦς· ὃς δ’ ἂν πώγωνα βαθὺν ἐπιδείξηται, καὶ παλάθην ἰσχάδων οὗτός γε προσεπιλήψεται. κομίζειν δ’ ἕκαστον σωφροσύνην μὲν ἢ δικαιοσύνην ἢ ἐγκράτειαν μηδαμῶς· οὐκ ἀναγκαῖα γὰρ ταῦτά γε, ἢν μὴ παρῇ· πέντε δὲ συλλογισμοὺς ἐξ ἅπαντος· οὐ γὰρ θέμις ἄνευ τούτων εἶναι σοφόν.<br>κεῖται δ’ ἐν μέσσοισι δύο χρυσοῖο τάλαντα,<br>τῷ δόμεν, ὃς μετὰ πᾶσιν ἐριζέμεν ἔξοχος εἴη.", "st": "25.41"}, {"sp": "N", "t": "<em>Φιλοσοφία.<\/em> βαβαί, ὅσοι· πλήρης μὲν ἡ ἄνοδος ὠθιζομένων ἐπὶ τὰς δύο μνᾶς, ὡς ἤκουσαν μόνον· παρὰ δὲ τὸ Πελασγικὸν ἄλλοι καὶ κατὰ τὸ Ἀσκληπιεῖον ἕτεροι καὶ παρὰ τὸν Ἄρειον πάγον ἔτι πλείους, ἔνιοι δὲ καὶ κατὰ τὸν Τάλω τάφον, οἱ δὲ καὶ πρὸς τὸ Ἀνακεῖον προσθέμενοι κλίμακας ἀνέρπουσι βομβηδὸν νὴ Δία καὶ βοτρυδὸν ἑσμοῦ δίκην, ἵνα καὶ καθ’ Ὅμηρον εἴπω· ἀλλὰ κἀκεῖθεν εὖ μάλα πολλοὶ κἀντεῦθεν<br>μυρίοι, ὅσσα τε φύλλα καὶ ἄνθεα γίνεται ὥρῃ.<br>μεστὴ δὲ ἡ ἀκρόπολις ἐν βραχεῖ κλαγγηδὸν προκαθιζόντων καὶ πανταχοῦ πήρα κολακεία, πώγων ἀναισχυντία, βακτηρία λιχνεία, συλλογισμὸς φιλαργυρία· οἱ ὀλίγοι δέ, ὁπόσοι πρὸς τὸ πρῶτον κήρυγμα ἐκεῖνο ἀνῄεσαν, ἀφανεῖς καὶ ἄσημοι, ἀναμιχθέντες τῷ πλήθει τῶν ἄλλων, καὶ λελήθασιν ἐν τῇ ὁμοιότητι τῶν ἄλλων σχημάτων.", "st": "25.42"}, {"sp": "N", "t": "<em>Παρρησιάδης.<\/em> τοῦτο γοῦν τὸ δεινότατόν ἐστιν, ὦ Φιλοσοφία, καὶ ὅ τις ἂν μέμψαιτο μάλιστά σου, τὸ μηδὲν ἐπιβαλεῖν γνώρισμα καὶ σημεῖον αὐτοῖς· πιθανώτεροι γὰρ οἱ γόητες οὗτοι πολλάκις τῶν ἀληθῶς φιλοσοφούντων.", "st": "25.42"}, {"sp": "N", "t": "<em>Φιλοσοφία.<\/em> ἔσται τοῦτο μετ’ ὀλίγον, ἀλλὰ δεχώμεθα ἤδη αὐτούς.", "st": "25.42"}, {"sp": "N", "t": "<em>Πλατωνικός.<\/em> ἡμᾶς πρώτους χρὴ τοὺς Πλατωνικοὺς λαβεῖν.", "st": "25.43"}, {"sp": "N", "t": "<em>Πυθαγορικός.<\/em> οὔκ, ἀλλὰ τοὺς Πυθαγορικοὺς ἡμᾶς· πρότερος γὰρ ὁ Πυθαγόρας ἦν.", "st": "25.43"}, {"sp": "N", "t": "<em>Στωικός.<\/em> Ληρεῖτε· ἀμείνους ἡμεῖς οἱ ἀπὸ τῆς Στοᾶς.", "st": "25.43"}, {"sp": "N", "t": "<em>Περιπατητικός.<\/em> οὐ μὲν οὖν, ἀλλ’ ἔν γε τοῖς χρήμασι πρῶτοι ἂν ἡμεῖς εἴημεν οἱ ἐκ τοῦ Περιπάτου.", "st": "25.43"}, {"sp": "N", "t": "<em>Ἐπικούρειος.<\/em> ἡμῖν τοῖς Ἐπικουρείοις τοὺς πλακοῦντας δότε καὶ τὰς παλάθας· περὶ δὲ τῶν μνῶν περιμενοῦμεν, κἂν ὑστάτους δέῃ λαβεῖν.", "st": "25.43"}, {"sp": "N", "t": "<em>Ἀκαδημαϊκός.<\/em> ποῦ τὰ δύο τάλαντα; δείξομεν γὰρ οἱ Ἀκαδημαϊκοὶ ὅσον τῶν ἄλλων ἐσμὲν ἐριστικώτεροι.", "st": "25.43"}, {"sp": "N", "t": "<em>Στωικός.<\/em> οὐχ ἡμῶν γε τῶν Στωϊκῶν παρόντων.", "st": "25.43"}, {"sp": "N", "t": "<em>Φιλοσοφία.<\/em> παύσασθε φιλονεικοῦντες· ὑμεῖς δὲ οἱ Κυνικοὶ μήτε ὠθεῖτε ἀλλήλους μήτε τοῖς ξύλοις παίετε· ἐπ’ ἄλλα γὰρ ἴστε κεκλημένοι. καὶ νῦν ἔγωγε ἡ Φιλοσοφία καὶ Ἀρετὴ αὕτη καὶ Ἀλήθεια δικάσομεν οἵτινες οἱ ὀρθῶς φιλοσοφοῦντές εἰσιν. εἶτα ὅσοι μὲν ἂν εὑρεθῶσιν κατὰ τὰ ἡμῖν δοκοῦντα βιοῦντες, εὐδαιμονήσουσιν ἄριστοι κεκριμένοι· τοὺς γόητας δὲ καὶ οὐδὲν ἡμῖν προσήκοντας κακοὺς κακῶς ἐπιτρίψομεν, ὡς μὴ ἀντιποιῶνται τῶν ὑπὲρ αὐτοὺς ἀλαζόνες ὄντες. τί τοῦτο; φεύγετε; νὴ Δία, κατὰ τῶν γε κρημνῶν οἱ πολλοὶ ἁλλόμενοι. κενὴ δ’ οὖν ἡ ἀκρόπολις, πλὴν ὀλίγων τούτων ὁπόσοι μεμενήκασιν οὐ φοβηθέντες τὴν κρίσιν.", "st": "25.44"}, {"sp": "N", "t": "οἱ ὑπηρέται ἀνέλεσθε τὴν πήραν, ἣν ὁ Κυνικὸς ἀπέρριψεν ἐν τῇ τροπῇ. φέρ’ ἴδω τί καὶ ἔχει· ἦ που θέρμους ἢ βιβλίον ἢ ἄρτους τῶν αὐτοπυριτῶν;", "st": "25.45"}, {"sp": "N", "t": "<em>Ὑπηρέτης.<\/em> Οὔκ, ἀλλὰ χρυσίον τουτὶ καὶ μύρον καὶ μαχαίριον κουρευτικὸν καὶ κάτοπτρον καὶ κύβους.", "st": "25.45"}, {"sp": "N", "t": "<em>Φιλοσοφία.<\/em> εὖ γε, ὦ γενναῖε. τοιαῦτα ἦν σοι τὰ ἐφόδια τῆς ἀσκήσεως καὶ μετὰ τούτων ἠξίους λοιδορεῖσθαι πᾶσιν καὶ τοὺς ἄλλους παιδαγωγεῖν;", "st": "25.45"}, {"sp": "N", "t": "<em>Παρρησιάδης.<\/em> τοιοῦτοι μὲν οὖν ὑμῖν οὗτοι. χρὴ δὲ ὑμᾶς σκοπεῖν ὅντινα τρόπον ἀγνοούμενα ταῦτα πεπαύσεται καὶ διαγνώσονται οἱ ἐντυγχάνοντες, οἵτινες οἱ ἀγαθοὶ αὐτῶν εἰσι καὶ οἵτινες αὖ πάλιν οἱ τοῦ ἑτέρου βίου.", "st": "25.45"}, {"sp": "N", "t": "<em>Φιλοσοφία.<\/em> Σύ, ὦ Ἀλήθεια, ἐξεύρισκε· ὑπὲρ σοῦ γὰρ τοῦτο γένοιτ’ ἄν, ὡς μὴ ἐπικρατῇ σου τὸ Ψεῦδος μηδὲ ὑπὸ τῇ Ἀγνοίᾳ λανθάνωσιν οἱ φαῦλοι τῶν ἀνδρῶν σε τοὺς χρηστοὺς μεμιμημένοι.", "st": "25.45"}, {"sp": "N", "t": "<em>Ἀλήθεια.<\/em> ἐπ’ αὐτῷ, εἰ δοκεῖ, Παρρησιάδῃ ποιησώμεθα τὸ τοιοῦτον, ἐπεὶ χρηστὸς ὦπται καὶ εὔνους ἡμῖν καὶ σέ, ὦ Φιλοσοφία, μάλιστα θαυμάζων, παραλαβόντα μεθ’ ἑαυτοῦ τὸν Ἔλεγχον ἅπασι τοῖς φάσκουσι φιλοσοφεῖν ἐντυγχάνειν. εἶθ’ ὃν μὲν ἂν εὕρῃ γνήσιον ὡς ἀληθῶς φιλόσοφον, στεφανωσάτω θαλλοῦ στεφάνῳ καὶ εἰς τὸ Πρυτανεῖον καλεσάτω, ἢν δέ τινι — οἷοι πολλοί εἰσι — καταράτῳ ἀνδρὶ ὑποκριτῇ φιλοσοφίας ἐντύχῃ, τὸ τριβώνιον περισπάσας ἀποκειράτω τὸν πώγωνα ἐν χρῷ πάνυ τραγοκουρικῇ μαχαίρᾳ καὶ ἐπὶ τοῦ μετώπου στίγματα ἐπιβαλέτω ἢ ἐγκαυσάτω κατὰ τὸ μεσόφρυον· ὁ δὲ τύπος τοῦ καυτῆρος ἔστω ἀλώπηξ ἢ πίθηκος.", "st": "25.46"}, {"sp": "N", "t": "<em>Φιλοσοφία.<\/em> εὖ γε, ὦ Ἀλήθεια, φής· ὁ δὲ ἔλεγχος, Παρρησιάδη, τοιόσδε ἔστω, οἷος ὁ τῶν ἀετῶν πρὸς τὸν ἥλιον εἶναι λέγεται, οὐ μὰ Δί’ ὥστε κἀκείνους ἀντιβλέπειν τῷ φωτὶ καὶ πρὸς ἐκεῖνο δοκιμάζεσθαι, ἀλλὰ προθεὶς χρυσίον καὶ δόξαν καὶ ἡδονὴν ὃν μὲν ἂν αὐτῶν ἴδῃς ὑπερορῶντα καὶ μηδαμῶς ἑλκόμενον πρὸς τὴν ὄψιν, οὗτος ἔστω ὁ τῷ θαλλῷ στεφόμενος, ὃν δ’ ἂν ἀτενὲς ἀποβλέποντα καὶ τὴν χεῖρα ὀρέγοντα ἐπὶ τὸ χρυσίον, ἀπάγειν ἐπὶ τὸ καυτήριον τοῦτον ἀποκείρας πρότερον τὸν πώγωνα ὡς ἔδοξεν.", "st": "25.46"}, {"sp": "N", "t": "<em>Παρρησιάδης.<\/em> ἔσται ταῦτα, ὦ Φιλοσοφία, καὶ ὄψει αὐτίκα μάλα τοὺς πολλοὺς αὐτῶν ἀλωπεκίας ἢ πιθηκοφόρους, ὀλίγους δὲ καὶ ἐστεφανωμένους· εἰ βούλεσθε μέντοι, κἀνταῦθα ὑμῖν ἀνάξω τινὰς ἤδη αὐτῶν.", "st": "25.47"}, {"sp": "N", "t": "<em>Φιλοσοφία.<\/em> πῶς λέγεις; ἀνάξεις τοὺς φυγόντας;", "st": "25.47"}, {"sp": "N", "t": "<em>Παρρησιάδης.<\/em> καὶ μάλα, ἤνπερ ἡ ἱέρειά μοι ἐθελήσῃ πρὸς ὀλίγον χρῆσαι τὴν ὁρμιὰν ἐκείνην καὶ τὸ ἄγκιστρον, ὅπερ ὁ ἁλιεὺς ἀνέθηκεν ὁ ἐκ Πειραιῶς.", "st": "25.47"}, {"sp": "N", "t": "<em>Ἱερεία.<\/em> ἰδοὺ δὴ λαβέ, καὶ τὸν κάλαμόν γε ἅμα, ὡς πάντα ἔχῃς.", "st": "25.47"}, {"sp": "N", "t": "<em>Παρρησιάδης.<\/em> οὐκοῦν, ὦ ἱέρεια, καὶ ἰσχάδας μοί τινας δὸς ἀνύσασα καὶ ὀλίγον τοῦ χρυσίου.", "st": "25.47"}, {"sp": "N", "t": "<em>Ἱερεία.<\/em> λάμβανε.", "st": "25.47"}, {"sp": "N", "t": "<em>Φιλοσοφία.<\/em> τί πράττειν ἁνὴρ διανοεῖται; δελεάσας τὸ ἄγκιστρον ἰσχάδι καὶ τῷ χρυσίῳ καθεζόμενος ἐπὶ τὸ ἄκρον τοῦ τειχίου καθῆκεν εἰς τὴν πόλιν. τί ταῦτα, ὦ Παρρησιάδη, ποιεῖς; ἦ που τοὺς λίθους ἁλιεύσειν διέγνωκας ἐκ τοῦ Πελασγικοῦ;", "st": "25.47"}, {"sp": "N", "t": "<em>Παρρησιάδης.<\/em> σιώπησον, ὦ Φιλοσοφία, καὶ τὴν ἄγραν περίμενε· σὺ δέ, ὦ Πόσειδον ἀγρεῦ καὶ Ἀμφιτρίτη φίλη, πολλοὺς ἡμῖν ἀνάπεμπε τῶν ἰχθύων.", "st": "25.47"}, {"sp": "N", "t": "ἀλλ’ ὁρῶ τινα λάβρακα εὐμεγέθη, μᾶλλον δὲ χρύσοφρυν· οὐκ, ἀλλὰ γαλεός ἐστιν. πρόσεισι γοῦν τῷ ἀγκίστρῳ κεχηνώς· ὤσφραται τοῦ χρυσίου· πλησίον ἤδη ἐστίν· ἔψαυσεν· εἴληπται· ἀνασπάσωμεν. καὶ σύ, ὦ Ἔλεγχε, ἀνάσπα· Ἔλεγχε, συνεπιλαβοῦ τῆς ὁρμιᾶς.", "st": "25.48"}, {"sp": "N", "t": "<em>Ἔλεγχος.<\/em> ἄνω ἐστί. φέρ’ ἴδω τίς εἶ, ὦ βέλτιστε ἰχθύων; κύων οὗτός γε. Ἡράκλεις τῶν ὀδόντων. τί τοῦτο, ὦ γενναιότατε; εἴληψαι λιχνεύων περὶ τὰς πέτρας, ἔνθα λήσειν ἤλπισας ὑποδεδυκώς; ἀλλὰ νῦν ἔσῃ φανερὸς ἅπασιν ἐκ τῶν βραγχίων ἀπηρτημένος. ἐξέλωμεν τὸ ἄγκιστρον καὶ τὸ δέλεαρ. μὰ Δί’ ἔπιεν. τουτὶ κενόν σοι τὸ ἄγκιστρον· ἡ δ’ ἰσχὰς ἤδη προσέσχηται καὶ τὸ χρυσίον ἐν τῇ κοιλίᾳ.", "st": "25.48"}, {"sp": "N", "t": "<em>Παρρησιάδης.<\/em> ἐξεμεσάτω νὴ Δία, ὡς καὶ ἐπ’ ἄλλους δελεάσωμεν. εὖ ἔχει· τί φής, ὦ Διόγενες; οἶσθα τοῦτον ὅστις ἐστίν, ἢ προσήκει τί σοι ἁνήρ;", "st": "25.48"}, {"sp": "N", "t": "<em>Διογένης.<\/em> οὐδαμῶς.", "st": "25.48"}, {"sp": "N", "t": "<em>Παρρησιάδης.<\/em> τί οὖν; πόσου ἄξιον αὐτὸν χρὴ φάναι; ἐγὼ μὲν γὰρ δύ’ ὀβολῶν πρῴην αὐτὸν ἐτιμησάμην.", "st": "25.48"}, {"sp": "N", "t": "<em>Διογένης.<\/em> πολὺ λέγεις· ἄβρωτός τε γάρ ἐστιν καὶ εἰδεχθὴς καὶ σκληρὸς καὶ ἄτιμος· ἄφες αὐτὸν ἐπὶ κεφαλὴν κατὰ τῆς πέτρας· σὺ δὲ ἄλλον ἀνάσπασον καθεὶς τὸ ἄγκιστρον. ἐκεῖνο μέντοι· ὅρα, ὦ Παρρησιάδη, μὴ καμπτόμενός σοι ὁ κάλαμος ἀποκλασθῇ.", "st": "25.48"}, {"sp": "N", "t": "<em>Παρρησιάδης.<\/em> θάρρει, ὦ Διόγενες· κοῦφοί εἰσι καὶ τῶν ἀφύων ἐλαφρότεροι.", "st": "25.48"}, {"sp": "N", "t": "<em>Διογένης.<\/em> νὴ Δί’, ἀφυέστατοί γε· ἀνάσπα δὲ ὅμως.", "st": "25.48"}, {"sp": "N", "t": "<em>Παρρησιάδης.<\/em> ἰδού τις ἄλλος ὑπόπλατος ὥσπερ ἡμίτομος ἰχθὺς πρόσεισιν, ψῆττά τις, κεχηνὼς εἰς τὸ ἄγκιστρον· κατέπιεν, ἔχεται, ἀνεσπάσθω. τίς ἐστιν;", "st": "25.49"}, {"sp": "N", "t": "<em>Ἔλεγχος.<\/em> ὁ Πλατωνικὸς εἶναι λέγων.", "st": "25.49"}, {"sp": "N", "t": "<em>Παρρησιάδης.<\/em> καὶ σύ, ὦ κατάρατε, ἥκεις ἐπὶ τὸ χρυσίον; τί φής, ὦ Πλάτων; τί ποιῶμεν αὐτόν;", "st": "25.49"}, {"sp": "N", "t": "<em>Πλάτων.<\/em> ἀπὸ τῆς αὐτῆς πέτρας καὶ οὗτος· ἐπ’ ἄλλον καθείσθω.", "st": "25.50"}, {"sp": "N", "t": "<em>Παρρησιάδης.<\/em> καὶ μὴν ὁρῶ τινα πάγκαλον προσιόντα, ὡς ἂν ἐν βυθῷ δόξειεν, ποικίλον τὴν χρόαν, ταινίας τινὰς ἐπὶ τοῦ νώτου ἐπιχρύσους ἔχοντα. ὁρᾷς, ὦ Ἔλεγχε;", "st": "25.50"}, {"sp": "N", "t": "<em>Ἔλεγχος.<\/em> ὁ τὸν Ἀριστοτέλη προσποιούμενος οὗτός ἐστιν.", "st": "25.50"}, {"sp": "N", "t": "<em>Παρρησιάδης.<\/em> ἦλθεν, εἶτα πάλιν ἄπεισιν. περισκοπεῖ ἀκριβῶς, αὖθις ἐπανῆλθεν, ἔχανεν, εἴληπται, ἀνιμήσθω.", "st": "25.50"}, {"sp": "N", "t": "<em>Ἀριστοτέλης.<\/em> μὴ ἀνέρῃ με, ὦ Παρρησιάδη, περὶ αὐτοῦ· ἀγνοῶ γὰρ ὅστις ἐστίν.", "st": "25.50"}, {"sp": "N", "t": "<em>Παρρησιάδης.<\/em> οὐκοῦν καὶ οὗτος, ὦ Ἀριστότελες, κατὰ τῶν πετρῶν.", "st": "25.50"}, {"sp": "N", "t": "ἀλλ’ ἢν ἰδού, πολλούς που τοὺς ἰχθῦς ὁρῶ κατὰ ταὐτὸν ὁμόχροας, ἀκανθώδεις καὶ τὴν ἐπιφάνειαν ἐκτετραχυσμένους, ἐχίνων δυσληπτοτέρους. ἦ που σαγήνης ἐπ’ αὐτοὺς δεήσει;", "st": "25.51"}, {"sp": "N", "t": "<em>Φιλοσοφία.<\/em> ἀλλ’ οὐ πάρεστιν. ἱκανὸν εἰ κἂν ἕνα τινὰ ἐκ τῆς ἀγέλης ἀνασπάσαιμεν. ἥξει δὲ ἐπὶ τὸ ἄγκιστρον δηλαδὴ ὃς ἂν αὐτῶν θρασύτατος ᾖ.", "st": "25.51"}, {"sp": "N", "t": "<em>Ἔλεγχος.<\/em> κάθες, εἰ δοκεῖ, σιδηρώσας γε πρότερον ἐπὶ πολὺ τῆς ὁρμιᾶς, ὡς μὴ ἀποπρίσῃ τοῖς ὀδοῦσι καταπιὼν τὸ χρυσίον.", "st": "25.51"}, {"sp": "N", "t": "<em>Παρρησιάδης.<\/em> καθῆκα. καὶ σὺ δέ, ὦ Πόσειδον, ταχεῖαν ἐπιτέλει τὴν ἄγραν. βαβαί, μάχονται περὶ τοῦ δελέατος, καὶ οἱ μὲν συνάμα πολλοὶ περιτρώγουσι τὴν ἰσχάδα, οἱ δὲ προσφύντες ἔχονται τοῦ χρυσίου. εὖ ἔχει· περιεπάρη τις μάλα καρτερός. φέρ’ ἴδω τίνος ἐπώνυμον σεαυτὸν εἶναι λέγεις; καίτοι γελοῖός εἰμι ἀναγκάζων ἰχθὺν λαλεῖν· ἄφωνοι γὰρ οὗτοί γε. ἀλλὰ σύ, ὦ Ἔλεγχε, εἰπὲ ὅντινα ἔχει διδάσκαλον αὐτοῦ.", "st": "25.51"}, {"sp": "N", "t": "<em>Ἔλεγχος.<\/em> Χρύσιππον τουτονί.", "st": "25.51"}, {"sp": "N", "t": "<em>Παρρησιάδης.<\/em> μανθάνω· διότι χρυσίον προσῆν, οἶμαι, τῷ ὀνόματι. σὺ δ’ οὖν, Χρύσιππε, πρὸς τῆς Ἀθηνᾶς εἰπέ, οἶσθα τοὺς ἄνδρας ἢ τοιαῦτα παραινεῖς αὐτοῖς ποιεῖν;", "st": "25.51"}, {"sp": "N", "t": "<em>Χρύσιππος.<\/em> νὴ Δί’, ὑβριστικὰ ἐρωτᾷς, ὦ Παρρησιάδη, προσήκειν τι ἡμῖν ὑπολαμβάνων τοιούτους ὄντας.", "st": "25.51"}, {"sp": "N", "t": "<em>Παρρησιάδης.<\/em> εὖ γε, ὦ Χρύσιππε, γενναῖος εἶ. οὗτος δὲ καὶ αὐτὸς ἐπὶ κεφαλὴν μετὰ τῶν ἄλλων, ἐπεὶ καὶ ἀκανθώδης ἐστί, καὶ δέος μὴ διαπαρῇ τις τὸν λαιμὸν ἐσθίων.", "st": "25.51"}, {"sp": "N", "t": "<em>Φιλοσοφία.<\/em> ἅλις, ὦ Παρρησιάδη, τῆς ἄγρας, μὴ καί τίς σοι, οἷοι πολλοί εἰσιν, οἴχηται ἀποσπάσας τὸ χρυσίον καὶ τὸ ἄγκιστρον, εἶτά σε ἀποτῖσαι τῇ ἱερείᾳ δεήσῃ. ὥστε ἡμεῖς μὲν ἀπίωμεν περιπατήσουσαι· καιρὸς δὲ καὶ ὑμᾶς ἀπιέναι ὅθεν ἥκετε, μὴ καὶ ὑπερήμεροι γένησθε τῆς προθεσμίας. σφὼ δέ, σὺ καὶ ὁ Ἔλεγχος, ὦ Παρρησιάδη, ἐν κύκλῳ ἐπὶ πάντας αὐτοὺς ἰόντες ἢ στεφανοῦτε ἢ ἐγκάετε, ὡς ἔφην.", "st": "25.52"}, {"sp": "N", "t": "<em>Παρρησιάδης.<\/em> ἔσται ταῦτα, ὦ Φιλοσοφία. χαίρετε, ὦ βέλτιστοι ἀνδρῶν. ἡμεῖς δὲ κατίωμεν, ὦ Ἔλεγχε, καὶ τελῶμεν τὰ παρηγγελμένα.", "st": "25.52"}, {"sp": "N", "t": "<em>Ἔλεγχος.<\/em> ποῖ δὲ καὶ πρῶτον ἀπιέναι δεήσει; μῶν εἰς τὴν Ἀκαδημίαν ἢ εἰς τὴν Στοὰν ἢ ἀπὸ τοῦ Λυκείου ποιησώμεθα τὴν ἀρχήν;", "st": "25.52"}, {"sp": "N", "t": "<em>Παρρησιάδης.<\/em> οὐδὲν διοίσει τοῦτο. πλὴν οἶδά γε ἐγὼ ὡς ὅποι ποτ’ ἂν ἀπέλθωμεν, ὀλίγων μὲν τῶν στεφάνων, πολλῶν δὲ τῶν καυτηρίων δεησόμεθα.", "st": "25.52"}, {"sp": "HDR", "t": "Δὶς κατηγορούμενος"}, {"sp": "N", "t": "<em>Ζεύς.<\/em> ἀλλ’ ἐπιτριβεῖεν ὁπόσοι τῶν φιλοσόφων παρὰ μόνοις τὴν εὐδαιμονίαν φασὶν εἶναι τοῖς θεοῖς. εἰ γοῦν ᾔδεσαν ὁπόσα τῶν ἀνθρώπων ἕνεκα πάσχομεν, οὐκ ἂν ἡμᾶς τοῦ νέκταρος ἢ τῆς ἀμβροσίας ἐμακάριζον Ὁμήρῳ πιστεύσαντες ἀνδρὶ τυφλῷ καὶ γόητι, μάκαρας ἡμᾶς καλοῦντι καὶ τὰ ἐν οὐρανῷ διηγουμένῳ, ὃς οὐδὲ τὰ ἐν τῇ γῇ καθορᾶν ἐδύνατο. αὐτίκα γέ τοι ὁ μὲν Ἥλιος οὑτοσὶ ζευξάμενος τὸ ἅρμα πανήμερος τὸν οὐρανὸν περιπολεῖ πῦρ ἐνδεδυκὼς καὶ τῶν ἀκτίνων ἀποστίλβων, οὐδ’ ὅσον κνήσασθαι τὸ οὖς, φασί, σχολὴν ἄγων· ἢν γάρ τι κἂν ὀλίγον ἐπιρρᾳθυμήσας λάθῃ, ἀφηνιάσαντες οἱ ἵπποι καὶ τῆς ὁδοῦ παρατραπόμενοι κατέφλεξαν τὰ πάντα. ἡ Σελήνη δὲ ἄγρυπνος καὶ αὐτὴ περίεισιν φαίνουσα τοῖς κωμάζουσιν καὶ τοῖς ἀωρὶ ἀπὸ τῶν δείπνων ἐπανιοῦσιν. ὁ Ἀπόλλων τε αὖ πολυπράγμονα τὴν τέχνην ἐπανελόμενος ὀλίγου δεῖν τὰ ὦτα ἐκκεκώφηται πρὸς τῶν ἐνοχλούντων κατὰ χρείαν τῆς μαντικῆς, καὶ ἄρτι μὲν αὐτῷ ἐν Δελφοῖς ἀναγκαῖον εἶναι, μετ’ ὀλίγον δὲ εἰς Κολοφῶνα θεῖ, κἀκεῖθεν εἰς Ξάνθον μεταβαίνει καὶ δρομαῖος αὖθις εἰς Δῆλον ἢ εἰς Βραγχίδας· καὶ ὅλως ἔνθα ἂν ἡ πρόμαντις πιοῦσα τοῦ ἱεροῦ νάματος καὶ μασησαμένη τῆς δάφνης καὶ τὸν τρίποδα διασείσασα κελεύῃ παρεῖναι, ἄοκνον χρὴ αὐτίκα μάλα παρεστάναι συνείροντα τοὺς χρησμοὺς ἢ οἴχεσθαί οἱ τὴν δόξαν τῆς τέχνης. ἐῶ γὰρ λέγειν ὁπόσα ἐπὶ πείρᾳ τῆς μαντικῆς ἐπιτεχνῶνται αὐτῷ ἄρνεια κρέα καὶ χελώνας εἰς τὸ αὐτὸ ἕψοντες, ὥστε εἰ μὴ τὴν ῥῖνα ὀξὺς ἦν, κἂν ἀπῆλθεν αὐτοῦ ὁ Λυδὸς καταγελῶν. ὁ μὲν γὰρ Ἀσκληπιὸς ὑπὸ τῶν νοσούντων ἐνοχλούμενος “ὁρῇ τε δεινὰ θιγγάνει τε ἀηδέων ἐπ’ ἀλλοτρίῃσί τε συμφορῇσιν ἰδίας καρποῦται λύπας.” τί γὰρ ἂν ἢ τοὺς Ἀνέμους φυτουργοῦντας λέγοιμι καὶ παραπέμποντας τὰ πλοῖα καὶ τοῖς λικμῶσιν ἐπιπνέοντας, ἢ τὸν Ὕπνον ἐπὶ πάντας πετόμενον, ἢ τὸν Ὄνειρον μετὰ τοῦ Ὕπνου διανυκτερεύοντα καὶ ὑποφητεύοντα αὐτῷ; πάντα γὰρ ταῦτα ὑπὸ φιλανθρωπίας οἱ θεοὶ πονοῦσιν, πρὸς τὸν ἐπὶ τῆς γῆς βίον ἕκαστος συντελοῦντες.", "st": "26.1"}, {"sp": "N", "t": "καίτοι τὰ μὲν τῶν ἄλλων μέτρια· ἐγὼ δὲ αὐτὸς ὁ πάντων βασιλεὺς καὶ πατὴρ ὅσας μὲν ἀηδίας ἀνέχομαι, ὅσα δὲ πράγματα ἔχω πρὸς τοσαύτας φροντίδας διῃρημένος· ᾧ πρῶτα μὲν τὰ τῶν ἄλλων θεῶν ἔργα ἐπισκοπεῖν ἀναγκαῖον ὁπόσοι τι ἡμῖν συνδιαπράττουσι τῆς ἀρχῆς, ὡς μὴ βλακεύωσιν ἐν αὐτοῖς, ἔπειτα δὲ καὶ αὐτῷ μυρία ἄττα πράττειν καὶ σχεδὸν ἀνέφικτα ὑπὸ λεπτότητος· οὐ γὰρ μόνον τὰ κεφάλαια ταῦτα τῆς διοικήσεως, ὑετοὺς καὶ χαλάζας καὶ πνεύματα καὶ ἀστραπὰς αὐτὸς οἰκονομησάμενος καὶ διατάξας πέπαυμαι τῶν ἐπὶ μέρους φροντίδων ἀπηλλαγμένος, ἀλλά με δεῖ καὶ ταῦτα μὲν ποιεῖν ἀποβλέπειν δὲ κατὰ τὸν αὐτὸν χρόνον ἁπανταχόσε καὶ πάντα ἐπισκοπεῖν ὥσπερ τὸν ἐν τῇ Νεμέᾳ βουκόλον, τοὺς κλέπτοντας, τοὺς ἐπιορκοῦντας, τοὺς θύοντας, εἴ τις ἔσπεισε, πόθεν ἡ κνῖσα καὶ ὁ καπνὸς ἀνέρχεται, τίς νοσῶν ἢ πλέων ἐκάλεσεν, καὶ τὸ πάντων ἐπιπονώτατον, ὑφ’ ἕνα καιρὸν ἔν τε Ὀλυμπίᾳ τῇ ἑκατόμβῃ παρεῖναι καὶ ἐν Βαβυλῶνι τοὺς πολεμοῦντας ἐπισκοπεῖν καὶ ἐν Γέταις χαλαζᾶν καὶ ἐν Αἰθίοψιν εὐωχεῖσθαι.", "st": "26.2"}, {"sp": "N", "t": "τὸ δὲ μεμψίμοιρον οὐδὲ οὕτω διαφυγεῖν ῥᾴδιον, ἀλλὰ πολλάκις οἱ μὲν ἄλλοι θεοί τε καὶ ἀνέρες ἱπποκορυσταὶ εὕδουσι παννύχιοι, τὸν Δία δὲ ἐμὲ οὐκ ἔχει νήδυμος ὕπνος· ἢν γάρ τί που καὶ μικρὸν ἐπινυστάσωμεν, ἀληθὴς εὐθὺς ὁ Ἐπίκουρος, ἀπρονοήτους ἡμᾶς ἀποφαίνων τῶν ἐπὶ γῆς πραγμάτων. καὶ ὁ κίνδυνος οὐκ εὐκαταφρόνητος εἰ ταῦτα οἱ ἄνθρωποι πιστεύσουσιν αὐτῷ, ἀλλ’ ἀστεφάνωτοι μὲν ἡμῖν οἱ ναοὶ ἔσονται, ἀκνίσωτοι δὲ αἱ ἀγυιαί, ἄσπονδοι δὲ οἱ κρατῆρες, ψυχροὶ δὲ οἱ βωμοί, καὶ ὅλως ἄθυτα καὶ ἀκαλλιέρητα πάντα καὶ ὁ λιμὸς πολύς. τοιγαροῦν ὥσπερ οἱ κυβερνῆται ὑψηλὸς μόνος ἐπὶ τῆς πρύμνης ἕστηκα τὸ πηδάλιον ἔχων ἐν ταῖν χεροῖν, καὶ οἱ μὲν ἐπιβάται μεθύοντες εἰ τύχοι ἐγκαθεύδουσιν, ἐγὼ δὲ ἄγρυπνος καὶ ἄσιτος ὑπὲρ ἁπάντων “μερμηρίζω κατὰ φρένα καὶ κατὰ θυμὸν” μόνῳ τῷ δεσπότης εἶναι δοκεῖν τετιμημένος.", "st": "26.2"}, {"sp": "N", "t": "ὥστε ἡδέως ἂν ἐροίμην τοὺς φιλοσόφους, οἳ μόνους τοὺς θεοὺς εὐδαιμονίζουσιν, πότε καὶ σχολάζειν ἡμᾶς τῷ νέκταρι καὶ τῇ ἀμβροσίᾳ νομίζουσι μυρία ὅσα ἔχοντας πράγματα.", "st": "26.3"}, {"sp": "N", "t": "Ἰδού γέ τοι ὑπ’ ἀσχολίας τοσαύτας ἑώλους δίκας φυλάττομεν ἀποκειμένας ὑπ’ εὐρῶτος ἤδη καὶ ἀραχνίων διεφθαρμένας, καὶ μάλιστα ὁπόσαι ταῖς ἐπιστήμαις καὶ τέχναις πρὸς ἀνθρώπους τινὰς συνεστᾶσιν, πάνυ παλαιὰς ἐνίας αὐτῶν. οἱ δὲ κεκράγασιν ἁπανταχόθεν καὶ ἀγανακτοῦσιν καὶ τὴν δίκην ἐπιβοῶνται κἀμὲ τῆς βραδυτῆτος αἰτιῶνται, ἀγνοοῦντες ὡς οὐκ ὀλιγωρίᾳ τὰς κρίσεις ὑπερημέρους συνέβη γενέσθαι, ἀλλ’ ὑπὸ τῆς εὐδαιμονίας ᾗ συνεῖναι ἡμᾶς ὑπολαμβάνουσιν. τοῦτο γὰρ τὴν ἀσχολίαν καλοῦσιν.", "st": "26.3"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> καὐτός, ὦ Ζεῦ, πολλὰ τοιαῦτα ἐπὶ τῆς γῆς ἀκούων δυσχεραινόντων λέγειν πρὸς σὲ οὐκ ἐτόλμων. ἐπεὶ δὲ σὺ περὶ τούτων τοὺς λόγους ἐνέβαλες, καὶ δὴ λέγω. πάνυ ἀγανακτοῦσιν, ὦ πάτερ, καὶ σχετλιάζουσιν καὶ εἰς τὸ φανερὸν μὲν οὐ τολμῶσι λέγειν, ὑποτονθορύζουσι δὲ συγκεκυφότες αἰτιώμενοι τὸν χρόνον· οὓς ἔδει πάλαι τὰ καθ’ αὑτοὺς εἰδότας στέργειν ἕκαστον τοῖς δεδικασμένοις.", "st": "26.4"}, {"sp": "N", "t": "<em>Ζεύς.<\/em> τί οὖν, ὦ Ἑρμῆ, δοκεῖ; προτίθεμεν αὐτοῖς ἀγορὰν δικῶν, ἢ θέλεις εἰς νέωτα παραγγελοῦμεν;", "st": "26.4"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> οὐ μὲν οὖν, ἀλλὰ ἤδη προθῶμεν.", "st": "26.4"}, {"sp": "N", "t": "<em>Ζεύς.<\/em> οὕτω ποίει· σὺ μὲν κήρυττε καταπτάμενος ὅτι ἀγορὰ δικῶν ἔσται κατὰ τάδε. πάντας ὁπόσοι τὰς γραφὰς ἀπενηνόχασιν, ἥκειν τήμερον εἰς Ἄρειον πάγον, ἐκεῖ δὲ τὴν μὲν Δίκην ἀποκληροῦν σφίσι τὰ δικαστήρια κατὰ λόγον τῶν τιμημάτων ἐξ ἁπάντων Ἀθηναίων· εἰ δέ τις ἄδικον οἴοιτο γεγενῆσθαι τὴν κρίσιν, ἐξεῖναι ἐφέντι ἐπ’ ἐμὲ δικάζεσθαι ἐξ ὑπαρχῆς, ὡς εἰ μηδὲ τὸ παράπαν ἐδεδίκαστο. σὺ δέ, ὦ θύγατερ, καθεζομένη παρὰ τὰς σεμνὰς θεὰς ἀποκλήρου τὰς δίκας καὶ ἐπισκόπει τοὺς δικάζοντας.", "st": "26.4"}, {"sp": "N", "t": "<em>Δίκη.<\/em> αὖθις εἰς τὴν γῆν, ἵν’ ἐξελαυνομένη πρὸς αὐτῶν δραπετεύω πάλιν ἐκ τοῦ βίου τὴν Ἀδικίαν ἐπιγελῶσαν οὐ φέρουσα;", "st": "26.5"}, {"sp": "N", "t": "<em>Ζεύς.<\/em> χρηστὰ ἐλπίζειν σε δεῖ· πάντως γὰρ ἤδη πεπείκασιν αὐτοὺς οἱ φιλόσοφοι σὲ τῆς Ἀδικίας προτιμᾶν, καὶ μάλιστα ὁ τοῦ Σωφρονίσκου τὸ δίκαιον ὑπερεπαινέσας καὶ ἀγαθῶν τὸ μέγιστον ἀποφήνας.", "st": "26.5"}, {"sp": "N", "t": "<em>Δίκη.<\/em> Πάνυ γοῦν ὃν φὴς αὐτὸν ἐκεῖνον ὤνησαν οἱ περὶ ἐμοῦ λόγοι, ὃς παραδοθεὶς τοῖς ἕνδεκα καὶ εἰς τὸ δεσμωτήριον ἐμπεσὼν ἔπιεν ἄθλιος τοῦ κωνείου, μηδὲ τὸν ἀλεκτρυόνα τῷ Ἀσκληπιῷ ἀποδεδωκώς· παρὰ τοσοῦτον ὑπερέσχον οἱ κατήγοροι τἀναντία περὶ τῆς Ἀδικίας φιλοσοφοῦντες.", "st": "26.5"}, {"sp": "N", "t": "<em>Ζεύς.<\/em> ξένα ἔτι τοῖς πολλοῖς τὰ τῆς φιλοσοφίας ἦν τότε, καὶ ὀλίγοι ἦσαν οἱ φιλοσοφοῦντες, ὥστε εἰκότως εἰς τὸν Ἄνυτον καὶ Μέλητον ἔρρεπεν τὰ δικαστήρια. τὸ δὲ νῦν εἶναι, οὐχ ὁρᾷς ὅσοι τρίβωνες καὶ βακτηρίαι καὶ πῆραι; καὶ ἁπανταχοῦ πώγων βαθὺς καὶ βιβλίον ἐν τῇ ἀριστερᾷ, καὶ πάντες ὑπὲρ σοῦ φιλοσοφοῦσι, μεστοὶ δὲ οἱ περίπατοι κατὰ ἴλας καὶ φάλαγγας ἀλλήλοις ἀπαντώντων, καὶ οὐδεὶς ὅστις οὐ τρόφιμος τῆς ἀρετῆς εἶναι δοκεῖν βούλεται. πολλοὶ γοῦν τὰς τέχνας ἀφέντες ἃς εἶχον τέως, ἐπὶ τὴν πήραν ᾄξαντες καὶ τὸ τριβώνιον, καὶ τὸ σῶμα πρὸς τὸν ἥλιον εἰς τὸ Αἰθιοπικὸν ἐπιχράναντες αὐτοσχέδιοι φιλόσοφοι ἐκ σκυτοτόμων ἢ τεκτόνων περινοστοῦσι σὲ καὶ τὴν σὴν ἀρετὴν ἐπαινοῦντες. ὥστε κατὰ τὴν παροιμίαν, θᾶττον ἄν τις ἐν πλοίῳ πεσὼν διαμάρτοι ξύλου ἢ ἔνθα ἂν ἀπίδῃ ὁ ὀφθαλμός, ἀπορήσει φιλοσόφου.", "st": "26.6"}, {"sp": "N", "t": "<em>Δίκη.<\/em> καὶ μὴν οὗτοί με, ὦ Ζεῦ, δεδίττονται πρὸς ἀλλήλους ἐρίζοντες καὶ ἀγνωμονοῦντες ἐν αὐτοῖς οἷς περὶ ἐμοῦ διεξέρχονται. φασὶ δὲ καὶ τοὺς πλείστους αὐτῶν ἐν μὲν τοῖς λόγοις προσποιεῖσθαί με, ἐπὶ δὲ τῶν πραγμάτων μηδὲ τὸ παράπαν εἰς τὴν οἰκίαν παραδέχεσθαι, ἀλλὰ δήλους εἶναι ἀποκλείσοντας ἢν ἀφίκωμαί ποτε αὐτοῖς ἐπὶ τὰς θύρας· πάλαι γὰρ τὴν Ἀδικίαν προεπεξενῶσθαι αὐτοῖς.", "st": "26.7"}, {"sp": "N", "t": "<em>Ζεύς.<\/em> οὐ πάντες, ὦ θύγατερ, μοχθηροί εἰσιν· ἱκανὸν δὲ κἂν ἐνίοις τισὶν χρηστοῖς ἐντύχῃς. ἀλλ’ ἄπιτε ἤδη, ὡς κἂν ὀλίγαι τήμερον ἐκδικασθῶσιν.", "st": "26.7"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> προΐωμεν, ὦ Δίκη, ταύτῃ εὐθὺ τοῦ Σουνίου μικρὸν ὑπὸ τὸν Ὑμηττὸν ἐπὶ τὰ λαιὰ τῆς Πάρνηθος, ἔνθα αἱ δύο ἐκεῖναι ἄκραι· σὺ γὰρ ἔοικας ἐκλελῆσθαι πάλαι τὴν ὁδόν. ἀλλὰ τί δακρύεις καὶ σχετλιάζεις; μὴ δέδιθι· οὐδέθ’ ὅμοια τὰ ἐν τῷ βίῳ· τεθνᾶσιν ἐκεῖνοι πάντες οἱ Σκείρωνες καὶ Πιτυοκάμπται καὶ Βουσίριδες καὶ Φαλάριδες οὓς ἐδεδίεις τότε, νυνὶ δὲ Σοφία καὶ Ἀκαδήμεια καὶ Στοὰ κατέχουσι πάντα καὶ πανταχοῦ σε ζητοῦσιν καὶ περὶ σοῦ διαλέγονται, κεχηνότες εἴ ποθεν εἰς αὐτοὺς καταπτοῖο πάλιν.", "st": "26.8"}, {"sp": "N", "t": "<em>Δίκη.<\/em> σὺ γοῦν μοι τἀληθές, ὦ Ἑρμῆ, ἂν εἴποις μόνος, ἅτε συνὼν αὐτοῖς τὰ πολλὰ καὶ συνδιατρίβων ἔν τε γυμνασίοις καὶ ἐν τῇ ἀγορᾷ — καὶ ἀγοραῖος γὰρ εἶ καὶ ἐν ταῖς ἐκκλησίαις κηρύττεις — ὁποῖοι γεγένηνται καὶ εἰ δυνατή μοι παρ’ αὐτοῖς ἡ μονή.", "st": "26.8"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> νὴ Δία, ἀδικοίην γὰρ ἂν πρὸς ἀδελφήν σε οὖσαν μὴ λέγων. οὐκ ὀλίγα πρὸς τῆς φιλοσοφίας ὠφέληνται οἱ πολλοὶ αὐτῶν· καὶ γὰρ εἰ μηδὲν ἄλλο, αἰδοῖ γοῦν τοῦ σχήματος μετριώτερα διαμαρτάνουσιν. πλὴν ἀλλὰ καὶ μοχθηροῖς τισιν ἐντεύξῃ αὐτῶν — χρὴ γάρ, οἶμαι, τἀληθῆ λέγειν — ἐνίοις δὲ ἡμισόφοις καὶ ἡμιφαύλοις. ἐπεὶ γὰρ αὐτοὺς μετέβαπτεν ἡ σοφία παραλαβοῦσα, ὁπόσοι μὲν εἰς κόρον ἔπιον τῆς βαφῆς, χρηστοὶ ἀκριβῶς ἀπετελέσθησαν ἀμιγεῖς ἑτέρων χρωμάτων, καὶ πρός γε τὴν σὴν ὑποδοχὴν οὗτοι ἑτοιμότατοι· ὅσοι δὲ ὑπὸ τοῦ πάλαι ῥύπου μὴ εἰς βάθος παρεδέξαντο ὁπόσον δευσοποιὸν τοῦ φαρμάκου, τῶν ἄλλων ἀμείνους, ἀτελεῖς δὲ ὅμως καὶ μιξόλευκοι καὶ κατεστιγμένοι καὶ παρδαλωτοὶ τὴν χρόαν. εἰσὶ δ’ οἳ καὶ μόνον ψαύσαντες ἔκτοσθεν τοῦ λέβητος ἄκρῳ τῷ δακτύλῳ καὶ ἐπιχρισάμενοι τῆς ἀσβόλου ἱκανῶς οἴονται καὶ οὗτοι μεταβεβάφθαι. σοὶ μέντοι δῆλον ὅτι μετὰ τῶν ἀρίστων ἡ διατριβὴ ἔσται.", "st": "26.8"}, {"sp": "N", "t": "ἀλλὰ μεταξὺ λόγων ἤδη πλησιάζομεν τῇ Ἀττικῇ· ὥστε τὸ μὲν Σούνιον ἐν δεξιᾷ καταλείπωμεν, εἰς δὲ τὴν ἀκρόπολιν ἀπονεύωμεν ἤδη. καὶ ἐπείπερ καταβεβήκαμεν, αὐτὴ μὲν ἐνταῦθά που ἐπὶ τοῦ πάγου κάθησο εἰς τὴν πνύκα ὁρῶσα καὶ περιμένουσα ἔστ’ ἂν κηρύξω τὰ παρὰ τοῦ Διός, ἐγὼ δὲ εἰς τὴν ἀκρόπολιν ἀναβὰς ῥᾷον οὕτως ἅπαντας ἐκ τοῦ ἐπηκόου προσκαλέσομαι.", "st": "26.9"}, {"sp": "N", "t": "<em>Δίκη.<\/em> μὴ πρότερον ἀπέλθῃς, ὦ Ἑρμῆ, πρὶν εἰπεῖν ὅστις οὗτος ὁ προσιών ἐστιν, ὁ κερασφόρος, ὁ τὴν σύριγγα, ὁ λάσιος ἐκ τοῖς σκελοῖν.", "st": "26.9"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> τί φής; ἀγνοεῖς τὸν Πᾶνα, τῶν Διονύσου θεραπόντων τὸν βακχικώτατον; οὗτος ᾤκει μὲν τὸ πρόσθεν ἀνὰ τὸ Παρθένιον, ὑπὸ δὲ τὸν Δάτιδος ἐπίπλουν καὶ τὴν Μαραθῶνάδε τῶν βαρβάρων ἀπόβασιν ἧκεν ἄκλητος τοῖς Ἀθηναίοις σύμμαχος, καὶ τὸ ἀπ’ ἐκείνου τὴν ὑπὸ τῇ ἀκροπόλει σπήλυγγα ταύτην ἀπολαβόμενος οἰκεῖ μικρὸν ὑπὲρ τοῦ Πελασγικοῦ εἰς τὸ μετοίκιον συντελῶν. καὶ νῦν ὡς τὸ εἰκὸς ἰδὼν ἡμᾶς ἐκ γειτόνων πρόσεισι δεξιωσόμενος.", "st": "26.9"}, {"sp": "N", "t": "<em>Πάν.<\/em> χαίρετε, ὦ Ἑρμῆ καὶ Δίκη.", "st": "26.10"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> καὶ σύ γε, ὦ Πάν, μουσικώτατε καὶ πηδητικώτατε Σατύρων ἁπάντων, Ἀθήνησι δὲ καὶ πολεμικώτατε.", "st": "26.10"}, {"sp": "N", "t": "<em>Πάν.<\/em> τίς δὲ ὑμᾶς, ὦ Ἑρμῆ, χρεία δεῦρο ἤγαγεν;", "st": "26.10"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> αὕτη σοι διηγήσεται τὰ πάντα· ἐγὼ δὲ ἐπὶ τὴν ἀκρόπολιν ἄπειμι καὶ τὸ κήρυγμα.", "st": "26.10"}, {"sp": "N", "t": "<em>Δίκη.<\/em> ὁ Ζεύς, ὦ Πάν, κατέπεμψέ με ἀποκληρώσουσαν τὰς δίκας. σοὶ δὲ πῶς τὰ ἐν Ἀθήναις ἔχει;", "st": "26.10"}, {"sp": "N", "t": "<em>Πάν.<\/em> τὸ μὲν ὅλον οὐ κατ’ ἀξίαν πράττω παρ’ αὐτοῖς, ἀλλὰ πολὺ καταδεέστερον τῆς ἐλπίδος, καὶ ταῦτα τηλικοῦτον ἀπωσάμενος κυδοιμὸν τὸν ἐκ τῶν βαρβάρων. ὅμως δὲ δὶς ἢ τρὶς τοῦ ἔτους ἀνιόντες ἐπιλεξάμενοι τράγον ἔνορχην θύουσί μοι πολλῆς τῆς κινάβρας ἀπόζοντα, εἶτ’ εὐωχοῦνται τὰ κρέα, ποιησάμενοί με τῆς εὐφροσύνης μάρτυρα καὶ ψιλῷ τιμήσαντες τῷ κρότῳ. πλὴν ἀλλ’ ἔχει τινά μοι ψυχαγωγίαν ὁ γέλως αὐτῶν καὶ ἡ παιδιά.", "st": "26.10"}, {"sp": "N", "t": "<em>Δίκη.<\/em> τὰ δ’ ἄλλα, ὦ Πάν, ἀμείνους πρὸς ἀρετὴν ἐγένοντο ὑπὸ τῶν φιλοσόφων;", "st": "26.11"}, {"sp": "N", "t": "<em>Πάν.<\/em> τίνας λέγεις τοὺς φιλοσόφους; ἆρ’ ἐκείνους τοὺς κατηφεῖς, τοὺς συνάμα πολλούς, τοὺς τὸ γένειον ὁμοίους ἐμοί, τοὺς λάλους;", "st": "26.11"}, {"sp": "N", "t": "<em>Δίκη.<\/em> καὶ μάλα.", "st": "26.11"}, {"sp": "N", "t": "<em>Πάν.<\/em> οὐκ οἶδα ὅλως ὅ τι καὶ λέγουσιν οὐδὲ συνίημι τὴν σοφίαν αὐτῶν· ὄρειος γὰρ ἔγωγε καὶ τὰ κομψὰ ταῦτα ῥημάτια καὶ ἀστικὰ οὐ μεμάθηκα, ὦ Δίκη. πόθεν γὰρ ἐν Ἀρκαδίᾳ σοφιστὴς ἢ φιλόσοφος; μέχρι τοῦ πλαγίου καλάμου καὶ τῆς σύριγγος ἐγὼ σοφός, τὰ δ’ ἄλλα αἰπόλος καὶ χορευτὴς καὶ πολεμιστής, ἢν δέῃ. πλὴν ἀλλ’ ἀκούω γε αὐτῶν ἀεὶ κεκραγότων καὶ ἀρετήν τινα καὶ ἰδέας καὶ φύσιν καὶ ἀσώματα διεξιόντων, ἄγνωστα ἐμοὶ καὶ ξένα ὀνόματα. καὶ τὰ πρῶτα μὲν εἰρηνικῶς ἐνάρχονται τῶν πρὸς ἀλλήλους λόγων, προιούσης δὲ τῆς συνουσίας ἐπιτείνουσι τὸ φθέγμα μέχρι πρὸς τὸ ὄρθιον, ὥστε ὑπερδιατεινομένων καὶ ἅμα λέγειν ἐθελόντων τό τε πρόσωπον ἐρυθριᾷ καὶ ὁ τράχηλος οἰδεῖ καὶ αἱ φλέβες ἐξανίστανται ὥσπερ τῶν αὐλητῶν ὁπόταν εἰς στενὸν τὸν αὐλὸν ἐμπνεῖν βιάζωνται. διαταράξαντες γοῦν τοὺς λόγους καὶ τὸ ἐξ ἀρχῆς ἐπισκοπούμενον συγχέαντες ἀπίασι λοιδορησάμενοι ἀλλήλοις οἱ πολλοί, τὸν ἱδρῶτα ἐκ τοῦ μετώπου ἀγκύλῳ τῷ δακτύλῳ ἀποξυόμενοι, καὶ οὗτος κρατεῖν ἔδοξεν ὃς ἂν μεγαλοφωνότερος αὐτῶν ᾖ καὶ θρασύτερος καὶ διαλυομένων ἀπέλθῃ ὕστερος. πλὴν ἀλλ’ ὅ γε λεὼς ὁ πολὺς τεθήπασιν αὐτούς, καὶ μάλιστα ὁπόσους μηδὲν τῶν ἀναγκαιοτέρων ἀσχολεῖ, καὶ παρεστᾶσι πρὸς τὸ θράσος καὶ τὴν βοὴν κεκηλημένοι. ἐμοὶ μὲν οὖν ἀλαζόνες τινὲς ἐδόκουν ἀπὸ τούτων καὶ ἠνιώμην ἐπὶ τῇ τοῦ πώγωνος ὁμοιότητι. εἰ δέ γε δημωφελές τι ἐνῆν τῇ βοῇ αὐτῶν καί τι ἀγαθὸν ἐκ τῶν ῥημάτων ἐκείνων ἀνεφύετο αὐτοῖς, οὐκ ἂν εἰπεῖν ἔχοιμι. πλὴν ἀλλ’ εἴ γε δεῖ μηδὲν ὑποστειλάμενον τἀληθὲς διηγήσασθαι — οἰκῶ γὰρ ἐπὶ σκοπῆς, ὡς ὁρᾷς — πολλοὺς αὐτῶν πολλάκις ἤδη ἐθεασάμην περὶ δείλην ὀψίαν —", "st": "26.11"}, {"sp": "N", "t": "<em>Δίκη.<\/em> ἐπίσχες, ὦ Πάν. οὐχ ὁ Ἑρμῆς σοι κηρύττειν ἔδοξεν;", "st": "26.12"}, {"sp": "N", "t": "<em>Πάν.<\/em> πάνυ μὲν οὖν.", "st": "26.12"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> ἀκούετε λεῴ, ἀγορὰν δικῶν ἀγαθῇ τύχῃ καταστησόμεθα τήμερον Ἐλαφηβολιῶνος ἑβδόμῃ ἱσταμένου. ὁπόσοι γραφὰς ἀπήνεγκαν, ἥκειν εἰς Ἄρειον πάγον, ἔνθα ἡ Δίκη ἀποκληρώσει τὰ δικαστήρια καὶ αὐτὴν παρέσται τοῖς δικάζουσιν· οἱ δικασταὶ ἐξ ἁπάντων Ἀθηναίων· ὁ μισθὸς τριώβολον ἑκάστης δίκης· ἀριθμὸς τῶν δικαστῶν κατὰ λόγον τοῦ ἐγκλήματος. ὁπόσοι δὲ ἀποθέμενοι γραφὴν πρὶν εἰσελθεῖν ἀπέθανον, καὶ τούτους ὁ Αἰακὸς ἀναπεμψάτω. ἢν δέ τις ἄδικα δεδικάσθαι οἴηται, ἐφέσιμον ἀγωνιεῖται τὴν δίκην· ἡ δὲ ἔφεσις ἐπὶ τὸν Δία.", "st": "26.12"}, {"sp": "N", "t": "<em>Πάν.<\/em> βαβαὶ τοῦ θορύβου· ἡλίκον, ὦ Δίκη, ἀνεβόησαν, ὡς δὲ καὶ σπουδῇ συνθέουσιν ἕλκοντες ἀλλήλους πρὸς τὸ ἄναντες εὐθὺ τοῦ Ἀρείου πάγου. καὶ ὁ Ἑρμῆς δὲ ἤδη πάρεστιν. ὥστε ὑμεῖς μὲν ἀμφὶ τὰς δίκας ἔχετε καὶ ἀποκληροῦτε καὶ διακρίνατε ὥσπερ ὑμῖν νόμος, ἐγὼ δὲ ἐπὶ τὸ σπήλαιον ἀπελθὼν συρίξομαί τι μέλος τῶν ἐρωτικῶν ᾧ τὴν Ἠχὼ εἴωθα ἐπικερτομεῖν· ἀκροάσεων δὲ καὶ λόγων τῶν δικανικῶν ἅλις ἔχει μοι ὁσημέραι τῶν ἐν Ἀρείῳ πάγῳ δικαζομένων ἀκούοντι.", "st": "26.12"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> ἄγε, ὦ Δίκη, προσκαλῶμεν.", "st": "26.13"}, {"sp": "N", "t": "<em>Δίκη.<\/em> εὖ λέγεις. ἀθρόοι γοῦν, ὡς ὁρᾷς, προσίασι θορυβοῦντες, ὥσπερ οἱ σφῆκες περιβομβοῦντες τὴν ἄκραν.", "st": "26.13"}, {"sp": "N", "t": "<em>Ἀθηναῖος.<\/em> εἴληφά σε, ὦ κατάρατε.", "st": "26.13"}, {"sp": "N", "t": "<em>Ἄλλος.<\/em> συκοφαντεῖς.", "st": "26.13"}, {"sp": "N", "t": "<em>Ἄλλος.<\/em> δώσεις ποτὲ ἤδη τὴν δίκην.", "st": "26.13"}, {"sp": "N", "t": "<em>Ἄλλος.<\/em> ἐξελέγξω σε δεινὰ εἰργασμένον.", "st": "26.13"}, {"sp": "N", "t": "<em>Ἄλλος.<\/em> ἐμοὶ πρώτῳ ἀποκλήρωσον.", "st": "26.13"}, {"sp": "N", "t": "<em>Ἄλλος.<\/em> ἕπου, μιαρέ, πρὸς τὸ δικαστήριον.", "st": "26.13"}, {"sp": "N", "t": "<em>Ἄλλος.<\/em> μὴ ἄγχε με.", "st": "26.13"}, {"sp": "N", "t": "<em>Δίκη.<\/em> οἶσθα ὃ δράσωμεν, ὦ Ἑρμῆ; τὰς μὲν ἄλλας δίκας εἰς τὴν αὔριον ὑπερβαλώμεθα, τήμερον δὲ κληρῶμεν τὰς τοιαύτας ὁπόσαι τέχναις ἢ βίοις ἢ ἐπιστήμαις πρὸς ἄνδρας εἰσὶν ἐπηγγελμέναι. καί μοι ταύτας ἀνάδος τῶν γραφῶν.", "st": "26.13"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> μέθη κατὰ τῆς Ἀκαδημείας περὶ Πολέμωνος ἀνδραποδισμοῦ.", "st": "26.13"}, {"sp": "N", "t": "<em>Δίκη.<\/em> ἑπτὰ κλήρωσον.", "st": "26.13"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> ἡ Στοὰ κατὰ τῆς Ἡδονῆς ἀδικίας, ὅτι τὸν ἐραστὴν αὐτῆς Διονύσιον ἀπεβουκόλησεν.", "st": "26.13"}, {"sp": "N", "t": "<em>Δίκη.<\/em> πέντε ἱκανοί.", "st": "26.13"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> περὶ Ἀριστίππου Τρυφὴ πρὸς Ἀρετήν.", "st": "26.13"}, {"sp": "N", "t": "<em>Δίκη.<\/em> πέντε καὶ τούτοις δικασάτωσαν.", "st": "26.13"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> Ἀργυραμοιβικὴ δρασμοῦ Διογένει.", "st": "26.13"}, {"sp": "N", "t": "<em>Δίκη.<\/em> τρεῖς ἀποκλήρου μόνους.", "st": "26.13"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> γραφικὴ κατὰ Πύρρωνος λιποταξίου.", "st": "26.13"}, {"sp": "N", "t": "<em>Δίκη.<\/em> ἐννέα κρινάτωσαν.", "st": "26.13"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> βούλει καὶ ταύτας ἀποκληρῶμεν, ὦ Δίκη, τὰς δύο, τὰς πρῴην ἀπενηνεγμένας κατὰ τοῦ ῥήτορος;", "st": "26.14"}, {"sp": "N", "t": "<em>Δίκη.<\/em> τὰς παλαιὰς πρότερον διανύσωμεν· αὗται δὲ εἰς ὕστερον δεδικάσονται.", "st": "26.14"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> καὶ μὴν ὅμοιαί γε καὶ αὗται καὶ τὸ ἔγκλημα, εἰ καὶ νεαρόν, ἀλλὰ παραπλήσιον τοῖς προαποκεκληρωμένοις· ὥστε ἐν τούτοις δικασθῆναι ἄξιον.", "st": "26.14"}, {"sp": "N", "t": "<em>Δίκη.<\/em> ἔοικας, ὦ Ἑρμῆ, χαριζομένῳ τὴν δέησιν. ἀποκληρῶμεν δ’ ὅμως, εἰ δοκεῖ, πλὴν ἀλλὰ ταύτας μόνας· ἱκαναὶ γὰρ αἱ ἀποκεκληρωμέναι. δὸς τὰς γραφάς.", "st": "26.14"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> ῥητορικὴ κακώσεως τῷ Σύρῳ· διάλογος τῷ αὐτῷ ὕβρεως.", "st": "26.14"}, {"sp": "N", "t": "<em>Δίκη.<\/em> τίς δὲ οὗτός ἐστιν; οὐ γὰρ ἐγγέγραπται τοὔνομα.", "st": "26.14"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> οὕτως ἀποκλήρου, τῷ ῥήτορι τῷ Σύρῳ· κωλύσει γὰρ οὐδὲν καὶ ἄνευ τοῦ ὀνόματος.", "st": "26.14"}, {"sp": "N", "t": "<em>Δίκη.<\/em> ἰδοῦ, καὶ τὰς ὑπερορίους ἤδη Ἀθήνησιν ἐν Ἀρείῳ πάγῳ ἀποκληρώσομεν, ἃς ὑπὲρ τὸν Εὐφράτην καλῶς εἶχε δεδικάσθαι; πλὴν ἀλλὰ κλήρου ἕνδεκα τοὺς αὐτοὺς ἑκατέρᾳ τῶν δικῶν.", "st": "26.14"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> εὖ γε, ὦ Δίκη, φείδῃ μὴ πολὺ ἀναλίσκεσθαι τὸ δικαστικόν.", "st": "26.14"}, {"sp": "N", "t": "<em>Δίκη.<\/em> οἱ πρῶτοι καθιζέτωσαν τῇ Ἀκαδημείᾳ καὶ τῇ Μέθῃ· σὺ δὲ τὸ ὕδωρ ἔγχει. προτέρα δὲ σὺ λέγε ἡ Μέθη. τί σιγᾷ καὶ διανεύει; μάθε, ὦ Ἑρμῆ, προσελθών.", "st": "26.15"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> “οὐ δύναμαι,” φησί, “τὸν ἀγῶνα εἰπεῖν ὑπὸ τοῦ ἀκράτου τὴν γλῶτταν πεπεδημένη, μὴ γέλωτα ὄφλω ἐν τῷ δικαστηρίῳ.” μόλις δὲ καὶ ἕστηκεν, ὡς ὁρᾷς.", "st": "26.15"}, {"sp": "N", "t": "<em>Δίκη.<\/em> οὐκοῦν συνήγορον ἀναβιβασάσθω τῶν κοινῶν τούτων τινά· πολλοὶ γὰρ οἱ κἂν ἐπὶ τριωβόλῳ διαρραγῆναι ἕτοιμοι.", "st": "26.15"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> ἀλλ’ οὐδὲ εἷς ἐθελήσει ἔν γε τῷ φανερῷ συναγορεῦσαι Μέθῃ. πλὴν εὐγνώμονά γε ταῦτα ἔοικεν ἀξιοῦν.", "st": "26.15"}, {"sp": "N", "t": "<em>Δίκη.<\/em> τὰ ποῖα;", "st": "26.15"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> “ἡ Ἀκαδήμεια πρὸς ἀμφοτέρους ἀεὶ παρεσκεύασται τοὺς λόγους καὶ τοῦτ’ ἀσκεῖ τἀναντία καλῶς δύνασθαι λέγειν. αὕτη τοίνυν,” φησίν, “ὑπὲρ ἐμοῦ πρότερον εἰπάτω, εἶτα ὕστερον ὑπὲρ ἑαυτῆς ἐρεῖ.”", "st": "26.15"}, {"sp": "N", "t": "<em>Δίκη.<\/em> καινὰ μὲν ταῦτα, εἰπὲ δὲ ὅμως, ὦ Ἀκαδήμεια, τὸν λόγον ἑκάτερον, ἐπεί σοι ῥᾴδιον.", "st": "26.15"}, {"sp": "N", "t": "<em>Ἀκαδήμεια.<\/em> ἀκούετε, ὦ ἄνδρες δικασταί, πρότερα τὰ ὑπὲρ τῆς Μέθης· ἐκείνης γὰρ τό γε νῦν ῥέον. ἠδίκηται ἡ ἀθλία τὰ μέγιστα ὑπὸ τῆς Ἀκαδημείας ἐμοῦ, ἀνδράποδον ὃ μόνον εἶχεν εὔνουν καὶ πιστὸν αὐτῇ, μηδὲν αἰσχρὸν ὧν προστάξειεν οἰόμενον, ἀφαιρεθεῖσα τὸν Πολέμωνα ἐκεῖνον, ὃς μεθ’ ἡμέραν ἐκώμαζεν διὰ τῆς ἀγορᾶς μέσης, ψαλτρίαν ἔχων καὶ κατᾳδόμενος ἕωθεν εἰς ἑσπέραν, μεθύων ἀεὶ καὶ κραιπαλῶν καὶ τὴν κεφαλὴν τοῖς στεφάνοις διηνθισμένος. καὶ ταῦτα ὅτι ἀληθῆ, μάρτυρες Ἀθηναῖοι ἅπαντες, οἳ μηδὲ πώποτε νήφοντα Πολέμωνα εἶδον. ἐπεὶ δὲ ὁ κακοδαίμων ἐπὶ τὰς τῆς Ἀκαδημείας θύρας ἐκώμασεν, ὥσπερ ἐπὶ πάντας εἰώθει, ἀνδραποδισαμένη αὐτὸν καὶ ἀπὸ τῶν χειρῶν τῆς Μέθης ἁρπάσασα μετὰ βίας καὶ πρὸς αὑτὴν ἀγαγοῦσα ὑδροποτεῖν τε κατηνάγκασεν καὶ νήφειν μετεδίδαξεν καὶ τοὺς στεφάνους περιέσπασεν καὶ δέον πίνειν κατακείμενον, ῥημάτια σκολιὰ καὶ δύστηνα καὶ πολλῆς φροντίδος ἀνάμεστα ἐπαίδευσεν· ὥστε ἀντὶ τοῦ τέως ἐπανθοῦντος αὐτῷ ἐρυθήματος ὠχρὸς ὁ ἄθλιος καὶ ῥικνὸς τὸ σῶμα γεγένηται, καὶ τὰς ᾠδὰς ἁπάσας ἀπομαθὼν ἄσιτος ἐνίοτε καὶ διψαλέος εἰς μέσην ἑσπέραν κάθηται ληρῶν ὁποῖα πολλὰ ἡ Ἀκαδήμεια ἐγὼ ληρεῖν διδάσκω. τὸ δὲ μέγιστον, ὅτι καὶ λοιδορεῖται τῇ Μέθῃ πρὸς ἐμοῦ ἐπαρθεὶς καὶ μυρία κακὰ διέξεισι περὶ αὐτῆς.", "st": "26.16"}, {"sp": "N", "t": "εἴρηται σχεδὸν τὰ ὑπὲρ τῆς Μέθης. ἤδη καὶ ὑπὲρ ἐμαυτῆς ἐρῶ, καὶ τὸ ἀπὸ τούτου ἐμοὶ ῥευσάτω.", "st": "26.16"}, {"sp": "N", "t": "<em>Δίκη.<\/em> τί ἄρα πρὸς ταῦτα ἐρεῖ; πλὴν ἀλλ’ ἔγχει τὸ ἴσον ἐν τῷ μέρει.", "st": "26.16"}, {"sp": "N", "t": "<em>Ἀκαδήμεια.<\/em> οὑτωσὶ μὲν ἀκοῦσαι πάνυ εὔλογα, ὦ ἄνδρες δικασταί, ἡ συνήγορος εἴρηκεν ὑπὲρ τῆς Μέθης, ἢν δὲ κἀμοῦ μετ’ εὐνοίας ἀκούσητε, εἴσεσθε ὡς οὐδὲν αὐτὴν ἠδίκηκα.", "st": "26.17"}, {"sp": "N", "t": "τὸν γὰρ Πολέμωνα τοῦτον, ὅν φησιν ἑαυτῆς οἰκέτην εἶναι, πεφυκότα οὐ φαύλως οὐδὲ κατὰ τὴν Μέθην, ἀλλ’ οἰκεῖον ἐμοὶ τὴν φύσιν, προαρπάσασα νέον ἔτι καὶ ἁπαλὸν ὄντα συναγωνιζομένης τῆς Ἡδονῆς, ἥπερ αὐτῇ τὰ πολλὰ ὑπουργεῖ, διέφθειρε τὸν ἄθλιον τοῖς κώμοις καὶ ταῖς ἑταίραις παρασχοῦσα ἔκδοτον, ὡς μηδὲ μικρὸν αὐτῷ τῆς αἰδοῦς ὑπολείπεσθαι. καὶ ἅ γε ὑπὲρ ἑαυτῆς λέγεσθαι μικρὸν ἔμπροσθεν ᾤετο, ταῦτα ὑπὲρ ἐμοῦ μᾶλλον εἰρῆσθαι νομίσατε· περιῄει γὰρ ἕωθεν ὁ ἄθλιος ἐστεφανωμένος, κραιπαλῶν, διὰ τῆς ἀγορᾶς μέσης καταυλούμενος, οὐδέποτε νήφων, κωμάζων ἐπὶ πάντας, ὕβρις τῶν προγόνων καὶ τῆς πόλεως ὅλης καὶ γέλως τοῖς ξένοις.", "st": "26.17"}, {"sp": "N", "t": "ἐπεὶ μέντοι γε παρ’ ἐμὲ ἧκεν, ἐγὼ μὲν ἔτυχον, ὥσπερ εἴωθα ποιεῖν, ἀναπεπταμένων τῶν θυρῶν πρὸς τοὺς παρόντας τῶν ἑταίρων λόγους τινὰς περὶ ἀρετῆς καὶ σωφροσύνης διεξιοῦσα· ὁ δὲ μετὰ τοῦ αὐλοῦ καὶ τῶν στεφάνων ἐπιστὰς τὰ μὲν πρῶτα ἐβόα καὶ συγχεῖν ἡμῶν ἐπειρᾶτο τὴν συνουσίαν ἐπιταράξας τῇ βοῇ· ἐπεὶ δὲ οὐδὲν ἡμεῖς ἐπεφροντίκειμεν αὐτοῦ, κατ’ ὀλίγον — οὐ γὰρ τέλεον ἦν διάβροχος τῇ Μέθῃ — ἀνένηφε πρὸς τοὺς λόγους καὶ ἀφῃρεῖτο τοὺς στεφάνους καὶ τὴν αὐλητρίδα κατεσιώπα καὶ ἐπὶ τῇ πορφυρίδι ᾐσχύνετο, καὶ ὥσπερ ἐξ ὕπνου βαθέος ἀνεγρόμενος ἑαυτόν τε ἑώρα ὅπως διέκειτο καὶ τοῦ πάλαι βίου κατεγίγνωσκεν. καὶ τὸ μὲν ἐρύθημα τὸ ἐκ τῆς Μέθης ἀπήνθει καὶ ἠφανίζετο, ἠρυθρία δὲ κατ’ αἰδῶ τῶν δρωμένων· καὶ τέλος ἀποδρὰς ὥσπερ εἶχεν ηὐτομόλησεν παρ’ ἐμέ, οὔτε ἐπικαλεσαμένης οὔτε βιασαμένης, ὡς αὕτη φησίν, ἐμοῦ, ἀλλ’ ἑκὼν αὐτὸς ἀμείνω ταῦτα εἶναι ὑπολαμβάνων.", "st": "26.17"}, {"sp": "N", "t": "Καί μοι ἤδη κάλει αὐτόν, ὅπως καταμάθητε ὃν τρόπον διάκειται πρὸς ἐμοῦ. — τοῦτον, ὦ ἄνδρες δικασταί, παραλαβοῦσα γελοίως ἔχοντα, μήτε φωνὴν ἀφιέναι μήτε ἑστάναι ὑπὸ τοῦ ἀκράτου δυνάμενον, ὑπέστρεψα καὶ ἀνένηψα καὶ ἀντὶ ἀνδραπόδου κόσμιον ἄνδρα καὶ σώφρονα καὶ πολλοῦ ἄξιον τοῖς Ἕλλησιν ἀπέδειξα· καὶ μοι αὐτός τε χάριν οἶδεν ἐπὶ τούτοις καὶ οἱ προσήκοντες ὑπὲρ αὐτοῦ.", "st": "26.17"}, {"sp": "N", "t": "εἴρηκα· ὑμεῖς δὲ ἤδη σκοπεῖτε ποτέρᾳ ἡμῶν ἄμεινον ἦν αὐτῷ συνεῖναι.", "st": "26.17"}, {"sp": "N", "t": "<em>Δίκη.<\/em> ἄγε δή, μὴ μέλλετε, ψηφοφορήσατε, ἀνάστητε· καὶ ἄλλοις χρὴ δικάζειν.", "st": "26.18"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> πάσαις ἡ Ἀκαδήμεια κρατεῖ πλὴν μιᾶς.", "st": "26.18"}, {"sp": "N", "t": "<em>Δίκη.<\/em> παράδοξον οὐδέν, εἶναί τινα καὶ τῇ Μέθῃ τιθέμενον.", "st": "26.18"}, {"sp": "N", "t": "καθίσατε οἱ τῇ Στοᾷ πρὸς τὴν Ἡδονὴν λαχόντες περὶ τοῦ ἐραστοῦ δικάζειν· ἐγκέχυται τὸ ὕδωρ. ἡ κατάγραφος ἡ τὰ ποικίλα σὺ ἤδη λέγε.", "st": "26.19"}, {"sp": "N", "t": "<em>Στοά.<\/em> οὐκ ἀγνοῶ μέν, ὦ ἄνδρες δικασταί, ὡς πρὸς εὐπρόσωπόν μοι τὴν ἀντίδικον ὁ λόγος ἔσται, ἀλλὰ καὶ ὑμῶν τοὺς πολλοὺς ὁρῶ πρὸς μὲν ἐκείνην ἀποβλέποντας καὶ μειδιῶντας πρὸς αὐτήν, ἐμοῦ δὲ καταφρονοῦντας, ὅτι ἐν χρῷ κέκαρμαι καὶ ἀρρενωπὸν βλέπω καὶ σκυθρωπὴ δοκῶ. ὅμως δέ, ἢν ἐθελήσητε ἀκοῦσαί μου λεγούσης, θαρρῶ πολὺ δικαιότερα ταύτης ἐρεῖν.", "st": "26.20"}, {"sp": "N", "t": "τοῦτο γάρ τοι καὶ τὸ παρὸν ἔγκλημά ἐστιν, ὅτι οὕτως ἑταιρικῶς ἐσκευασμένη τῷ ἐπαγωγῷ τῆς ὄψεως ἐραστὴν ἐμὸν ἄνδρα τότε σώφρονα τὸν Διονύσιον φενακίσασα πρὸς ἑαυτὴν περιέσπασεν, καὶ ἥν γε οἱ πρὸ ὑμῶν δίκην ἐδίκασαν τῇ Ἀκαδημείᾳ καὶ τῇ Μέθῃ, ἀδελφὴ τῆς παρούσης δίκης ἐστίν· ἐξετάζεται γὰρ ἐν τῷ παρόντι πότερα χοίρων δίκην κάτω νενευκότας ἡδομένους χρὴ βιοῦν μηδὲν μεγαλόφρον ἐπινοοῦντας ἢ ἐν δευτέρῳ τοῦ καλῶς ἔχοντος ἡγησαμένους τὸ τερπνὸν ἐλευθέρους ἐλευθέρως φιλοσοφεῖν, μήτε τὸ ἀλγεινὸν ὡς ἄμαχον δεδιότας μήτε τὸ ἡδὺ ἀνδραποδωδῶς προαιρουμένους καὶ τὴν εὐδαιμονίαν ζητοῦντας ἐν τῷ μέλιτι καὶ ταῖς ἰσχάσιν. τὰ τοιαῦτα γὰρ αὕτη δελέατα τοῖς ἀνοήτοις προτείνουσα καὶ μορμολυττομένη τῷ πόνῳ προσάγεται αὐτῶν τοὺς πολλούς, ἐν οἷς καὶ τὸν δείλαιον ἐκεῖνον ἀφηνιάσαι ἡμῶν πεποίηκεν, νοσοῦντα τηρήσασα· οὐ γὰρ ἂν ὑγιαίνων ποτὲ προσήκατο τοὺς παρὰ ταύτης λόγους.", "st": "26.20"}, {"sp": "N", "t": "καίτοι τί ἂν ἔγωγε ἀγανακτοίην κατ’ αὐτῆς, ὅπου μηδὲ τῶν θεῶν φείδεται, ἀλλὰ τὴν ἐπιμέλειαν αὐτῶν διαβάλλει; ὥστε εἰ σωφρονεῖτε, καὶ ἀσεβείας ἂν δίκην λάβοιτε παρ’ αὐτῆς. ἀκούω δὲ ἔγωγε ὡς οὐδὲ αὐτὴ παρεσκεύασται ποιήσασθαι τοὺς λόγους, ἀλλὰ τὸν Ἐπίκουρον ἀναβιβάσεται συναγορεύσοντα· οὕτως ἐντρυφᾷ τῷ δικαστηρίῳ. πλὴν ἀλλὰ ἐκεῖνά γε· αὐτὴν ἐρωτᾶτε, οἵους ἂν οἴεται γενέσθαι τὸν Ἡρακλέα καὶ τὸν ὑμέτερον Θησέα, εἰ προσθέντες τῇ ἡδονῇ ἔφυγον τοὺς πόνους· οὐδὲν γὰρ ἂν ἐκώλυεν μεστὴν ἀδικίας εἶναι τὴν γῆν, ἐκείνων μὴ πονησάντων. ταῦτα εἶπον οὐ πάνυ τοῖς μακροῖς τῶν λόγων χαίρουσα. εἰ δέ γε ἐθελήσειε κατὰ μικρὸν ἀποκρίνασθαί μοι συνερωτωμένη, τάχιστα ἂν γνωσθείη τὸ μηδὲν οὖσα. πλὴν ἀλλὰ ὑμεῖς γε τοῦ ὅρκου μνημονεύσαντες ψηφίσασθε ἤδη τὰ εὔορκα μὴ πιστεύσαντες Ἐπικούρῳ λέγοντι μηδὲν ἐπισκοπεῖν τῶν παρ’ ἡμῖν γιγνομένων τοὺς θεούς.", "st": "26.20"}, {"sp": "N", "t": "<em>Δίκη.<\/em> μετάστηθι. ὁ Ἐπίκουρος ὑπὲρ τῆς Ἡδονῆς λέγε.", "st": "26.20"}, {"sp": "N", "t": "<em>Ἐπίκουρος.<\/em> οὐ μακρά, ὦ ἄνδρες δικασταί, πρὸς ὑμᾶς ἐρῶ· δεῖ γὰρ οὐδὲ πολλῶν μοι τῶν λόγων.", "st": "26.21"}, {"sp": "N", "t": "ἀλλ’ εἰ μὲν ἐπῳδαῖς τισιν ἢ φαρμάκοις ὅν φησιν ἐραστὴν ἑαυτῆς ἡ Στοὰ τὸν Διονύσιον κατηνάγκασεν ταύτης μὲν ἀπέχεσθαι, πρὸς ἑαυτὴν δὲ ἀποβλέπειν ἡ Ἡδονή, φαρμακὶς ἂν εἰκότως ἔδοξεν καὶ ἀδικεῖν ἐκέκριτο ἐπὶ τοὺς ἀλλοτρίους ἐραστὰς μαγγανεύουσα. εἰ δέ τις ἐλεύθερος ἐν ἐλευθέρᾳ τῇ πόλει, μὴ ἀπαγορευόντων τῶν νόμων, τὴν παρὰ ταύτης ἀηδίαν μυσαχθεὶς καὶ ἥν φησι κεφάλαιον τῶν πόνων τὴν εὐδαιμονίαν παραγίγνεσθαι λῆρον οἰηθείς, τοὺς μὲν ἀγκύλους ἐκείνους λόγους καὶ λαβυρίνθοις ὁμοίους ἀπέφυγε, πρὸς δὲ τὴν Ἡδονὴν ἄσμενος ἐδραπέτευσεν ὥσπερ δεσμά τινα διακόψας τὰς τῶν λόγων πλεκτάνας, ἀνθρώπινα καὶ οὐ βλακώδη φρονήσας καὶ τὸν μὲν πόνον, ὅπερ ἐστί, πονηρόν, ἡδεῖαν δὲ τὴν ἡδονὴν οἰηθείς, ἀποκλείειν ἐχρῆν αὐτόν, ὥσπερ ἐκ ναυαγίου λιμένι προσνέοντα καὶ γαλήνης ἐπιθυμοῦντα συνωθοῦντας ἐπὶ κεφαλὴν εἰς τὸν πόνον, καὶ ἔκδοτον τὸν ἄθλιον παρέχειν ταῖς ἀπορίαις, καὶ ταῦτα ὥσπερ ἱκέτην ἐπὶ τὸν τοῦ Ἐλέου βωμὸν ἐπὶ τὴν Ἡδονὴν καταφεύγοντα, ἵνα τὴν πολυθρύλητον ἀρετὴν δηλαδὴ ἐπὶ τὸ ὄρθιον ἱδρῶτι πολλῷ ἀνελθὼν ἴδῃ κᾆτα δι’ ὅλου πονήσας τοῦ βίου εὐδαιμονήσῃ μετὰ τὸν βίον;", "st": "26.21"}, {"sp": "N", "t": "καίτοι τίς ἂν κριτὴς δικαιότερος δόξειεν αὐτοῦ ἐκείνου, ὃς τὰ παρὰ τῆς Στοᾶς εἰδώς, εἰ καί τις ἄλλος, καὶ μόνον τέως τὸ καλὸν ἀγαθὸν οἰόμενος εἶναι, μεταμαθὼν ὡς κακὸν ὁ πόνος ἦν, τὸ βέλτιον ἐξ ἀμφοῖν δοκιμάσας εἵλετο; ἑώρα γάρ, οἶμαι, τούτους περὶ τοῦ καρτερεῖν καὶ ἀνέχεσθαι τοὺς πόνους πολλὰ διεξιόντας, ἰδίᾳ δὲ τὴν Ἡδονὴν θεραπεύοντας, καὶ μέχρι τοῦ λόγου νεανιευομένους, οἴκοι δὲ κατὰ τοὺς τῆς Ἡδονῆς νόμους βιοῦντας, αἰσχυνομένους μὲν εἰ φανοῦνται χαλῶντες τοῦ τόνου καὶ προδιδόντες τὸ δόγμα, πεπονθότας δὲ ἀθλίους τὸ τοῦ Ταντάλου, καὶ ἔνθα ἂν λήσειν καὶ ἀσφαλῶς παρανομήσειν ἐλπίσωσιν, χανδὸν ἐμπιμπλαμένους τοῦ ἡδέος. εἰ γοῦν τις αὐτοῖς τὸν τοῦ Γύγου δακτύλιον ἔδωκεν, ὡς περιθεμένους μὴ ὁρᾶσθαι, ἢ τὴν τοῦ Ἄϊδος κυνῆν, εὖ οἶδ’ ὅτι μακρὰ χαίρειν τοῖς πόνοις φράσαντες ἐπὶ τὴν Ἡδονὴν ὠθοῦντο ἂν καὶ ἐμιμοῦντο ἅπαντες τὸν Διονύσιον, ὃς μέχρι μὲν τῆς νόσου ἤλπιζεν ὠφελήσειν τι αὐτὸν τοὺς περὶ τῆς καρτερίας λόγους· ἐπεὶ δὲ ἤλγησεν καὶ ἐνόσησεν καὶ ὁ πόνος ἀληθέστερος αὐτοῦ καθίκετο, ἰδὼν τὸ σῶμα τὸ ἑαυτοῦ ἀντιφιλοσοφοῦν τῇ Στοᾷ καὶ τἀναντία δογματίζον, αὐτῷ μᾶλλον ἢ τούτοις ἐπίστευσεν καὶ ἔγνω ἄνθρωπος ὢν καὶ ἀνθρώπου σῶμα ἔχων, καὶ διετέλεσεν οὐχ ὡς ἀνδριάντι αὐτῷ χρώμενος, εἰδὼς ὅτι ὃς ἂν ἄλλως λέγῃ καὶ Ἡδονῆς κατηγορῇ,<br>λόγοισι χαίρει, τὸν δὲ νοῦν ἐκεῖς’ ἔχει.<br>εἴρηκα· ὑμεῖς δ’ ἐπὶ τούτοις ψηφοφορήσατε.", "st": "26.21"}, {"sp": "N", "t": "<em>Στοά.<\/em> μηδαμῶς, ἀλλ’ ὀλίγα μοι συνερωτῆσαι ἐπιτρέψατε.", "st": "26.22"}, {"sp": "N", "t": "<em>Ἐπίκουρος.<\/em> Ἐρώτησον· ἀποκρινοῦμαι γάρ.", "st": "26.22"}, {"sp": "N", "t": "<em>Στοά.<\/em> κακὸν ἡγῇ τὸν πόνον;", "st": "26.22"}, {"sp": "N", "t": "<em>Ἐπίκουρος.<\/em> ναί.", "st": "26.22"}, {"sp": "N", "t": "<em>Στοά.<\/em> τὴν ἡδονὴν δὲ ἀγαθόν;", "st": "26.22"}, {"sp": "N", "t": "<em>Ἐπίκουρος.<\/em> πάνυ μὲν οὖν.", "st": "26.22"}, {"sp": "N", "t": "<em>Στοά.<\/em> τί δέ; οἶσθα τί διάφορον καὶ ἀδιάφορον καὶ προηγμένον καὶ ἀποπροηγμένον;", "st": "26.22"}, {"sp": "N", "t": "<em>Ἐπίκουρος.<\/em> μάλιστα.", "st": "26.22"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> οὔ φασιν, ὦ Στοά, συνιέναι οἱ δικασταὶ τὰ δισύλλαβα ταῦτα ἐρωτήματα· ὥστε ἡσυχίαν ἄγετε. ψηφοφοροῦσι γάρ.", "st": "26.22"}, {"sp": "N", "t": "<em>Στοά.<\/em> καὶ μὴν ἐκράτησα ἄν, εἰ συνηρώτησα ἐν τῷ τρίτῳ τῶν ἀναποδείκτων σχήματι.", "st": "26.22"}, {"sp": "N", "t": "<em>Δίκη.<\/em> τίς ὑπερέσχεν;", "st": "26.22"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> πάσαις ἡ Ἡδονή.", "st": "26.22"}, {"sp": "N", "t": "<em>Στοά.<\/em> ἐφίημι ἐπὶ τὸν Δία.", "st": "26.22"}, {"sp": "N", "t": "<em>Δίκη.<\/em> τύχῃ τῇ ἀγαθῇ. σὺ δὲ ἄλλους κάλει.", "st": "26.22"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> περὶ Ἀριστίππου Ἀρετὴ καὶ Τρυφή, καὶ Ἀρίστιππος δὲ αὐτὸς παρέστω.", "st": "26.23"}, {"sp": "N", "t": "<em>Ἀρετή.<\/em> προτέραν ἐμὲ χρὴ τὴν Ἀρετὴν λέγειν· ἐμὸς γάρ ἐστιν Ἀρίστιππος, ὡς δηλοῦσιν οἱ λόγοι καὶ τὰ ἔργα.", "st": "26.23"}, {"sp": "N", "t": "<em>Τρυφή.<\/em> οὐ μὲν οὖν, ἀλλ’ ἐμὲ τὴν Τρυφήν· ἐμὸς γὰρ ὁ ἀνήρ, ὡς ἔστιν ὁρᾶν ἀπὸ τῶν στεφάνων καὶ τῆς πορφυρίδος καὶ τῶν μύρων.", "st": "26.23"}, {"sp": "N", "t": "<em>Δίκη.<\/em> μὴ φιλονεικεῖτε· ὑπερκείσεται γὰρ καὶ αὕτη ἡ δίκη ἔστ’ ἂν ὁ Ζεὺς δικάσῃ περὶ τοῦ Διονυσίου· παραπλήσιον γάρ τι καὶ τοῦτο ἔοικεν εἶναι. ὥστ’ ἐὰν μὲν ἡ Ἡδονὴ κρατήσῃ, καὶ τὸν Ἀρίστιππον ἕξει ἡ Τρυφή· νικώσης δὲ αὖ τῆς Στοᾶς, καὶ οὗτος ἔσται τῆς Ἀρετῆς κεκριμένος. ὥστε ἄλλοι παρέστωσαν. τὸ δεῖνα μέντοι, μὴ λαμβανέτωσαν οὗτοι τὸ δικαστικόν· ἀδίκαστος γὰρ ἡ δίκη μεμένηκεν αὐτοῖς.", "st": "26.23"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> μάτην οὖν ἀνεληλυθότες ὦσι γέροντες ἄνδρες οὕτω μακρὰν τὴν ἀνάβασιν;", "st": "26.23"}, {"sp": "N", "t": "<em>Δίκη.<\/em> ἱκανόν, εἰ τριτημόριον λάβοιεν. ἄπιτε, μὴ ἀγανακτεῖτε, αὖθις δικάσετε.", "st": "26.23"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> Διογένη Σινωπέα παρεῖναι καιρός, καὶ σὺ ἡ Ἀργυραμοιβικὴ λέγε.", "st": "26.24"}, {"sp": "N", "t": "<em>Διογένης.<\/em> καὶ μὴν ἄν γε μὴ παύσηται ἐνοχλοῦσα, ὦ Δίκη, οὐκέτι δρασμοῦ δικάσεταί μοι, ἀλλὰ πολλῶν καὶ βαθέων τραυμάτων· ἐγὼ γὰρ αὐτίκα μάλα πατάξας τῷ ξύλῳ —", "st": "26.24"}, {"sp": "N", "t": "<em>Δίκη.<\/em> τί τοῦτο; πέφευγεν ἡ Ἀργυραμοιβική, ὁ δὲ διώκει ἐπηρμένος τὸ βάκτρον. οὐ μέτριόν τι κακὸν ἡ ἀθλία ἔοικε λήψεσθαι. τὸν Πύρρωνα κήρυττε.", "st": "26.24"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> ἀλλ’ ἡ μὲν Γραφικὴ πάρεστιν, ὦ Δίκη, ὁ Πύρρων δὲ οὐδὲ τὴν ἀρχὴν ἀνελήλυθεν, καὶ ἐῴκει τοῦτο πράξειν.", "st": "26.25"}, {"sp": "N", "t": "<em>Δίκη.<\/em> διὰ τί, ὦ Ἑρμῆ;", "st": "26.25"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> ὅτι οὐδὲν ἡγεῖται κριτήριον ἀληθὲς εἶναι.", "st": "26.25"}, {"sp": "N", "t": "<em>Δίκη.<\/em> τοιγαροῦν ἐρήμην αὐτοῦ καταδικασάτωσαν. τὸν λογογράφον ἤδη κάλει τὸν Σύρον. καίτοι πρῴην ἀπηνέχθησαν κατ’ αὐτοῦ αἱ γραφαί, καὶ οὐδὲν ἤπειγεν ἤδη κεκρίσθαι. πλὴν ἀλλ’ ἐπεὶ ἔδοξεν, προτέραν εἰσάγαγε τῆς Ῥητορικῆς τὴν δίκην. βαβαί, ὅσοι συνεληλύθασιν ἐπὶ τὴν ἀκρόασιν.", "st": "26.25"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> εἰκότως, ὦ Δίκη· τό τε γὰρ μὴ ἕωλον εἶναι τὴν κρίσιν, ἀλλὰ καινὴν καὶ ξένην, χθές, ὥσπερ ἔφης, ἐπηγγελμένην, καὶ τὸ ἐλπίζειν ἀκούσεσθαι Ῥητορικῆς μὲν καὶ Διαλόγου ἐν τῷ μέρει κατηγορούντων, ἀπολογουμένου δὲ πρὸς ἀμφοτέρους τοῦ Σύρου, τοῦτο πολλοὺς ἐπήγαγε τῷ δικαστηρίῳ. πλὴν ἀλλὰ ἄρξαι ποτέ, ὦ Ῥητορική, τῶν λόγων.", "st": "26.25"}, {"sp": "N", "t": "<em>Ῥητορική.<\/em> πρῶτον μέν, ὦ ἄνδρες Ἀθηναῖοι, τοῖς θεοῖς εὔχομαι πᾶσι καὶ πάσαις, ὅσην εὔνοιαν ἔχουσα διατελῶ τῇ τε πόλει καὶ πᾶσιν ὑμῖν, τοσαύτην ὑπάρξαι μοι παρ’ ὑμῶν εἰς τουτονὶ τὸν ἀγῶνα, ἔπειθ’ ὅπερ ἐστὶ μάλιστα δίκαιον, τοῦτο παραστῆσαι τοὺς θεοὺς ὑμῖν, τὸν μὲν ἀντίδικον σιωπᾶν κελεύειν, ἐμὲ δὲ ὡς προῄρημαι καὶ βεβούλημαι τὴν κατηγορίαν ἐᾶσαι ποιήσασθαι. οὐχὶ δὲ ταὐτὰ παρίσταταί μοι γιγνώσκειν ὅταν τε εἰς ἃ πέπονθα ἀποβλέψω καὶ ὅταν εἰς τοὺς λόγους οὓς ἀκούω· τοὺς μὲν γὰρ λόγους ὡς ὁμοιοτάτους τοῖς ἐμοῖς οὗτος ἐρεῖ πρὸς ὑμᾶς, τὰ δὲ πράγματα εἰς τοῦτο προήκοντα ὄψεσθε ὥστε ὅπως μὴ χεῖρόν τι πείσομαι πρὸς αὐτοῦ σκέψασθαι δέον. ἀλλὰ γὰρ ἵνα μὴ μακρὰ προοιμιάζωμαι τοῦ ὕδατος πάλαι εἰκῆ ῥέοντος, ἄρξομαι τῆς κατηγορίας.", "st": "26.26"}, {"sp": "N", "t": "ἐγὼ γάρ, ὦ ἄνδρες δικασταί, τουτονὶ κομιδῇ μειράκιον ὄντα, βάρβαρον ἔτι τὴν φωνὴν καὶ μονονουχὶ κάνδυν ἐνδεδυκότα εἰς τὸν Ἀσσύριον τρόπον, περὶ τὴν Ἰωνίαν εὑροῦσα πλαζόμενον ἔτι καὶ ὅ τι χρήσαιτο ἑαυτῷ οὐκ εἰδότα παραλαβοῦσα ἐπαίδευσα. καὶ ἐπειδὴ ἐδόκει μοι εὐμαθὴς εἶναι καὶ ἀτενὲς ὁρᾶν εἰς ἐμέ — ὑπέπτησσε γὰρ τότε καὶ ἐθεράπευεν καὶ μόνην ἐθαύμαζεν — ἀπολιποῦσα τοὺς ἄλλους ὁπόσοι ἐμνήστευόν με πλούσιοι καὶ καλοὶ καὶ λαμπροὶ τὰ προγονικά, τῷ ἀχαρίστῳ τούτῳ ἐμαυτὴν ἐνεγγύησα πένητι καὶ ἀφανεῖ καὶ νέῳ προῖκα οὐ μικρὰν ἐπενεγκαμένη πολλοὺς καὶ θαυμασίους λόγους. εἶτα ἀγαγοῦσα αὐτὸν εἰς τοὺς φυλέτας τοὺς ἐμοὺς παρενέγραψα καὶ ἀστὸν ἀπέφηνα, ὥστε τοὺς διαμαρτόντας τῆς ἐγγύης ἀποπνίγεσθαι. δόξαν δὲ αὐτῷ περινοστεῖν ἐπιδειξομένῳ τοῦ γάμου τὴν εὐποτμίαν, οὐδὲ τότε ἀπελείφθην, ἀλλὰ πανταχοῦ ἑπομένη ἄνω καὶ κάτω περιηγόμην· καὶ κλεινὸν αὐτὸν καὶ ἀοίδιμον ἐποίουν κατακοσμοῦσα καὶ περιστέλλουσα. καὶ τὰ μὲν ἐπὶ τῆς Ἑλλάδος καὶ τῆς Ἰωνίας μέτρια, εἰς δὲ τὴν Ἰταλίαν ἀποδημῆσαι θελήσαντι αὐτῷ τὸν Ἰόνιον συνδιέπλευσα καὶ τὰ τελευταῖα μέχρι τῆς Κελτικῆς συναπάρασα εὐπορεῖσθαι ἐποίησα.", "st": "26.27"}, {"sp": "N", "t": "καὶ μέχρι μὲν πολλοῦ πάντα μοι ἐπείθετο καὶ συνῆν ἀεί, μηδεμίαν νύκτα γιγνόμενος ἀπόκοιτος παρ’ ἡμῶν.", "st": "26.27"}, {"sp": "N", "t": "ἐπεὶ δὲ ἱκανῶς ἐπεσιτίσατο καὶ τὰ πρὸς εὐδοξίαν εὖ ἔχειν αὐτῷ ὑπέλαβεν, τὰς ὀφρῦς ἐπάρας καὶ μέγα φρονήσας ἐμοῦ μὲν ἠμέλησεν, μᾶλλον δὲ τέλεον εἴασεν, αὐτὸς δὲ τὸν γενειήτην ἐκεῖνον, τὸν ἀπὸ τοῦ σχήματος, τὸν Διάλογον, Φιλοσοφίας υἱὸν εἶναι λεγόμενον, ὑπεραγαπήσας μάλα ἐρωτικῶς πρεσβύτερον αὐτοῦ ὄντα, τούτῳ σύνεστιν. καὶ οὐκ αἰσχύνεται τὴν μὲν ἐλευθερίαν καὶ τὸ ἄνετον τῶν ἐν ἐμοὶ λόγων συντεμών, εἰς μικρὰ δὲ καὶ κομματικὰ ἐρωτήματα κατακλείσας ἑαυτόν, καὶ ἀντὶ τοῦ λέγειν ὅ τι βούλεται μεγάλῃ τῇ φωνῇ βραχεῖς τινας λόγους ἀναπλέκων καὶ συλλαβίζων, ἀφ’ ὧν ἀθρόος μὲν ἔπαινος ἢ κρότος πολὺς οὐκ ἂν ἀπαντήσειεν αὐτῷ, μειδίαμα δὲ παρὰ τῶν ἀκουόντων καὶ τὸ ἐπισεῖσαι τὴν χεῖρα ἐντὸς τῶν ὅρων καὶ μικρὰ ἐπινεῦσαι τῇ κεφαλῇ καὶ ἐπιστενάξαι τοῖς λεγομένοις. τοιούτων ἠράσθη ὁ γενναῖος ἐμοῦ καταφρονήσας. φασὶν δὲ αὐτὸν μηδὲ πρὸς τὸν ἐρώμενον τοῦτον εἰρήνην ἄγειν, ἀλλὰ ὅμοια καὶ ἐκεῖνον ὑβρίζειν.", "st": "26.28"}, {"sp": "N", "t": "πῶς οὖν οὐκ ἀχάριστος οὗτος καὶ ἔνοχος τοῖς περὶ τῆς κακώσεως νόμοις, ὃς τὴν μὲν νόμῳ γαμετὴν παρ’ ἧς τοσαῦτα εἴληφεν καὶ δι’ ἣν ἔνδοξός ἐστιν οὕτως ἀτίμως ἀπέλιπεν, καινῶν δὲ ὠρέχθη πραγμάτων, καὶ ταῦτα νῦν ὁπότε μόνην ἐμὲ θαυμάζουσιν καὶ ἐπιγράφονται ἅπαντες προστάτιν ἑαυτῶν; ἀλλ’ ἐγὼ μὲν ἀντέχω τοσούτων μνηστευόντων, καὶ κόπτουσιν αὐτοῖς τὴν θύραν καὶ τοὔνομα ἐπιβοωμένοις μεγάλῃ τῇ φωνῇ οὔτε ἀνοίγειν οὔτε ὑπακούειν βούλομαι· ὁρῶ γὰρ αὐτοὺς οὐδὲν πλέον τῆς βοῆς κομίζοντας. οὗτος δὲ οὐδὲ οὕτως ἐπιστρέφεται πρὸς ἐμέ, ἀλλὰ πρὸς τὸν ἐρώμενον βλέπει, τί, ὦ θεοί, χρηστὸν παρ’ αὐτοῦ λήψεσθαι προσδοκῶν, ὃν οἶδε τοῦ τρίβωνος οὐδὲν πλέον ἔχοντα;", "st": "26.29"}, {"sp": "N", "t": "εἴρηκα, ὦ ἄνδρες δικασταί, ὑμεῖς δέ, ἢν εἰς τὸν ἐμὸν τρόπον τῶν λόγων ἀπολογεῖσθαι θέλῃ, τοῦτο μὲν μὴ ἐπιτρέπετε, — ἄγνωμον γὰρ ἐπ’ ἐμὲ τὴν ἐμὴν μάχαιραν ἀκονᾶν — κατὰ δὲ τὸν αὑτοῦ ἐρώμενον τὸν Διάλογον οὕτως ἀπολογείσθω, ἢν δύνηται.", "st": "26.29"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> τοῦτο μὲν ἀπίθανον· οὐ γὰρ οἷόν τε, ὦ Ῥητορική, μόνον αὐτὸν ἀπολογεῖσθαι κατὰ σχῆμα τοῦ Διαλόγου, ἀλλὰ ῥῆσιν καὶ αὐτὸς εἰπάτω.", "st": "26.29"}, {"sp": "N", "t": "<em>Σῦρος.<\/em> ἐπεὶ καὶ τοῦτο, ὦ ἄνδρες δικασταί, ἡ ἀντίδικος ἠγανάκτησεν, εἰ μακρῷ χρήσομαι τῷ λόγῳ, καὶ ταῦτα τὸ δύνασθαι λέγειν παρ’ ἐκείνης λαβών, πολλὰ μὲν οὐκ ἐρῶ πρὸς ὑμᾶς, τὰ κεφάλαια δὲ αὐτὰ ἀπολυσάμενος τῶν κατηγορηθέντων ὑμῖν ἀπολείψω σκοπεῖν περὶ ἁπάντων. πάντα γὰρ ὁπόσα διηγήσατο περὶ ἐμοῦ ἀληθῆ ὄντα διηγήσατο· καὶ γὰρ ἐπαίδευσεν καὶ συναπεδήμησεν καὶ εἰς τοὺς Ἕλληνας ἐνέγραψεν, καὶ κατά γε τοῦτο χάριν ἂν εἰδείην τῷ γάμῳ. δι’ ἃς δὲ αἰτίας ἀπολιπὼν αὐτὴν ἐπὶ τουτονὶ τὸν Διάλογον ἐτραπόμην, ἀκούσατε, ὦ ἄνδρες δικασταί, καί με μηδὲν τοῦ χρησίμου ἕνεκα ψεύδεσθαι ὑπολάβητε.", "st": "26.30"}, {"sp": "N", "t": "ἐγὼ γὰρ ὁρῶν ταύτην οὐκέτι σωφρονοῦσαν οὐδὲ μένουσαν ἐπὶ τοῦ κοσμίου σχήματος οἷόν ποτε ἐσχηματισμένην αὐτὴν ὁ Παιανιεὺς ἐκεῖνος ἠγάγετο, κοσμουμένην δὲ καὶ τὰς τρίχας εὐθετίζουσαν εἰς τὸ ἑταιρικὸν καὶ φυκίον ἐντριβομένην καὶ τὠφθαλμὼ ὑπογραφομένην, ὑπώπτευον εὐθὺς καὶ παρεφύλαττον ὅποι τὸν ὀφθαλμὸν φέρει. καὶ τὰ μὲν ἄλλα ἐῶ· καθ’ ἑκάστην δὲ τὴν νύκτα ὁ μὲν στενωπὸς ἡμῶν ἐνεπίμπλατο μεθυόντων ἐραστῶν κωμαζόντων ἐπ’ αὐτὴν καὶ κοπτόντων τὴν θύραν, ἐνίων δὲ καὶ εἰσβιάζεσθαι σὺν οὐδενὶ κόσμῳ τολμώντων. αὐτὴ δὲ ἐγέλα καὶ ἥδετο τοῖς δρωμένοις καὶ τὰ πολλὰ ἢ παρέκυπτεν ἀπὸ τοῦ τέγους ᾀδόντων ἀκούουσα τραχείᾳ τῇ φωνῇ ᾠδάς τινας ἐρωτικὰς ἢ καὶ παρανοίγουσα τὰς θυρίδας ἐμὲ οἰομένη λανθάνειν ἠσέλγαινε καὶ ἐμοιχεύετο πρὸς αὐτῶν. ὅπερ ἐγὼ μὴ φέρων γράψασθαι μὲν αὐτὴν μοιχείας οὐκ ἐδοκίμαζον, ἐν γειτόνων δὲ οἰκοῦντι τῷ Διαλόγῳ προσελθὼν ἠξίουν καταδεχθῆναι ὑπ’ αὐτοῦ.", "st": "26.31"}, {"sp": "N", "t": "ταῦτά ἐστιν ἃ τὴν Ῥητορικὴν ἐγὼ μεγάλα ἠδίκηκα. καίτοι εἰ καὶ μηδὲν αὐτῇ τοιοῦτο ἐπέπρακτο, καλῶς εἶχέ μοι ἀνδρὶ ἤδη τετταράκοντα ἔτη σχεδὸν γεγονότι θορύβων μὲν ἐκείνων καὶ δικῶν ἀπηλλάχθαι καὶ τοὺς ἄνδρας τοὺς δικαστὰς ἀτρεμεῖν ἐᾶν, τυράννων κατηγορίας καὶ ἀριστέων ἐπαίνους ἐκφυγόντα, εἰς δὲ τὴν Ἀκαδήμειαν ἢ εἰς τὸ Λύκειον ἐλθόντα τῷ βελτίστῳ τούτῳ Διαλόγῳ συμπεριπατεῖν ἠρέμα διαλεγομένους, τῶν ἐπαίνων καὶ κρότων οὐ δεομένους. πολλὰ ἔχων εἰπεῖν ἤδη παύσομαι. ὑμεῖς δὲ εὔορκον τὴν ψῆφον ἐνέγκατε.", "st": "26.32"}, {"sp": "N", "t": "<em>Δίκη.<\/em> τίς κρατεῖ;", "st": "26.32"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> πάσαις ὁ Σύρος πλὴν μιᾶς.", "st": "26.32"}, {"sp": "N", "t": "<em>Δίκη.<\/em> ῥήτωρ τις ἔοικεν εἶναι ὁ τὴν ἐναντίαν θέμενος.", "st": "26.32"}, {"sp": "N", "t": "ὁ Διάλογος ἐπὶ τῶν αὐτῶν λέγε. ὑμεῖς δὲ περιμείνατε, διπλάσιον ἀποισόμενοι τὸν μισθὸν ἐπ’ ἀμφοτέραις ταῖς δίκαις.", "st": "26.33"}, {"sp": "N", "t": "<em>Διάλογος.<\/em> ἐγὼ δέ, ὦ ἄνδρες δικασταί, μακροὺς μὲν ἀποτείνειν τοὺς λόγους οὐκ ἂν ἐβουλόμην πρὸς ὑμᾶς, ἀλλὰ κατὰ μικρὸν ὥσπερ εἴωθα. ὅμως δὲ ὡς νόμος ἐν τοῖς δικαστηρίοις, οὕτω ποιήσομαι τὴν κατηγορίαν ἰδιώτης παντάπασιν καὶ ἄτεχνος τῶν τοιούτων ὤν· καί μοι τοῦτο ἔστω πρὸς ὑμᾶς τὸ προοίμιον.", "st": "26.33"}, {"sp": "N", "t": "ἃ δὲ ἠδίκημαι καὶ περιύβρισμαι πρὸς τούτου, ταῦτά ἐστιν, ὅτι με σεμνὸν τέως ὄντα καὶ θεῶν τε πέρι καὶ φύσεως καὶ τῆς τῶν ὅλων περιόδου σκοπούμενον, ὑψηλὸν ἄνω που τῶν νεφῶν ἀεροβατοῦντα, ἔνθα ὁ μέγας ἐν οὐρανῷ Ζεὺς πτηνὸν ἅρμα ἐλαύνων φέρεται, κατασπάσας αὐτὸς ἤδη κατὰ τὴν ἁψῖδα πετόμενον καὶ ἀναβαίνοντα ὑπὲρ τὰ νῶτα τοῦ οὐρανοῦ καὶ τὰ πτερὰ συντρίψας ἰσοδίαιτον τοῖς πολλοῖς ἐποίησεν, καὶ τὸ μὲν τραγικὸν ἐκεῖνο καὶ σωφρονικὸν προσωπεῖον ἀφεῖλέ μου, κωμικὸν δὲ καὶ σατυρικὸν ἄλλο ἐπέθηκέ μοι καὶ μικροῦ δεῖν γελοῖον. εἶτά μοι εἰς τὸ αὐτὸ φέρων συγκαθεῖρξεν τὸ σκῶμμα καὶ τὸν ἴαμβον καὶ κυνισμὸν καὶ τὸν Εὔπολιν καὶ τὸν Ἀριστοφάνη, δεινοὺς ἄνδρας ἐπικερτομῆσαι τὰ σεμνὰ καὶ χλευάσαι τὰ ὀρθῶς ἔχοντα. τελευταῖον δὲ καὶ Μένιππόν τινα τῶν παλαιῶν κυνῶν μάλα ὑλακτικὸν ὡς δοκεῖ καὶ κάρχαρον ἀνορύξας, καὶ τοῦτον ἐπεισήγαγεν μοι φοβερόν τινα ὡς ἀληθῶς κύνα καὶ τὸ δῆγμα λαθραῖον, ὅσῳ καὶ γελῶν ἅμα ἔδακνεν.", "st": "26.33"}, {"sp": "N", "t": "πῶς οὖν οὐ δεινὰ ὕβρισμαι μηκέτ’ ἐπὶ τοῦ οἰκείου διακείμενος, ἀλλὰ κωμῳδῶν καὶ γελωτοποιῶν καὶ ὑποθέσεις ἀλλοκότους ὑποκρινόμενος αὐτῷ; τὸ γὰρ πάντων ἀτοπώτατον, κρᾶσίν τινα παράδοξον κέκραμαι καὶ οὔτε πεζός εἰμι οὔτε ἐπὶ τῶν μέτρων βέβηκα, ἀλλὰ ἱπποκενταύρου δίκην σύνθετόν τι καὶ ξένον φάσμα τοῖς ἀκούουσι δοκῶ.", "st": "26.33"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> τί οὖν πρὸς ταῦτα ἐρεῖς, ὦ Σύρε;", "st": "26.34"}, {"sp": "N", "t": "<em>Σῦρος.<\/em> ἀπροσδόκητον, ὦ ἄνδρες δικασταί, τὸν ἀγῶνα τοῦτον ἀγωνίζομαι παρ’ ὑμῖν· πάντα γοῦν μᾶλλον ἂν ἤλπισα ἢ τὸν Διάλογον τοιαῦτα ἐρεῖν περὶ ἐμοῦ, ὃν παραλαβὼν ἐγὼ σκυθρωπὸν ἔτι τοῖς πολλοῖς δοκοῦντα καὶ ὑπὸ τῶν συνεχῶν ἐρωτήσεων κατεσκληκότα, καὶ ταύτῃ αἰδέσιμον μὲν εἶναι δοκοῦντα, οὐ πάντῃ δὲ ἡδὺν οὐδὲ τοῖς πλήθεσι κεχαρισμένον, πρῶτον μὲν αὐτὸν ἐπὶ γῆς βαίνειν εἴθισα εἰς τὸν ἀνθρώπινον τοῦτον τρόπον, μετὰ δὲ τὸν αὐχμὸν τὸν πολὺν ἀποπλύνας καὶ μειδιᾶν καταναγκάσας ἡδίω τοῖς ὁρῶσι παρεσκεύασα, ἐπὶ πᾶσι δὲ τὴν κωμῳδίαν αὐτῷ παρέζευξα, καὶ κατὰ τοῦτο πολλήν οἱ μηχανώμενος τὴν εὔνοιαν παρὰ τῶν ἀκουόντων, οἳ τέως τὰς ἀκάνθας τὰς ἐν αὐτῷ δεδιότες ὥσπερ τὸν ἐχῖνον εἰς τὰς χεῖρας λαβεῖν αὐτὸν ἐφυλάττοντο.", "st": "26.34"}, {"sp": "N", "t": "ἀλλ’ ἐγὼ οἶδ’ ὅπερ μάλιστα λυπεῖ αὐτόν, ὅτι μὴ τὰ γλίσχρα ἐκεῖνα καὶ λεπτὰ κάθημαι πρὸς αὐτὸν σμικρολογούμενος, εἰ ἀθάνατος ἡ ψυχή, καὶ πόσας κοτύλας ὁ θεὸς ὁπότε τὸν κόσμον εἰργάσατο τῆς ἀμιγοῦς καὶ κατὰ ταὐτὰ ἐχούσης οὐσίας ἐνέχεεν εἰς τὸν κρατῆρα ἐν ᾧ τὰ πάντα ἐκεράννυτο, καὶ εἰ ἡ Ῥητορικὴ πολιτικῆς μορίου εἴδωλον, κολακείας τὸ τέταρτον. χαίρει γὰρ οὐκ οἶδ’ ὅπως τὰ τοιαῦτα λεπτολογῶν καθάπερ οἱ τὴν ψώραν ἡδέως κνώμενοι, καὶ τὸ φρόντισμα ἡδὺ αὐτῷ δοκεῖ καὶ μέγα φρονεῖ ἢν λέγηται ὡς οὐ παντὸς ἀνδρός ἐστι συνιδεῖν ἃ περὶ τῶν ἰδεῶν ὀξυδορκεῖ.", "st": "26.34"}, {"sp": "N", "t": "ταῦτα δηλαδὴ καὶ παρ’ ἐμοῦ ἀπαιτεῖ καὶ τὰ πτερὰ ἐκεῖνα ζητεῖ καὶ ἄνω βλέπει τὰ πρὸ τοῖν ποδοῖν οὐχ ὁρῶν. ἐπεὶ τῶν γε ἄλλων ἕνεκα οὐκ ἂν οἶμαι μέμψαιτό μοι, ὡς θοἰμάτιον τοῦτο τὸ Ἑλληνικὸν περισπάσας αὐτοῦ βαρβαρικόν τι μετενέδυσα, καὶ ταῦτα βάρβαρος αὐτὸς εἶναι δοκῶν· ἠδίκουν γὰρ ἂν τὰ τοιαῦτα εἰς αὐτὸν παρανομῶν καὶ τὴν πάτριον ἐσθῆτα λωποδυτῶν.", "st": "26.34"}, {"sp": "N", "t": "ἀπολελόγημαι ὡς δυνατὸν ἐμοί· ὑμεῖς δὲ ὁμοίαν τῇ πάλαι τὴν ψῆφον ἐνέγκατε.", "st": "26.34"}, {"sp": "N", "t": "<em>Ἑρμῆς.<\/em> βαβαί, δέκα ὅλαις κρατεῖς· ὁ γὰρ αὐτὸς ἐκεῖνος ὁ πάλαι οὐδὲ νῦν ὁμόψηφός ἐστιν. ἀμέλει τοῦτο ἔθος ἐστίν, καὶ πᾶσι τὴν τετρυπημένην οὗτος φέρει· καὶ μὴ παύσαιτο φθονῶν τοῖς ἀρίστοις. ἀλλ’ ὑμεῖς μὲν ἄπιτε ἀγαθῇ τύχῃ, αὔριον δὲ τὰς λοιπὰς δικάσομεν.", "st": "26.35"}, {"sp": "HDR", "t": "Περὶ Θυσιῶν"}, {"sp": "N", "t": "ἃ μὲν γὰρ ἐν ταῖς θυσίαις οἱ μάταιοι πράττουσι καὶ ταῖς ἑορταῖς καὶ προσόδοις τῶν θεῶν καὶ ἃ αἰτοῦσι καὶ ἃ εὔχονται καὶ ἃ γιγνώσκουσι περὶ αὐτῶν, οὐκ οἶδα εἴ τις οὕτως κατηφής ἐστι καὶ λελυπημένος ὅστις οὐ γελάσεται τὴν ἀβελτερίαν ἐπιβλέψας τῶν δρωμένων. καὶ πολύ γε, οἶμαι, πρότερον τοῦ γελᾶν πρὸς ἑαυτὸν ἐξετάσει πότερον εὐσεβεῖς αὐτοὺς χρὴ καλεῖν ἢ τοὐναντίον θεοῖς ἐχθροὺς καὶ κακοδαίμονας, οἵ γε οὕτω ταπεινὸν καὶ ἀγεννὲς τὸ θεῖον ὑπειλήφασιν ὥστε εἶναι ἀνθρώπων ἐνδεὲς καὶ κολακευόμενον ἥδεσθαι καὶ ἀγανακτεῖν ἀμελούμενον.", "st": "27.1"}, {"sp": "N", "t": "τὰ γοὺν Αἰτωλικὰ πάθη καὶ τὰς τῶν Καλυδωνίων συμφορὰς καὶ τοὺς τοσούτους φόνους καὶ τὴν Μελεάγρου διάλυσιν, πάντα ταῦτα ἔργα φασὶν εἶναι τῆς Ἀρτέμιδος μεμψιμοιρούσης ὅτι μὴ παρελήφθη πρὸς τὴν θυσίαν ὑπὸ τοῦ Οἰνέως· οὕτως ἄρα βαθέως καθίκετο αὐτῆς ἡ τῶν ἱερείων διαφορά. καί μοι δοκῶ ὁρᾶν αὐτὴν ἐν τῷ οὐρανῷ τότε μόνην τῶν ἄλλων θεῶν εἰς Οἰνέως πεπορευμένων, δεινὰ ποιοῦσαν καὶ σχετλιάζουσαν οἵας ἑορτῆς ἀπολειφθήσεται.", "st": "27.1"}, {"sp": "N", "t": "τοὺς δ’ αὖ Αἰθίοπας καὶ μακαρίους καὶ τρισευδαίμονας εἴποι τις ἄν, εἴ γε ἀπομνημονεύει τὴν χάριν αὐτοῖς ὁ Ζεὺς ἣν πρὸς αὐτὸν ἐπεδείξαντο δώδεκα ἑξῆς ἡμέρας ἑστιάσαντες, καὶ ταῦτα ἐπαγόμενον καὶ τοὺς ἄλλους θεούς.", "st": "27.2"}, {"sp": "N", "t": "οὕτως οὐδέν, ὡς ἔοικεν, ἀμισθὶ ποιοῦσιν ὧν ποιοῦσιν, ἀλλὰ πωλοῦσιν τοῖς ἀνθρώποις τἀγαθά, καὶ ἔνεστι πρίασθαι παρ’ αὐτῶν τὸ μὲν ὑγιαίνειν, εἰ τύχοι, βοϊδίου, τὸ δὲ πλουτεῖν βοῶν τεττάρων, τὸ δὲ βασιλεύειν ἑκατόμβης, τὸ δὲ σῶον ἐπανελθεῖν ἐξ Ἰλίου εἰς Πύλον ταύρων ἐννέα, καὶ τὸ ἐκ τῆς Αὐλίδος εἰς Ἴλιον διαπλεῦσαι παρθένου βασιλικῆς. ἡ μὲν γὰρ Ἑκάβη τὸ μὴ ἁλῶναι τὴν πόλιν τότε ἐπρίατο παρὰ τῆς Ἀθηνᾶς βοῶν δώδεκα καὶ πέπλου. εἰκάζειν δὲ χρὴ πολλὰ εἶναι ἀλεκτρυόνος καὶ στεφάνου καὶ λιβανωτοῦ μόνου παρ’ αὐτοῖς ὤνια.", "st": "27.2"}, {"sp": "N", "t": "ταῦτά γε, οἶμαι, καὶ ὁ Χρύσης ἐπιστάμενος ἅτε ἱερεὺς ὢν καὶ γέρων καὶ τὰ θεῖα σοφός, ἐπειδὴ ἄπρακτος ἀπῄει παρὰ τοῦ Ἀγαμέμνονος, ὡς ἂν καὶ προδανείσας τῷ Ἀπόλλωνι τὴν χάριν δικαιολογεῖται καὶ ἀπαιτεῖ τὴν ἀμοιβὴν καὶ μόνον οὐκ ὀνειδίζει λέγων, “ὦ βέλτιστε Ἄπολλον, ἐγὼ μέν σου τὸν νεὼν τέως ἀστεφάνωτον ὄντα πολλάκις ἐστεφάνωσα, καὶ τοσαῦτά σοι μηρία ταύρων τε καὶ αἰγῶν ἔκαυσα ἐπὶ τῶν βωμῶν, σὺ δὲ ἀμελεῖς μου τοιαῦτα πεπονθότος καὶ παρ’ οὐδὲν τίθεσαι τὸν εὐεργέτην.” τοιγαροῦν οὕτω κατεδυσώπησεν αὐτὸν ἐκ τῶν λόγων, ὥστε ἁρπασάμενος τὰ τόξα καὶ ἐπὶ τοῦ ναυστάθμου καθίσας ἑαυτὸν κατετόξευσε τῷ λοιμῷ τοὺς Ἀχαιοὺς αὐταῖς ἡμιόνοις καὶ κυσίν.", "st": "27.3"}, {"sp": "N", "t": "ἐπεὶ δὲ ἅπαξ τοῦ Ἀπόλλωνος ἐμνήσθην, βούλομαι καὶ τὰ ἄλλα εἰπεῖν, ἃ περὶ αὐτοῦ οἱ σοφοὶ τῶν ἀνθρώπων λέγουσιν, οὐχ ὅσα περὶ τοὺς ἔρωτας ἐδυστύχησεν οὐδὲ τοῦ Ὑακίνθου τὸν φόνον οὐδὲ τῆς Δάφνης τὴν ὑπεροψίαν, ἀλλ’ ὅτι καὶ καταγνωσθεὶς ἐπὶ τῷ τῶν Κυκλώπων θανάτῳ καὶ ἐξοστρακισθεὶς διὰ τοῦτο ἐκ τοῦ οὐρανοῦ, ἐπέμφθη εἰς τὴν γῆν ἀνθρωπίνῃ χρησόμενος τῇ τύχῃ· ὅτε δὴ καὶ ἐθήτευσεν ἐν Θετταλίᾳ παρὰ Ἀδμήτῳ καὶ ἐν Φρυγίᾳ παρὰ Λαομέδοντι, παρὰ τούτῳ μέν γε οὐ μόνος ἀλλὰ μετὰ τοῦ Ποσειδῶνος, ἀμφότεροι πλινθεύοντες ὑπ’ ἀπορίας καὶ ἐργαζόμενοι τὸ τεῖχος· καὶ οὐδὲ ἐντελῆ τὸν μισθὸν ἐκομίσαντο παρὰ τοῦ Φρυγός, ἀλλὰ προσώφειλεν αὐτοῖς πλέον ἢ τριάκοντα, φασί, δραχμὰς Τρωϊκάς.", "st": "27.4"}, {"sp": "N", "t": "ἢ γὰρ οὐ ταῦτα σεμνολογοῦσιν οἱ ποιηταὶ περὶ τῶν θεῶν καὶ πολὺ τούτων ἱερώτερα περί τε Ἡφαίστου καὶ Προμηθέως καὶ Κρόνου καὶ Ῥέας καὶ σχεδὸν ὅλης τῆς τοῦ Διὸς οἰκίας; καὶ ταῦτα παρακαλέσαντες τὰς Μούσας συνῳδοὺς ἐν ἀρχῇ τῶν ἐπῶν, ὑφ’ ὧν δὴ ἔνθεοι γενόμενοι, ὡς τὸ εἰκός, ᾄδουσιν ὡς ὁ μὲν Κρόνος ἐπειδὴ τάχιστα ἐξέτεμε τὸν πατέρα τὸν Οὐρανόν, ἐβασίλευσέν τε ἐν αὐτῷ καὶ τὰ τέκνα κατήσθιεν ὥσπερ ὁ Ἀργεῖος Θυέστης ὕστερον· ὁ δὲ Ζεὺς κλαπεὶς ὑπὸ τῆς Ῥέας ὑποβαλομένης τὸν λίθον εἰς τὴν Κρήτην ἐκτεθεὶς ὑπ’ αἰγὸς ἀνετράφη καθάπερ ὁ Τήλεφος ὑπὸ ἐλάφου καὶ ὁ Πέρσης Κῦρος ὁ πρότερος ὑπὸ τῆς κυνός, εἶτ’ ἐξελάσας τὸν πατέρα καὶ εἰς τὸ δεσμωτήριον καταβαλὼν αὐτὸς ἔσχε τὴν ἀρχήν· ἔγημε δὲ πολλὰς μὲν καὶ ἄλλας, ὑστάτην δὲ τὴν ἀδελφὴν κατὰ τοὺς Περσῶν καὶ Ἀσσυρίων νόμους· ἐρωτικὸς δὲ ὢν καὶ εἰς τὰ ἀφροδίσια ἐκκεχυμένος ῥᾳδίως ἐνέπλησε παίδων τὸν οὐρανόν, τοὺς μὲν ἐξ ὁμοτίμων ποιησάμενος, ἐνίους δὲ νόθους ἐκ τοῦ θνητοῦ καὶ ἐπιγείου γένους, ἄρτι μὲν ὁ γεννάδας γενόμενος χρυσός, ἄρτι δὲ ταῦρος ἢ κύκνος ἢ ἀετός, καὶ ὅλως ποικιλώτερος αὐτοῦ Πρωτέως· μόνην δὲ τὴν Ἀθηνᾶν ἔφυσεν ἐκ τῆς ἑαυτοῦ κεφαλῆς ὑπ’ αὐτὸν ἀτεχνῶς τὸν ἐγκέφαλον συλλαβών· τὸν μὲν γὰρ Διόνυσον ἡμιτελῆ, φασίν, ἐκ τῆς μητρὸς ἔτι καιομένης ἁρπάσας ἐν τῷ μηρῷ φέρων κατώρυξε κᾆτα ἐξέτεμεν τῆς ὠδῖνος ἐνστάσης.", "st": "27.5"}, {"sp": "N", "t": "ὅμοια δὲ τούτοις καὶ περὶ τῆς Ἥρας ᾄδουσιν, ἄνευ τῆς πρὸς τὸν ἄνδρα ὁμιλίας ὑπηνέμιον αὐτὴν παῖδα γεννῆσαι τὸν Ἥφαιστον, οὐ μάλα εὐτυχῆ τοῦτον, ἀλλὰ βάναυσον καὶ χαλκέα καὶ πυρίτην, ἐν καπνῷ τὸ πᾶν βιοῦντα καὶ σπινθήρων ἀνάπλεων οἷα δὴ καμινευτήν, καὶ οὐδὲ ἄρτιον τὼ πόδε· χωλευθῆναι γὰρ αὐτὸν ἀπὸ τοῦ πτώματος, ὁπότε ἐρρίφη ὑπὸ τοῦ Διὸς ἐξ οὐρανοῦ, καὶ εἴ γε μὴ οἱ Λήμνιοι καλῶς ποιοῦντες ἔτι φερόμενον αὐτὸν ὑπεδέξαντο, κἂν ἐτεθνήκει ἡμῖν ὁ Ἥφαιστος ὥσπερ ὁ Ἀστυάναξ ἀπὸ τοῦ πύργου καταπεσών. Καίτοι τὰ μὲν Ἡφαίστου μέτρια· τὸν δὲ Προμηθέα τίς οὐκ οἶδεν οἷα ἔπαθεν, διότι καθ’ ὑπερβολὴν φιλάνθρωπος ἦν; καὶ γὰρ αὖ καὶ τοῦτον εἰς τὴν Σκυθίαν ἀγαγὼν ὁ Ζεὺς ἀνεσταύρωσεν ἐπὶ τοῦ Καυκάσου, τὸν ἀετὸν αὐτῷ παρακαταστήσας τὸ ἧπαρ ὁσημέραι κολάψοντα.", "st": "27.6"}, {"sp": "N", "t": "οὗτος μὲν οὖν ἐξετέλεσε τὴν καταδίκην. ἡ Ῥέα δέ — χρὴ γὰρ ἴσως καὶ ταῦτα εἰπεῖν — πῶς οὐκ ἀσχημονεῖ καὶ δεινὰ ποιεῖ, γραῦς μὲν ἤδη καὶ ἔξωρος οὖσα καὶ τοσούτων μήτηρ θεῶν, παιδεραστοῦσα δὲ ἔτι καὶ ζηλοτυποῦσα καὶ τὸν Ἄττιν ἐπὶ τῶν λεόντων περιφέρουσα, καὶ ταῦτα μηκέτι χρήσιμον εἶναι δυνάμενον; ὥστε πῶς ἂν ἔτι μέμφοιτό τις ἢ τῇ Ἀφροδίτῃ ὅτι μοιχεύεται, ἢ τῇ Σελήνῃ πρὸς τὸν Ἐνδυμίωνα κατιούσῃ πολλάκις ἐκ μέσης τῆς ὁδοῦ;", "st": "27.7"}, {"sp": "N", "t": "φέρε δὲ ἤδη τούτων ἀφέμενοι τῶν λόγων εἰς αὐτὸν ἀνέλθωμεν τὸν οὐρανὸν ποιητικῶς ἀναπτάμενοι κατὰ τὴν αὐτὴν Ὁμήρῳ καὶ Ἡσιόδῳ ὁδὸν καὶ θεασώμεθα ὅπως διακεκόσμηται τὰ ἄνω. καὶ ὅτι μὲν χαλκοῦς ἐστιν τὰ ἔξω, καὶ πρὸ ἡμῶν τοῦ Ὁμήρου λέγοντος ἠκούσαμεν· ὑπερβάντι δὲ καὶ ἀνακύψαντι μικρὸν εἰς τὸ ἄνω καὶ ἀτεχνῶς ἐπὶ τοῦ νώτου γενομένῳ φῶς τε λαμπρότερον φαίνεται καὶ ἥλιος καθαρώτερος καὶ ἄστρα διαυγέστερα καὶ τὸ πᾶν ἡμέρα καὶ χρυσοῦν τὸ δάπεδον. εἰσιόντων δὲ πρῶτα μὲν οἰκοῦσιν αἱ Ὧραι· πυλωροῦσι γάρ· ἔπειτα δ’ ἡ Ἶρις καὶ ὁ Ἑρμῆς ὄντες ὑπηρέται καὶ ἀγγελιαφόροι τοῦ Διός, ἑξῆς δὲ τοῦ Ἡφαίστου τὸ χαλκεῖον ἀνάμεστον ἁπάσης τέχνης, μετὰ δὲ αἱ τῶν θεῶν οἰκίαι καὶ τοῦ Διὸς τὰ βασίλεια, ταῦτα πάντα περικαλλῆ τοῦ Ἡφαίστου κατασκευάσαντος.", "st": "27.8"}, {"sp": "N", "t": "“οἱ δὲ θεοὶ πὰρ Ζηνὶ καθήμενοι —” πρέπει γάρ, οἶμαι, ἄνω ὄντα μεγαληγορεῖν — ἀποσκοποῦσιν εἰς τὴν γῆν καὶ πάντῃ περιβλέπουσιν ἐπικύπτοντες εἴ ποθεν ὄψονται πῦρ ἀναπτόμενον ἢ ἀναφερομένην κνῖσαν “ἑλισσομένην περὶ καπνῷ.” κἂν μὲν θύῃ τις, εὐωχοῦνται πάντες ἐπικεχηνότες τῷ καπνῷ καὶ τὸ αἷμα πίνοντες τοῖς βωμοῖς προσχεόμενον ὥσπερ αἱ μυῖαι· ἢν δὲ οἰκοσιτῶσιν, νέκταρ καὶ ἀμβροσία τὸ δεῖπνον. πάλαι μὲν οὖν καὶ ἄνθρωποι συνειστιῶντο καὶ συνέπινον αὐτοῖς, ὁ Ἰξίων καὶ ὁ Τάνταλος· ἐπεὶ δὲ ἦσαν ὑβρισταὶ καὶ λάλοι, ἐκεῖνοι μὲν ἔτι καὶ νῦν κολάζονται, ἄβατος δὲ τῷ θνητῷ γένει καὶ ἀπόρρητος ὁ οὐρανός.", "st": "27.9"}, {"sp": "N", "t": "τοιοῦτος ὁ βίος τῶν θεῶν. τοιγαροῦν καὶ οἱ ἄνθρωποι συνῳδὰ τούτοις καὶ ἀκόλουθα περὶ τὰς θρησκείας ἐπιτηδεύουσιν. καὶ πρῶτον μὲν ὕλας ἀπετέμοντο καὶ ὄρη ἀνέθεσαν καὶ ὄρνεα καθιέρωσαν καὶ φυτὰ ἐπεφήμισαν ἑκάστῳ θεῷ. μετὰ δὲ νειμάμενοι κατὰ ἔθνη σέβουσι καὶ πολίτας αὐτῶν ἀποφαίνουσιν, ὁ μὲν Δελφὸς τὸν Ἀπόλλω καὶ ὁ Δήλιος, ὁ δὲ Ἀθηναῖος τὴν Ἀθηνᾶν — μαρτυρεῖται γοῦν τὴν οἰκειότητα τῷ ὀνόματι — καὶ τὴν Ἥραν ὁ Ἀργεῖος καὶ ὁ Μυγδόνιος τὴν Ῥέαν καὶ τὴν Ἀφροδίτην ὁ Πάφιος. οἱ δ’ αὖ Κρῆτες οὐ γενέσθαι παρ’ αὐτοῖς οὐδὲ τραφῆναι μόνον τὸν Δία λέγουσιν, ἀλλὰ καὶ τάφον αὐτοῦ δεικνύουσιν· καὶ ἡμεῖς ἄρα τοσοῦτον ἠπατήμεθα χρόνον οἰόμενοι τὸν Δία βροντᾶν τε καὶ ὕειν καὶ τὰ ἄλλα πάντα ἐπιτελεῖν, ὁ δὲ ἐλελήθει πάλαι τεθνεὼς παρὰ Κρησὶ τεθαμμένος.", "st": "27.10"}, {"sp": "N", "t": "ἔπειτα δὲ ναοὺς ἐγείραντες ἵνα αὐτοῖς μὴ ἄοικοι μηδὲ ἀνέστιοι δῆθεν ὦσιν, εἰκόνας αὐτοῖς ἀπεικάζουσιν παρακαλέσαντες ἢ Πραξιτέλην ἢ Πολύκλειτον ἢ Φειδίαν, οἱ δὲ οὐκ οἶδ’ ὅπου ἰδόντες ἀναπλάττουσι γενειήτην μὲν τὸν Δία, παῖδα δὲ εἰς ἀεὶ τὸν Ἀπόλλωνα καὶ τὸν Ἑρμῆν ὑπηνήτην καὶ τὸν Ποσειδῶνα κυανοχαίτην καὶ γλαυκῶπιν τὴν Ἀθηνᾶν. ὅμως δ’ οὖν οἱ παριόντες εἰς τὸν νεὼν οὔτε τὸν ἐξ Ἰνδῶν ἐλέφαντα ἔτι οἴονται ὁρᾶν οὔτε τὸ ἐκ τῆς Θρᾴκης μεταλλευθὲν χρυσίον ἀλλ’ αὐτὸν τὸν Κρόνου καὶ Ῥέας, εἰς τὴν γῆν ὑπὸ Φειδίου μετῳκισμένον καὶ τὴν Πισαίων ἐρημίαν ἐπισκοπεῖν κεκελευσμένον, ἀγαπῶντα εἰ διὰ πέντε ὅλων ἐτῶν θύσει τις αὐτῷ πάρεργον Ὀλυμπίων.", "st": "27.11"}, {"sp": "N", "t": "θέμενοι δὲ βωμοὺς καὶ προρρήσεις καὶ περιρραντήρια προσάγουσι τὰς θυσίας, βοῦν μὲν ἀροτῆρα ὁ γεωργός, ἄρνα δὲ ὁ ποιμὴν καὶ αἶγα ὁ αἰπόλος, ὁ δέ τις λιβανωτὸν ἢ πόπανον, ὁ δὲ πένης ἱλάσατο τὸν θεὸν κύσας μόνον τὴν ἑαυτοῦ δεξιάν. ἀλλ’ οἵ γε θύοντες — ἐπ’ ἐκείνους γὰρ ἐπάνειμι — στεφανώσαντες τὸ ζῷον καὶ πολύ γε πρότερον ἐξετάσαντες εἰ ἐντελὲς εἴη, ἵνα μηδὲ τῶν ἀχρήστων τι κατασφάττωσιν, προσάγουσι τῷ βωμῷ καὶ φονεύουσιν ἐν ὀφθαλμοῖς τοῦ θεοῦ γοερόν τι μυκώμενον καὶ ὡς τὸ εἰκὸς εὐφημοῦν καὶ ἡμίφωνον ἤδη τῇ θυσίᾳ ἐπαυλοῦν. τίς οὐκ ἂν εἰκάσειεν ἥδεσθαι ταῦτα ὁρῶντας τοὺς θεούς;", "st": "27.12"}, {"sp": "N", "t": "καὶ τὸ μὲν πρόγραμμά φησι μὴ παριέναι εἰς τὸ εἴσω τῶν περιρραντηρίων ὅστις μὴ καθαρός ἐστιν τὰς χεῖρας· ὁ δὲ ἱερεὺς αὐτὸς ἕστηκεν ᾑμαγμένος καὶ ὥσπερ ὁ Κύκλωψ ἐκεῖνος ἀνατέμνων καὶ τὰ ἔγκατα ἐξαιρῶν καὶ καρδιουλκῶν καὶ τὸ αἷμα τῷ βωμῷ περιχέων καὶ τί γὰρ οὐκ εὐσεβὲς ἐπιτελῶν; ἐπὶ πᾶσι δὲ πῦρ ἀνακαύσας ἐπέθηκε φέρων αὐτῇ δορᾷ τὴν αἶγα καὶ αὐτοῖς ἐρίοις τὸ πρόβατον· ἡ δὲ κνῖσα θεσπέσιος καὶ ἱεροπρεπὴς χωρεῖ ἄνω καὶ εἰς αὐτὸν τὸν οὐρανὸν ἠρέμα διασκίδναται.", "st": "27.13"}, {"sp": "N", "t": "ὁ μέν γε Σκύθης πάσας τὰς θυσίας ἀφεὶς καὶ ἡγησάμενος ταπεινὰς αὐτοὺς τοὺς ἀνθρώπους τῇ Ἀρτέμιδι παρίστησι καὶ οὕτως ποιῶν ἀρέσκει τὴν θεόν.", "st": "27.13"}, {"sp": "N", "t": "ταῦτα μὲν δὴ ἴσως μέτρια καὶ τὰ ὑπ’ Ἀσσυρίων γιγνόμενα καὶ ὑπὸ Φρυγῶν καὶ Λυδῶν, ἢν δ’ εἰς τὴν Αἴγυπτον ἔλθῃς, τότε δὴ τότε ὄψει πολλὰ τὰ σεμνὰ καὶ ὡς ἀληθῶς ἄξια τοῦ οὐρανοῦ, κριοπρόσωπον μὲν τὸν Δία, κυνοπρόσωπον δὲ τὸν βέλτιστον Ἑρμῆν καὶ τὸν Πᾶνα ὅλον τράγον καὶ ἶβίν τινα καὶ κροκόδειλον ἕτερον καὶ πίθηκον.<br>εἰ δ’ ἐθέλεις καὶ ταῦτα δαήμεναι, ὄφρ’ εὖ εἰδῇς,<br>ἀκούσῃ πολλῶν σοφιστῶν καὶ γραμματέων καὶ προφητῶν ἐξυρημένων διηγουμένων, — πρότερον δέ, φησὶν ὁ λόγος, “θύρας δ’ ἐπίθεσθε βέβηλοι” — ὡς ἄρα ὑπὸ τὸν πόλεμον καὶ τῶν γιγάντων τὴν ἐπανάστασιν οἱ θεοὶ φοβηθέντες ἧκον εἰς τὴν Αἴγυπτον ὡς δὴ ἐνταῦθα λησόμενοι τοὺς πολεμίους· εἶθ’ ὁ μὲν αὐτῶν ὑπέδυ τράγον, ὁ δὲ κριὸν ὑπὸ τοῦ δέους, ὁ δὲ θηρίον ἢ ὄρνεον· διὸ δὴ εἰσέτι καὶ νῦν φυλάττεσθαι τὰς τότε μορφὰς τοῖς θεοῖς. ταῦτα γὰρ ἀμέλει ἐν τοῖς ἀδύτοις ἀπόκειται γραφέντα πλεῖον ἢ πρὸ ἐτῶν μυρίων.", "st": "27.14"}, {"sp": "N", "t": "αἱ δὲ θυσίαι καὶ παρ’ ἐκείνοις αἱ αὐταί, πλὴν ὅτι πενθοῦσι τὸ ἱερεῖον καὶ κόπτονται περιστάντες ἤδη πεφονευμένον. οἱ δὲ καὶ θάπτουσι μόνον ἀποσφάξαντες.", "st": "27.15"}, {"sp": "N", "t": "ὁ μὲν γὰρ Ἆπις, ὁ μέγιστος αὐτοῖς θεός, ἐὰν ἀποθάνῃ, τίς οὕτω περὶ πολλοῦ ποιεῖται τὴν κόμην ὅστις οὐκ ἀπεξύρησε καὶ ψιλὸν ἐπὶ τῆς κεφαλῆς τὸ πένθος ἐπεδείξατο, κἂν τὸν Νίσου ἔχῃ πλόκαμον τὸν πορφυροῦν; ἔστι δὲ ὁ Ἆπις ἐξ ἀγέλης θεός, ἐπὶ τῷ προτέρῳ χειροτονούμενος ὡς πολὺ καλλίων καὶ σεμνότερος τῶν ἰδιωτῶν Βοῶν.", "st": "27.15"}, {"sp": "N", "t": "ταῦτα οὕτω γιγνόμενα καὶ ὑπὸ τῶν πολλῶν πιστευόμενα δεῖσθαί μοι δοκεῖ τοῦ μὲν ἐπιτιμήσοντος οὐδενός, Ἡρακλείτου δέ τινος ἢ Δημοκρίτου, τοῦ μὲν γελασομένου τὴν ἄγνοιαν αὐτῶν, τοῦ δὲ τὴν ἄνοιαν ὀδυρουμένου.", "st": "27.15"}, {"sp": "HDR", "t": "Πρὸς τὸν ἀπαίδευτον καὶ πολλὰ βιβλία ὠνούμενον"}, {"sp": "N", "t": "καὶ μὴν ἐναντίον ἐστὶν οὗ ἐθέλεις ὃ νῦν ποιεῖς. οἴει μὲν γὰρ ἐν παιδείᾳ καὶ αὐτὸς εἶναί τις δόξειν σπουδῇ συνωνούμενος τὰ κάλλιστα τῶν βιβλίων· τὸ δέ σοι περὶ τὰ κάτω χωρεῖ, καὶ ἔλεγχος γίγνεται τῆς ἀπαιδευσίας πως τοῦτο. μάλιστα δὲ οὐδὲ τὰ κάλλιστα ὠνῇ, ἀλλὰ πιστεύεις τοῖς ὡς ἔτυχεν ἐπαινοῦσι καὶ ἕρμαιον εἶ τῶν τὰ τοιαῦτα ἐπιψευδομένων τοῖς βιβλίοις καὶ θησαυρὸς ἕτοιμος τοῖς καπήλοις αὐτῶν. ἢ πόθεν γάρ σοι διαγνῶναι δυνατόν, τίνα μὲν παλαιὰ καὶ πολλοῦ ἄξια, τίνα δὲ φαῦλα καὶ ἄλλως σαπρά, εἰ μὴ τῷ διαβεβρῶσθαι καὶ κατακεκόφθαι αὐτὰ τεκμαίροιο καὶ συμβούλους τοὺς σέας ἐπὶ τὴν ἐξέτασιν παραλαμβάνοις; ἐπεὶ τοῦ ἀκριβοῦς ἢ ἀσφαλοῦς ἐν αὐτοῖς τίς ἢ ποία διάγνωσις;", "st": "28.1"}, {"sp": "N", "t": "ἵνα δέ σοι δῶ αὐτὰ ἐκεῖνα κεκρικέναι, ὅσα ὁ Καλλῖνος εἰς κάλλος ἢ ὁ ἀοίδιμος Ἀττικὸς σὺν ἐπιμελείᾳ τῇ πάσῃ ἔγραψαν, σοὶ τί ὄφελος, ὦ θαυμάσιε, τοῦ κτήματος οὔτε εἰδότι τὸ κάλλος αὐτῶν οὔτε χρησομένῳ ποτὲ οὐδὲν μᾶλλον ἢ τυφλὸς ἄν τις ἀπολαύσειε κάλλους παιδικῶν; σὺ δὲ ἀνεῳγμένοις μὲν τοῖς ὀφθαλμοῖς ὁρᾷς τὰ βιβλία, καὶ νὴ Δία κατακόρως, καὶ ἀναγιγνώσκεις ἔνια πάνυ ἐπιτρέχων, φθάνοντος τοῦ ὀφθαλμοῦ τὸ στόμα· οὐδέπω δὲ τοῦτό μοι ἱκανόν, ἢν μὴ εἰδῇς τὴν ἀρετὴν καὶ κακίαν ἑκάστου τῶν ἐγγεγραμμένων καὶ συνίῃς ὅστις μὲν ὁ νοῦς σύμπασιν, τίς δὲ ἡ τάξις τῶν ὀνομάτων, ὅσα τε πρὸς τὸν ὀρθὸν κανόνα τῷ συγγραφεῖ ἀπηκρίβωται καὶ ὅσα κίβδηλα καὶ νόθα καὶ παρακεκομμένα.", "st": "28.2"}, {"sp": "N", "t": "τί οὖν; φὴς καὶ ταὐτὰ μὴ μαθὼν ἡμῖν εἰδέναι; πόθεν, εἰ μή ποτε παρὰ τῶν Μουσῶν κλῶνα δάφνης καθάπερ ὁ ποιμὴν ἐκεῖνος λαβών; Ἑλικῶνα μὲν γάρ, ἵνα διατρίβειν αἱ θεαὶ λέγονται, οὐδὲ ἀκήκοας οἶμαί ποτε, οὐδὲ τὰς αὐτὰς διατριβὰς ἡμῖν ἐν παισὶν ἐποιοῦ· σοὶ καὶ μεμνῆσθαι Μουσῶν ἀνόσιον. ἐκεῖναι γὰρ ποιμένι μὲν οὐκ ἂν ὤκνησαν φανῆναι σκληρῷ ἀνδρὶ καὶ δασεῖ καὶ πολὺν τὸν ἥλιον ἐπὶ τῷ σώματι ἐμφαίνοντι, οἵῳ δὲ σοί — καί μοι πρὸς τῆς Λιβανίτιδος ἄφες ἐν τῷ παρόντι τὸ μὴ σύμπαντα σαφῶς εἰπεῖν — οὐδὲ ἐγγὺς γενέσθαι ποτ’ ἂν εὖ οἶδ’ ὅτι ἠξίωσαν, ἀλλ’ ἀντὶ τῆς δάφνης μυρρίνῃ ἂν ἢ καὶ μαλάχης φύλλοις μαστιγοῦσαι ἀπήλλαξαν ἂν τῶν τοιούτων, ὡς μὴ μιᾶναι μήτε τὸν Ὀλμειὸν μήτε τὴν τοῦ Ἵππου κρήνην, ἅπερ ἢ ποιμνίοις διψῶσιν ἢ ποιμένων στόμασι καθαροῖς πότιμα.", "st": "28.3"}, {"sp": "N", "t": "καίτοι οὐδέ, εἰ καὶ πάνυ ἀναίσχυντος εἶ καὶ ἀνδρεῖος τὰ τοιαῦτα, τολμήσειας ἄν ποτε εἰπεῖν ὡς ἐπαιδεύθης ἢ ἐμέλησέ σοι πώποτε τῆς ἐν χρῷ πρὸς τὰ βιβλία συνουσίας ἢ ὡς διδάσκαλός σοι ὁ δεῖνα ἢ τῷ δεῖνι συνεφοίτας.", "st": "28.3"}, {"sp": "N", "t": "ἀλλ’ ἑνὶ τούτῳ μόνῳ πάντα ἐκεῖνα ἀναδραμεῖσθαι νῦν ἐλπίζεις, τῷ κτᾶσθαι πολλὰ βιβλία. κατὰ δὴ ταῦτα, ἐκεῖνα ἔχε συλλαβὼν τὰ τοῦ Δημοσθένους ὅσα τῇ χειρὶ τῇ αὑτοῦ ὁ ῥήτωρ ἔγραψε, καὶ τὰ τοῦ Θουκυδίδου ὅσα παρὰ τοῦ Δημοσθένους καὶ αὐτὰ ὀκτάκις μεταγεγραμμένα εὑρέθη, καὶ ὅλως ἅπαντα ἐκεῖνα ὅσα ὁ Σύλλας Ἀθήνηθεν εἰς Ἰταλίαν ἐξέπεμψε· τί ἂν πλέον ἐκ τούτου εἰς παιδείαν κτήσαιο, κἂν ὑποβαλόμενος αὐτὰ ἐπικαθεύδῃς ἢ συγκολλήσας καὶ περιβαλόμενος περινοστῇς; πίθηκος γὰρ ὁ πίθηκος, ἡ παροιμία φησί, κἂν χρύσεα ἔχῃ σύμβολα. καὶ σὺ τοίνυν βιβλίον μὲν ἔχεις ἐν τῇ χειρὶ καὶ ἀναγιγνώσκεις ἀεί, τῶν δὲ ἀναγιγνωσκομένων οἶσθα οὐδέν, ἀλλ’ ὄνος λύρας ἀκούεις κινῶν τὰ ὦτα.", "st": "28.4"}, {"sp": "N", "t": "ὡς εἴ γε τὸ κεκτῆσθαι τὰ βιβλία καὶ πεπαιδευμένον ἀπέφαινε τὸν ἔχοντα, πολλοῦ ἂν ὡς ἀληθῶς τὸ κτῆμα ἦν ἄξιον καὶ μόνων ὑμῶν τῶν πλουσίων, εἰ ὥσπερ ἐξ ἀγορᾶς ἦν πριάσθαι τοὺς πένητας ἡμᾶς ὑπερβάλλοντας. τίς δὲ τοῖς ἐμπόροις καὶ τοῖς βιβλιοκαπήλοις ἤρισεν ἂν περὶ παιδείας τοσαῦτα βιβλία ἔχουσι καὶ πωλοῦσιν, ἀλλ’ εἴ γε διελέγχειν ἐθέλεις, ὄψει μηδ’ ἐκείνους πολύ σου τὰ εἰς παιδείαν ἀμείνους, ἀλλὰ βαρβάρους μὲν τὴν φωνὴν ὥσπερ σύ, ἀξυνέτους δὲ τῇ γνώσει, οἵους εἰκὸς εἶναι τοὺς μηδὲν τῶν καλῶν καὶ αἰσχρῶν καθεωρακότας. καίτοι σὺ μὲν δύο ἢ τρία παρ’ αὐτῶν ἐκείνων πριάμενος ἔχεις, οἱ δὲ νύκτωρ καὶ μεθ’ ἡμέραν διὰ χειρὸς ἔχουσιν αὐτά.", "st": "28.4"}, {"sp": "N", "t": "τίνος οὖν ἀγαθοῦ ὠνῇ ταῦτα, εἰ μὴ καὶ τὰς ἀποθήκας αὐτὰς τῶν βιβλίων ἡγῇ πεπαιδεῦσθαι τοσαῦτα περιεχούσας παλαιῶν ἀνδρῶν συγγράμματα;", "st": "28.5"}, {"sp": "N", "t": "καί μοι, εἰ δοκεῖ, ἀπόκριναι· μᾶλλον δέ, ἐπεὶ τοῦτό σοι ἀδύνατον, ἐπίνευσον γοῦν ἢ ἀνάνευσον πρὸς τὰ ἐρωτώμενα. εἴ τις αὐλεῖν μὴ ἐπιστάμενος κτήσαιτο τοὺς Τιμοθέου αὐλοὺς ἢ τοὺς Ἰσμηνίου, οὓς ἑπτὰ ταλάντων ὁ Ἰσμηνίας ἐν Κορίνθῳ ἐπρίατο, ἆρ’ ἂν διὰ τοῦτο καὶ αὐλεῖν δύναιτο, ἢ οὐδὲν ὄφελος αὐτῷ τοῦ κτήματος οὐκ ἐπισταμένῳ χρήσασθαι κατὰ τὴν τέχνην; εὖ γε ἀνένευσας· οὐδὲ γὰρ τοὺς Μαρσύου ἢ Ὀλύμπου κτησάμενος αὐλήσειεν ἂν μὴ μαθών. τί δ’ εἴ τις τοῦ Ἡρακλέους τὰ τόξα κτήσαιτο μὴ Φιλοκτήτης ὢν ὡς δύνασθαι ἐντείνασθαί τε αὐτὰ καὶ ἐπίσκοπα τοξεῦσαι; τί σοι καὶ οὗτος δοκεῖ; ἆρ’ ἂν ἐπιδείξασθαί τι ἔργον τοξότου ἄξιον; ἀνένευσας καὶ τοῦτο. κατὰ ταὐτὰ δὴ καὶ ὁ κυβερνᾶν οὐκ εἰδὼς καὶ ἱππεύειν μὴ μεμελετηκὼς εἰ ὁ μὲν ναῦν καλλίστην παραλάβοι, τοῖς πᾶσι καὶ εἰς κάλλος καὶ εἰς ἀσφάλειαν κάλλιστα ἐξειργασμένην, ὁ δὲ ἵππον κτήσαιτο Μῆδον ἢ κενταυρίδην ἢ κοππαφόρον, ἐλέγχοιτο ἄν, οἶμαι, ἑκάτερος οὐκ εἰδὼς ὅ τι χρήσαιτο ἑκατέρῳ. ἐπινεύεις καὶ τοῦτο; πείθου δὴ καὶ τοῦτό μοι ἐπίνευσον· εἴ τις ὥσπερ σὺ ἀπαίδευτος ὢν ὠνοῖτο πολλὰ βιβλία, οὐ σκώμματα οὗτος εἰς ἀπαιδευσίαν καθ’ ἑαυτοῦ ἐκφέροι; τί ὀκνεῖς καὶ τοῦτο ἐπινεύειν; ἔλεγχος γάρ, οἶμαι, σαφὴς οὗτος, καὶ τῶν ὁρώντων ἕκαστος εὐθὺς τὸ προχειρότατον ἐκεῖνο ἐπιφθέγγεται, “τί κυνὶ καὶ βαλανείῳ;”", "st": "28.5"}, {"sp": "N", "t": "καὶ ἐγένετό τις οὐ πρὸ πολλοῦ ἐν Ἀσίᾳ πλούσιος ἀνὴρ ἐκ συμφορᾶς ἀποτμηθεὶς τοὺς πόδας ἀμφοτέρους, ἀπὸ κρύους, οἶμαι, ἀποσαπέντας ἐπειδή ποτε διὰ χιόνος ὁδοιπορῆσαι συνέβη αὐτῷ. οὗτος τοίνυν τοῦτο μὲν ἐλεεινὸν ἐπεπόνθει, καὶ θεραπεύων τὴν δυστυχίαν ξυλίνους πόδας πεποίητο, καὶ τούτους ὑποδούμενος ἐβάδιζεν ἐπιστηριζόμενος ἅμα τοῖς οἰκέταις. ἐκεῖνο δὲ γελοῖον ἐποίει, κρηπῖδας γὰρ καλλίστας ἐωνεῖτο νεοτμήτους ἀεί, καὶ τὴν πλείστην πραγματείαν περὶ ταύτας εἶχεν, ὡς καλλίστοις ὑποδήμασι κεκοσμημένα εἴη αὐτῷ τὰ ξύλα. οὐ ταὐτὰ οὖν καὶ σὺ ποιεῖς χωλὴν μὲν ἔχων καὶ συκίνην τὴν γνώμην, ὠνούμενος δὲ χρυσοῦς ἐμβάτας, οἷς μόλις ἄν τις καὶ ἀρτίπους ἐμπεριπατήσειεν;", "st": "28.6"}, {"sp": "N", "t": "ἐπεὶ δὲ ἐν τοῖς ἄλλοις καὶ τὸν Ὅμηρον ἐπρίω πολλάκις, ἀναγνώτω σοί τις αὐτοῦ λαβὼν τὴν δευτέραν τῆς Ἰλιάδος ῥαψῳδίαν, ἧς τὰ μὲν ἄλλα μὴ ἐξετάζειν· οὐδὲν γὰρ αὐτῶν πρὸς σέ· πεποίηται δέ τις αὐτῷ δημηγορῶν παγγέλοιος ἄνθρωπος, διάστροφος τὸ σῶμα καὶ λελωβημένος. ἐκεῖνος τοίνυν ὁ Θερσίτης ὁ τοιοῦτος εἰ λάβοι τὴν Ἀχιλλέως πανοπλίαν, οἴει ὅτι αὐτίκα διὰ τοῦτο καὶ καλὸς ἅμα καὶ ἰσχυρὸς ἂν γένοιτο, καὶ ὑπερπηδήσεται μὲν τὸν ποταμόν, ἐπιθολώσει δὲ αὐτοῦ τὸ ῥεῖθρον τῷ φόνῳ τῶν Φρυγῶν, ἀποκτενεῖ δὲ τὸν Ἕκτορα καὶ πρὸ αὐτοῦ τὸν Λυκάονα καὶ τὸν Ἀστεροπαῖον, μηδὲ φέρειν ἐπὶ τῶν ὤμων τὴν μελίαν δυνάμενος; οὐκ ἂν εἴποις· ἀλλὰ καὶ γέλωτα ἂν ὀφλισκάνοι χωλεύων ὑπὸ τῇ ἀσπίδι καὶ ἐπὶ στόμα καταπίπτων ὑπὸ τοῦ βάρους καὶ ὑπὸ τῷ κράνει ὁπότε ἀνανεύσειε δεικνὺς τοὺς παραβλῶπας ἐκείνους αὑτοῦ ὀφθαλμοὺς καὶ τὸν θώρακα ἐπαίρων τῷ τοῦ μεταφρένου κυρτώματι καὶ τὰς κνημῖδας ἐπισυρόμενος, καὶ ὅλως αἰσχύνων ἀμφοτέρους, καὶ τὸν δημιουργὸν αὐτῶν καὶ τὸν δεσπότην. τὸ αὐτὸ δὴ καὶ σὺ πάσχων οὐχ ὁρᾷς, ὁπόταν τὸ μὲν βιβλίον ἐν τῇ χειρὶ ἔχῃς πάγκαλον, πορφυρᾶν μὲν ἔχον τὴν διφθέραν, χρυσοῦν δὲ τὸν ὀμφαλόν, ἀναγιγνώσκῃς δὲ αὐτὸ βαρβαρίζων καὶ καταισχύνων καὶ διαστρέφων, ὑπὸ μὲν τῶν πεπαιδευμένων καταγελώμενος, ὑπὸ δὲ τῶν συνόντων σοι κολάκων ἐπαινούμενος, οἳ καὶ αὐτοὶ πρὸς ἀλλήλους ἐπιστρεφόμενοι γελῶσι τὰ πολλά;", "st": "28.7"}, {"sp": "N", "t": "θέλω γοῦν σοι διηγήσασθαί τι Πυθοῖ γενόμενον. Ταραντῖνος Εὐάγγελος τοὔνομα τῶν οὐκ ἀφανῶν ἐν τῷ Τάραντι ἐπεθύμησεν νικῆσαι Πύθια. τὰ μὲν οὖν τῆς γυμνῆς ἀγωνίας αὐτίκα ἐδόκει αὐτῷ ἀδύνατον εἶναι μήτε πρὸς ἰσχὺν μήτε πρὸς ὠκύτητα εὖ πεφυκότι, κιθάρᾳ δὲ καὶ ᾠδῇ ῥᾳδίως κρατήσειν ἐπείσθη ὑπὸ καταράτων ἀνθρώπων οὓς εἶχε περὶ αὑτὸν ἐπαινούντων καὶ βοώντων ὁπότε καὶ τὸ σμικρότατον ἐκεῖνος ἀνακρούσαιτο. ἧκεν οὖν εἰς τοὺς Δελφοὺς τοῖς τε ἄλλοις λαμπρὸς καὶ δὴ καὶ ἐσθῆτα χρυσόπαστον ποιησάμενος καὶ στέφανον δάφνης χρυσῆς κάλλιστον, ὡς ἀντὶ καρποῦ τῆς δάφνης σμαράγδους εἶναι ἰσομεγέθεις τῷ καρπῷ· τὴν μέν γε κιθάραν αὐτήν, ὑπερφυές τι χρῆμα εἰς κάλλος καὶ πολυτέλειαν, χρυσοῦ μὲν τοῦ ἀκηράτου πᾶσαν, σφραγῖσι δὲ καὶ λίθοις ποικίλοις κατακεκοσμημένην, Μουσῶν μεταξὺ καὶ Ἀπόλλωνος καὶ Ὀρφέως ἐντετορνευμένων, θαῦμα μέγα τοῖς ὁρῶσιν.", "st": "28.8"}, {"sp": "N", "t": "ἐπεὶ δ’ οὖν ποτε καὶ ἧκεν ἡ τοῦ ἀγῶνος ἡμέρα, τρεῖς μὲν ἦσαν, ἔλαχεν δὲ μέσος αὐτῶν ὁ Εὐάγγελος ᾄδειν· καὶ μετὰ Θέσπιν τὸν Θηβαῖον οὐ φαύλως ἀγωνισάμενον εἰσέρχεται ὅλος περιλαμπόμενος τῷ χρυσῷ καὶ τοῖς σμαράγδοις καὶ βηρύλλοις καὶ ὑακίνθοις· καὶ ἡ πορφύρα δὲ ἐνέπρεπε τῆς ἐσθῆτος, ἣ μεταξὺ τοῦ χρυσοῦ διεφαίνετο. τούτοις ἅπασι προεκπλήξας τὸ θέατρον καὶ θαυμαστῆς ἐλπίδος ἐμπλήσας τοὺς θεατάς, ἐπειδή ποτε καὶ ᾆσαι καὶ κιθαρίσαι πάντως ἔδει, ἀνακρούεται μὲν ἀνάρμοστόν τι καὶ ἀσύντακτον, ἀπορρήγνυσι δὲ τρεῖς ἅμα χορδὰς σφοδρότερον τοῦ δέοντος ἐμπεσὼν τῇ κιθάρᾳ, ᾄδειν δὲ ἄρχεται ἀπόμουσόν τι καὶ λεπτόν, ὥστε γέλωτα μὲν παρὰ πάντων γενέσθαι τῶν θεατῶν, τοὺς ἀθλοθέτας δὲ ἀγανακτήσαντας ἐπὶ τῇ τόλμῃ μαστιγώσαντας αὐτὸν ἐκβαλεῖν τοῦ θεάτρου· ὅτεπερ καὶ γελοιότατος ὤφθη δακρύων ὁ χρυσοῦς Εὐάγγελος καὶ ὑπὸ τῶν μαστιγοφόρων συρόμενος διὰ μέσης τῆς σκηνῆς καὶ τὰ σκέλη καθῃματωμένος ἐκ τῶν μαστίγων καὶ συλλέγων χαμάθεν τῆς κιθάρας τὰς σφραγῖδας· ἐξεπεπτώκεσαν γὰρ κἀκείνης συμμαστιγουμένης αὐτῷ.", "st": "28.9"}, {"sp": "N", "t": "μικρὸν δὲ ἐπισχὼν μετ’ αὐτὸν Εὔμηλός τις Ἠλεῖος εἰσέρχεται, κιθάραν μὲν παλαιὰν ἔχων, ξυλίνους δὲ κόλλοπας ἐπικειμένην, ἐσθῆτα δὲ μόγις σὺν τῷ στεφάνῳ δέκα δραχμῶν ἀξίαν· ἀλλ’ οὗτός γε ᾄσας δεξιῶς καὶ κιθαρίσας κατὰ τὸν νόμον τῆς τέχνης ἐκράτει καὶ ἀνεκηρύττετο καὶ τοῦ Εὐαγγέλου κατεγέλα μάτην ἐμπομπεύσαντος τῇ κιθάρᾳ καὶ ταῖς σφραγῖσιν ἐκείναις. καὶ εἰπεῖν γε λέγεται πρὸς αὐτόν· “ὦ Εὐάγγελε, σὺ μὲν χρυσῆν δάφνην περίκεισαι, πλουτεῖς γάρ, ἐγὼ δὲ ὁ πένης τὴν Δελφικήν. πλὴν τοῦτό γε μόνον ὤνησο τῆς σκευῆς, ὅτι μηδὲ ἐλεούμενος ἐπὶ τῇ ἥττῃ ἀπέρχῃ, ἀλλὰ μισούμενος προσέτι διὰ τὴν ἄτεχνόν σου ταύτην τρυφήν.” περὶ πόδα δή σοι καὶ Εὐάγγελος οὗτος, παρ’ ὅσον σοί γε οὐδ’ ὀλίγον μέλει τοῦ γέλωτος τῶν θεατῶν.", "st": "28.10"}, {"sp": "N", "t": "οὐκ ἄκαιρον δ’ ἂν γένοιτο καὶ Λέσβιον μῦθόν τινα διηγήσασθαί σοι πάλαι γενόμενον. ὅτε τὸν Ὀρφέα διεσπάσαντο αἱ Θρᾷτται, φασὶ τὴν κεφαλὴν αὐτοῦ σὺν τῇ λύρᾳ εἰς τὸν Ἕβρον ἐμπεσοῦσαν ἐκβληθῆναι εἰς τὸν μέλανα κόλπον, καὶ ἐπιπλεῖν γε τὴν κεφαλὴν τῇ λύρᾳ, τὴν μὲν ᾄδουσαν θρῆνόν τινα ἐπὶ τῷ Ὀρφεῖ, ὡς λόγος, τὴν λύραν δὲ αὐτὴν ὑπηχεῖν τῶν ἀνέμων ἐμπιπτόντων ταῖς χορδαῖς, καὶ οὕτω μετ’ ᾠδῆς προσενεχθῆναι τῇ Λέσβῳ, κἀκείνους ἀνελομένους τὴν μὲν κεφαλὴν καταθάψαι ἵναπερ νῦν τὸ Βακχεῖον αὐτοῖς ἐστι, τὴν λύραν δὲ ἀναθεῖναι εἰς τοῦ Ἀπόλλωνος τὸ ἱερόν, καὶ ἐπὶ πολύ γε σώζεσθαι αὐτήν.", "st": "28.11"}, {"sp": "N", "t": "χρόνῳ δὲ ὕστερον Νέανθον τὸν τοῦ Πιττακοῦ τοῦ τυράννου ταῦτα ὑπὲρ τῆς λύρας πυνθανόμενον, ὡς ἐκήλει μὲν θηρία καὶ φυτὰ καὶ λίθους, ἐμελῴδει δὲ καὶ μετὰ τὴν τοῦ Ὀρφέως συμφορὰν μηδενὸς ἁπτομένου, εἰς ἔρωτα τοῦ κτήματος ἐμπεσεῖν καὶ διαφθείραντα τὸν ἱερέα μεγάλοις χρήμασι πεῖσαι ὑποθέντα ἑτέραν ὁμοίαν λύραν δοῦναι αὐτῷ τὴν τοῦ Ὀρφέως. λαβόντα δὲ μεθ’ ἡμέραν μὲν ἐν τῇ πόλει χρῆσθαι οὐκ ἀσφαλὲς οἴεσθαι εἶναι, νύκτωρ δὲ ὑπὸ κόλπου ἔχοντα μόνον προελθεῖν εἰς τὸ προάστειον καὶ προχειρισάμενον κρούειν καὶ συνταράττειν τὰς χορδὰς ἄτεχνον καὶ ἄμουσον νεανίσκον, ἐλπίζοντα μέλη τινὰ θεσπέσια ὑπηχήσειν τὴν λύραν ὑφ’ ὧν πάντας καταθέλξειν καὶ κηλήσειν, καὶ ὅλως μακάριον ἔσεσθαι κληρονομήσαντα τῆς Ὀρφέως μουσικῆς· ἄχρι δὴ συνελθόντας τοὺς κύνας πρὸς τὸν ἦχον — πολλοὶ δὲ ἦσαν αὐτόθι — διασπάσασθαι αὐτόν, ὡς τοῦτο γοῦν ὅμοιον τῷ Ὀρφεῖ παθεῖν καὶ μόνους ἐφ’ ἑαυτὸν συγκαλέσαι τοὺς κύνας. ὅτεπερ καὶ σαφέστατα ὤφθη ὡς οὐχ ἡ λύρα ἡ θέλγουσα ἦν, ἀλλὰ ἡ τέχνη καὶ ἡ ᾠδή, ἃ μόνα ἐξαίρετα τῷ Ὀρφεῖ παρὰ τῆς μητρὸς ὑπῆρχεν· ἡ λύρα δὲ ἄλλως κτῆμα ἦν, οὐδὲν ἄμεινον τῶν ἄλλων βαρβίτων.", "st": "28.12"}, {"sp": "N", "t": "καὶ τί σοι τὸν Ὀρφέα ἢ τὸν Νέανθον λέγω, ὅπου καὶ καθ’ ἡμᾶς αὐτοὺς ἐγένετό τις καὶ ἔτι ἐστίν, οἶμαι, ὃς τὸν Ἐπικτήτου λύχνον τοῦ Στωϊκοῦ κεραμεοῦν ὄντα τρισχιλίων δραχμῶν ἐπρίατο; ἤλπιζεν γὰρ οἶμαι κἀκεῖνος, εἰ τῶν νυκτῶν ὑπ’ ἐκείνῳ τῷ λύχνῳ ἀναγιγνώσκοι, αὐτίκα μάλα καὶ τὴν Ἐπικτήτου σοφίαν ὄναρ ἐπικτήσεσθαι καὶ ὅμοιος ἔσεσθαι τῷ θαυμαστῷ ἐκείνῳ γέροντι.", "st": "28.13"}, {"sp": "N", "t": "χθὲς δὲ καὶ πρῴην ἄλλος τις τὴν Πρωτέως τοῦ Κυνικοῦ βακτηρίαν, ἣν καταθέμενος ἥλατο εἰς τὸ πῦρ, ταλάντου κἀκεῖνος ἐπρίατο, καὶ ἔχει μὲν τὸ κειμήλιον τοῦτο καὶ δείκνυσιν ὡς Τεγεᾶται τοῦ Καλυδωνίου ὑὸς τὸ δέρμα καὶ Θηβαῖοι τὰ ὀστᾶ τοῦ Γηρυόνου καὶ Μεμφῖται τῆς Ἴσιδος τοὺς πλοκάμους· αὐτὸς δὲ ὁ τοῦ θαυμαστοῦ κτήματος δεσπότης καὶ αὐτὸν σὲ τῇ ἀπαιδευσίᾳ καὶ βδελυρίᾳ ὑπερηκόντισεν. ὁρᾷς ὅπως κακοδαιμόνως διάκειται, βακτηρίας εἰς τὴν κεφαλὴν ὡς ἀληθῶς δεόμενος.", "st": "28.14"}, {"sp": "N", "t": "λέγεται δὲ καὶ Διονύσιον τραγῳδίαν ποιεῖν φαύλως πάνυ καὶ γελοίως, ὥστε τὸν Φιλόξενον πολλάκις δι’ αὐτὴν εἰς τὰς λατομίας ἐμπεσεῖν οὐ δυνάμενον κατέχειν τὸν γέλωτα. οὗτος τοίνυν πυθόμενος ὡς ἐγγελᾶται, τὸ Αἰσχύλου πυξίον εἰς ὃ ἐκεῖνος ἔγραφε σὺν πολλῇ σπουδῇ κτησάμενος καὶ αὐτὸς ᾤετο ἔνθεος ἔσεσθαι καὶ κάτοχος ἐκ τοῦ πυξίου· ἀλλ’ ὅμως ἐν αὐτῷ ἐκείνῳ μακρῷ γελοιότερα ἔγραφεν, οἷον κἀκεῖνο τό·<br>Δωρὶς τέθνηκεν ἡ Διονυσίου γυνή.<br>καὶ πάλιν·<br>οἴμοι, γυναῖκα χρησίμην ἀπώλεσα.<br>καὶ τοῦτο γὰρ ἐκ τοῦ πυξίου, καὶ τό·<br>αὑτοῖς γὰρ ἐμπαίζουσιν οἱ μωροὶ βροτῶν.", "st": "28.15"}, {"sp": "N", "t": "Τοῦτο μέν γε πρὸς σὲ μάλιστα εὐστόχως ἂν εἰρημένον εἴη τῷ Διονυσίῳ, καὶ δι’ αὐτὸ χρυσῶσαι αὐτοῦ ἔδει ἐκεῖνο τὸ πυξίον.", "st": "28.15"}, {"sp": "N", "t": "τίνα γὰρ ἐλπίδα καὶ αὐτὸς ἔχων εἰς τὰ βιβλία καὶ ἀνατυλίττεις ἀεὶ καὶ διακολλᾷς καὶ περικόπτεις καὶ ἀλείφεις τῷ κρόκῳ καὶ τῇ κέδρῳ καὶ διφθέρας περιβάλλεις καὶ ὀμφαλοὺς ἐντίθης, ὡς δή τι ἀπολαύσων αὐτῶν; πάνυ γοῦν ἤδη βελτίων γεγένησαι διὰ τὴν ὠνήν, ὃς τοιαῦτα μὲν φθέγγῃ — μᾶλλον δὲ τῶν ἰχθύων ἀφωνότερος εἶ — βιοῖς δὲ ὡς οὐδ’ εἰπεῖν καλόν, μῖσος δὲ ἄγριον, φασί, παρὰ πάντων ἔχεις ἐπὶ τῇ βδελυρίᾳ· ὡς εἰ τοιούτους ἀπειργάζετο τὰ βιβλία, φυγῇ φευκτέον ἂν ἦν ὅτι πορρωτάτω ἀπ’ αὐτῶν.", "st": "28.16"}, {"sp": "N", "t": "δυοῖν δὲ ὄντοιν ἅττ’ ἂν παρὰ τῶν παλαιῶν τις κτήσαιτο, λέγειν τε δύνασθαι καὶ πράττειν τὰ δέοντα ζήλῳ τῶν ἀρίστων καὶ φυγῇ τῶν χειρόνων, ὅταν μήτε ἐκεῖνα μήτε ταῦτα φαίνηταί τις παρ’ αὐτῶν ὠφελούμενος, τί ἄλλο ἢ τοῖς μυσὶ διατριβὰς ὠνεῖται καὶ ταῖς τίλφαις οἰκήσεις καὶ πληγὰς ὡς ἀμελοῦσι τοῖς οἰκέταις;", "st": "28.17"}, {"sp": "N", "t": "πῶς δὲ οὐ κἀκεῖνο αἰσχρόν, εἴ τις ἐν τῇ χειρὶ ἔχοντά σε βιβλίον ἰδών — ἀεὶ δέ τι πάντως ἔχεις — ἔροιτο οὗτινος ἢ ῥήτορος ἢ συγγραφέως ἢ ποιητοῦ ἐστι, σὺ δὲ ἐκ τῆς ἐπιγραφῆς εἰδὼς πρᾴως εἴποις τοῦτό γε· εἶτα, ὡς φιλεῖ τὰ τοιαῦτα ἐν συνουσίᾳ προχωρεῖν εἰς μῆκος λόγων, ὁ μὲν ἐπαινοῖ τι ἢ αἰτιῷτο τῶν ἐγγεγραμμένων, σὺ δὲ ἀποροίης καὶ μηδὲν ἔχοις εἰπεῖν; οὐκ εὔξῃ τότε χανεῖν σοι τὴν γῆν, κατὰ σεαυτοῦ ὁ Βελλεροφόντης περιφέρων τὸ βιβλίον;", "st": "28.18"}, {"sp": "N", "t": "Δημήτριος δὲ ὁ Κυνικὸς ἰδὼν ἐν Κορίνθῳ ἀπαίδευτόν τινα βιβλίον κάλλιστον ἀναγιγνώσκοντα — τὰς Βάκχας οἶμαι τοῦ Εὐριπίδου, κατὰ τὸν ἄγγελον δὲ ἦν τὸν διηγούμενον τὰ τοῦ Πενθέως πάθη καὶ τὸ τῆς Ἀγαύης ἔργον — ἁρπάσας διέσπασεν αὐτὸ εἰπών, “ἄμεινόν ἐστι τῷ Πενθεῖ ἅπαξ σπαραχθῆναι ὑπ’ ἐμοῦ ἢ ὑπὸ σοῦ πολλάκις.”", "st": "28.19"}, {"sp": "N", "t": "Ζητῶν δὲ ἀεὶ πρὸς ἐμαυτὸν οὔπω καὶ τήμερον εὑρεῖν δεδύνημαι τίνος ἕνεκα τὴν σπουδὴν ταύτην ἐσπούδακας περὶ τὴν ὠνὴν τῶν βιβλίων· ὠφελείας μὲν γὰρ ἢ χρείας τῆς ἀπ’ αὐτῶν οὐδ’ ἂν οἰηθείη τις τῶν καὶ ἐπ’ ἐλάχιστόν σε εἰδότων, οὐ μᾶλλον ἢ φαλακρὸς ἄν τις πρίαιτο κτένας ἢ κάτοπτρον ὁ τυφλὸς ἢ ὁ κωφὸς αὐλητὴν ἢ παλλακὴν ὁ εὐνοῦχος ἢ ὁ ἠπειρώτης κώπην ἢ ὁ κυβερνήτης ἄροτρον. ἀλλὰ μὴ ἐπίδειξιν πλούτου σοι τὸ πρᾶγμα ἔχει καὶ βούλει τοῦτο ἐμφῆναι ἅπασιν, ὅτι καὶ εἰς τὰ μηδέν σοι χρήσιμα ὅμως ἐκ πολλῆς τῆς περιουσίας ἀναλίσκεις; καὶ μὴν ὅσα γε κἀμὲ Σύρον ὄντα εἰδέναι, εἰ μὴ σαυτὸν φέρων ταῖς τοῦ γέροντος ἐκείνου διαθήκαις παρενέγραψας, ἀπωλώλεις ἂν ὑπὸ λιμοῦ ἤδη καὶ ἀγορὰν προὐτίθεις τῶν βιβλίων.", "st": "28.19"}, {"sp": "N", "t": "λοιπὸν οὖν δὴ ἐκεῖνο, πεπεισμένον ὑπὸ τῶν κολάκων ὡς οὐ μόνον καλὸς εἶ καὶ ἐράσμιος ἀλλὰ σοφὸς καὶ ῥήτωρ καὶ συγγραφεὺς οἷος οὐδ’ ἕτερος, ὠνεῖσθαι τὰ βιβλία, ὡς ἀληθεύοις τοὺς ἐπαίνους αὐτῶν. φασὶ δὲ σὲ καὶ λόγους ἐπιδείκνυσθαι αὐτοῖς ἐπὶ δείπνῳ κἀκείνους χερσαίων βατράχων δίκην διψῶντας κεκραγέναι, ἢ μὴ πίνειν, ἢν μὴ διαρραγῶσι βοῶντες.", "st": "28.20"}, {"sp": "N", "t": "καὶ γὰρ οὐκ οἶδ’ ὅπως ῥᾷστος εἶ τῆς ῥινὸς ἕλκεσθαι, καὶ πιστεύεις αὐτοῖς ἅπαντα, ὅς ποτε κἀκεῖνο ἐπείσθης, ὡς βασιλεῖ τινι ὡμοιώθης τὴν ὄψιν, καθάπερ ὁ ψευδαλέξανδρος καὶ ὁ ψευδοφίλιππος ἐκεῖνος κναφεὺς καὶ ὁ κατὰ τοὺς προπάτορας ἡμῶν ψευδονέρων καὶ εἴ τις ἄλλος τῶν ὑπὸ τῷ ψευδο τεταγμένων.", "st": "28.20"}, {"sp": "N", "t": "καὶ τί θαυμαστὸν εἰ τοῦτο ἔπαθες, ἀνόητος καὶ ἀπαίδευτος ἄνθρωπος, καὶ προῄεις ἐξυπτιάζων καὶ μιμούμενος βάδισμα καὶ σχῆμα καὶ βλέμμα ἐκείνου ᾧ σεαυτὸν εἰκάζων ἔχαιρες, ὅπου καὶ Πύρρον φασὶ τὸν Ἠπειρώτην, τὰ ἄλλα θαυμαστὸν ἄνδρα, οὕτως ὑπὸ κολάκων ἐπὶ τῷ ὁμοίῳ ποτὲ διαφθαρῆναι ὡς πιστεύειν ὅτι ὅμοιος ἦν Ἀλεξάνδρῳ ἐκείνῳ; καίτοι τὸ τῶν μουσικῶν τοῦτο, δὶς διὰ πασῶν τὸ πρᾶγμα ἦν· εἶδον γὰρ καὶ τὴν τοῦ Πύρρου εἰκόνα· καὶ ὅμως ἐπέπειστο ἐκμεμάχθαι τοῦ Ἀλεξάνδρου τὴν μορφήν. ἀλλ’ ἕνεκα μὲν δὴ τούτων ὕβρισταί μοι εἰς τὸν Πύρρον, ὅτι σὲ εἴκασα κατὰ τοῦτο αὐτῷ· τὸ δὲ ἀπὸ τούτου καὶ πάνυ σοι πρέπον ἂν εἴη. ἐπεὶ γὰρ οὕτω διέκειτο ὁ Πύρρος καὶ ταῦτα ὑπὲρ ἑαυτοῦ ἐπέπειστο, οὐδεὶς ὅστις οὐ συνετίθετο καὶ συνέπασχεν αὐτῷ, ἄχρι δή τις ἐν Λαρίσῃ πρεσβῦτις ξένη αὐτῷ τἀληθὲς εἰποῦσα ἔπαυσεν αὐτὸν τῆς κορύζης. ὁ μὲν γὰρ Πύρρος ἐπιδείξας αὐτῇ εἰκόνα Φιλίππου καὶ Περδίκκου καὶ Ἀλεξάνδρου καὶ Κασσάνδρου καὶ ἄλλων βασιλέων ἤρετο τίνι ὅμοιος εἴη, πάνυ πεπεισμένος ἐπὶ τὸν Ἀλέξανδρον ἥξειν αὐτήν, ἡ δὲ πολὺν χρόνον ἐπισχοῦσα, “Βατραχίωνι,” ἔφη, “τῷ μαγείρῳ·” καὶ γὰρ ἦν τις ἐν τῇ Λαρίσῃ Βατραχίων μάγειρος τῷ Πύρρῳ ὅμοιος.", "st": "28.21"}, {"sp": "N", "t": "καὶ σὺ δὴ ᾧτινι μὲν τῶν τοῖς ὀρχησταῖς συνόντων κιναίδων ἔοικας οὐκ ἂν εἴποιμι, ὅτι δὲ μανίαν ἐρρωμένην ἔτι καὶ νῦν μαίνεσθαι δοκεῖς ἅπασιν ἐπ’ ἐκείνῃ τῇ εἰκόνι, πάνυ σαφῶς οἶδα. οὔκουν θαυμαστόν, εἰ ἀπίθανος οὕτως ζωγράφος ὢν καὶ τοῖς πεπαιδευμένοις ἐξομοιοῦσθαι ἐθέλεις, πιστεύων τοῖς τὰ τοιαῦτά σε ἐπαινοῦσι.", "st": "28.22"}, {"sp": "N", "t": "καίτοι τί ταῦτα ληρῶ; πρόδηλος γὰρ ἡ αἰτία τῆς περὶ τὰ βιβλία σπουδῆς, εἰ καὶ ὑπὸ νωθείας ἐγὼ μὴ πάλαι κατεῖδον· σοφὸν γάρ, ὡς γοῦν οἴει, τοῦτ’ ἐπινενόηκας καὶ ἐλπίδας οὐ μικρὰς ἔχεις περὶ τοῦ πράγματος, εἰ βασιλεὺς μάθοι ταῦτα σοφὸς ἀνὴρ καὶ παιδείαν μάλιστα τιμῶν· εἰ δὲ ταῦτα ὑπὲρ σοῦ ἐκεῖνος ἀκούσειεν, ὡς ὠνῇ βιβλία καὶ συνάγεις πολλά, πάντα ἐν βραχεῖ παρ’ αὐτοῦ ἔσεσθαί σοι νομίζεις.", "st": "28.22"}, {"sp": "N", "t": "ἀλλ’, ὦ κατάπυγον, οἴει τοσοῦτον μανδραγόραν κατακεχύσθαι αὐτοῦ ὡς ταῦτα μὲν ἀκούειν, ἐκεῖνα δὲ μὴ εἰδέναι, οἷος μέν σου ὁ μεθ’ ἡμέραν βίος, οἷοι δέ σοι πότοι, ὁποῖαι δὲ νύκτες καὶ οἵοις καὶ ἡλίκοις συγκαθεύδεις; οὐκ οἶσθα ὡς ὦτα καὶ ὀφθαλμοὶ πολλοὶ βασιλέως; τὰ δὲ σὰ οὕτω περιφανῆ ἐστιν ὡς καὶ τυφλοῖς εἶναι καὶ κωφοῖς γνώριμα· εἰ γὰρ καὶ φθέγξαιο μόνον, εἰ γὰρ καὶ λουόμενος ἀποδύσαιο, μᾶλλον δὲ μὴ ἀποδύσῃ, εἰ δοκεῖ, οἱ δ’ οἰκέται μόνον ἢν ἀποδύσωνταί σου, τί οἴει; μὴ αὐτίκα ἔσεσθαι πάντα σου πρόδηλα τὰ τῆς νυκτὸς ἀπόρρητα; εἰπὲ γοῦν μοι καὶ τόδε, εἰ Βάσσος ὁ ὑμέτερος ἐκεῖνος σοφιστὴς ἢ Βάταλος ὁ αὐλητὴς ἢ ὁ κίναιδος Ἡμιθέων ὁ Συβαρίτης, ὃς τοὺς θαυμαστοὺς ὑμῖν νόμους συνέγραψεν, ὡς χρὴ λεαίνεσθαι καὶ παρατίλλεσθαι καὶ πάσχειν καὶ ποιεῖν ἐκεῖνα, — εἰ τούτων τις νυνὶ λεοντῆν περιβαλόμενος καὶ ῥόπαλον ἔχων βαδίζοι, τί οἴει φανεῖσθαι τοῖς ὁρῶσιν; Ἡρακλέα εἶναι αὐτόν; οὔκ, εἴ γε μὴ χύτραις λημῶντες τυγχάνοιεν. μυρία γάρ ἐστι τὰ ἀντιμαρτυροῦντα τῷ σχήματι, βάδισμα καὶ βλέμμα καὶ φωνὴ καὶ τράχηλος ἐπικεκλασμένος καὶ ψιμύθιον καὶ μαστίχη καὶ φῦκος, οἷς ὑμεῖς κοσμεῖσθε, καὶ ὅλως κατὰ τὴν παροιμίαν, θᾶττον ἂν πέντε ἐλέφαντας ὑπὸ μάλης κρύψειας ἢ ἕνα κίναιδον. εἶτα ἡ λεοντῆ μὲν τὸν τοιοῦτον οὐκ ἂν ἔκρυψεν, σὺ δ’ οἴει λήσειν σκεπόμενος βιβλίῳ; ἀλλ’ οὐ δυνατόν· προδώσει γάρ σε καὶ ἀποκαλύψει τὰ ἄλλα ὑμῶν γνωρίσματα.", "st": "28.23"}, {"sp": "N", "t": "τὸ δ’ ὅλον ἀγνοεῖν μοι δοκεῖς ὅτι τὰς ἀγαθὰς ἐλπίδας οὐ παρὰ τῶν βιβλιοκαπήλων δεῖ ζητεῖν, ἀλλὰ παρ’ αὑτοῦ καὶ τοῦ καθ’ ἡμέραν βίου λαμβάνειν. σὺ δ’ οἴει συνήγορον κοινὸν καὶ μάρτυρα ἔσεσθαί σοι τὸν Ἀττικὸν καὶ Καλλῖνον τοὺς βιβλιογράφους; οὔκ, ἀλλ’ ὠμούς τινας ἀνθρώπους ἐπιτρίψοντάς σε, ἢν οἱ θεοὶ ἐθέλωσι, καὶ πρὸς ἔσχατον πενίας συνελάσοντας· δέον ἔτι νῦν σωφρονήσαντα ἀποδόσθαι μέν τινι τῶν πεπαιδευμένων τὰ βιβλία ταῦτα καὶ σὺν αὐτοῖς τὴν νεόκτιστον ταύτην οἰκίαν, ἀποδοῦναι δὲ τοῖς ἀνδραποδοκαπήλοις μέρος γοῦν ἀπὸ πολλῶν τῶν ὀφειλομένων.", "st": "28.24"}, {"sp": "N", "t": "καὶ γὰρ κἀκεῖνα· περὶ δύο ταῦτα δεινῶς ἐσπούδακας, βιβλίων τε τῶν πολυτελῶν κτῆσιν καὶ μειρακίων τῶν ἐξώρων καὶ ἤδη καρτερῶν ὠνήν, καὶ τὸ πρᾶγμά σοι πάνυ σπουδάζεται καὶ θηρεύεται. ἀδύνατον δὲ πένητα ὄντα πρὸς ἄμφω διαρκεῖν. σκόπει τοίνυν ὡς ἱερὸν χρῆμα συμβουλή. ἀξιῶ γάρ σε ἀφέμενον τῶν μηδὲν προσηκόντων τὴν ἑτέραν νόσον θεραπεύειν καὶ τοὺς ὑπηρέτας ἐκείνους ὠνεῖσθαι, ὅπως μὴ ἐπιλειπόντων σε τῶν οἴκοθεν μεταστέλλοιό τινας τῶν ἐλευθέρων, οἷς ἀκίνδυνον ἀπελθοῦσιν, ἢν μὴ λάβωσιν ἅπαντα, ἐξαγορεῦσαι τὰ πραχθέντα ὑμῖν μετὰ τὸν πότον, οἷα καὶ πρῴην αἴσχιστα περὶ σοῦ διηγεῖτο ἐξελθὼν ὁ πόρνος, ἔτι καὶ δήγματα ἐπιδεικνύς. ἀλλ’ ἔγωγε καὶ μάρτυρας ἂν παρασχοίμην τοὺς τότε παρόντας ὡς ἠγανάκτησα καὶ ὀλίγου πληγὰς ἐνέτριψα αὐτῷ χαλεπαίνων ὑπὲρ σοῦ, καὶ μάλισθ’ ὅτε καὶ ἄλλον ἐπεκαλέσατο μάρτυρα τῶν ὁμοίων καὶ ἄλλον ταὐτὰ καὶ λόγοις διηγουμένους. πρὸς δὴ ταῦτα, ὦγαθέ, ταμιεύου τἀργύριον καὶ φύλαττε, ὡς οἴκοι καὶ κατὰ πολλὴν ἀσφάλειαν ταῦτα ποιεῖν καὶ πάσχειν ἔχῃς. ὥστε μὲν γὰρ μηκέτι ἐργάζεσθαι τίς ἂν μεταπείσειέ σε; οὐδὲ γὰρ κύων ἅπαξ παύσαιτ’ ἂν σκυτοτραγεῖν μαθοῦσα.", "st": "28.25"}, {"sp": "N", "t": "τὸ δ’ ἕτερον ῥᾴδιον, τὸ μηκέτι ὠνεῖσθαι βιβλία. ἱκανῶς πεπαίδευσαι, ἅλις σοι τῆς σοφίας. μόνον οὐκ ἐπ’ ἄκρου τοῦ χείλους ἔχεις τὰ παλαιὰ πάντα. πᾶσαν μὲν ἱστορίαν οἶσθα, πάσας δὲ λόγων τέχνας καὶ κάλλη αὐτῶν καὶ κακίας καὶ ὀνομάτων χρῆσιν τῶν Ἀττικῶν· πάνσοφόν τι χρῆμα καὶ ἄκρον ἐν παιδείᾳ γεγένησαι διὰ τὸ πλῆθος τῶν βιβλίων. κωλύει γὰρ οὐδὲν κἀμέ σοι ἐνδιατρίβειν, ἐπειδὴ χαίρεις ἐξαπατώμενος.", "st": "28.26"}, {"sp": "N", "t": "ἡδέως δ’ ἂν καὶ ἐροίμην σε, τὰ τοσαῦτα βιβλία ἔχων τί μάλιστα ἀναγιγνώσκεις αὐτῶν; τὰ Πλάτωνος; τὰ Ἀντισθένους; τὰ Ἀρχιλόχου; τὰ Ἱππώνακτος; ἢ τούτων μὲν ὑπερφρονεῖς, ῥήτορες δὲ μάλιστά σοι διὰ χειρός; εἰπέ μοι, καὶ Αἰσχίνου τὸν κατὰ Τιμάρχου λόγον ἀναγιγνώσκεις; ἢ ἐκεῖνά γε πάντα οἶσθα καὶ γιγνώσκεις αὐτῶν ἕκαστον, τὸν δὲ Ἀριστοφάνην καὶ τὸν Εὔπολιν ὑποδέδυκας; ἀνέγνως καὶ τοὺς Βάπτας, τὸ δρᾶμα ὅλον; εἶτ’ οὐδέν σου τἀκεῖ καθίκετο, οὐδ’ ἠρυθρίασας γνωρίσας αὐτά; τοῦτο γοῦν καὶ μάλιστα θαυμάσειεν ἄν τις, τίνα ποτὲ ψυχὴν ἔχων ἅπτῃ τῶν βιβλίων, ὁποίαις αὐτὰ χερσὶν ἀνελίττεις. πότε δὲ ἀναγιγνώσκεις; μεθ’ ἡμέραν; ἀλλ’ οὐδεὶς ἑώρακε τοῦτο ποιοῦντα. ἀλλὰ νύκτωρ; πότερον ἐπιτεταγμένος ἤδη ἐκείνοις ἢ πρὸ τῶν λόγων;", "st": "28.27"}, {"sp": "N", "t": "ἀλλὰ πρὸς Κότυος μηκέτι μὴ τολμήσῃς τοιοῦτο μηδέν, ἄφες δὲ τὰ βιβλία καὶ μόνα ἐργάζου τὰ σαυτοῦ. καίτοι ἐχρῆν μηκέτι μηδὲ ἐκεῖνα, αἰδεσθῆναι δὲ τὴν τοῦ Εὐριπίδου Φαίδραν καὶ ὑπὲρ τῶν γυναικῶν ἀγανακτοῦσαν καὶ λέγουσαν,<br>οὐδὲ σκότον φρίσσουσι τὸν συνεργάτην<br>τέρεμνά τ’ οἴκων μή ποτε φθογγὴν ἀφῇ.<br>εἰ δὲ πάντως ἐμμένειν τῇ ὁμοίᾳ νόσῳ διέγνωσται, ἴθι, ὠνοῦ μὲν βιβλία καὶ οἴκοι κατακλείσας ἔχε καὶ καρποῦ τὴν δόξαν τῶν κτημάτων. ἱκανόν σοι καὶ τοῦτο. προσάψῃ δὲ μηδέποτε μηδὲ ἀναγνῷς μηδὲ ὑπαγάγῃς τῇ γλώττῃ παλαιῶν ἀνδρῶν λόγους καὶ ποιήματα μηδὲν δεινόν σε εἰργασμένα.", "st": "28.28"}, {"sp": "N", "t": "οἶδα ὡς μάτην ταῦτά μοι λελήρηται καὶ κατὰ τὴν παροιμίαν Αἰθίοπα σμήχειν ἐπιχειρῶ· σὺ γὰρ ὠνήσῃ καὶ χρήσῃ εἰς οὐδὲν καὶ καταγελασθήσῃ πρὸς τῶν πεπαιδευμένων, οἷς ἀπόχρη ὠφελεῖσθαι οὐκ ἐκ τοῦ κάλλους τῶν βιβλίων οὐδ’ ἐκ τῆς πολυτελείας αὐτῶν, ἀλλ’ ἐκ τῆς φωνῆς καὶ τῆς γνώμης τῶν γεγραφότων.", "st": "28.28"}, {"sp": "N", "t": "σὺ δὲ οἴει θεραπεύσειν τὴν ἀπαιδευσίαν καὶ ἐπικαλύψειν τῇ δόξῃ ταύτῃ καὶ ἐκπλήξειν τῷ πλήθει τῶν βιβλίων, οὐκ εἰδὼς ὅτι καὶ οἱ ἀμαθέστατοι τῶν ἰατρῶν τὸ αὐτὸ σοὶ ποιοῦσιν, ἐλεφαντίνους νάρθηκας καὶ σικύας ἀργυρᾶς ποιούμενοι καὶ σμίλας χρυσοκολλήτους· ὁπόταν δὲ καὶ χρήσασθαι τούτοις δέῃ, οἱ μὲν οὐδὲ ὅπως χρὴ μεταχειρίσασθαι αὐτὰ ἴσασιν· παρελθὼν δέ τις εἰς τὸ μέσον τῶν μεμαθηκότων φλεβότομον εὖ μάλα ἠκονημένον ἔχων ἰοῦ τἄλλα μεστὸν ἀπήλλαξε τῆς ὀδύνης τὸν νοσοῦντα. ἵνα δὲ καὶ γελοιοτέρῳ τινὶ τὰ σὰ εἰκάσω, τοὺς κουρέας τούτους ἐπίσκεψαι, καὶ ὄψει τοὺς μὲν τεχνίτας αὐτῶν ξυρὸν καὶ μαχαιρίδας καὶ κάτοπτρον σύμμετρον ἔχοντας, τοὺς δὲ ἀμαθεῖς καὶ ἰδιώτας πλῆθος μαχαιρίδων προτιθέντας καὶ κάτοπτρα μεγάλα, οὐ μὴν λήσειν γε διὰ ταῦτα οὐδὲν εἰδότας. ἀλλὰ τὸ γελοιότατον ἐκεῖνο πάσχουσιν, ὅτι κείρονται μὲν οἱ πολλοὶ παρὰ τοῖς γείτοσιν αὐτῶν, πρὸς δὲ τὰ ἐκείνων κάτοπτρα προσελθόντες τὰς κόμας εὐθετίζουσιν.", "st": "28.29"}, {"sp": "N", "t": "καὶ σὺ τοίνυν ἄλλῳ μὲν δεηθέντι χρήσειας ἂν τὰ βιβλία, χρήσασθαι δὲ αὐτὸς οὐκ ἂν δύναιο. καίτοι οὐδὲ ἔχρησάς τινι βιβλίον πώποτε, ἀλλὰ τὸ τῆς κυνὸς ποιεῖς τῆς ἐν τῇ φάτνῃ κατακειμένης, ἣ οὔτε αὐτὴ τῶν κριθῶν ἐσθίει οὔτε τῷ ἵππῳ δυναμένῳ φαγεῖν ἐπιτρέπει.", "st": "28.30"}, {"sp": "N", "t": "ταῦτα τό γε νῦν εἶναι ὑπὲρ μόνων τῶν βιβλίων παρρησιάζομαι πρὸς σέ, περὶ δὲ τῶν ἄλλων ὅσα κατάπτυστα καὶ ἐπονείδιστα ποιεῖς, αὖθις ἀκούσῃ πολλάκις.", "st": "28.30"}, {"sp": "HDR", "t": "Περὶ τοῦ Ἐνυπνίου ἤτοι Βίος Λουκιανοῦ"}, {"sp": "N", "t": "ἄρτι μὲν ἐπεπαύμην εἰς τὰ διδασκαλεῖα φοιτῶν ἤδη τὴν ἡλικίαν πρόσηβος ὤν, ὁ δὲ πατὴρ ἐσκοπεῖτο μετὰ τῶν φίλων ὅ τι καὶ διδάξαιτό με. τοῖς πλείστοις οὖν ἔδοξεν παιδεία μὲν καὶ πόνου πολλοῦ καὶ χρόνου μακροῦ καὶ δαπάνης οὐ μικρᾶς καὶ τύχης δεῖσθαι λαμπρᾶς, τὰ δ’ ἡμέτερα μικρά τε εἶναι καὶ ταχεῖάν τινα τὴν ἐπικουρίαν ἀπαιτεῖν· εἰ δέ τινα τέχνην τῶν βαναύσων τούτων ἐκμάθοιμι, τὸ μὲν πρῶτον εὐθὺς ἂν αὐτὸς ἔχειν τὰ ἀρκοῦντα παρὰ τῆς τέχνης καὶ μηκέτ’ οἰκόσιτος εἶναι τηλικοῦτος ὤν, οὐκ εἰς μακρὰν δὲ καὶ τὸν πατέρα εὐφρανεῖν ἀποφέρων ἀεὶ τὸ γιγνόμενον.", "st": "29.1"}, {"sp": "N", "t": "δευτέρας οὖν σκέψεως ἀρχὴ προὐτέθη, τίς ἀρίστη τῶν τεχνῶν καὶ ῥᾴστη ἐκμαθεῖν καὶ ἀνδρὶ ἐλευθέρῳ πρέπουσα καὶ πρόχειρον ἔχουσα τὴν χορηγίαν καὶ διαρκῆ τὸν πόρον. ἄλλου τοίνυν ἄλλην ἐπαινοῦντος, ὡς ἕκαστος γνώμης ἢ ἐμπειρίας εἶχεν, ὁ πατὴρ εἰς τὸν θεῖον ἀπιδών, — παρῆν γὰρ ὁ πρὸς μητρὸς θεῖος, ἄριστος ἑρμογλύφος εἶναι δοκῶν — “οὐ θέμις,” εἶπεν, “ἄλλην τέχνην ἐπικρατεῖν σοῦ παρόντος, ἀλλὰ τοῦτον ἄγε —” δείξας ἐμέ — “δίδασκε παραλαβὼν λίθων ἐργάτην ἀγαθὸν εἶναι καὶ συναρμοστὴν καὶ ἑρμογλυφέα· δύναται γὰρ καὶ τοῦτο, φύσεώς γε, ὡς οἶσθα, ἔχων δεξιῶς.” ἐτεκμαίρετο δὲ ταῖς ἐκ τοῦ κηροῦ παιδιαῖς· ὁπότε γὰρ ἀφεθείην ὑπὸ τῶν διδασκάλων, ἀποξέων ἂν τὸν κηρὸν ἢ βόας ἢ ἵππους ἢ καὶ νὴ Δί’ ἀνθρώπους ἀνέπλαττον, εἰκότας, ὡς ἐδόκουν τῷ πατρί· ἐφ’ οἷς παρὰ μὲν τῶν διδασκάλων πληγὰς ἐλάμβανον, τότε δὲ ἔπαινος εἰς τὴν εὐφυίαν καὶ ταῦτα ἦν, καὶ χρηστὰς εἶχον ἐπ’ ἐμοὶ τὰς ἐλπίδας ὡς ἐν βραχεῖ μαθήσομαι τὴν τέχνην, ἀπ’ ἐκείνης γε τῆς πλαστικῆς.", "st": "29.2"}, {"sp": "N", "t": "ἅμα τε οὖν ἐπιτήδειος ἐδόκει ἡμέρα τέχνης ἐνάρχεσθαι, κἀγὼ παρεδεδόμην τῷ θείῳ μὰ τὸν Δί’ οὐ σφόδρα τῷ πράγματι ἀχθόμενος, ἀλλά μοι καὶ παιδιάν τινα οὐκ ἀτερπῆ ἐδόκει ἔχειν καὶ πρὸς τοὺς ἡλικιώτας ἐπίδειξιν, εἰ φαινοίμην θεούς τε γλύφων καὶ ἀγαλμάτια μικρά τινα κατασκευάζων ἐμαυτῷ τε κἀκείνοις οἷς προῃρούμην. καὶ τό γε πρῶτον ἐκεῖνο καὶ σύνηθες τοῖς ἀρχομένοις ἐγίγνετο. ἐγκοπέα γάρ τινά μοι δοὺς ὁ θεῖος ἐκέλευσεν ἠρέμα καθικέσθαι πλακὸς ἐν μέσῳ κειμένης, ἐπειπὼν τὸ κοινὸν “ἀρχὴ δέ τοι ἥμισυ παντός.” σκληρότερον δὲ κατενεγκόντος ὑπ’ ἀπειρίας κατεάγη μὲν ἡ πλάξ, ὁ δὲ ἀγανακτήσας σκυτάλην τινὰ πλησίον κειμένην λαβὼν οὐ πρᾴως οὐδὲ προτρεπτικῶς μου κατήρξατο, ὥστε δάκρυά μοι τὰ προοίμια τῆς τέχνης.", "st": "29.3"}, {"sp": "N", "t": "ἀποδρὰς οὖν ἐκεῖθεν ἐπὶ τὴν οἰκίαν ἀφικνοῦμαι συνεχὲς ἀναλύζων καὶ δακρύων τοὺς ὀφθαλμοὺς ὑπόπλεως, καὶ διηγοῦμαι τὴν σκυτάλην καὶ τοὺς μώλωπας ἐδείκνυον, καὶ κατηγόρουν πολλήν τινα ὠμότητα, προσθεὶς ὅτι ὑπὸ φθόνου ταῦτα ἔδρασε, μὴ αὐτὸν ὑπερβάλωμαι κατὰ τὴν τέχνην. ἀνακτησαμένης δὲ τῆς μητρὸς καὶ πολλὰ τῷ ἀδελφῷ λοιδορησαμένης, ἐπεὶ νὺξ ἐπῆλθεν κατέδαρθον ἔτι ἔνδακρυς καὶ τὴν σκυτάλην ἐννοῶν.", "st": "29.4"}, {"sp": "N", "t": "μέχρι μὲν δὴ τούτων γελάσιμα καὶ μειρακιώδη τὰ εἰρημένα· τὰ μετὰ ταῦτα δὲ οὐκέτι εὐκαταφρόνητα, ὦ ἄνδρες, ἀκούσεσθε, ἀλλὰ καὶ πάνυ φιληκόων ἀκροατῶν δεόμενα· ἵνα γὰρ καθ’ Ὅμηρον εἴπω,<br>θεῖός μοι ἐνύπνιον ἦλθεν ὄνειρος<br>ἀμβροσίην διὰ νύκτα,<br>ἐναργὴς οὕτως ὥστε μηδὲν ἀπολείπεσθαι τῆς ἀληθείας. ἔτι γοῦν καὶ μετὰ τοσοῦτον χρόνον τά τε σχήματά μοι τῶν φανέντων ἐν τοῖς ὀφθαλμοῖς παραμένει καὶ ἡ φωνὴ τῶν ἀκουσθέντων ἔναυλος· οὕτω σαφῆ πάντα ἦν.", "st": "29.5"}, {"sp": "N", "t": "δύο γυναῖκες λαβόμεναι ταῖν χεροῖν εἷλκόν με πρὸς ἑαυτὴν ἑκατέρα μάλα βιαίως καὶ καρτερῶς· μικροῦ γοῦν με διεσπάσαντο πρὸς ἀλλήλας φιλοτιμούμεναι· καὶ γὰρ καὶ ἄρτι μὲν ἂν ἡ ἑτέρα ἐπεκράτει καὶ παρὰ μικρὸν ὅλον εἶχέ με, ἄρτι δ’ ἂν αὖθις ὑπὸ τῆς ἑτέρας εἰχόμην. ἐβόων δὲ πρὸς ἀλλήλας ἑκατέρα, ἡ μὲν ὡς αὐτῆς ὄντα με κεκτῆσθαι βούλοιτο, ἡ δὲ ὡς μάτην τῶν ἀλλοτρίων ἀντιποιοῖτο. ἦν δὲ ἡ μὲν ἐργατικὴ καὶ ἀνδρικὴ καὶ αὐχμηρὰ τὴν κόμην, τὼ χεῖρε τύλων ἀνάπλεως, διεζωσμένη τὴν ἐσθῆτα, τιτάνου καταγέμουσα, οἷος ἦν ὁ θεῖος ὁπότε ξέοι τοὺς λίθους· ἡ ἑτέρα δὲ μάλα εὐπρόσωπος καὶ τὸ σχῆμα εὐπρεπὴς καὶ κόσμιος τὴν ἀναβολήν.", "st": "29.6"}, {"sp": "N", "t": "τέλος δ’ οὖν ἐφιᾶσί μοι δικάζειν ὁποτέρᾳ βουλοίμην συνεῖναι αὐτῶν. προτέρα δὲ ἡ σκληρὰ ἐκείνη καὶ ἀνδρώδης ἔλεξεν·", "st": "29.6"}, {"sp": "N", "t": "“ἐγώ, φίλε παῖ, Ἑρμογλυφικὴ τέχνη εἰμί, ἣν χθὲς ἤρξω μανθάνειν, οἰκεία τέ σοι καὶ συγγενὴς οἴκοθεν· ὅ τε γὰρ πάππος σου —” εἰποῦσα τοὔνομα τοῦ μητροπάτορος — “λιθοξόος ἦν καὶ τὼ θείω ἀμφοτέρω καὶ μάλα εὐδοκιμεῖτον δι’ ἡμᾶς. εἰ δ’ ἐθέλεις λήρων μὲν καὶ φληνάφων τῶν παρὰ ταύτης ἀπέχεσθαι,” — δείξασα τὴν ἑτέραν — “ἕπεσθαι δὲ καὶ συνοικεῖν ἐμοί, πρῶτα μὲν θρέψῃ γεννικῶς καὶ τοὺς ὤμους ἕξεις καρτερούς, φθόνου δὲ παντὸς ἀλλότριος ἔσῃ· καὶ οὔποτε ἄπει ἐπὶ τὴν ἀλλοδαπήν, τὴν πατρίδα καὶ τοὺς οἰκείους καταλιπών, οὐδὲ ἐπὶ λόγοις... ἐπαινέσονταί σε πάντες.”", "st": "29.7"}, {"sp": "N", "t": "“μὴ μυσαχθῇς δὲ τοῦ σχήματος τὸ εὐτελὲς μηδὲ τῆς ἐσθῆτος τὸ πιναρόν· ἀπὸ γὰρ τοιούτων ὁρμώμενος καὶ Φειδίας ἐκεῖνος ἔδειξε τὸν Δία καὶ Πολύκλειτος τὴν Ἥραν εἰργάσατο καὶ Μύρων ἐπῃνέθη καὶ Πραξιτέλης ἐθαυμάσθη. προσκυνοῦνται γοῦν οὗτοι μετὰ τῶν θεῶν. εἰ δὴ τούτων εἷς γένοιο, πῶς μὲν οὐ κλεινὸς αὐτὸς παρὰ πᾶσιν ἀνθρώποις ἔσῃ, ζηλωτὸν δὲ καὶ τὸν πατέρα ἀποδείξεις, περίβλεπτον δὲ ἀποφανεῖς καὶ τὴν πατρίδα;”", "st": "29.8"}, {"sp": "N", "t": "Ταῦτα καὶ ἔτι τούτων πλείονα διαπταίουσα καὶ βαρβαρίζουσα πάμπολλα εἶπεν ἡ Τέχνη, μάλα δὴ σπουδῇ συνείρουσα καὶ πείθειν με πειρωμένη· ἀλλ’ οὐκέτι μέμνημαι· τὰ πλεῖστα γὰρ ἤδη μου τὴν μνήμην διέφυγεν.", "st": "29.8"}, {"sp": "N", "t": "ἐπεὶ δ’ οὖν ἐπαύσατο, ἄρχεται ἡ ἑτέρα ὧδέ πως·", "st": "29.8"}, {"sp": "N", "t": "“ἐγὼ δέ, ὦ τέκνον, Παιδεία εἰμὶ ἤδη συνήθης σοι καὶ γνωρίμη, εἰ καὶ μηδέπω εἰς τέλος μου πεπείρασαι. ἡλίκα μὲν οὖν τὰ ἀγαθὰ ποριῇ λιθοξόος γενόμενος, αὕτη προείρηκεν· οὐδὲν γὰρ ὅτι μὴ ἐργάτης ἔσῃ τῷ σώματι πονῶν κἀν τούτῳ τὴν ἅπασαν ἐλπίδα τοῦ βίου τεθειμένος, ἀφανὴς μὲν αὐτὸς ὤν, ὀλίγα καὶ ἀγεννῆ λαμβάνων, ταπεινὸς τὴν γνώμην, εὐτελὴς δὲ τὴν πρόοδον, οὔτε φίλοις ἐπιδικάσιμος οὔτε ἐχθροῖς φοβερὸς οὔτε τοῖς πολίταις ζηλωτός, ἀλλ’ αὐτὸ μόνον ἐργάτης καὶ τῶν ἐκ τοῦ πολλοῦ δήμου εἷς, ἀεὶ τὸν προὔχοντα ὑποπτήσσων καὶ τὸν λέγειν δυνάμενον θεραπεύων, λαγὼ βίον ζῶν καὶ τοῦ κρείττονος ἕρμαιον ὤν· εἰ δὲ καὶ Φειδίας ἢ Πολύκλειτος γένοιο καὶ πολλὰ θαυμαστὰ ἐξεργάσαιο, τὴν μὲν τέχνην ἅπαντες ἐπαινέσονται, οὐκ ἔστι δὲ ὅστις τῶν ἰδόντων, εἰ νοῦν ἔχοι, εὔξαιτ’ ἂν σοὶ ὅμοιος γενέσθαι· οἷος γὰρ ἂν ᾖς, βάναυσος καὶ χειρῶναξ καὶ ἀποχειροβίωτος νομισθήσῃ.”", "st": "29.9"}, {"sp": "N", "t": "ἢν δ’ ἐμοὶ πείθῃ, πρῶτον μέν σοι πολλὰ ἐπιδείξω παλαιῶν ἀνδρῶν ἔργα καὶ πράξεις θαυμαστὰς καὶ λόγους αὐτῶν ἀπαγγελῶ, καὶ πάντων ὡς εἰπεῖν ἔμπειρον ἀποφανῶ, καὶ τὴν ψυχήν, ὅπερ σοι κυριώτατόν ἐστι, κατακοσμήσω πολλοῖς καὶ ἀγαθοῖς κοσμήμασι — σωφροσύνῃ, δικαιοσύνῃ, εὐσεβείᾳ, πρᾳότητι, ἐπιεικείᾳ, συνέσει, καρτερίᾳ, τῷ τῶν καλῶν ἔρωτι, τῇ πρὸς τὰ σεμνότατα ὁρμῇ· ταῦτα γάρ ἐστιν ὁ τῆς ψυχῆς ἀκήρατος ὡς ἀληθῶς κόσμος. λήσει δέ σε οὔτε παλαιὸν οὐδὲν οὔτε νῦν γενέσθαι δέον, ἀλλὰ καὶ τὰ μέλλοντα προόψει μετ’ ἐμοῦ, καὶ ὅλως ἅπαντα ὁπόσα ἐστί, τά τε θεῖα τά τ’ ἀνθρώπινα, οὐκ εἰς μακράν σε διδάξομαι.", "st": "29.10"}, {"sp": "N", "t": "“καὶ ὁ νῦν πένης ὁ τοῦ δεῖνος, ὁ βουλευσάμενός τι περὶ ἀγεννοῦς οὕτω τέχνης, μετ’ ὀλίγον ἅπασι ζηλωτὸς καὶ ἐπίφθονος ἔσῃ, τιμώμενος καὶ ἐπαινούμενος καὶ ἐπὶ τοῖς ἀρίστοις εὐδοκιμῶν καὶ ὑπὸ τῶν γένει καὶ πλούτῳ προὐχόντων ἀποβλεπόμενος, ἐσθῆτα μὲν τοιαύτην ἀμπεχόμενος,” — δείξασα τὴν ἑαυτῆς· πάνυ δὲ λαμπρὰν ἐφόρει — “ἀρχῆς δὲ καὶ προεδρίας ἀξιούμενος. κἄν που ἀποδημῇς, οὐδ’ ἐπὶ τῆς ἀλλοδαπῆς ἀγνὼς οὐδ’ ἀφανὴς ἔσῃ· τοιαῦτά σοι περιθήσω τὰ γνωρίσματα ὥστε τῶν ὁρώντων ἕκαστος τὸν πλησίον κινήσας δείξει σε τῷ δακτύλῳ, οὗτος ἐκεῖνος λέγων.”", "st": "29.11"}, {"sp": "N", "t": "ἂν δέ τι σπουδῆς ἄξιον ἢ τοὺς φίλους ἢ καὶ τὴν πόλιν ὅλην καταλαμβάνῃ, εἰς σὲ πάντες ἀποβλέψονται· κἄν πού τι λέγων τύχῃς, κεχηνότες οἱ πολλοὶ ἀκούσονται, θαυμάζοντες καὶ εὐδαιμονίζοντές σε τῆς δυνάμεως τῶν λόγων καὶ τὸν πατέρα τῆς εὐποτμίας. ὃ δὲ λέγουσιν, ὡς ἄρα καὶ ἀθάνατοι γίγνονταί τινες ἐξ ἀνθρώπων, τοῦτό σοι περιποιήσω· καὶ γὰρ ἢν αὐτὸς ἐκ τοῦ βίου ἀπέλθῃς, οὔποτε παύσῃ συνὼν τοῖς πεπαιδευμένοις καὶ προσομιλῶν τοῖς ἀρίστοις. ὁρᾷς τὸν Δημοσθένην ἐκεῖνον, τίνος υἱὸν ὄντα ἐγὼ ἡλίκον ἐποίησα. ὁρᾷς τὸν Αἰσχίνην, ὡς τυμπανιστρίας υἱὸς ἦν, ἀλλ’ ὅμως αὐτὸν δι’ ἐμὲ Φίλιππος ἐθεράπευεν. ὁ δὲ Σωκράτης καὶ αὐτὸς ὑπὸ τῇ Ἑρμογλυφικῇ ταύτῃ τραφείς, ἐπειδὴ τάχιστα συνῆκεν τοῦ κρείττονος καὶ δραπετεύσας παρ’ αὐτῆς ηὐτομόλησεν ὡς ἐμέ, ἀκούεις ὡς παρὰ πάντων ᾄδεται.", "st": "29.12"}, {"sp": "N", "t": "ἀφεὶς δὲ αὖ τοὺς τηλικούτους καὶ τοιούτους ἄνδρας καὶ πράξεις λαμπρὰς καὶ λόγους σεμνοὺς καὶ σχῆμα εὐπρεπὲς καὶ τιμὴν καὶ δόξαν καὶ ἔπαινον καὶ προεδρίας καὶ δύναμιν καὶ ἀρχὰς καὶ τὸ ἐπὶ λόγοις εὐδοκιμεῖν καὶ τὸ ἐπὶ συνέσει εὐδαιμονίζεσθαι, χιτώνιόν τι πιναρὸν ἐνδύσῃ καὶ σχῆμα δουλοπρεπὲς ἀναλήψῃ καὶ μοχλία καὶ γλυφεῖα καὶ κοπέας καὶ κολαπτῆρας ἐν ταῖν χεροῖν ἕξεις κάτω νενευκὼς εἰς τὸ ἔργον, χαμαιπετὴς καὶ χαμαίζηλος καὶ πάντα τρόπον ταπεινός, ἀνακύπτων δὲ οὐδέποτε οὐδὲ ἀνδρῶδες οὐδὲ ἐλεύθερον οὐδὲν ἐπινοῶν, ἀλλὰ τὰ μὲν ἔργα ὅπως εὔρυθμα καὶ εὐσχήμονα ἔσται σοι προνοῶν, ὅπως δὲ αὐτὸς εὔρυθμός τε καὶ κόσμιος ἔσῃ, ἥκιστα πεφροντικώς, ἀλλ’ ἀτιμότερον ποιῶν σεαυτὸν λίθων.", "st": "29.13"}, {"sp": "N", "t": "ταῦτα ἔτι λεγούσης αὐτῆς οὐ περιμείνας ἐγὼ τὸ τέλος τῶν λόγων ἀναστὰς ἀπεφηνάμην, καὶ τὴν ἄμορφον ἐκείνην καὶ ἐργατικὴν ἀπολιπὼν μετέβαινον πρὸς τὴν Παιδείαν μάλα γεγηθώς, καὶ μάλιστα ἐπεί μοι καὶ εἰς νοῦν ἦλθεν ἡ σκυτάλη καὶ ὅτι πληγὰς εὐθὺς οὐκ ὀλίγας ἀρχομένῳ μοι χθὲς ἐνετρίψατο. ἡ δὲ ἀπολειφθεῖσα τὸ μὲν πρῶτον ἠγανάκτει καὶ τὼ χεῖρε συνεκρότει καὶ τοὺς ὀδόντας συνέπριε· τέλος δέ, ὥσπερ τὴν Νιόβην ἀκούομεν, ἐπεπήγει καὶ εἰς λίθον μετεβέβλητο. εἰ δὲ παράδοξα ἔπαθε, μὴ ἀπιστήσητε· θαυματοποιοὶ γὰρ οἱ ὄνειροι.", "st": "29.14"}, {"sp": "N", "t": "ἡ ἑτέρα δὲ πρός με ἀπιδοῦσα, “τοιγαροῦν ἀμείψομαί σε,” ἔφη, “τῆσδε τῆς δικαιοσύνης, ὅτι καλῶς τὴν δίκην ἐδίκασας, καὶ ἐλθὲ ἤδη, ἐπίβηθι τούτου τοῦ ὀχήματος,” — δείξασά τι ὄχημα ὑποπτέρων ἵππων τινῶν τῷ Πηγάσῳ ἐοικότων — “ὅπως εἰδῇς οἷα καὶ ἡλίκα μὴ ἀκολουθήσας ἐμοὶ ἀγνοήσειν ἔμελλες.” ἐπεὶ δὲ ἀνῆλθον, ἡ μὲν ἤλαυνε καὶ ὑφηνιόχει, ἀρθεὶς δὲ εἰς ὕψος ἐγὼ ἐπεσκόπουν ἀπὸ τῆς ἕω ἀρξάμενος ἄχρι πρὸς τὰ ἑσπέρια πόλεις καὶ ἔθνη καὶ δήμους, καθάπερ ὁ Τριπτόλεμος ἀποσπείρων τι εἰς τὴν γῆν. οὐκέτι μέντοι μέμνημαι ὅ τι τὸ σπειρόμενον ἐκεῖνο ἦν, πλὴν τοῦτο μόνον ὅτι κάτωθεν ἀφορῶντες ἄνθρωποι ἐπῄνουν καὶ μετ’ εὐφημίας καθ’ οὓς γενοίμην τῇ πτήσει παρέπεμπον.", "st": "29.15"}, {"sp": "N", "t": "δείξασα δέ μοι τὰ τοσαῦτα κἀμὲ τοῖς ἐπαινοῦσιν ἐκείνοις ἐπανήγαγεν αὖθις, οὐκέτι τὴν αὐτὴν ἐσθῆτα ἐκείνην ἐνδεδυκότα ἣν εἶχον ἀφιπτάμενος, ἀλλά μοι ἐδόκουν εὐπάρυφός τις ἐπανήκειν. καταλαβοῦσα οὖν καὶ τὸν πατέρα ἑστῶτα καὶ περιμένοντα ἐδείκνυεν αὐτῷ ἐκείνη τὴν ἐσθῆτα κἀμέ, οἷος ἥκοιμι, καί τι καὶ ὑπέμνησεν οἷα μικροῦ δεῖν περὶ ἐμοῦ ἐβουλεύσαντο.", "st": "29.16"}, {"sp": "N", "t": "ταῦτα μέμνημαι ἰδὼν ἀντίπαις ἔτι ὤν, ἐμοὶ δοκεῖν ἐκταραχθεὶς πρὸς τὸν τῶν πληγῶν φόβον.", "st": "29.16"}, {"sp": "N", "t": "μεταξὺ δὲ λέγοντος, “Ἡράκλεις,” ἔφη τις, “ὡς μακρὸν τὸ ἐνύπνιον καὶ δικανικόν.” εἶτ’ ἄλλος ὑπέκρουσε, “χειμερινὸς ὄνειρος, ὅτε μήκισταί εἰσιν αἱ νύκτες, ἢ τάχα που τριέσπερος, ὥσπερ ὁ Ἡρακλῆς, καὶ αὐτός ἐστι. τί δ’ οὖν ἐπῆλθεν αὐτῷ ληρῆσαι ταῦτα πρὸς ἡμᾶς καὶ μνησθῆναι παιδικῆς νυκτὸς καὶ ὀνείρων παλαιῶν καὶ γεγηρακότων; ἕωλος γὰρ ἡ ψυχρολογία. μὴ ὀνείρων τινὰς ὑποκριτὰς ἡμᾶς ὑπείληφεν;” οὔκ, ὦγαθέ· οὐδὲ γὰρ ὁ Ξενοφῶν ποτε διηγούμενος τὸ ἐνύπνιον, ὡς ἐδόκει αὐτῷ κεραυνὸς ἐμπεσὼν καίειν τὴν πατρῴαν οἰκίαν καὶ τὰ ἄλλα, — ἴστε γάρ — οὐχ ὑπόκρισιν τὴν ὄψιν οὐδ’ ὡς φλυαρεῖν ἐγνωκὼς αὐτὰ διεξῄει, καὶ ταῦτα ἐν πολέμῳ καὶ ἀπογνώσει πραγμάτων, περιεστώτων πολεμίων, ἀλλά τι καὶ χρήσιμον εἶχεν ἡ διήγησις.", "st": "29.17"}, {"sp": "N", "t": "καὶ τοίνυν κἀγὼ τοῦτον τὸν ὄνειρον ὑμῖν διηγησάμην ἐκείνου ἕνεκα, ὅπως οἱ νέοι πρὸς τὰ βελτίω τρέπωνται καὶ παιδείας ἔχωνται, καὶ μάλιστα εἴ τις αὐτῶν ὑπὸ πενίας ἐθελοκακεῖ καὶ πρὸς τὴν ἥττω ἀποκλίνει, φύσιν οὐκ ἀγεννῆ διαφθείρων. ἐπιρρωσθήσεται εὖ οἶδ’ ὅτι κἀκεῖνος ἀκούσας τοῦ μύθου, ἱκανὸν ἑαυτῷ παράδειγμα ἐμὲ προστησάμενος, ἐννοῶν οἷος μὲν ὢν πρὸς τὰ κάλλιστα ὥρμησα καὶ παιδείας ἐπεθύμησα, μηδὲν ἀποδειλιάσας πρὸς τὴν πενίαν τὴν τότε, οἷος δὲ πρὸς ὑμᾶς ἐπανελήλυθα, εἰ καὶ μηδὲν ἄλλο, οὐδενὸς γοῦν τῶν λιθογλύφων ἀδοξότερος.", "st": "29.18"}, {"sp": "HDR", "t": "Περὶ τοῦ Παρασίτου ὅτι Τέχνη ἡ Παρασιτική"}, {"sp": "N", "t": "<em>Τυχιάδης.<\/em> τί ποτε ἄρα, ὦ Σίμων, οἱ μὲν ἄλλοι ἄνθρωποι καὶ ἐλεύθεροι καὶ δοῦλοι τέχνην ἕκαστός τινα ἐπίστανται δι’ ἧς αὑτοῖς τέ εἰσιν καὶ ἄλλῳ χρήσιμοι, σὺ δέ, ὡς ἔοικεν, ἔργον οὐδὲν ἔχεις δι’ οὗ ἄν τι ἢ αὐτὸς ἀπόναιο ἢ ἄλλῳ μεταδοίης;", "st": "30.1"}, {"sp": "N", "t": "<em>Σίμων.<\/em> πῶς τοῦτο ἐρωτᾷς, ὦ Τυχιάδη; οὐδέπω οἶδα. πειρῶ δὴ σαφέστερον ἐρωτᾶν.", "st": "30.1"}, {"sp": "N", "t": "<em>Τυχιάδης.<\/em> ἔστιν ἥντινα τυγχάνεις ἐπιστάμενος τέχνην, οἷον μουσικήν;", "st": "30.1"}, {"sp": "N", "t": "<em>Σίμων.<\/em> μὰ Δία.", "st": "30.1"}, {"sp": "N", "t": "<em>Τυχιάδης.<\/em> Τί δέ, ἰατρικήν;", "st": "30.1"}, {"sp": "N", "t": "<em>Σίμων.<\/em> οὐδὲ ταύτην.", "st": "30.1"}, {"sp": "N", "t": "<em>Τυχιάδης.<\/em> ἀλλὰ γεωμετρίαν;", "st": "30.1"}, {"sp": "N", "t": "<em>Σίμων.<\/em> οὐδαμῶς.", "st": "30.1"}, {"sp": "N", "t": "<em>Τυχιάδης.<\/em> τί δέ, ῥητορικήν; φιλοσοφίας μὲν γὰρ τοσοῦτον ἀπέχεις ὅσον καὶ ἡ κακία.", "st": "30.1"}, {"sp": "N", "t": "<em>Σίμων.<\/em> ἐγὼ μέν, εἰ οἷόν τε εἶναι, καὶ πλεῖον. ὥστε μὴ δόκει τοῦτο καθάπερ ἀγνοοῦντι ὀνειδίσαι· φημὶ γὰρ κακὸς εἶναι καὶ χείρων ἢ σὺ δοκεῖς.", "st": "30.1"}, {"sp": "N", "t": "<em>Τυχιάδης.<\/em> ναί. ἀλλὰ ταύτας μὲν ἴσως τὰς τέχνας οὐκ ἐξέμαθες διὰ μέγεθος αὐτῶν καὶ δυσκολίαν, τῶν δὲ δημοτικῶν τινα, τεκτονικὴν ἢ σκυτοτομικήν; καὶ γὰρ οὐδὲ τἄλλα οὕτως ἔχει σοι, ὡς μὴ καὶ τοιαύτης ἂν δεηθῆναι τέχνης.", "st": "30.1"}, {"sp": "N", "t": "<em>Σίμων.<\/em> ὀρθῶς λέγεις, ὦ Τυχιάδη· ἀλλ’ οὐδὲ γὰρ τούτων οὐδεμιᾶς ἐπιστήμων εἰμί.", "st": "30.1"}, {"sp": "N", "t": "<em>Τυχιάδης.<\/em> τίνος οὖν ἑτέρας;", "st": "30.1"}, {"sp": "N", "t": "<em>Σίμων.<\/em> τίνος; ὡς ἐγὼ οἶμαι, γενναίας· ἣν εἰ μάθοις, καὶ σὲ ἐπαινέσειν οἴομαι. ἔργῳ μὲν οὖν κατορθοῦν φημι ἤδη, εἰ δέ σοι καὶ λόγῳ, οὐκ ἔχω εἰπεῖν.", "st": "30.1"}, {"sp": "N", "t": "<em>Τυχιάδης.<\/em> τίνα ταύτην;", "st": "30.1"}, {"sp": "N", "t": "<em>Σίμων.<\/em> οὔπω μοι δοκῶ τοὺς περὶ ταύτην ἐκμεμελετηκέναι λόγους. ὥστε ὅτι τέχνην μέν τινα ἐπίσταμαι, ὑπάρχει ἤδη σοι γιγνώσκειν καὶ μὴ διὰ τοῦτο χαλεπῶς μοι ἔχειν· ἥντινα δέ, αὖθις ἀκούσῃ.", "st": "30.1"}, {"sp": "N", "t": "<em>Τυχιάδης.<\/em> ἀλλ’ οὐκ ἀνέξομαι.", "st": "30.1"}, {"sp": "N", "t": "<em>Σίμων.<\/em> τό γε τῆς τέχνης παράδοξον ἴσως φανεῖταί σοι ἀκούσαντι.", "st": "30.1"}, {"sp": "N", "t": "<em>Τυχιάδης.<\/em> καὶ μὴν διὰ τοῦτο σπουδάζω μαθεῖν.", "st": "30.1"}, {"sp": "N", "t": "<em>Σίμων.<\/em> εἰσαῦθις, ὦ Τυχιάδη.", "st": "30.1"}, {"sp": "N", "t": "<em>Τυχιάδης.<\/em> μηδαμῶς, ἀλλ’ ἤδη λέγε, εἰ μή περ ἄρα αἰσχύνῃ.", "st": "30.1"}, {"sp": "N", "t": "<em>Σίμων.<\/em> ἡ παρασιτική.", "st": "30.1"}, {"sp": "N", "t": "<em>Τυχιάδης.<\/em> κᾆτα εἰ μὴ μαίνοιτό τις, ὦ Σίμων, τέχνην ταύτην φαίη ἄν;", "st": "30.2"}, {"sp": "N", "t": "<em>Σίμων.<\/em> ἔγωγε· εἰ δέ σοι μαίνεσθαι δοκῶ, τοῦ μηδεμίαν ἄλλην ἐπίστασθαι τέχνην αἰτίαν εἶναί μοι τὴν μανίαν δόκει καί με τῶν ἐγκλημάτων ἤδη ἀφίει. φασὶ γὰρ τὴν δαίμονα ταύτην τὰ μὲν ἄλλα χαλεπὴν εἶναι τοῖς ἔχουσι, παραιτεῖσθαι δὲ τῶν ἁμαρτημάτων αὐτοὺς ὥσπερ διδάσκαλον ἢ παιδαγωγὸν τούτων ἀναδεχομένην εἰς αὑτὴν τὰς αἰτίας.", "st": "30.2"}, {"sp": "N", "t": "<em>Τυχιάδης.<\/em> οὐκοῦν, ὦ Σίμων, ἡ παρασιτικὴ τέχνη ἐστί;", "st": "30.2"}, {"sp": "N", "t": "<em>Σίμων.<\/em> τέχνη γάρ, κἀγὼ ταύτης δημιουργός.", "st": "30.2"}, {"sp": "N", "t": "<em>Τυχιάδης.<\/em> καὶ σὺ ἄρα παράσιτος;", "st": "30.2"}, {"sp": "N", "t": "<em>Σίμων.<\/em> πάνυ ὠνείδισας, ὦ Τυχιάδη.", "st": "30.2"}, {"sp": "N", "t": "<em>Τυχιάδης.<\/em> ἀλλ’ οὐκ ἐρυθριᾷς παράσιτον σαυτὸν καλῶν;", "st": "30.2"}, {"sp": "N", "t": "<em>Σίμων.<\/em> οὐδαμῶς· αἰσχυνοίμην γὰρ ἄν, εἰ μὴ λέγοιμι.", "st": "30.2"}, {"sp": "N", "t": "<em>Τυχιάδης.<\/em> καὶ νὴ Δία ὁπόταν σε βουλώμεθα γνωρίζειν τῶν οὐκ ἐπισταμένων τῳ, ὅτε χρῄζοι μαθεῖν, ὁ παράσιτος δῆλον ὅτι φήσομεν εὖ λέγοντες;", "st": "30.2"}, {"sp": "N", "t": "<em>Σίμων.<\/em> πολὺ μᾶλλον τοῦτο λέγοντες ἐμὲ ἢ Φειδίαν ἀγαλματοποιόν· χαίρω γὰρ τῇ τέχνῃ οὐδέν τι ἧττον ἢ Φειδίας ἔχαιρε τῷ Διί.", "st": "30.2"}, {"sp": "N", "t": "<em>Τυχιάδης.<\/em> καὶ μὴν ἐκεῖνό μοι σκοποῦντι προοῖσται γέλως πάμπολυς.", "st": "30.2"}, {"sp": "N", "t": "<em>Σίμων.<\/em> τὸ ποῖον;", "st": "30.2"}, {"sp": "N", "t": "<em>Τυχιάδης.<\/em> εἴ γε καὶ ταῖς ἐπιστολαῖς ἄνωθεν ὥσπερ ἔθος ἐπιγράφοιμεν, Σίμωνι παρασίτῳ.", "st": "30.2"}, {"sp": "N", "t": "<em>Σίμων.<\/em> καὶ μὴν ἂν ἐμοὶ μᾶλλον χαρίζοιο ἢ Δίωνι ἐπιγράφων φιλοσόφῳ.", "st": "30.2"}, {"sp": "N", "t": "<em>Τυχιάδης.<\/em> ἀλλὰ σὺ μὲν ὅπως χαίρεις καλούμενος, οὐδὲν ἢ μικρόν μοι μέλει· σκοπεῖν δὲ δεῖ καὶ τὴν ἄλλην ἀτοπίαν.", "st": "30.3"}, {"sp": "N", "t": "<em>Σίμων.<\/em> τίνα μήν;", "st": "30.3"}, {"sp": "N", "t": "<em>Τυχιάδης.<\/em> εἰ καὶ ταύτην ταῖς ἄλλαις τέχναις ἐγκαταλέξομεν, ὥστε ἐπειδὰν πυνθάνηταί τις, ὁποία τις αὕτη τέχνη ἐστί, λέγειν, οἷον γραμματικὴ ἢ ἰατρική, παρασιτική.", "st": "30.3"}, {"sp": "N", "t": "<em>Σίμων.<\/em> ἐγὼ μέν, ὦ Τυχιάδη, πολὺ μᾶλλον ταύτην ἤ τινα ἑτέραν τέχνην φαίην ἄν. εἰ δέ σοι φίλον ἀκούειν, καὶ ὅπως οἴομαι λέγοιμι ἄν, καίπερ οὐ παντάπασιν ὤν, ὡς ἔφθην εἰπών, ἐπὶ τοῦτο παρεσκευασμένος.", "st": "30.3"}, {"sp": "N", "t": "<em>Τυχιάδης.<\/em> οὐθέν, εἰ καὶ σμικρὰ λέγοις, ἀληθῆ δέ, διοίσει.", "st": "30.3"}, {"sp": "N", "t": "<em>Σίμων.<\/em> ἴθι δὴ πρῶτον, εἴ σοι δοκεῖ, περὶ τῆς τέχνης, ἥτις ποτὲ οὖσα τυγχάνει τῷ γένει, σκοπῶμεν· οὑτωσὶ γὰρ ἐπακολουθήσαιμεν ἂν καὶ ταῖς κατ’ εἶδος τέχναις, εἴπερ ἄρα ὀρθῶς μετέχοιεν αὐτῆς.", "st": "30.3"}, {"sp": "N", "t": "<em>Τυχιάδης.<\/em> τί ποτ’ οὖν ἐστιν ἡ τέχνη; πάντως ἐπίστασαι.", "st": "30.3"}, {"sp": "N", "t": "<em>Σίμων.<\/em> πάνυ μὲν οὖν.", "st": "30.3"}, {"sp": "N", "t": "<em>Τυχιάδης.<\/em> μὴ τοίνυν ὄκνει λέγειν αὐτήν, εἴπερ οἶσθα.", "st": "30.3"}, {"sp": "N", "t": "<em>Σίμων.<\/em> τέχνη ἐστίν, ὡς ἐγὼ διαμνημονεύω σοφοῦ τινος ἀκούσας, σύστημα ἐκ καταλήψεων συγγεγυμνασμένων πρός τι τέλος εὔχρηστον τῷ βίῳ.", "st": "30.4"}, {"sp": "N", "t": "<em>Τυχιάδης.<\/em> ὀρθῶς ἐκεῖνός γε εἰπὼν σύ τε ἀπομνημονεύσας.", "st": "30.4"}, {"sp": "N", "t": "<em>Σίμων.<\/em> εἰ δὲ μετέχοι τούτων ἁπάντων ἡ παρασιτική, τί ἂν ἄλλο ἢ καὶ αὐτὴ τέχνη εἴη;", "st": "30.4"}, {"sp": "N", "t": "<em>Τυχιάδης.<\/em> τέχνη γάρ, εἴπερ οὕτως ἔχοι.", "st": "30.4"}, {"sp": "N", "t": "<em>Σίμων.<\/em> φέρε δὴ καθ’ ἕκαστον τοῖς τῆς τέχνης εἴδεσιν ἐφαρμόζοντες τὴν παρασιτικήν, εἰ συνᾴδει σκοπῶμεν ἢ ὁ περὶ αὐτῆς λόγος, καθάπερ αἱ πονηραὶ χύτραι διακρουόμεναι, σαθρὸν ἀποφθέγγεται. δεῖ τοίνυν πᾶσαν τέχνην σύστημα ἐκ καταλήψεων … πρῶτον μὲν τὸ δοκιμάζειν καὶ διακρίνειν ὅστις ἂν ἐπιτήδειος γένοιτο τρέφειν αὐτόν, καὶ ὅτῳ παρασιτεῖν ἀρξάμενος οὐκ ἂν μεταγνοίη. ἢ τὸν μὲν ἀργυρογνώμονα τέχνην τινὰ φήσομεν ἔχειν, εἴπερ ἐπίσταται διαγιγνώσκειν τά τε κίβδηλα τῶν νομισμάτων καὶ τὰ μή, τοῦτον δὲ ἄνευ τέχνης διακρίνειν τούς τε κιβδήλους τῶν ἀνθρώπων καὶ τοὺς ἀγαθούς, καὶ ταῦτα οὐχ ὥσπερ τῶν νομισμάτων καὶ τῶν ἀνθρώπων φανερῶν εὐθὺς ὄντων; αὐτὰ μέντοι ταῦτα καὶ ὁ σοφὸς Εὐριπίδης καταμέμφεται λέγων·<br>ἀνδρῶν δ’ ὅτῳ χρὴ τὸν κακὸν διειδέναι,<br>οὐδεὶς χαρακτὴρ ἐμπέφυκε σώματι.<br>ᾧ δὴ καὶ μείζων ἡ τοῦ παρασίτου τέχνη, ἥ γε καὶ τὰ οὕτως ἄδηλα καὶ ἀφανῆ μᾶλλον τῆς μαντικῆς γνωρίζει τε καὶ οἶδεν.", "st": "30.4"}, {"sp": "N", "t": "τὸ δέ γε ἐπίστασθαι λόγους λέγειν ἐπιτηδείους καὶ πράγματα πράττειν δι’ ὧν οἰκειώσεται καὶ εὐνούστατον ἑαυτὸν τῷ τρέφοντι ἀποδείξει, ἆρ’ οὐ συνέσεως καὶ καταλήψεως ἐρρωμένης εἶναί σοι δοκεῖ;", "st": "30.5"}, {"sp": "N", "t": "<em>Τυχιάδης.<\/em> καὶ μάλα.", "st": "30.5"}, {"sp": "N", "t": "<em>Σίμων.<\/em> τὸ δέ γε ἐν ταῖς ἑστιάσεσιν αὐταῖς ὅπως παντὸς ἀπέλθοι πλέον ἔχων καὶ παρευδοκιμῶν τοὺς μὴ τὴν αὐτὴν αὐτῷ κεκτημένους τέχνην, ἄνευ τινὸς λόγου καὶ σοφίας πράττεσθαι οἴει;", "st": "30.5"}, {"sp": "N", "t": "<em>Τυχιάδης.<\/em> οὐδαμῶς.", "st": "30.5"}, {"sp": "N", "t": "<em>Σίμων.<\/em> τί δέ, τὸ ἐπίστασθαι τὰς ἀρετὰς καὶ κακίας τῶν σιτίων καὶ τῶν ὄψων πολυπραγμοσύνην ἀτέχνου τινὸς εἶναί σοι δοκεῖ, καὶ ταῦτα τοῦ γενναιοτάτου Πλάτωνος οὑτωσὶ λέγοντος, “τοῦ μέλλοντος ἑστιάσεσθαι μὴ μαγειρικοῦ ὄντος, σκευαζομένης θοίνης ἀκυροτέρα ἡ κρίσις;”", "st": "30.5"}, {"sp": "N", "t": "ὅτι γε μὴν οὐκ ἐκ καταλήψεως μόνον, ἀλλὰ συγγεγυμνασμένης ἐστὶν ἡ παρασιτική, μάθοις ἂν ἐνθένδε ῥᾳδίως· αἱ μὲν γὰρ τῶν ἄλλων τεχνῶν καταλήψεις καὶ ἡμέρας καὶ νύκτας καὶ μῆνας καὶ ἐνιαυτοὺς πολλάκις ἀσυγγύμναστοι μένουσιν, καὶ ὅμως οὐκ ἀπόλλυνται παρὰ τοῖς κεκτημένοις αἱ τέχναι, ἡ δὲ τοῦ παρασίτου κατάληψις εἰ μὴ καθ’ ἡμέραν εἴη ἐν γυμνασίᾳ, ἀπόλλυσιν οὐ μόνον, οἶμαι, τὴν τέχνην, ἀλλὰ καὶ αὐτὸν τὸν τεχνίτην.", "st": "30.6"}, {"sp": "N", "t": "τό γε μὴν “πρός τι τέλος εὔχρηστον τῷ βίῳ” μὴ καὶ μανίας ᾖ ζητεῖν. ἐγὼ γὰρ τοῦ φαγεῖν καὶ τοῦ πιεῖν οὐδὲν εὐχρηστότερον εὑρίσκω ἐν τῷ βίῳ, ὧν οὐδὲ ζῆν γε ἄνευ ἔστιν.", "st": "30.7"}, {"sp": "N", "t": "<em>Τυχιάδης.<\/em> πάνυ μὲν οὖν.", "st": "30.7"}, {"sp": "N", "t": "<em>Σίμων.<\/em> καὶ μὴν οὐδὲ τοιοῦτόν τί ἐστιν ἡ παρασιτικὴ ὁποῖον τὸ κάλλος καὶ ἡ ἰσχύς, ὥστε τέχνην μὲν μὴ δοκεῖν αὐτήν, δύναμιν δέ τινα τοιαύτην.", "st": "30.8"}, {"sp": "N", "t": "<em>Τυχιάδης.<\/em> ἀληθῆ λέγεις.", "st": "30.8"}, {"sp": "N", "t": "<em>Σίμων.<\/em> ἀλλὰ μέντοι οὐδὲ ἀτεχνία ἐστίν· ἡ γὰρ ἀτεχνία οὐδέποτε οὐδὲν κατορθοῖ τῷ κεκτημένῳ. φέρε γάρ, εἰ ἐπιτρέψειας σὺ σεαυτῷ ναῦν ἐν θαλάττῃ καὶ χειμῶνι μὴ ἐπιστάμενος κυβερνᾶν, σωθείης ἄν;", "st": "30.8"}, {"sp": "N", "t": "<em>Τυχιάδης.<\/em> ⟨οὐδαμῶς.⟩", "st": "30.8"}, {"sp": "N", "t": "<em>Σίμων.<\/em> ⟨τί δ’, εἰ ἵππους ἐπιτραφθείη τις μὴ ἐπιστάμενος ἠνιοχεῖν;⟩", "st": "30.8"}, {"sp": "N", "t": "<em>Τυχιάδης.<\/em> οὐδ’ οὗτος.", "st": "30.8"}, {"sp": "N", "t": "<em>Σίμων.<\/em> τί δή ποτε, ἢ τῷ μὴ ἔχειν τέχνην, δι’ ἧς δυνήσεται σώζειν ἑαυτόν;", "st": "30.8"}, {"sp": "N", "t": "<em>Τυχιάδης.<\/em> καὶ μάλα.", "st": "30.8"}, {"sp": "N", "t": "<em>Σίμων.<\/em> οὐκοῦν καὶ παράσιτος ὑπὸ τῆς παρασιτικῆς, εἴπερ ἦν ἀτεχνία, οὐκ ἂν ἐσώζετο;", "st": "30.8"}, {"sp": "N", "t": "<em>Τυχιάδης.<\/em> ναί.", "st": "30.8"}, {"sp": "N", "t": "<em>Σίμων.<\/em> οὐκοῦν τέχνῃ σώζεται, ἀτεχνίᾳ δὲ οὔ;", "st": "30.8"}, {"sp": "N", "t": "<em>Τυχιάδης.<\/em> πάνυ μὲν οὖν.", "st": "30.8"}, {"sp": "N", "t": "<em>Σίμων.<\/em> τέχνη ἄρα ἐστὶν ἡ παρασιτική.", "st": "30.8"}, {"sp": "N", "t": "<em>Τυχιάδης.<\/em> τέχνη, ὡς ἔοικεν.", "st": "30.8"}, {"sp": "N", "t": "<em>Σίμων.<\/em> καὶ μὴν κυβερνήτας μὲν ἀγαθοὺς ναυαγίᾳ περιπεσόντας καὶ ἡνιόχους τεχνίτας ἐκπεσόντας τῶν δίφρων οἶδα ἐγὼ πολλάκις, καὶ τοὺς μὲν συντριβέντας, τοὺς δὲ καὶ πάμπαν διαφθαρέντας, παρασίτου δὲ ναυάγιον οὐδὲ εἷς ἔχοι τοιοῦτον εἰπεῖν.", "st": "30.8"}, {"sp": "N", "t": "οὐκοῦν εἰ μήτε ἀτεχνία ἐστὶν ἡ παρασιτικὴ μήτε δύναμις, σύστημα δέ τι ἐκ καταλήψεων γεγυμνασμένων, τέχνη δῆλον ὅτι διωμολόγηται ἡμῖν σήμερον.", "st": "30.8"}, {"sp": "N", "t": "<em>Τυχιάδης.<\/em> ὅσον ἐκ τούτου εἰκάζω· ἀλλ’ ἐκεῖνο, ὅπως καὶ ὅρον ἡμῖν τινα γενναῖον ἀποδῷς τῆς παρασιτικῆς.", "st": "30.9"}, {"sp": "N", "t": "<em>Σίμων.<\/em> ὀρθῶς σύ γε λέγων. δοκεῖ γὰρ δή μοι οὕτως ἂν μάλιστα ὡρίσθαι· παρασιτική ἐστιν τέχνη ποτέων καὶ βρωτέων καὶ τῶν διὰ ταῦτα λεκτέων καὶ πρακτέων, τέλος δὲ αὐτῆς τὸ ἡδύ.", "st": "30.9"}, {"sp": "N", "t": "<em>Τυχιάδης.<\/em> ὑπέρευγέ μοι δοκεῖς ὁρίσασθαι τὴν σεαυτοῦ τέχνην· ἀλλ’ ἐκεῖνο σκόπει, μὴ πρὸς ἐνίους τῶν φιλοσόφων μάχη σοι περὶ τοῦ τέλους ᾖ.", "st": "30.9"}, {"sp": "N", "t": "<em>Σίμων.<\/em> καὶ μὴν ἀπόχρη γε εἴπερ ἔσται τὸ αὐτὸ τέλος εὐδαιμονίας καὶ παρασιτικῆς.", "st": "30.9"}, {"sp": "N", "t": "φανεῖται δὲ οὕτως· ὁ γὰρ σοφὸς Ὅμηρος τὸν τοῦ παρασίτου βίον θαυμάζων ὡς ἄρα μακάριος καὶ ζηλωτὸς εἴη μόνος, οὕτω φησίν·<br>οὐ γὰρ ἔγωγέ τί φημι τέλος χαριέστερον εἶναι,<br>ἢ ὅτ’ ἂν εὐφροσύνη μὲν ἔχῃ κάτα δῆμον ἅπαντα,<br>δαιτυμόνες δ’ ἀνὰ δώματ’ ἀκουάζωνται ἀοιδοῦ<br>ἥμενοι ἑξείης, παρὰ δὲ πλήθωσι τράπεζαι<br>σίτου καὶ κρειῶν, μέθυ δ’ ἐκ κρητῆρος ἀφύσσων<br>οἰνοχόος φορέῃσι καὶ ἐγχείῃ δεπάεσσι.<br>καὶ ὡς οὐχ ἱκανῶς ταῦτα θαυμάζων μᾶλλον τὴν αὑτοῦ γνώμην ποιεῖ φανερωτέραν εὖ λέγων·<br>τοῦτό τί μοι κάλλιστον ἐνὶ φρεσὶν εἴδεται εἶναι,<br>οὐχ ἕτερόν τι, ἐξ ὧν φησιν, ἢ τὸ παρασιτεῖν εὔδαιμον νομίζων. καὶ μὴν οὐδὲ τῷ τυχόντι ἀνδρὶ περιτέθεικε τούτους τοὺς λόγους, ἀλλὰ τῷ σοφωτάτῳ τῶν ὅλων. καίτοι γε εἴπερ ἐβούλετο Ὀδυσσεὺς τὸ κατὰ τοὺς Στωϊκοὺς ἐπαινεῖν τέλος, ἐδύνατο ταυτὶ λέγειν ὅτε τὸν Φιλοκτήτην ἀνήγαγεν ἐκ τῆς Λήμνου, ὅτε τὸ Ἴλιον ἐξεπόρθησεν, ὅτε τοὺς Ἕλληνας φεύγοντας κατέσχεν, ὅτε εἰς Τροίαν εἰσῆλθεν ἑαυτὸν μαστιγώσας καὶ κακὰ καὶ Στωϊκὰ ῥάκη ἐνδύς· ἀλλὰ τότε οὐκ εἶπε τοῦτο τέλος χαριέστερον. ἀλλὰ μὴν καὶ ἐν τῷ τῶν Ἐπικουρείων βίῳ γενόμενος αὖθις παρὰ τῇ Καλυψοῖ, ὅτε αὐτῷ ὑπῆρχεν ἐν ἀργίᾳ τε βιοτεύειν καὶ τρυφᾶν καὶ βινεῖν τὴν Ἄτλαντος θυγατέρα καὶ κινεῖν πάσας τὰς λείας κινήσεις, οὐδὲ τότε εἶπε τοῦτο τὸ τέλος χαριέστερον, ἀλλὰ τὸν τῶν παρασίτων βίον. ἐκαλοῦντο δὲ δαιτυμόνες οἱ παράσιτοι τότε. πῶς οὖν λέγει; πάλιν γὰρ ἄξιον ἀναμνησθῆναι τῶν ἐπῶν· οὐδὲν γὰρ οἷον ἀκούειν αὐτῶν πολλάκις λεγομένων· “δαιτυμόνες καθήμενοι ἑξείης·” καί·<br>παρὰ δὲ πλήθωσι τράπεζαι<br>σίτου καὶ κρειῶν.", "st": "30.10"}, {"sp": "N", "t": "ὅ γε μὴν Ἐπίκουρος σφόδρα ἀναισχύντως ὑφελόμενος τὸ τῆς παρασιτικῆς τέλος τῆς καθ’ αὑτὸν εὐδαιμονίας τέλος αὐτὸ ποιεῖ. καὶ ὅτι κλοπὴ τὸ πρᾶγμά ἐστιν καὶ οὐδὲν Ἐπικούρῳ μέλει τὸ ἡδύ, ἀλλὰ τῷ παρασίτῳ, οὕτω μάθοις ἄν. ἔγωγε ἡγοῦμαι τὸ ἡδὺ πρῶτον μὲν τὸ τῆς σαρκὸς ἀόχλητον, ἔπειτα τὸ μὴ θορύβου καὶ ταραχῆς τὴν ψυχὴν ἐμπεπλῆσθαι. τούτων τοίνυν ὁ μὲν παράσιτος ἑκατέρων τυγχάνει, ὁ δὲ Ἐπίκουρος οὐδὲ θατέρου· ὁ γὰρ ζητῶν περὶ σχήματος γῆς καὶ κόσμων ἀπειρίας καὶ μεγέθους ἡλίου καὶ ἀποστημάτων καὶ πρώτων στοιχείων καὶ περὶ θεῶν, εἴτε εἰσὶν εἴτε οὐκ εἰσί, καὶ περὶ αὐτοῦ τοῦ τέλους ἀεὶ πολεμῶν καὶ διαφερόμενος πρός τινας οὐ μόνον ἐν ἀνθρωπίναις, ἀλλὰ καὶ ἐν κοσμικαῖς ἐστιν ὀχλήσεσιν. ὁ δὲ παράσιτος πάντα καλῶς ἔχειν οἰόμενος καὶ πεπιστευκὼς μὴ ἄλλως ταῦτα ἔχειν ἄμεινον ἢ ἔχει, μετὰ πολλῆς ἀδείας καὶ γαλήνης, οὐδενὸς αὐτῷ τοιούτου παρενοχλοῦντος, ἐσθίει καὶ κοιμᾶται ὕπτιος ἀφεικὼς τοὺς πόδας καὶ τὰς χεῖρας ὥσπερ Ὀδυσσεὺς τῆς Σχερίας ἀποπλέων οἴκαδε.", "st": "30.11"}, {"sp": "N", "t": "καὶ μὴν οὐχὶ κατὰ ταῦτα μόνον οὐδὲν προσήκει τὸ ἡδὺ τῷ Ἐπικούρῳ, ἀλλὰ καὶ κατ’ ἐκεῖνα· ὁ γὰρ Ἐπίκουρος οὗτος, ὅστις ποτέ ἐστιν ὁ σοφός, ἤτοι φαγεῖν ἔχει ἢ οὔ· εἰ μὲν οὐκ ἔχει, οὐχ ὅπως ἡδέως ζήσεται, ἀλλ’ οὐδὲ ζήσεται· εἰ δὲ ἔχει, εἴτε παρ’ ἑαυτοῦ εἴτε παρ’ ἄλλου· εἰ μὲν οὖν παρ’ ἄλλου τὸ φαγεῖν ἔχοι, παράσιτός ἐστι καὶ οὐχ ὃς λέγει· εἰ δὲ παρ’ ἑαυτοῦ, οὐχ ἡδέως ζήσεται.", "st": "30.12"}, {"sp": "N", "t": "<em>Τυχιάδης.<\/em> πῶς οὐχ ἡδέως;", "st": "30.12"}, {"sp": "N", "t": "<em>Σίμων.<\/em> εἰ γὰρ ἔχοι τὸ φαγεῖν παρ’ ἑαυτοῦ, πολλά τοι, ὦ Τυχιάδη, τὰ ἀηδέα τῷ τοιούτῳ βίῳ παρακολουθεῖν ἀνάγκη· καὶ ἄθρει πόσα. δεῖ τὸν μέλλοντα βιώσεσθαι καθ’ ἡδονὴν τὰς ἐγγιγνομένας ὀρέξεις ἁπάσας ἀναπληροῦν. ἢ τί φής;", "st": "30.12"}, {"sp": "N", "t": "<em>Τυχιάδης.<\/em> κἀμοὶ δοκεῖ.", "st": "30.12"}, {"sp": "N", "t": "<em>Σίμων.<\/em> οὐκοῦν τῷ μὲν συχνὰ κεκτημένῳ ἴσως τοῦτο παρέχει, τῷ δὲ ὀλίγα καὶ μηδὲν οὐκέτι· ὥστε πένης οὐκ ἂν σοφὸς γένοιτο οὐδὲ ἐφίκοιτο τοῦ τέλους, λέγω δὴ τοῦ ἡδέος. ἀλλ’ οὐδὲ μὴν ὁ πλούσιος, ὁ παρὰ τῆς οὐσίας ἀφθόνως ταῖς ἐπιθυμίαις χορηγῶν, δυνήσεται τοῦδε ἐφικέσθαι. τί δή ποτε; ὅτι πᾶσα ἀνάγκη τὸν ἀναλίσκοντα τὰ ἑαυτοῦ πολλαῖς περιπίπτειν ἀηδίαις, τοῦτο μὲν τῷ μαγείρῳ κακῶς σκευάσαντι τὸ ὄψον μαχόμενον ἢ εἰ μὴ μάχοιτο φαῦλα παρὰ τοῦτο ἐσθίοντα τὰ ὄψα καὶ τοῦ ἡδέος ὑστεροῦντα, τοῦτο δὲ τῷ οἰκονομοῦντι τὰ κατὰ τὴν οἰκίαν, εἰ μὴ καλῶς οἰκονομοίη, μαχόμενον. ἢ οὐχ οὕτως;", "st": "30.12"}, {"sp": "N", "t": "<em>Τυχιάδης.<\/em> νὴ Δία, κἀμοὶ δοκεῖ.", "st": "30.12"}, {"sp": "N", "t": "<em>Σίμων.<\/em> τῷ μὲν οὖν Ἐπικούρῳ πάντα συμβαίνειν εἰκός, ὥστε οὐδέποτε τεύξεται τοῦ τέλους· τῷ δὲ παρασίτῳ οὔτε μάγειρός ἐστιν ᾧ χαλεπήναι, οὔτε ἀγρὸς οὔτε οἶκος οὔτε ἀργύρια, ὑπὲρ ὧν ἀπολλυμένων ἀχθεσθείη, ὥστε καὶ φάγοι καὶ πίοι μόνος οὗτος ὑπὸ μηδενός, ὧν ἐκείνους ἀνάγκη, ἐνοχλούμενος.", "st": "30.12"}, {"sp": "N", "t": "ἀλλ’ ὅτι μὲν τέχνη ἐστὶν ἡ παρασιτική, κἀκ τούτων καὶ τῶν ἄλλων ἱκανῶς δέδεικται. λοιπὸν ὅτι καὶ ἀρίστη δεικτέον, καὶ τοῦτο οὐχ ἁπλῶς, ἀλλὰ πρῶτον μέν, ὅτι κοινῇ πασῶν διαφέρει τῶν τεχνῶν, εἶτα ὅτι καὶ ἰδίᾳ ἑκάστης.", "st": "30.13"}, {"sp": "N", "t": "κοινῇ μὲν οὖν ἁπασῶν οὕτω διαφέρει· πάσης γὰρ τέχνης ἀνάγκη προάγειν μάθησιν πόνον φόβον πληγάς, ἅπερ οὐκ ἔστιν ὅστις οὐκ ἂν ἀπεύξαιτο· ταύτην δὲ τὴν τέχνην, ὡς ἔοικεν, μόνην ἔξεστι μαθεῖν ἄνευ πόνου. τίς γὰρ ἀπὸ δείπνου ποτὲ ἀπῆλθεν κλαίων, ὥσπερ τινὰς ἐκ τῶν διδασκάλων ὁρῶμεν, τίς δ’ ἐπὶ δεῖπνον ἀπιὼν ὤφθη σκυθρωπός, ὥσπερ οἱ εἰς διδασκαλεῖα φοιτῶντες; καὶ μὴν ὁ μὲν παράσιτος ἑκὼν αὐτὸς ἐπὶ δεῖπνον ἔρχεται μάλα ἐπιθυμῶν τῆς τέχνης, οἱ δὲ τὰς ἄλλας τέχνας μανθάνοντες μισοῦσιν αὐτάς, ὥστε ἔνιοι δι’ αὐτὰς ἀποδιδράσκουσι.", "st": "30.13"}, {"sp": "N", "t": "τί δέ, οὐ κἀκεῖνο ἐννοῆσαί σε δεῖ, ὅτι καὶ τοὺς ἐν ἐκείναις ταῖς τέχναις προκόπτοντας οἱ πατέρες καὶ μητέρες τούτοις τιμῶσι μάλιστα, οἷς καθ’ ἡμέραν καὶ τὸν παράσιτον, “καλῶς νὴ Δία ἔγραψεν ὁ παῖς,” λέγοντες, “δότε αὐτῷ φαγεῖν” “οὐκ ἔγραψεν ὀρθῶς, μὴ δότε;” οὕτω τὸ πρᾶγμα καὶ ἔντιμον καὶ ἐν τιμωρίᾳ μέγα φαίνεται.", "st": "30.13"}, {"sp": "N", "t": "καὶ μὴν αἱ ἄλλαι τέχναι τὸ τέλος ὕστερον τοῦτο ἔχουσι, μετὰ τὸ μαθεῖν καὶ τοὺς καρποὺς ἡδέως ἀπολαμβάνουσαι· πολλὴ γὰρ “καὶ ὄρθιος οἶμος ἐς αὐτάς·” ἡ δὲ παρασιτικὴ μόνη τῶν ἄλλων εὐθὺς ἀπολαύει τῆς τέχνης ἐν αὐτῷ τῷ μανθάνειν, καὶ ἅμα τε ἄρχεται καὶ ἐν τῷ τέλει ἐστίν.", "st": "30.14"}, {"sp": "N", "t": "καὶ μέντοι τῶν ἄλλων τεχνῶν οὐ τινές, ἀλλὰ πᾶσαι ἐπὶ μόνην τὴν τροφὴν γεγόνασιν, ὁ δὲ παράσιτος εὐθὺς ἔχει τὴν τροφὴν ἅμα τῷ ἄρξασθαι τῆς τέχνης. ἢ οὐκ ἐννοεῖς ὅτι ὁ μὲν γεωργὸς γεωργεῖ οὐ τοῦ γεωργεῖν ἕνεκα καὶ ὁ τέκτων τεκταίνεται οὐχὶ τοῦ τεκταίνεσθαι ἕνεκα, ὁ δὲ παράσιτος οὐχ ἕτερον μέν τι διώκει, ἀλλὰ τὸ αὐτὸ καὶ ἔργον μὲν ἐστὶν αὐτοῦ καὶ οὗ ἕνεκα γίγνεται;", "st": "30.14"}, {"sp": "N", "t": "καὶ μὴν ἐκεῖνά γε οὐδείς ἐστιν ὅστις οὐκ ἐπίσταται, ὅτι οἱ μὲν τὰς λοιπὰς τέχνας ἐργαζόμενοι τὸν μὲν ἄλλον χρόνον ταλαιπωροῦσι, μίαν δὲ ἢ δύο μόνας τοῦ μηνὸς ἡμέρας ἱερὰς ἄγουσι, καὶ εὐφραίνεσθαι λέγονται τότε· ὁ δὲ παράσιτος τοῦ μηνὸς τὰς τριάκονθ’ ἡμέρας ἱερὰς ἄγει· πᾶσαι γὰρ αὐτῷ δοκοῦσιν εἶναι τῶν θεῶν.", "st": "30.15"}, {"sp": "N", "t": "ἔτι οἱ μὲν βουλόμενοι τὰς ἄλλας τέχνας κατορθοῦν ὀλιγοσιτίαις καὶ ὀλιγοποσίαις χρῶνται καθάπερ οἱ νοσοῦντες, πολυποσίαις δὲ καὶ πολυσιτίαις οὐκ ἔστιν εὐφραινόμενον μανθάνειν.", "st": "30.16"}, {"sp": "N", "t": "καὶ αἱ μὲν ἄλλαι τέχναι χωρὶς ὀργάνων οὐδαμῶς τῷ κεκτημένῳ ὑπηρετεῖν δύνανται· οὔτε γὰρ αὐλεῖν ἔνι χωρὶς αὐλῶν οὔτε ψάλλειν ἄνευ λύρας οὔτε ἱππεύειν ἄνευ ἵππου· αὕτη δὲ οὕτως ἐστὶν ἀγαθὴ καὶ οὐ βαρεῖα τῷ τεχνίτῃ, ὥστε ὑπάρχει καὶ μηδὲν ἔχοντι ὅπλον χρῆσθαι αὐτῇ.", "st": "30.17"}, {"sp": "N", "t": "καὶ ὡς ἔοικεν ἄλλας τέχνας μανθάνομεν μισθὸν διδόντες, ταύτην δὲ λαμβάνοντες. ἔτι τῶν μὲν ἄλλων τεχνῶν εἰσι διδάσκαλοί τινες,", "st": "30.18"}, {"sp": "N", "t": "τῆς δὲ παρασιτικῆς οὐδείς, ἀλλ’ ὥσπερ ἡ ποιητικὴ κατὰ Σωκράτη καὶ αὕτη τινὶ θείᾳ μοίρᾳ παραγίγνεται.", "st": "30.19"}, {"sp": "N", "t": "κἀκεῖνο δὲ σκόπει, ὅτι τὰς μὲν ἄλλας τέχνας ὁδεύοντες ἢ πλέοντες οὐ δυνάμεθα διαπράττεσθαι, ταύτῃ δέ ἐστι χρῆσθαι καὶ ἐν ὁδῷ καὶ πλέοντι.", "st": "30.20"}, {"sp": "N", "t": "<em>Τυχιάδης.<\/em> πάνυ μὲν οὖν.", "st": "30.21"}, {"sp": "N", "t": "<em>Σίμων.<\/em> καὶ μέντοι, ὦ Τυχιάδη, αἱ μὲν ἄλλαι τέχναι δοκοῦσί μοι ταύτης ἐπιθυμεῖν, αὕτη δὲ οὐδεμιᾶς ἑτέρας.", "st": "30.21"}, {"sp": "N", "t": "<em>Τυχιάδης.<\/em> τί δέ, οὐχ οἱ τὰ ἀλλότρια λαμβάνοντες ἀδικεῖν σοι δοκοῦσι;", "st": "30.21"}, {"sp": "N", "t": "<em>Σίμων.<\/em> πῶς γὰρ οὔ;", "st": "30.21"}, {"sp": "N", "t": "<em>Τυχιάδης.<\/em> πῶς οὖν ὁ παράσιτος τὰ ἀλλότρια λαμβάνων οὐκ ἀδικεῖ μόνος;", "st": "30.21"}, {"sp": "N", "t": "<em>Σίμων.<\/em> οὐκ ἔχω λέγειν. καὶ μὴν τῶν ἄλλων τεχνῶν αἱ ἀρχαὶ φαῦλαί τινες καὶ εὐτελεῖς εἰσι, τῆς δὲ παρασιτικῆς ἀρχὴ πάνυ γενναία τις· τὸ γὰρ θρυλούμενον τοῦτο τῆς φιλίας ὄνομα οὐκ ἂν ἄλλο τι εὕροις ἢ ἀρχὴν παρασιτικῆς.", "st": "30.22"}, {"sp": "N", "t": "<em>Τυχιάδης.<\/em> πῶς λέγεις;", "st": "30.22"}, {"sp": "N", "t": "<em>Σίμων.<\/em> ὅτι οὐδεὶς ἐχθρὸν ἢ ἀγνῶτα ἄνθρωπον ἀλλ’ οὐδὲ συνήθη μετρίως ἐπὶ δεῖπνον καλεῖ, ἀλλὰ δεῖ πρότερον οἶμαι τοῦτον γενέσθαι φίλον, ἵνα κοινωνήσῃ σπονδῶν καὶ τραπέζης καὶ τῶν τῆς τέχνης ταύτης μυστηρίων. ἐγὼ γοῦν πολλάκις ἤκουσά τινων λεγόντων, “ποταπὸς δὲ οὗτος φίλος ὅστις οὔτε βέβρωκεν οὔτε πέπωκεν μεθ’ ἡμῶν,” δῆλον ὅτι τὸν συμπίνοντα καὶ συνεσθίοντα μόνον πιστὸν φίλον ἡγουμένων.", "st": "30.22"}, {"sp": "N", "t": "ὅτι γε μὴν ἡ βασιλικωτάτη τῶν τεχνῶν ἔστιν αὕτη, μάθοις ἂν καὶ ἐκ τοῦδε οὐχ ἥκιστα· τὰς μὲν γὰρ λοιπὰς τέχνας οὐ μόνον κακοπαθοῦντες καὶ ἱδροῦντες, ἀλλὰ νὴ Δία καθήμενοι καὶ ἑστῶτες ἐργάζονται ὥσπερ ἀμέλει δοῦλοι τῶν τεχνῶν, ὁ δὲ παράσιτος μεταχειρίζεται τὴν αὑτοῦ τέχνην ὡς βασιλεὺς κατακείμενος.", "st": "30.23"}, {"sp": "N", "t": "ἐκεῖνα μὲν γὰρ τί δεῖ λέγειν περὶ τῆς εὐδαιμονίας αὐτοῦ, ὅτι δὴ μόνος κατὰ τὸν σοφὸν Ὅμηρον “οὔτε φυτεύει χερσὶ φυτὸν οὔτε ἀροῖ, ἀλλὰ τά γ’ ἄσπαρτα καὶ ἀνήροτα πάντα” νέμεται;", "st": "30.24"}, {"sp": "N", "t": "καὶ μὴν ῥήτορά τε καὶ γεωμέτρην καὶ χαλκέα οὐδὲν κωλύει τὴν ἑαυτοῦ τέχνην ἐργάζεσθαι ἐάν τε πονηρὸς ἐάν τε καὶ μωρὸς ᾖ, παρασιτεῖν δὲ οὐδεὶς δύναται ἢ μωρὸς ὢν ἢ πονηρός.", "st": "30.25"}, {"sp": "N", "t": "<em>Τυχιάδης.<\/em> παπαί, οἷον χρῆμα ἀποφαίνῃ τὴν παρασιτικήν· ὥστε καὶ αὐτὸς ἤδη βούλεσθαι δοκῶ μοι παράσιτος εἶναι ἀντὶ τούτου ὅς εἰμι.", "st": "30.25"}, {"sp": "N", "t": "<em>Σίμων.<\/em> ὡς μὲν τοίνυν κοινῇ πασῶν διαφέρει, δεδεῖχθαί μοι δοκῶ. φέρε δὴ ὡς καὶ κατ’ ἰδίαν ἑκάστης διαφέρει σκοπῶμεν. τὸ μὲν δὴ ταῖς βαναύσοις τέχναις παραβάλλειν αὐτὴν ἀνόητόν ἐστιν, καὶ μᾶλλόν πως καθαιροῦντος τὸ ἀξίωμα τῆς τέχνης. ὅτι γε μὴν τῶν καλλίστων καὶ μεγίστων τεχνῶν διαφέρει δεικτέον. ὡμολόγηται δὴ πρὸς πάντων τήν τε ῥητορικὴν καὶ τὴν φιλοσοφίαν, ἃς διὰ γενναιότητα καὶ ἐπιστήμας ἀποφαίνονταί τινες, … ἐπειδὰν καὶ τούτων ἀποδείξαιμι τὴν παρασιτικὴν πολὺ κρατοῦσαν, δῆλον ὅτι τῶν ἄλλων τεχνῶν δόξει προφερεστάτη καθάπερ ἡ Ναυσικάα τῶν θεραπαινίδων.", "st": "30.26"}, {"sp": "N", "t": "κοινῇ μὲν οὖν ἀμφοῖν διαφέρει καὶ τῆς ῥητορικῆς καὶ τῆς φιλοσοφίας, πρῶτον κατὰ τὴν ὑπόστασιν· ἡ μὲν γὰρ ὑφέστηκεν, αἱ δὲ οὔ. οὔτε γὰρ τὴν ῥητορικὴν ἕν τι καὶ τὸ αὐτὸ νομίζομεν, ἀλλ’ οἱ μὲν τέχνην, οἱ δὲ τοὐναντίον ἀτεχνίαν, ἄλλοι δὲ κακοτεχνίαν, ἄλλοι δὲ ἄλλο τι. ὁμοίως δὲ καὶ τὴν φιλοσοφίαν οὐ κατὰ τὰ αὐτὰ καὶ ὡσαύτως ἔχουσαν, ἑτέρως μὲν γὰρ Ἐπικούρῳ δοκεῖ τὰ πράγματα ἔχειν, ἑτέρως δὲ τοῖς ἀπὸ τῆς Στοᾶς, ἑτέρως δὲ τοῖς ἀπὸ τῆς Ἀκαδημίας, ἑτέρως δὲ τοῖς ἀπὸ τοῦ Περιπάτου, καὶ ἁπλῶς ἄλλος ἄλλην ἀξιοῖ τὴν φιλοσοφίαν εἶναι· καὶ μέχρι γε νῦν οὔτε οἱ αὐτοὶ γνώμης κρατοῦσιν οὔτε αὐτῶν ἡ τέχνη μία φαίνεται. ἐξ ὧν δῆλον ὅ τι τεκμαίρεσθαι καταλείπεται. ἀρχὴν γάρ φημι μηδὲ εἶναι τέχνην ἧς οὐκ ἔστιν ὑπόστασις. ἐπεὶ τί δή ποτε ἀριθμητικὴ μὲν μία ἐστὶ καὶ ἡ αὐτὴ καὶ δὶς δύο παρά τε ἡμῖν καὶ παρὰ Πέρσαις τέσσαρά ἐστιν καὶ συμφωνεῖ ταῦτα καὶ παρὰ Ἕλλησι καὶ βαρβάροις, φιλοσοφίας δὲ πολλὰς καὶ διαφόρους ὁρῶμεν καὶ οὔτε τὰς ἀρχὰς οὔτε τὰ τέλη σύμφωνα πασῶν;", "st": "30.27"}, {"sp": "N", "t": "<em>Τυχιάδης.<\/em> ἀληθῆ λέγεις· μίαν μὲν γὰρ τὴν φιλοσοφίαν εἶναι λέγουσιν, αὐτοὶ δὲ αὐτὴν ποιοῦσι πολλάς.", "st": "30.27"}, {"sp": "N", "t": "<em>Σίμων.<\/em> καὶ μὴν καὶ τὰς μὲν ἄλλας τέχνας, εἰ καί τι κατὰ ταύτας ἀσύμφωνον εἴη, κἂν παρέλθοι τις συγγνώμης ἀξιώσας, ἐπεὶ μέσαι τε δοκοῦσι καὶ αἱ καταλήψεις αὐτῶν οὐκ εἰσὶν ἀμετάπτωτοι. φιλοσοφίαν δὲ τίς ἂν καὶ ἀνάσχοιτο μὴ μίαν εἶναι καὶ μηδὲ σύμφωνον αὐτὴν ἑαυτῇ μᾶλλον τῶν ὀργάνων; μία μὲν οὖν οὐκ ἔστι φιλοσοφία, ἐπειδὴ ὁρῶ καὶ ἄπειρον οὖσαν· πολλαὶ δὲ οὐ δύνανται εἶναι, ἐπειδήπερ ἡ σοφία μία.", "st": "30.28"}, {"sp": "N", "t": "ὁμοίως δὲ καὶ περὶ τῆς ὑποστάσεως τῆς ῥητορικῆς ταὐτὰ φαίη τις ἄν· τὸ γὰρ περὶ ἑνὸς προκειμένου ταὐτὰ μὴ λέγειν ἅπαντας, ἀλλὰ μάχην εἶναι φορᾶς ἀντιδόξου, ἀπόδειξις μεγίστη τοῦ μηδὲ ἀρχὴν εἶναι τοῦτο οὗ μία κατάληψις οὐκ ἔστιν· τὸ γὰρ ζητεῖν τό, τί μᾶλλον αὐτό ἐστιν, καὶ τὸ μηδέποτε ὁμολογεῖν ἓν εἶναι, τοῦτο αὐτὴν ἀναιρεῖ τοῦ ζητουμένου τὴν οὐσίαν.", "st": "30.29"}, {"sp": "N", "t": "ἡ μέντοι παρασιτικὴ οὐχ οὕτως ἔχει, ἀλλὰ καὶ ἐν Ἕλλησι καὶ βαρβάροις μία ἐστὶν καὶ κατὰ ταὐτὰ καὶ ὡσαύτως, καὶ οὐκ ἂν εἴποι τις ἄλλως μὲν τούσδε, ἑτέρως δὲ τούσδε παρασιτεῖν, οὐδέ εἰσιν ὡς ἔοικεν ἐν παρασίτοις τινες οἷον Στωϊκοὶ ἢ Ἐπικούρειοι δόγματα ἔχοντες διάφορα, ἀλλὰ πᾶσι πρὸς ἅπαντας ὁμολογία τίς ἐστιν καὶ συμφωνία τῶν ἔργων καὶ τοῦ τέλους. ὥστε ἔμοιγε δοκεῖ ἡ παρασιτικὴ κινδυνεύειν κατά γε τοῦτο καὶ σοφία εἶναι.", "st": "30.30"}, {"sp": "N", "t": "<em>Τυχιάδης.<\/em> πάνυ μοι δοκεῖς ἱκανῶς ταῦτα εἰρηκέναι. ὡς δὲ καὶ τὰ ἄλλα χείρων ἐστὶν ἡ φιλοσοφία τῆς σῆς τέχνης, πῶς ἀποδεικνύεις;", "st": "30.31"}, {"sp": "N", "t": "<em>Σίμων.<\/em> οὐκοῦν ἀνάγκη πρῶτον εἰπεῖν ὅτι φιλοσοφίας μὲν οὐδέποτε ἠράσθη παράσιτος, παρασιτικῆς δὲ πάμπολλοι ἐπιθυμήσαντες μνημονεύονται φιλόσοφοι, καὶ μέχρι γε νῦν ἐρῶσιν.", "st": "30.31"}, {"sp": "N", "t": "<em>Τυχιάδης.<\/em> καὶ τίνας ἂν ἔχοις εἰπεῖν φιλοσόφους παρασιτεῖν σπουδάσαντας;", "st": "30.31"}, {"sp": "N", "t": "<em>Σίμων.<\/em> οὕστινας μέντοι, ὦ Τυχιάδη; οὓς καὶ σὺ γιγνώσκων ὑποκρίνῃ ἀγνοεῖν κἀμὲ κατασοφίζῃ ὥς τινος αὐτοῖς αἰσχύνης ἐντεῦθεν γιγνομένης, οὐχὶ τιμῆς.", "st": "30.31"}, {"sp": "N", "t": "<em>Τυχιάδης.<\/em> οὐ μὰ τὸν Δία, ὦ Σίμων, ἀλλὰ καὶ σφόδρα ἀπορῶ οὕστινας καὶ εὕροις εἰπεῖν.", "st": "30.31"}, {"sp": "N", "t": "<em>Σίμων.<\/em> ὦ γενναῖε, σύ μοι δοκεῖς ἀνήκοος εἶναι καὶ τῶν ἀναγραψάντων τοὺς ἐκείνων βίους, ἐπεὶ πάντως ἂν καὶ ἐπιγνῶναι οὕστινας λέγω δύναιο.", "st": "30.31"}, {"sp": "N", "t": "<em>Τυχιάδης.<\/em> καὶ μέντοι νὴ τὸν Ἡρακλέα ποθῶ δὴ ἀκούειν τίνες εἰσίν.", "st": "30.31"}, {"sp": "N", "t": "<em>Σίμων.<\/em> ἐγώ σοι καταλέξω αὐτοὺς ὄντας οὐχὶ τοὺς φαύλους, ἀλλ’ ὡς ἐγὼ δοκῶ, τοὺς ἀρίστους καὶ οὓς ἥκιστα σὺ οἴει. Αἰσχίνης μέντοι ὁ Σωκρατικός, οὗτος ὁ τοὺς μακροὺς καὶ ἀστείους διαλόγους γράψας, ἧκέν ποτε εἰς Σικελίαν κομίζων αὐτούς, εἴ πως δύναιτο δι’ αὐτῶν γνωσθῆναι Διονυσίῳ τῷ τυράννῳ, καὶ τὸν Μιλτιάδην ἀναγνοὺς καὶ δόξας εὐδοκιμηκέναι λοιπὸν ἐκάθητο ἐν Σικελίᾳ παρασιτῶν Διονυσίῳ καὶ ταῖς Σωκράτους διατριβαῖς ἐρρῶσθαι φράσας.", "st": "30.32"}, {"sp": "N", "t": "τί δέ, καὶ Ἀρίστιππος ὁ Κυρηναῖος οὐχὶ τῶν δοκίμων φαίνεταί σοι φιλοσόφων;", "st": "30.33"}, {"sp": "N", "t": "<em>Τυχιάδης.<\/em> καὶ πάνυ.", "st": "30.33"}, {"sp": "N", "t": "<em>Σίμων.<\/em> καὶ οὗτος μέντοι κατὰ τὸν αὐτὸν χρόνον διέτριβεν ἐν Συρακούσαις παρασιτῶν Διονυσίῳ. πάντων γοῦν ἀμέλει τῶν παρασίτων αὐτὸς ηὐδοκίμει παρ’ αὐτῷ· καὶ γὰρ ἦν πλέον τι τῶν ἄλλων πρὸς τὴν τέχνην εὐφυής, ὥστε τοὺς ὀψοποιοὺς ὁσημέραι ἔπεμπεν παρὰ τοῦτον ὁ Διονύσιος ὥς τι παρ’ αὐτοῦ μαθησομένους.", "st": "30.33"}, {"sp": "N", "t": "οὗτος μέντοι δοκεῖ καὶ κοσμῆσαι τὴν τέχνην ἀξίως.", "st": "30.33"}, {"sp": "N", "t": "ὁ δὲ Πλάτων ὑμῶν ὁ γενναιότατος καὶ αὐτὸς μὲν ἧκεν εἰς Σικελίαν ἐπὶ τούτῳ, καὶ ὀλίγας παρασιτήσας ἡμέρας τῷ τυράννῳ τοῦ παρασιτεῖν ὑπὸ ἀφυίας ἐξέπεσε, καὶ πάλιν Ἀθήναζε ἀφικόμενος καὶ φιλοπονῄσας καὶ παρασκευάσας ἑαυτὸν αὖθις δευτέρῳ στόλῳ ἐπέπλευσε τῇ Σικελίᾳ καὶ δειπνήσας πάλιν ὀλίγας ἡμέρας ὑπὸ ἀμαθίας ἐξέπεσε· καὶ αὕτη ἡ συμφορὰ Πλάτωνι περὶ Σικελίαν ὁμοία δοκεῖ γενέσθαι τῇ Νικίου.", "st": "30.34"}, {"sp": "N", "t": "<em>Τυχιάδης.<\/em> καὶ τίς, ὦ Σίμων, περὶ τούτου λέγει;", "st": "30.34"}, {"sp": "N", "t": "<em>Σίμων.<\/em> πολλοὶ μὲν καὶ ἄλλοι, Ἀριστόξενος δὲ ὁ μουσικός, πολλοῦ λόγου ἄξιος.", "st": "30.35"}, {"sp": "N", "t": "Εὐριπίδης μὲν γὰρ ὅτι Ἀρχελάῳ μέχρι μὲν τοῦ θανάτου παρεσίτει καὶ Ἀνάξαρχος Ἀλεξάνδρῳ πάντως ἐπίστασαι.", "st": "30.35"}, {"sp": "N", "t": "καὶ Ἀριστοτέλης δὲ τῆς παρασιτικῆς ἤρξατο μόνον ὥσπερ καὶ τῶν ἄλλων τεχνῶν.", "st": "30.36"}, {"sp": "N", "t": "φιλοσόφους μὲν οὖν, ὥσπερ ἦν, παρασιτεῖν σπουδάσαντας ἔδειξα· παράσιτον δὲ οὐδεὶς ἔχει φράσαι φιλοσοφεῖν ἐθελήσαντα.", "st": "30.37"}, {"sp": "N", "t": "καὶ μέντοι εἰ ἔστιν εὔδαιμον τὸ μὴ πεινῆν μηδὲ διψῆν μηδὲ ῥιγοῦν, ταῦτα οὐδενὶ ἄλλῳ ὑπάρχει ἢ παρασίτῳ. ὥστε φιλοσόφους μὲν ἄν τις πολλοὺς καὶ ῥιγοῦντας καὶ πεινῶντας εὕροι, παράσιτον δὲ οὔ· ἢ οὐκ ἂν εἴη παράσιτος, ἀλλὰ δυστυχής τις καὶ πτωχὸς ἄνθρωπος καὶ φιλοσόφῳ ὅμοιος.", "st": "30.38"}, {"sp": "N", "t": "<em>Τυχιάδης.<\/em> ἱκανῶς ταῦτά γε. ὅτι δὲ κατὰ τἄλλα διαφέρει φιλοσοφίας καὶ ῥητορικῆς ἡ παρασιτικὴ πῶς ἐπιδεικνύεις;", "st": "30.39"}, {"sp": "N", "t": "<em>Σίμων.<\/em> εἰσίν, ὦ βέλτιστε, καιροὶ τοῦ τῶν ἀνθρώπων βίου, ὁ μέν τις εἰρήνης, οἶμαι, ὁ δ’ αὖ πολέμου. ἐν δὴ τούτοις πᾶσα ἀνάγκη φανερὰς γίγνεσθαι τὰς τέχνας καὶ τοὺς ἔχοντας ταύτας ὁποῖοί τινές εἰσιν. πρότερον δέ, εἰ δοκεῖ, σκοπώμεθα τὸν τοῦ πολέμου καιρόν, καὶ τίνες ἂν εἶεν μάλιστα χρησιμώτατοι ἰδίᾳ τε ἕκαστος αὐτῷ καὶ κοινῇ τῇ πόλει.", "st": "30.39"}, {"sp": "N", "t": "<em>Τυχιάδης.<\/em> ὡς οὐ μέτριον ἀγῶνα καταγγέλλεις τῶν ἀνδρῶν· καὶ ἔγωγε πάλαι γελῶ κατ’ ἐμαυτὸν ἐννοῶν ποῖος ἂν εἴη συμβαλλόμενος παρασίτῳ φιλόσοφος.", "st": "30.39"}, {"sp": "N", "t": "<em>Σίμων.<\/em> ἵνα τοίνυν μὴ πάνυ θαυμάζῃς μηδὲ τὸ πρᾶγμά σοι δοκῇ χλεύης ἄξιον, φέρε προτυπωσώμεθα παρ’ ἡμῖν αὐτοῖς ἠγγέλθαι μὲν αἰφνίδιον εἰς τὴν χώραν ἐμβεβληκέναι πολεμίους, εἶναι δὲ ἀνάγκην ἐπεξιέναι καὶ μὴ περιορᾶν ἔξω δῃουμένην τὴν γῆν, τὸν στρατηγὸν δὲ παραγγέλλειν ἅπαντας εἰς τὸν κατάλογον τοὺς ἐν ἡλικίᾳ, καὶ δὴ χωρεῖν τοὺς ἄλλους, ἐν δὲ δὴ τούτοις φιλοσόφους τινὰς καὶ ῥήτορας καὶ παρασίτους. πρῶτον τοίνυν ἀποδύσωμεν αὐτούς· ἀνάγκη γὰρ τοὺς μέλλοντας ὁπλίζεσθαι γυμνοῦσθαι πρότερον. θεῶ δὴ τοὺς ἄνδρας, ὦ γενναῖε, καθ’ ἕκαστον καὶ δοκίμαζε τὰ σώματα. τοὺς μὲν τοίνυν αὐτῶν ὑπὸ ἐνδείας ἴδοις ἂν λεπτοὺς καὶ ὠχρούς, πεφρικότας, ὥσπερ ἤδη τραυματίας παρειμένους· ἀγῶνα μὲν γὰρ καὶ μάχην σταδιαίαν καὶ ὠθισμὸν καὶ κόνιν καὶ τραύματα μὴ γελοῖον ᾖ λέγειν δύνασθαι φέρειν ἀνθρώπους ὥσπερ ἐκείνους τινὸς δεομένους ἀναλήψεως.", "st": "30.40"}, {"sp": "N", "t": "ἄθρει δὲ πάλιν μεταβὰς τὸν παράσιτον ὁποῖός τις φαίνεται. ἆρ’ οὐχ ὁ μὲν τὸ σῶμα πρῶτον πολὺς καὶ τὸ χρῶμα ἡδύς, οὐ μέλας δὲ οὐδὲ λευκός — τὸ μὲν γὰρ γυναικί, τὸ δὲ δούλῳ προσέοικεν — ἔπειτα θυμοειδής, δεινὸν βλέπων ὁποῖον ἡμεῖς, μέγα καὶ ὕφαιμον; οὐ γὰρ καλὸν δεδοικότα καὶ θῆλυν ὀφθαλμὸν εἰς πόλεμον φέρειν. ἆρ’ οὐχ ὁ τοιοῦτος καλὸς μὲν γένοιτ’ ἂν καὶ ζῶν ὁπλίτης, καλὸς δὲ καὶ εἰ ἀποθάνοι νεκρός;", "st": "30.41"}, {"sp": "N", "t": "ἀλλὰ τί δεῖ ταῦτα εἰκάζειν ἔχοντας αὐτῶν παραδείγματα; ἁπλῶς γὰρ εἰπεῖν, ἐν πολέμῳ τῶν πώποτε ῥητόρων ἢ φιλοσόφων οἱ μὲν οὐδὲ ὅλως ὑπέμειναν ἔξω τοῦ τείχους προελθεῖν, εἰ δέ τις καὶ ἀναγκασθεὶς παρετάξατο, φημὶ τοῦτον λείψαντα τὴν τάξιν ὑποστρέφειν.", "st": "30.42"}, {"sp": "N", "t": "<em>Τυχιάδης.<\/em> ὡς θαυμάσια πάντα καὶ οὐδὲν ὑπισχνῇ μέτριον. λέγε δὲ ὅμως.", "st": "30.42"}, {"sp": "N", "t": "<em>Σίμων.<\/em> τῶν μὲν τοίνυν ῥητόρων Ἰσοκράτης οὐχ ὅπως εἰς πόλεμον ἐξῆλθέν ποτε, ἀλλ’ οὐδ’ ἐπὶ δικαστήριον ἀνέβη, διὰ δειλίαν, οἶμαι, ὅτι οὐδὲ τὴν φωνὴν διὰ τοῦτο εἶχεν ἔτι. τί δ’; οὐχὶ Δημάδης μὲν καὶ Αἰσχίνης καὶ Φιλοκράτης ὑπὸ δέους εὐθὺς τῇ καταγγελίᾳ τοῦ Φιλίππου πολέμου τὴν πόλιν προὔδοσαν καὶ σφᾶς αὐτοὺς τῷ Φιλίππῳ καὶ διετέλεσαν Ἀθήνησιν ἀεὶ τὰ ἐκείνου πολιτευόμενοι, ὃς εἴ γε καὶ ἄλλος τις Ἀθηναίοις κατὰ ταῦτα ἐπολέμει· κἀκεῖνος ἐν αὐτοῖς ἦν φίλος. Ὑπερίδης δὲ καὶ Δημοσθένης καὶ Λυκοῦργος, οἵ γε δοκοῦντες ἀνδρειότεροι κἀν ταῖς ἐκκλησίαις ἀεὶ θορυβοῦντες καὶ λοιδορούμενοι τῷ Φιλίππῳ, τί ποτε ἀπειργάσαντο γενναῖον ἐν τῷ πρὸς αὐτὸν πολέμῳ; καὶ Ὑπερίδης μὲν καὶ Λυκοῦργος οὐδὲ ἐξῆλθον, ἀλλ’ οὐδὲ ὅλως ἐτόλμησαν μικρὸν ἔξω παρακῦψαι τῶν πυλῶν, ἀλλ’ ἐντειχίδιοι ἐκάθηντο παρ’ αὐτοῖς ἤδη πολιορκούμενοι γνωμίδια καὶ προβουλευμάτια συντιθέντες. ὁ δὲ δὴ κορυφαιότατος αὐτῶν, ὁ ταυτὶ λέγων ἐν ταῖς ἐκκλησίαις συνεχῶς· “Φίλιππος γὰρ ὁ Μακεδὼν ὄλεθρος, ὅθεν οὐδὲ ἀνδράποδον πρίαιτό τίς ποτε,” τολμήσας προελθεῖν εἰς τὴν Βοιωτίαν, πρὶν ἢ συμμῖξαι τὰ στρατόπεδα καὶ συμβαλεῖν εἰς χεῖρας ῥίψας τὴν ἀσπίδα ἔφυγεν. ἢ οὐδέπω ταῦτα πρότερον διήκουσας οὐδενός, πάνυ γνώριμα ὄντα οὐχ ὅπως Ἀθηναίοις, ἀλλὰ Θρᾳξὶ καὶ Σκύθαις, ὅθεν ἐκεῖνο τὸ κάθαρμα ἦν;", "st": "30.42"}, {"sp": "N", "t": "<em>Τυχιάδης.<\/em> ἐπίσταμαι ταῦτα· ἀλλ’ οὗτοι μὲν ῥήτορες καὶ λόγους λέγειν ἠσκηκότες, ἀρετὴν δὲ οὔ. τί δὲ περὶ τῶν φιλοσόφων λέγεις; οὐ γὰρ δὴ τούτους ἔχεις ὥσπερ ἐκείνους αἰτιᾶσθαι.", "st": "30.43"}, {"sp": "N", "t": "<em>Σίμων.<\/em> οὗτοι πάλιν, ὦ Τυχιάδη, οἱ περὶ τῆς ἀνδρείας ὁσημέραι διαλεγόμενοι καὶ κατατρίβοντες τὸ τῆς ἀρετῆς ὄνομα πολλῷ μᾶλλον τῶν ῥητόρων φανοῦνται δειλότεροι καὶ μαλακώτεροι. σκόπει δὴ οὕτως. πρῶτον μὲν οὐκ ἔστιν ὅστις εἰπεῖν ἔχοι φιλόσοφον ἐν πολέμῳ τετελευτηκότα· ἤτοι γὰρ οὐδὲ ὅλως ἐστρατεύσαντο, ἢ εἴπερ ἐστρατεύσαντο, πάντες ἔφυγον. Ἀντισθένης μὲν οὖν καὶ Διογένης καὶ Κράτης καὶ Ζήνων καὶ Πλάτων καὶ Αἰσχίνης καὶ Ἀριστοτέλης καὶ πᾶς οὗτος ὁ ὅμιλος οὐδὲ εἶδον παράταξιν· μόνος δὲ τολμήσας ἐξελθεῖν εἰς τὴν ἐπὶ Δηλίῳ μάχην ὁ σοφὸς αὐτῶν Σωκράτης φεύγων ἐκεῖθεν ἀπὸ τῆς Πάρνηθος εἰς τὴν Ταυρέου παλαίστραν κατέφυγεν. πολὺ γὰρ αὐτῷ ἀστειότερον ἐδόκει μετὰ τῶν μειρακυλλίων καθεζόμενον ὀαρίζειν καὶ σοφισμάτια προβάλλειν τοῖς ἐντυγχάνουσιν ἢ ἀνδρὶ Σπαρτιάτῃ μάχεσθαι.", "st": "30.43"}, {"sp": "N", "t": "<em>Τυχιάδης.<\/em> ὦ γενναῖε, ταῦτα μὲν ἤδη καὶ παρ’ ἄλλων ἐπυθόμην, οὐ μὰ Δία σκώπτειν αὐτοὺς καὶ ὀνειδίζειν βουλομένων· ὥστε οὐδέν τί μοι δοκεῖς χαριζόμενος τῇ σεαυτοῦ τέχνῃ καταψεύδεσθαι τῶν ἀνδρῶν.", "st": "30.43"}, {"sp": "N", "t": "ἀλλ’ εἰ δοκεῖ ἤδη, φέρε καὶ σὺ τὸν παράσιτον ὁποῖός τίς ἐστιν ἐν πολέμῳ λέγε, καὶ εἰ καθόλως λέγεται παράσιτός τις γενέσθαι τῶν παλαιῶν;", "st": "30.44"}, {"sp": "N", "t": "<em>Σίμων.<\/em> καὶ μήν, ὦ φιλότης, οὐδεὶς οὕτως ἀνήκοος Ὁμήρου, οὐδ’ ἂν πάμπαν ἰδιώτης τύχῃ, ὃς οὐκ ἐπίσταται παρ’ αὐτῷ τοὺς ἀρίστους τῶν ἡρώων παρασίτους ὄντας. ὅ τε γὰρ Νέστωρ ἐκεῖνος, οὗ ἀπὸ τῆς γλώττης ὥσπερ μέλι ὁ λόγος ἀπέρρει, αὐτοῦ τοῦ βασιλέως παράσιτος ἦν, καὶ οὔτε τὸν Ἀχιλλέα, ὅσπερ ἐδόκει τε καὶ ἦν τὸ σῶμα γενναιότατος, οὔτε τὸν Διομήδην οὔτε τὸν Αἴαντα ὁ Ἀγαμέμνων οὕτως ἐπαινεῖ τε καὶ θαυμάζει ὥσπερ τὸν Νέστορα. οὐδὲ γὰρ δέκα Αἴαντας εὔχεται γενέσθαι αὑτῷ οὔτε δέκα Ἀχιλλέας· πάλαι δ’ ἂν ἑαλωκέναι τὴν Τροίαν, εἰ τοιούτους ὁποῖος ἦν οὗτος ὁ παράσιτος, καίπερ γέρων ὤν, στρατιώτας εἶχεν δέκα. καὶ τὸν Ἰδομενέα τὸν τοῦ Διὸς ἔγγονον παράσιτον Ἀγαμέμνονος ὁμοίως λέγει.", "st": "30.44"}, {"sp": "N", "t": "<em>Τυχιάδης.<\/em> ταῦτα μὲν καὶ αὐτὸς ἐπίσταμαι· οὔπω γε μὴν δοκῶ μοι γιγνώσκειν, πῶς δὴ τὼ ἄνδρε τῷ Ἀγαμέμνονι παράσιτοι ἦσαν.", "st": "30.45"}, {"sp": "N", "t": "<em>Σίμων.<\/em> ἀναμνήσθητι, ὦ γενναῖε, τῶν ἐπῶν ἐκείνων ὧνπερ αὐτὸς ὁ Ἀγαμέμνων πρὸς τὸν Ἰδομενέα λέγει.", "st": "30.45"}, {"sp": "N", "t": "<em>Τυχιάδης.<\/em> ποίων;", "st": "30.45"}, {"sp": "N", "t": "<em>Σίμων.<\/em> σὸν δὲ πλεῖον δέπας αἰεὶ<br>ἕστηχ’ ὥσπερ ἐμοὶ πιέειν ὅτε θυμὸς ἀνώγοι.<br>ἐνταῦθα γὰρ τὸ αἰεὶ πλεῖον δέπας εἴρηκεν οὐχ ὅτι τὸ ποτήριον διὰ παντὸς πλῆρες ἑστήκει τῷ Ἰδομενεῖ καὶ μαχομένῳ καὶ καθεύδοντι, ἀλλ’ ὅτι αὐτῷ δι’ ὅλου τοῦ βίου μόνῳ συνδειπνεῖν ὑπῆρχεν τῷ βασιλεῖ, οὐχ ὥσπερ τοῖς λοιποῖς στρατιώταις πρὸς ἡμέρας τινὰς καλουμένοις.", "st": "30.45"}, {"sp": "N", "t": "τὸν μὲν γὰρ Αἴαντα, ἐπεὶ καλῶς ἐμονομάχησεν τῷ Ἕκτορι, “εἰς Ἀγαμέμνονα δῖον ἄγον,” φησίν, κατὰ τιμὴν ἀξιωθέντα ὀψὲ τοῦ παρὰ τῷ βασιλεῖ δείπνου. ὁ δὲ Ἰδομενεὺς καὶ ὁ Νέστωρ ὁσημέραι συνεδείπνουν τῷ βασιλεῖ, ὡς αὐτός φησιν. Νέστωρ δὲ παράσιτός μοι δοκεῖ τῶν βασιλέων μάλιστα τεχνίτης καὶ ἀγαθὸς γενέσθαι· οὐ γὰρ ἐπὶ τοῦ Ἀγαμέμνονος ἄρξασθαι τῆς τέχνης, ἀλλὰ ἄνωθεν ἐπὶ Καινέως καὶ Ἐξαδίου· δοκεῖ δὲ οὐδὲ ἂν παύσασθαι παρασιτῶν, εἰ μὴ ὁ Ἀγαμέμνων ἀπέθανεν.", "st": "30.45"}, {"sp": "N", "t": "<em>Τυχιάδης.<\/em> οὑτοσὶ μὲν γενναῖος ὁ παράσιτος. εἰ δὲ καὶ ἄλλους τινὰς οἶσθα, πειρῶ λέγειν.", "st": "30.45"}, {"sp": "N", "t": "<em>Σίμων.<\/em> τί οὖν, ὦ Τυχιάδη, οὐχὶ καὶ Πάτροκλος τοῦ Ἀχιλλέως παράσιτος ἦν, καὶ ταῦτα οὐδενὸς τῶν ἄλλων Ἑλλήνων φαυλότερος οὔτε τὴν ψυχὴν οὔτε τὸ σῶμα νεανίας ὤν; ἐγὼ γὰρ οὐδ’ αὐτοῦ μοι δοκῶ τοῦ Ἀχιλλέως τεκμαίρεσθαι τοῖς ἔργοις αὐτοῦ χείρω εἶναι· τόν τε γὰρ Ἕκτορα ῥήξαντα τὰς πύλας καὶ παρὰ ταῖς ναυσὶν εἴσω μαχόμενον οὗτος ἐξέωσεν καὶ τὴν Πρωτεσιλάου ναῦν ἤδη καιομένην ἔσβεσεν, καίτοι ἐπεβάτευον αὐτῆς οὐχ οἱ φαυλότατοι, ἀλλ’ οἱ τοῦ Τελαμῶνος Αἴας τε καὶ Τεῦκρος, ὁ μὲν ὁπλίτης ἀγαθός, ὁ δὲ τοξότης. καὶ πολλοὺς μὲν ἀπέκτεινε τῶν βαρβάρων, ἐν δὲ δὴ τούτοις καὶ Σαρπηδόνα τὸν παῖδα τοῦ Διός, ὁ παράσιτος τοῦ Ἀχιλλέως. καὶ ἀπέθανεν δὲ οὐχὶ τοῖς ἄλλοις ὁμοίως, ἀλλὰ τὸν μὲν Ἕκτορα Ἀχιλλεὺς ἀπέκτεινεν, εἷς ἕνα, καὶ αὐτὸν τὸν Ἀχιλλέα Πάρις, τὸν δὲ παράσιτον θεὸς καὶ δύο ἄνθρωποι. καὶ τελευτῶν δὲ φωνὰς ἀφῆκεν οὐχ οἵαςὁ γενναιότατος Ἕκτωρ καὶ προσπίπτων τὸν Ἀχιλλέα καὶ ἱκετεύων ὅπωςὁ νεκρὸς αὐτοῦ τοῖς οἰκείοις ἀποδοθῇ, ἀλλ’ οἵας εἰκὸς ἀφεῖναι παράσιτον. τίνας δὴ ταύτας; τοιοῦτοι δ’ εἴπερ μοι ἐείκοσιν ἀντεβόλησαν, πάντες κ’ αὐτόθ’ ὄλοντο ἐμῷ ὑπὸ δουρὶ δαμέντες.", "st": "30.46"}, {"sp": "N", "t": "<em>Τυχιάδης.<\/em> ταῦτα μὲν ἱκανῶς· ὅτι δὲ μὴ φίλος ἀλλὰ παράσιτος ἦν ὁ Πάτροκλος τοῦ Ἀχιλλέως πειρῶ λέγειν.", "st": "30.47"}, {"sp": "N", "t": "<em>Σίμων.<\/em> αὐτόν, ὦ Τυχιάδη, τὸν Πάτροκλον ὅτι παράσιτος ἦν λέγοντά σοι παρέξομαι.", "st": "30.47"}, {"sp": "N", "t": "<em>Τυχιάδης.<\/em> θαυμαστὰ λέγεις.", "st": "30.47"}, {"sp": "N", "t": "<em>Σίμων.<\/em> ἄκουε τοίνυν αὐτῶν τῶν ἐπῶν·<br>μὴ ἐμὰ σῶν ἀπάνευθε τιθήμεναι ὀστέ’, Ἀχιλλεῦ,<br>ἀλλ’ ὁμοῦ, ὡς ἐτράφην περ ἐν ὑμετέροισι δόμοισι.<br>καὶ πάλιν ὑποβάς, “καὶ νῦν με δεξάμενος,” φησίν, “ὁ Πηλεὺς<br>ἔτρεφεν ἐνδυκέως καὶ σὸν θεράποντ’ ὀνόμηνε.”<br>τουτέστι παράσιτον εἶχεν. εἰ μὲν τοίνυν φίλον ἐβούλετο τὸν Πάτροκλον λέγειν, οὐκ ἂν αὐτὸν ὠνόμαζεν θεράποντα· ἐλεύθερος γὰρ ἦν ὁ Πάτροκλος. τίνας τοίνυν λέγει τοὺς θεράποντα· εἰ μήτε τοὺς δούλους μήτε τοὺς φίλους; τοὺς παρασίτους δῆλον ὅτι· ᾗ καὶ τὸν Μηριόνην τοῦ Ἰδομενέως καὶ αὐτὸν θεράποντα ὀνομάζει.", "st": "30.47"}, {"sp": "N", "t": "Σκόπει δὲ ὅτι καὶ ἐνταῦθα τὸν μὲν Ἰδομενέα Διὸς ὄντα υἱὸν οὐκ ἀξιοῖ λέγειν “ἀτάλαντον Ἄρηϊ,” Μηριόνην δὲ τὸν παράσιτον αὐτοῦ.", "st": "30.47"}, {"sp": "N", "t": "τί δέ; οὐχὶ καὶ Ἀριστογείτων, δημοτικὸς ὢν καὶ πένης, ὥσπερ Θουκυδίδης φησί, παράσιτος ἦν Ἁρμοδίου; τί δέ; οὐχὶ καὶ ἐραστής; ἐπιεικῶς γὰρ οἱ παράσιτοι καὶ ἐρασταὶ τῶν τρεφόντων εἰσίν. οὗτος τοίνυν πάλιν ὁ παράσιτος τὴν Ἀθηναίων πόλιν τυραννουμένην εἰς ἐλευθερίαν ἀφείλετο, καὶ νῦν ἕστηκε χαλκοῦς ἐν τῇ ἀγορᾷ μετὰ τῶν παιδικῶν.", "st": "30.48"}, {"sp": "N", "t": "οὗτοι μὲν δή, τοιοίδε ὄντες, μάλα ἀγαθοὶ παράσιτοι ἦσαν.", "st": "30.48"}, {"sp": "N", "t": "σὺ δὲ δὴ ποῖόν τινα εἰκάζεις ἐν πολέμῳ τὸν παράσιτον; οὐχὶ πρῶτον μὲν ὁ τοιοῦτος ἀριστοποιησάμενος ἔξεισιν ἐπὶ τὴν παράταξιν, καθάπερ καὶ ὁ Ὀδυσσεὺς ἀξιοῖ; οὐ γὰρ ἄλλως ἐν πολέμῳ μάχεσθαι, φησίν, ἔστιν, εἰ καὶ εὐθὺς ἅμα ἕῳ μάχεσθαι δέοι. καὶ ὃν ἄλλοι στρατιῶται χρόνον ὑπὸ δέους ὁ μέν τις ἀκριβῶς ἁρμόζει τὸ κράνος, ὁ δὲ θωράκιον ἐνδύεται, ὁ δὲ αὐτὸ τὸ δεινὸν ὑποπτεύων τοῦ πολέμου τρέμει, οὗτος δὲ ἐσθίει τότε μάλα φαιδρῷ τῷ προσώπῳ καὶ μετὰ τὴν ἔξοδον εὐθὺς ἐν πρώτοις διαγωνίζεται· ὁ δὲ τρέφων αὐτὸν ὄπισθεν ὑποτέτακται τῷ παρασίτῳ, κἀκεῖνος αὐτὸν ὥσπερ ὁ Αἴας τὸν Τεῦκρον ὑπὸ τῷ σάκει καλύπτει, καὶ τῶν βελῶν ἀφιεμένων γυμνώσας ἑαυτὸν τοῦτον σκέπει· βούλεται γὰρ ἐκεῖνον μᾶλλον σώζειν ἢ ἑαυτόν.", "st": "30.49"}, {"sp": "N", "t": "εἰ δὲ δὴ καὶ πέσοι παράσιτος ἐν πολέμῳ, οὐκ ἂν ἐπ’ αὐτῷ δήπου οὔτε λοχαγὸς οὔτε στρατιώτης αἰσχυνθείη μεγάλῳ τε ὄντι νεκρῷ καὶ ὥσπερ ἐν συμποσίῳ καλῷ καλῶς κατακειμένῳ. ὡς ἄξιόν γε φιλοσόφου νεκρὸν ἰδεῖν τούτῳ παρακείμενον, ξηρόν, ῥυπῶντα, μακρὸν πωγώνιον ἔχοντα, προτεθνηκότα τῆς μάχης, ἀσθενῆ ἄνθρωπον. τίς οὐκ ἂν καταφρονήσειε ταύτης τῆς πόλεως τοὺς ὑπασπιστὰς αὐτῆς οὕτως κακοδαίμονας ὁρῶν; τίς δὲ οὐκ ἂν εἰκάσαι, χλωροὺς καὶ κομήτας ὁρῶν ἀνθρωπίσκους κειμένους, τὴν πόλιν ἀποροῦσαν συμμάχων τοὺς ἐν τῇ εἱρκτῇ κακούργους ἐπιλῦσαι τῷ πολέμῳ;", "st": "30.50"}, {"sp": "N", "t": "τοιοῦτοι μὲν ἐν πολέμῳ πρὸς ῥήτορας καὶ φιλοσόφους εἰσὶν οἱ παράσιτοι.", "st": "30.50"}, {"sp": "N", "t": "ἐν εἰρήνῃ δὲ τοσούτῳ μοι δοκεῖ διαφέρειν παρασιτικὴ φιλοσοφίας ὅσον αὐτὴ ἡ εἰρήνη πολέμου.", "st": "30.51"}, {"sp": "N", "t": "καὶ πρῶτον, εἰ δοκεῖ, σκοπῶμεν τὰ τῆς εἰρήνης χωρία.", "st": "30.51"}, {"sp": "N", "t": "<em>Τυχιάδης.<\/em> οὔπω συνίημι ὅ τι τοῦτό πως βούλεται, σκοπῶμεν δὲ ὅμως.", "st": "30.51"}, {"sp": "N", "t": "<em>Σίμων.<\/em> οὐκοῦν ἀγορὰν καὶ δικαστήρια καὶ παλαίστρας καὶ γυμνάσια καὶ κυνηγέσια καὶ συμπόσια ἔγωγε φαίην ἂν πόλεως χωρία.", "st": "30.51"}, {"sp": "N", "t": "<em>Τυχιάδης.<\/em> πάνυ μὲν οὖν.", "st": "30.51"}, {"sp": "N", "t": "<em>Σίμων.<\/em> ὁ τοίνυν παράσιτος εἰς ἀγορὰν μὲν καὶ δικαστήρια οὐ πάρεισιν, ὅτι, οἶμαι, τοῖς συκοφάνταις πάντα τὰ χωρία ταῦτα μᾶλλον προσήκει καὶ ὅτι οὐδὲν μέτριόν ἐστιν τῶν ἐν τούτοις γιγνομένων, τὰς δὲ παλαίστρας καὶ τὰ γυμνάσια καὶ τὰ συμπόσια διώκει καὶ κοσμεῖ μόνος οὗτος. ἐπεὶ τίς ἐν παλαίστρᾳ φιλόσοφος ἢ ῥήτωρ ἀποδὺς ἄξιος συγκριθῆναι παρασίτου τῷ σώματι; ἢ τίς ἐν γυμνασίῳ τούτων ὀφθεὶς οὐκ αἰσχύνη μᾶλλον τοῦ χωρίου ἐστί; καὶ μὴν ἐν ἐρημίᾳ τούτων οὐδεὶς ἂν ὑποσταίη θηρίον ὁμόσε ἰόν, ὁ δὲ παράσιτος αὐτά τε ἐπιόντα μένει καὶ δέχεται ῥᾳδίως, μεμελετηκὼς αὐτῶν ἐν τοῖς δείπνοις καταφρονεῖν, καὶ οὔτε ἔλαφος οὔτε σῦς αὐτὸν ἐκπλήττει πεφρικώς, ἀλλὰ κἂν ἐπ’ αὐτὸν ὁ σῦς τὸν ὀδόντα θήγῃ, καὶ ὁ παράσιτος ἐπὶ τὸν σῦν ἀντιθήγει. τοὺς μὲν γὰρ λαγὼς διώκει μᾶλλον τῶν κυνῶν. ἐν δὲ δὴ συμποσίῳ τίς ἂν καὶ ἁμιλλήσαιτο παρασίτῳ ἤτοι παίζοντι ἢ ἐσθίοντι; τίς δ’ ἂν μᾶλλον εὐφράναι τοὺς συμπότας; πότερόν ποτε οὗτος ᾄδων καὶ σκώπτων, ἢ ἄνθρωπος μὴ γελῶν, ἐν τριβωνίῳ κείμενος, εἰς τὴν γῆν ὁρῶν, ὥσπερ ἐπὶ πένθος οὐχὶ συμπόσιον ἥκων; καὶ ἔμοιγε δοκεῖ, ἐν συμποσίῳ φιλόσοφος τοιοῦτόν ἐστιν οἷον ἐν βαλανείῳ κύων.", "st": "30.51"}, {"sp": "N", "t": "φέρε δὴ ταῦτα ἀφέντες ἐπ’ αὐτὸν ἤδη βαδίζωμεν τὸν βίον τοῦ παρασίτου, σκοποῦντες ἅμα καὶ παραβάλλοντες ἐκεῖνον.", "st": "30.52"}, {"sp": "N", "t": "πρῶτον τοίνυν ἴδοι τις ἂν τὸν μὲν παράσιτον ἀεὶ δόξης καταφρονοῦντα καὶ οὐδὲν αὐτῷ μέλον ὅ τι ἂν οἱ ἄνθρωποι οἴωνται περὶ αὐτοῦ, ῥήτορας δὲ καὶ φιλοσόφους εὕροι τις ἂν οὐ τινάς, ἀλλὰ πάντας ὑπὸ τύφου καὶ δόξης τριβέντας, καὶ οὐ δόξης μόνον, ἀλλὰ καὶ ὃ τούτου αἴσχιόν ἐστιν, ὑπ’ ἀργυρίου. καὶ ὁ μὲν παράσιτος οὕτως ἔχει πρὸς ἀργύριον ὡς οὐκ ἄν τις οὐδὲ πρὸς τὰς ἐν τοῖς αἰγιαλοῖς ψηφῖδας ἀμελῶς ἔχοι, καὶ οὐδὲν αὐτῷ δοκεῖ διαφέρειν τὸ χρυσίον τοῦ πυρός. οἵ γε μὴν ῥήτορες, καὶ ὃ δεινότερόν ἐστιν, καὶ οἱ φιλοσοφεῖν φάσκοντες πρὸς αὐτὰ οὕτως διάκεινται κακοδαιμόνως, ὥστε τῶν μάλιστα νῦν εὐδοκιμούντων φιλοσόφων — περὶ μὲν γὰρ τῶν ῥητόρων τί δεῖ λέγειν; — ὁ μὲν δικάζων δίκην δώροις ἐπ’ αὐτῇ ἑάλω, ὁ δὲ παρὰ βασιλέως ὑπὲρ τοῦ συνεῖναι μισθὸν αἰτεῖ καὶ οὐκ αἰσχύνεται ὅτι πρεσβύτης ἀνὴρ διὰ τοῦτο ἀποδημεῖ καὶ μισθοφορεῖ καθάπερ Ἰνδὸς ἢ Σκύθης αἰχμάλωτος, καὶ οὐδὲ αὐτὸ τὸ ὄνομα αἰσχύνεται ὃ λαμβάνει.", "st": "30.52"}, {"sp": "N", "t": "εὕροις δ’ ἂν οὐ μόνον ταῦτα περὶ τούτους, ἀλλὰ καὶ ἄλλα πάθη, οἷον λύπας καὶ ὀργὰς καὶ φθόνους καὶ παντοίας ἐπιθυμίας. ὅ γε μὴν παράσιτος ἔξωθεν τούτων ἐστὶν ἁπάντων· οὔτε γὰρ ὀργίζεται δι’ ἀνεξικακίαν καὶ ὅτι οὐκ ἔστιν αὐτῷ ὅτῳ ὀργισθείη· καὶ εἰ ἀγανακτήσειεν δέ ποτε, ἡ ὀργὴ αὐτοῦ χαλεπὸν μὲν οὐδὲ σκυθρωπὸν οὐδὲν ἀπεργάζεται, μᾶλλον δὲ γέλωτα, καὶ εὐφραίνει τοὺς συνόντας. λυπεῖταί γε μὴν ἥκιστα πάντων, τοῦτο τῆς τέχνης παρασκευαζούσης αὐτῷ καὶ χαριζομένης, μὴ ἔχειν ὑπὲρ ὅτου λυπηθείη· οὔτε γὰρ χρήματά ἐστιν αὐτῷ οὔτε οἶκος οὔτε οἰκέτης οὔτε γυνὴ οὔτε παῖδες, ὧν διαφθειρομένων πᾶσα ἀνάγκη ἐστὶ λυπεῖσθαι τὸν ἔχοντα αὐτά. ἐπιθυμεῖ δὲ οὔτε δόξης οὔτε χρημάτων, ἀλλ’ οὐδὲ ὡραίου τινός.", "st": "30.53"}, {"sp": "N", "t": "<em>Τυχιάδης.<\/em> ἀλλ’, ὦ Σίμων, εἰκός γε ἐνδείᾳ τροφῆς λυπηθῆναι αὐτόν.", "st": "30.54"}, {"sp": "N", "t": "<em>Σίμων.<\/em> ἀγνοεῖς, ὦ Τυχιάδη, ὅτι ἐξ ἀρχῆς οὐδὲ παράσιτός ἐστιν οὗτος, ὅστις ἀπορεῖ τροφῆς· οὐδὲ γὰρ ἀνδρεῖος ἀπορίᾳ ἀνδρείας ἐστὶν ἀνδρεῖος, οὐδὲ φρόνιμος ἀπορίᾳ φρενῶν ἐστιν φρόνιμος· ἄλλως γὰρ οὐδὲ παράσιτος ἂν εἴη. πρόκειται δὲ ἡμῖν περὶ παρασίτου ζητεῖν ὄντος, οὐχὶ μὴ ὄντος. εἰ δὲ ὁ ἀνδρεῖος οὐκ ἄλλως ἢ παρουσίᾳ ἀνδρειότητος καὶ ὁ φρόνιμος παρουσίᾳ φρονήσεως, καὶ ὁ παράσιτος δὲ παρουσίᾳ τοῦ παρασιτεῖν παράσιτος ἔσται· ὡς εἴ γε τοῦτο μὴ ὑπάρχοι αὐτῷ, περὶ ἄλλου τινός, καὶ οὐχὶ παρασίτου, ζητήσομεν.", "st": "30.54"}, {"sp": "N", "t": "<em>Τυχιάδης.<\/em> οὐκοῦν οὐδέποτε ἀπορήσει παράσιτος τροφῆς", "st": "30.54"}, {"sp": "N", "t": "<em>Σίμων.<\/em> ἔοικεν· ὥστε οὔτ’ ἐπὶ τούτῳ οὔτ’ ἐπ’ ἄλλῳ ἐστὶν ὅτῳ λυπηθείη ἄν.", "st": "30.54"}, {"sp": "N", "t": "καὶ μὴν καὶ πάντες ὁμοῦ καὶ φιλόσοφοι καὶ ῥήτορες φοβοῦνται μάλιστα. τούς γέ τοι πλείστους αὐτῶν εὕροι τις ἂν μετὰ ξύλου προϊόντας, οὐκ ἂν δή που, εἰ μὴ ἐφοβοῦντο, ὡπλισμένους, καὶ τὰς θύρας δὲ μάλα ἐρρωμένως ἀποκλείοντας, μή τις ἄρα νύκτωρ ἐπιβουλεύσειεν αὐτοῖς δεδιότας. ὁ δὲ τὴν θύραν τοῦ δωματίου προστίθησιν εἰκῆ, καὶ τοῦτο ὡς μὴ ὑπ’ ἀνέμου ἀνοιχθείη, καὶ γενομένου ψόφου νύκτωρ οὐδέν τι μᾶλλον θορυβεῖται ἢ μὴ γενομένου, καὶ δι’ ἐρημίας δὲ ἀπιὼν ἄνευ ξίφους ὁδεύει· φοβεῖται γὰρ οὐδὲν οὐδαμοῦ. φιλοσόφους δὲ ἤδη ἐγὼ πολλάκις εἶδον, οὐδενὸς ὄντος δεινοῦ, τόξα ἐνεσκευασμένους· ξύλα μὲν γὰρ ἔχουσιν καὶ εἰς βαλανεῖον ἀπιόντες καὶ ἐπ’ ἄριστον.", "st": "30.55"}, {"sp": "N", "t": "παρασίτου μέντοι οὐδεὶς ἔχοι κατηγορῆσαι μοιχείαν ἢ βίαν ἢ ἁρπαγὴν ἢ ἄλλο τι ἀδίκημα ἁπλῶς· ἐπεὶ ὅ γε τοιοῦτος οὐκ ἂν εἴη παράσιτος, ἀλλ’ ἑαυτὸν ἐκεῖνος ἀδικεῖ. ὥστ’ εἰ μοιχεύσας τύχοι, ἅμα τῷ ἀδικήματι καὶ τοὔνομα μεταλαμβάνει τοῦ ἀδικήματος. ὥσπερ γὰρ ὁ ἀγαθὸς φαῦλα ποιῶν διὰ τοῦτο οὐκ ἀγαθός, ἀλλὰ φαῦλος εἶναι ἀναλαμβάνει, οὕτως, οἶμαι, καὶ ὁ παράσιτος, ἐάν τι ἀδικῇ, αὐτὸ μὲν τοῦτο ὅπερ ἐστὶν ἀποβάλλει, ἀναλαμβάνει δὲ ὃ ἀδικεῖ. ἀδικήματα δὲ τοιαῦτα ῥητόρων καὶ φιλοσόφων ἄφθονα οὐ μόνον ἴσμεν αὐτοὶ γεγονότα καθ’ ἡμᾶς, ἀλλὰ κἀν τοῖς βιβλίοις ἀπολελειμμένα ὑπομνήματα ἔχομεν ὧν ἠδίκησαν. ἀπολογία μὲν γὰρ Σωκράτους ἐστὶν καὶ Αἰσχίνου καὶ Ὑπερίδου καὶ Δημοσθένους καὶ τῶν πλείστων σχεδόν τι ῥητόρων καὶ σοφῶν, παρασίτου δὲ οὐκ ἔστιν ἀπολογία οὐδ’ ἔχει τις εἰπεῖν δίκην πρὸς παράσιτόν τινι γεγραμμένην.", "st": "30.56"}, {"sp": "N", "t": "ἀλλὰ νὴ Δία ὁ μὲν βίος τοῦ παρασίτου κρείττων ἐστὶν τοῦ τῶν ῥητόρων καὶ τῶν φιλοσόφων, ὁ δὲ θάνατος φαυλότερος; πάνυ μὲν οὖν τοὐναντίον παρὰ πολὺ εὐδαιμονέστερος. φιλοσόφους μὲν γὰρ ἴσμεν ἅπαντας ἢ τοὺς πλείστους κακοὺς κακῶς ἀποθανόντας, τοὺς μὲν ἐκ καταδίκης, ἑαλωκότας ἐπὶ τοῖς μεγίστοις ἀδικήμασι, φαρμάκῳ, τοὺς δὲ καταπρησθέντας τὸ σῶμα ἅπαν, τοὺς δὲ ἀπὸ δυσουρίας φθινήσαντας, τοὺς δὲ φυγόντας. παρασίτου δὲ θάνατον οὐδεὶς ἔχει τοιοῦτον εἰπεῖν, ἀλλὰ τὸν εὐδαιμονέστατον φαγόντος καὶ πιόντος. εἰ δέ τις καὶ δοκεῖ βιαίῳ τετελευτηκέναι θανάτῳ, ἀπεπτήσας ἀπέθανεν.", "st": "30.57"}, {"sp": "N", "t": "<em>Τυχιάδης.<\/em> ταῦτα μὲν ἱκανῶς διημίλληταί σοι τὰ πρὸς τοὺς φιλοσόφους ὑπὲρ τοῦ παρασίτου. λοιπὸν δὲ εἰ καλὸν καὶ λυσιτελές ἐστιν τὸ κτῆμα τοῦτο τῷ τρέφοντι, πειρῶ λέγειν· ἐμοὶ μὲν γὰρ δοκοῦσιν ὥσπερ εὐεργετοῦντες καὶ χαριζόμενοι τρέφειν αὐτοὺς οἱ πλούσιοι, καὶ εἶναι τοῦτο αἰσχύνην τῷ τρεφομένῳ.", "st": "30.58"}, {"sp": "N", "t": "<em>Σίμων.<\/em> ὡς ἠλίθιά γε σου, ὦ Τυχιάδη, ταῦτα, εἰ μὴ δύνασαι γινώσκειν ὅτι πλούσιος ἀνήρ, εἰ καὶ τὸ Γύγου χρυσίον ἔχοι, μόνος ἐσθίων πένης ἐστὶν καὶ προϊὼν ἄνευ παρασίτου πτωχὸς δοκεῖ, καὶ ὥσπερ στρατιώτης χωρὶς ὅπλων ἀτιμότερος καὶ ἐσθὴς ἄνευ πορφύρας καὶ ἵππος ἄνευ φαλάρων, οὕτω καὶ πλούσιος ἄνευ παρασίτου ταπεινός τις καὶ εὐτελὴς φαίνεται. καὶ μὴν ὁ μὲν πλούσιος κοσμεῖται ὑπ’ αὐτοῦ, τὸν δὲ παράσιτον πλούσιος οὐδέποτε κοσμεῖ.", "st": "30.58"}, {"sp": "N", "t": "ἄλλως τε οὐδὲ ὄνειδος αὐτῷ ἐστιν, ὡς σὺ φής, τὸ παρασιτεῖν ἐκείνῳ, δῆλον ὅτι ὥς τινι κρείττονι χείρονα, ὅπου γε μὴν τῷ πλουσίῳ τοῦτο λυσιτελές ἐστιν, τὸ τρέφειν τὸν παράσιτον, ᾧ γε μετὰ τοῦ κοσμεῖσθαι ὑπ’ αὐτοῦ καὶ ἀσφάλεια πολλὴ ἐκ τῆς τούτου δορυφορίας ὑπάρχει· οὔτε γὰρ μάχῃ ῥᾳδίως ἄν τις ἐπιχειρήσαι τῷ πλουσίῳ τοῦτον ὁρῶν παρεστῶτα, ἀλλ’ οὐδ’ ἂν ἀποθάνοι φαρμάκῳ οὐδεὶς ἔχων παράσιτον. τίς γὰρ ἂν τολμήσειεν ἐπιβουλεῦσαί τινι τούτου προεσθίοντος καὶ προπίνοντος; ὥστε ὁ πλούσιος οὐχὶ κοσμεῖται μόνον, ἀλλὰ καὶ ἐκ τῶν μεγίστων κινδύνων ὑπὸ τοῦ παρασίτου σώζεται. οὕτω μὲν ὁ παράσιτος διὰ φιλοστοργίαν πάντα κίνδυνον ὑπομένει, καὶ οὐκ ἂν παραχωρήσειεν τῷ πλουσίῳ φαγεῖν μόνῳ, ἀλλὰ καὶ ἀποθανεῖν αἱρεῖται συμφαγών.", "st": "30.59"}, {"sp": "N", "t": "<em>Τυχιάδης.<\/em> πάντα μοι δοκεῖς, ὦ Σίμων, διεξελθεῖν ὑστερήσας οὐδὲν τῆς σεαυτοῦ τέχνης, οὐχ ὥσπερ αὐτὸς ἔφασκες, ἀμελέτητος ὤν, ἀλλ’ ὥσπερ ἄν τις ὑπὸ τῶν μεγίστων γεγυμνασμένος. λοιπόν, εἰ μὴ αἴσχιον αὐτὸ τὸ ὄνομά ἐστι τῆς παρασιτικῆς, θέλω μαθεῖν.", "st": "30.60"}, {"sp": "N", "t": "<em>Σίμων.<\/em> ὅρα δὴ τὴν ἀπόκρισιν, ἐάν σοι ἱκανῶς λέγεσθαι δοκῇ, καὶ πειρῶ πάλιν αὐτὸς ἀποκρίνασθαι πρὸς τὸ ἐρωτώμενον ᾗ ἄριστα οἴει. φέρε γάρ, τὸν σῖτον οἱ παλαιοὶ τί καλοῦσι;", "st": "30.60"}, {"sp": "N", "t": "<em>Τυχιάδης.<\/em> τροφήν.", "st": "30.60"}, {"sp": "N", "t": "<em>Σίμων.<\/em> τί δὲ τὸ σιτεῖσθαι, οὐχὶ τὸ ἐσθίειν;", "st": "30.60"}, {"sp": "N", "t": "<em>Τυχιάδης.<\/em> ναί.", "st": "30.60"}, {"sp": "N", "t": "<em>Σίμων.<\/em> οὐκοῦν καθωμολόγηται τὸ παρασιτεῖν ὅτι οὐκ ἄλλο ἐστίν;", "st": "30.60"}, {"sp": "N", "t": "<em>Τυχιάδης.<\/em> τοῦτο γάρ, ὦ Σίμων, ἐστὶν ὃ αἰσχρὸν φαίνεται.", "st": "30.60"}, {"sp": "N", "t": "<em>Σίμων.<\/em> φέρε δὴ πάλιν ἀπόκριναί μοι, πότερόν σοι δοκεῖ διαφέρειν, καὶ προκειμένων ἀμφοῖν πότερον ἂν αὐτὸς ἕλοιο, ἆρά γε τὸ πλεῖν ἢ τὸ παραπλεῖν;", "st": "30.61"}, {"sp": "N", "t": "<em>Τυχιάδης.<\/em> τὸ παραπλεῖν ἔγωγε.", "st": "30.61"}, {"sp": "N", "t": "<em>Σίμων.<\/em> τί δέ, τὸ τρέχειν ἢ τὸ παρατρέχειν;", "st": "30.61"}, {"sp": "N", "t": "<em>Τυχιάδης.<\/em> Τὸ παρατρέχειν.", "st": "30.61"}, {"sp": "N", "t": "<em>Σίμων.<\/em> τί δέ, τὸ ἱππεύειν ἢ τὸ παριππεύειν;", "st": "30.61"}, {"sp": "N", "t": "<em>Τυχιάδης.<\/em> τὸ παριππεύειν.", "st": "30.61"}, {"sp": "N", "t": "<em>Σίμων.<\/em> τί δέ, τὸ ἀκοντίζειν ἢ τὸ παρακοντίζειν;", "st": "30.61"}, {"sp": "N", "t": "<em>Τυχιάδης.<\/em> τὸ παρακοντίζειν.", "st": "30.61"}, {"sp": "N", "t": "<em>Σίμων.<\/em> οὐκοῦν ὁμοίως ἂν ἕλοιο καὶ τοῦ ἐσθίειν μᾶλλον τὸ παρασιτεῖν;", "st": "30.61"}, {"sp": "N", "t": "<em>Τυχιάδης.<\/em> ὁμολογεῖν ἀνάγκη. καί σοι λοιπὸν ὥσπερ οἱ παῖδες ἀφίξομαι καὶ ἑῷος καὶ μετ’ ἄριστον μαθησόμενος τὴν τέχνην. σὺ δέ με αὐτὴν δίκαιος διδάσκειν ἀφθόνως, ἐπεὶ καὶ πρῶτος μαθητής σοι γίγνομαι. φασὶ δὲ καὶ τὰς μητέρας μᾶλλον τὰ πρῶτα φιλεῖν τῶν τέκνων.", "st": "30.61"}, {"sp": "HDR", "t": "Φιλοψευδὴς ἢ Ἀπιστῶν"}, {"sp": "N", "t": "<em>Τυχιάδης.<\/em> ἔχεις μοι, ὦ Φιλόκλεις, εἰπεῖν τί ποτε ἄρα ἐστὶν ὃ πολλοὺς εἰς ἐπιθυμίαν τοῦ ψεύδους προάγεται, ὡς αὐτούς τε χαίρειν μηδὲν ὑγιὲς λέγοντας καὶ τοῖς τὰ τοιαῦτα διεξιοῦσιν μάλιστα προσέχειν τὸν νοῦν;", "st": "31.1"}, {"sp": "N", "t": "<em>Φιλοκλῆς.<\/em> πολλά, ὦ Τυχιάδη, ἐστὶν ἃ τοὺς ἀνθρώπους ἐνίους ἀναγκάζει τὰ ψευδῆ λέγειν εἰς τὸ χρήσιμον ἀποβλέποντας.", "st": "31.1"}, {"sp": "N", "t": "<em>Τυχιάδης.<\/em> οὐδὲν πρὸς ἔπος ταῦτα, φασίν, οὐ γὰρ περὶ τούτων ἠρόμην ὁπόσοι τῆς χρείας ἕνεκα ψεύδονται· συγγνωστοὶ γὰρ οὗτοί γε, μᾶλλον δὲ καὶ ἐπαίνου τινὲς αὐτῶν ἄξιοι, ὁπόσοι ἢ πολεμίους ἐξηπάτησαν ἢ ἐπὶ σωτηρίᾳ τῷ τοιούτῳ φαρμάκῳ ἐχρήσαντο ἐν τοῖς δεινοῖς, οἷα πολλὰ καὶ ὁ Ὀδυσσεὺς ἐποίει τήν τε αὑτοῦ ψυχὴν ἀρνύμενος καὶ τὸν νόστον τῶν ἑταίρων. ἀλλὰ περὶ ἐκείνων, ὦ ἄριστε, φημὶ οἳ αὐτὸ ἄνευ τῆς χρείας τὸ ψεῦδος πρὸ πολλοῦ τῆς ἀληθείας τίθενται, ἡδόμενοι τῷ πράγματι καὶ ἐνδιατρίβοντες ἐπ’ οὐδεμιᾷ προφάσει ἀναγκαίᾳ. τούτους οὖν ἐθέλω εἰδέναι τίνος ἀγαθοῦ τοῦτο ποιοῦσιν.", "st": "31.1"}, {"sp": "N", "t": "<em>Φιλοκλῆς.<\/em> ἦ που κατανενόηκας ἤδη τινὰς τοιούτους, οἷς ἔμφυτος ὁ ἔρως οὗτός ἐστι πρὸς τὸ ψεῦδος;", "st": "31.2"}, {"sp": "N", "t": "<em>Τυχιάδης.<\/em> καὶ μάλα πολλοί εἰσιν οἱ τοιοῦτοι.", "st": "31.2"}, {"sp": "N", "t": "<em>Φιλοκλῆς.<\/em> τί δ’ οὖν ἄλλο ἢ ἄνοιαν χρὴ αἰτίαν εἶναι αὐτοῖς φάναι τοῦ μὴ τἀληθῆ λέγειν, εἴ γε τὸ χείριστον ἀντὶ τοῦ βελτίστου προαιροῦνται;", "st": "31.2"}, {"sp": "N", "t": "<em>Τυχιάδης.<\/em> οὐδὲν οὐδὲ τοῦτο, ὦ Φιλόκλεις· ἐπεὶ πολλοὺς ἂν ἐγώ σοι δείξαιμι συνετοὺς τἄλλα καὶ τὴν γνώμην θαυμαστοὺς οὐκ οἶδ’ ὅπως ἑαλωκότας τούτῳ τῷ κακῷ καὶ φιλοψευδεῖς ὄντας, ὡς ἀνιᾶσθαί με, εἰ τοιοῦτοι ἄνδρες ἄριστοι τὰ πάντα ὅμως χαίρουσιν αὑτούς τε καὶ τοὺς ἐντυγχάνοντας ἐξαπατῶντες. ἐκείνους μὲν γὰρ τοὺς παλαιοὺς πρὸ ἐμοῦ σὲ χρὴ εἰδέναι, τὸν Ἡρόδοτον καὶ Κτησίαν τὸν Κνίδιον καὶ πρὸ τούτων τοὺς ποιητὰς καὶ τὸν Ὅμηρον αὐτόν, ἀοιδίμους ἄνδρας, ἐγγράφῳ τῷ ψεύσματι κεχρημένους, ὡς μὴ μόνους ἐξαπατᾶν τοὺς τότε ἀκούοντας σφῶν, ἀλλὰ καὶ μέχρις ἡμῶν διικνεῖσθαι τὸ ψεῦδος ἐκ διαδοχῆς ἐν καλλίστοις ἔπεσι καὶ μέτροις φυλαττόμενον. ἐμοὶ γοῦν πολλάκις αἰδεῖσθαι ὑπὲρ αὐτῶν ἔπεισιν, ὁπόταν Οὐρανοῦ τομὴν καὶ Προμηθέως δεσμὰ διηγῶνται καὶ Γιγάντων ἐπανάστασιν καὶ τὴν ἐν Ἅιδου πᾶσαν τραγῳδίαν, καὶ ὡς δι’ ἔρωτα ὁ Ζεὺς ταῦρος ἢ κύκνος ἐγένετο καὶ ὡς ἐκ γυναικός τις εἰς ὄρνεον ἢ εἰς ἄρκτον μετέπεσεν, ἔτι δὲ Πηγάσους καὶ Χιμαίρας καὶ Γοργόνας καὶ Κύκλωπας καὶ ὅσα τοιαῦτα, πάνυ ἀλλόκοτα καὶ τεράστια μυθίδια παίδων ψυχὰς κηλεῖν δυνάμενα ἔτι τὴν Μορμὼ καὶ τὴν Λάμιαν δεδιότων.", "st": "31.2"}, {"sp": "N", "t": "καίτοι τὰ μὲν τῶν ποιητῶν ἴσως μέτρια, τὸ δὲ καὶ πόλεις ἤδη καὶ ἔθνη ὅλα κοινῇ καὶ δημοσίᾳ ψεύδεσθαι πῶς οὐ γελοῖον; εἰ Κρῆτες μὲν τὸν Διὸς τάφον δεικνύντες οὐκ αἰσχύνονται, Ἀθηναῖοι δὲ τὸν Ἐριχθόνιον ἐκ τῆς γῆς ἀναδοθῆναί φασιν καὶ τοὺς πρώτους ἀνθρώπους ἐκ τῆς Ἀττικῆς ἀναφῦναι καθάπερ τὰ λάχανα, πολὺ σεμνότερον οὗτοί γε τῶν Θηβαίων, οἳ ἐξ ὄφεως ὀδόντων Σπαρτούς τινας ἀναβεβλαστηκέναι διηγοῦνται. ὃς δ’ ἂν οὖν ταῦτα καταγέλαστα ὄντα μὴ οἴηται ἀληθῆ εἶναι, ἀλλ’ ἐμφρόνως ἐξετάζων αὐτὰ Κοροίβου τινὸς ἢ Μαργίτου νομίζῃ τὸ πείθεσθαι ἢ Τριπτόλεμον ἐλάσαι διὰ τοῦ ἀέρος ἐπὶ δρακόντων ὑποπτέρων ἢ Πᾶνα ἥκειν ἐξ Ἀρκαδίας σύμμαχον εἰς Μαραθῶνα ἢ Ὠρείθυιαν ὑπὸ τοῦ Βορέου ἁρπασθῆναι, ἀσεβὴς οὗτός γε καὶ ἀνόητος αὐτοῖς ἔδοξεν οὕτω προδήλοις καὶ ἀληθέσι πράγμασιν ἀπιστῶν· εἰς τοσοῦτον ἐπικρατεῖ τὸ ψεῦδος.", "st": "31.3"}, {"sp": "N", "t": "<em>Φιλοκλῆς.<\/em> ἀλλ’ οἱ μὲν ποιηταί, ὦ Τυχιάδη, καὶ αἱ πόλεις δὲ συγγνώμης εἰκότως τυγχάνοιεν ἄν, οἱ μὲν τὸ ἐκ τοῦ μύθου τερπνὸν ἐπαγωγότατον ὂν ἐγκαταμιγνύντες τῇ γραφῇ, οὗπερ μάλιστα δέονται πρὸς τοὺς ἀκροατάς, Ἀθηναῖοι δὲ καὶ Θηβαῖοι καὶ εἴ τινες ἄλλοι σεμνοτέρας ἀποφαίνοντες τὰς πατρίδας ἐκ τῶν τοιούτων. εἰ γοῦν τις ἀφέλοι τὰ μυθώδη ταῦτα ἐκ τῆς Ἑλλάδος, οὐδὲν ἂν κωλύσειε λιμῷ τοὺς περιηγητὰς αὐτῶν διαφθαρῆναι μηδὲ ἀμισθὶ τῶν ξένων τἀληθὲς ἀκούειν ἐθελησάντων. οἱ δὲ μηδεμιᾶς ἕνεκα αἰτίας τοιαύτης ὅμως χαίροντες τῷ ψεύσματι παγγέλοιοι εἰκότως δοκοῖεν ἄν.", "st": "31.4"}, {"sp": "N", "t": "<em>Τυχιάδης.<\/em> εὖ λέγεις· ἐγώ γέ τοι παρὰ Εὐκράτους ἥκω σοι τοῦ πάνυ, πολλὰ τὰ ἄπιστα καὶ μυθώδη ἀκούσας· μᾶλλον δὲ μεταξὺ λεγομένων ἀπιὼν ᾠχόμην οὐ φέρων τοῦ πράγματος τὴν ὑπερβολήν, ἀλλά με ὥσπερ αἱ Ἐρινύες ἐξήλασαν πολλὰ τεράστια καὶ ἀλλόκοτα διεξιόντες.", "st": "31.5"}, {"sp": "N", "t": "<em>Φιλοκλῆς.<\/em> καίτοι, ὦ Τυχιάδη, ἀξιόπιστός τις ὁ Εὐκράτης ἐστίν, καὶ οὐδεὶς ἂν οὐδὲ πιστεύσειεν ὡς ἐκεῖνος οὕτω βαθὺν πώγωνα καθειμένος ἑξηκοντούτης ἀνήρ, ἔτι καὶ φιλοσοφίᾳ συνὼν τὰ πολλά, ὑπομείνειεν ἂν καὶ ἄλλου τινὸς ψευδομένου ἐπακοῦσαι παρών, οὐχ ὅπως αὐτός τι τολμῆσαι τοιοῦτον.", "st": "31.5"}, {"sp": "N", "t": "<em>Τυχιάδης.<\/em> οὐ γὰρ οἶσθα, ὦ ἑταῖρε, οἷα μὲν εἶπεν, ὅπως δὲ αὐτὰ ἐπιστώσατο, ὡς δὲ καὶ ἐπώμνυτο τοῖς πλείστοις, παραστησάμενος τὰ παιδία, ὥστε με ἀποβλέποντα εἰς αὐτὸν ποικίλα ἐννοεῖν, ἄρτι μὲν ὡς μεμήνοι καὶ ἔξω εἴη τοῦ καθεστηκότος, ἄρτι δὲ ὡς γόης ὢν ἄρα τοσοῦτον χρόνον ἐλελήθει με ὑπὸ τῇ λεοντῇ γελοῖόν τινα πίθηκον περιστέλλων· οὕτως ἄτοπα διηγεῖτο.", "st": "31.5"}, {"sp": "N", "t": "<em>Φιλοκλῆς.<\/em> τίνα ταῦτα πρὸς τῆς Ἑστίας, ὦ Τυχιάδη; ἐθέλω γὰρ εἰδέναι ἥντινα τὴν ἀλαζονείαν ὑπὸ τηλικούτῳ τῷ πώγωνι ἔσκεπεν.", "st": "31.5"}, {"sp": "N", "t": "<em>Τυχιάδης.<\/em> εἰώθειν μὲν καὶ ἄλλοτε, ὦ Φιλόκλεις, φοιτᾶν παρ’ αὐτόν, εἴ ποτε πολλὴν τὴν σχολὴν ἄγοιμι, τήμερον δὲ Λεοντίχῳ συγγενέσθαι δεόμενος — ἑταῖρος δέ μοι, ὡς οἶσθα — ἀκούσας τοῦ παιδὸς ὡς παρὰ τὸν Εὐκράτην ἕωθεν ἁπέλθοι νοσοῦντα ἐπισκεψόμενος, ἀμφοῖν ἕνεκα, ὡς καὶ τῷ Λεοντίχῳ συγγενοίμην κἀκεῖνον ἴδοιμι — ἠγνοήκειν γὰρ ὡς νοσοίη — παραγίγνομαι πρὸς αὐτόν.", "st": "31.6"}, {"sp": "N", "t": "εὑρίσκω δὲ αὐτόθι τὸν μὲν Λεόντιχον οὐκέτι — ἐφθάκει γάρ, ὡς ἔφασκον, ὀλίγον προεξεληλυθώς — ἄλλους δὲ συχνούς, ἐν οἷς Κλεόδημός τε ἦν ὁ ἐκ τοῦ Περιπάτου καὶ Δεινόμαχος ὁ Στωϊκὸς καὶ Ἴων, οἶσθα τὸν ἐπὶ τοῖς Πλάτωνος λόγοις θαυμάζεσθαι ἀξιοῦντα ὡς μόνον ἀκριβῶς κατανενοηκότα τὴν γνώμην τοῦ ἀνδρὸς καὶ τοῖς ἄλλοις ὑποφητεῦσαι δυνάμενον. ὁρᾷς οἵους ἄνδρας σοί φημι, πανσόφους καὶ παναρέτους, ὅ τι περ τὸ κεφάλαιον αὐτὸ ἐξ ἑκάστης προαιρέσεως, αἰδεσίμους ἅπαντας καὶ μονονουχὶ φοβεροὺς τὴν πρόσοψιν; ἔτι καὶ ὁ ἰατρὸς Ἀντίγονος παρῆν, κατὰ χρείαν, οἶμαι, τῆς νόσου ἐπικληθείς. καὶ ῥᾷον ἐδόκει ἤδη ἔχειν ὁ Εὐκράτης καὶ τὸ νόσημα τῶν συντρόφων ἦν· τὸ ῥεῦμα γὰρ εἰς τοὺς πόδας αὖθις αὐτῷ κατεληλύθει.", "st": "31.6"}, {"sp": "N", "t": "Καθέζεσθαι οὖν με παρ’ αὐτὸν ἐπὶ τῆς κλίνης ὁ Εὐκράτης ἐκέλευεν, ἠρέμα ἐγκλίνας τῇ φωνῇ εἰς τὸ ἀσθενικὸν ὁπότε εἶδέ με, καίτοι βοῶντος αὐτοῦ καὶ διατεινομένου τι μεταξὺ εἰσιὼν ἐπήκουον. κἀγὼ μάλα πεφυλαγμένως, μὴ ψαύσαιμι τοῖν ποδοῖν αὐτοῦ, ἀπολογησάμενος τὰ συνήθη ταῦτα, ὡς ἀγνοήσαιμι νοσοῦντα καὶ ὡς ἐπεὶ ἔμαθον δρομαῖος ἔλθοιμι, ἐκαθεζόμην πλησίον.", "st": "31.6"}, {"sp": "N", "t": "οἱ μὲν δὴ ἐτύγχανον οἶμαι περὶ τοῦ νοσήματος τὰ μὲν ἤδη πολλὰ προειρηκότες, τὰ δὲ καὶ τότε διεξιόντες, ἔτι δὲ καὶ θεραπείας τινὰς ἕκαστος ὑποβάλλοντες. ὁ γοῦν Κλεόδημος, “εἰ τοίνυν,” φησίν, “τῇ ἀριστερᾷ τις ἀνελόμενος χαμᾶθεν τὸν ὀδόντα τῆς μυγαλῆς οὕτω φονευθείσης, ὡς προεῖπον, ἐνδήσειεν εἰς δέρμα λέοντος ἄρτι ἀποδαρέν, εἶτα περιάψειε περὶ τὰ σκέλη, αὐτίκα παύεται τὸ ἄλγημα.”", "st": "31.7"}, {"sp": "N", "t": "“οὐκ εἰς λέοντος,” ἔφη ὁ Δεινόμαχος, “ἐγὼ ἤκουσα, ἐλάφου δὲ θηλείας ἔτι παρθένου καὶ ἀβάτου· καὶ τὸ πρᾶγμα οὕτω πιθανώτερον· ὠκὺ γὰρ ἡ ἔλαφος καὶ ἔρρωται μάλιστα ἐκ τῶν ποδῶν. ὁ δὲ λέων ἄλκιμος μέν, καὶ τὸ λίπος αὐτοῦ καὶ ἡ χεὶρ ἡ δεξιὰ καὶ αἱ τρίχες ἐκ τοῦ πώγωνος αἱ ὀρθαὶ μεγάλα δύνανται, εἴ τις ἐπίσταιτο αὐτοῖς χρῆσθαι μετὰ τῆς οἰκείας ἐπῳδῆς ἑκάστῳ· ποδῶν δὲ ἴασιν ἥκιστα ἐπαγγέλλεται.”", "st": "31.7"}, {"sp": "N", "t": "“καὶ αὐτός,” ἦ δ’ ὃς ὁ Κλεόδημος, “οὕτω πάλαι ἐγίγνωσκον, ἐλάφου χρῆναι τὸ δέρμα εἶναι, διότι ὠκὺ ἔλαφος· ἔναγχος δὲ Λίβυς ἀνὴρ σοφὸς τὰ τοιαῦτα μετεδίδαξέ με εἰπὼν ὠκυτέρους εἶναι τῶν ἐλάφων τοὺς λέοντας. ἀμέλει, ἔφη, καὶ αἱροῦσιν αὐτὰς διώκοντες.”", "st": "31.7"}, {"sp": "N", "t": "ἐπῄνεσαν οἱ παρόντες ὡς εὖ εἰπόντος τοῦ Λίβυος. ἐγὼ δέ, “οἴεσθε γάρ,” ἔφην, “ἐπῳδαῖς τισιν τὰ τοιαῦτα παύεσθαι ἢ τοῖς ἔξωθεν παραρτήμασιν τοῦ κακοῦ ἔνδον διατρίβοντος;” ἐγέλασαν ἐπὶ τῷ λόγῳ καὶ δῆλοι ἦσαν κατεγνωκότες μου πολλὴν τὴν ἄνοιαν, εἰ μὴ ἐπισταίμην τὰ προδηλότατα καὶ περὶ ὧν οὐδεὶς ἂν εὖ φρονῶν ἀντείποι μὴ οὐχὶ οὕτως ἔχειν. ὁ μέντοι ἰατρὸς Ἀντίγονος ἐδόκει μοι ἡσθῆναι τῇ ἐρωτήσει μου· πάλαι γὰρ ἠμελεῖτο, οἶμαι, βοηθεῖν ἀξιῶν τῷ Εὐκράτει μετὰ τῆς τέχνης οἴνου τε παραγγέλλων ἀπέχεσθαι καὶ λάχανα σιτεῖσθαι καὶ ὅλως ὑφαιρεῖν τοῦ τόνου.", "st": "31.8"}, {"sp": "N", "t": "ὁ δ’ οὖν Κλεόδημος ὑπομειδιῶν ἅμα, “τί λέγεις,” ἔφη, “ὦ Τυχιάδη; ἄπιστον εἶναί σοι δοκεῖ τὸ ἐκ τῶν τοιούτων γίγνεσθαί τινας ὠφελείας εἰς τὰ νοσήματα;” “ἔμοιγε,” ἦν δ’ ἐγώ, “εἰ μὴ πάνυ κορύζης τὴν ῥῖνα μεστὸς εἴην, ὡς πιστεύειν τὰ ἔξω καὶ μηδὲν κοινωνοῦντα τοῖς ἔνδοθεν ἐπεγείρουσι τὰ νοσήματα μετὰ ῥηματίων, ὥς φατε, καὶ γοητείας τινὸς ἐνεργεῖν καὶ τὴν ἴασιν ἐπιπέμπειν προσαρτώμενα. τὸ δ’ οὐκ ἂν γένοιτο, οὐδ’ ἢν εἰς τοῦ Νεμείου λέοντος τὸ δέρμα ἐνδήσῃ τις ἑκκαίδεκα ὅλας μυγαλᾶς· ἐγὼ γοῦν αὐτὸν τὸν λέοντα εἶδον πολλάκις χωλεύοντα ὑπ’ ἀλγηδόνων ἐν ὁλοκλήρῳ τῷ αὑτοῦ δέρματι.”", "st": "31.8"}, {"sp": "N", "t": "“πάνυ γὰρ ἰδιώτης,” ἔφη ὁ Δεινόμαχος, “εἶ καὶ τὰ τοιαῦτα οὐκ ἐμέλησέ σοι ἐκμαθεῖν ὅντινα τρόπον ὁμιλεῖ τοῖς νοσήμασι προσφερόμενα, κἀμοὶ δοκεῖς οὐδὲ τὰ προφανέστατα ἂν παραδέξασθαι ταῦτα, τῶν ἐκ περιόδου πυρετῶν τὰς ἀποπομπὰς καὶ τῶν ἑρπετῶν τὰς καταθέλξεις καὶ βουβώνων ἰάσεις καὶ τἄλλα ὁπόσα καὶ αἱ γρᾶες ἤδη ποιοῦσιν. εἰ δὲ ἐκεῖνα γίγνεται ἅπαντα, τί δή ποτε οὐχὶ ταῦτα οἰήσῃ γίγνεσθαι ὑπὸ τῶν ὁμοίων;”", "st": "31.9"}, {"sp": "N", "t": "“ἀπέραντα,” ἦν δ’ ἐγώ, “σὺ περαίνεις, ὦ Δεινόμαχε, καὶ ἥλῳ, φασίν, ἐκκρούεις τὸν ἧλον· οὐδὲ γὰρ ἃ φὴς ταῦτα δῆλα μετὰ τοιαύτης δυνάμεως γιγνόμενα. ἢν γοῦν μὴ πείσῃς πρότερον ἐπάγων τῷ λόγῳ διότι φύσιν ἔχει οὕτω γίγνεσθαι, τοῦ τε πυρετοῦ καὶ τοῦ οἰδήματος δεδιότος ἢ ὄνομα θεσπέσιον ἢ ῥῆσιν βαρβαρικὴν καὶ διὰ τοῦτο ἐκ τοῦ βουβῶνος δραπετεύοντος, ἔτι σοι γραῶν μῦθοι τὰ λεγόμενά ἐστι.”", "st": "31.9"}, {"sp": "N", "t": "“σύ μοι δοκεῖς,” ἦ δ’ ὃς ὁ Δεινόμαχος, “τὰ τοιαῦτα λέγων οὐδὲ θεοὺς εἶναι πιστεύειν εἴ γε μὴ οἴει τὰς ἰάσεις οἷόν τε εἶναι ὑπὸ ἱερῶν ὀνομάτων γίγνεσθαι.” “τοῦτο μέν,” ἦν δ’ ἐγώ, “μὴ λέγε, ὦ ἄριστε· κωλύει γὰρ οὐδὲν καὶ θεῶν ὄντων ὅμως τὰ τοιαῦτα ψευδῆ εἶναι. ἐγὼ δὲ καὶ θεοὺς σέβω καὶ ἰάσεις αὐτῶν ὁρῶ καὶ ἃ εὖ ποιοῦσι τοὺς κάμνοντας ὑπὸ φαρμάκων καὶ ἰατρικῆς ἀνιστάντες· ὁ γοῦν Ἀσκληπιὸς αὐτὸς καὶ οἱ παῖδες αὐτοῦ ἤπια φάρμακα πάσσοντες ἐθεράπευον τοὺς νοσοῦντας, οὐ λεοντᾶς καὶ μυγαλᾶς περιάπτοντες.”", "st": "31.10"}, {"sp": "N", "t": "“ἔα τοῦτον,” ἔφη ὁ Ἴων, “ἐγὼ δὲ ὑμῖν θαυμάσιόν τι διηγήσομαι. ἦν μὲν ἐγὼ μειράκιον ἔτι ἀμφὶ τὰ τετταρακαίδεκα ἔτη σχεδόν· ἧκεν δέ τις ἀγγέλλων τῷ πατρὶ Μίδαν τὸν ἀμπελουργόν, ἐρρωμένον εἰς τὰ ἄλλα οἰκέτην καὶ ἐργατικόν, ἀμφὶ πλήθουσαν ἀγορὰν ὑπὸ ἐχίδνης δηχθέντα κεῖσθαι ἤδη σεσηπότα τὸ σκέλος· ἀναδοῦντι γὰρ αὐτῷ τὰ κλήματα καὶ ταῖς χάραξι περιπλέκοντι προσερπύσαν τὸ θηρίον δακεῖν κατὰ τὸν μέγαν δάκτυλον, καὶ τὸ μὲν φθάσαι καὶ καταδῦναι αὖθις εἰς τὸν φωλεόν, τὸν δὲ οἰμώζειν ἀπολλύμενον ὑπ’ ἀλγηδόνων.", "st": "31.11"}, {"sp": "N", "t": "ταῦτά τε οὖν ἀπηγγέλλετο καὶ τὸν Μίδαν ἑωρῶμεν αὐτὸν ἐπὶ σκίμποδος ὑπὸ τῶν ὁμοδούλων προσκομιζόμενον, ὅλον ᾠδηκότα, πελιδνόν, μυδῶντα ἐπιπολῆς, ὀλίγον ἔτι ἐμπνέοντα. λελυπημένῳ δὴ τῷ πατρὶ τῶν φίλων τις παρών, ‘θάρρει,’ ἔφη, ‘ἐγὼ γάρ σοι ἄνδρα Βαβυλώνιον τῶν Χαλδαίων, ὥς φασιν, αὐτίκα μέτειμι, ὃς ἰάσεται τὸν ἄνθρωπον’ καὶ ἵνα μὴ διατρίβω λέγων, ἧκεν ὁ Βαβυλώνιος καὶ ἀνέστησε τὸν Μίδαν ἐπῳδῇ τινι ἐξελάσας τὸν ἰὸν ἐκ τοῦ σώματος, ἔτι καὶ προσαρτήσας τῷ ποδὶ νεκρᾶς παρθένου λίθον ἀπὸ τῆς στήλης ἐκκολάψας.", "st": "31.11"}, {"sp": "N", "t": "καὶ τοῦτο μὲν ἴσως μέτριον· καίτοι ὁ Μίδας αὐτὸς ἀράμενος τὸν σκίμποδα ἐφ’ οὗ ἐκεκόμιστο ᾤχετο εἰς τὸν ἀγρὸν ἀπιών· τοσοῦτον ἡ ἐπῳδὴ ἐδυνήθη καὶ ὁ στηλίτης ἐκεῖνος λίθος.", "st": "31.11"}, {"sp": "N", "t": "ὁ δὲ καὶ ἄλλα ἐποίησε θεσπέσια ὡς ἀληθῶς· εἰς γὰρ τὸν ἀγρὸν ἐλθὼν ἕωθεν, ἐπειπὼν ἱερατικά τινα ἐκ βίβλου παλαιᾶς ὀνόματα ἑπτὰ καὶ θείῳ καὶ δᾳδὶ καθαγνίσας τὸν τόπον περιελθὼν ἐς τρίς, ἐξεκάλεσεν ὅσα ἦν ἑρπετὰ ἐντὸς τῶν ὅρων. ἧκον οὖν ὥσπερ ἑλκόμενοι πρὸς τὴν ἐπῳδὴν ὄφεις πολλοὶ καὶ ἀσπίδες καὶ ἔχιδναι καὶ κεράσται καὶ ἀκοντίαι φρῦνοί τε καὶ φύσαλοι, ἐλείπετο δὲ εἷς δράκων παλαιός, ὑπὸ γήρως, οἶμαι, ἐξερπύσαι μὴ δυνάμενος ἢ παρακούσας τοῦ προστάγματος· ὁ δὲ μάγος οὐκ ἔφη παρεῖναι ἅπαντας, ἀλλ’ ἕνα τινὰ τῶν ὄφεων τὸν νεώτατον χειροτονήσας πρεσβευτὴν ἔπεμψεν ἐπὶ τὸν δράκοντα, καὶ μετὰ μικρὸν ἧκε κἀκεῖνος. ἐπεὶ δὲ συνηλίσθησαν, ἐνεφύσησε μὲν αὐτοῖς ὁ Βαβυλώνιος, τὰ δὲ αὐτίκα μάλα κατεκαύθη ἅπαντα ὑπὸ τῷ φυσήματι, ἡμεῖς δὲ ἐθαυμάζομεν.”", "st": "31.12"}, {"sp": "N", "t": "“εἰπέ μοι, ὦ Ἴων,” ἦν δ’ ἐγώ, “ὁ ὄφις δὲ ὁ πρεσβευτὴς ὁ νέος ἄρα καὶ ἐχειραγώγει τὸν δράκοντα ἤδη, ὡς φής, γεγηρακότα, ἢ σκίπωνα ἔχων ἐκεῖνος ἐπεστηρίζετο;”", "st": "31.13"}, {"sp": "N", "t": "“σὺ μὲν παίζεις,” ἔφη ὁ Κλεόδημος, “ἐγὼ δὲ καὶ αὐτὸς ἀπιστότερος ὤν σου πάλαι τὰ τοιαῦτα — ᾤμην γὰρ οὐδενὶ λόγῳ δυνατὸν γίγνεσθαι ἂν αὐτὰ — ὅμως ὅτε τὸ πρῶτον εἶδον πετόμενον τὸν ξένον τὸν βάρβαρον — ἐξ Ὑπερβορέων δὲ ἦν, ὡς ἔφασκεν — ἐπίστευσα καὶ ἐνικήθην ἐπὶ πολὺ ἀντισχών. τί γὰρ ἔδει ποιεῖν αὐτὸν ὁρῶντα διὰ τοῦ ἀέρος φερόμενον ἡμέρας οὔσης καὶ ἐφ’ ὕδατος βαδίζοντα καὶ διὰ πυρὸς διεξιόντα σχολῇ καὶ βάδην;” “σὺ ταῦτα εἶδες,” ἦν δ’ ἐγώ, “τὸν Ὑπερβόρεον ἄνδρα πετόμενον ἢ ἐπὶ τοῦ ὕδατος βεβηκότα;” “καὶ μάλα,” ἦ δ’ ὅς, “ὑποδεδεμένον γε καρβατίνας, οἷα μάλιστα ἐκεῖνοι ὑποδοῦνται. τὰ μὲν γὰρ σμικρὰ ταῦτα τί χρὴ καὶ λέγειν ὅσα ἐπεδείκνυτο, ἔρωτας ἐπιπέμπων καὶ δαίμονας ἀνάγων καὶ νεκροὺς ἑώλους ἀνακαλῶν καὶ τὴν Ἑκάτην αὐτὴν ἐναργῆ παριστὰς καὶ τὴν Σελήνην καθαιρῶν;", "st": "31.13"}, {"sp": "N", "t": "ἐγὼ γοῦν διηγήσομαι ὑμῖν ἃ εἶδον γιγνόμενα ὑπ’ αὐτοῦ ἐν Γλαυκίου τοῦ Ἀλεξικλέους.", "st": "31.14"}, {"sp": "N", "t": "“ἄρτι γὰρ ὁ Γλαυκίας τοῦ πατρὸς ἀποθανόντος παραλαβὼν τὴν οὐσίαν ἠράσθη Χρυσίδος τῆς Δημέου γυναικός. ἐμοὶ δὲ διδασκάλῳ ἐχρῆτο πρὸς τοὺς λόγους, καὶ εἴ γε μὴ ὁ ἔρως ἐκεῖνος ἀπησχόλησεν αὐτόν, ἅπαντα ἂν ἤδη τὰ τοῦ Περιπάτου ἠπίστατο, ὃς καὶ ὀκτωκαιδεκαέτης ὢν ἀνέλυε καὶ τὴν φυσικὴν ἀκρόασιν μετεληλύθει εἰς τέλος. ἀμηχανῶν δὲ ὅμως τῷ ἔρωτι μηνύει μοι τὸ πᾶν, ἐγὼ δὲ ὥσπερ εἰκὸς ἦν, διδάσκαλον ὄντα, τὸν Ὑπερβόρεον ἐκεῖνον μάγον ἄγω παρ’ αὐτὸν ἐπὶ μναῖς τέτταρσι μὲν τὸ παραυτίκα — ἔδει γὰρ προτελέσαι τι εἰς τὰς θυσίας — ἑκκαίδεκα δέ, εἰ τύχοι τῆς Χρυσίδος. ὁ δὲ αὐξομένην τηρήσας τὴν σελήνην — τότε γὰρ ὡς ἐπὶ τὸ πολὺ τὰ τοιαῦτα τελεσιουργεῖται — βόθρον τε ὀρυξάμενος ἐν ὑπαίθρῳ τινὶ τῆς οἰκίας περὶ μέσας νύκτας ἀνεκάλεσεν ἡμῖν πρῶτον μὲν τὸν Ἀλεξικλέα τὸν πατέρα τοῦ Γλαυκίου πρὸ ἑπτὰ μηνῶν τεθνεῶτα· ἠγανάκτει δὲ ὁ γέρων ἐπὶ τῷ ἔρωτι καὶ ὠργίζετο, τὰ τελευταῖα δὲ ὅμως ἐφῆκεν αὐτῷ ἐρᾶν. μετὰ δὲ τὴν Ἑκάτην τε ἀνήγαγεν ἐπαγομένην τὸν Κέρβερον καὶ τὴν Σελήνην κατέσπασεν, πολύμορφόν τι θέαμα καὶ ἄλλοτε ἀλλοῖόν τι φανταζόμενον· τὸ μὲν γὰρ πρῶτον γυναικείαν μορφὴν ἐπεδείκνυτο, εἶτα βοῦς ἐγίγνετο πάγκαλος, εἶτα σκύλαξ ἐφαίνετο. τέλος δ’ οὖν ὁ Ὑπερβόρεος ἐκ πηλοῦ ἐρώτιόν τι ἀναπλάσας, Ἄπιθι, ἔφη, καὶ ἄγε Χρυσίδα. καὶ ὁ μὲν πηλὸς ἐξέπτατο, μετὰ μικρὸν δὲ ἐπέστη κόπτουσα τὴν θύραν ἐκείνη καὶ εἰσελθοῦσα περιβάλλει τὸν Γλαυκίαν ὡς ἂν ἐκμανέστατα ἐρῶσα καὶ συνῆν ἄχρι δὴ ἀλεκτρυόνων ἠκούσαμεν ᾀδόντων. τότε δὴ ἥ τε Σελήνη ἀνέπτατο εἰς τὸν οὐρανὸν καὶ ἡ Ἑκάτη ἔδυ κατὰ τῆς γῆς καὶ τὰ ἄλλα φάσματα ἠφανίσθη καὶ τὴν Χρυσίδα ἐξεπέμψαμεν περὶ αὐτό που σχεδὸν τὸ λυκαυγές.", "st": "31.14"}, {"sp": "N", "t": "εἰ ταῦτα εἶδες, ὦ Τυχιάδη, οὐκ ἂν ἔτι ἠπίστησας εἶναι πολλὰ ἐν ταῖς ἐπῳδαῖς χρήσιμα.”", "st": "31.15"}, {"sp": "N", "t": "“εὖ λέγεις,” ἦν δ’ ἐγώ· “ἐπίστευον γὰρ ἄν, εἴ γε εἶδον αὐτά, νῦν δὲ συγγνώμη, οἶμαι, εἰ μὴ τὰ ὅμοια ὑμῖν ὀξυδορκεῖν ἔχω. πλὴν ἀλλ’ οἶδα γὰρ τὴν Χρυσίδα ἣν λέγεις, ἐραστὴν γυναῖκα καὶ πρόχειρον, οὐχ ὁρῶ δὲ τίνος ἕνεκα ἐδεήθητε ἐπ’ αὐτὴν τοῦ πηλίνου πρεσβευτοῦ καὶ μάγου τοῦ ἐξ Ὑπερβορέων καὶ Σελήνης αὐτῆς, ἣν εἴκοσι δραχμῶν ἀγαγεῖν εἰς Ὑπερβορέους δυνατὸν ἦν. πάνυ γὰρ ἐνδίδωσιν πρὸς ταύτην τὴν ἐπῳδὴν ἡ γυνὴ καὶ τὸ ἐναντίον τοῖς φάσμασιν πέπονθεν· ἐκεῖνα μὲν γὰρ ἢν ψόφον ἀκούσῃ χαλκοῦ ἢ σιδήρου, πέφευγε — καὶ ταῦτα γὰρ ὑμεῖς φατε — αὕτη δὲ ἂν ἀργύριόν που ψοφῇ, ἔρχεται πρὸς τὸν ἦχον. ἄλλως τε καὶ αὐτοῦ θαυμάζω τοῦ μάγου, εἰ δυνάμενος αὐτὸς ἐρᾶσθαι πρὸς τῶν πλουσιωτάτων γυναικῶν καὶ τάλαντα ὅλα παρ’ αὐτῶν λαμβάνειν, ὁ δὲ τεττάρων μνῶν πάνυ σμικρολόγος ὢν Γλαυκίαν ἐπέραστον ἐργάζεται.”", "st": "31.15"}, {"sp": "N", "t": "“Γελοῖα ποιεῖς,” ἔφη ὁ Ἴων, “ἀπιστῶν ἅπασιν.", "st": "31.15"}, {"sp": "N", "t": "ἐγὼ γοῦν ἡδέως ἂν ἐροίμην σε, τί περὶ τούτων φὴς ὅσοι τοὺς δαιμονῶντας ἀπαλλάττουσι τῶν δειμάτων οὕτω σαφῶς ἐξᾴδοντες τὰ φάσματα. καὶ ταῦτα οὐκ ἐμὲ χρὴ λέγειν, ἀλλὰ πάντες ἴσασι τὸν Σύρον τὸν ἐκ τῆς Παλαιστίνης, τὸν ἐπὶ τούτῳ σοφιστήν, ὅσους παραλαβὼν καταπίπτοντας πρὸς τὴν σελήνην καὶ τὼ ὀφθαλμὼ διαστρέφοντας καὶ ἀφροῦ πιμπλαμένους τὸ στόμα ὅμως ἀνίστησι καὶ ἀποπέμπει ἀρτίους τὴν γνώμην, ἐπὶ μισθῷ μεγάλῳ ἀπαλλάξας τῶν δεινῶν. ἐπειδὰν γὰρ ἐπιστὰς κειμένοις ἔρηται ὅθεν εἰσεληλύθασιν εἰς τὸ σῶμα, ὁ μὲν νοσῶν αὐτὸς σιωπᾷ, ὁ δαίμων δὲ ἀποκρίνεται, ἑλληνίζων ἢ βαρβαρίζων ὁπόθεν ἂν αὐτὸς ᾖ, ὅπως τε καὶ ὅθεν εἰσῆλθεν εἰς τὸν ἄνθρωπον· ὁ δὲ ὅρκους ἐπάγων, εἰ δὲ μὴ πεισθείη, καὶ ἀπειλῶν ἐξελαύνει τὸν δαίμονα. ἐγὼ γοῦν καὶ εἶδον ἐξιόντα μέλανα καὶ καπνώδη τὴν χρόαν.” “οὐ μέγα,” ἦν δ’ ἐγώ, “τὰ τοιαῦτά σε ὁρᾶν, ὦ Ἴων, ᾧ γε καὶ αἱ ἰδέαι αὐταὶ φαίνονται ἃ ὁ πατὴρ ὑμῶν Πλάτων δείκνυσιν, ἀμαυρόν τι θέαμα ὡς πρὸς ἡμᾶς τοὺς ἀμβλυώττοντας.”", "st": "31.16"}, {"sp": "N", "t": "“μόνος γὰρ Ἴων,” ἔφη ὁ Εὐκράτης, “τὰ τοιαῦτα εἶδεν, οὐχὶ δὲ καὶ ἄλλοι πολλοὶ δαίμοσιν ἐντετυχήκασιν οἱ μὲν νύκτωρ, οἱ δὲ μεθ’ ἡμέραν; ἐγὼ δὲ οὐχ ἅπαξ ἀλλὰ μυριάκις ἤδη σχέδον τὰ τοιαῦτα τεθέαμαι· καὶ τὸ μὲν πρῶτον ἐταραττόμην πρὸς αὐτά, νῦν δὲ δὴ ὑπὸ τοῦ ἔθους οὐδέν τι παράλογον ὁρᾶν μοι δοκῶ, καὶ μάλιστα ἐξ οὗ μοι τὸν δακτύλιον ὁ Ἄραψ ἔδωκε σιδήρου τοῦ ἐκ τῶν σταυρῶν πεποιημένον καὶ τὴν ἐπῳδὴν ἐδίδαξεν τὴν πολυώνυμον, ἐκτὸς εἰ μὴ κἀμοὶ ἀπιστήσεις, ὦ Τυχιάδη.” “καὶ πῶς ἄν,” ἦν δ’ ἐγώ, “ἀπιστήσαιμι Εὐκράτει τῷ Δείνωνος, σοφῷ ἀνδρὶ καὶ μάλιστα ἐλευθερίῳ, τὰ δοκοῦντά οἱ λέγοντι οἴκοι παρ’ αὑτῷ ἐπ’ ἐξουσίας;”", "st": "31.17"}, {"sp": "N", "t": "“τὸ γοῦν περὶ τοῦ ἀνδριάντος,” ἦ δ’ ὃς ὁ Εὐκράτης, “ἅπασι τοῖς ἐπὶ τῆς οἰκίας ὅσαι νύκτες φαινόμενον καὶ παισὶ καὶ νεανίαις καὶ γέρουσι, τοῦτο οὐ παρ’ ἐμοῦ μόνον ἀκούσειας ἂν ἀλλὰ καὶ παρὰ τῶν ἡμετέρων ἁπάντων.” “ποίου,” ἦν δ’ ἐγώ, “ἀνδριάντος;”", "st": "31.18"}, {"sp": "N", "t": "“οὐχ ἑώρακας,” ἔφη, “εἰσιὼν ἐν τῇ αὐλῇ ἀνεστηκότα πάγκαλον ἀνδριάντα, Δημητρίου ἔργον τοῦ ἀνθρωποποιοῦ;” “μῶν τὸν δισκεύοντα,” ἦν δ’ ἐγώ, “φής, τὸν ἐπικεκυφότα κατὰ τὸ σχῆμα τῆς ἀφέσεως, ἀπεστραμμένον εἰς τὴν δισκοφόρον, ἠρέμα ὀκλάζοντα τῷ ἑτέρῳ, ἐοικότα συναναστησομένῳ μετὰ τῆς βολῆς;” “οὐκ ἐκεῖνον,” ἦ δ’ ὅς, “ἐπεὶ τῶν Μύρωνος ἔργων ἓν καὶ τοῦτό ἐστιν, ὁ δισκοβόλος ὃν λέγεις· οὐδὲ τὸν παρ’ αὐτόν φημι, τὸν διαδούμενον τὴν κεφαλὴν τῇ ταινίᾳ, τὸν καλόν, Πολυκλείτου γὰρ τοῦτο ἔργον. ἀλλὰ τοὺς μὲν ἐπὶ τὰ δεξιὰ εἰσιόντων ἄφες, ἐν οἷς καὶ τὰ Κριτίου καὶ Νησιώτου πλάσματα ἕστηκεν, οἱ τυραννοκτόνοι· σὺ δὲ εἴ τινα παρὰ τὸ ὕδωρ τὸ ἐπιρρέον εἶδες προγάστορα, φαλαντίαν, ἡμίγυμνον τὴν ἀναβολήν, ἠνεμωμένον τοῦ πώγωνος τὰς τρίχας ἐνίας, ἐπίσημον τὰς φλέβας, αὐτοανθρώπῳ ὅμοιον, ἐκεῖνον λέγω· Πέλλιχος ὁ Κορίνθιος στρατηγὸς εἶναι δοκεῖ.”", "st": "31.18"}, {"sp": "N", "t": "“νὴ Δί’,” ἦν δ’ ἐγώ, “εἶδόν τινα ἐπὶ δεξιὰ τοῦ κρουνοῦ, ταινίας καὶ στεφάνους ξηροὺς ἔχοντα, κατακεχρυσωμένον πετάλοις τὸ στῆθος.” “ἐγὼ δέ,” ὁ Εὐκράτης ἔφη, “ἐκεῖνα ἐχρύσωσα, ὁπότε μ’ ἰάσατο διὰ τρίτης ὑπὸ τοῦ ἠπιάλου ἀπολλύμενον.” “ἦ γὰρ καὶ ἰατρός,” ἦν δ’ ἐγώ, “ὁ βέλτιστος ἡμῖν Πέλλιχος οὗτός ἐστιν;” “μὴ σκῶπτε,” ἦ δ’ ὃς ὁ Εὐκράτης, “ἤ σε οὐκ εἰς μακρὰν μέτεισιν ὁ ἀνήρ· οἶδα ἐγὼ ὅσον δύναται οὗτος ὁ ὑπὸ σοῦ γελώμενος ἀνδριάς. ἢ οὐ νομίζεις τοῦ αὐτοῦ εἶναι καὶ ἐπιπέμπειν ἠπιάλους οἷς ἂν ἐθέλῃ, εἴ γε καὶ ἀποπέμπειν δυνατὸν αὐτῷ;” “ἵλεως,” ἦν δ’ ἐγώ, “ἔστω ὁ ἀνδριὰς καὶ ἤπιος οὕτως ἀνδρεῖος ὤν. τί δ’ οὖν καὶ ἄλλο ποιοῦντα ὁρᾶτε αὐτὸν ἅπαντες οἱ ἐν τῇ οἰκίᾳ;”", "st": "31.19"}, {"sp": "N", "t": "“ἐπειδὰν τάχιστα,” ἔφη, “νὺξ γένηται, ὁ δὲ καταβὰς ἀπὸ τῆς βάσεως ἐφ’ ᾗ ἕστηκε περίεισιν ἐν κύκλῳ τὴν οἰκίαν, καὶ πάντες ἐντυγχάνομεν αὐτῷ ἐνίοτε καὶ ᾄδοντι, καὶ οὐκ ἔστιν ὅντινα ἠδίκησεν· ἐκτρέπεσθαι γὰρ χρὴ μόνον· ὁ δὲ παρέρχεται μηδὲν ἐνοχλήσας τοὺς ἰδόντας. καὶ μὴν καὶ λούεται τὰ πολλὰ καὶ παίζει δι’ ὅλης τῆς νυκτός, ὥστε ἀκούειν τοῦ ὕδατος ψοφοῦντος.” “ὅρα τοίνυν,” ἦν δ’ ἐγώ, “μὴ οὐχὶ Πέλλιχος ὁ ἀνδριάς, ἀλλὰ Τάλως ὁ Κρὴς ὁ τοῦ Μίνωος ᾖ· καὶ γὰρ ἐκεῖνος χαλκοῦς τις ἦν τῆς Κρήτης περίπολος. εἰ δὲ μὴ χαλκοῦ, ὦ Εὔκρατες, ἀλλὰ ξύλου πεποίητο, οὐδὲν αὐτὸν ἐκώλυεν οὐ Δημητρίου ἔργον εἶναι, ἀλλὰ τῶν Δαιδάλου τεχνημάτων· δραπετεύει γοῦν, ὡς φής, ἀπὸ τῆς βάσεως καὶ οὗτος.”", "st": "31.19"}, {"sp": "N", "t": "“ὅρα,” ἔφη, “ὦ Τυχιάδη, μή σοι μεταμελήσῃ τοῦ σκώμματος ὕστερον. οἶδα ἐγὼ οἷα ἔπαθεν ὁ τοὺς ὀβολοὺς ὑφελόμενος οὓς κατὰ τὴν νουμηνίαν ἑκάστην τίθεμεν αὐτῷ.” “πάνδεινα ἐχρῆν,” ἔφη ὁ Ἴων, “ἱερόσυλόν γε ὄντα. πῶς δ’ οὖν αὐτὸν ἠμύνατο, ὦ Εὔκρατες; ἐθέλω γὰρ ἀκοῦσαι, εἰ καὶ ὅτι μάλιστα οὑτοσὶ Τυχιάδης ἀπιστήσει.”", "st": "31.20"}, {"sp": "N", "t": "“πολλοί,” ἦ δ’ ὅς, “ἔκειντο ὀβολοὶ πρὸ τοῖν ποδοῖν αὐτοῦ καὶ ἄλλα νομίσματα ἔνια ἀργυρᾶ πρὸς τὸν μηρὸν κηρῷ κεκολλημένα καὶ πέταλα ἐξ ἀργύρου, εὐχαί τινος ἢ μισθὸς ἐπὶ τῇ ἰάσει ὁπόσοι δι’ αὐτὸν ἐπαύσαντο πυρετῷ ἐχόμενοι. ἦν δὲ ἡμῖν Λίβυς τις οἰκέτης κατάρατος, ἱπποκόμος· οὗτος ἐπεχείρησε νυκτὸς ὑφελέσθαι πάντα ἐκεῖνα καὶ ὑφείλετο καταβεβηκότα ἤδη τηρήσας τὸν ἀνδριάντα. ἐπεὶ δὲ ἐπανελθὼν τάχιστα ἔγνω περισεσυλημένος ὁ Πέλλιχος, ὅρα ὅπως ἠμύνατο καὶ κατεφώρασε τὸν Λίβυν· δι’ ὅλης γὰρ τῆς νυκτὸς περιῄει ἐν κύκλῳ τὴν αὐλὴν ὁ ἄθλιος ἐξελθεῖν οὐ δυνάμενος ὥσπερ εἰς λαβύρινθον ἐμπεσών, ἄχρι δὴ κατελήφθη ἔχων τὰ φώρια γενομένης ἡμέρας. καὶ τότε μὲν πληγὰς οὐκ ὀλίγας ἔλαβεν ἁλούς, οὐ πολὺν δὲ ἐπιβιοὺς χρόνον κακὸς κακῶς ἀπέθανεν μαστιγούμενος, ὡς ἔλεγεν, κατὰ τὴν νύκτα ἑκάστην, ὥστε καὶ μώλωπας εἰς τὴν ἐπιοῦσαν φαίνεσθαι αὐτοῦ ἐπὶ τοῦ σώματος. πρὸς ταῦτα, ὦ Τυχιάδη, καὶ τὸν Πέλλιχον σκῶπτε κἀμὲ ὥσπερ τοῦ Μίνωος ἡλικιώτην παραπαίειν ἤδη δόκει.” “ἀλλ’, ὦ Εὔκρατες,” ἦν δ’ ἐγώ, “ἔστ’ ἂν χαλκὸς μὲν ὁ χαλκός, τὸ δὲ ἔργον Δημήτριος ὁ Ἀλωπεκῆθεν εἰργασμένος ᾖ, οὐ θεοποιός τις ἀλλ’ ἀνθρωποποιὸς ὤν, οὔποτε φοβήσομαι τὸν ἀνδριάντα Πελλίχου, ὃν οὐδὲ ζῶντα πάνυ ἐδεδίειν ἂν ἀπειλοῦντά μοι.”", "st": "31.20"}, {"sp": "N", "t": "ἐπὶ τούτοις Ἀντίγονος ὁ ἰατρὸς εἶπε, “κἀμοί, ὦ Εὔκρατες, Ἱπποκράτης ἐστὶ χαλκοῦς ὅσον πηχυαῖος τὸ μέγεθος· οὗτος ἐπειδὰν μόνον ἡ θρυαλλὶς ἀποσβῇ, περίεισιν τὴν οἰκίαν ὅλην ἐν κύκλῳ ψοφῶν καὶ τὰς πυξίδας ἀνατρέπων καὶ τὰ φάρμακα συγχέων καὶ τὴν θυίαν περιτρέπων, καὶ μάλιστα ἐπειδὰν τὴν θυσίαν ὑπερβαλώμεθα, ἣν κατὰ τὸ ἔτος ἕκαστον αὐτῷ θύομεν.” “ἀξιοῖ γάρ,” ἦν δ’ ἐγώ, “καὶ ὁ Ἱπποκράτης ἤδη ὁ ἰατρὸς θύεσθαι αὑτῷ, καὶ ἀγανακτεῖ ἢν μὴ κατὰ καιρὸν ἐφ’ ἱερῶν τελείων ἑστιαθῇ; ὃν ἔδει ἀγαπᾶν, εἴ τις ἐναγίσειεν αὐτῷ ἢ μελίκρατον ἐπισπείσειεν ἢ στεφανώσειε τὴν στήλην.”", "st": "31.21"}, {"sp": "N", "t": "“ἄκουε τοίνυν,” ἔφη ὁ Εὐκράτης, “— τοῦτο μὲν καὶ ἐπὶ μαρτύρων — ὃ πρὸ ἐτῶν πέντε εἶδον· ἐτύγχανε μὲν ἀμφὶ τρυγητὸν τοῦ ἔτους ὄν, ἐγὼ δὲ ἀνὰ τὸν ἀγρὸν μεσούσης ἡμέρας τρυγῶντας ἀφεὶς τοὺς ἐργάτας κατ’ ἐμαυτὸν εἰς τὴν ὕλην ἀπῄειν μεταξὺ φροντίζων τι καὶ ἀνασκοπούμενος. ἐπεὶ δ’ ἐν τῷ συνηρεφεῖ ἦν, τὸ μὲν πρῶτον ὑλαγμὸς ἐγένετο κυνῶν, κἀγὼ εἴκαζον Μνάσωνα τὸν υἱόν, ὥσπερ εἰώθει, παίζειν καὶ κυνηγετεῖν εἰς τὸ λάσιον μετὰ τῶν ἡλικιωτῶν παρελθόντα. τὸ δ’ οὐκ εἶχεν οὕτως, ἀλλὰ μετ’ ὀλίγον σεισμοῦ τινος ἅμα γενομένου καὶ βοῆς οἷον ἐκ βροντῆς γυναῖκα ὁρῶ προσιοῦσαν φοβεράν, ἡμισταδιαίαν σχεδὸν τὸ ὕψος. εἶχεν δὲ καὶ δᾷδα ἐν τῇ ἀριστερᾷ καὶ ξίφος ἐν τῇ δεξιᾷ ὅσον εἰκοσάπηχυ, καὶ τὰ μὲν ἔνερθεν ὀφιόπους ἦν, τὰ δὲ ἄνω Γοργόνι ἐμφερής, τὸ βλέμμα φημὶ καὶ τὸ φρικῶδες τῆς προσόψεως, καὶ ἀντὶ τῆς κόμης τοὺς δράκοντας βοστρυχηδὸν καθεῖτο εἰλουμένους περὶ τὸν αὐχένα καὶ ἐπὶ τῶν ὤμων ἐνίους ἐσπειραμένους. ὁρᾶτε,” ἔφη, “ὅπως ἔφριξα, ὦ φίλοι, μεταξὺ διηγούμενος.” καὶ ἅμα λέγων ἐδείκνυεν ὁ Εὐκράτης τὰς ἐπὶ τοῦ πήχεως τρίχας δῆθεν ὀρθὰς ὑπὸ τοῦ φόβου.", "st": "31.22"}, {"sp": "N", "t": "οἱ μὲν οὖν ἀμφὶ τὸν Ἴωνα καὶ τὸν Δεινόμαχον καὶ τὸν Κλεόδημον κεχηνότες ἀτενὲς προσεῖχον αὐτῷ, γέροντες ἄνδρες ἑλκόμενοι τῆς ῥινός, ἠρέμα προσκυνοῦντες οὕτως ἀπίθανον κολοσσόν, ἡμισταδιαίαν γυναῖκα, γιγάντειόν τι μορμολύκειον. ἐγὼ δὲ ἐνενόουν μεταξὺ οἷοι ὄντες αὐτοὶ νέοις τε ὁμιλοῦσιν ἐπὶ σοφίᾳ καὶ ὑπὸ πολλῶν θαυμάζονται, μόνῃ τῇ πολιᾷ καὶ τῷ πώγωνι διαφέροντες τῶν βρεφῶν, τὰ δ’ ἄλλα καὶ αὐτῶν ἐκείνων εὐαγωγότεροι πρὸς τὸ ψεῦδος.", "st": "31.23"}, {"sp": "N", "t": "ὁ γοῦν Δεινόμαχος, “εἰπέ μοι,” ἔφη, “ὦ Εὔκρατες, οἱ κύνες δὲ τῆς θεοῦ πηλίκοι τὸ μέγεθος ἦσαν;”", "st": "31.24"}, {"sp": "N", "t": "“ἐλεφάντων,” ἦ δ’ ὅς, “ὑψηλότεροι τῶν Ἰνδικῶν, μέλανες καὶ αὐτοὶ καὶ λάσιοι πιναρᾷ καὶ αὐχμώσῃ τῇ λάχνῃ. — ἐγὼ μὲν οὖν ἰδὼν ἔστην ἀναστρέψας ἅμα τὴν σφραγῖδα ἥν μοι ὁ Ἄραψ ἔδωκεν εἰς τὸ εἴσω τοῦ δακτύλου· ἡ Ἑκάτη δὲ πατάξασα τῷ δρακοντείῳ ποδὶ τοὔδαφος ἐποίησεν χάσμα παμμέγεθες, ἡλίκον Ταρτάρειον τὸ βάθος· εἶτα ᾤχετο μετ’ ὀλίγον ἁλλομένη εἰς αὐτό. ἐγὼ δὲ θαρρήσας ἐπέκυψα λαβόμενος δένδρου τινὸς πλησίον πεφυκότος, ὡς μὴ σκοτοδινιάσας ἐμπέσοιμι ἐπὶ κεφαλήν· εἶτα ἑώρων τὰ ἐν Ἅιδου ἅπαντα, τὸν Πυριφλεγέθοντα, τὴν λίμνην, τὸν Κέρβερον, τοὺς νεκρούς, ὥστε γνωρίζειν ἐνίους αὐτῶν· τὸν γοῦν πατέρα εἶδον ἀκριβῶς αὐτὰ ἐκεῖνα ἔτι ἀμπεχόμενον ἐν οἷς αὐτὸν κατεθάψαμεν.”", "st": "31.24"}, {"sp": "N", "t": "“τί δὲ ἔπραττον,” ὁ Ἴων ἔφη, “ὦ Εὔκρατες, αἱ ψυχαί;” “τί δ’ ἄλλο,” ἦ δ’ ὅς, “ἢ κατὰ φῦλα καὶ φρήτρας μετὰ τῶν φίλων καὶ συγγενῶν διατρίβουσιν ἐπὶ τοῦ ἀσφοδέλου κατακείμενοι.” “ἀντιλεγέτωσαν νῦν ἔτι,” ἦ δ’ ὃς ὁ Ἴων, “οἱ ἀμφὶ τὸν Ἐπίκουρον τῷ ἱερῷ Πλάτωνι καὶ τῷ περὶ τῶν ψυχῶν λόγῳ. σὺ δὲ μὴ καὶ τὸν Σωκράτην αὐτὸν καὶ τὸν Πλάτωνα εἶδες ἐν τοῖς νεκροῖς;” “τὸν Σωκράτην ἔγωγε,” ἦ δ’ ὅς, “οὐδὲ τοῦτον σαφῶς, ἀλλὰ εἰκάζων ὅτι φαλακρὸς καὶ προγάστωρ ἦν· τὸν Πλάτωνα δὲ οὐκ ἐγνώρισα· χρὴ γάρ, οἶμαι, πρὸς φίλους ἄνδρας τἀληθῆ λέγειν.”", "st": "31.24"}, {"sp": "N", "t": "“ἅμα δ’ οὖν ἐγώ τε ἅπαντα ἱκανῶς ἑωράκειν, καὶ τὸ χάσμα συνῄει καὶ συνέμυε· καί τινες τῶν οἰκετῶν ἀναζητοῦντές με, καὶ Πυρρίας οὗτος ἐν αὐτοῖς, ἐπέστησαν οὔπω τέλεον μεμυκότος τοῦ χάσματος. εἰπέ, Πυρρία, εἰ ἀληθῆ λέγω.” “νὴ Δί’,” ἔφη ὁ Πυρρίας, “καὶ ὑλακῆς δὲ ἤκουσα διὰ τοῦ χάσματος καὶ πῦρ τι ὑπέλαμπεν, ἀπὸ τῆς δᾳδός μοι δοκεῖν.” κἀγὼ ἐγέλασα ἐπιμετρήσαντος τοῦ μάρτυρος τὴν ὑλακὴν καὶ τὸ πῦρ.", "st": "31.24"}, {"sp": "N", "t": "ὁ Κλεόδημος δέ, “οὐ καινά,” εἶπεν, “οὐδὲ ἄλλοις ἀόρατα ταῦτα εἶδες, ἐπεὶ καὶ αὐτὸς οὐ πρὸ πολλοῦ νοσήσας τοιόνδε τι ἐθεασάμην· ἐπεσκόπει δέ με καὶ ἐθεράπευεν Ἀντίγονος οὗτος. ἑβδόμη μὲν ἦν ἡμέρα, ὁ δὲ πυρετὸς οἷος καῦσος σφοδρότατος. ἅπαντες δέ με ἀπολιπόντες ἐπ’ ἐρημίας ἐπικλεισάμενοι τὰς θύρας ἔξω περιέμενον· οὕτω γὰρ αὐτὸς ἐκέλευσας, ὦ Ἀντίγονε, εἴ πως δυνηθείην εἰς ὕπνον τραπέσθαι. τότε οὖν ἐφίσταταί μοι νεανίας ἐγρηγορότι πάγκαλος λευκὸν ἱμάτιον περιβεβλημένος, εἶτα ἀναστήσας ἄγει διά τινος χάσματος εἰς τὸν Ἅιδην, ὡς αὐτίκα ἐγνώρισα Τάνταλον ἰδὼν καὶ Τιτυὸν καὶ Σίσυφον. καὶ τὰ μὲν ἄλλα τί ἂν ὑμῖν λέγοιμι; ἐπεὶ δὲ κατὰ τὸ δικαστήριον ἐγενόμην — παρῆν δὲ καὶ ὁ Αἰακὸς καὶ ὁ Χάρων καὶ αἱ Μοῖραι καὶ αἱ Ἐρινύες — ὁ μέν τις ὥσπερ βασιλεὺς (ὁ Πλούτων, μοι δοκεῖ) καθῆστο ἐπιλεγόμενος τῶν τεθνηξομένων τὰ ὀνόματα, οὓς ἤδη ὑπερημέρους τῆς ζωῆς συνέβαινεν εἶναι. ὁ δὲ νεανίσκος ἐμὲ φέρων παρέστησεν αὐτῷ· ὁ δὲ Πλούτων ἠγανάκτησέν τε καὶ πρὸς τὸν ἀγαγόντα με, ‘οὔπω πεπλήρωται,’ φησίν, ‘τὸ νῆμα αὐτῷ, ὥστε ἀπίτω. σὺ δὲ δὴ τὸν χαλκέα Δημύλον ἄγε· ὑπὲρ γὰρ τὸν ἄτρακτον βιοῖ.’ κἀγὼ ἄσμενος ἀναδραμὼν αὐτὸς μὲν ἤδη ἀπύρετος ἦν, ἀπήγγελλον δὲ ἅπασιν ὡς τεθνήξεται Δημύλος· ἐν γειτόνων δὲ ἡμῖν ᾤκει νοσῶν τι καὶ αὐτός, ὡς ἀπηγγέλλετο. καὶ μετὰ μικρὸν ἠκούομεν οἰμωγῆς ὀδυρομένων ἐπ’ αὐτῷ.”", "st": "31.25"}, {"sp": "N", "t": "“τί θαυμαστόν;” εἶπεν ὁ Ἀντίγονος· “ἐγὼ γὰρ οἶδά τινα μετὰ εἰκοστὴν ἡμέραν ἧς ἐτάφη ἀναστάντα, θεραπεύσας καὶ πρὸ τοῦ θανάτου καὶ ἐπεὶ ἀνέστη τὸν ἄνθρωπον.” “καὶ πῶς,” ἦν δ’ ἐγώ, “ἐν εἴκοσιν ἡμέραις οὔτ’ ἐμύδησεν τὸ σῶμα οὔτε ἄλλως ὑπὸ λιμοῦ διεφθάρη; εἰ μή τινα Ἐπιμενίδην σύ γε ἐθεράπευες.”", "st": "31.26"}, {"sp": "N", "t": "ἅμα ταῦτα λεγόντων ἡμῶν ἐπεισῆλθον οἱ τοῦ Εὐκράτους υἱοὶ ἐκ τῆς παλαίστρας, ὁ μὲν ἤδη ἐξ ἐφήβων, ὁ δὲ ἕτερος ἀμφὶ τὰ πεντεκαίδεκα ἔτη, καὶ ἀσπασάμενοι ἡμᾶς ἐκαθέζοντο ἐπὶ τῆς κλίνης παρὰ τῷ πατρί· ἐμοὶ δὲ εἰσεκομίσθη θρόνος. καὶ ὁ Εὐκράτης ὥσπερ ἀναμνησθεὶς πρὸς τὴν ὄψιν τῶν υἱέων, “οὕτως ὀναίμην,” ἔφη, “τούτων —” ἐπιβαλὼν αὐτοῖν τὴν χεῖρα — “ἀληθῆ, ὦ Τυχιάδη, πρός σε ἐρῶ. τὴν μακαρῖτίν μου γυναῖκα τὴν τούτων μητέρα πάντες ἴσασιν ὅπως ἠγάπησα, ἐδήλωσα δὲ οἷς περὶ αὐτὴν ἔπραξα οὐ ζῶσαν μόνον, ἀλλὰ καὶ ἐπεὶ ἀπέθανεν, τόν τε κόσμον ἅπαντα συγκατακαύσας καὶ τὴν ἐσθῆτα ᾗ ζῶσα ἔχαιρεν. ἑβδόμῃ δὲ μετὰ τὴν τελευτὴν ἡμέρᾳ ἐγὼ μὲν ἐνταῦθα ἐπὶ τῆς κλίνης ὥσπερ νῦν ἐκείμην παραμυθούμενος τὸ πένθος· ἀνεγίγνωσκον γὰρ τὸ περὶ ψυχῆς τοῦ Πλάτωνος βιβλίον ἐφ’ ἡσυχίας· ἐπεισέρχεται δὲ μεταξὺ ἡ Δημαινέτη αὐτὴ ἐκείνη καὶ καθίζεται πλησίον ὥσπερ νῦν Εὐκρατίδης οὑτοσί,” δείξας τὸν νεώτερον τῶν υἱέων· ὁ δὲ αὐτίκα ἔφριξε μάλα παιδικῶς, καὶ πάλαι ἤδη ὠχρὸς ὢν πρὸς τὴν διήγησιν. “ἐγὼ δέ,” ἦ δ’ ὃς ὁ Εὐκράτης, “ὡς εἶδον, περιπλακεὶς αὐτῇ ἐδάκρυον ἀνακωκύσας· ἡ δὲ οὐκ εἴα βοᾶν, ἀλλ’ ᾐτιᾶτό με ὅτι τὰ ἄλλα πάντα χαρισάμενος αὐτῇ θάτερον τοῖν σανδάλοιν χρυσοῖν ὄντοιν οὐ κατακαύσαιμι, εἶναι δὲ αὐτὸ ἔφασκεν ὑπὸ τῇ κιβωτῷ παραπεσόν. καὶ διὰ τοῦτο ἡμεῖς οὐχ εὑρόντες θάτερον μόνον ἐκαύσαμεν. ἔτι δὲ ἡμῶν διαλεγομένων κατάρατόν τι κυνίδιον ὑπὸ τῇ κλίνῃ ὂν Μελιταῖον ὑλάκτησεν, ἡ δὲ ἠφανίσθη πρὸς τὴν ὑλακήν. τὸ μέντοι σανδάλιον εὑρέθη ὑπὸ τῇ κιβωτῷ καὶ κατεκαύθη ὕστερον.”", "st": "31.27"}, {"sp": "N", "t": "“ἔτι ἀπιστεῖν τούτοις, ὦ Τυχιάδη, ἄξιον ἐναργέσιν οὖσιν καὶ κατὰ τὴν ἡμέραν ἑκάστην φαονομένοις;” “μὰ Δί’,” ἦν δ’ ἐγώ· “ἐπεὶ σανδάλῳ γε χρυσῷ εἰς τὰς πυγὰς ὥσπερ τὰ παιδία παίεσθαι ἄξιοι ἂν εἶεν οἱ ἀπιστοῦντες καὶ οὕτως ἀναισχυντοῦντες πρὸς τὴν ἀλήθειαν.”", "st": "31.28"}, {"sp": "N", "t": "ἐπὶ τούτοις ὁ Πυθαγορικὸς Ἀρίγνωτος εἰσῆλθεν, ὁ κομήτης, ὁ σεμνὸς ἀπὸ τοῦ προσώπου, οἶσθα τὸν ἀοίδιμον ἐπὶ τῇ σοφίᾳ, τὸν ἱερὸν ἐπονομαζόμενον. κἀγὼ μὲν ὡς εἶδον αὐτὸν ἀνέπνευσα, τοῦτ’ ἐκεῖνο ἥκειν μοι νομίσας πέλεκύν τινα κατὰ τῶν ψευσμάτων. “ἐπιστομιεῖ γὰρ αὐτούς,” ἔλεγον, “ὁ σοφὸς ἀνὴρ οὕτω τεράστια διεξιόντας.” καὶ τὸ τοῦ λόγου, θεὸν ἀπὸ μηχανῆς ἐπεισκυκληθῆναί μοι τοῦτον ᾤμην ὑπὸ τῆς Τύχης· ὁ δὲ ἐπεὶ ἐκαθέζετο ὑπεκστάντος αὐτῷ τοῦ Κλεοδήμου, πρῶτα μὲν περὶ τῆς νόσου ἤρετο, καὶ ὡς ῥᾷον ἤδη ἔχειν ἤκουσεν παρὰ τοῦ Εὐκράτους, “τί δέ,” ἔφη, “πρὸς αὑτοὺς ἐφιλοσοφεῖτε; μεταξὺ γὰρ εἰσιὼν ἐπήκουσα, καί μοι ἐδοκεῖτε εἰς καλὸν διατεθήσεσθαι τὴν διατριβήν.”", "st": "31.29"}, {"sp": "N", "t": "“τί δ’ ἄλλο,” εἶπεν ὁ Εὐκράτης, “ἢ τουτονὶ τὸν ἀδαμάντινον πείθομεν” — δείξας ἐμέ — “ἡγεῖσθαι δαίμονάς τινας εἶναι καὶ φάσματα καὶ νεκρῶν ψυχὰς περιπολεῖν ὑπὲρ γῆς καὶ φαίνεσθαι οἷς ἂν ἐθέλωσιν.” ἐγὼ μὲν οὖν ἠρυθρίασα καὶ κάτω ἔνευσα αἰδεσθεὶς τὸν Ἀρίγνωτον. ὁ δὲ, “ὅρα,” ἔφη, “ὦ Εὔκρατες, μὴ τοῦτό φησιν Τυχιάδης, τὰς τῶν βιαίως ἀποθανόντων μόνας ψυχὰς περινοστεῖν, οἷον εἴ τις ἀπήγξατο ἢ ἀπετμήθη τὴν κεφαλὴν ἢ ἀνεσκολοπίσθη ἢ ἄλλῳ γέ τῳ τρόπῳ τοιούτῳ ἀπῆλθεν ἐκ τοῦ βίου, τὰς δὲ τῶν κατὰ μοῖραν ἀποθανόντων οὐκέτι· ἢν γὰρ τοῦτο λέγῃ, οὐ πάνυ ἀπόβλητα φήσει.” “μὰ Δί’,” ἦ δ’ ὃς ὁ Δεινόμαχος, “ἀλλ’ οὐδὲ ὅλως εἶναι τὰ τοιαῦτα οὐδὲ συνεστῶτα ὁρᾶσθαι οἴεται.”", "st": "31.29"}, {"sp": "N", "t": "“πῶς λέγεις,” ἦ δ’ ὃς ὁ Ἀρίγνωτος, δριμὺ ἀπιδὼν εἰς ἐμέ, “οὐδέν σοι τούτων γίγνεσθαι δοκεῖ, καὶ ταῦτα πάντων, ὡς εἰπεῖν, ὁρώντων;” “ἀπολόγησαι,” ἦν δ’ ἐγώ, “ὑπὲρ ἐμοῦ, εἰ μὴ πιστεύω, διότι μηδὲ ὁρῶ μόνος τῶν ἄλλων· εἰ δὲ ἑώρων, καὶ ἐπίστευον ἂν δηλαδὴ ὥσπερ ὑμεῖς.” “ἀλλά,” ἦ δ’ ὅς, “ἤν ποτε εἰς Κόρινθον ἔλθῃς, ἐροῦ ἔνθα ἐστὶν ἡ Εὐβατίδου οἰκία, καὶ ἐπειδάν σοι δειχθῇ παρὰ τὸ Κράνειον, παρελθὼν εἰς αὐτὴν λέγε πρὸς τὸν θυρωρὸν Τίβειον ὡς ἐθέλοις ἰδεῖν ὅθεν τὸν δαίμονα ὁ Πυθαγορικὸς Ἀρίγνωτος ἀνορύξας ἀπήλασε καὶ πρὸς τὸ λοιπὸν οἰκεῖσθαι τὴν οἰκίαν ἐποίησεν.”", "st": "31.30"}, {"sp": "N", "t": "“τί δὲ τοῦτο ἦν, ὦ Ἀρίγνωτε;” ἤρετο ὁ Εὐκράτης. “ἀοίκητος ἦν,” ἦ δ’ ὅς, “ἐκ πολλοῦ ὑπὸ δειμάτων, εἰ δέ τις οἰκήσειεν εὐθὺς ἐκπλαγεὶς ἔφευγεν, ἐκδιωχθεὶς ὑπό τινος φοβεροῦ καὶ ταραχώδους φάσματος. συνέπιπτεν οὖν ἤδη καὶ ἡ στέγη κατέρρει, καὶ ὅλως οὐδεὶς ἦν ὁ θαρρήσων παρελθεῖν εἰς αὐτήν.", "st": "31.31"}, {"sp": "N", "t": "ἐγὼ δὲ ἐπεὶ ταῦτα ἤκουσα, τὰς βίβλους λαβὼν — εἰσὶ δέ μοι Αἰγύπτιαι μάλα πολλαὶ περὶ τῶν τοιούτων — ἧκον εἰς τὴν οἰκίαν περὶ πρῶτον ὕπνον ἀποτρέποντος τοῦ ξένου καὶ μόνον οὐκ ἐπιλαμβανομένου, ἐπεὶ ἔμαθεν οἷ βαδίζοιμι, εἰς προὖπτον κακόν, ὡς ᾤετο. ἐγὼ δὲ λύχνον λαβὼν μόνος εἰσέρχομαι, καὶ ἐν τῷ μεγίστῳ οἰκήματι καταθεὶς τὸ φῶς ἀνεγίγνωσκον ἡσυχῇ χαμαὶ καθεζόμενος· ἐφίσταται δὲ ὁ δαίμων ἐπί τινα τῶν πολλῶν ἥκειν νομίζων καὶ δεδίξεσθαι κἀμὲ ἐλπίζων ὥσπερ τοὺς ἄλλους, αὐχμηρὸς καὶ κομήτης καὶ μελάντερος τοῦ ζόφου. καὶ ὁ μὲν ἐπιστὰς ἐπειρᾶτό μου, πανταχόθεν προσβάλλων εἴ ποθεν κρατήσειεν, καὶ ἄρτι μὲν κύων ἄρτι δὲ ταῦρος γιγνόμενος ἢ λέων. ἐγὼ δὲ προχειρισάμενος τὴν φρικωδεστάτην ἐπίρρησιν αἰγυπτιάζων τῇ φωνῇ συνήλασα κατᾴδων αὐτὸν εἴς τινα γωνίαν σκοτεινοῦ οἰκήματος· ἰδὼν δὲ αὐτὸν οἷ κατέδυ, τὸ λοιπὸν ἀνεπαυόμην.", "st": "31.31"}, {"sp": "N", "t": "ἕωθεν δὲ πάντων ἀπεγνωκότων καὶ νεκρὸν εὑρήσειν με οἰομένων καθάπερ τοὺς ἄλλους, προελθὼν ἀπροσδόκητος ἅπασι πρόσειμι τῷ Εὐβατίδῃ, εὖ ἀγγέλλων ὅτι καθαρὰν αὐτῷ καὶ ἀδείμαντον ἤδη ἐξῆν τὴν οἰκίαν οἰκεῖν. παραλαβὼν οὖν αὐτόν τε καὶ τῶν ἄλλων πολλοὺς — εἵποντο γὰρ τοῦ παραδόξου ἕνεκα — ἐκέλευον ἀγαγὼν ἐπὶ τὸν τόπον οὗ καταδεδυκότα τὸν δαίμονα ἑωράκειν, σκάπτειν λαβόντας δικέλλας καὶ σκαφεῖα, καὶ ἐπειδὴ ἐποίησαν, εὑρέθη ὅσον ἐπ’ ὀργυιὰν κατορωρυγμένος τις νεκρὸς ἕωλος μόνα τὰ ὀστᾶ κατὰ σχῆμα συγκείμενος. ἐκεῖνον μὲν οὖν ἐθάψαμεν ἀνορύξαντες, ἡ οἰκία δὲ τὸ ἀπ’ ἐκείνου ἐπαύσατο ἐνοχλουμένη ὑπὸ τῶν φασμάτων.”", "st": "31.31"}, {"sp": "N", "t": "ὡς δὲ ταῦτα εἶπεν ὁ Ἀρίγνωτος, ἀνὴρ δαιμόνιος τὴν σοφίαν καὶ ἅπασιν αἰδέσιμος, οὐδεὶς ἦν ἔτι τῶν παρόντων ὃς οὐχὶ κατεγίγνωσκέ μου πολλὴν τὴν ἄνοιαν τοῖς τοιούτοις ἀπιστοῦντος, καὶ ταῦτα Ἀριγνώτου λέγοντος. ἐγὼ δὲ ὅμως οὐδὲν τρέσας οὔτε τὴν κόμην οὔτε τὴν δόξαν τὴν περὶ αὐτοῦ, “τί τοῦτ’,” ἔφην, “ὦ Ἀρίγνωτε; καὶ σὺ τοιοῦτος ἦσθα, ἡ μόνη ἐλπὶς τῆς ἀληθείας — καπνοῦ μεστὸς καὶ ἰνδαλμάτων; τὸ γοῦν τοῦ λόγου ἐκεῖνο, ἄνθρακες ἡμῖν ὁ θησαυρὸς πέφηνε.”", "st": "31.32"}, {"sp": "N", "t": "“σὺ δέ,” ἦ δ’ ὃς ὁ Ἀρίγνωτος, “εἰ μήτε ἐμοὶ πιστεύεις μήτε Δεινομάχῳ ἢ Κλεοδήμῳ τουτωῒ μήτε αὐτῷ Εὐκράτει, φέρε εἰπὲ τίνα περὶ τῶν τοιούτων ἀξιοπιστότερον ἡγῇ τἀναντία ἡμῖν λέγοντα;” “νὴ Δί’,” ἦν δ’ ἐγώ, “μάλα θαυμαστὸν ἄνδρα τὸν Ἀβδηρόθεν ἐκεῖνον Δημόκριτον, ὃς οὕτως ἄρα ἐπέπειστο μηδὲν οἷόν τε εἶναι συστῆναι τοιοῦτον ὥστε, ἐπειδὴ καθείρξας ἑαυτὸν εἰς μνῆμα ἔξω πυλῶν ἐνταῦθα διετέλει γράφων καὶ συντάττων καὶ νύκτωρ καὶ μεθ’ ἡμέραν, καί τινες τῶν νεανίσκων ἐρεσχελεῖν αὐτὸν βουλόμενοι καὶ δειματοῦν στειλάμενοι νεκρικῶς ἐσθῆτι μελαίνῃ καὶ προσωπείοις εἰς τὰ κρανία μεμιμημένοις περιστάντες αὐτὸν περιεχόρευον ὑπὸ πυκνῇ τῇ βάσει ἀναπηδῶντες, ὁ δὲ οὔτε ἔδεισεν τὴν προσποίησιν αὐτῶν οὔτε ὅλως ἀνέβλεψεν πρὸς αὐτούς, ἀλλὰ μεταξὺ γράφων, ‘παύσασθε,’ ἔφη, ‘παίζοντες·’ οὕτω βεβαίως ἐπίστευε μηδὲν εἶναι τὰς ψυχὰς ἔτι ἔξω γενομένας τῶν σωμάτων.”", "st": "31.32"}, {"sp": "N", "t": "“τοῦτο φής,” ἦ δ’ ὃς ὁ Εὐκράτης, “ἀνόητόν τινα ἄνδρα καὶ τὸν Δημόκριτον γενέσθαι, εἴ γε οὕτως ἐγίγνωσκεν.", "st": "31.32"}, {"sp": "N", "t": "ἐγὼ δὲ ὑμῖν καὶ ἄλλο διηγήσομαι αὐτὸς παθών, οὐ παρ’ ἄλλου ἀκούσας· τάχα γὰρ ἂν καὶ σύ, ὦ Τυχιάδη, ἀκούων προσβιβασθείης πρὸς τὴν ἀλήθειαν τῆς διηγήσεως.", "st": "31.33"}, {"sp": "N", "t": "ὁπότε γὰρ ἐν Αἰγύπτῳ διῆγον ἔτι νέος ὤν, ὑπὸ τοῦ πατρὸς ἐπὶ παιδείας προφάσει ἀποσταλείς, ἐπεθύμησα εἰς Κοπτὸν ἀναπλεύσας ἐκεῖθεν ἐπὶ τὸν Μέμνονα ἐλθὼν ἀκοῦσαι τὸ θαυμαστὸν ἐκεῖνο ἠχοῦντα πρὸς ἀνίσχοντα τὸν ἥλιον. ἐκείνου μὲν οὖν ἤκουσα οὐ κατὰ τὸ κοινὸν τοῖς πολλοῖς ἄσημόν τινα φωνήν, ἀλλά μοι καὶ ἔχρησεν ὁ Μέμνων αὐτὸς ἀνοίξας γε τὸ στόμα ἐν ἔπεσιν ἑπτά, καὶ εἴ γε μὴ περιττὸν ἦν, αὐτὰ ἂν ὑμῖν εἶπον τὰ ἔπη.", "st": "31.33"}, {"sp": "N", "t": "κατὰ δὲ τὸν ἀνάπλουν ἔτυχεν ἡμῖν συμπλέων Μεμφίτης ἀνὴρ τῶν ἱερῶν γραμματέων, θαυμάσιος τὴν σοφίαν καὶ τὴν παιδείαν πᾶσαν εἰδὼς τὴν Αἰγύπτιον· ἐλέγετο δὲ τρία καὶ εἴκοσιν ἔτη ἐν τοῖς ἀδύτοις ὑπόγειος ᾠκηκέναι μαγεύειν παιδευόμενος ὑπὸ τῆς Ἴσιδος.”", "st": "31.34"}, {"sp": "N", "t": "“Παγκράτην,” ἔφη ὁ Ἀρίγνωτος, “λέγεις ἐμὸν διδάσκαλον, ἄνδρα ἱερόν, ἐξυρημένον, ἐν ὀθονίοις, ἀεὶ νοήμονα, οὐ καθαρῶς ἑλληνίζοντα, ἐπιμήκη, σιμόν, πρόχειλον, ὑπόλεπτον τὰ σκέλη.” “αὐτόν,” ἦ δ’ ὅς, “ἐκεῖνον τὸν Παγκράτην· καὶ τὰ μὲν πρῶτα ἠγνόουν ὅστις ἦν, ἐπεὶ δὲ ἑώρων αὐτὸν εἴ ποτε ὁρμίσαιμεν τὸ πλοῖον ἄλλα τε πολλὰ τεράστια ἐργαζόμενον, καὶ δὴ καὶ ἐπὶ κροκοδείλων ὀχούμενον καὶ συννέοντα τοῖς θηρίοις, τὰ δὲ ὑποπτήσσοντα καὶ σαίνοντα ταῖς οὐραῖς, ἔγνων ἱερόν τινα ἄνθρωπον ὄντα, κατὰ μικρὸν δὲ φιλοφρονούμενος ἔλαθον ἑταῖρος αὐτῷ καὶ συνήθης γενόμενος, ὥστε πάντων ἐκοινώνει μοι τῶν ἀπορρήτων.", "st": "31.34"}, {"sp": "N", "t": "καὶ τέλος πείθει με τοὺς μὲν οἰκέτας ἅπαντας ἐν τῇ Μέμφιδι καταλιπεῖν, αὐτὸν δὲ μόνον ἀκολουθεῖν μετ’ αὐτοῦ, μὴ γὰρ ἀπορήσειν ἡμᾶς τῶν διακονησομένων· καὶ τὸ μετὰ τοῦτο οὕτω διήγομεν.", "st": "31.34"}, {"sp": "N", "t": "ἐπειδὴ δὲ ἔλθοιμεν εἴς τι καταγώγιον, λαβὼν ἂν ὁ ἀνὴρ ἢ τὸν μοχλὸν τῆς θύρας ἢ τὸ κόρηθρον ἢ καὶ τὸ ὕπερον περιβαλὼν ἱματίοις ἐπειπών τινα ἐπῳδὴν ἐποίει βαδίζειν, τοῖς ἄλλοις ἅπασιν ἄνθρωπον εἶναι δοκοῦντα. τὸ δὲ ἀπιὸν ὕδωρ τε ἐμπίπλη καὶ ὠψώνει καὶ ἐσκεύαζεν καὶ πάντα δεξιῶς ὑπηρέτει καὶ διηκονεῖτο ἡμῖν· εἶτα ἐπειδὴ ἅλις ἔχοι τῆς διακονίας, αὖθις κόρηθρον τὸ κόρηθρον ἢ ὕπερον τὸ ὕπερον ἄλλην ἐπῳδὴν ἐπειπὼν ἐποίει ἄν.", "st": "31.35"}, {"sp": "N", "t": "τοῦτο ἐγὼ πάνυ ἐσπουδακὼς οὐκ εἶχον ὅπως ἐκμάθοιμι παρ’ αὐτοῦ· ἐβάσκαινε γάρ, καίτοι πρὸς τὰ ἄλλα προχειρότατος ὤν. μιᾷ δέ ποτε ἡμέρᾳ λαθὼν ἐπήκουσα τῆς ἐπῳδῆς, ἦν δὲ τρισύλλαβος σχεδόν, ἐν σκοτεινῷ ὑποστάς. καὶ ὁ μὲν ᾤχετο εἰς τὴν ἀγορὰν ἐντειλάμενος τῷ ὑπέρῳ ἃ ἔδει ποιεῖν.”", "st": "31.35"}, {"sp": "N", "t": "ἐγὼ δὲ εἰς τὴν ὑστεραίαν ἐκείνου τι κατὰ τὴν ἀγορὰν πραγματευομένου λαβὼν τὸ ὕπερον σχηματίσας ὁμοίως, ἐπειπὼν τὰς συλλαβάς, ἐκέλευσα ὑδροφορεῖν. ἐπεὶ δὲ ἐμπλησάμενον τὸν ἀμφορέα ἐκόμισε, “πέπαυσο,” ἔφην, “καὶ μηκέτι ὑδροφόρει, ἀλλ’ ἴσθι αὖθις ὕπερον· τὸ δὲ οὐκέτι μοι πείθεσθαι ἤθελεν, ἀλλ’ ὑδροφόρει ἀεί, ἄχρι δὴ ἐνέπλησεν ἡμῖν ὕδατος τὴν οἰκίαν ἐπαντλοῦν. ἐγὼ δὲ ἀμηχανῶν τῷ πράγματι — ἐδεδίειν γὰρ μὴ ὁ Παγκράτης ἐπανελθὼν ἀγανακτήσῃ, ὅπερ καὶ ἐγένετο — ἀξίνην λαβὼν διακόπτω τὸ ὕπερον εἰς δύο μέρη· τὰ δέ, ἑκάτερον τὸ μέρος, ἀμφορέας λαβόντα ὑδροφόρει καὶ ἀνθ’ ἑνὸς δύο μοι ἐγεγένηντο οἱ διάκονοι. ἐν τούτῳ καὶ ὁ Παγκράτης ἐφίσταται καὶ συνεὶς τὸ γενόμενον ἐκεῖνα μὲν αὖθις ἐποίησε ξύλα, ὥσπερ ἦν πρὸ τῆς ἐπῳδῆς, αὐτὸς δὲ ἀπολιπών με λαθὼν οὐκ οἶδ’ ὅποι ἀφανὴς ᾤχετο ἀπιών.”", "st": "31.36"}, {"sp": "N", "t": "“νῦν οὖν,” ἔφη ὁ Δεινόμαχος, “οἶσθα κἂν ἐκεῖνο, ἄνθρωπον ποιεῖν ἐκ τοῦ ὑπέρου;” “νὴ Δί’, ἦ δ’ ὅς, ἐξ ἡμισείας γε· οὐκέτι γὰρ εἰς τὸ ἀρχαῖον οἷόν τέ μοι ἀπάγειν αὐτό, ἢν ἅπαξ γένηται ὑδροφόρος, ἀλλὰ δεήσει ἡμῖν ἐπικλυσθῆναι τὴν οἰκίαν ἐπαντλουμένην.”", "st": "31.36"}, {"sp": "N", "t": "“οὐ παύσεσθε,” ἦν δ’ ἐγώ, “τὰ τοιαῦτα τερατολογοῦντες γέροντες ἄνδρες; εἰ δὲ μή, ἀλλὰ κἂν τούτων γε τῶν μειρακίων ἕνεκα εἰς ἄλλον τινὰ καιρὸν ὑπερβάλλεσθε τὰς παραδόξους ταύτας καὶ φοβερὰς διηγήσεις, μή πως λάθωσιν ἡμῖν ἐμπλησθέντες δειμάτων καὶ ἀλλοκότων μυθολογημάτων. φείδεσθαι οὖν χρὴ αὐτῶν μηδὲ τοιαῦτα ἐθίζειν ἀκούειν, ἃ διὰ παντὸς τοῦ βίου συνόντα ἐνοχλήσει καὶ ψοφοδεεῖς ποιήσει ποικίλης τῆς δεισιδαιμονίας ἐμπιπλάντα,”", "st": "31.37"}, {"sp": "N", "t": "“εὖ γε ὑπέμνησας,” ἦ δ’ ὃς ὁ Εὐκράτης, “εἰπὼν τὴν δεισιδαιμονίαν. τί γάρ σοι, ὦ Τυχιάδη, περὶ τῶν τοιούτων δοκεῖ, λέγω δὴ χρησμῶν καὶ θεσφάτων καὶ ὅσα θεοφορούμενοί τινες ἀναβοῶσιν ἢ ἐξ ἀδύτων ἀκούεται ἢ παρθένος ἔμμετρα φθεγγομένη προθεσπίζει τὰ μέλλοντα; ἢ δηλαδὴ καὶ τοῖς τοιούτοις ἀπιστήσεις; ἐγὼ δὲ ὅτι μὲν καὶ δακτύλιόν τινα ἱερὸν ἔχω Ἀπόλλωνος τοῦ Πυθίου εἰκόνα ἐκτυποῦντα τὴν σφραγῖδα καὶ οὗτος ὁ Ἀπόλλων φθέγγεται πρὸς ἐμέ, οὐ λέγω, μή σοι ἄπιστα δόξω περὶ ἐμαυτοῦ μεγαλαυχεῖσθαι· ἃ δὲ Ἀμφιλόχου τε ἤκουσα ἐν Μαλλῷ, τοῦ ἥρωος ὕπαρ διαλεχθέντος μοι καὶ συμβουλεύσαντος περὶ τῶν ἐμῶν, καὶ ἃ εἶδον αὐτός, ἐθέλω ὑμῖν εἰπεῖν, εἶτα ἑξῆς ἃ ἐν Περγάμῳ εἶδον καὶ ἃ ἤκουσα ἐν Πατάροις.", "st": "31.38"}, {"sp": "N", "t": "Ὁπότε γὰρ ἐξ Αἰγύπτου ἐπανῄειν οἴκαδε ἀκούων τὸ ἐν Μαλλῷ τοῦτο μαντεῖον ἐπιφανέστατόν τε καὶ ἀληθέστατον εἶναι καὶ χρᾶν ἐναργῶς πρὸς ἔπος ἀποκρινόμενον οἷς ἂν ἐγγράψας τις εἰς τὸ γραμματεῖον παραδῷ τῷ προφήτῃ, καλῶς ἔχειν ἡγησάμην ἐν παράπλῳ πειραθῆναι τοῦ χρηστηρίου καί τι περὶ τῶν μελλόντων συμβουλεύσασθαι τῷ θεῷ —”", "st": "31.38"}, {"sp": "N", "t": "ταῦτα ἔτι τοῦ Εὐκράτους λέγοντος ἰδὼν οἷ τὸ πρᾶγμα προχωρήσειν ἔμελλε καὶ ὡς οὐ μικρᾶς ἐνήρχετο τῆς περὶ τὰ χρηστήρια τραγῳδίας, οὐ δοκιμάσας μόνος ἀντιλέγειν ἅπασιν, ἀπολιπὼν αὐτὸν ἔτι διαπλέοντα ἐξ Αἰγύπτου εἰς τὴν Μαλλόν — καὶ γὰρ συνίειν ὅτι μοι ἄχθονται παρόντι καθάπερ ἀντισοφιστῇ τῶν ψευσμάτων — “ἀλλ’ ἐγὼ ἄπειμι,” ἔφην, “Λεόντιχον ἀναζητήσων· δέομαι γάρ τι αὐτῷ συγγενέσθαι. ὑμεῖς δὲ ἐπείπερ οὐχ ἱκανὰ ἡγεῖσθε τὰ ἀνθρώπινα εἶναι, καὶ αὐτοὺς ἤδη τοὺς θεοὺς καλεῖτε συνεπιληψομένους ὑμῖν τῶν μυθολογουμένων” καὶ ἅμα λέγων ἐξῄειν. οἱ δὲ ἄσμενοι ἐλευθερίας λαβόμενοι εἱστίων, ὡς τὸ εἰκός, αὑτοὺς καὶ ἐνεφοροῦντο τῶν ψευσμάτων.", "st": "31.39"}, {"sp": "N", "t": "τοιαῦτά σοι, ὦ Φιλόκλεις, παρὰ Εὐκράτει ἀκούσας περίειμι νὴ τὸν Δία ὥσπερ οἱ τοῦ γλεύκους πιόντες ἐμπεφυσημένος τὴν γαστέρα ἐμέτου δεόμενος. ἡδέως δ’ ἄν ποθεν ἐπὶ πολλῷ ἐπριάμην ληθεδανόν τι φάρμακον ὧν ἤκουσα, ὡς μή τι κακὸν ἐργάσηταί με ἡ μνήμη αὐτῶν ἐνοικουροῦσα· τέρατα γοῦν καὶ δαίμονας καὶ Ἑκάτας ὁρᾶν μοι δοκῶ.", "st": "31.39"}, {"sp": "N", "t": "<em>Φιλοκλῆς.<\/em> καὶ αὐτός, ὦ Τυχιάδη, τοιοῦτόν τι ἀπέλαυσα τῆς διηγήσεως. φασί γέ τοι μὴ μόνον λυττᾶν καὶ τὸ ὕδωρ φοβεῖσθαι ὁπόσους ἂν οἱ λυττῶντες κύνες δάκωσιν, ἀλλὰ κἄν τινα ὁ δηχθεὶς ἄνθρωπος δάκῃ, ἴσα τῷ κυνὶ δύναται τὸ δῆγμα, καὶ τὰ αὐτὰ κἀκεῖνος φοβεῖται. καὶ σὺ τοίνυν ἔοικας αὐτὸς ἐν Εὐκράτους δηχθεὶς ὑπὸ πολλῶν ψευσμάτων μεταδεδωκέναι κἀμοὶ τοῦ δήγματος· οὕτω δαιμόνων μοι τὴν ψυχὴν ἐνέπλησας.", "st": "31.40"}, {"sp": "N", "t": "<em>Τυχιάδης.<\/em> ἀλλὰ θαρρῶμεν, ὦ φιλότης, μέγα τῶν τοιούτων ἀλεξιφάρμακον ἔχοντες τὴν ἀλήθειαν καὶ τὸν ἐπὶ πᾶσι λόγον ὀρθόν, ᾧ χρωμένους ἡμᾶς μηδὲν μὴ ταράξῃ τῶν κενῶν καὶ ματαίων τούτων ψευσμάτων.", "st": "31.40"}, {"sp": "HDR", "t": "Περὶ τῶν ἐν Μισθῷ συνόντων"}, {"sp": "N", "t": "καὶ τί σοι πρῶτον, ὦ φιλότης, ἢ τί ὕστατον, φασί, καταλέξω τούτων ἃ πάσχειν ἢ ποιεῖν ἀνάγκη τοὺς ἐπὶ μισθῷ συνόντας κἀν ταῖς τῶν εὐδαιμόνων τούτων φιλίαις ἐξεταζομένους — εἰ χρὴ φιλίαν τὴν τοιαύτην αὐτῶν δουλείαν ἐπονομάζειν; οἶδα γὰρ πολλὰ καὶ σχεδὸν τὰ πλεῖστα τῶν συμβαινόντων αὐτοῖς, οὐκ αὐτὸς μὰ Δία τοῦ τοιούτου πειραθείς, οὐ γὰρ ἐν ἀνάγκῃ μοι ἡ πεῖρα ἐγεγένητο, μηδέ, ὦ θεοί, γένοιτο· ἀλλὰ πολλοὶ τῶν εἰς τὸν βίον τοῦτον ἐμπεπτωκότων ἐξηγόρευον πρός με, οἱ μὲν ἔτι ἐν τῷ κακῷ ὄντες, ἀποδυρόμενοι ὁπόσα καὶ ὁποῖα ἔπασχον, οἱ δὲ ὥσπερ ἐκ δεσμωτηρίου τινὸς ἀποδράντες οὐκ ἀηδῶς μνημονεύοντες ὧν ἐπεπόνθεσαν· ἀλλὰ γὰρ εὐφραίνοντο ἀναλογιζόμενοι οἵων ἀπηλλάγησαν.", "st": "33.1"}, {"sp": "N", "t": "ἀξιοπιστότεροι δὲ ἦσαν οὗτοι διὰ πάσης, ὡς εἰπεῖν, τῆς τελετῆς διεξεληλυθότες καὶ πάντα ἐξ ἀρχῆς εἰς τέλος ἐποπτεύσαντες. οὐ παρέργως οὖν οὐδὲ ἀμελῶς ἐπήκουον αὐτῶν καθάπερ ναυαγίαν τινὰ καὶ σωτηρίαν αὑτῶν παράλογον διηγουμένων, οἷοί εἰσιν οἱ πρὸς τοῖς ἱεροῖς ἐξυρημένοι τὰς κεφαλὰς συνάμα πολλοὶ τὰς τρικυμίας καὶ ζάλας καὶ ἀκρωτήρια καὶ ἐκβολὰς καὶ ἱστοῦ κλάσεις καὶ πηδαλίων ἀποκαυλίσεις διεξιόντες, ἐπὶ πᾶσι δὲ τοὺς Διοσκούρους ἐπιφαινομένους, — οἰκεῖοι γὰρ τῆς τοιαύτης τραγῳδίας οὗτοί γε — ἤ τιν’ ἄλλον ἐκ μηχανῆς θεὸν ἐπὶ τῷ καρχησίῳ καθεζόμενον ἢ πρὸς τοῖς πηδαλίοις ἑστῶτα καὶ πρός τινα ᾐόνα μαλακὴν ἀπευθύνοντα τὴν ναῦν, οἷ προσενεχθεῖσα ἔμελλεν αὐτὴ μὲν ἠρέμα καὶ κατὰ σχολὴν διαλυθήσεσθαι, αὐτοὶ δὲ ἀσφαλῶς ἀποβήσεσθαι χάριτι καὶ εὐμενείᾳ τοῦ θεοῦ.", "st": "33.1"}, {"sp": "N", "t": "ἐκεῖνοι μὲν οὖν τὰ πολλὰ ταῦτα πρὸς τὴν χρείαν τὴν παραυτίκα ἐπιτραγῳδοῦσιν ὡς παρὰ πλειόνων λαμβάνοιεν, οὐ δυστυχεῖς μόνον ἀλλὰ καὶ θεοφιλεῖς τινες εἶναι δοκοῦντες·", "st": "33.1"}, {"sp": "N", "t": "οἱ δὲ τοὺς ἐν ταῖς οἰκίαις χειμῶνας καὶ τὰς τρικυμίας καὶ νὴ Δία πεντακυμίας τε καὶ δεκακυμίας, εἰ οἷόν τε εἰπεῖν, διηγούμενοι, καὶ ὡς τὸ πρῶτον εἰσέπλευσαν, γαληνοῦ ὑποφαινομένου τοῦ πελάγους, καὶ ὅσα πράγματα παρὰ τὸν πλοῦν ὅλον ὑπέμειναν ἢ διψῶντες ἢ ναυτιῶντες ἢ ὑπεραντλούμενοι τῇ ἅλμῃ, καὶ τέλος ὡς πρὸς πέτραν τινὰ ὕφαλον ἢ σκόπελον ἀπόκρημνον περιρρήξαντες τὸ δύστηνον σκαφίδιον ἄθλιοι κακῶς ἐξενήξαντο γυμνοὶ καὶ πάντων ἐνδεεῖς τῶν ἀναγκαίων — ἐν δὴ τούτοις καὶ τῇ τούτων διηγήσει ἐδόκουν μοι τὰ πολλὰ οὗτοι ὑπ’ αἰσχύνης ἐπικρύπτεσθαι, καὶ ἑκόντες εἶναι ἐπιλανθάνεσθαι αὐτῶν.", "st": "33.2"}, {"sp": "N", "t": "ἀλλ’ ἔγωγε κἀκεῖνα καὶ εἴ τιν’ ἄλλα ἐκ τοῦ λόγου συντιθεὶς εὑρίσκω προσόντα ταῖς τοιαύταις συνουσίαις, οὐκ ὀκνήσω σοι πάντα, ὦ καλὲ Τιμόκλεις, διεξελθεῖν· δοκῶ γάρ μοι ἐκ πολλοῦ ἤδη κατανενοηκέναι σε τούτῳ τῷ βίῳ ἐπιβουλεύοντα,", "st": "33.2"}, {"sp": "N", "t": "καὶ πρῶτόν γε ὁπηνίκα περὶ τῶν τοιούτων ὁ λόγος ἐνέπεσεν, εἶτα ἐπῄνεσέ τις τῶν παρόντων τὴν τοιαύτην μισθοφοράν, τρισευδαίμονας εἶναι λέγων οἷς μετὰ τοῦ φίλους ἔχειν τοὺς ἀρίστους Ῥωμαίων καὶ δειπνεῖν δεῖπνα πολυτελῆ καὶ ἀσύμβολα καὶ οἰκεῖν ἐν καλῷ καὶ ἀποδημεῖν μετὰ πάσης ῥᾳστώνης καὶ ἡδονῆς ἐπὶ λευκοῦ ζεύγους, εἰ τύχοι, ἐξυπτιάζοντας, προσέτι καὶ μισθὸν τῆς φιλίας καὶ ὧν εὖ πάσχουσιν τούτων λαμβάνειν οὐκ ὀλίγον ἐστίν· ἀτεχνῶς γὰρ ἄσπορα καὶ ἀνήροτα τοῖς τοιούτοις τὰ πάντα φύεσθαι. ὁπότε οὖν ταῦτα καὶ τὰ τοιαῦτα ἤκουες, ἑώρων ὅπως ἐκεχήνεις πρὸς αὐτὰ καὶ πάνυ σφόδρα πρὸς τὸ δέλεαρ ἀναπεπταμένον παρεῖχες τὸ στόμα.", "st": "33.3"}, {"sp": "N", "t": "ὡς οὖν τό γε ἡμέτερον εἰσαῦθίς ποτε ἀναίτιον ᾖ μηδὲ ἔχῃς λέγειν ὡς ὁρῶντές σε τηλικοῦτο μετὰ τῆς καρίδος ἄγκιστρον καταπίνοντα οὐκ ἐπελαβόμεθα οὐδὲ πρὶν ἐμπεσεῖν τῷ λαιμῷ περιεσπάσαμεν οὐδὲ προεδηλώσαμεν, ἀλλὰ περιμείναντες ἐξ ἑλκομένου καὶ ἐμπεπηγότος ἤδη συρόμενον καὶ πρὸς ἀνάγκην ἀγόμενον ὁρᾶν, ὅτ’ οὐδὲν ὄφελος ἑστῶτες ἐπεδακρύομεν· ὅπως μὴ ταῦτα λέγῃς ποτέ, πάνυ εὔλογα, ἢν λέγηται, καὶ ἄφυκτα ἡμῖν, ὡς οὐκ ἀδικοῦμεν μὴ προμηνύσαντες, ἄκουσον ἐξ ἀρχῆς ἁπάντων, καὶ τὸ δίκτυόν τε αὐτὸ καὶ τῶν κύρτων τὸ ἀδιέξοδον ἔκτοσθεν ἐπὶ σχολῆς, ἀλλὰ μὴ ἔνδοθεν ἐκ τοῦ μυχοῦ προεπισκόπησον, καὶ τοῦ ἀγκίστρου δὲ τὸ ἀγκύλον καὶ τὴν εἰς τὸ ἔμπαλιν τοῦ σκόλοπος ἀναστροφὴν καὶ τῆς τριαίνης τὰς ἀκμὰς εἰς τὰς χεῖρας λαβὼν καὶ πρὸς τὴν γνάθον πεφυσημένην ἀποπειρώμενος, ἢν μὴ πάνυ ὀξέα μηδὲ ἄφυκτα μηδὲ ἀνιαρὰ ἐν τοῖς τραύμασι φαίνηται βιαίως σπῶντα καὶ ἀμάχως ἀντιλαμβανόμενα, ἡμᾶς μὲν ἐν τοῖς δειλοῖς καὶ διὰ τοῦτο πεινῶσιν ἀνάγραφε, σεαυτὸν δὲ παρακαλέσας θαρρεῖν ἐπιχείρει τῇ ἄγρᾳ, εἰ θέλεις, καθάπερ ὁ λάρος ὅλον περιχανὼν τὸ δέλεαρ.", "st": "33.3"}, {"sp": "N", "t": "ῥηθήσεται δὲ ὁ πᾶς λόγος τὸ μὲν ὅλον ἴσως διὰ σέ, πλὴν ἀλλ’ οὔ γε περὶ τῶν φιλοσοφούντων ὑμῶν μόνον, οὐδὲ ὁπόσοι σπουδαιοτέραν τὴν προαίρεσιν προείλοντο ἐν τῷ βίῳ, ἀλλὰ καὶ περὶ γραμματιστῶν καὶ ῥητόρων καὶ μουσικῶν καὶ ὅλως τῶν ἐπὶ παιδείαις συνεῖναι καὶ μισθοφορεῖν ἀξιουμένων. κοινῶν δὲ ὡς ἐπίπαν ὄντων καὶ ὁμοίων τῶν συμβαινόντων ἅπασι, δῆλον ὡς οὐκ ἐξαίρετα μέν, αἰσχίω δὲ τὰ αὐτὰ ὄντα γίγνεται τοῖς φιλοσοφοῦσιν, εἰ τῶν ὁμοίων τοῖς ἄλλοις ἀξιοῖντο καὶ μηδὲν αὐτοὺς σεμνότερον οἱ μισθοδόται ἄγοιεν. ὅ τι δ’ ἂν οὖν ὁ λόγος αὐτὸς ἐπιὼν ἐξευρίσκῃ, τούτου τὴν αἰτίαν μάλιστα μὲν οἱ ποιοῦντες αὐτοί, ἔπειτα δὲ οἱ ὑπομένοντες αὐτὰ δίκαιοι ἔχειν· ἐγὼ δὲ ἀναίτιος, εἰ μὴ ἀληθείας καὶ παρρησίας ἐπιτίμιόν τί ἐστιν.", "st": "33.4"}, {"sp": "N", "t": "τοὺς μέντοι τοῦ ἄλλου πλήθους, οἷον γυμναστάς τινας ἢ κόλακας, ἰδιώτας καὶ μικροὺς τὰς γνώμας καὶ ταπεινοὺς αὐτόθεν ἀνθρώπους, οὔτε ἀποτρέπειν ἄξιον τῶν τοιούτων συνουσιῶν, οὐδὲ γὰρ ἂν πεισθεῖεν, οὔτε μὴν αἰτιᾶσθαι καλῶς ἔχει μὴ ἀπολειπομένους τῶν μισθοδοτῶν εἰ καὶ πάνυ πολλὰ ὑβρίζοιντο ὑπ’ αὐτῶν, ἐπιτήδειοι γὰρ καὶ οὐκ ἀνάξιοι τῆς τοιαύτης διατριβῆς· ἄλλως τε οὐδὲ σχοῖεν ἄν τι ἄλλο πρὸς ὅ τι χρὴ ἀποκλίναντας αὐτοὺς παρέχειν αὑτοὺς ἐνεργούς, ἀλλ’ ἤν τις αὐτῶν ἀφέλῃ τοῦτο, ἄτεχνοι αὐτίκα καὶ ἀργοὶ καὶ περιττοί εἰσιν. οὐδὲν οὖν οὔτ’ αὐτοὶ δεινὸν πάσχοιεν ἂν οὔτ’ ἐκεῖνοι ὑβρισταὶ δοκοῖεν εἰς τὴν ἀμίδα, φασίν, ἐνουροῦντες· ἐπὶ γάρ τοι τὴν ὕβριν ταύτην ἐξ ἀρχῆς παρέρχονται εἰς τὰς οἰκίας, καὶ ἡ τέχνη φέρειν καὶ ἀνέχεσθαι τὰ γιγνόμενα. περὶ δὲ ὧν προεῖπον τῶν πεπαιδευμένων ἄξιον ἀγανακτεῖν καὶ πειρᾶσθαι ὡς ἔνι μάλιστα μετάγειν αὐτοὺς καὶ πρὸς ἐλευθερίαν ἀφαιρεῖσθαι.", "st": "33.4"}, {"sp": "N", "t": "δοκῶ δέ μοι καλῶς ἂν ποιῆσαι, εἰ τὰς αἰτίας ἀφ’ ὧν ἐπὶ τὸν τοιοῦτον βίον ἀφικνοῦνταί τινες προεξετάσας δείξαιμι οὐ πάνυ βιαίους οὐδ’ ἀναγκαίας· οὕτω γὰρ ἂν αὐτοῖς ἡ ἀπολογία προαναιροῖτο καὶ ἡ πρώτη ὑπόθεσις τῆς ἐθελοδουλείας. οἱ μὲν δὴ πολλοὶ τὴν πενίαν καὶ τὴν τῶν ἀναγκαίων χρείαν προθέμενοι ἱκανὸν τοῦτο προκάλυμμα οἴονται προβεβλῆσθαι τῆς πρὸς τὸν βίον τοῦτον αὐτομολίας, καὶ ἀποχρῆν αὐτοῖς νομίζουσιν εἰ λέγοιεν ὡς συγγνώμης ἄξιον ποιοῦσιν τὸ χαλεπώτατον τῶν ἐν τῷ βίῳ, τὴν πενίαν, διαφυγεῖν ζητοῦντες· εἶτα ὁ Θέογνις πρόχειρος καὶ πολὺ τό,<br>πᾶς γὰρ ἀνὴρ πενίῃ δεδμημένος<br>καὶ ὅσα ἄλλα δείματα ὑπὲρ τῆς πενίας οἱ ἀγεννέστατοι τῶν ποιητῶν ἐξενηνόχασιν.", "st": "33.5"}, {"sp": "N", "t": "ἐγὼ δ’ εἰ μὲν ἑώρων αὐτοὺς φυγήν τινα ὡς ἀληθῶς τῆς πενίας εὑρισκομένους ἐκ τῶν τοιούτων συνουσιῶν, οὐκ ἂν ὑπὲρ τῆς ἄγαν ἐλευθερίας ἐμικρολογούμην πρὸς αὐτούς· ἐπεὶ δὲ — ὡς ὁ καλός που ῥήτωρ ἔφη — τοῖς τῶν νοσούντων σιτίοις ἐοικότα λαμβάνουσι, τίς ἔτι μηχανὴ μὴ οὐχὶ καὶ πρὸς τοῦτο κακῶς βεβουλεῦσθαι δοκεῖν αὐτούς, ἀεὶ μενούσης αὐτοῖς ὁμοίας τῆς ὑποθέσεως τοῦ βίου; πενία γὰρ εἰσαεὶ καὶ τὸ λαμβάνειν ἀναγκαῖον καὶ ἀπόθετον οὐδὲν οὐδὲ περιττὸν εἰς φυλακήν, ἀλλὰ τὸ δοθέν, κἂν δοθῇ, κἂν ἀθρόως ληφθῇ, πᾶν ἀκριβῶς καὶ τῆς χρείας ἐνδεῶς καταναλίσκεται. καλῶς δὲ εἶχε μὴ τοιαύτας τινὰς ἀφορμὰς ἐπινοεῖν αἳ τὴν πενίαν τηροῦσι παραβοηθοῦσαι μόνον αὐτῇ, ἀλλ’ αἳ τέλεον ἐξαιρήσουσιν, καὶ ὑπέρ γε τοῦ τοιούτου καὶ εἰς βαθυκήτεα πόντον ἴσως ῥιπτεῖν, εἰ δεῖ, ὦ Θέογνι, καὶ πετρέων, ὡς φής, κατ’ ἠλιβάτων. εἰ δέ τις ἀεὶ πένης καὶ ἐνδεὴς καὶ ὑπόμισθος ὢν οἴεται πενίαν αὐτῷ τούτῳ διαπεφευγέναι, οὐκ οἶδα πῶς ὁ τοιοῦτος οὐκ ἂν δόξειεν ἑαυτὸν ἐξαπατᾶν.", "st": "33.5"}, {"sp": "N", "t": "ἄλλοι δὲ πενίαν μὲν αὐτὴν οὐκ ἂν φοβηθῆναι οὐδὲ καταπλαγῆναί φασιν, εἰ ἐδύναντο τοῖς ἄλλοις ὁμοίως πονοῦντες ἐκπορίζειν τὰ ἄλφιτα, νῦν δέ, πεπονηκέναι γὰρ αὐτοῖς τὰ σώματα ἢ ὑπὸ γήρως ἢ ὑπὸ νόσων, ἐπὶ τήνδε ῥᾴστην οὖσαν τὴν μισθοφορὰν ἀπηντηκέναι. φέρ’ οὖν ἴδωμεν εἰ ἀληθῆ λέγουσιν καὶ ἐκ τοῦ ῥᾴστου, μὴ πολλὰ μηδὲ πλείω τῶν ἄλλων πονοῦσι, περιγίγνεται αὐτοῖς τὰ διδόμενα· εὐχῇ γὰρ ἂν ἐοικότα εἴη ταῦτά γε, μὴ πονήσαντα μηδὲ καμόντα ἕτοιμον ἀργύριον λαβεῖν. τὸ δ’ ἐστὶ καὶ ῥηθῆναι κατ’ ἀξίαν ἀδύνατον· τοσαῦτα πονοῦσιν καὶ κάμνουσιν ἐν ταῖς συνουσίαις, ὥστε πλείονος ἐνταῦθα καὶ ἐπὶ τοῦτο μάλιστα τῆς ὑγιείας δεῖσθαι, μυρίων ὄντων ὁσημέραι τῶν ἐπιτριβόντων τὸ σῶμα καὶ πρὸς ἐσχάτην ἀπόγνωσιν καταπονούντων. λέξομεν δὲ αὐτὰ ἐν τῷ προσήκοντι καιρῷ, ἐπειδὰν καὶ τὰς ἄλλας αὐτῶν δυσχερείας διεξίωμεν· τὸ δὲ νῦν εἶναι ἱκανὸν ἦν ὑποδεῖξαι ὡς οὐδ’ οἱ διὰ ταύτην λέγοντες αὑτοὺς ἀποδίδοσθαι τὴν πρόφασιν ἀληθεύοιεν ἄν.", "st": "33.6"}, {"sp": "N", "t": "λοιπὸν δὴ καὶ ἀληθέστατον μέν, ἥκιστα δὲ πρὸς αὐτῶν λεγόμενον, ἡδονῆς ἕνεκα καὶ τῶν πολλῶν καὶ ἀθρόων ἐλπίδων εἰσπηδᾶν αὐτοὺς εἰς τὰς οἰκίας, καταπλαγέντας μὲν τὸ πλῆθος τοῦ χρυσοῦ καὶ τοῦ ἀργύρου, εὐδαιμονήσαντας δὲ ἐπὶ τοῖς δείπνοις καὶ τῇ ἄλλῃ τρυφῇ, ἐλπίσαντας δὲ ὅσον αὐτίκα χανδὸν οὐδενὸς ἐπιστομίζοντος πίεσθαι τοῦ χρυσίου. ταῦτα ὑπάγει αὐτοὺς καὶ δούλους ἀντὶ ἐλευθέρων τίθησιν — οὐχ ἡ τῶν ἀναγκαίων χρεία, ἣν ἔφασκον, ἀλλ’ ἡ τῶν οὐκ ἀναγκαίων ἐπιθυμία καὶ ὁ τῶν πολλῶν καὶ πολυτελῶν ἐκείνων ζῆλος. τοιγαροῦν ὥσπερ δυσέρωτας αὐτοὺς καὶ κακοδαίμονας ἐραστὰς ἔντεχνοί τινες καὶ τρίβωνες ἐρώμενοι παραλαβόντες ὑπεροπτικῶς περιέπουσιν, ὅπως ἀεὶ ἐρασθήσονται αὐτῶν θεραπεύοντες, ἀπολαῦσαι δὲ τῶν παιδικῶν ἀλλ’ οὐδὲ μέχρι φιλήματος ἄκρου μεταδιδόντες· ἴσασι γὰρ ἐν τῷ τυχεῖν τὴν διάλυσιν τοῦ ἔρωτος γενησομένην. ταύτην οὖν ἀποκλείουσιν καὶ ζηλοτύπως φυλάττουσιν· τὰ δὲ ἄλλα ἐπ’ ἐλπίδος ἀεὶ τὸν ἐραστὴν ἔχουσιν. δεδίασι γὰρ μὴ αὐτὸν ἡ ἀπόγνωσις ἀπαγάγῃ τῆς ἄγαν ἐπιθυμίας καὶ ἀνέραστος αὐτοῖς γένηται· προσμειδιῶσιν οὖν καὶ ὑπισχνοῦνται καὶ ἀεὶ εὖ ποιήσουσι καὶ χαριοῦνται καὶ ἐπιμελήσονται πολυτελῶς. εἶτ’ ἔλαθον ἄμφω γηράσαντες, ἔξωροι γενόμενοι καὶ οὗτος τοῦ ἐρᾶν κἀκεῖνος τοῦ μεταδιδόναι. πέπρακται δ’ οὖν αὐτοῖς οὐδὲν ἐν ἅπαντι τῷ βίῳ πέρα τῆς ἐλπίδος.", "st": "33.7"}, {"sp": "N", "t": "τὸ μὲν δὴ δι’ ἡδονῆς ἐπιθυμίαν ἅπαντα ὑπομένειν οὐ πάνυ ἴσως ὑπαίτιον, ἀλλὰ συγγνώμη εἴ τις ἡδονῇ χαίρει καὶ τοῦτο ἐξ ἅπαντος θεραπεύει ὅπως μεθέξει αὐτῆς. καίτοι αἰσχρὸν ἴσως καὶ ἀνδραποδῶδες ἀποδόσθαι διὰ ταύτην ἑαυτόν· πολὺ γὰρ ἡδίων ἡ ἐκ τῆς ἐλευθερίας ἡδονή. ὅμως δ’ οὖν ἐχέτω τινὰ συγγνώμην αὐτοῖς, εἰ ἐπιτυγχάνοιτο· τὸ δὲ δι’ ἡδονῆς ἐλπίδα μόνον πολλὰς ἀηδίας ὑπομένειν γελοῖον οἶμαι καὶ ἀνόητον, καὶ ταῦτα ὁρῶντας ὡς οἱ μὲν πόνοι σαφεῖς καὶ πρόδηλοι καὶ ἀναγκαῖοι, τὸ δὲ ἐλπιζόμενον ἐκεῖνο, ὁτιδήποτέ ἐστιν τὸ ἡδύ, οὔτε ἐγένετό πω τοσούτου χρόνου, προσέτι δὲ οὐδὲ γενήσεσθαι ἔοικεν, εἴ τις ἐκ τῆς ἀληθείας λογίζοιτο. οἱ μέν γε τοῦ Ὀδυσσέως ἑταῖροι γλυκύν τινα τὸν λωτὸν ἐσθίοντες ἠμέλουν τῶν ἄλλων καὶ πρὸς τὸ παρὸν ἡδὺ τῶν καλῶς ἐχόντων κατεφρόνουν· ὥστε οὐ πάντῃ ἄλογος αὐτῶν ἡ λήθη τοῦ καλοῦ, πρὸς τῷ ἡδεῖ ἐκείνῳ τῆς ψυχῆς διατριβούσης. τὸ δὲ λιμῷ συνόντα παρεστῶτα ἄλλῳ τοῦ λωτοῦ ἐμφορουμένῳ μηδὲν μεταδιδόντι ὑπὸ ἐλπίδος μόνης τοῦ κἂν αὐτὸν παραγεύσασθαί ποτε δεδέσθαι, τῶν καλῶς καὶ ὀρθῶς ἐχόντων ἐπιλελησμένον, Ἡράκλεις, ὡς καταγέλαστον καὶ πληγῶν τινων Ὁμηρικῶν ὡς ἀληθῶς δεόμενον.", "st": "33.8"}, {"sp": "N", "t": "τὰ μὲν τοίνυν πρὸς τὰς συνουσίας αὐτοὺς ἄγοντα καὶ ἀφ’ ὧν αὑτοὺς φέροντες ἐπιτρέπουσι τοῖς πλουσίοις χρῆσθαι πρὸς ὅ τι ἂν ἐθέλωσιν, ταῦτά ἐστιν ἢ ὅτι ἐγγύτατα τούτων, πλὴν εἰ μὴ κἀκείνων τις μεμνῆσθαι ἀξιώσειεν τῶν καὶ μόνῃ τῇ δόξῃ ἐπαιρομένων τοῦ συνεῖναι εὐπατρίδαις τε καὶ εὐπαρύφοις ἀνδράσιν· εἰσὶν γὰρ οἳ καὶ τοῦτο περίβλεπτον καὶ ὑπὲρ τοὺς πολλοὺς νομίζουσιν, ὡς ἔγωγε τοὐμὸν ἴδιον οὐδὲ βασιλεῖ τῷ μεγάλῳ αὐτὸ μόνον συνεῖναι καὶ συνὼν ὁρᾶσθαι μηδὲν χρηστὸν ἀπολαύων τῆς συνουσίας δεξαίμην ἄν.", "st": "33.9"}, {"sp": "N", "t": "τοιαύτης δὲ αὐτοῖς τῆς ὑποθέσεως οὔσης, φέρε ἤδη πρὸς ἡμᾶς αὐτοὺς ἐπισκοπήσωμεν οἷα μὲν πρὸ τοῦ εἰσδεχθῆναι καὶ τυχεῖν ὑπομένουσιν, οἷα δὲ ἐν αὐτῷ ἤδη ὄντες πάσχουσιν, ἐπὶ πᾶσι δὲ ἥτις αὐτοῖς ἡ καταστροφὴ τοῦ δράματος γίγνεται. οὐ γὰρ δὴ ἐκεῖνό γε εἰπεῖν ἐστιν, ὡς εἰ καὶ πονηρὰ ταῦτα, εὔληπτα γοῦν καὶ οὐ πολλοῦ δεήσει τοῦ πόνου, ἀλλὰ θελῆσαι δεῖ μόνον, εἶτά σοι πέπρακται τὸ πᾶν εὐμαρῶς· ἀλλὰ πολλῆς μὲν τῆς διαδρομῆς δεῖ, συνεχοῦς δὲ τῆς θυραυλίας, ἕωθέν τε ἐξανιστάμενον περιμένειν ὠθούμενον καὶ ἀποκλειόμενον καὶ ἀναίσχυντον ἐνίοτε καὶ ὀχληρὸν δοκοῦντα καὶ ὑπὸ θυρωρῷ κακῶς συρίζοντι καὶ ὀνομακλήτορι Λιβυκῷ ταττόμενον καὶ μισθὸν τελοῦντα τῆς μνήμης τοῦ ὀνόματος. καὶ μὴν καὶ ἐσθῆτος ὑπὲρ τὴν ὑπάρχουσαν δύναμιν ἐπιμεληθῆναι χρὴ πρὸς τὸ τοῦ θεραπευομένου ἀξίωμα, καὶ χρώματα αἱρεῖσθαι οἷς ἂν ἐκεῖνος ἥδηται, ὡς μὴ ἀπᾴδῃς μηδὲ προσκρούῃς βλεπόμενος, καὶ φιλοπόνως ἕπεσθαι, μᾶλλον δὲ ἡγεῖσθαι, ὑπὸ τῶν οἰκετῶν προωθούμενον καὶ ὥσπερ τινὰ πομπὴν ἀναπληροῦντα.", "st": "33.10"}, {"sp": "N", "t": "ὁ δὲ οὐδὲ προσβλέπει πολλῶν ἑξῆς ἡμερῶν.", "st": "33.10"}, {"sp": "N", "t": "ἢν δέ ποτε καὶ τὰ ἄριστα πράξῃς, καὶ ἴδῃ σε καὶ προσκαλέσας ἔρηταί τι ὧν ἂν τύχῃ, τότε δὴ τότε πολὺς μὲν ὁ ἱδρώς, ἀθρόος δὲ ὁ ἴλιγγος καὶ τρόμος ἄκαιρος καὶ γέλως τῶν παρόντων ἐπὶ τῇ ἀπορίᾳ. καὶ πολλάκις ἀποκρίνασθαι δέον, “τίς ἦν ὁ βασιλεὺς τῶν Ἀχαιῶν,” ὅτι “χίλιαι νῆες ἦσαν αὐτοῖς,” λέγεις. τοῦτο οἱ μὲν χρηστοὶ αἰδῶ ἐκάλεσαν, οἱ δὲ τολμηροὶ δειλίαν, οἱ δὲ κακοήθεις ἀπαιδευσίαν. σὺ δ’ οὖν ἐπισφαλεστάτης πειραθεὶς τῆς πρώτης φιλοφροσύνης ἀπῆλθες καταδικάσας σεαυτοῦ πολλὴν τὴν ἀπόγνωσιν.", "st": "33.11"}, {"sp": "N", "t": "ἐπειδὰν δὲ<br>πολλὰς μὲν ἀΰπνους νύκτας ἰαύσῃς<br>ἤματα δ’ αἱματόεντα<br>διαγάγῃς, οὐ μὰ Δία τῆς Ἑλένης ἕνεκα οὐδὲ τῶν Πριάμου Περγάμων, ἀλλὰ τῶν ἐλπιζομένων πέντε ὀβολῶν, τύχῃς δὲ καὶ τραγικοῦ τινος θεοῦ συνιστάντος, ἐξέτασις τοὐντεῦθεν εἰ οἶσθα τὰ μαθήματα. καὶ τῷ μὲν πλουσίῳ ἡ διατριβὴ οὐκ ἀηδὴς ἐπαινουμένῳ καὶ εὐδαιμονιζομένῳ, σοὶ δὲ ὁ ὑπὲρ τῆς ψυχῆς ἀγὼν καὶ ὑπὲρ ἅπαντος τοῦ βίου τότε προκεῖσθαι δοκεῖ· ὑπεισέρχεται γὰρ εἰκότως τὸ μηδ’ ὑπ’ ἄλλου ἂν καταδεχθῆναι πρὸς τοῦ προτέρου ἀποβληθέντα καὶ δόξαντα εἶναι ἀδόκιμον. ἀνάγκη τοίνυν εἰς μυρία διαιρεθῆναι τότε, τοῖς μὲν ἀντεξεταζομένοις φθονοῦντα, — τίθει γὰρ καὶ ἄλλους εἶναι τῶν αὐτῶν ἀντιποιουμένους — αὐτὸν δὲ πάντα ἐνδεῶς εἰρηκέναι νομίζοντα, φοβούμενον δὲ καὶ ἐλπίζοντα καὶ πρὸς τὸ ἐκείνου πρόσωπον ἀτενίζοντα καὶ εἰ μὲν ἐκφαυλίζοι τι τῶν λεγομένων, ἀπολλύμενον, εἰ δὲ μειδιῶν ἀκούοι, γεγηθότα καὶ εὔελπιν καθιστάμενον.", "st": "33.11"}, {"sp": "N", "t": "εἰκὸς δὲ πολλοὺς εἶναι τοὺς ἐναντία σοι φρονοῦντας καὶ ἄλλους ἀντὶ σοῦ τιθεμένους, ὧν ἕκαστος ὥσπερ ἐκ λόχου τοξεύων λέληθεν. εἶτ’ ἐννόησον ἄνδρα ἐν βαθεῖ πώγωνι καὶ πολιᾷ τῇ κόμῃ ἐξεταζόμενον εἴ τι οἶδεν ὠφέλιμον, καὶ τοῖς μὲν δοκοῦντα εἰδέναι, τοῖς δὲ μή.", "st": "33.12"}, {"sp": "N", "t": "μέσος ἐν τοσούτῳ χρόνος, καὶ πολυπραγμονεῖταί σου ἅπας ὁ παρεληλυθὼς βίος, κἂν μέν τις ἢ πολίτης ὑπὸ φθόνου ἢ γείτων ἔκ τινος εὐτελοῦς αἰτίας προσκεκρουκὼς ἀνακρινόμενος εἴπῃ μοιχὸν ἢ παιδεραστήν, τοῦτ’ ἐκεῖνο, ἐκ τῶν Διὸς δέλτων ὁ μάρτυς, ἂν δὲ πάντες ἅμα ἑξῆς ἐπαινῶσιν, ὕποπτοι καὶ ἀμφίβολοι καὶ δεδεκασμένοι. χρὴ τοίνυν πολλὰ εὐτυχῆσαι καὶ μηδὲν ὅλως ἐναντιωθῆναι· μόνως γὰρ ἂν οὕτως κρατήσειας.", "st": "33.12"}, {"sp": "N", "t": "Εἶεν· καὶ δὴ εὐτύχηταί σοι πάντα εὐχῆς μειζόνως· αὐτός τε γὰρ ἐπῄνεσε τοὺς λόγους καὶ τῶν φίλων οἱ ἐντιμότατοι καὶ οἷς μάλιστα πιστεύει τὰ τοιαῦτα οὐκ ἀπέτρεψαν· ἔτι δὲ καὶ ἡ γυνὴ βούλεται, οὐκ ἀντιλέγει δὲ οὔτε ὁ ἐπίτροπος οὔτε ὁ οἰκονόμος· οὐδέ τις ἐμέμψατό σου τὸν βίον, ἀλλὰ πάντα ἵλεω καὶ πανταχόθεν αἴσια τὰ ἱερά.", "st": "33.12"}, {"sp": "N", "t": "κεκράτηκας οὖν, ὦ μακάριε, καὶ ἔστεψαι τὰ Ὀλύμπια, μᾶλλον δὲ Βαβυλῶνα εἴληφας ἢ τὴν Σάρδεων ἀκρόπολιν καθῄρηκας, καὶ ἕξεις τὸ τῆς Ἀμαλθείας κέρας καὶ ἀμέλξεις ὀρνίθων γάλα. δεῖ δή σοι ἀντὶ τῶν τοσούτων πόνων μέγιστα ἡλίκα γενέσθαι τἀγαθά, ἵνα μὴ φύλλινος μόνον ὁ στέφανος ᾖ, καὶ τόν τε μισθὸν οὐκ εὐκαταφρόνητον ὁρισθῆναι καὶ τοῦτον ἐν καιρῷ τῆς χρείας ἀπραγμόνως ἀποδίδοσθαι καὶ τὴν ἄλλην τιμὴν ὑπὲρ τοὺς πολλοὺς ὑπάρχειν, πόνων δὲ ἐκείνων καὶ πηλοῦ καὶ δρόμων καὶ ἀγρυπνιῶν ἀναπεπαῦσθαι, καὶ τοῦτο δὴ τὸ τῆς εὐχῆς, ἀποτείναντα τὼ πόδε καθεύδειν, μόνα ἐκεῖνα πράττοντα ὧν ἕνεκα τὴν ἀρχὴν παρελήφθης καὶ ὧν ἔμμισθος εἶ. ἐχρῆν μὲν οὕτως, ὦ Τιμόκλεις, καὶ οὐδὲν ἂν ἦν μέγα κακὸν ὑποκύψαντα φέρειν τὸν ζυγὸν ἐλαφρόν τε καὶ εὔφορον καὶ τὸ μέγιστον, ἐπίχρυσον ὄντα. ἀλλὰ πολλοῦ, μᾶλλον δὲ τοῦ παντὸς δεῖ· μυρία γάρ ἐστιν ἀφόρητα ἐλευθέρῳ ἀνδρὶ ἐν αὐταῖς ἤδη ταῖς συνουσίαις γιγνόμενα. σκέψαι δὲ αὐτὸς ἑξῆς ἀκούων, εἴ τις ἂν αὐτὰ ὑπομεῖναι δύναιτο παιδείᾳ κἂν ἐπ’ ἐλάχιστον ὡμιληκώς.", "st": "33.13"}, {"sp": "N", "t": "ἄρξομαι δὲ ἀπὸ τοῦ πρώτου δείπνου, ἢν δοκῇ, ὅ σε εἰκὸς δειπνήσειν τὰ προτέλεια τῆς μελλούσης συνουσίας.", "st": "33.14"}, {"sp": "N", "t": "εὐθὺς οὖν πρόσεισιν παραγγέλλων τις ἥκειν ἐπὶ τὸ δεῖπνον, οὐκ ἀνομίλητος οἰκέτης, ὃν χρὴ πρῶτον ἵλεων ποιήσασθαι, παραβύσαντα εἰς τὴν χεῖρα, ὡς μὴ ἀδέξιος εἶναι δοκῇς, τοὐλάχιστον πέντε δραχμάς· ὁ δὲ ἀκκισάμενος καί, “ἄπαγε, παρὰ σοῦ δὲ ἐγώ;” καί, “Ἡράκλεις, μὴ γένοιτο,” ὑπειπὼν τέλος ἐπείσθη, καὶ ἄπεισί σοι πλατὺ ἐγχανών. σὺ δὲ ἐσθῆτα καθαρὰν προχειρισάμενος καὶ σεαυτὸν ὡς κοσμιώτατα σχηματίσας λουσάμενος ἥκεις, δεδιὼς μὴ πρὸ τῶν ἄλλων ἀφίκοιο· ἀπειρόκαλον γάρ, ὥσπερ καὶ τὸ ὕστατον ἥκειν φορτικόν. αὐτὸ οὖν τηρήσας τὸ μέσον τοῦ καιροῦ εἰσελήλυθας, καί σε πάνυ ἐντίμως ἐδέξατο, καὶ παραλαβών τις κατέκλινε μικρὸν ὑπὲρ τοῦ πλουσίου μετὰ δύο που σχεδὸν τῶν παλαιῶν φίλων.", "st": "33.14"}, {"sp": "N", "t": "σὺ δ’ ὥσπερ εἰς τοῦ Διὸς τὸν οἶκον παρελθὼν πάντα τεθαύμακας καὶ ἐφ’ ἑκάστῳ τῶν πραττομένων μετέωρος εἶ· ξένα γάρ σοι καὶ ἄγνωστα πάντα· καὶ ἥ τε οἰκετεία εἰς σὲ ἀποβλέπει καὶ τῶν παρόντων ἕκαστος ὅ τι πράξεις ἐπιτηροῦσιν, οὐδὲ αὐτῷ δὲ ἀμελὲς τῷ πλουσίῳ τοῦτο, ἀλλὰ καὶ προεῖπέ τισι τῶν οἰκετῶν ἐπισκοπεῖν εἴ πως εἰς τοὺς παῖδας ἢ εἰς τὴν γυναῖκα πολλάκις ἐκ περιωπῆς ἀποβλέψεις. οἱ μὲν γὰρ τῶν συνδείπνων ἀκόλουθοι ὁρῶντες ἐκπεπληγμένον εἰς τὴν ἀπειρίαν τῶν δρωμένων ἀποσκώπτουσι, τεκμήριον τοῦ μὴ παρ’ ἄλλῳ πρότερόν σε δεδειπνηκέναι τὸ καινὸν εἶναί σοι τὸ χειρόμακτρον τιθέμενοι.", "st": "33.15"}, {"sp": "N", "t": "ὥσπερ οὖν εἰκός, ἰδίειν τε ἀνάγκη ὑπ’ ἀπορίας καὶ μήτε διψῶντα πιεῖν αἰτεῖν τολμᾶν, μὴ δόξῃς οἰνόφλυξ τις εἶναι, μήτε τῶν ὄψων παρατεθέντων ποικίλων καὶ πρός τινα τάξιν ἐσκευασμένων εἰδέναι ἐφ’ ὅ τι πρῶτον ἢ δεύτερον τὴν χεῖρα ἐνέγκῃς· ὑποβλέπειν οὖν εἰς τὸν πλησίον δεήσει κἀκεῖνον ζηλοῦν καὶ μανθάνειν τοῦ δείπνου τὴν ἀκολουθίαν.", "st": "33.15"}, {"sp": "N", "t": "τὰ δ’ ἄλλα ποικίλος εἶ καὶ θορύβου πλέως τὴν ψυχήν, πρὸς ἕκαστα τῶν πραττομένων ἐκπεπληγμένος, καὶ ἄρτι μὲν εὐδαιμονίζεις τὸν πλούσιον τοῦ χρυσοῦ καὶ τοῦ ἐλέφαντος καὶ τῆς τοσαύτης τρυφῆς, ἄρτι δὲ οἰκτείρεις σεαυτόν, ὡς τὸ μηδὲν ὢν εἶτα ζῆν ὑπολαμβάνεις. ἐνίοτε δὲ κἀκεῖνο εἰσέρχεταί σε, ὡς ζηλωτόν τινα βιώσῃ τὸν βίον ἅπασιν ἐκείνοις ἐντρυφήσων καὶ μεθέξων αὐτῶν ἐξ ἰσοτιμίας· οἴει γὰρ εἰσαεὶ Διονύσια ἑορτάσειν. καί που καὶ μειράκια ὡραῖα διακονούμενα καὶ ἠρέμα προσμειδιῶντα γλαφυρωτέραν ὑπογράφει σοι τὴν μέλλουσαν διατριβήν, ὥστε συνεχῶς τὸ Ὁμηρικὸν ἐκεῖνο ἐπιφθέγγεσθαι,<br>οὐ νέμεσις Τρῶας καὶ ἐϋκνήμιδας Ἀχαιούς<br>πολλὰ πονεῖν καὶ ὑπομένειν ὑπὲρ τῆς τοσαύτης εὐδαιμονίας.", "st": "33.16"}, {"sp": "N", "t": "Φιλοτησίαι τὸ ἐπὶ τούτῳ, καὶ σκύφον εὐμεγέθη τινὰ αἰτήσας προὔπιέν σοι τῷ διδασκάλῳ, ἢ ὁτιδήποτε προσειπών· σὺ δὲ λαβών, ὅτι μέν τί σε καὶ αὐτὸν ὑπειπεῖν ἔδει ἠγνόησας ὑπ’ ἀπειρίας, καὶ ἀγροικίας δόξαν ὦφλες.", "st": "33.16"}, {"sp": "N", "t": "ἐπίφθονος δ’ οὖν ἀπὸ τῆς προπόσεως ἐκείνης πολλοῖς τῶν παλαιῶν φίλων γεγένησαι, καὶ πρότερον ἐπὶ τῇ κατακλίσει λυπήσας τινὰς αὐτῶν, ὅτι τήμερον ἥκων προὐκρίθης ἀνδρῶν πολυετῆ δουλείαν ἠντληκότων. εὐθὺς οὖν καὶ τοιοῦτός τις ἐν αὐτοῖς περὶ σοῦ λόγος· “τοῦτο ἡμῖν πρὸς τοῖς ἄλλοις δεινοῖς ἐλείπετο, καὶ τῶν ἄρτι εἰσεληλυθότων εἰς τὴν οἰκίαν δευτέρους εἶναι, καὶ μόνοις τοῖς Ἕλλησι τούτοις ἀνέῳκται ἡ Ῥωμαίων πόλις· καίτοι τί ἐστιν ἐφ’ ὅτῳ προτιμῶνται ἡμῶν; οὐ ῥημάτια δύστηνα λέγοντες οἴονταί τι παμμέγεθες ὠφελεῖν;” ἄλλος δέ, “οὐ γὰρ εἶδες ὅσα μὲν ἔπιεν, ὅπως δὲ τὰ παρατεθέντα συλλαβὼν κατέφαγεν; ἀπειρόκαλος ἄνθρωπος καὶ λιμοῦ πλέως, οὐδ’ ὄναρ λευκοῦ ποτε ἄρτου ἐμφορηθείς, οὔτι γε Νομαδικοῦ ἢ Φασιανοῦ ὄρνιθος, ὧν μόλις τὰ ὀστᾶ ἡμῖν καταλέλοιπεν.” τρίτος ἄλλος, “ὦ μάταιοι,” φησίν, “πέντε οὐδ’ ὅλων ἡμερῶν ὄψεσθε αὐτὸν ἐνταῦθά που ἐν ἡμῖν τὰ ὅμοια ποτνιώμενον· νῦν μὲν γὰρ ὥσπερ τὰ καινὰ τῶν ὑποδημάτων ἐν τιμῇ τινι καὶ ἐπιμελείᾳ ἐστίν, ἐπειδὰν δὲ πατηθῇ πολλάκις καὶ ὑπὸ τοῦ πηλοῦ ἀναπλασθῇ, ὑπὸ τῇ κλίνῃ ἀθλίως ἐρρίψεται κόρεων ὥσπερ ἡμεῖς ἀνάπλεως.”", "st": "33.17"}, {"sp": "N", "t": "Ἐκεῖνοι μὲν οὖν τοιαῦτα πολλὰ περὶ σοῦ στρέφουσι, καί που ἤδη καὶ πρὸς διαβολάς τινες αὐτῶν παρασκευάζονται.", "st": "33.17"}, {"sp": "N", "t": "τὸ δ’ οὖν συμπόσιον ὅλον ἐκεῖνο σόν ἐστιν καὶ περὶ σοῦ οἱ πλεῖστοι τῶν λόγων. σὺ δ’ ὑπ’ ἀηθείας πλέον τοῦ ἱκανοῦ ἐμπιὼν οἴνου λεπτοῦ καὶ δριμέος, πάλαι τῆς γαστρὸς ἐπειγούσης, πονηρῶς ἔχεις, καὶ οὔτε προεξαναστῆναί σοι καλὸν οὔτε μένειν ἀσφαλές. ἀποτεινομένου τοίνυν τοῦ πότου καὶ λόγων ἐπὶ λόγοις γιγνομένων καὶ θεαμάτων ἐπὶ θεάμασι παριόντων — ἅπαντα γὰρ ἐπιδείξασθαί σοι τὰ αὑτοῦ βούλεται — κόλασιν οὐ μικρὰν ὑπομένεις μήτε ὁρῶν τὰ γιγνόμενα μήτε ἀκούων εἴ τις ᾄδει ἢ κιθαρίζει πάνυ τιμώμενος μειρακίσκος, ἀλλ’ ἐπαινεῖς μὲν ὑπ’ ἀνάγκης, εὔχῃ δὲ ἢ σεισμῷ συμπεσεῖν ἐκεῖνα πάντα ἢ πυρκαϊάν τινα προσαγγελθῆναι, ἵνα ποτὲ καὶ διαλυθῇ τὸ συμπόσιον.", "st": "33.18"}, {"sp": "N", "t": "τοῦτο μὲν δή σοι τὸ πρῶτον, ὦ ἑταῖρε, καὶ ἥδιστον ἐκεῖνο δεῖπνον, οὐκ ἔμοιγε τοῦ θύμου καὶ τῶν λευκῶν ἁλῶν ἥδιον ὁπηνίκα βούλομαι καὶ ὁπόσον ἐλευθέρως ἐσθιομένων.", "st": "33.19"}, {"sp": "N", "t": "ἵνα γοῦν σοι τὴν ὀξυρεγμίαν τὴν ἐπὶ τούτοις παρῶ καὶ τὸν ἐν τῇ νυκτὶ ἔμετον, ἕωθεν δεήσει περὶ τοῦ μισθοῦ συμβῆναι ὑμᾶς, ὁπόσον τε καὶ ὁπότε τοῦ ἔτους χρὴ λαμβάνειν. παρόντων οὖν ἢ δύο ἢ τριῶν φίλων προσκαλέσας σε καὶ καθίζεσθαι κελεύσας ἄρχεται λέγειν· “τὰ μὲν ἡμέτερα ὁποῖά ἐστιν ἑώρακας ἤδη, καὶ ὡς τῦφος ἐν αὐτοῖς οὐδὲ εἷς, ἀτραγῴδητα δὲ καὶ πεζὰ πάντα καὶ δημοτικά, χρὴ δέ σε οὕτως ἔχειν ὡς ἁπάντων ἡμῖν κοινῶν ἐσομένων· γελοῖον γὰρ εἰ τὸ κυριώτατον, τὴν ψυχήν σοι τὴν ἐμαυτοῦ ἢ καὶ νὴ Δία τῶν παίδων.” — εἰ παῖδες εἶεν αὐτῷ παιδεύσεως δεόμενοι — “ἐπιτρέπων τῶν ἄλλων μὴ ἐπ’ ἴσης ἡγοίμην δεσπότην. ἐπεὶ δὲ καὶ ὡρίσθαι τι δεῖ, — ὁρῶ μὲν τὸ μέτριον καὶ αὔταρκες τοῦ σοῦ τρόπου καὶ συνίημι ὡς οὐχὶ μισθοῦ ἐλπίδι προσελήλυθας ἡμῶν τῇ οἰκίᾳ, τῶν δὲ ἄλλων ἕνεκα, τῆς εὐνοίας τῆς παρ’ ἡμῶν καὶ τιμῆς, ἣν παρὰ πᾶσιν ἕξεις· ὅμως δ’ οὖν καὶ ὡρίσθω τι, — σὺ δ’ αὐτὸς ὅ τι καὶ βούλει λέγε, μεμνημένος, ὦ φίλτατε, κἀκείνων ἅπερ ἐν ἑορταῖς διετησίοις εἰκὸς ἡμᾶς παρέξειν· οὐ γὰρ ἀμελήσομεν οὐδὲ τῶν τοιούτων, εἰ καὶ μὴ νῦν αὐτὰ συντιθέμεθα· πολλαὶ δέ, οἶσθα, τοῦ ἔτους αἱ τοιαῦται ἀφορμαί. καὶ πρὸς ἐκεῖνα τοίνυν ἀποβλέπων μετριώτερον δῆλον ὅτι ἐπιβαλεῖς ἡμῖν τὸν μισθόν. ἄλλως τε καὶ πρέπον ἂν εἴη τοῖς πεπαιδευμένοις ὑμῖν κρείττοσιν εἶναι χρημάτων.”", "st": "33.19"}, {"sp": "N", "t": "ὁ μὲν ταῦτα εἰπὼν καὶ ὅλον σε διασείσας ταῖς ἐλπίσι τιθασὸν ἑαυτῷ πεποίηκε, σὺ δὲ πάλαι τάλαντα καὶ μυριάδας ὀνειροπολήσας καὶ ἀγροὺς ὅλους καὶ συνοικίας συνίης μὲν ἠρέμα τῆς μικρολογίας, σαίνεις δὲ ὅμως τὴν ὑπόσχεσιν καὶ τό, “πάντα ἡμῖν κοινὰ ἔσται,” βέβαιον καὶ ἀληθὲς ἔσεσθαι νομίζεις, οὐκ εἰδὼς ὅτι τὰ τοιαῦτα<br>χείλεα μέν τ’ ἐδίην’, ὑπερῴην δ’ οὐκ ἐδίηνε.<br>τελευταῖον δ’ ὑπ’ αἰδοῦς αὐτῷ ἐπέτρεψας. ὁ δὲ αὐτὸς μὲν οὔ φησιν ἐρεῖν, τῶν φίλων δέ τινα τῶν παρόντων κελεύει μέσον ἐλθόντα τοῦ πράγματος εἰπεῖν ὃ μήτ’ αὐτῷ γίγνοιτ’ ἂν βαρὺ καὶ πρὸς ἄλλα τούτων ἀναγκαιότερα δαπανῶντι μήτε τῷ ληψομένῳ εὐτελές. ὁ δὲ ὠμογέρων τις ἐκ παίδων κολακείᾳ σύντροφος, “ὡς μὲν οὐκ εὐδαιμονέστατος εἶ”, φησίν, “τῶν ἐν τῇ πόλει ἁπάντων, ὦ οὗτος, οὐκ ἂν εἴποις, ᾧ γε τοῦτο πρῶτον ὑπῆρχεν ὃ πολλοῖς πάνυ γλιχομένοις μόλις ἂν γένοιτο παρὰ τῆς Τύχης· λέγω δὲ ὁμιλίας ἀξιωθῆναι καὶ ἑστίας κοινωνῆσαι καὶ εἰς τὴν πρώτην οἰκίαν τῶν ἐν τῇ Ῥωμαίων ἀρχῇ καταδεχθῆναι· τοῦτο γὰρ ὑπὲρ τὰ Κροίσου τάλαντα καὶ τὸν Μίδου πλοῦτον, εἰ σωφρονεῖν οἶσθα. ἰδὼν δὲ πολλοὺς τῶν εὐδοκίμων ἐθελήσαντας ἄν, εἰ καὶ προσδιδόναι δέοι, μόνης τῆς δόξης ἕνεκα συνεῖναι τούτῳ καὶ ὁρᾶσθαι περὶ αὐτὸν ἑταίρους καὶ φίλους εἶναι δοκοῦντας, οὐκ ἔχω ὅπως σε τῆς εὐποτμίας μακαρίσω, ὃς καὶ προσλήψῃ μισθὸν τῆς τοιαύτης εὐδαιμονίας. ἀρκεῖν οὖν νομίζω, εἰ μὴ πάνυ ἄσωτος εἶ, τοσόνδε τι· —” εἰπὼν ἐλάχιστον καὶ μάλιστα πρὸς τὰς σὰς ἐκείνας ἐλπίδας.", "st": "33.20"}, {"sp": "N", "t": "ἀγαπᾶν δ’ ὅμως ἀναγκαῖον· οὐ γὰρ οὐδ’ ἂν φυγεῖν ἔτι σοι δυνατὸν ἐντὸς ἀρκύων γενομένῳ. δέχῃ τοίνυν τὸν χαλινὸν μύσας καὶ τὰ πρῶτα εὐάγωγος εἶ πρὸς αὐτὸν οὐ πάνυ περισπῶντα οὐδὲ ὀξέως νύττοντα, μέχρι ἂν λάθῃς τέλεον αὐτῷ συνήθης γενόμενος.", "st": "33.21"}, {"sp": "N", "t": "οἱ μὲν δὴ ἔξω ἄνθρωποι τὸ μετὰ τοῦτο ζηλοῦσί σε ὁρῶντες ἐντὸς τῆς κιγκλίδος διατρίβοντα καὶ ἀκωλύτως εἰσιόντα καὶ τῶν πάνυ τινὰ ἔνδον γεγενημένον· σὺ δὲ αὐτὸς οὐδέπω ὁρᾷς οὗτινος ἕνεκα εὐδαίμων αὐτοῖς εἶναι δοκεῖς. πλὴν ἀλλὰ χαίρεις γε καὶ σεαυτὸν ἐξαπατᾷς καὶ ἀεὶ τὰ μέλλοντα βελτίω γενήσεσθαι νομίζεις. τὸ δ’ ἔμπαλιν ἢ σὺ ἤλπισας γίγνεται καὶ ὡς ἡ παροιμία φησίν, ἐπὶ Μανδροβούλου χωρεῖ τὸ πρᾶγμα, καθ’ ἑκάστην, ὡς εἰπεῖν, τὴν ἡμέραν ἀποσμικρυνόμενον καὶ εἰς τοὐπίσω ἀναποδίζον.", "st": "33.21"}, {"sp": "N", "t": "ἠρέμα οὖν καὶ κατ’ ὀλίγον, ὥσπερ ἐν ἀμυδρῷ τῷ φωτὶ τότε πρῶτον διαβλέπων, ἄρχῃ κατανοεῖν ὡς αἱ μὲν χρυσαῖ ἐκεῖναι ἐλπίδες οὐδὲν ἀλλ’ ἢ φῦσαί τινες ἦσαν ἐπίχρυσοι, βαρεῖς δὲ καὶ ἀληθεῖς καὶ ἀπαραίτητοι καὶ συνεχεῖς οἱ πόνοι. “τίνες οὗτοι;” ἴσως ἐρήσῃ με· “οὑχ ὁρῶ γὰρ ὅ τι τὸ ἐπίπονον ἐν ταῖς τοιαύταις συνουσίαις ἐστὶν οὐδ’ ἐπινοῶ ἅτινα ἔφησθα τὰ καματηρὰ καὶ ἀφόρητα.” οὐκοῦν ἄκουσον, ὦ γενναῖε, μὴ εἰ κάματος ἔνεστιν ἐν τῷ πράγματι μόνον ἐξετάζων, ἀλλὰ καὶ τὸ αἰσχρὸν καὶ ταπεινὸν καὶ συνόλως δουλοπρεπὲς οὐκ ἐν παρέργῳ τῆς ἀκροάσεως τιθέμενος.", "st": "33.22"}, {"sp": "N", "t": "καὶ πρῶτόν γε μέμνησο μηκέτι ἐλεύθερον τὸ ἀπ’ ἐκείνου μηδὲ εὐπατρίδην σεαυτὸν οἴεσθαι. πάντα γὰρ ταῦτα, τὸ γένος, τὴν ἐλευθερίαν, τοὺς προγόνους ἔξω τοῦ ὀδοῦ καταλείψων ἴσθι ἐπειδὰν ἐπὶ τοιαύτην σαυτὸν λατρείαν ἀπεμπολήσας εἰσίῃς· οὐ γὰρ ἐθελήσει σοι ἡ Ἐλευθερία συνεισελθεῖν ἐφ’ οὕτως ἀγεννῆ πράγματα καὶ ταπεινὰ εἰσιόντι. δοῦλος οὖν, εἰ καὶ πάνυ ἀχθέσῃ τῷ ὀνόματι, καὶ οὐχ ἑνός, ἀλλὰ πολλῶν δοῦλος ἀναγκαίως ἔσῃ καὶ θητεύσεις κάτω νενευκὼς ἕωθεν εἰς ἑσπέραν “ἀεικελίῳ ἐπὶ μισθῷ.” καὶ ἅτε δὴ μὴ ἐκ παίδων τῇ Δουλείᾳ συντραφείς, ὀψιμαθήσας δὲ καὶ πόρρω που τῆς ἡλικίας παιδευόμενος πρὸς αὐτῆς οὐ πάνυ εὐδόκιμος ἔσῃ οὐδὲ πολλοῦ ἄξιος τῷ δεσπότῃ· διαφθείρει γάρ σε ἡ μνήμη τῆς ἐλευθερίας ὑπιοῦσα καὶ ἀποσκιρτᾶν ἐνίοτε ποιεῖ καὶ δι’ αὐτὸ ἐν τῇ δουλείᾳ πονηρῶς ἀπαλλάττειν.", "st": "33.23"}, {"sp": "N", "t": "πλὴν εἰ μὴ ἀποχρῆν σοι πρὸς ἐλευθερίαν νομίζεις τὸ μὴ Πυρρίου μηδὲ Ζωπυρίωνος υἱὸν εἶναι, μηδὲ ὥσπερ τις Βιθυνὸς ὑπὸ μεγαλοφώνῳ τῷ κήρυκι ἀπημπολῆσθαι. ἀλλ’ ὁπόταν, ὦ βέλτιστε, τῆς νουμηνίας ἐπιστάσης ἀναμιχθεὶς τῷ Πυρρίᾳ καὶ τῷ Ζωπυρίωνι προτείνῃς τὴν χεῖρα ὁμοίως τοῖς ἄλλοις οἰκέταις καὶ λάβῃς ἐκεῖνο ὁτιδήποτε ἦν τὸ γιγνόμενον, τοῦτο ἡ πρᾶσίς ἐστι. κήρυκος γὰρ οὐκ ἔδει ἐπ’ ἄνδρα ἑαυτὸν ἀποκηρύξαντα καὶ μακρῷ χρόνῳ μνηστευσάμενον ἑαυτῷ τὸν δεσπότην.", "st": "33.23"}, {"sp": "N", "t": "εἶτ’, ὦ κάθαρμα, φαίην ἄν, καὶ μάλιστα πρὸς τὸν φιλοσοφεῖν φάσκοντα, εἰ μέν σέ τις ἢ πλέοντα καταποντιστὴς συλλαβὼν ἢ λῃστὴς ἀπεδίδοτο, ᾤκτειρες ἂν σεαυτὸν ὡς παρὰ τὴν ἀξίαν δυστυχοῦντα, ἢ εἴ τίς σου λαβόμενος ἦγε δοῦλον εἶναι λέγων, ἐβόας ἂν τοὺς νόμους καὶ δεινὰ ἐποίεις καὶ ἠγανάκτεις καί, “Ὦ γῆ καὶ θεοί,” μεγάλῃ τῇ φωνῇ ἐκεκράγεις ἄν, σεαυτὸν δὲ ὀλίγων ἕνεκα ὀβολῶν ἐν τούτῳ τῆς ἡλικίας, ὅτε καὶ εἰ φύσει δοῦλος ἦσθα, καιρὸς ἦν πρὸς ἐλευθερίαν ἤδη ὁρᾶν, αὐτῇ ἀρετῇ καὶ σοφίᾳ φέρων ἀπημπόληκας, οὐδὲ τοὺς πολλοὺς ἐκείνους λόγους αἰδεσθεὶς οὓς ὁ καλὸς Πλάτων ἢ ὁ Χρύσιππος ἢ Ἀριστοτέλης διεξεληλύθασι τὸ μὲν ἐλευθέριον ἐπαινοῦντες, τὸ δουλοπρεπὲς δὲ διαβάλλοντες; καὶ οὐκ αἰσχύνῃ κόλαξιν ἀνθρώποις καὶ ἀγοραίοις καὶ βωμολόχοις ἀντεξεταζόμενος καὶ ἐν τοσούτῳ πλήθει Ῥωμαϊκῷ μόνος ξενίζων τῷ τρίβωνι καὶ πονηρῶς τὴν Ῥωμαίων φωνὴν βαρβαρίζων, εἶτα δειπνῶν δεῖπνα θορυβώδη καὶ πολυάνθρωπα συγκλύδων τινῶν καὶ τῶν πλείστων μοχθηρῶν; καὶ ἐν αὐτοῖς ἐπαινεῖς φορτικῶς καὶ πίνεις πέρα τοῦ μετρίως ἔχοντος. ἕωθέν τε ὑπὸ κώδωνι ἐξαναστὰς ἀποσεισάμενος τοῦ ὕπνου τὸ ἥδιστον συμπεριθεῖς ἄνω καὶ κάτω ἔτι τὸν χθιζὸν ἔχων πηλὸν ἐπὶ τοῖν σκελοῖν. οὕτως ἀπορία μέν σε θέρμων ἔσχεν ἢ τῶν ἀγρίων λαχάνων, ἐπέλιπον δὲ καὶ αἱ κρῆναι ῥέουσαι τοῦ ψυχροῦ ὕδατος, ὡς ἐπὶ ταῦτά σε ὑπ’ ἀμηχανίας ἐλθεῖν; ἀλλὰ δῆλον ὡς οὐχ ὕδατος οὐδὲ θέρμων, ἀλλὰ πεμμάτων καὶ ὄψου καὶ οἴνου ἀνθοσμίου ἐπιθυμῶν ἑάλως, καθάπερ ὁ λάβραξ αὐτὸν μάλα δικαίως τὸν ὀρεγόμενον τούτων λαιμὸν διαπαρείς. παρὰ πόδας τοιγαροῦν τῆς λιχνείας ταύτης τἀπίχειρα, καὶ ὥσπερ οἱ πίθηκοι δεθεὶς κλοιῷ τὸν τράχηλον ἄλλοις μὲν γέλωτα παρέχεις, σεαυτῷ δὲ δοκεῖς τρυφᾶν, ὅτι ἔστι σοι τῶν ἰσχάδων ἀφθόνως ἐντραγεῖν. ἡ δὲ ἐλευθερία καὶ τὸ εὐγενὲς αὐτοῖς φυλέταις καὶ φράτερσι φροῦδα πάντα καὶ οὐδὲ μνήμη τις αὐτῶν.", "st": "33.24"}, {"sp": "N", "t": "καὶ ἀγαπητὸν εἰ μόνον τὸ αἰσχρὸν προσῆν τῷ πράγματι, δοῦλον ἀντ’ ἐλευθέρου δοκεῖν, οἱ δὲ πόνοι μὴ κατὰ τοὺς πάνυ τούτους οἰκέτας. ἀλλ’ ὅρα εἰ μετριώτερά σοι προστέτακται τῶν Δρόμωνι καὶ Τιβείῳ προστεταγμένων. ὧν μὲν γὰρ ἕνεκα, τῶν μαθημάτων ἐπιθυμεῖν φήσας, παρείληφέ σε, ὀλίγον αὐτῷ μέλει. “τί γὰρ κοινόν,” φασί, “λύρᾳ καὶ ὄνῳ;” πάνυ γοῦν, — οὐχ ὁρᾷς; — ἐκτετήκασι τῷ πόθῳ τῆς Ὁμήρου σοφίας ἢ τῆς Δημοσθένους δεινότητος ἢ τῆς Πλάτωνος μεγαλοφροσύνης, ὧν ἤν τις ἐκ τῆς ψυχῆς ἀφέλῃ τὸ χρυσίον καὶ τὸ ἀργύριον καὶ τὰς περὶ τούτων φροντίδας, τὸ καταλειπόμενόν ἐστι τῦφος καὶ μαλακία καὶ ἡδυπάθεια καὶ ἀσέλγεια καὶ ὕβρις καὶ ἀπαιδευσία. δεῖται δή σου ἐπ’ ἐκεῖνα μὲν οὐδαμῶς, ἐπεὶ δὲ πώγωνα ἔχεις βαθὺν καὶ σεμνός τις εἶ τὴν πρόσοψιν καὶ ἱμάτιον Ἑλληνικὸν εὐσταλῶς περιβέβλησαι καὶ πάντες ἴσασί σε γραμματικὸν ἢ ῥήτορα ἢ φιλόσοφον, καλὸν αὐτῷ δοκεῖ ἀναμεμῖχθαι καὶ τοιοῦτόν τινα τοῖς προϊοῦσι καὶ προπομπεύουσιν αὐτοῦ· δόξει γὰρ ἐκ τούτου καὶ φιλομαθὴς τῶν Ἑλληνικῶν μαθημάτων καὶ ὅλως περὶ παιδείαν φιλόκαλος. ὥστε κινδυνεύεις, ὦ γενναῖε, ἀντὶ τῶν θαυμαστῶν λόγων τὸν πώγωνα καὶ τὸν τρίβωνα μεμισθωκέναι.", "st": "33.25"}, {"sp": "N", "t": "χρὴ οὖν σε ἀεὶ σὺν αὐτῷ ὁρᾶσθαι καὶ μηδέποτε ἀπολείπεσθαι, ἀλλὰ ἕωθεν ἐξαναστάντα παρέχειν σεαυτὸν ὀφθησόμενον ἐν τῇ θεραπείᾳ καὶ μὴ λιπεῖν τὴν τάξιν. ὁ δὲ ἐπιβάλλων ἐνίοτέ σοι τὴν χεῖρα, ὅ τι ἂν τύχῃ ληρεῖ, τοῖς ἐντυγχάνουσιν ἐπιδεικνύμενος ὡς οὐδὲ ὁδῷ βαδίζων ἀμελής ἐστι τῶν Μουσῶν, ἀλλ’ εἰς καλὸν τὴν ἐν τῷ περιπάτῳ διατίθεται σχολήν.", "st": "33.25"}, {"sp": "N", "t": "σὺ δ’ ἄθλιος τὰ μὲν παραδραμών, τὰ δὲ βάδην ἄναντα πολλὰ καὶ κάταντα — τοιαύτη γάρ, ὡς οἶσθα, ἡ πόλις — περιελθὼν ἵδρωκάς τε καὶ πνευστιᾷς, κἀκείνου ἔνδον τινὶ τῶν φίλων πρὸς ὃν ἦλθεν διαλεγομένου, μηδὲ ὅπου καθίζῃς ἔχων ὀρθὸς ὑπ’ ἀπορίας ἀναγιγνώσκεις τὸ βιβλίον προχειρισάμενος.", "st": "33.26"}, {"sp": "N", "t": "ἐπειδὰν δὲ ἄσιτόν τε καὶ ἄποτον ἡ νὺξ καταλάβῃ, λουσάμενος πονηρῶς ἀωρὶ περὶ αὐτό που σχεδὸν τὸ μεσονύκτιον ἥκεις ἐπὶ τὸ δεῖπνον, οὐκέθ’ ὁμοίως ἔντιμος οὐδὲ περίβλεπτος τοῖς παροῦσιν, ἀλλ’ ἤν τις ἄλλος ἐπεισέλθῃ νεαλέστερος, εἰς τοὐπίσω σύ· καὶ οὕτως εἰς τὴν ἀτιμοτάτην γωνίαν ἐξωσθεὶς κατάκεισαι μάρτυς μόνον τῶν παραφερομένων, τὰ ὀστᾶ, εἰ ἐφίκοιτο μέχρι σοῦ, καθάπερ οἱ κύνες περιεσθίων ἢ τὸ σκληρὸν τῆς μαλάχης φύλλον ᾧ τὰ ἄλλα συνειλοῦσιν, εἰ ὑπεροφθείη ὑπὸ τῶν προκατακειμένων, ἄσμενος ὑπὸ λιμοῦ παροψώμενος.", "st": "33.26"}, {"sp": "N", "t": "Οὐ μὴν οὐδὲ ἡ ἄλλη ὕβρις ἄπεστιν, ἀλλ’ οὔτε ᾠὸν ἔχεις μόνος — οὐ γὰρ ἀναγκαῖόν ἐστιν καὶ σὲ τῶν αὐτῶν ἀεὶ τοῖς ξένοις καὶ ἀγνώστοις ἀντιποιεῖσθαι· ἀγνωμοσύνη γὰρ δὴ τοῦτό γε — οὔτε ἡ ὄρνις ὁμοία ταῖς ἄλλαις, ἀλλὰ τῷ μὲν πλησίον παχεῖα καὶ πιμελής, σοὶ δὲ νεοττὸς ἡμίτομος ἢ φάττα τις ὑπόσκληρος, ὕβρις ἄντικρυς καὶ ἀτιμία. πολλάκις δ’ εἰ ἐπιλίποι ἄλλου τινὸς αἰφνιδίως ἐπιπαρόντος, ἀράμενος ὁ διάκονος τὰ σοὶ παρακείμενα φέρων ἐκείνῳ παρατέθεικεν ὑποτονθορύσας, “σὺ γὰρ ἡμέτερος εἶ.” τεμνομένου μὲν γὰρ ἐν τῷ μέσῳ ἢ συὸς ὑπογαστρίου ἢ ἐλάφου, χρὴ ἐκ παντὸς ἢ τὸν διανέμοντα ἵλεων ἔχειν ἢ τὴν Προμηθέως μερίδα φέρεσθαι, ὀστᾶ κεκαλυμμένα τῇ πιμελῇ. τὸ γὰρ τῷ μὲν ὑπὲρ σὲ τὴν λοπάδα παρεστάναι ἔστ’ ἂν ἀπαγορεύσῃ ἐμφορούμενος, σὲ δὲ οὕτω ταχέως παραδραμεῖν, τίνι φορητὸν ἐλευθέρῳ ἀνδρὶ κἂν ὁπόσην αἱ ἔλαφοι τὴν χολὴν ἔχοντι; καίτοι οὐδέπω ἐκεῖνο ἔφην, ὅτι τῶν ἄλλων ἥδιστόν τε καὶ παλαιότατον οἶνον πινόντων μόνος σὺ πονηρόν τινα καὶ παχὺν πίνεις, θεραπεύων ἀεὶ ἐν ἀργύρῳ ἢ χρυσῷ πίνειν, ὡς μὴ ἐλεγχθείης ἀπὸ τοῦ χρώματος οὕτως ἄτιμος ὢν συμπότης. καὶ εἴθε γε κἂν ἐκείνου εἰς κόρον ἦν πιεῖν, νῦν δὲ πολλάκις αἰτήσαντος ὁ παῖς “οὐδ’ ἀΐοντι ἔοικεν.”", "st": "33.26"}, {"sp": "N", "t": "ἀνιᾷ δή σε πολλὰ καὶ ἀθρόα καὶ σχεδὸν τὰ πάντα, καὶ μάλιστα ὅταν σε παρευδοκιμῇ κίναιδός τις ἢ ὀρχηστοδιδάσκαλος ἢ Ἰωνικὰ συνείρων Ἀλεξανδρεωτικὸς ἀνθρωπίσκος. τοῖς μὲν γὰρ τὰ ἐρωτικὰ ταῦτα διακονουμένοις καὶ γραμματίδια ὑπὸ κόλπου διακομίζουσιν πόθεν σύ γ’ ἰσότιμος; κατακείμενος τοιγαροῦν ἐν μυχῷ τοῦ συμποσίου καὶ ὑπ’ αἰδοῦς καταδεδυκὼς στένεις ὡς τὸ εἰκὸς καὶ σεαυτὸν οἰκτείρεις καὶ αἰτιᾷ τὴν Τύχην οὐδὲ ὀλίγα σοι τῶν χαρίτων ἐπιψεκάσασαν. ἡδέως δ’ ἄν μοι δοκεῖς καὶ ποιητὴς γενέσθαι τῶν ἐρωτικῶν ᾀσμάτων ἢ κἂν ἄλλου ποιήσαντος δύνασθαι ᾄδειν ἀξίως· ὁρᾷς γὰρ οἷ τὸ προτιμᾶσθαι καὶ εὐδοκιμεῖν ἐστιν. ὑποσταίης δὲ ἄν, εἰ καὶ μάγον ἢ μάντιν ὑποκρίνασθαι δέοι τῶν κλήρους πολυταλάντους καὶ ἀρχὰς καὶ ἀθρόους τοὺς πλούτους ὑπισχνουμένων· καὶ γὰρ αὖ καὶ τούτους ὁρᾷς εὖ φερομένους ἐν ταῖς φιλίαις καὶ πολλῶν ἀξιουμένους. κἂν ἕν τι οὖν τούτων ἡδέως ἂν γένοιο, ὡς μὴ ἀπόβλητος καὶ περιττὸς εἴης· ἀλλ’ οὐδὲ πρὸς ταῦτα ὁ κακοδαίμων πιθανὸς εἶ. τοιγαροῦν ἀνάγκη μειοῦσθαι καὶ σιωπῇ ἀνέχεσθαι ὑποιμώζοντα καὶ ἀμελούμενον.", "st": "33.27"}, {"sp": "N", "t": "ἢν μὲν γὰρ κατείπῃ σοῦ τις ψιθυρὸς οἰκέτης, ὡς μόνος οὐκ ἐπῄνεις τὸν τῆς δεσποίνης παιδίσκον ὀρχούμενον ἢ κιθαρίζοντα, κίνδυνος οὐ μικρὸς ἐκ τοῦ πράγματος. χρὴ οὖν χερσαίου βατράχου δίκην διψῶντα κεκραγέναι, ὡς ἐπίσημος ἔσῃ ἐν τοῖς ἐπαινοῦσι καὶ κορυφαῖος ἐπιμελούμενον· πολλάκις δὲ καὶ τῶν ἄλλων σιωπησάντων αὐτὸν ἐπειπεῖν ἐσκεμμένον τινὰ ἔπαινον πολλὴν τὴν κολακείαν ἐμφανιοῦντα.", "st": "33.28"}, {"sp": "N", "t": "τὸ μὲν γὰρ λιμῷ συνόντα καὶ νὴ Δία γε διψῶντα μύρῳ χρίεσθαι καὶ στεφανοῦσθαι τὴν κεφαλήν, ἠρέμα καὶ γελοῖον· ἔοικας γὰρ τότε στήλῃ ἑώλου τινὸς νεκροῦ ἄγοντος ἐναγίσματα· καὶ γὰρ ἐκείνων καταχέαντες μύρον καὶ τὸν στέφανον ἐπιθέντες αὐτοὶ πίνουσι καὶ εὐωχοῦνται τὰ παρεσκευασμένα.", "st": "33.28"}, {"sp": "N", "t": "ἢν μὲν γὰρ καὶ ζηλότυπός τις ᾖ καὶ παῖδες εὔμορφοι ὦσιν ἢ νέα γυνὴ καὶ σὺ μὴ παντελῶς πόρρω Ἀφροδίτης καὶ Χαρίτων ᾖς, οὐκ ἐν εἰρήνῃ τὸ πρᾶγμα οὐδὲ ὁ κίνδυνος εὐκαταφρόνητος. ὦτα γὰρ καὶ ὀφθαλμοὶ βασιλέως πολλοί, οὐ μόνον τἀληθῆ ὁρῶντες, ἀλλ’ ἀεί τι καὶ προσεπιμετροῦντες, ὡς μὴ νυστάζειν δοκοῖεν. δεῖ οὖν ὥσπερ ἐν τοῖς Περσικοῖς δείπνοις κάτω νεύοντα κατακεῖσθαι, δεδιότα μή τις εὐνοῦχός σε ἴδῃ προσβλέψαντα μιᾷ τῶν παλλακίδων, ἐπεὶ ἄλλος γε εὐνοῦχος ἐντεταμένον πάλαι τὸ τόξον ἔχων ἃ μὴ θέμις ὁρῶντα ἕτοιμος κολάσαι, διαπείρας τῷ οἰστῷ μεταξὺ πίνοντος τὴν γνάθον.", "st": "33.29"}, {"sp": "N", "t": "εἶτα ἀπελθὼν τοῦ δείπνου μικρόν τι κατέδαρθες· ὑπὸ δὲ ᾠδὴν ἀλεκτρυόνων ἀνεγρόμενος, “ὢ δείλαιος ἐγώ,” φής, “καὶ ἄθλιος, οἵας τὰς πάλαι διατριβὰς ἀπολιπὼν καὶ ἑταίρους καὶ βίον ἀπράγμονα καὶ ὕπνον μετρούμενον τῇ ἐπιθυμίᾳ καὶ περιπάτους ἐλευθερίους εἰς οἷον βάραθρον φέρων ἐμαυτὸν ἐνσέσεικα. τίνος ἕνεκα, ὦ θεοί, ἢ τίς ὁ λαμπρὸς οὗτος μισθός ἐστιν; οὐ γὰρ καὶ ἄλλως μοι πλείω τούτων ἐκπορίζειν δυνατὸν ἦν καὶ προσῆν τὸ ἐλεύθερον καὶ τὸ πάντα ἐπ’ ἐξουσίας; νῦν δὲ τὸ τοῦ λόγου, λέων κρόκῃ δεθείς, ἄνω καὶ κάτω περισύρομαι, τὸ πάντων οἴκτιστον, οὐκ εὐδοκιμεῖν εἰδὼς οὐδὲ κεχαρισμένος εἶναι δυνάμενος. ἰδιώτης γὰρ ἔγωγε τῶν τοιούτων καὶ ἄτεχνος, καὶ μάλιστα παραβαλλόμενος ἀνδράσι τέχνην τὸ πρᾶγμα πεποιημένοις, ὥστε καὶ ἀχάριστός εἰμι καὶ ἥκιστα συμποτικός, οὐδ’ ὅσον γέλωτα ποιῆσαι δυνάμενος. συνίημι δὲ ὡς καὶ ἐνοχλῶ πολλάκις βλεπόμενος, καὶ μάλισθ’ ὅταν ἡδίων αὐτὸς αὑτοῦ εἶναι θέλῃ· σκυθρωπὸς γὰρ αὐτῷ δοκῶ. καὶ ὅλως οὐκ ἔχω ὅπως ἁρμόσωμαι πρὸς αὐτόν. ἢν μὲν γὰρ ἐπὶ τοῦ σεμνοῦ φυλάττω ἐμαυτόν, ἀηδὴς ἔδοξα καὶ μονονουχὶ φευκτέος· ἢν δὲ μειδιάσω καὶ ῥυθμίσω τὸ πρόσωπον εἰς τὸ ἥδιστον, κατεφρόνησεν εὐθὺς καὶ διέπτυσεν, καὶ τὸ πρᾶγμα ὅμοιον δοκεῖ ὥσπερ ἂν εἴ τις κωμῳδίαν ὑποκρίναιτο τραγικὸν προσωπεῖον περικείμενος. τὸ δ’ ὅλον, τίνα ἄλλον ὁ μάταιος ἐμαυτῷ βιώσομαι βίον τὸν παρόντα τοῦτον ἄλλῳ βεβιωκώς;”", "st": "33.30"}, {"sp": "N", "t": "ἔτι σου ταῦτα διαλογιζομένου ὁ κώδων ἤχησεν, καὶ χρὴ τῶν ὁμοίων ἔχεσθαι καὶ περινοστεῖν καὶ ἑστάναι, ὑπαλείψαντά γε πρότερον τοὺς βουβῶνας καὶ τὰς ἰγνύας, εἰ θέλεις διαρκέσαι πρὸς τὸν ἆθλον. εἶτα δεῖπνον ὅμοιον καὶ εἰς τὴν αὐτὴν ὥραν περιηγμένον. καί σοι τὰ τῆς διαίτης πρὸς τὸν πάλαι βίον ἀντίστροφα, καὶ ἡ ἀγρυπνία δὲ καὶ ὁ ἱδρὼς καὶ ὁ κάματος ἠρέμα ἤδη ὑπορύττουσιν, ἢ φθόην ἢ περιπνευμονίαν ἢ κώλου ἄλγημα ἢ τὴν καλὴν ποδάγραν ἀναπλάττοντες. ἀντέχεις δὲ ὅμως, καὶ πολλάκις κατακεῖσθαι δέον, οὐδὲ τοῦτο συγκεχώρηται· σκῆψις γὰρ ἡ νόσος καὶ φυγὴ τῶν καθηκόντων ἔδοξεν. ὥστ’ ἐξ ἁπάντων ὠχρὸς ἀεὶ καὶ ὅσον οὐδέπω τεθνηξομένῳ ἔοικας.", "st": "33.31"}, {"sp": "N", "t": "καὶ τὰ μὲν ἐν τῇ πόλει ταῦτα. ἢν δέ που καὶ ἀποδημῆσαι δέῃ, τὰ μὲν ἄλλα ἐῶ· ὕοντος δὲ πολλάκις ὕστατος ἐλθὼν — τοιοῦτο γάρ σοι ἀποκεκλήρωται καὶ τὸ ζεῦγος — περιμένεις ἔστ’ ἂν οὐκέτ’ οὔσης καταγωγῆς τῷ μαγείρῳ σε ἢ τῷ τῆς δεσποίνης κομμωτῇ συμπαραβύσωσιν, οὐδὲ τῶν φρυγάνων δαψιλῶς ὑποβαλόντες.", "st": "33.32"}, {"sp": "N", "t": "οὐκ ὀκνῶ δέ σοι καὶ διηγήσασθαι ὅ μοι Θεσμόπολις οὗτος ὁ Στωϊκὸς διηγήσατο συμβὰν αὐτῷ πάνυ γελοῖον καὶ νὴ Δί’ οὐκ ἀνέλπιστον ὡς ἂν καὶ ἄλλῳ ταὐτὸν συμβαίη. συνῆν μὲν γὰρ πλουσίᾳ τινὶ καὶ τρυφώσῃ γυναικὶ τῶν ἐπιφανῶν ἐν τῇ πόλει. δεῆσαν δὲ καὶ ἀποδημῆσαί ποτε, τὸ μὲν πρῶτον ἐκεῖνο παθεῖν ἔφη γελοιότατον, συγκαθέζεσθαι γὰρ αὐτῷ παραδεδόσθαι φιλοσόφῳ ὄντι κίναιδόν τινα τῶν πεπιττωμένων τὰ σκέλη καὶ τὸν πώγωνα περιεξυρημένων· διὰ τιμῆς δ’ αὐτὸν ἐκείνη, ὡς τὸ εἰκός, ἦγεν. καὶ τοὔνομα δὲ τοῦ κιναίδου ἀπεμνημόνευεν· Χελιδόνιον γὰρ καλεῖσθαι. τοῦτο τοίνυν πρῶτον ἡλίκον, σκυθρωπῷ καὶ γέροντι ἀνδρὶ καὶ πολιῷ τὸ γένειον — οἶσθα δὲ ὡς βαθὺν πώγωνα καὶ σεμνὸν ὁ Θεσμόπολις εἶχεν — παρακαθίζεσθαι φῦκος ἐντετριμμένον καὶ ὑπογεγραμμένον τοὺς ὀφθαλμοὺς καὶ διασεσαλευμένον τὸ βλέμμα καὶ τὸν τράχηλον ἐπικεκλασμένον, οὐ χελιδόνα μὰ Δί’, ἀλλὰ γῦπά τινα περιτετιλμένον τὰ πτερά· καὶ εἴ γε μὴ πολλὰ δεηθῆναι αὐτοῦ, καὶ τὸν κεκρύφαλον ἔχοντα ἐπὶ τῇ κεφαλῇ ἂν συγκαθίζεσθαι. τὰ δ’ οὖν ἄλλα παρ’ ὅλην τὴν ὁδὸν μυρίας τὰς ἀηδίας ἀνασχέσθαι ὑπᾴδοντος καὶ τερετίζοντος, εἰ δὲ μὴ ἐπεῖχεν αὐτός, ἴσως ἂν καὶ ὀρχουμένου ἐπὶ τῆς ἀπήνης.", "st": "33.33"}, {"sp": "N", "t": "ἕτερον δ’ οὖν τι καὶ τοιοῦτον αὐτῷ προσταχθῆναι. καλέσασα γὰρ αὐτὸν ἡ γυνή, “Θεσμόπολι,” φησίν, “οὕτως ὄναιο, χάριν οὐ μικρὰν αἰτούσῃ δὸς μηδὲν ἀντειπὼν μηδὲ ὅπως ἐπὶ πλεῖόν σου δεήσομαι περιμείνας.” τοῦ δέ, ὅπερ εἰκὸς ἦν, ὑποσχομένου πάντα πράξειν, “δέομαί σου τοῦτο,” ἔφη, “χρηστὸν ὁρῶσά σε καὶ ἐπιμελῆ καὶ φιλόστοργον, τὴν κύνα ἣν οἶσθα τὴν Μυρρίνην ἀναλαβὼν εἰς τὸ ὄχημα φύλαττέ μοι καὶ ἐπιμελοῦ ὅπως μηδενὸς ἐνδεὴς ἔσται· βαρύνεται γὰρ ἡ ἀθλία τὴν γαστέρα καὶ σχεδὸν ὡς ἐπίτεξ ἐστίν· οἱ δὲ κατάρατοι οὗτοι καὶ ἀπειθεῖς οἰκέται οὐχ ὅπως ἐκείνης, ἀλλ’ οὐδ’ ἐμοῦ αὐτῆς πολὺν ποιοῦνται λόγον ἐν ταῖς ὁδοῖς. μὴ τοίνυν τι σμικρὸν οἰηθῇς εὖ ποιήσειν με τὸ περισπούδαστόν μοι καὶ ἥδιστον κυνίδιον διαφυλάξας.” ὑπέσχετο ὁ Θεσμόπολις πολλὰ ἱκετευούσης καὶ μονονουχὶ καὶ δακρυούσης. τὸ δὲ πρᾶγμα παγγέλοιον ἦν, κυνίδιον ἐκ τοῦ ἱματίου προκῦπτον μικρὸν ὑπὸ τὸν πώγωνα καὶ κατουρῆσαν πολλάκις, εἰ καὶ μὴ ταῦτα ὁ Θεσμόπολις προσετίθει, καὶ βαΰζον λεπτῇ τῇ φωνῇ — τοιαῦτα γὰρ τὰ Μελιταῖα — καὶ τὸ γένειον τοῦ φιλοσόφου περιλιχμώμενον, καὶ μάλιστα εἴ τι τοῦ χθιζοῦ αὐτῷ ζωμοῦ ἐγκατεμέμικτο. καὶ ὅ γε κίναιδος, ὁ σύνεδρος, οὐκ ἀμούσως ποτὲ καὶ εἰς τοὺς ἄλλους τοὺς παρόντας ἐν τῷ συμποσίῳ ἀποσκώπτων, ἐπειδή ποτε καὶ ἐπὶ τὸν Θεσμόπολιν καθῆκε τὸ σκῶμμα, “περὶ δὲ Θεσμοπόλιδος,” ἔφη, “τοῦτο μόνον εἰπεῖν ἔχω, ὅτι ἀντὶ Στωϊκοῦ ἤδη Κυνικὸς ἡμῖν γεγένηται.” τὸ δ’ οὖν κυνίδιον καὶ τετοκέναι ἐν τῷ τρίβωνι τῷ τοῦ Θεσμοπόλιδος ἐπυθόμην.", "st": "33.34"}, {"sp": "N", "t": "τοιαῦτα ἐντρυφῶσι, μᾶλλον δὲ ἐνυβρίζουσι τοῖς συνοῦσι, κατὰ μικρὸν αὐτοὺς χειροήθεις τῇ ὕβρει παρασκευάζοντες. οἶδα δ’ ἐγὼ καὶ ῥήτορα τῶν καρχάρων ἐπὶ τῷ δείπνῳ κελευσθέντα μελετήσαντα μὰ τὸν Δί’ οὐκ ἀπαιδεύτως, ἀλλὰ πάνυ τορῶς καὶ συγκεκροτημένως· ἐπῃνεῖτο γοῦν μεταξὺ πινόντων οὐ πρὸς ὕδωρ μεμετρημένον, ἀλλὰ πρὸς οἴνου ἀμφορέας λέγων, καὶ τοῦτο ὑποστῆναι τὸ τόλμημα ἐπὶ διακοσίαις δραχμαῖς ἐλέγετο.", "st": "33.35"}, {"sp": "N", "t": "ταῦτα μὲν οὖν ἴσως μέτρια. ἢν δὲ ποιητικὸς αὐτὸς ἢ συγγραφικὸς ὁ πλούσιος ᾖ, παρὰ τὸ δεῖπνον τὰ αὑτοῦ ῥαψῳδῶν, τότε καὶ μάλιστα διαρραγῆναι χρὴ ἐπαινοῦντα καὶ κολακεύοντα καὶ τρόπους ἐπαίνων καινοτέρους ἐπινοοῦντα. εἰσὶ δ’ οἳ καὶ ἐπὶ κάλλει θαυμάζεσθαι ἐθέλουσιν, καὶ δεῖ Ἀδώνιδας αὐτοὺς καὶ Ὑακίνθους ἀκούειν, πήχεως ἐνίοτε τὴν ῥῖνα ἔχοντας. σὺ δ’ οὖν ἂν μὴ ἐπαινῇς, εἰς τὰς λιθοτομίας τὰς Διονυσίου εὐθὺς ἀφίξῃ ὡς καὶ φθονῶν καὶ ἐπιβουλεύων αὐτῷ. χρὴ δὲ καὶ σοφοὺς καὶ ῥήτορας εἶναι αὐτούς, κἂν εἴ τι σολοικίσαντες τύχωσιν, αὐτὸ τοῦτο τῆς Ἀττικῆς καὶ τοῦ Ὑμηττοῦ μεστοὺς δοκεῖν τοὺς λόγους καὶ νόμον εἶναι τὸ λοιπὸν οὕτω λέγειν.", "st": "33.35"}, {"sp": "N", "t": "καίτοι φορητὰ ἴσως τὰ τῶν ἀνδρῶν. αἱ δὲ οὖν γυναῖκες — καὶ γὰρ αὖ καὶ τόδε ὑπὸ τῶν γυναικῶν σπουδάζεται, τὸ εἶναί τινας αὐταῖς πεπαιδευμένους μισθοῦ ὑποτελεῖς συνόντας καὶ τῷ φορείῳ ἑπομένους· ἓν γάρ τι καὶ τοῦτο τῶν ἄλλων καλλωπισμάτων αὐταῖς δοκεῖ, ἢν λέγηται ὡς πεπαιδευμέναι τέ εἰσιν καὶ φιλόσοφοι καὶ ποιοῦσιν ᾄσματα οὐ πολὺ τῆς Σαπφοῦς ἀποδέοντα — διὰ δὴ ταῦτα μισθωτοὺς καὶ αὗται περιάγονται ῥήτορας καὶ γραμματικοὺς καὶ φιλοσόφους, ἀκροῶνται δ’ αὐτῶν — πηνίκα; γελοῖον γὰρ καὶ τοῦτο — ἤτοι μεταξὺ κομμούμεναι καὶ τὰς κόμας παραπλεκόμεναι ἢ παρὰ τὸ δεῖπνον· ἄλλοτε γὰρ οὐκ ἄγουσι σχολήν. πολλάκις δὲ καὶ μεταξὺ τοῦ φιλοσόφου τι διεξιόντος ἡ ἅβρα προσελθοῦσα ὤρεξε παρὰ τοῦ μοιχοῦ γραμμάτιον, οἱ δὲ περὶ σωφροσύνης ἐκεῖνοι λόγοι ἑστᾶσι περιμένοντες, ἔστ’ ἂν ἐκείνη ἀντιγράψασα τῷ μοιχῷ ἐπαναδράμῃ πρὸς τὴν ἀκρόασιν.", "st": "33.36"}, {"sp": "N", "t": "ἐπειδὰν δέ ποτε διὰ μακροῦ τοῦ χρόνου Κρονίων ἢ Παναθηναίων ἐπιστάντων πέμπηταί τί σοι ἐφεστρίδιον ἄθλιον ἢ χιτώνιον ὑπόσαθρον, ἐνταῦθα μάλιστα πολλὴν δεῖ καὶ μεγάλην γενέσθαι τὴν πομπήν. καὶ ὁ μὲν πρῶτος εὐθὺς ἔτι σκεπτομένου παρακούσας τοῦ δεσπότου προδραμὼν καὶ προμηνύσας ἀπέρχεται μισθὸν οὐκ ὀλίγον τῆς ἀγγελίας προλαβών. ἕωθεν δὲ τρισκαίδεκα ἥκουσιν κομίζοντες, ἕκαστος ὡς πολλὰ εἶπε καὶ ὡς ὑπέμνησε καὶ ὡς ἐπιτραπεὶς τὸ κάλλιον ἐπελέξατο διεξιών. ἅπαντες δ’ οὖν ἀπαλλάττονται λαβόντες, ἔτι καὶ βρενθυόμενοι ὅτι μὴ πλείω ἔδωκας.", "st": "33.37"}, {"sp": "N", "t": "ὁ μὲν γὰρ μισθὸς αὐτὸς κατὰ δῠ ὀβολοὺς ἢ τέτταρας, καὶ βαρὺς αἰτῶν σὺ καὶ ὀχληρὸς δοκεῖς. ἵνα δ’ οὖν λάβῃς, κολακευτέος μὲν αὐτὸς καὶ ἱκετευτέος, θεραπευτέος δὲ καὶ ὁ οἰκονόμος, οὗτος μὲν κατ’ ἄλλον θεραπείας τρόπον· οὐκ ἀμελητέος δὲ οὐδὲ ὁ σύμβουλος καὶ φίλος. καὶ τὸ ληφθὲν ἤδη προωφείλετο ἱματιοκαπήλῳ ἢ ἰατρῷ ἢ σκυτοτόμῳ τινί. ἄδωρα οὖν σοι τὰ δῶρα καὶ ἀνόνητα.", "st": "33.38"}, {"sp": "N", "t": "πολὺς δὲ ὁ φθόνος, καί που καὶ διαβολή τις ἠρέμα ὑπεξανίσταται πρὸς ἄνδρα ἤδη τοὺς κατὰ σοῦ λόγους ἡδέως ἐνδεχόμενον· ὁρᾷ γὰρ ἤδη σὲ μὲν ὑπὸ τῶν συνεχῶν πόνων ἐκτετρυχωμένον καὶ πρὸς τὴν θεραπείαν σκάζοντα καὶ ἀπηυδηκότα, τὴν ποδάγραν δὲ ὑπανιοῦσαν. ὅλως γὰρ ὅπερ ἦν νοστιμώτατον ἐν σοὶ ἀπανθισάμενος καὶ τὸ ἐγκαρπότατον τῆς ἡλικίας καὶ τὸ ἀκμαιότατον τοῦ σώματος ἐπιτρίψας καὶ ῥάκος σε πολυσχιδὲς ἐργασάμενος ἤδη περιβλέπει, σὲ μὲν οἷ τῆς κόπρου ἀπορρίψει φέρων, ἄλλον δὲ ὅπως τῶν δυναμένων τοὺς πόνους καρτερεῖν προσλήψεται. καὶ ἤτοι μειράκιον αὐτοῦ ὅτι ἐπείρασάς ποτε ἢ τῆς γυναικὸς ἅβραν παρθένον γέρων ἀνὴρ διαφθείρεις ἢ ἄλλο τι τοιοῦτον ἐπικληθείς, νύκτωρ ἐγκεκαλυμμένος ἐπὶ τράχηλον ὠσθεὶς ἐξελήλυθας, ἔρημος ἁπάντων καὶ ἄπορος, τὴν βελτίστην ποδάγραν αὐτῷ γήρᾳ παραλαβών, καὶ ἃ μὲν τέως ᾔδεις ἀπομαθὼν ἐν τοσούτῳ χρόνῳ, θυλάκου δὲ μείζω τὴν γαστέρα ἐργασάμενος, ἀπλήρωτόν τι καὶ ἀπαραίτητον κακόν. καὶ γὰρ ὁ λαιμὸς ἀπαιτεῖ τὰ ἐκ τοῦ ἔθους καὶ ἀπομανθάνων αὐτὰ ἀγανακτεῖ.", "st": "33.39"}, {"sp": "N", "t": "καί σε οὐκ ἄν τις ἄλλος δέξαιτο ἔξωρον ἤδη γεγονότα καὶ τοῖς γεγηρακόσιν ἵπποις ἐοικότα, ὧν οὐδὲ τὸ δέρμα ὁμοίως χρήσιμον. ἄλλως τε καὶ ἡ ἐκ τοῦ ἀπωσθῆναι διαβολὴ πρὸς τὸ μεῖζον εἰκαζομένη μοιχὸν ἢ φαρμακέα σε ἤ τι τοιοῦτον ἄλλο δοκεῖν ποιεῖ· ὁ μὲν γὰρ κατήγορος καὶ σιωπῶν ἀξιόπιστος, σὺ δὲ Ἕλλην καὶ ῥᾴδιος τὸν τρόπον καὶ πρὸς πᾶσαν ἀδικίαν εὔκολος. τοιούτους γὰρ ἅπαντας ἡμᾶς εἶναι οἴονται, καὶ μάλα εἰκότως· δοκῶ γάρ μοι καὶ τῆς τοιαύτης δόξης αὐτῶν, ἣν ἔχουσι περὶ ἡμῶν, κατανενοηκέναι τὴν αἰτίαν. πολλοὶ γὰρ εἰς τὰς οἰκίας παρελθόντες ὑπὲρ τοῦ μηδὲν ἄλλο χρήσιμον εἰδέναι μαντείας καὶ φαρμακείας ὑπέσχοντο καὶ χάριτας ἐπὶ τοῖς ἐρωτικοῖς καὶ ἐπαγωγὰς τοῖς ἐχθροῖς, καὶ ταῦτα πεπαιδεῦσθαι λέγοντες καὶ τρίβωνας ἀμπεχόμενοι καὶ πώγωνας οὐκ εὐκαταφρονήτους καθειμένοι. εἰκότως οὖν τὴν ὁμοίαν περὶ πάντων ὑπόνοιαν ἔχουσιν, οὓς ἀρίστους ᾤοντο τοιούτους ὁρῶντες, καὶ μάλιστα ἐπιτηροῦντες αὐτῶν τὴν ἐν τοῖς δείπνοις καὶ τῇ ἄλλῃ συνουσίᾳ κολακείαν καὶ τὴν πρὸς τὸ κέρδος δουλοπρέπειαν.", "st": "33.40"}, {"sp": "N", "t": "ἀποσεισάμενοι δὲ αὐτοὺς μισοῦσι, καὶ μάλα εἰκότως, καὶ ἐξ ἅπαντος ζητοῦσιν ὅπως ἄρδην ἀπολέσωσιν, ἢν δύνωνται· λογίζονται γὰρ ὡς ἐξαγορεύσουσιν αὐτῶν τὰ πολλὰ ἐκεῖνα τῆς φύσεως ἀπόρρητα ὡς ἅπαντα εἰδότες ἀκριβῶς καὶ γυμνοὺς αὐτοὺς ἐπωπτευκότες. τοῦτο τοίνυν ἀποπνίγει αὐτούς· ἅπαντες γὰρ ἀκριβῶς ὅμοιοί εἰσιν τοῖς καλλίστοις τούτοις βιβλίοις, ὧν χρυσοῖ μὲν οἱ ὀμφαλοί, πορφυρᾶ δὲ ἔκτοσθεν ἡ διφθέρα, τὰ δὲ ἔνδον ἢ Θυέστης ἐστὶν τῶν τέκνων ἑστιώμενος ἢ Οἰδίπους τῇ μητρὶ συνὼν ἢ Τηρεὺς δύο ἀδελφὰς ἅμα ὀπυίων. τοιοῦτοι καὶ αὐτοί εἰσι, λαμπροὶ καὶ περίβλεπτοι, ἔνδον δὲ ὑπὸ τῇ πορφύρᾳ πολλὴν τὴν τραγῳδίαν σκέποντες· ἕκαστον γοῦν αὐτῶν ἢν ἐξειλήσῃς, δρᾶμα οὐ μικρὸν εὑρήσεις Εὐριπίδου τινὸς ἢ Σοφοκλέους, τὰ δ’ ἔξω πορφύρα εὐανθὴς καὶ χρυσοῦς ὁ ὀμφαλός. ταῦτα οὖν συνεπιστάμενοι αὑτοῖς, μισοῦσι καὶ ἐπιβουλεύουσιν εἴ τις ἀποστὰς ἀκριβῶς κατανενοηκὼς αὐτοὺς ἐκτραγῳδήσει καὶ πρὸς πολλοὺς ἐρεῖ.", "st": "33.41"}, {"sp": "N", "t": "βούλομαι δ’ ὅμως ἔγωγε ὥσπερ ὁ Κέβης ἐκεῖνος εἰκόνα τινὰ τοῦ τοιούτου βίου σοι γράψαι, ὅπως εἰς ταύτην ἀποβλέπων εἰδῇς εἴ σοι παριτητέον ἐστὶν εἰς αὐτήν. ἡδέως μὲν οὖν Ἀπελλοῦ τινος ἢ Παρρασίου ἢ Ἀετίωνος ἢ καὶ Εὐφράνορος ἂν ἐδεήθην ἐπὶ τὴν γραφήν· ἐπεὶ δὲ ἄπορον νῦν εὑρεῖν τινα οὕτως γενναῖον καὶ ἀκριβῆ τὴν τέχνην, ψιλὴν ὡς οἷόν τέ σοι ἐπιδείξω τὴν εἰκόνα.", "st": "33.42"}, {"sp": "N", "t": "καὶ δὴ γεγράφθω προπύλαια μὲν ὑψηλὰ καὶ ἐπίχρυσα καὶ μὴ κάτω ἐπὶ τοῦ ἐδάφους, ἀλλ’ ἄνω τῆς γῆς ἐπὶ λόφου κείμενα, καὶ ἡ ἄνοδος ἐπὶ πολὺ καὶ ἀνάντης καὶ ὄλισθον ἔχουσα, ὡς πολλάκις ἤδη πρὸς τῷ ἄκρῳ ἔσεσθαι ἐλπίσαντας ἐκτραχηλισθῆναι διαμαρτόντος τοῦ ποδός. ἔνδον δὲ ὁ Πλοῦτος αὐτὸς καθήσθω χρυσοῦς ὅλος, ὡς δοκεῖ, πάνυ εὔμορφος καὶ ἐπέραστος. ὁ δὲ ἐραστὴς μόλις ἀνελθὼν καὶ πλησιάσας τῇ θύρᾳ τεθηπέτω ἀφορῶν εἰς τὸ χρυσίον. παραλαβοῦσα δ’ αὐτὸν ἡ Ἐλπίς, εὐπρόσωπος καὶ αὕτη καὶ ποικίλα ἀμπεχομένη, εἰσαγέτω σφόδρα ἐκπεπληγμένον τῇ εἰσόδῳ. τοὐντεῦθεν δὲ ἡ μὲν Ἐλπὶς ἀεὶ προηγείσθω, διαδεξάμεναι δ’ αὐτὸν ἄλλαι γυναῖκες, Ἀπάτη καὶ Δουλεία, παραδότωσαν τῷ Πόνῳ, ὁ δὲ πολλὰ τὸν ἄθλιον καταγυμνάσας τελευτῶν ἐγχειρισάτω αὐτὸν τῷ Γήρᾳ ἤδη ὑπονοσοῦντα καὶ τετραμμένον τὴν χρόαν. ὑστάτη δὲ ἡ Ὕβρις ἐπιλαβομένη συρέτω πρὸς τὴν Ἀπόγνωσιν. ἡ δὲ Ἐλπὶς τὸ ἀπὸ τούτου ἀφανὴς ἀποπτέσθω, καὶ μηκέτι καθ’ οὓς εἰσῆλθε τοὺς χρυσοῦς θυρῶνας, ἔκ τινος δὲ ἀποστρόφου καὶ λεληθυίας ἐξόδου ἐξωθείσθω γυμνὸς προγάστωρ ὠχρὸς γέρων, τῇ ἑτέρᾳ μὲν τὴν αἰδῶ σκέπων, τῇ δεξιᾷ δὲ αὐτὸς ἑαυτὸν ἄγχων. ἀπαντάτω δ’ ἐξιόντι ἡ Μετάνοια δακρύουσα εἰς οὐδὲν ὄφελος καὶ τὸν ἄθλιον ἐπαπολλύουσα.", "st": "33.42"}, {"sp": "N", "t": "τοῦτο μὲν ἔστω τὸ τέλος τῆς γραφῆς. σὺ δ’ οὖν, ὦ ἄριστε Τιμόκλεις, αὐτὸς ἤδη ἀκριβῶς ἐπισκοπῶν ἕκαστα ἐννόησον, εἴ σοι καλῶς ἔχει παρελθόντα εἰς τὴν εἰκόνα κατὰ ταύτας τὰς θύρας ἐκείνης τῆς ἔμπαλιν αἰσχρῶς οὕτως ἐκπεσεῖν. ὅ τι δ’ ἂν πράττῃς, μέμνησο τοῦ σοφοῦ λέγοντος ὡς θεὸς ἀναίτιος, αἰτία δὲ ἑλομένου.", "st": "33.42"}, {"sp": "HDR", "t": "Ἀνάχαρσις ἢ Περὶ Γυμνασίων"}, {"sp": "N", "t": "<em>Ἀνάχαρσις.<\/em> ταῦτα δὲ ὑμῖν, ὦ Σόλων, τίνος ἕνεκα οἱ νέοι ποιοῦσιν; οἱ μὲν αὐτῶν περιπλεκόμενοι ἀλλήλους ὑποσκελίζουσιν, οἱ δὲ ἄγχουσι καὶ λυγίζουσι καὶ ἐν τῷ πηλῷ συναναφύρονται κυλινδούμενοι ὥσπερ σύες. καίτοι κατ’ ἀρχὰς εὐθὺς ἀποδυσάμενοι — ἑώρων γάρ — λίπα τε ἠλείψαντο καὶ κατέψησε μάλα εἰρηνικῶς ἅτερος τὸν ἕτερον ἐν τῷ μέρει. μετὰ δὲ οὐκ οἶδ’ ὅ τι παθόντες ὠθοῦσί τε ἀλλήλους συννενευκότες καὶ τὰ μέτωπα συναράττουσιν ὥσπερ οἱ κριοί. καὶ ἢν ἰδοὺ ἀράμενος ἐκεινοσὶ τὸν ἕτερον ἐκ τοῖν σκελοῖν ἀφῆκεν εἰς τὸ ἔδαφος, εἶτ’ ἐπικαταπεσὼν ἀνακύπτειν οὐκ ἐᾷ, συνωθῶν κάτω εἰς τὸν πηλόν· τέλος δὲ ἤδη περιπλέξας αὐτῷ τὰ σκέλη κατὰ τὴν γαστέρα τὸν πῆχυν ὑποβαλὼν τῷ λαιμῷ ἄγχει ἄθλιον, ὁ δὲ παρακροτεῖ εἰς τὸν ὦμον, ἱκετεύων οἶμαι, ὡς μὴ τέλεον ἀποπνιγείη. καὶ οὐδὲ τοῦ ἐλαίου ἕνεκα φείδονται μὴ μολύνεσθαι, ἀλλ’ ἀφανίσαντες τὸ χρῖσμα καὶ τοῦ βορβόρου ἀναπλησθέντες ἐν ἱδρῶτι ἅμα πολλῷ γέλωτα ἐμοὶ γοῦν παρέχουσιν ὥσπερ αἱ ἐγχέλυες ἐκ τῶν χειρῶν διολισθαίνοντες.", "st": "34.1"}, {"sp": "N", "t": "ἕτεροι δὲ ἐν τῷ αἰθρίῳ τῆς αὐλῆς τὸ αὐτὸ τοῦτο δρῶσιν, οὐκ ἐν πηλῷ οὗτοί γε, ἀλλὰ ψάμμον ταύτην βαθεῖαν ὑποβαλόμενοι ἐν τῷ ὀρύγματι πάττουσίν τε ἀλλήλους καὶ αὐτοὶ ἑκόντες ἐπαμῶνται τὴν κόνιν ἀλεκτρυόνων δίκην, ὡς ἀφυκτότεροι εἶεν ἐν ταῖς συμπλοκαῖς, οἶμαι, τῆς ψάμμου τὸν ὄλισθον ἀφαιρούσης καὶ βεβαιοτέραν ἐν ξηρῷ παρεχούσης τὴν ἀντίληψιν.", "st": "34.2"}, {"sp": "N", "t": "οἱ δὲ ὀρθοστάδην κεκονιμένοι καὶ αὐτοὶ παίουσιν ἀλλήλους προσπεσόντες καὶ λακτίζουσιν. οὑτοσὶ γοῦν καὶ τοὺς ὀδόντας ἔοικεν ἀποπτύσειν ὁ κακοδαίμων, οὕτως αἵματος αὐτῷ καὶ ψάμμου ἀναπέπλησται τὸ στόμα, πύξ, ὡς ὁρᾷς, παταχθέντος εἰς τὴν γνάθον. ἀλλ’ οὐδὲ ὁ ἄρχων οὑτοσὶ διίστησιν αὐτοὺς καὶ λύει τὴν μάχην — τεκμαίρομαι γὰρ τῇ πορφυρίδι τῶν ἀρχόντων τινὰ τοῦτον εἶναι — ὁ δὲ καὶ ἐποτρύνει καὶ τὸν πατάξαντα ἐπαινεῖ.", "st": "34.3"}, {"sp": "N", "t": "ἄλλοι δὲ ἀλλαχόθι πάντες ἐγκονοῦσι καὶ ἀναπηδῶσιν ὥσπερ θέοντες ἐπὶ τοῦ αὐτοῦ μένοντες καὶ εἰς τὸ ἄνω συναλλόμενοι λακτίζουσιν τὸν ἀέρα.", "st": "34.4"}, {"sp": "N", "t": "ταῦτα οὖν ἐθέλω εἰδέναι τίνος ἀγαθοῦ ἂν εἴη ποιεῖν· ὡς ἔμοιγε μανίᾳ μᾶλλον ἐοικέναι δοκεῖ τὸ πρᾶγμα, καὶ οὐκ ἔστιν ὅστις ἂν ῥᾳδίως μεταπείσειέ με ὡς οὐ παραπαίουσιν οἱ ταῦτα δρῶντες.", "st": "34.5"}, {"sp": "N", "t": "<em>Σόλων.<\/em> καὶ εἰκότως, ὦ Ἀνάχαρσι, τοιαῦτά σοι τὰ γιγνόμενα φαίνεται, ξένα γε ὄντα καὶ πάμπολυ τῶν Σκυθικῶν ἐθῶν ἀπᾴδοντα, καθάπερ καὶ ὑμῖν πολλὰ εἰκὸς εἶναι μαθήματα καὶ ἐπιτηδεύματα τοῖς Ἕλλησιν ἡμῖν ἀλλόκοτα εἶναι δόξαντα ἄν, εἴ τις ἡμῶν ὥσπερ σὺ νῦν ἐπισταίη αὐτοῖς. πλὴν ἀλλὰ θάρρει, ὦγαθέ· οὐ γὰρ μανία τὰ γιγνόμενά ἐστιν οὐδ’ ἐφ’ ὕβρει οὗτοι παίουσιν ἀλλήλους καὶ κυλίουσιν ἐν τῷ πηλῷ ἢ ἐπιπάττουσιν τὴν κόνιν, ἀλλ’ ἔχει τινὰ χρείαν οὐκ ἀτερπῆ τὸ πρᾶγμα καὶ ἀκμὴν οὐ μικρὰν ἐπάγει τοῖς σώμασιν· ἢν γοῦν ἐνδιατρίψῃς, ὥσπερ οἶμαί σε ποιήσειν, τῇ Ἑλλάδι, οὐκ εἰς μακρὰν εἷς καὶ αὐτὸς ἔσῃ τῶν πεπηλωμένων ἢ κεκονιμένων· οὕτω σοι τὸ πρᾶγμα ἡδύ τε ἅμα καὶ λυσιτελὲς εἶναι δόξει.", "st": "34.6"}, {"sp": "N", "t": "<em>Ἀνάχαρσις.<\/em> ἄπαγε, ὦ Σόλων, ὑμῖν ταῦτα γένοιτο τὰ ὠφέλιμα καὶ τερπνά, ἐμὲ δὲ εἴ τις ὑμῶν τοιοῦτό τι διαθείη, εἴσεται ὡς οὐ μάτην παρεζώσμεθα τὸν ἀκινάκην.", "st": "34.6"}, {"sp": "N", "t": "ἀτὰρ εἰπέ μοι, τί ὄνομα ἔθεσθε τοῖς γιγνομένοις, ἢ τί φῶμεν ποιεῖν αὐτούς;", "st": "34.7"}, {"sp": "N", "t": "<em>Σόλων.<\/em> ὁ μὲν χῶρος αὐτός, ὦ Ἀνάχαρσι, γυμνάσιον ὑφ’ ἡμῶν ὀνομάζεται καὶ ἔστιν ἱερὸν Ἀπόλλωνος τοῦ Λυκείου. καὶ τὸ ἄγαλμα δὲ αὐτοῦ ὁρᾷς, τὸν ἐπὶ τῇ στήλῃ κεκλιμένον, τῇ ἀριστερᾷ μὲν τὸ τόξον ἔχοντα, ἡ δεξιὰ δὲ ὑπὲρ τῆς κεφαλῆς ἀνακεκλασμένη ὥσπερ ἐκ καμάτου μακροῦ ἀναπαυόμενον δείκνυσι τὸν θεόν.", "st": "34.7"}, {"sp": "N", "t": "τῶν γυμνασμάτων δὲ τούτων τὸ μὲν ἐν τῷ πηλῷ ἐκεῖνο πάλη καλεῖται, οἱ δ’ ἐν τῇ κόνει παλαίουσι καὶ αὐτοί, τὸ δὲ παίειν ἀλλήλους ὀρθοστάδην παγκρατιάζειν λέγομεν. καὶ ἄλλα δὲ ἡμῖν ἐστι γυμνάσια τοιαῦτα πυγμῆς καὶ δίσκου καὶ τοῦ ὑπεράλλεσθαι, ὧν ἁπάντων ἀγῶνας προτίθεμεν, καὶ ὁ κρατήσας ἄριστος εἶναι δοκεῖ τῶν καθ’ αὑτὸν καὶ ἀναιρεῖται τὰ ἆθλα.", "st": "34.8"}, {"sp": "N", "t": "<em>Ἀνάχαρσις.<\/em> τὰ δὲ ἆθλα τίνα ὑμῖν ταῦτά ἐστιν;", "st": "34.9"}, {"sp": "N", "t": "<em>Σόλων.<\/em> Ὀλυμπίασι μὲν στέφανος ἐκ κοτίνου, Ἰσθμοῖ δὲ ἐκ πίτυος, ἐν Νεμέᾳ δὲ σελίνων πεπλεγμένος, Πυθοῖ δὲ μῆλα τῶν ἱερῶν τοῦ θεοῦ, παρ’ ἡμῖν δὲ τοῖς Παναθηναίοις τὸ ἔλαιον τὸ ἐκ τῆς μορίας. τί ἐγέλασας, ὦ Ἀνάχαρσι; ἢ διότι μικρά σοι εἶναι ταῦτα δοκεῖ;", "st": "34.9"}, {"sp": "N", "t": "<em>Ἀνάχαρσις.<\/em> οὔκ, ἀλλὰ πάνσεμνα, ὦ Σόλων, κατέλεξας τὰ ἆθλα καὶ ἄξια τοῖς τε διαθεῖσιν αὐτὰ φιλοτιμεῖσθαι ἐπὶ τῇ μεγαλοδωρεᾷ καὶ τοῖς ἀγωνισταῖς αὐτοῖς ὑπερεσπουδακέναι περὶ τὴν ἀναίρεσιν τῶν τηλικούτων, ὥστε μήλων ἕνεκα καὶ σελίνων τοσαῦτα προπονεῖν καὶ κινδυνεύειν ἀγχομένους πρὸς ἀλλήλων καὶ κατακλωμένους, ὡς οὐκ ἐνὸν ἀπραγμόνως εὐπορῆσαι μήλων ὅτῳ ἐπιθυμία ἢ σελίνῳ ἐστεφανῶσθαι ἢ πίτυϊ μήτε πηλῷ καταχριόμενον τὸ πρόσωπον μήτε λακτιζόμενον εἰς τὴν γαστέρα ὑπὸ τῶν ἀνταγωνιστῶν.", "st": "34.9"}, {"sp": "N", "t": "<em>Σόλων.<\/em> ἀλλ’, ὦ ἄριστε, οὐκ εἰς ψιλὰ τὰ διδόμενα ἡμεῖς ἀποβλέπομεν. ταῦτα μὲν γάρ ἐστι σημεῖα τῆς νίκης καὶ γνωρίσματα οἵτινες οἱ κρατήσαντες. ἡ δὲ παρακολουθοῦσα τούτοις δόξα τοῦ παντὸς ἀξία τοῖς νενικηκόσιν, ὑπὲρ ἧς καὶ λακτίζεσθαι καλῶς ἔχει τοῖς θηρωμένοις τὴν εὔκλειαν ἐκ τῶν πόνων. οὐ γὰρ ἀπονητὶ προσγένοιτο ἂν αὕτη, ἀλλὰ χρὴ τὸν ὀρεγόμενον αὐτῆς πολλὰ τὰ δυσχερῆ ἀνασχόμενον ἐν τῇ ἀρχῇ τότ’ ἤδη τὸ λυσιτελὲς καὶ ἡδὺ τέλος ἐκ τῶν καμάτων περιμένειν.", "st": "34.10"}, {"sp": "N", "t": "<em>Ἀνάχαρσις.<\/em> τοῦτο φής, ὦ Σόλων, τὸ τέλος ἡδὺ καὶ λυσιτελές, ὅτι πάντες αὐτοὺς ὄψονται ἐστεφανωμένους καὶ ἐπὶ τῇ νίκῃ ἐπαινέσονται πολὺ πρότερον οἰκτείραντες ἐπὶ ταῖς πληγαῖς, οἱ δὲ εὐδαιμονήσουσιν ἀντὶ τῶν πόνων μῆλα καὶ σέλινα ἔχοντες.", "st": "34.10"}, {"sp": "N", "t": "<em>Σόλων.<\/em> ἄπειρος εἶ, φημί, τῶν ἡμετέρων ἔτι· μετὰ μικρὸν δὲ ἄλλα σοι δόξει περὶ αὐτῶν, ἐπειδὰν εἰς τὰς πανηγύρεις ἀπιὼν ὁρᾷς τοσοῦτο πλῆθος ἀνθρώπων συλλεγόμενον ἐπὶ τὴν θέαν τῶν τοιούτων καὶ θέατρα μυρίανδρα συμπληρούμενα καὶ τοὺς ἀγωνιστὰς ἐπαινουμένους, τὸν δὲ καὶ νικήσαντα αὐτῶν ἰσόθεον νομιζόμενον.", "st": "34.10"}, {"sp": "N", "t": "<em>Ἀνάχαρσις.<\/em> αὐτὸ τοῦτο, ὦ Σόλων, καὶ τὸ οἴκτιστόν ἐστιν, εἰ μὴ ἐπ’ ὀλίγων ταῦτα πάσχουσιν, ἀλλὰ ἐν τοσούτοις θεαταῖς καὶ μάρτυσι τῆς ὕβρεως, οἳ δηλαδὴ εὐδαιμονίζουσιν αὐτοὺς αἵματι ῥαινομένους ὁρῶντες ἢ ἀγχομένους ὑπὸ τῶν ἀντιπάλων· ταῦτα γὰρ τὰ εὐδαιμονέστατα πρόσεστι τῇ νίκῃ αὐτῶν. παρ’ ἡμῖν δὲ τοῖς Σκύθαις ἤν τις, ὦ Σόλων, ἢ πατάξῃ τινὰ τῶν πολιτῶν ἢ ἀνατρέψῃ προσπεσὼν ἢ θοἰμάτια περιρρήξῃ, μεγάλας οἱ πρεσβῦται τὰς ζημίας ἐπάγουσι, κἂν ἐπ’ ὀλίγων μαρτύρων τοῦτο πάθῃ τις, οὔτι γε ἐν τηλικούτοις θεάτροις, οἷα σὺ διηγῇ τὸ Ἰσθμοῖ καὶ τὸ ἐν Ὀλυμπίᾳ. οὐ μὴν ἀλλὰ τοὺς μὲν ἀγωνιστὰς οἰκτείρειν μοι ἔπεισιν ὧν πάσχουσιν, τῶν δὲ θεατῶν οὓς φὴς ἁπανταχόθεν τοὺς ἀρίστους παραγίγνεσθαι εἰς τὰς πανηγύρεις καὶ πάνυ θαυμάζω, εἰ τἀναγκαῖα παρέντες σχολάζουσιν ἐπὶ τοῖς τοιούτοις. οὐδὲ γὰρ ἐκεῖνό πω δύναμαι κατανοῆσαι ὅ τι τὸ τερπνὸν αὐτοῖς, ὁρᾶν παιομένους τε καὶ διαπληκτιζομένους ἀνθρώπους καὶ πρὸς τὴν γῆν ἀραττομένους καὶ συντριβομένους ὑπ’ ἀλλήλων.", "st": "34.11"}, {"sp": "N", "t": "<em>Σόλων.<\/em> εἰ καιρὸς ἦν, ὦ Ἀνάχαρσι, Ὀλυμπίων ἢ Ἰσθμίων ἢ Παναθηναίων, αὐτὸ ἄν σε τὸ γιγνόμενον ἐδίδαξεν ὡς οὐ μάτην ἐσπουδάκαμεν ἐπὶ τούτοις. οὐ γὰρ οὕτω λέγων ἄν τις προσβιβάσειέν σε τῇ ἡδονῇ τῶν ἐκεῖ δρωμένων, ὡς εἰ καθεζόμενος αὐτὸς ἐν μέσοις τοῖς θεαταῖς βλέποις ἀρετὰς ἀνδρῶν καὶ κάλλη σωμάτων καὶ εὐεξίας θαυμαστὰς καὶ ἐμπειρίας δεινὰς καὶ ἰσχὺν ἄμαχον καὶ τόλμαν καὶ φιλοτιμίαν καὶ γνώμας ἀηττήτους καὶ σπουδὴν ἄλεκτον ὑπὲρ τῆς νίκης. εὖ γὰρ δὴ οἶδα ὡς οὐκ ἂν ἐπαύσω ἐπαινῶν καὶ ἐπιβοῶν καὶ ἐπικροτῶν.", "st": "34.12"}, {"sp": "N", "t": "<em>Ἀνάχαρσις.<\/em> νὴ Δί’, ὦ Σόλων, καὶ ἐπιγελῶν γε προσέτι καὶ ἐπιχλευάζων· ἅπαντα γὰρ ὁπόσα κατηριθμήσω ἐκεῖνα, τὰς ἀρετὰς καὶ τὰς εὐεξίας καὶ τὰ κάλλη καὶ τόλμαν, ὁρῶ οὐδενὸς μεγάλου ἕνεκα παραπολλυμένας ὑμῖν, οὔτε πατρίδος κινδυνευούσης οὔτε χώρας πορθουμένης οὔτε φίλων ἢ οἰκείων πρὸς ὕβριν ἀπαγομένων. ὥστε τοσούτῳ γελοιότεροι ἂν εἶεν, ἄριστοι μέν, ὡς φής, ὄντες, μάτην δὲ τοσαῦτα πάσχοντες καὶ ταλαιπωρούμενοι καὶ αἰσχύνοντες τὰ κάλλη καὶ τὰ μεγέθη τῇ ψάμμῳ καὶ τοῖς ὑπωπίοις, ὡς μήλου καὶ κοτίνου ἐγκρατεῖς γένοιντο νικήσαντες. ἡδὺ γάρ μοι ἀεὶ μεμνῆσθαι τῶν ἄθλων τοιούτων ὄντων. ἀτὰρ εἰπέ μοι, πάντες αὐτὰ λαμβάνουσιν οἱ ἀγωνισταί;", "st": "34.13"}, {"sp": "N", "t": "<em>Σόλων.<\/em> οὐδαμῶς, ἀλλὰ εἷς ἐξ ἁπάντων, ὁ κρατήσας αὐτῶν.", "st": "34.13"}, {"sp": "N", "t": "<em>Ἀνάχαρσις.<\/em> εἶτα, ὦ Σόλων, ἐπὶ τῷ ἀδήλῳ καὶ ἀμφιβόλῳ τῆς νίκης τοσοῦτοι πονοῦσι, καὶ ταῦτ’ εἰδότες ὅτι ὁ μὲν νικῶν εἷς ἔσται πάντως, οἱ δὲ ἡττώμενοι πάμπολλοι, μάτην ἄθλιοι πληγάς, οἱ δὲ καὶ τραύματα λαβόντες;", "st": "34.13"}, {"sp": "N", "t": "<em>Σόλων.<\/em> ἔοικας, ὦ Ἀνάχαρσι, μηδέπω ἐννενοηκέναι πολιτείας ὀρθῆς πέρι μηδέν· οὐ γὰρ ἂν τὰ κάλλιστα τῶν ἐθῶν ἐν ψόγῳ ἐτίθεσο. ἢν δέ σοι μελήσῃ ποτὲ εἰδέναι ὅπως ἂν τὰ κάλλιστα οἰκηθείη πόλις καὶ ὅπως ἂν ἄριστοι γένοιντο οἱ πολῖται αὐτῆς, ἐπαινέσῃ τότε καὶ τὰς ἀσκήσεις ταύτας καὶ τὴν φιλοτιμίαν ἣν φιλοτιμούμεθα περὶ αὐτάς, καὶ εἴσῃ ὅτι πολὺ τὸ χρήσιμον ἔχουσιν ἐγκαταμεμιγμένον τοῖς πόνοις, εἰ καὶ νῦν μάτην σπουδάζεσθαι δοκοῦσιν.", "st": "34.14"}, {"sp": "N", "t": "<em>Ἀνάχαρσις.<\/em> καὶ μήν, ὦ Σόλων, κατ’ οὐδὲν ἄλλο ἀπὸ τῆς Σκυθίας ἥκω παρ’ ὑμᾶς τοσαύτην μὲν γῆν διοδεύσας, μέγαν δὲ τὸν Εὔξεινον καὶ δυσχείμερον περαιωθείς, ἢ ὅπως νόμους τε τοὺς Ἑλλήνων ἐκμάθοιμι καὶ ἔθη τὰ παρ’ ὑμῖν κατανοήσαιμι καὶ πολιτείαν τὴν ἀρίστην ἐκμελετήσαιμι. διὸ καὶ σὲ μάλιστα φίλον ἐξ ἁπάντων Ἀθηναίων καὶ ξένον προειλόμην κατὰ κλέος, ἐπείπερ ἤκουον νόμων τε συγγραφέα τινὰ εἶναι σε καὶ ἐθῶν τῶν ἀρίστων εὑρετὴν καὶ ἐπιτηδευμάτων ὠφελίμων εἰσηγητήν, καὶ ὅλως πολιτείας τινὸς συναρμοστήν. ὥστε οὐκ ἂν φθάνοις διδάσκων με καὶ μαθητὴν ποιούμενος· ὡς ἔγωγε ἡδέως ἂν ἄσιτός σοι καὶ ἄποτος παρακαθεζόμενος, εἰς ὅσον ἂν αὐτὸς διαρκοίης λέγων, κεχηνὼς ἐπακούοιμι περὶ πολιτείας τε καὶ νόμων διεξιόντος.", "st": "34.14"}, {"sp": "N", "t": "<em>Σόλων.<\/em> τὰ μὲν πάντα οὐ ῥᾴδιον, ὦ ἑταῖρε, διελθεῖν ἐν βραχεῖ, ἀλλὰ κατὰ μέρη ἐπιὼν εἴσῃ ἕκαστα, οἷα μὲν περὶ θεῶν, οἷα δὲ περὶ γονέων ἢ περὶ γάμων ἢ τῶν ἄλλων δοκεῖ ἡμῖν. ἃ δὲ περὶ τῶν νέων γιγνώσκομεν καὶ ὅπως αὐτοῖς χρώμεθα, ἐπειδὰν πρῶτον ἄρξωνται συνιέναι τε τοῦ βελτίονος καὶ τῷ σώματι ἀνδρίζεσθαι καὶ ὑφίστασθαι τοὺς πόνους, ταῦτα ἤδη σοι διέξειμι, ὡς μάθοις οὗτινος χάριν τὰς ἀσκήσεις ταύτας προτεθείκαμεν αὐτοῖς καὶ διαπονεῖν τὸ σῶμα καταναγκάζομεν, οὐ μόνον ἕνεκα τῶν ἀγώνων, ὅπως τὰ ἆθλα δύναιντο ἀναιρεῖσθαι — ἐπ’ ἐκεῖνα μὲν γὰρ ὀλίγοι πάνυ ἐξ ἁπάντων χωροῦσιν — ἀλλὰ μεῖζόν τι ἁπάσῃ τῇ πόλει ἀγαθὸν ἐκ τούτου καὶ αὐτοῖς ἐκείνοις προσκτώμενοι. κοινὸς γάρ τις ἀγὼν ἄλλος ἅπασι τοῖς ἀγαθοῖς πολίταις πρόκειται καὶ στέφανος οὐ πίτυος οὐδὲ κοτίνου ἢ σελίνων, ἀλλ’ ὃς ἐν αὑτῷ συλλαβὼν ἔχει τὴν ἀνθρώπου εὐδαιμονίαν, οἷον ἐλευθερίαν λέγω αὐτοῦ τε ἑκάστου ἰδίᾳ καὶ κοινῇ τῆς πατρίδος καὶ πλοῦτον καὶ δόξαν καὶ ἑορτῶν πατρίων ἀπόλαυσιν καὶ οἰκείων σωτηρίαν, καὶ συνόλως τὰ κάλλιστα ὧν ἄν τις εὔξαιτο γενέσθαι οἱ παρὰ τῶν θεῶν. ταῦτα πάντα τῷ στεφάνῳ ὅν φημι συναναπέπλεκται καὶ ἐκ τοῦ ἀγῶνος ἐκείνου περιγίγνεται ἐφ’ ὃν αἱ ἀσκήσεις αὗται καὶ οἱ πόνοι ἄγουσιν.", "st": "34.15"}, {"sp": "N", "t": "<em>Ἀνάχαρσις.<\/em> εἶτα, ὦ θαυμάσιε Σόλων, τοιαῦτά μοι καὶ τηλικαῦτα ἔχων ἆθλα διεξιέναι, μῆλα καὶ σέλινα διηγοῦ καὶ θαλλὸν ἐλαίας ἀγρίας καὶ πίτυν;", "st": "34.16"}, {"sp": "N", "t": "<em>Σόλων.<\/em> καὶ μήν, ὦ Ἀνάχαρσι, οὐδ’ ἐκεῖνά σοι ἔτι δόξει μικρὰ εἶναι, ὁπόταν ἃ λέγω καταμάθῃς· ἀπὸ γάρ τοι τῆς αὐτῆς γνώμης γίγνεται, καὶ μέρη πάντα ταῦτά ἐστι μικρὰ τοῦ μείζονος ἐκείνου ἀγῶνος καὶ τοῦ στεφάνου ὃν κατέλεξα τοῦ πανευδαίμονος. ὁ δὲ λόγος, οὐκ οἶδ’ ὅπως ὑπερβὰς τὴν τάξιν, ἐκείνων πρότερον ἐπεμνήσθη τῶν Ἰσθμοῖ γιγνομένων καὶ Ὀλυμπίασι καὶ ἐν Νεμέᾳ. πλὴν ἀλλὰ νώ — σχολὴν γὰρ ἄγομεν καὶ σύ, ὡς φής, προθυμῇ ἀκούειν — ἀναδραμούμεθα ῥᾳδίως πρὸς τὴν ἀρχὴν καὶ τὸν κοινὸν ἀγῶνα δι’ ὅν φημι πάντα ταῦτα ἐπιτηδεύεσθαι.", "st": "34.16"}, {"sp": "N", "t": "<em>Ἀνάχαρσις.<\/em> ἄμεινον, ὦ Σόλων, οὕτως· καθ’ ὁδὸν γὰρ ἂν ἡμῖν ὁ λόγος μᾶλλον προχωροίη, καὶ τάχ’ ἂν ἴσως ἀπὸ τούτων πεισθείην μηδὲ ἐκείνων ἔτι καταγελᾶν, εἴ τινα ἴδοιμι σεμνυνόμενον κοτίνῳ ἢ σελίνῳ ἐστεφανωμένον. ἀλλ’ εἰ δοκεῖ, εἰς τὸ σύσκιον ἐκεῖσε ἀπελθόντες καθίσωμεν ἐπὶ τῶν θάκων, ὡς μὴ ἐνοχλοῖεν ἡμῖν οἱ ἐπικεκραγότες τοῖς παλαίουσιν. ἄλλως τε — εἰρήσεται γάρ — οὐδὲ τὸν ἥλιον ἔτι ῥᾳδίως ἀνέχομαι ὀξὺν καὶ φλογμώδη ἐμπίπτοντα γυμνῇ τῇ κεφαλῇ. τὸν γὰρ πῖλόν μοι ἀφελεῖν οἴκοθεν ἔδοξεν, ὡς μὴ μόνος ἐν ὑμῖν ξενίζοιμι τῷ σχήματι. ἡ δὲ ὥρα τοῦ ἔτους ὅ τι περ τὸ πυρωδέστατόν ἐστι, τοῦ ἀστέρος ὃν ὑμεῖς κύνα φατὲ πάντα καταφλέγοντος καὶ τὸν ἀέρα ξηρὸν καὶ διακαῆ τιθέντος, ὅ τε ἥλιος κατὰ μεσημβρίαν ἤδη ὑπὲρ κεφαλῆς ἐπικείμενος φλογμὸν τοῦτον οὐ φορητὸν ἐπάγει τοῖς σώμασιν. ὥστε καὶ σοῦ θαυμάζω, ὅπως γηραιὸς ἤδη ἄνθρωπος οὔτε ἰδίεις πρὸς τὸ θάλπος ὥσπερ ἐγὼ οὔτε ὅλως ἐνοχλουμένῳ ἔοικας, οὐδὲ περιβλέπεις σύσκιόν τι ἔνθα ὑποδύσῃ, ἀλλὰ δέχῃ τὸν ἥλιον εὐμαρῶς.", "st": "34.16"}, {"sp": "N", "t": "<em>Σόλων.<\/em> οἱ μάταιοι γὰρ οὗτοι πόνοι, ὦ Ἀνάχαρσι, καὶ αἱ συνεχεῖς ἐν τῷ πηλῷ κυβιστήσεις καὶ αἱ ὕπαιθροι ἐν τῇ ψάμμῳ ταλαιπωρίαι τοῦτο ἡμῖν τὸ ἀμυντήριον παρέχουσι πρὸς τὰς τοῦ ἡλίου βολάς, καὶ οὐκέτι πίλου δεόμεθα ὃς τὴν ἀκτῖνα κωλύσει καθικνεῖσθαι τῆς κεφαλῆς.", "st": "34.16"}, {"sp": "N", "t": "ἀπίωμεν δ’ οὖν. καὶ ὅπως μὴ καθάπερ νόμοις προσέξεις οἷς ἂν λέγω πρὸς σέ, ὡς ἐξ ἅπαντος πιστεύειν αὐτοῖς, ἀλλ’ ἔνθα ἄν σοι μὴ ὀρθῶς τι λέγεσθαι δοκῇ, ἀντιλέγειν εὐθὺς καὶ διευθύνειν τὸν λόγον. δυοῖν γὰρ θατέρου πάντως οὐκ ἂν ἁμάρτοιμεν, ἢ σὲ βεβαίως πεισθῆναι ἐκχέαντα ὁπόσα οἴει ἀντιλεκτέα εἶναι ἢ ἐμὲ ἀναδιδαχθῆναι ὡς οὐκ ὀρθῶς γιγνώσκω περὶ αὐτῶν. καὶ ἐν τούτῳ πᾶσα ἄν σοι ἡ πόλις ἡ Ἀθηναίων οὐκ ἂν φθάνοι χάριν ὁμολογοῦσα· ὅσα γὰρ ἂν ἐμὲ παιδεύσῃς καὶ μεταπείσῃς πρὸς τὸ βέλτιον, ἐκείνην τὰ μέγιστα ἔσῃ ὠφεληκώς. οὐδὲν γὰρ ἂν ἀποκρυψαίμην αὐτήν, ἀλλ’ εὐθὺς εἰς τὸ μέσον καταθήσω φέρων καὶ καταστὰς ἐν τῇ πνυκὶ ἐρῶ πρὸς ἅπαντας, “ἄνδρες ‘Ἀθηναῖοι, ἐγὼ μὲν ὑμῖν ἔγραψα τοὺς νόμους οἵους ᾤμην ὠφελιμωτάτους ἔσεσθαι τῇ πόλει, ὁ δὲ ξένος οὑτοσί’ —” δείξας σέ, ὦ Ἀνάχαρσι — “Σκύθης μέν ἐστι, σοφὸς δὲ ὢν μετεπαίδευσέ με καὶ ἄλλα βελτίω μαθήματα καὶ ἐπιτηδεύματα ἐδιδάξατο· ὥστε εὐεργέτης ὑμῶν ὁ ἀνὴρ ἀναγεγράφθω καὶ χαλκοῦν αὐτὸν ἀναστήσατε παρὰ τοὺς ἐπωνύμους ἢ ἐν πόλει παρὰ τὴν Ἀθηνᾶν.” καὶ εὖ ἴσθι ὡς οὐκ αἰσχυνεῖται ἡ Ἀθηναίων πόλις παρὰ βαρβάρου καὶ ξένου τὰ συμφέροντα ἐκμανθάνοντες.", "st": "34.17"}, {"sp": "N", "t": "<em>Ἀνάχαρσις.<\/em> τοῦτ’ ἐκεῖνο ἦν ἄρα, ὃ ἐγὼ περὶ ὑμῶν ἤκουον τῶν Ἀθηναίων, ὡς εἴητε εἴρωνες ἐν τοῖς λόγοις. ἐπεὶ πόθεν ἂν ἐγὼ νομὰς καὶ πλάνης ἄνθρωπος, ἐφ’ ἁμάξης βεβιωκώς, ἄλλοτε ἄλλην γῆν ἀμείβων, πόλιν δὲ οὔτε οἰκήσας πώποτε οὔτε ἄλλοτε ἢ νῦν ἑωρακώς, περὶ πολιτείας διεξίοιμι καὶ διδάσκοιμι αὐτόχθονας ἄνδρας πόλιν ταύτην ἀρχαιοτάτην τοσούτοις ἤδη χρόνοις ἐν εὐνομίᾳ κατῳκηκότας, καὶ μάλιστα σέ, ὦ Σόλων, ᾧ τοῦτο ἐξ ἀρχῆς καὶ μάθημα, ὡς φασίν, ἐγένετο, ἐπίστασθαι ὅπως ἂν ἄριστα πόλις οἰκοῖτο καὶ οἷστισιν νόμοις χρωμένη εὐδαιμονήσειε; πλὴν ἀλλὰ καὶ τοῦτο ὡς νομοθέτῃ πειστέον σοι, καὶ ἀντερῶ ἤν τί μοι δοκῇ μὴ ὀρθῶς λέγεσθαι, ὡς βεβαιότερον μάθοιμι.", "st": "34.18"}, {"sp": "N", "t": "καὶ ἰδοὺ γὰρ ἤδη ἐκφυγόντες τὸν ἥλιον ἐν τῷ συνηρεφεῖ ἐσμεν, καὶ καθέδρα μάλα ἡδεῖα καὶ εὔκαιρος ἐπὶ ψυχροῦ τοῦ λίθου. λέγε οὖν τὸν λόγον ἐξ ἀρχῆς καθ’ ὅ τι τοὺς νέους παραλαβόντες ἐκ παίδων εὐθὺς διαπονεῖτε, καὶ ὅπως ὑμῖν ἄριστοι ἄνδρες ἀποβαίνουσιν ἐκ τοῦ πηλοῦ καὶ τῶν ἀσκημάτων τούτων, καὶ τί ἡ κόνις καὶ τὰ κυβιστήματα συντελεῖ πρὸς ἀρετὴν αὐτοῖς. τοῦτο γὰρ δὴ μάλιστα ἐξ ἀρχῆς εὐθὺς ἐπόθουν ἀκοῦσαι· τὰ δ’ ἄλλα εἰς ὕστερον διδάξῃ με κατὰ καιρὸν ἕκαστον ἐν τῷ μέρει. ἐκείνου μέντοι, ὦ Σόλων, μέμνησό μοι παρὰ τὴν ῥῆσιν, ὅτι πρὸς ἄνδρα βάρβαρον ἐρεῖς. λέγω δὲ ὡς μὴ περιπλέκῃς μηδὲ ἀπομηκύνῃς τοὺς λόγους· δέδια γὰρ μὴ ἐπιλανθάνωμαι τῶν πρώτων, εἰ τὰ μετὰ ταῦτα πολλὰ ἐπιρρέοι.", "st": "34.18"}, {"sp": "N", "t": "<em>Σόλων.<\/em> σὺ τοῦτο, ὦ Ἀνάχαρσι, ταμιεύσῃ ἄμεινον, ἔνθα ἄν σοι δοκῇ μὴ πάνυ σαφὴς ὁ λόγος εἶναι ἢ πόρρω ποι ἀποπλανᾶσθαι εἰκῆ ῥέων· ἐρήσῃ γὰρ μεταξὺ ὅ τι ἂν ἐθέλῃς καὶ διακόψεις αὐτοῦ τὸ μῆκος. ἢν μέντοι μὴ ἐξαγώνια μηδὲ πόρρω τοῦ σκοποῦ τὰ λεγόμενα ᾖ, κωλύσει οὐδέν, οἶμαι, εἰ καὶ μακρὰ λέγοιτο, ἐπεὶ καὶ τῇ βουλῇ τῇ ἐξ Ἀρείου πάγου, ἥπερ τὰς φονικὰς ἡμῖν δίκας δικάζει, πάτριον οὕτω ποιεῖν. ὁπόταν γὰρ ἀνελθοῦσα εἰς τὸν πάγον συγκαθέζηται φόνου ἢ τραύματος ἐκ προνοίας ἢ πυρκαϊᾶς δικάσοντες, ἀποδίδοται λόγος ἑκατέρῳ τῶν κρινομένων καὶ λέγουσιν ἐν τῷ μέρει ὁ μὲν διώκων ὁ δὲ φεύγων, ἢ αὐτοὶ ἢ ῥήτορας ἀναβιβάζονται τοὺς ἐροῦντας ὑπὲρ αὐτῶν. οἱ δὲ ἔστ’ ἂν μὲν περὶ τοῦ πράγματος λέγωσιν, ἀνέχεται ἡ βουλὴ καθ’ ἡσυχίαν ἀκούουσα· ἢν δέ τις ἢ φροίμιον εἴπῃ πρὸ τοῦ λόγου, ὡς εὐνουστέρους ἀπεργάσαιτο αὐτούς, ἢ οἶκτον ἢ δείνωσιν ἔξωθεν ἐπάγῃ τῷ πράγματι — οἷα πολλὰ ῥητόρων παῖδες ἐπὶ τοὺς δικαστὰς μηχανῶνται — παρελθὼν ὁ κῆρυξ κατεσιώπησεν εὐθύς, οὐκ ἐῶν ληρεῖν πρὸς τὴν βουλὴν καὶ περιπέττειν τὸ πρᾶγμα ἐν τοῖς λόγοις, ὡς γυμνὰ τὰ γεγενημένα οἱ Ἀρεοπαγῖται βλέποιεν.", "st": "34.19"}, {"sp": "N", "t": "ὥστε καὶ σέ, ὦ Ἀνάχαρσι, Ἀρεοπαγίτην ἐν τῷ παρόντι ποιοῦμαι ἔγωγε, καὶ κατὰ τὸν τῆς βουλῆς μου νόμον ἄκουε, καὶ σιωπᾶν κέλευε, ἢν αἴσθῃ καταρρητορευόμενος· ἄχρι δ’ ἂν οἰκεῖα τῷ πράγματι λέγηται, ἐξέστω ἀπομηκύνειν. οὐδὲ γὰρ ὑφ’ ἡλίῳ ἔτι ποιησόμεθα τὴν συνουσίαν, ὡς ἄχθεσθαι εἰ ἀποτείνοιτο ἡ ῥῆσις, ἀλλὰ ἥ τε σκιὰ πυκνὴ καὶ ἡμεῖς σχολὴν ἄγομεν.", "st": "34.19"}, {"sp": "N", "t": "<em>Ἀνάχαρσις.<\/em> εὐγνώμονά σου ταῦτα, ὦ Σόλων, καὶ ἔγωγε ἤδη χάριν οὐ μικρὰν οἶδά σοι καὶ ἐπὶ τούτοις, ὅτι πάρεργον τοῦ λόγου καὶ τὰ ἐν Ἀρείῳ πάγῳ γιγνόμενα ἐδιδάξω με, θαυμάσια ὡς ἀληθῶς καὶ ἀγαθῶν βουλευτῶν ἔργα πρὸς ἀλήθειαν οἰσόντων τὴν ψῆφον. ἐπὶ τούτοις οὖν ἤδη λέγε, καὶ ὁ Ἀρεοπαγίτης ἐγὼ — τοῦτο γὰρ ἔθου με — κατὰ σχῆμα τῆς βουλῆς ἀκούσομαί σου.", "st": "34.19"}, {"sp": "N", "t": "<em>Σόλων.<\/em> οὐκοῦν διὰ βραχέων προακοῦσαι χρή σε ἃ περὶ πόλεως καὶ πολιτῶν ἡμῖν δοκεῖ. πόλιν γὰρ ἡμεῖς οὐ τὰ οἰκοδομήματα ἡγούμεθα εἶναι, οἷον τείχη καὶ ἱερὰ καὶ νεωσοίκους, ἀλλὰ ταῦτα μὲν ὥσπερ σῶμά τι ἑδραῖον καὶ ἀκίνητον ὑπάρχειν εἰς ὑποδοχὴν καὶ ἀσφάλειαν τῶν πολιτευομένων, τὸ δὲ πᾶν κῦρος ἐν τοῖς πολίταις τιθέμεθα· τούτους γὰρ εἶναι τοὺς ἀναπληροῦντας καὶ διατάττοντας καὶ ἐπιτελοῦντας ἕκαστα καὶ φυλάττοντας, οἷόν τι ἐν ἡμῖν ἑκάστῳ ἐστὶν ἡ ψυχή. τοῦτο δὴ τοίνυν κατανοήσαντες ἐπιμελούμεθα μέν, ὡς ὁρᾷς, καὶ τοῦ σώματος τῆς πόλεως, κατακοσμοῦντες αὐτὸ ὡς κάλλιστον ἡμῖν εἴη, ἔνδοθέν τε οἰκοδομήμασιν κατεσκευασμένον καὶ ταῖς ἔκτοσθεν ταύταις περιβολαῖς εἰς τὸ ἀσφαλέστατον πεφραγμένον. μάλιστα δὲ καὶ ἐξ ἅπαντος τοῦτο προνοοῦμεν, ὅπως οἱ πολῖται ἀγαθοὶ μὲν τὰς ψυχάς, ἰσχυροὶ δὲ τὰ σώματα γίγνοιντο· τοὺς γὰρ τοιούτους σφίσι τε αὐτοῖς καλῶς χρήσεσθαι ἐν εἰρήνῃ συμπολιτευομένους καὶ ἐκ πολέμου σώσειν τὴν πόλιν καὶ ἐλευθέραν καὶ εὐδαίμονα διαφυλάξειν.", "st": "34.20"}, {"sp": "N", "t": "τὴν μὲν δὴ πρώτην ἀνατροφὴν αὐτῶν μητράσι καὶ τίτθαις καὶ παιδαγωγοῖς ἐπιτρέπομεν ὑπὸ παιδείαις ἐλευθερίοις ἄγειν τε καὶ τρέφειν αὐτούς, ἐπειδὰν δὲ συνετοὶ ἤδη γίγνωνται τῶν καλῶς ἐχόντων, καὶ αἰδὼς καὶ ἐρύθημα καὶ φόβος καὶ ἐπιθυμία τῶν ἀρίστων ἀναφύηται αὐτοῖς, καὶ αὐτὰ ἤδη τὰ σώματα ἀξιόχρεα δοκῇ πρὸς τοὺς πόνους παγιώτερα γιγνόμενα καὶ πρὸς τὸ ἰσχυρότερον συνιστάμενα, τηνικαῦτα ἤδη παραλαβόντες αὐτοὺς διδάσκομεν, ἄλλα μὲν τῆς ψυχῆς μαθήματα καὶ γυμνάσια προτιθέντες, ἄλλως δὲ πρὸς τοὺς πόνους καὶ τὰ σώματα ἐθίζοντες. οὐ γὰρ ἱκανὸν ἡμῖν ἔδοξε τὸ μόνον φῦναι ὡς ἔφυ ἕκαστος ἤτοι κατὰ τὸ σῶμα ἢ κατὰ τὴν ψυχήν, ἀλλὰ καὶ παιδεύσεως καὶ μαθημάτων ἐπ’ αὐτοὺς δεόμεθα, ὑφ’ ὧν τά τε εὐφυῶς διακείμενα βελτίω παρὰ πολὺ γίγνοιτο ἂν καὶ τὰ φαύλως ἔχοντα μετακοσμοῖτο πρὸς τὸ βέλτιον. καὶ τὸ παράδειγμα ἡμῖν παρὰ τῶν γεωργῶν, οἳ τὰ φυτὰ μέχρι μὲν πρόσγεια καὶ νήπιά ἐστι, σκέπουσιν καὶ περιφράττουσιν ὡς μὴ βλάπτοιντο ὑπὸ τῶν πνευμάτων, ἐπειδὰν δὲ ἤδη παχύνηται τὸ ἔρνος, τηνικαῦτα περιτέμνουσίν τε τὰ περιττὰ καὶ παραδιδόντες αὐτὰ τοῖς ἀνέμοις δονεῖν καὶ διασαλεύειν καρπιμώτερα ἐξεργάζονται.", "st": "34.20"}, {"sp": "N", "t": "τὴν μὲν τοίνυν ψυχὴν μουσικῇ τὸ πρῶτον καὶ ἀριθμητικῇ ἀναρριπίζομεν, καὶ γράμματα γράψασθαι καὶ τορῶς αὐτὰ ἐπιλέξασθαι διδάσκομεν· προϊοῦσιν δὲ ἤδη σοφῶν ἀνδρῶν γνώμας καὶ ἔργα παλαιὰ καὶ λόγους ὠφελίμους ἐν μέτροις κατακοσμήσαντες, ὡς μᾶλλον μνημονεύοιεν, ῥαψῳδοῦμεν αὐτοῖς. οἱ δὲ καὶ ἀκούοντες ἀριστείας τινὰς καὶ πράξεις ἀοιδίμους ὀρέγονται κατὰ μικρὸν καὶ πρὸς μίμησιν ἐπεγείρονται, ὡς καὶ αὐτοὶ ᾄδοιντο καὶ θαυμάζοιντο ὑπὸ τῶν ὕστερον. οἷα πολλὰ Ἡσίοδός τε ἡμῖν καὶ Ὅμηρος ἐποίησαν.", "st": "34.21"}, {"sp": "N", "t": "ἐπειδὰν δὲ πλησιάζωσι πρὸς τὴν πολιτείαν καὶ δέῃ αὐτοὺς ἤδη μεταχειρίζεσθαι τὰ κοινά — καίτοι ἔξω τοῦ ἀγῶνος ἴσως ταῦτα· οὐ γὰρ ὅπως τὰς ψυχὰς αὐτῶν ἀσκοῦμεν ἐξ ἀρχῆς προὔκειτο εἰπεῖν, ἀλλὰ δι’ ὅ τι τοῖς τοιούτοις πόνοις καταγυμνάζειν αὐτοὺς ἀξιοῦμεν. ὥστε αὐτὸς ἐμαυτῷ σιωπᾶν προστάττω, οὐ περιμείνας τὸν κήρυκα οὐδὲ τὸν Ἀρεοπαγίτην σέ, ὃς ὑπ’ αἰδοῦς, οἶμαι, ἀνέχῃ ληροῦντα ἤδη τοσαῦτα ἔξω τοῦ πράγματος.", "st": "34.21"}, {"sp": "N", "t": "<em>Ἀνάχαρσις.<\/em> εἰπέ μοι, ὦ Σόλων, πρὸς δὲ δὴ τοὺς τὰ ἀναγκαιότατα μὴ λέγοντας ἐν Ἀρείῳ πάγῳ, ἀλλὰ ἀποσιωπῶντας, οὐδὲν τῇ βουλῇ πρόστιμον ἐπινενόηται;", "st": "34.21"}, {"sp": "N", "t": "<em>Σόλων.<\/em> τί τοῦτο ἤρου με; οὐδέπω γὰρ δῆλον.", "st": "34.21"}, {"sp": "N", "t": "<em>Ἀνάχαρσις.<\/em> ὅτι τὰ κάλλιστα καὶ ἐμοὶ ἀκοῦσαι ἥδιστα παρείς, τὰ περὶ τῆς ψυχῆς, τὰ ἧττον ἀναγκαῖα λέγειν διανοῇ, γυμνάσια καὶ διαπονήσεις τῶν σωμάτων.", "st": "34.21"}, {"sp": "N", "t": "<em>Σόλων.<\/em> μέμνημαι γάρ, ὦ γενναῖε, τῶν ἀπ’ ἀρχῆς προρρήσεων καὶ ἀποπλανᾶν οὐ βούλομαι τὸν λόγον, μή σου ἐπιταράξῃ τὴν μνήμην ἐπιρρέων. πλὴν ἀλλὰ καὶ ταῦτα ἐρῶ διὰ βραχέων, ὡς οἷόν τε· τὸ γὰρ ἀκριβὲς τῆς περὶ αὐτῶν διασκέψεως ἑτέρου ἂν εἴη λόγου.", "st": "34.21"}, {"sp": "N", "t": "ῥυθμίζομεν οὖν τὰς γνώμας αὐτῶν νόμους τε τοὺς κοινοὺς ἐκδιδάσκοντες, οἳ δημοσίᾳ πᾶσι πρόκεινται ἀναγιγνώσκειν μεγάλοις γράμμασιν ἀναγεγραμμένοι, κελεύοντες ἅ τε χρὴ ποιεῖν καὶ ὧν ἀπέχεσθαι, καὶ ἀγαθῶν ἀνδρῶν συνουσίαις, παρ’ ὧν λέγειν τὰ δέοντα ἐκμανθάνουσι καὶ πράττειν τὰ δίκαια καὶ ἐκ τοῦ ἴσου ἀλλήλοις συμπολιτεύεσθαι καὶ μὴ ἐφίεσθαι τῶν αἰσχρῶν καὶ ὀρέγεσθαι τῶν καλῶν, βίαιον δὲ μηδὲν ποιεῖν. οἱ δὲ ἄνδρες οὗτοι σοφισταὶ καὶ φιλόσοφοι πρὸς ἡμῶν ὀνομάζονται. καὶ μέντοι καὶ εἰς τὸ θέατρον συνάγοντες αὐτοὺς δημοσίᾳ παιδεύομεν ὑπὸ κωμῳδίαις καὶ τραγῳδίαις ἀρετάς τε ἀνδρῶν παλαιῶν καὶ κακίας θεωμένους, ὡς τῶν μὲν ἀποτρέποιντο, ἐπ’ ἐκεῖνα δὲ σπεύδοιεν. τοῖς δέ γε κωμῳδοῖς καὶ λοιδορεῖσθαι καὶ ἀποσκώπτειν ἐφίεμεν εἰς τοὺς πολίτας οὓς ἂν αἰσχρὰ καὶ ἀνάξια τῆς πόλεως ἐπιτηδεύοντας αἴσθωνται, αὐτῶν τε ἐκείνων χάριν, ἀμείνους γὰρ οὕτω γίγνονται ὀνειδιζόμενοι, καὶ τῶν πολλῶν, ὡς φεύγοιεν τὸν ἐπὶ τοῖς ὁμοίοις ἔλεγχον.", "st": "34.22"}, {"sp": "N", "t": "<em>Ἀνάχαρσις.<\/em> εἶδον, ὦ Σόλων, οὓς φὴς τοὺς τραγῳδοὺς καὶ κωμῳδούς, εἴ γε ἐκεῖνοί εἰσιν, ὑποδήματα μὲν βαρέα καὶ ὑψηλὰ ὑποδεδεμένοι, χρυσαῖς δὲ ταινίαις τὴν ἐσθῆτα πεποικιλμένοι, κράνη δὲ ἐπικείμενοι παγγέλοια κεχηνότα παμμέγεθες· αὐτοὶ δὲ ἔνδοθεν μεγάλα τε ἐκεκράγεσαν καὶ διέβαινον οὐκ οἶδ’ ὅπως ἀσφαλῶς ἐν τοῖς ὑποδήμασιν. Διονύσῳ δὲ οἶμαι τότε ἡ πόλις ἑώρταζεν. οἱ δὲ κωμῳδοὶ βραχύτεροι μὲν ἐκείνων καὶ πεζοὶ καὶ ἀνθρωπινώτεροι καὶ ἧττον ἐβόων, κράνη δὲ πολὺ γελοιότερα. καὶ τὸ θέατρον γοῦν ἅπαν ἐγέλα ἐπ’ αὐτοῖς· ἐκείνων δὲ τῶν ὑψηλῶν σκυθρωποὶ ἅπαντες ἤκουον, οἰκτείροντες, οἶμαι, αὐτοὺς πέδας τηλικαύτας ἐπισυρομένους.", "st": "34.23"}, {"sp": "N", "t": "<em>Σόλων.<\/em> οὐκ ἐκείνους, ὦγαθέ, ᾤκτειρον, ἀλλὰ ποιητὴς ἴσως ἀρχαίαν τινὰ συμφορὰν ἐπεδείκνυτο τοῖς θεαταῖς καὶ ῥήσεις οἰκτρὰς ἐτραγῴδει πρὸς τὸ θέατρον ὑφ’ ὧν εἰς δάκρυα κατεσπῶντο οἱ ἀκούοντες. εἰκὸς δέ σε καὶ αὐλοῦντας ἑωρακέναι τινὰς τότε καὶ ἄλλους συνᾴδοντας ἐν κύκλῳ συνεστῶτας. οὐδ’ αὐτά, ὦ Ἀνάχαρσι, ἀχρεῖα ᾄσματα καὶ αὐλήματα.", "st": "34.23"}, {"sp": "N", "t": "τούτοις δ’ οὖν ἅπασι καὶ τοῖς τοιούτοις παραθηγόμενοι τὰς ψυχὰς ἀμείνους ἡμῖν γίγνονται.", "st": "34.23"}, {"sp": "N", "t": "τὰ δὲ δὴ σώματα, ὅπερ μάλιστα ἐπόθεις ἀκοῦσαι, ὧδε καταγυμνάζομεν. ἀποδύσαντες αὐτά, ὡς ἔφην, οὐκέτι ἁπαλὰ καὶ τέλεον ἀσυμπαγῆ ὄντα, πρῶτον μὲν ἐθίζειν ἀξιοῦμεν πρὸς τὸν ἀέρα, συνοικειοῦντες αὐτὰ ταῖς ὥραις ἑκάσταις, ὡς μήτε θάλπος δυσχεραίνειν μήτε πρὸς κρύος ἀπαγορεύειν, ἔπειτα δὲ χρίομεν ἐλαίῳ καὶ καταμαλάττομεν, ὡς εὐτονώτερα γίγνοιτο· ἄτοπον γάρ, εἰ τὰ μὲν σκύτη νομίζομεν ὑπὸ τῷ ἐλαίῳ μαλαττόμενα δυσραγέστερα καὶ πολλῷ διαρκέστερα γίγνεσθαι νεκρά γε ἤδη ὄντα, τὸ δ’ ἔτι ζωῆς μετέχον σῶμα μὴ ἂν ἄμεινον ἡγοίμεθα ὑπὸ τοῦ ἐλαίου διατεθήσεσθαι.", "st": "34.24"}, {"sp": "N", "t": "τοὐντεῦθεν ποικίλα τὰ γυμνάσια ἐπινοήσαντες καὶ διδασκάλους ἑκάστων ἐπιστήσαντες τὸν μέν τινα πυκτεύειν, τὸν δὲ παγκρατιάζειν διδάσκομεν, ὡς τούς τε πόνους καρτερεῖν ἐθίζοιντο καὶ ὁμόσε χωρεῖν ταῖς πληγαῖς μηδὲ ἀποτρέποιντο δέει τῶν τραυμάτων. τοῦτο δὲ ἡμῖν δύο τὰ ὠφελιμώτατα ἐξεργάζεται ἐν αὐτοῖς, θυμοειδεῖς τε παρασκευάζον εἰς τοὺς κινδύνους καὶ τῶν σωμάτων ἀφειδεῖν καὶ προσέτι ἐρρῶσθαι καὶ καρτεροὺς εἶναι.", "st": "34.24"}, {"sp": "N", "t": "ὅσοι δὲ αὐτῶν κάτω συννενευκότες παλαίουσιν, καταπίπτειν τε ἀσφαλῶς μανθάνουσι καὶ ἀνίστασθαι εὐμαρῶς καὶ ὠθισμοὺς καὶ περιπλοκὰς καὶ λυγισμοὺς καὶ ἄγχεσθαι δύνασθαι καὶ εἰς ὕψος ἀναβαστάσαι τὸν ἀντίπαλον, οὐκ ἀχρεῖα οὐδὲ οὗτοι ἐκμελετῶντες, ἀλλὰ ἓν μὲν τὸ πρῶτον καὶ μέγιστον ἀναμφιβόλως κτώμενοι· δυσπαθέστερα γὰρ καὶ καρτερώτερα τὰ σώματα γίγνονται αὐτοῖς διαπονούμενα. ἕτερον δὲ οὐδὲ αὐτὸ μικρόν· ἔμπειροι γὰρ δὴ ἐκ τούτου καθίστανται, εἴ ποτε ἀφίκοιντο εἰς χρείαν τῶν μαθημάτων τούτων ἐν ὅπλοις· δῆλον γὰρ ὅτι καὶ πολεμίῳ ἀνδρὶ ὁ τοιοῦτος συμπλακεὶς καταρρίψει τε θᾶττον ὑποσκελίσας καὶ καταπεσὼν εἴσεται ὡς ῥᾷστα ἐξανίστασθαι. πάντα γὰρ ταῦτα, ὦ Ἀνάχαρσι, ἐπ’ ἐκεῖνον τὸν ἀγῶνα ποριζόμεθα τὸν ἐν τοῖς ὅπλοις καὶ ἡγούμεθα πολὺ ἀμείνοσι χρήσασθαι τοῖς οὕτως ἀσκηθεῖσιν, ἐπειδὰν πρότερον αὐτῶν γυμνὰ τὰ σώματα καταμαλάξαντες καὶ διαπονήσαντες ἐρρωμενέστερα καὶ ἀλκιμώτερα ἐξεργασώμεθα καὶ κοῦφα καὶ εὔτονα καὶ τὰ αὐτὰ βαρέα τοῖς ἀνταγωνισταῖς.", "st": "34.24"}, {"sp": "N", "t": "ἐννοεῖς γάρ, οἶμαι, τὸ μετὰ τοῦτο, οἵους εἰκὸς σὺν ὅπλοις ἔσεσθαι τοὺς καὶ γυμνοὺς ἂν φόβον τοῖς δυσμενέσιν ἐμποιήσαντας, οὐ πολυσαρκίαν ἀργὸν καὶ λευκὴν ἢ ἀσαρκίαν μετὰ ὠχρότητος ἐπιδεικνυμένους οἷα γυναικῶν σώματα ὑπὸ σκιᾷ μεμαρασμένα, τρέμοντα ἱδρῶτί τε πολλῷ εὐθὺς ῥεόμενα καὶ ἀσθμαίνοντα ὑπὸ τῷ κράνει, καὶ μάλιστα ἢν καὶ ὁ ἥλιος ὥσπερ νῦν τὸ μεσημβρινὸν ἐπιφλέγῃ. οἷς τί ἄν τις χρήσαιτο διψῶσι καὶ τὸν κονιορτὸν οὐκ ἀνεχομένοις καὶ εἰ αἷμα ἴδοιεν, εὐθὺς ταραττομένοις καὶ προαποθνήσκουσι πρὶν ἐντὸς βέλους γενέσθαι καὶ εἰς χεῖρας ἐλθεῖν τοῖς πολεμίοις;", "st": "34.25"}, {"sp": "N", "t": "οὗτοι δὲ ἡμῖν ὑπέρυθροι εἰς τὸ μελάντερον ὑπὸ τοῦ ἡλίου κεχρωσμένοι καὶ ἀρρενωποί, πολὺ τὸ ἔμψυχον καὶ θερμὸν καὶ ἀνδρῶδες ἐπιφαίνοντες, τοσαύτης εὐεξίας ἀπολάμποντες, οὔτε ῥικνοὶ καὶ κατεσκληκότες οὔτε περιπληθεῖς εἰς βάρος, ἀλλὰ εἰς τὸ σύμμετρον περιγεγραμμένοι, τὸ μὲν ἀχρεῖον τῶν σαρκῶν καὶ περιττὸν τοῖς ἱδρῶσιν ἐξαναλωκότες, ὃ δὲ ἰσχὺν καὶ τόνον παρεῖχεν ἀμιγὲς τοῦ φαύλου περιλελειμμένον ἐρρωμένως φυλάττοντες. ὅπερ γὰρ δὴ οἱ λικμῶντες τὸν πυρόν, τοῦτο ἡμῖν καὶ τὰ γυμνάσια ἐργάζεται ἐν τοῖς σώμασι, τὴν μὲν ἄχνην καὶ τοὺς ἀθέρας ἀποφυσῶντα, καθαρὸν δὲ τὸν καρπὸν διευκρινοῦντα καὶ προσωρεύοντα.", "st": "34.25"}, {"sp": "N", "t": "καὶ διὰ τοῦτο ὑγιαίνειν τε ἀνάγκη καὶ ἐπὶ μήκιστον διαρκεῖν ἐν τοῖς καμάτοις· ὀψέ τε ἂν ἰδίειν ὁ τοιοῦτος ἄρξαιτο καὶ ὀλιγάκις ἂν ἀσθενῶν φανείη. ὥσπερ ἂν εἰ πῦρ τις φέρων ἅμα ἐμβάλοι εἰς πυρὸν αὐτὸν καὶ εἰς τὴν καλάμην αὐτοῦ καὶ εἰς τὴν ἄχνην — αὖθις γὰρ ἐπὶ τὸν λικμῶντα ἐπάνειμι — θᾶττον ἄν, οἶμαι, παρὰ πολὺ ἡ καλάμη ἀναφλεγείη, ὁ δὲ πυρὸς κατ’ ὀλίγον οὔτε φλογὸς μεγάλης ἀνισταμένης οὔτε ὑπὸ μιᾷ τῇ ὁρμῇ, ἀλλὰ κατὰ μικρὸν ὑποτυφόμενος χρόνῳ ὕστερον καὶ αὐτὸς ἂν κατακαυθείη.", "st": "34.26"}, {"sp": "N", "t": "οὐ τοίνυν οὐδὲ νόσος οὐδὲ κάματος εἰς τοιοῦτο σῶμα ἐμπεσόντα ῥᾳδίως ἐλέγξειεν ἂν οὐδ’ ἐπικρατήσειεν εὐμαρῶς· ἔνδοθέν τε γὰρ εὖ παρεσκεύασται αὐτῷ καὶ τὰ ἔξω μάλα καρτερῶς πέφρακται πρὸς αὐτά, ὡς μὴ παριέναι εἰς τὸ εἴσω, μηδὲ παραδέχεσθαι μήτε ἥλιον αὐτὸν μήτε κρύος ἐπὶ λύμῃ τοῦ σώματος. πρός τε τὸ ἐνδιδὸν ἐν τοῖς πόνοις πολὺ τὸ θερμὸν τὸ ἔνδοθεν ἐπιρρέον, ἅτε ἐκ πολλοῦ προπαρεσκευασμένον καὶ εἰς τὴν ἀναγκαίαν χρείαν ἀποκείμενον, ἀναπληροῖ εὐθὺς ἐπάρδον τῇ ἀκμῇ καὶ ἀκαμάτους ἐπὶ πλεῖστον παρέχεται· τὸ γὰρ προπονῆσαι πολλὰ καὶ προκαμεῖν οὐκ ἀνάλωσιν τῆς ἰσχύος, ἀλλ’ ἐπίδοσιν ἐργάζεται, καὶ ἀναρριπιζομένη πλείων γίγνεται.", "st": "34.26"}, {"sp": "N", "t": "καὶ μὴν καὶ δρομικοὺς εἶναι ἀσκοῦμεν αὐτοὺς εἰς μῆκός τε διαρκεῖν ἐθίζοντες καὶ εἰς τὸ ἐν βραχεῖ ὠκύτατον ἐπικουφίζοντες· καὶ ὁ δρόμος οὐ πρὸς τὸ στερρὸν καὶ ἀντίτυπον, ἀλλὰ ἐν ψάμμῳ βαθείᾳ, ἔνθα οὔτε βεβαίως ἀπερεῖσαι τὴν βάσιν οὔτε ἐπιστηρίξαι ῥᾴδιον ὑποσυρομένου πρὸς τὸ ὑπεῖκον τοῦ ποδός. ἀλλὰ καὶ ὑπεράλλεσθαι τάφρον, εἰ δέοι, ἢ εἴ τι ἄλλο ἐμπόδιον, καὶ πρὸς τοῦτο ἀσκοῦνται ἡμῖν, ἔτι καὶ μολυβδίδας χειροπληθεῖς ἐν ταῖν χεροῖν ἔχοντες. εἶτα περὶ ἀκοντίου βολῆς εἰς μῆκος ἁμιλλῶνται. εἶδες δὲ καὶ ἄλλο τι ἐν τῷ γυμνασίῳ χαλκοῦν περιφερές, ἀσπίδι μικρᾷ ἐοικὸς ὄχανον οὐκ ἐχούσῃ οὐδὲ τελαμῶνας, καὶ ἐπειράθης γε αὐτοῦ κειμένου ἐν τῷ μέσῳ καὶ ἐδόκει σοι βαρὺ καὶ δύσληπτον ὑπὸ λειότητος. ἐκεῖνο τοίνυν ἄνω τε ἀναρριπτοῦσιν εἰς τὸν ἀέρα καὶ εἰς τὸ πόρρω, φιλοτιμούμενοι ὅστις ἐπὶ μήκιστον ἐξέλθοι καὶ τοὺς ἄλλους ὑπερβάλοιτο· καὶ ὁ πόνος οὗτος ὤμους τε αὐτῶν κρατύνει καὶ τόνον τοῖς ἄκροις ἐντίθησιν.", "st": "34.27"}, {"sp": "N", "t": "ὁ πηλὸς δὲ καὶ ἡ κόνις, ἅπερ σοι γελοιότερα ἐξ ἀρχῆς ἔδοξεν, ἄκουσον, ὦ θαυμάσιε, ὅτου ἕνεκα ὑποβέβληται. πρῶτον μέν, ὡς μὴ ἐπὶ τὸ κραταιὸν ἡ πτῶσις αὐτοῖς γίγνοιτο, ἀλλ’ ἐπὶ τὸ μαλακὸν ἀσφαλῶς πίπτοιεν· ἔπειτα καὶ τὸν ὄλισθον ἀνάγκη πλείω γίγνεσθαι, ἱδρούντων ἐν τῷ πηλῷ, ὃ σὺ ταῖς ἐγχέλεσιν εἴκαζες, οὐκ ἀχρεῖον οὐδὲ γελοῖον ὄν, ἀλλὰ καὶ τοῦτο εἰς ἰσχὺν καὶ τόνον οὐκ ὀλίγα συντελεῖ, ὁπόταν οὕτως ἐχόντων ἀλλήλων ἀναγκάζωνται ἐγκρατῶς ἀντιλαμβάνεσθαι καὶ συνέχειν διολισθάνοντας· αἴρεσθαί τε ἐν πηλῷ ἱδρωκότα μετ’ ἐλαίου, ἐκπεσεῖν καὶ διαρρυῆναι τῶν χειρῶν σπουδάζοντα, μὴ μικρὸν εἶναι νόμιζε. καὶ ταῦτα πάντα, ὥσπερ ἔφην ἔμπροσθεν, εἰς τοὺς πολέμους καὶ χρήσιμα, εἰ δέοι φίλον τρωθέντα ῥᾳδίως ἀράμενον ὑπεξενεγκεῖν ἢ καὶ πολέμιον συναρπάσαντα ἥκειν μετέωρον κομίζοντα. καὶ διὰ τοῦτο εἰς ὑπερβολὴν ἀσκοῦμεν, τὰ χαλεπώτερα προτιθέντες ὡς τὰ μικρότερα μακρῷ εὐκολώτερον φέροιεν.", "st": "34.28"}, {"sp": "N", "t": "τὴν μέντοι κόνιν ἐπὶ τὸ ἐναντίον χρησίμην οἰόμεθα εἶναι, ὡς μὴ διολισθάνοιεν συμπλεκόμενοι. ἐπειδὰν γὰρ ἐν τῷ πηλῷ ἀσκηθῶσιν συνέχειν τὸ διαδιδρᾶσκον ὑπὸ γλισχρότητος, ἐθίζονται ἐκφεύγειν αὐτοὶ ληφθέντες ἐκ τῶν χειρῶν, καὶ ταῦτα ἐν ἀφύκτῳ ἐχόμενοι. καὶ μὴν καὶ τὸν ἱδρῶτα συνέχειν δοκεῖ ἡ κόνις ἀθρόον ἐκχεόμενον ἐπιπαττομένη, καὶ ἐπὶ πολὺ διαρκεῖν ποιεῖ τὴν δύναμιν, καὶ κώλυμα γίγνεται μὴ βλάπτεσθαι ὑπὸ τῶν ἀνέμων ἀραιοῖς τότε καὶ ἀνεῳγόσιν τοῖς σώμασιν ἐμπιπτόντων. ἄλλως τε καὶ τὸν ῥύπον ἀποσμᾷ καὶ στιλπνότερον ποιεῖ τὸν ἄνδρα. καὶ ἔγωγε ἡδέως ἂν παραστησάμενος πλησίον τῶν τε λευκῶν τινα ἐκείνων καὶ ὑπὸ σκιᾷ δεδιῃτημένων καὶ ὃν ἂν ἕλῃ τῶν ἐν τῷ Λυκείῳ γυμναζομένων, ἀποπλύνας τὴν κόνιν καὶ τὸν πηλόν, ἐροίμην ἄν σε ποτέρῳ ἂν ὅμοιος εὔξαιο γενέσθαι· οἶδα γὰρ ὡς αὐτίκα ἕλοιο ἂν ἐκ πρώτης προσόψεως, εἰ καὶ μὴ ἐπὶ τῶν ἔργων πειραθείης ἑκατέρου, συνεστηκὼς καὶ συγκεκροτημένος εἶναι μᾶλλον ἢ θρύπτεσθαι καὶ διαρρεῖν καὶ λευκὸς εἶναι ἀπορίᾳ καὶ φυγῇ εἰς τὰ εἴσω τοῦ αἵματος.", "st": "34.29"}, {"sp": "N", "t": "ταῦτ’ ἔστιν, ὦ Ἀνάχαρσι, ἃ τοὺς νέους ἡμεῖς ἀσκοῦμεν οἰόμενοι φύλακας ἡμῖν τῆς πόλεως ἀγαθοὺς γενέσθαι καὶ ἐν ἐλευθερίᾳ βιώσεσθαι δι’ αὐτούς, κρατοῦντες μὲν τῶν δυσμενῶν εἰ ἐπίοιεν, φοβεροὶ δὲ τοῖς περιοίκοις ὄντες, ὡς ὑποπτήσσειν τε καὶ ὑποτελεῖν ἡμῖν τοὺς πλείστους αὐτῶν. ἐν εἰρήνῃ τε αὖ πολὺ ἀμείνοσιν αὐτοῖς χρώμεθα περὶ μηδὲν τῶν αἰσχρῶν φιλοτιμουμένοις μηδ’ ὑπ’ ἀργίας εἰς ὕβριν τρεπομένοις, ἀλλὰ περὶ τὰ τοιαῦτα διατρίβουσιν καὶ ἀσχόλοις οὖσιν ἐν αὐτοῖς. καὶ ὅπερ ἔφην τὸ κοινὸν ἀγαθὸν καὶ τὴν ἄκραν πόλεως εὐδαιμονίαν, τοῦτ’ ἔστιν, ὁπότε εἰς τε εἰρήνην καὶ εἰς πόλεμον τὰ ἄριστα παρεσκευασμένη φαίνοιτο ἡ νεότης περὶ τὰ κάλλιστα ἡμῖν σπουδάζοντες.", "st": "34.30"}, {"sp": "N", "t": "<em>Ἀνάχαρσις.<\/em> οὐκοῦν, ὦ Σόλων, ἤν ποτε ὑμῖν ἐπίωσιν οἱ πολέμιοι, χρισάμενοι τῷ ἐλαίῳ καὶ κονισάμενοι πρόιτε καὶ αὐτοὶ πὺξ τὰς χεῖρας ἐπ’ αὐτοὺς προβεβλημένοι, κἀκεῖνοι δηλαδὴ ὑποπτήσσουσιν ὑμᾶς καὶ φεύγουσιν δεδιότες μὴ σφίσι κεχηνόσι πάσσητε τὴν ψάμμον εἰς τὸ στόμα ἢ περιπηδήσαντες, ὡς κατὰ νώτου γένησθε, περιπλέξητε αὐτοῖς τὰ σκέλη περὶ τὴν γαστέρα καὶ διάγχητε ὑπὸ τὸ κράνος ὑποβαλόντες τὸν πῆχυν. καὶ μὴ Δί’ οἱ μὲν τοξεύσουσι δῆλον ὅτι καὶ ἀκοντιοῦσιν, ὑμῶν δὲ ὥσπερ ἀνδριάντων οὐ καθίξεται τὰ βέλη κεχρωσμένων πρὸς τὸν ἥλιον καὶ πολὺ τὸ αἷμα πεπορισμένων. οὐ γὰρ καλάμη καὶ ἀθέρες ὑμεῖς ἐστε, ὡς τάχιστα ἐνδιδόναι πρὸς τὰς πληγάς, ἀλλὰ ὀψέ ποτε ἂν καὶ μόλις κατατεμνόμενοι βαθέσι τοῖς τραύμασιν αἷμα ὀλίγον ὑποδείξαιτε. τοιαῦτα γὰρ φής, εἰ μὴ πάνυ παρήκουσα τοῦ παραδείγματος.", "st": "34.31"}, {"sp": "N", "t": "ἢ τὰς πανοπλίας ἐκείνας τότε ἀναλήψεσθε τὰς τῶν κωμῳδῶν τε καὶ τραγῳδῶν, καὶ ἢν προτεθῇ ὑμῖν ἔξοδος, ἐκεῖνα τὰ κράνη περιθήσεσθε τὰ κεχηνότα, ὡς φοβερώτεροι εἴητε τοῖς ἐναντίοις μορμολυττόμενοι αὐτούς, καὶ ὑποδήσεσθε τὰ ὑψηλὰ ἐκεῖνα δηλαδή· φεύγουσί τε γάρ, ἢν δέῃ, κοῦφα, καὶ ἢν διώκητε, ἄφυκτα τοῖς πολεμίοις ἔσται, ὑμῶν οὕτω μεγάλα διαβαινόντων ἐπ’ αὐτούς.", "st": "34.32"}, {"sp": "N", "t": "ἀλλ’ ὅρα μὴ ταῦτα μὲν ὑμῖν τὰ κομψὰ λῆρος ᾖ καὶ παιδιὰ ἄλλως καὶ διατριβαὶ ἀργοῦσι καὶ ῥᾳθυμεῖν ἐθέλουσι τοῖς νεανίσκοις. εἰ δὲ βούλεσθε πάντως ἐλεύθεροι καὶ εὐδαίμονες εἶναι, ἄλλων ὑμῖν γυμνασίων δεήσει καὶ ἀσκήσεως ἀληθινῆς τῆς ἐν τοῖς ὅπλοις, καὶ ἡ ἅμιλλα οὐ πρὸς ἀλλήλους μετὰ παιδιᾶς, ἀλλὰ πρὸς τοὺς δυσμενεῖς ἔσται μετὰ κινδύνων μελετῶσι τὴν ἀρετήν. ὥστε ἀφέντας τὴν κόνιν καὶ τὸ ἔλαιον δίδασκε αὐτοὺς τοξεύειν καὶ ἀκοντίζειν μὴ κοῦφα διδοὺς τὰ ἀκόντια καὶ οἷα διαφέρεσθαι πρὸς τὸν ἄνεμον, ἀλλ’ ἔστω λόγχη βαρεῖα μετὰ συριγμοῦ ἑλιττομένη καὶ λίθος χειροπληθὴς καὶ σάγαρις καὶ γέρρον ἐν τῇ ἀριστερᾷ καὶ θώραξ καὶ κράνος.", "st": "34.32"}, {"sp": "N", "t": "ὡς δὲ νῦν ἔχετε, θεῶν τινος εὐμενείᾳ σώζεσθαί μοι δοκεῖτε, οἳ μηδέπω ἀπολώλατε ὑπό τινων ὀλίγων ψιλῶν ἐπιπεσόντων. ἰδού γέ τοι ἢν σπασάμενος τὸ μικρὸν τοῦτο ξιφίδιον τὸ παρὰ τὴν ζώνην μόνος ἐπεισπέσω τοῖς νέοις ὑμῶν ἅπασιν, αὐτοβοεὶ ἂν ἕλοιμι τὸ γυμνάσιον φυγόντων ἐκείνων καὶ οὐδενὸς ἀντιβλέπειν τῷ σιδήρῳ τολμῶντος, ἀλλὰ περὶ τοὺς ἀνδριάντας ἂν περιιστάμενοι καὶ περὶ τοὺς κίονας κατακρυπτόμενοι γέλωτα ἄν μοι παράσχοιεν δακρύοντες οἱ πολλοὶ καὶ τρέμοντες. καὶ τότ’ ἂν ἴδοις οὐκέτι ἐρυθριῶντας αὐτοὺς τὰ σώματα οἷοι νῦν εἰσιν, ἀλλὰ ὠχροὶ ἅπαντες αὐτίκα γένοιντ’ ἂν ὑπὸ τοῦ δέους μεταβαφέντες. οὕτως ὑμᾶς ἡ εἰρήνη διατέθεικε βαθεῖα οὖσα, ὡς μὴ ἂν ῥᾳδίως ἀνασχέσθαι λόφον ἕνα κράνους πολεμίου ἰδόντας.", "st": "34.33"}, {"sp": "N", "t": "<em>Σόλων.<\/em> οὐ ταῦτα ἔφασαν, ὦ Ἀνάχαρσι, Θρᾳκῶν τε ὅσοι μετ’ Εὐμόλπου ἐφ’ ἡμᾶς ἐστράτευσαν καὶ αἱ γυναῖκες ὑμῶν αἱ μετὰ Ἱππολύτης ἐλάσασαι ἐπὶ τὴν πόλιν οὐδὲ οἱ ἄλλοι ὅσοι ἡμῶν ἐν ὅπλοις ἐπειράθησαν. ἡμεῖς γάρ, ὦ μακάριε, οὐκ ἐπείπερ οὕτω γυμνὰ τὰ σώματα ἐκπονοῦμεν τῶν νέων, διὰ τοῦτο καὶ ἄνοπλα ἐξάγομεν ἐπὶ τοὺς κινδύνους, ἀλλ’ ἐπειδὰν καθ’ αὑτοὺς ἄριστοι γένωνται, ἀσκοῦνται τὸ μετὰ τοῦτο σὺν τοῖς ὅπλοις, καὶ πολὺ ἄμεινον χρήσαιντ’ ἂν αὐτοῖς οὕτω διακείμενοι.", "st": "34.34"}, {"sp": "N", "t": "<em>Ἀνάχαρσις.<\/em> καὶ ποῦ τοῦτο ὑμῖν ἐστι τὸ γυμνάσιον τὸ ἐν τοῖς ὅπλοις; οὐ γὰρ εἶδον ἔγωγε ἐν τῇ πόλει τοιοῦτον οὐδέν, ἅπασαν αὐτὴν ἐν κύκλῳ περιελθών.", "st": "34.34"}, {"sp": "N", "t": "<em>Σόλων.<\/em> ἀλλὰ ἴδοις ἄν, ὦ Ἀνάχαρσι, ἐπὶ πλέον ἡμῖν συνδιατρίψας, καὶ ὅπλα ἑκάστῳ μάλα πολλά, οἷς χρώμεθα ὁπόταν ἀναγκαῖον ᾖ, καὶ λόφους καὶ φάλαρα καὶ ἵππους, καὶ ἱππέας σχεδὸν τὸ τέταρτον τῶν πολιτῶν. τὸ μέντοι ὁπλοφορεῖν ἀεὶ καὶ ἀκινάκην παρεζῶσθαι περιττὸν ἐν εἰρήνῃ οἰόμεθα εἶναι, καὶ πρόστιμόν γ’ ἔστιν, ὅστις ἐν ἄστει σιδηροφοροίη μηδὲν δέον ἢ ὅπλα ἐξενέγκοι εἰς τὸ δημόσιον. ὑμεῖς δὲ συγγνωστοὶ ἐν ὅπλοις ἀεὶ βιοῦντες· τό τε γὰρ ἐν ἀφράκτῳ οἰκεῖν ῥᾴδιον εἰς ἐπιβουλήν, καὶ οἱ πόλεμοι μάλα πολλοί, καὶ ἄδηλον ὁπότε τις ἐπιστὰς κοιμώμενον κατασπάσας ἀπὸ τῆς ἁμάξης φονεύσειεν· ἥ τε πρὸς ἀλλήλους ἀπιστία, αὐθαιρέτως καὶ μὴ ἐν νόμῳ συμπολιτευομένων, ἀναγκαῖον ἀεὶ τὸν σίδηρον ποιεῖ, ὡς πλησίον εἶναι ἀμυνοῦντα, εἴ τις βιάζοιτο.", "st": "34.34"}, {"sp": "N", "t": "<em>Ἀνάχαρσις.<\/em> εἶτα, ὦ Σόλων, σιδηροφορεῖν μὲν οὐδενὸς ἀναγκαίου ἕνεκα περιττὸν ὑμῖν δοκεῖ, καὶ τῶν ὅπλων φείδεσθε, ὡς μὴ διὰ χειρὸς ὄντα φθείροιτο, ἀλλὰ φυλάττετε ἀποκείμενα ὡς χρησόμενοι τότε, τῆς χρείας ἐπιστάσης· τὰ δὲ σώματα τῶν νέων οὐδενὸς δεινοῦ ἐπείγοντος καταπονεῖτε παίοντες καὶ ὑπὸ τῶν ἱδρώτων καταναλίσκοντες, οὐ ταμιευόμενοι πρὸς τὸ ἀναγκαῖον τὰς ἀλκὰς αὐτῶν, ἀλλ’ εἰκῆ ἐν τῷ πηλῷ καὶ τῇ κόνει ἐκχέοντες;", "st": "34.35"}, {"sp": "N", "t": "<em>Σόλων.<\/em> ἔοικας, ὦ Ἀνάχαρσι, τοιόνδε τι δυνάμεως πέρι ἐννοεῖν, ὡς οἴνῳ ἢ ὕδατι ἢ ἄλλῳ τῶν ὑγρῶν ὁμοίαν αὐτὴν οὖσαν. δέδιας οὖν μὴ ὥσπερ ἐξ ἀγγείου κεραμεοῦ λάθῃ διαρρυεῖσα ἐν τοῖς πόνοις κᾆτα ἡμῖν κενὸν καὶ ξηρὸν οἴχηται τὸ σῶμα καταλιποῦσα ὑπὸ μηδενὸς ἔνδοθεν ἀναπληρούμενον. τὸ δὲ οὐχ οὕτως ἔχει σοι, ἀλλὰ ὅσῳ τις ἂν αὐτὴν ἐξαντλῇ τοῖς πόνοις, τοσῷδε μᾶλλον ἐπιρρεῖ κατὰ τὸν περὶ τῆς Ὕδρας μῦθον, εἴ τινα ἤκουσας, ὡς ἀντὶ μιᾶς κεφαλῆς τμηθείσης δύ’ ἀεὶ ἄλλαι ἀνεφύοντο. ἢν δὲ ἀγύμναστος ἐξ ἀρχῆς καὶ ἄτονος ᾖ μηδὲ διαρκῆ τὴν ὕλην ἔχῃ ὑποβεβλημένην, τότε ὑπὸ τῶν καμάτων βλάπτοιτο ἂν καὶ καταμαραίνοιτο, οἷόν τι ἐπὶ πυρὸς καὶ λύχνου γίγνεται. ὑπὸ γὰρ τῷ αὐτῷ φυσήματι τὸ μὲν πῦρ ἀνακαύσειας ἂν καὶ μεῖζον ἐν βραχεῖ ποιήσειας παραθήγων τῷ πνεύματι, καὶ τὸ τοῦ λύχνου φῶς ἀποσβέσειας οὐκ ἔχον ἀποχρῶσαν τῆς ὕλης τὴν χορηγίαν, ὡς διαρκῆ εἶναι πρὸς τὸ ἀντιπνέον· οὐ γὰρ ἀπ’ ἰσχυρᾶς, οἶμαι, τῆς ῥίζης ἀνεφύετο.", "st": "34.35"}, {"sp": "N", "t": "<em>Ἀνάχαρσις.<\/em> ταυτὶ μέν, ὦ Σόλων, οὐ πάνυ συνίημι· λεπτότερα γὰρ ἢ κατ’ ἐμὲ εἴρηκας, ἀκριβοῦς τινος φροντίδος καὶ διανοίας ὀξὺ δεδορκυίας δεόμενα. ἐκεῖνο δέ μοι πάντως εἰπέ, τίνος ἕνεκα οὐχὶ καὶ ἐν τοῖς ἀγῶσι τοῖς Ὀλυμπίασι καὶ Ἰσθμοῖ καὶ Πυθοῖ καὶ τοῖς ἄλλοις, ὁπότε πολλοί, ὡς φής, συνίασιν ὀψόμενοι τοὺς νέους ἀγωνιζομένους, οὐδέποτε ἐν ὅπλοις ποιεῖσθε τὴν ἅμιλλαν, ἀλλὰ γυμνοὺς εἰς τὸ μέσον παραγαγόντες λακτιζομένους καὶ παιομένους ἐπιδείκνυτε καὶ νικήσασι μῆλα καὶ κότινον δίδοτε; ἄξιον γὰρ εἰδέναι τοῦτό γε, οὗτινος ἕνεκα οὕτω ποιεῖτε.", "st": "34.36"}, {"sp": "N", "t": "<em>Σόλων.<\/em> ἡγούμεθα γάρ, ὦ Ἀνάχαρσι, τὴν εἰς τὰ γυμνάσια προθυμίαν οὕτως ἂν πλείω ἐγγενέσθαι αὐτοῖς, εἰ τοὺς ἀριστεύοντας ἐν τούτοις ἴδοιεν τιμωμένους καὶ ἀνακηρυττομένους ἐν μέσοις τοῖς Ἕλλησι. καὶ διὰ τοῦτο ὡς εἰς τοσούτους ἀποδυσόμενοι εὐεξίας τε ἐπιμελοῦνται, ὡς μὴ αἰσχύνοιντο γυμνωθέντες, καὶ ἀξιονικότατον ἕκαστος αὑτὸν ἀπεργάζεται. καὶ τὰ ἆθλα, ὥσπερ ἔμπροσθεν εἶπον, οὐ μικρά, ὁ ἔπαινος ὁ παρὰ τῶν θεατῶν καὶ τὸ ἐπισημότατον γενέσθαι καὶ δείκνυσθαι τῷ δακτύλῳ ἄριστον εἶναι τῶν καθ’ αὑτὸν δοκοῦντα. τοιγάρτοι πολλοὶ τῶν θεατῶν, οἷς καθ’ ἡλικίαν ἔτι ἄσκησις, ἀπίασιν οὐ μετρίως ἐκ τῶν τοιούτων ἀρετῆς καὶ πόνων ἐρασθέντες. ὡς εἴ γέ τις, ὦ Ἀνάχαρσι, τὸν τῆς εὐκλείας ἔρωτα ἐκβάλοι ἐκ τοῦ βίου, τί ἂν ἔτι ἀγαθὸν ἡμῖν γένοιτο, ἢ τίς ἄν τι λαμπρὸν ἐργάσασθαι ἐπιθυμήσειεν; νῦν δὲ καὶ ἀπὸ τούτων εἰκάζειν παρέχοιεν ἄν σοι, ὁποῖοι ἐν πολέμοις ὑπὲρ πατρίδος καὶ παίδων καὶ γυναικῶν καὶ ἱερῶν γένοιντ’ ἂν ὅπλα ἔχοντες οἱ κοτίνου πέρι καὶ μήλων γυμνοὶ τοσαύτην προθυμίαν εἰς τὸ νικᾶν εἰσφερόμενοι.", "st": "34.36"}, {"sp": "N", "t": "καίτοι τί ἂν πάθοις, εἰ θεάσαιο καὶ ὀρτύγων καὶ ἀλεκτρυόνων ἀγῶνας παρ’ ἡμῖν καὶ σπουδὴν ἐπὶ τούτοις οὐ μικράν; ἢ γελάσῃ δῆλον ὅτι, καὶ μάλιστα ἢν μάθῃς ὡς ὑπὸ νόμῳ αὐτὸ δρῶμεν καὶ προστέτακται πᾶσι τοῖς ἐν ἡλικίᾳ παρεῖναι καὶ ὁρᾶν τὰ ὄρνεα διαπυκτεύοντα μέχρι τῆς ἐσχάτης ἀπαγορεύσεως; ἀλλ’ οὐδὲ τοῦτο γελοῖον· ὑποδύεται γάρ τις ἠρέμα ταῖς ψυχαῖς ὁρμὴ εἰς τοὺς κινδύνους, ὡς μὴ ἀγεννέστεροι καὶ ἀτολμότεροι φαίνοιντο τῶν ἀλεκτρυόνων μηδὲ προαπαγορεύοιεν ὑπὸ τραυμάτων ἢ καμάτου ἤ του ἄλλου δυσχεροῦς.", "st": "34.37"}, {"sp": "N", "t": "τὸ δὲ δὴ ἐν ὅπλοις πειρᾶσθαι αὐτῶν καὶ ὁρᾶν τιτρωσκομένους — ἄπαγε· θηριῶδες γὰρ καὶ δεινῶς σκαιὸν καὶ προσέτι γε ἀλυσιτελὲς ἀποσφάττειν τοὺς ἀρίστους καὶ οἷς ἄν τις ἄμεινον χρήσαιτο κατὰ τῶν δυσμενῶν.", "st": "34.37"}, {"sp": "N", "t": "ἐπεὶ δὲ φής, ὦ Ἀνάχαρσι, καὶ τὴν ἄλλην Ἑλλάδα ἐπελεύσεσθαι, μέμνησο ἤν ποτε καὶ εἰς Λακεδαίμονα ἔλθῃς, μὴ καταγελάσαι μηδὲ ἐκείνων μηδὲ οἴεσθαι μάτην πονεῖν αὐτούς, ὁπόταν ἢ σφαίρας πέρι ἐν τῷ θεάτρῳ συμπεσόντες παίωσιν ἀλλήλους ἢ εἰς χωρίον εἰσελθόντες ὕδατι περιγεγραμμένον, εἰς φάλαγγα διαστάντες, τὰ πολεμίων ἀλλήλους ἐργάζωνται γυμνοὶ καὶ αὐτοί, ἄχρις ἂν ἐκβάλωσι τοῦ περιγράμματος τὸ ἕτερον σύνταγμα οἱ ἕτεροι, τοὺς κατὰ Λυκοῦργον οἱ καθ’ Ἡρακλέα ἢ ἔμπαλιν, συνωθοῦντες εἰς τὸ ὕδωρ· τὸ γὰρ ἀπὸ τούτου εἰρήνη λοιπὸν καὶ οὐδεὶς ἂν ἔτι παίσειε. μάλιστα δὲ ἢν ὁρᾷς μαστιγουμένους αὐτοὺς ἐπὶ τῷ βωμῷ καὶ αἵματι ῥεομένους, πατέρας δὲ καὶ μητέρας παρεστώσας οὐχ ὅπως ἀνιωμένας ἐπὶ τοῖς γιγνομένοις ἀλλὰ καὶ ἀπειλούσας, εἰ μὴ ἀντέχοιεν πρὸς τὰς πληγάς, καὶ ἱκετευούσας ἐπὶ μήκιστον διαρκέσαι πρὸς τὸν πόνον καὶ ἐγκαρτερῆσαι τοῖς δεινοῖς. πολλοὶ γοῦν καὶ ἐναπέθανον τῷ ἀγῶνι μὴ ἀξιώσαντες ἀπαγορεῦσαι ζῶντες ἔτι ἐν ὀφθαλμοῖς τῶν οἰκείων μηδὲ εἶξαι τοῖς σώμασιν· ὧν καὶ τοὺς ἀνδριάντας ὄψει τιμωμένους δημοσίᾳ ὑπὸ τῆς Σπάρτης ἀνασταθέντας.", "st": "34.38"}, {"sp": "N", "t": "Ὅταν τοίνυν ὁρᾷς κἀκεῖνα, μήτε μαίνεσθαι ὑπολάβῃς αὐτοὺς μήτε εἴπῃς, ὡς οὐδεμιᾶς ἕνεκα αἰτίας ἀναγκαίας ταλαιπωροῦσι, μήτε τυράννου βιαζομένου μήτε πολεμίων διατιθέντων. εἴποι γὰρ ἄν σοι καὶ ὑπὲρ ἐκείνων Λυκοῦργος ὁ νομοθέτης αὐτῶν πολλὰ τὰ εὔλογα καὶ ἃ συνιδὼν κολάζει αὐτούς, οὐκ ἐχθρὸς ὢν οὐδὲ ὑπὸ μίσους αὐτὸ δρῶν οὐδὲ τὴν νεολαίαν τῆς πόλεως εἰκῆ παραναλίσκων, ἀλλὰ καρτερικωτάτους καὶ παντὸς δεινοῦ κρείττονας ἀξιῶν εἶναι τοὺς σώζειν μέλλοντας τὴν πατρίδα. καίτοι κἂν μὴ ὁ Λυκοῦργος εἴπῃ, ἐννοεῖς, οἶμαι, καὶ αὐτὸς ὡς οὐκ ἄν ποτε ληφθεὶς ὁ τοιοῦτος ἐν πολέμῳ ἀπόρρητόν τι ἐξείποι τῆς Σπάρτης αἰκιζομένων τῶν ἐχθρῶν, ἀλλὰ καταγελῶν αὐτῶν μαστιγοῖτο ἂν ἁμιλλώμενος πρὸς τὸν παίοντα, ὁπότερος ἀπαγορεύσειεν.", "st": "34.38"}, {"sp": "N", "t": "<em>Ἀνάχαρσις.<\/em> ὁ Λυκοῦργος δὲ καὶ αὐτός, ὦ Σόλων, ἐμαστιγοῦτο ἐφ’ ἡλικίας, ἢ ἐκπρόθεσμος ὢν ἤδη τοῦ ἀγῶνος ἀσφαλῶς τὰ τοιαῦτα ἐνεανιεύσατο;", "st": "34.39"}, {"sp": "N", "t": "<em>Σόλων.<\/em> πρεσβύτης ἤδη ὢν ἔγραψε τοὺς νόμους αὐτοῖς Κρήτηθεν ἀφικόμενος. ἀποδεδημήκει δὲ παρὰ τοὺς Κρῆτας, ὅτι ἤκουεν εὐνομωτάτους εἶναι, Μίνωος τοῦ Διὸς νομοθετήσαντος ἐν αὐτοῖς.", "st": "34.39"}, {"sp": "N", "t": "<em>Ἀνάχαρσις.<\/em> τί οὖν, ὦ Σόλων, οὐχὶ καὶ σὺ ἐμιμήσω Λυκοῦργον καὶ μαστιγοῖς τοὺς νέους; καλὰ γὰρ καὶ ταῦτα καὶ ἄξια ὑμῶν ἐστιν.", "st": "34.39"}, {"sp": "N", "t": "<em>Σόλων.<\/em> ὅτι ἡμῖν ἱκανά, ὦ Ἀνάχαρσι, ταῦτα τὰ γυμνάσια οἰκεῖα ὄντα· ζηλοῦν δὲ τὰ ξενικὰ οὐ πάνυ ἀξιοῦμεν.", "st": "34.39"}, {"sp": "N", "t": "<em>Ἀνάχαρσις.<\/em> οὔκ; ἀλλὰ συνίης, οἶμαι, οἷόν τί ἐστι μαστιγοῦσθαι γυμνὸν ἄνω τὰς χεῖρας ἐπαίροντα μηδενὸς ἕνεκα ὠφελίμου ἢ αὐτῷ ἑκάστῳ ἢ κοινῇ τῇ πόλει. ὡς ἔγωγε ἤν ποτε ἐπιδημήσω τῇ Σπάρτῃ καθ’ ὃν καιρὸν ταῦτα δρῶσι, δοκῶ μοι τάχιστα καταλευσθήσεσθαι δημοσίᾳ πρὸς αὐτῶν, ἐπιγελῶν ἑκάστοις, ὁπόταν ὁρῶ τυπτομένους καθάπερ κλέπτας ἢ λωποδύτας ἤ τι ἄλλο τοιοῦτον ἐργασαμένους. ἀτεχνῶς γὰρ ἐλλεβόρου δεῖσθαί μοι δοκεῖ ἡ πόλις αὐτῶν καταγέλαστα ὑφ’ αὑτῆς πάσχουσα.", "st": "34.39"}, {"sp": "N", "t": "<em>Σόλων.<\/em> μὴ ἐρήμην, ὦ γενναῖε, μηδὲ τῶν ἀνδρῶν ἀπόντων μόνος αὐτὸς λέγων οἴου κρατεῖν· ἔσται γάρ τις ὁ καὶ ὑπὲρ ἐκείνων σοι τὰ εἰκότα ἐν Σπάρτῃ ἀντερῶν.", "st": "34.40"}, {"sp": "N", "t": "πλὴν ἀλλὰ ἐπείπερ ἐγὼ τὰ ἡμέτερά σοι διεξελήλυθα, σὺ δὲ οὐ πάνυ ἀρεσκομένῳ αὐτοῖς ἔοικας, οὐκ ἄδικα αἰτήσειν ἔοικα παρὰ σοῦ ὡς καὶ αὐτὸς ἐν τῷ μέρει διεξέλθῃς πρός με ὃν τρόπον ὑμεῖς οἱ Σκύθαι διασκεῖτε τοὺς νέους τοὺς παρ’ ὑμῖν καὶ οἷστισι γυμνασίοις ἀνατρέφετε καὶ ὅπως ὑμῖν ἄνδρες ἀγαθοὶ γίγνονται.", "st": "34.40"}, {"sp": "N", "t": "<em>Ἀνάχαρσις.<\/em> δικαιότατα μὲν οὖν, ὦ Σόλων, καὶ ἔγωγε διηγήσομαι τὰ Σκυθῶν νόμιμα, οὐ σεμνὰ ἴσως οὐδὲ καθ’ ὑμᾶς, οἵ γε οὐδὲ κατὰ κόρρης παταχθῆναι τολμήσαιμεν ἂν μίαν πληγήν· δειλοὶ γάρ ἐσμεν· ἀλλὰ εἰρήσεταί γε ὁποῖα ἂν ᾖ. εἰς αὔριον μέντοι, εἰ δοκεῖ, ὑπερβαλώμεθα τὴν συνουσίαν, ὡς ἅ τε αὐτὸς ἔφης ἔτι μᾶλλον ἐννοήσαιμι καθ’ ἡσυχίαν ἅ τε χρὴ εἰπεῖν συναγάγοιμι τῇ μνήμῃ ἐπελθών. τὸ δὲ νῦν ἔχον ἀπίωμεν ἐπὶ τούτοις· ἑσπέρα γὰρ ἤδη.", "st": "34.40"}, {"sp": "HDR", "t": "Μένιππος ἢ Νεκυομαντεία"}, {"sp": "N", "t": "<em>Μένιππος.<\/em> ὦ χαῖρε μέλαθρον πρόπυλά θ’ ἑστίας ἐμῆς,<br>ὡς ἄσμενός ς’ ἐσεῖδον ἐς φάος μολών.", "st": "35.1"}, {"sp": "N", "t": "<em>Φίλος.<\/em> οὐ Μένιππος οὗτός ἐστιν ὁ κύων; οὐ μὲν οὖν ἄλλος, εἰ μὴ ἐγὼ παραβλέπω· Μένιππος ὅλος. τί οὖν αὐτῷ βούλεται τὸ ἀλλόκοτον τοῦ σχήματος, πῖλος καὶ λύρα καὶ λεοντῆ; πλὴν ἀλλὰ προσιτέον γε αὐτῷ. χαῖρε, ὦ Μένιππε· πόθεν ἡμῖν ἀφῖξαι; πολὺς γὰρ χρόνος οὐ πέφηνας ἐν τῇ πόλει.", "st": "35.1"}, {"sp": "N", "t": "<em>Μένιππος.<\/em> ἥκω νεκρῶν κευθμῶνα καὶ σκότου πύλας λιπών, ἵν’ Ἅιδης χωρὶς ᾤκισται θεῶν.", "st": "35.1"}, {"sp": "N", "t": "<em>Φίλος.<\/em> Ἡράκλεις, ἐλελήθει Μένιππος ἡμᾶς ἀποθανών, κᾆτα ἐξ ὑπαρχῆς ἀναβεβίωκεν;", "st": "35.1"}, {"sp": "N", "t": "<em>Μένιππος.<\/em> οὔκ, ἀλλ’ ἔτ’ ἔμπνουν Ἀΐδης μ’ ἐδέξατο.", "st": "35.1"}, {"sp": "N", "t": "<em>Φίλος.<\/em> τίς δὴ αἰτία σοι τῆς καινῆς καὶ παραδόξου ταύτης ἀποδημίας;", "st": "35.1"}, {"sp": "N", "t": "<em>Μένιππος.<\/em> νεότης μ’ ἐπῆρε καὶ θράσος τοῦ νοῦ πλέον.", "st": "35.1"}, {"sp": "N", "t": "<em>Φίλος.<\/em> παῦσαι, μακάριε, τραγῳδῶν καὶ λέγε οὑτωσί πως ἁπλῶς καταβὰς ἀπὸ τῶν ἰαμβείων, τίς ἡ στολή; τί σοι τῆς κάτω πορείας ἐδέησεν; ἄλλως γὰρ οὐχ ἡδεῖά τις οὐδὲ ἀσπάσιος ἡ ὁδός.", "st": "35.1"}, {"sp": "N", "t": "<em>Μένιππος.<\/em> ὦ φιλότης, χρειώ με κατήγαγεν εἰς Ἀΐδαο ψυχῇ χρησόμενον Θηβαίου Τειρεσίαο.", "st": "35.1"}, {"sp": "N", "t": "<em>Φίλος.<\/em> οὗτος, ἀλλ’ ἦ παραπαίεις· οὐ γὰρ ἂν οὕτως ἐμμέτρως ἐρραψῴδεις πρὸς ἄνδρας φίλους.", "st": "35.1"}, {"sp": "N", "t": "<em>Μένιππος.<\/em> μὴ θαυμάσῃς, ὦ ἑταῖρε· νεωστὶ γὰρ Εὐριπίδῃ καὶ Ὁμήρῳ συγγενόμενος οὐκ οἶδ’ ὅπως ἀνεπλήσθην τῶν ἐπῶν καὶ αὐτόματά μοι τὰ μέτρα ἐπὶ τὸ στόμα ἔρχεται.", "st": "35.1"}, {"sp": "N", "t": "ἀτὰρ εἰπέ μοι, πῶς τὰ ὑπὲρ γῆς ἔχει καὶ τί ποιοῦσιν οἱ ἐν τῇ πόλει;", "st": "35.2"}, {"sp": "N", "t": "<em>Φίλος.<\/em> καινὸν οὐδέν, ἀλλ’ οἷα καὶ πρὸ τοῦ· ἁρπάζουσιν, ἐπιορκοῦσιν, τοκογλυφοῦσιν, ὀβολοστατοῦσιν.", "st": "35.2"}, {"sp": "N", "t": "<em>Μένιππος.<\/em> ἄθλιοι καὶ κακοδαίμονες· οὐ γὰρ ἴσασιν οἷα ἔναγχος κεκύρωται παρὰ τοῖς κάτω καὶ οἷα κεχειροτόνηται τὰ ψηφίσματα κατὰ τῶν πλουσίων, ἃ μὰ τὸν Κέρβερον οὐδεμία μηχανὴ τὸ διαφυγεῖν αὐτούς.", "st": "35.2"}, {"sp": "N", "t": "<em>Φίλος.<\/em> τί φής; δέδοκταί τι νεώτερον τοῖς κάτω περὶ τῶν ἐνθάδε;", "st": "35.2"}, {"sp": "N", "t": "<em>Μένιππος.<\/em> νὴ Δία, καὶ πολλά γε· ἀλλ’ οὐ θέμις ἐκφέρειν αὐτὰ πρὸς ἅπαντας οὐδὲ ἐξαγορεύειν τὰ ἀπόρρητα, μὴ καί τις ἡμᾶς γράψηται γραφὴν ἀσεβείας ἐπὶ τοῦ Ῥαδαμάνθυος.", "st": "35.2"}, {"sp": "N", "t": "<em>Φίλος.<\/em> μηδαμῶς, ὦ Μένιππε, πρὸς τοῦ Διός, μὴ φθονήσῃς τῶν λόγων φίλῳ ἀνδρί· πρὸς γὰρ εἰδότα σιωπᾶν ἐρεῖς, τά τ’ ἄλλα καὶ πρὸς μεμυημένον.", "st": "35.2"}, {"sp": "N", "t": "<em>Μένιππος.<\/em> χαλεπὸν μὲν ἐπιτάττεις τὸ ἐπίταγμα καὶ οὐ πάντῃ εὐσεβές· πλὴν ἀλλὰ σοῦ γε ἕνεκα τολμητέον. ἔδοξε δὴ τοὺς πλουσίους τούτους καὶ πολυχρημάτους καὶ τὸ χρυσίον κατάκλειστον ὥσπερ τὴν Δανάην φυλάττοντας —", "st": "35.2"}, {"sp": "N", "t": "<em>Φίλος.<\/em> μὴ πρότερον εἴπῃς, ὦγαθέ, τὰ δεδογμένα πρὶν ἐκεῖνα διελθεῖν ἃ μάλιστ’ ἂν ἡδέως ἀκούσαιμί σου, τίς ἡ ἐπίνοιά σοι τῆς καθόδου ἐγένετο, τίς δ’ ὁ τῆς πορείας ἡγεμών, εἶθ’ ἑξῆς ἅ τε εἶδες ἅ τε ἤκουσας παρ’ αὐτοῖς· εἰκὸς γὰρ δὴ φιλόκαλον ὄντα σε μηδὲν τῶν ἀξίων θέας ἢ ἀκοῆς παραλιπεῖν.", "st": "35.2"}, {"sp": "N", "t": "<em>Μένιππος.<\/em> ὑπουργητέον καὶ ταῦτά σοι· τί γὰρ ἂν καὶ πάθοι τις, ὁπότε φίλος ἀνὴρ βιάζοιτο; καὶ δὴ πρῶτά σοι δίειμι τὰ περὶ τῆς γνώμης τῆς ἐμῆς, ὅθεν ὡρμήθην πρὸς τὴν κατάβασιν. ἐγὼ γάρ, ἄχρι μὲν ἐν παισὶν ἦν, ἀκούων Ὁμήρου καὶ Ἡσιόδου πολέμους καὶ στάσεις διηγουμένων οὐ μόνον τῶν ἡμιθέων, ἀλλὰ καὶ αὐτῶν ἤδη τῶν θεῶν, ἔτι δὲ καὶ μοιχείας αὐτῶν καὶ βίας καὶ ἁρπαγὰς καὶ δίκας καὶ πατέρων ἐξελάσεις καὶ ἀδελφῶν γάμους, πάντα ταῦτα ἐνόμιζον εἶναι καλὰ καὶ οὐ παρέργως ἐκινούμην πρὸς αὐτά. ἐπεὶ δὲ εἰς ἄνδρας τελεῖν ἠρξάμην, πάλιν αὖ ἐνταῦθα ἤκουον τῶν νόμων τἀναντία τοῖς ποιηταῖς κελευόντων, μήτε μοιχεύειν μήτε στασιάζειν μήτε ἁρπάζειν. ἐν μεγάλῃ οὖν καθειστήκειν ἀμφιβολίᾳ, οὐκ εἰδὼς ὅ τι χρησαίμην ἐμαυτῷ· οὔτε γὰρ ἄν ποτε τοὺς θεοὺς μοιχεῦσαι καὶ στασιάσαι πρὸς ἀλλήλους ἡγούμην εἰ μὴ ὡς περὶ καλῶν τούτων ἐγίγνωσκον, οὔτ’ ἂν τοὺς νομοθέτας τἀναντία παραινεῖν εἰ μὴ λυσιτελεῖν ὑπελάμβανον.", "st": "35.3"}, {"sp": "N", "t": "ἐπεὶ δὲ διηπόρουν, ἔδοξέ μοι ἐλθόντα παρὰ τοὺς καλουμένους τούτους φιλοσόφους ἐγχειρίσαι τε ἐμαυτὸν καὶ δεηθῆναι αὐτῶν χρῆσθαί μοι ὅ τι βούλοιντο καί τινα ὁδὸν ἁπλῆν καὶ βέβαιον ὑποδεῖξαι τοῦ βίου.", "st": "35.4"}, {"sp": "N", "t": "ταῦτα μὲν δὴ φρονῶν προσῄειν αὐτοῖς, ἐλελήθειν δ’ ἐμαυτὸν εἰς αὐτό, φασί, τὸ πῦρ ἐκ τοῦ καπνοῦ βιαζόμενος. παρὰ γὰρ δὴ τούτοις μάλιστα εὕρισκον ἐπισκοπῶν τὴν ἄγνοιαν καὶ τὴν ἀπορίαν πλείονα, ὥστε μοι τάχιστα χρυσοῦν ἀπέδειξαν οὗτοι τὸν τῶν ἰδιωτῶν τοῦτον βίον.", "st": "35.4"}, {"sp": "N", "t": "ἀμέλει ὁ μὲν αὐτῶν παρῄνει τὸ πᾶν ἥδεσθαι καὶ μόνον τοῦτο ἐκ παντὸς μετιέναι· τοῦτο γὰρ εἶναι τὸ εὔδαιμον. ὁ δέ τις ἔμπαλιν, πονεῖν τὰ πάντα καὶ μοχθεῖν καὶ τὸ σῶμα καταναγκάζειν ῥυπῶντα καὶ αὐχμῶντα καὶ πᾶσι δυσαρεστοῦντα καὶ λοιδορούμενον, συνεχὲς ἐπιρραψῳδῶν τὰ πάνδημα ἐκεῖνα τοῦ Ἡσιόδου περὶ τῆς ἀρετῆς ἔπη καὶ τὸν ἱδρῶτα καὶ τὴν ἐπὶ τὸ ἄκρον ἀνάβασιν. ἄλλος καταφρονεῖν χρημάτων παρεκελεύετο καὶ ἀδιάφορον οἴεσθαι τὴν κτῆσιν αὐτῶν· ὁ δέ τις ἔμπαλιν ἀγαθὸν εἶναι καὶ τὸν πλοῦτον ἀπεφαίνετο. περὶ μὲν γὰρ τοῦ κόσμου τί χρὴ καὶ λέγειν; ὅς γε ἰδέας καὶ ἀσώματα καὶ ἀτόμους καὶ κενὰ καὶ τοιοῦτόν τινα ὄχλον ὀνομάτων ὁσημέραι παρ’ αὐτῶν ἀκούων ἐναυτίων. καὶ τὸ πάντων ἀτοπώτατον, ὅτι περὶ τῶν ἐναντιωτάτων ἕκαστος αὐτῶν λέγων σφόδρα νικῶντας καὶ πιθανοὺς λόγους ἐπορίζετο, ὥστε μήτε τῷ θερμὸν τὸ αὐτὸ πρᾶγμα λέγοντι μήτε τῷ ψυχρὸν ἀντιλέγειν ἔχειν, καὶ ταῦτ’ εἰδότα σαφῶς ὡς οὐκ ἄν ποτε θερμὸν εἴη τι καὶ ψυχρὸν ἐν ταὐτῷ χρόνῳ. ἀτεχνῶς οὖν ἔπασχον τοῖς νυστάζουσι τούτοις ὅμοιον, ἄρτι μὲν ἐπινεύων, ἄρτι δὲ ἀνανεύων ἔμπαλιν.", "st": "35.4"}, {"sp": "N", "t": "πολλῷ δὲ τούτων ἐκεῖνο ἀλογώτερον· τοὺς γὰρ αὐτοὺς τούτους εὕρισκον ἐπιτηρῶν ἐναντιώτατα τοῖς αὑτῶν λόγοις ἐπιτηδεύοντας. τοὺς γοῦν καταφρονεῖν παραινοῦντας χρημάτων ἑώρων ἀπρὶξ ἐχομένους αὐτῶν καὶ περὶ τόκων διαφερομένους καὶ ἐπὶ μισθῷ παιδεύοντας καὶ πάντα ἕνεκα τούτων ὑπομένοντας, τούς τε τὴν δόξαν ἀποβαλλομένους αὐτῆς ταύτης χάριν τὰ πάντα καὶ πράττοντας καὶ λέγοντας, ἡδονῆς τε αὖ σχεδὸν ἅπαντας κατηγοροῦντας, ἰδίᾳ δὲ μόνῃ ταύτῃ προσηρτημένους.", "st": "35.5"}, {"sp": "N", "t": "σφαλεὶς οὖν καὶ τῆσδε τῆς ἐλπίδος ἔτι μᾶλλον ἐδυσχέραινον, ἠρέμα παραμυθούμενος ἐμαυτὸν ὅτι μετὰ πολλῶν καὶ σοφῶν καὶ σφόδρα ἐπὶ συνέσει διαβεβοημένων ἀνόητός τέ εἰμι καὶ τἀληθὲς ἔτι ἀγνοῶν περιέρχομαι. καί μοί ποτε διαγρυπνοῦντι τούτων ἕνεκα ἔδοξεν εἰς Βαβυλῶνα ἐλθόντα δεηθῆναί τινος τῶν μάγων τῶν Ζωροάστρου μαθητῶν καὶ διαδόχων· ἤκουον δ’ αὐτοὺς ἐπῳδαῖς τε καὶ τελεταῖς τισιν ἀνοίγειν τοῦ Ἅιδου τὰς πύλας καὶ κατάγειν ὃν ἂν βούλωνται ἀσφαλῶς καὶ ὀπίσω αὖθις ἀναπέμπειν. ἄριστον οὖν ἡγούμην εἶναι παρά τινος τούτων διαπραξάμενον τὴν κατάβασιν ἐλθόντα παρὰ Τειρεσίαν τὸν Βοιώτιον μαθεῖν παρ’ αὐτοῦ ἅτε μάντεως καὶ σοφοῦ, τίς ἐστιν ὁ ἄριστος βίος καὶ ὃν ἄν τις ἕλοιτο εὖ φρονῶν.", "st": "35.6"}, {"sp": "N", "t": "καὶ δὴ ἀναπηδήσας ὡς εἶχον τάχους ἔτεινον εὐθὺ Βαβυλῶνος· ἐλθὼν δὲ συγγίγνομαί τινι τῶν Χαλδαίων σοφῷ ἀνδρὶ καὶ θεσπεσίῳ τὴν τέχνην, πολιῷ μὲν τὴν κόμην, γένειον δὲ μάλα σεμνὸν καθειμένῳ, τοὔνομα δὲ ἦν αὐτῷ Μιθροβαρζάνης. δεηθεὶς δὲ καὶ καθικετεύσας μόγις ἐπέτυχον παρ’ αὐτοῦ, ἐφ’ ὅτῳ βούλοιτο μισθῷ, καθηγήσασθαί μοι τῆς ὁδοῦ.", "st": "35.6"}, {"sp": "N", "t": "παραλαβὼν δέ με ὁ ἀνὴρ πρῶτα μὲν ἡμέρας ἐννέα καὶ εἴκοσιν ἅμα τῇ σελήνῃ ἀρξάμενος ἔλουε κατάγων ἕωθεν ἐπὶ τὸν Εὐφράτην πρὸς ἀνίσχοντα τὸν ἥλιον, ῥῆσίν τινα μακρὰν ἐπιλέγων ἧς οὐ σφόδρα κατήκουον· ὥσπερ γὰρ οἱ φαῦλοι τῶν ἐν τοῖς ἀγῶσι κηρύκων ἐπίτροχόν τι καὶ ἀσαφὲς ἐφθέγγετο. πλὴν ἐῴκει γέ τινας ἐπικαλεῖσθαι δαίμονας. μετὰ δ’ οὖν τὴν ἐπῳδὴν τρὶς ἄν μου πρὸς τὸ πρόσωπον ἀποπτύσας, ἐπανῄει πάλιν οὐδένα τῶν ἀπαντώντων προσβλέπων. καὶ σιτία μὲν ἦν ἡμῖν τὰ ἀκρόδρυα, ποτὸν δὲ γάλα καὶ μελίκρατον καὶ τὸ τοῦ Χοάσπου ὕδωρ, εὐνὴ δὲ ὑπαίθριος ἐπὶ τῆς πόας.", "st": "35.7"}, {"sp": "N", "t": "ἐπεὶ δ’ ἅλις εἶχε τῆς προδιαιτήσεως, περὶ μέσας νύκτας ἐπὶ τὸν Τίγρητα ποταμὸν ἀγαγὼν ἐκάθηρέν τέ με καὶ ἀπέμαξε καὶ περιήγνισεν δᾳδὶ καὶ σκίλλῃ καὶ ἄλλοις πλείοσιν, ἅμα καὶ τὴν ἐπῳδὴν ἐκείνην ὑποτονθορύσας. εἶτά με ὅλον καταμαγεύσας καὶ περιελθών, ἵνα μὴ βλαπτοίμην ὑπὸ τῶν φασμάτων, ἐπανάγει εἰς τὴν οἰκίαν, ὡς εἶχον, ἀναποδίζοντα, καὶ τὸ λοιπὸν ἀμφὶ πλοῦν εἴχομεν.", "st": "35.7"}, {"sp": "N", "t": "αὐτὸς μὲν οὖν μαγικήν τινα ἐνέδυ στολὴν τὰ πολλὰ ἐοικυῖαν τῇ Μηδικῇ, ἐμὲ δὲ τουτοισὶ φέρων ἐνεσκεύασε, τῷ πίλῳ καὶ τῇ λεοντῇ καὶ προσέτι τῇ λύρᾳ, καὶ παρεκελεύσατο, ἤν τις ἔρηταί με τοὔνομα, Μένιππον μὴ λέγειν, Ἡρακλέα δὲ ἢ Ὀδυσσέα ἢ Ὀρφέα.", "st": "35.8"}, {"sp": "N", "t": "<em>Φίλος.<\/em> ὡς δὴ τί τοῦτο, ὦ Μένιππε; οὐ γὰρ συνίημι τὴν αἰτίαν οὔτε τοῦ σχήματος οὔτε τῶν ὀνομάτων.", "st": "35.8"}, {"sp": "N", "t": "<em>Μένιππος.<\/em> καὶ μὴν πρόδηλόν γε τοῦτο καὶ οὐ παντελῶς ἀπόρρητον· ἐπεὶ γὰρ οὗτοι πρὸ ἡμῶν ζῶντες εἰς Ἅιδου κατεληλύθεσαν, ἡγεῖτο, εἴ με ἀπεικάσειεν αὐτοῖς, ῥᾳδίως ἂν τὴν τοῦ Αἰακοῦ φρουρὰν διαλαθεῖν καὶ ἀκωλύτως ἂν παρελθεῖν ἅτε συνηθέστερον, τραγικῶς μάλα παραπεμπόμενον ὑπὸ τοῦ σχήματος.", "st": "35.8"}, {"sp": "N", "t": "ἤδη δ’ οὖν ὑπέφαινεν ἡμέρα, καὶ κατελθόντες ἐπὶ τὸν ποταμὸν περὶ ἀναγωγὴν ἐγιγνόμεθα. παρεσκεύαστο δ’ αὐτῷ καὶ σκάφος καὶ ἱερεῖα καὶ μελίκρατον καὶ ἄλλα ὅσα πρὸς τὴν τελετὴν χρήσιμα. ἐμβαλόμενοι οὖν ἅπαντα τὰ παρεσκευασμένα οὕτω δὴ καὶ αὐτοὶ βαίνομεν ἀχνύμενοι, θαλερὸν κατὰ δάκρυ χέοντες.", "st": "35.9"}, {"sp": "N", "t": "Καὶ μέχρι μέν τινος ὑπεφερόμεθα ἐν τῷ ποταμῷ, εἶτα δὲ εἰσεπλεύσαμεν εἰς τὸ ἕλος καὶ τὴν λίμνην εἰς ἣν ὁ Εὐφράτης ἀφανίζεται. περαιωθέντες δὲ καὶ ταύτην ἀφικνούμεθα εἰς τι χωρίον ἔρημον καὶ ὑλῶδες καὶ ἀνήλιον, εἰς ὃ καὶ δὴ ἀποβάντες — ἡγεῖτο δὲ ὁ Μιθροβαρζάνης — βόθρον τε ὠρυξάμεθα καὶ τὰ μῆλα κατεσφάξαμεν καὶ τὸ αἷμα περὶ αὐτὸν ἐσπείσαμεν. ὁ δὲ μάγος ἐν τοσούτῳ δᾷδα καιομένην ἔχων οὐκέτ’ ἠρεμαίᾳ τῇ φωνῇ, παμμέγεθες δέ, ὡς οἷός τε ἦν, ἀνακραγὼν δαίμονάς τε ὁμοῦ πάντας ἐπεβοᾶτο καὶ Ποινὰς καὶ Ἐρινύας<br>καὶ νυχίαν Ἑκάτην καὶ ἐπαινὴν Περσεφόνειαν,<br>παραμιγνὺς ἅμα βαρβαρικά τινα καὶ ἄσημα ὀνόματα καὶ πολυσύλλαβα.", "st": "35.9"}, {"sp": "N", "t": "εὐθὺς οὖν ἅπαντα ἐκεῖνα ἐσαλεύετο καὶ ὑπὸ τῆς ἐπῳδῆς τοὔδαφος ἀνερρήγνυτο καὶ ὑλακὴ τοῦ Κερβέρου πόρρωθεν ἠκούετο καὶ τὸ πρᾶγμα ὑπερκατηφὲς ἦν καὶ σκυθρωπόν.<br>ἔδδεισεν δ’ ὑπένερθεν ἄναξ ἐνέρων Ἀϊδωνεύς —<br>κατεφαίνετο γὰρ ἤδη τὰ πλεῖστα, καὶ ἡ λίμνη καὶ ὁ Πυριφλεγέθων καὶ τοῦ Πλούτωνος τὰ βασίλεια. κατελθόντες δ’ ὅμως διὰ τοῦ χάσματος τὸν μὲν Ῥαδάμανθυν εὕρομεν τεθνεῶτα μικροῦ δεῖν ὑπὸ τοῦ δέους· ὁ δὲ Κέρβερος ὑλάκτησε μέν τι καὶ παρεκίνησε, ταχὺ δέ μου κρούσαντος τὴν λύραν παραχρῆμα ἐκηλήθη ὑπὸ τοῦ μέλους. ἐπεὶ δὲ πρὸς τὴν λίμνην ἀφικόμεθα, μικροῦ μὲν οὐδὲ ἐπεραιώθημεν· ἦν γὰρ πλῆρες ἤδη τὸ πορθμεῖον καὶ οἰμωγῆς ἀνάπλεων, τραυματίαι δὲ πάντες ἐπέπλεον, ὁ μὲν τὸ σκέλος, ὁ δὲ τὴν κεφαλήν, ὁ δὲ ἄλλο τι συντετριμμένος, ἐμοὶ δοκεῖν, ἔκ τινος πολέμου παρόντες.", "st": "35.10"}, {"sp": "N", "t": "ὅμως δ’ οὖν ὁ βέλτιστος Χάρων ὡς εἶδε τὴν λεοντῆν, οἰηθείς με τὸν Ἡρακλέα εἶναι, εἰσεδέξατο καὶ διεπόρθμευσέν τε ἄσμενος καὶ ἀποβᾶσι διεσήμηνε τὴν ἀτραπόν.", "st": "35.10"}, {"sp": "N", "t": "ἐπεὶ δὲ ἦμεν ἐν τῷ σκότῳ, προῄει μὲν ὁ Μιθροβαρζάνης, εἱπόμην δὲ ἐγὼ κατόπιν ἐχόμενος αὐτοῦ, ἕως πρὸς λειμῶνα μέγιστον ἀφικνούμεθα τῷ ἀσφοδέλῳ κατάφυτον, ἔνθα δὴ περιεπέτοντο ἡμᾶς τετριγυῖαι τῶν νεκρῶν αἱ σκιαί. κατ’ ὀλίγον δὲ προϊόντες παραγιγνόμεθα πρὸς τὸ τοῦ Μίνωος δικαστήριον· ἐτύγχανε δὲ ὁ μὲν ἐπὶ θρόνου τινὸς ὑψηλοῦ καθήμενος, παρειστήκεσαν δὲ αὐτῷ Ποιναὶ καὶ Ἐρινύες καὶ Ἀλάστορες. ἑτέρωθεν δὲ προσήγοντο πολλοί τινες ἐφεξῆς, ἁλύσει μακρᾷ δεδεμένοι· ἐλέγοντο δὲ εἶναι μοιχοὶ καὶ πορνοβοσκοὶ καὶ τελῶναι καὶ κόλακες καὶ συκοφάνται καὶ τοιοῦτος ὅμιλος τῶν πάντα κυκώντων ἐν τῷ βίῳ. χωρὶς δὲ οἵ τε πλούσιοι καὶ τοκογλύφοι προσῄεσαν ὠχροὶ καὶ προγάστορες καὶ ποδαγροί, κλοιὸν ἕκαστος αὐτῶν καὶ κόρακα διτάλαντον ἐπικείμενος. ἐφεστῶτες οὖν ἡμεῖς ἑωρῶμέν τε τὰ γιγνόμενα καὶ ἠκούομεν τῶν ἀπολογουμένων· κατηγόρουν δὲ αὐτῶν καινοί τινες καὶ παράδοξοι ῥήτορες.", "st": "35.11"}, {"sp": "N", "t": "<em>Φίλος.<\/em> τίνες οὗτοι, πρὸς Διός; μὴ γὰρ ὀκνήσῃς καὶ τοῦτο εἰπεῖν.", "st": "35.11"}, {"sp": "N", "t": "<em>Μένιππος.<\/em> οἶσθά που ταυτασὶ τὰς πρὸς τὸν ἥλιον ἀποτελουμένας σκιὰς ὑπὸ τῶν σωμάτων;", "st": "35.11"}, {"sp": "N", "t": "<em>Φίλος.<\/em> πάνυ μὲν οὖν.", "st": "35.11"}, {"sp": "N", "t": "<em>Μένιππος.<\/em> αὗται τοίνυν, ἐπειδὰν ἀποθάνωμεν, κατηγοροῦσί τε καὶ καταμαρτυροῦσι καὶ διελέγχουσι τὰ πεπραγμένα ἡμῖν παρὰ τὸν βίον, καὶ σφόδρα τινὲς ἀξιόπιστοι δοκοῦσιν ἅτε ἀεὶ συνοῦσαι καὶ μηδέποτε ἀφιστάμεναι τῶν σωμάτων.", "st": "35.11"}, {"sp": "N", "t": "ὁ δ’ οὖν Μίνως ἐπιμελῶς ἐξετάζων ἀπέπεμπεν ἕκαστον εἰς τὸν τῶν ἀσεβῶν χῶρον δίκην ὑφέξοντα κατ’ ἀξίαν τῶν τετολμημένων, καὶ μάλιστα ἐκείνων ἥπτετο τῶν ἐπὶ πλούτοις τε καὶ ἀρχαῖς τετυφωμένων καὶ μονονουχὶ καὶ προσκυνεῖσθαι περιμενόντων, τήν τε ὀλιγοχρόνιον ἀλαζονείαν αὐτῶν καὶ τὴν ὑπεροψίαν μυσαττόμενος, καὶ ὅτι μὴ ἐμέμνηντο θνητοί τε ὄντες αὐτοὶ καὶ θνητῶν ἀγαθῶν τετυχηκότες. οἳ δὲ ἀποδυσάμενοι τὰ λαμπρὰ ἐκεῖνα πάντα, πλούτους λέγω καὶ γένη καὶ δυναστείας, γυμνοὶ κάτω νενευκότες παρειστήκεσαν ὥσπερ τινὰ ὄνειρον ἀναπεμπαζόμενοι τὴν παρ’ ἡμῖν εὐδαιμονίαν· ὥστ’ ἔγωγε ταῦτα ὁρῶν ὑπερέχαιρον καὶ εἴ τινα γνωρίσαιμι αὐτῶν, προσιὼν ἂν ἡσυχῇ πως ὑπεμίμνησκον οἷος ἦν παρὰ τὸν βίον καὶ ἡλίκον ἐφύσα τότε, ἡνίκα πολλοὶ μὲν ἕωθεν ἐπὶ τῶν πυλώνων παρειστήκεσαν τὴν πρόοδον αὐτοῦ περιμένοντες ὠθούμενοί τε καὶ ἀποκλειόμενοι πρὸς τῶν οἰκετῶν· ὁ δὲ μόλις ἄν ποτε ἀνατείλας αὐτοῖς πορφυροῦς τις ἢ περίχρυσος ἢ διαποίκιλος εὐδαίμονας ᾤετο καὶ μακαρίους ἀποφαίνειν τοὺς προσειπόντας, εἰ τὸ στῆθος ἢ τὴν δεξιὰν προτείνων δοίη καταφιλεῖν. ἐκεῖνοι μὲν οὖν ἠνιῶντο ἀκούοντες.", "st": "35.12"}, {"sp": "N", "t": "τῷ δὲ Μίνῳ μία τις καὶ πρὸς χάριν ἐδικάσθη· τὸν γάρ τοι Σικελιώτην Διονύσιον πολλά γε καὶ δεινὰ καὶ ἀνόσια ὑπό τε Δίωνος κατηγορηθέντα καὶ ὑπὸ τῆς σκιᾶς καταμαρτυρηθέντα παρελθὼν Ἀρίστιππος ὁ Κυρηναῖος — ἄγουσι δ’ αὐτὸν ἐν τιμῇ καὶ δύναται μέγιστον ἐν τοῖς κάτω — μικροῦ δεῖν τῇ Χιμαίρᾳ προσδεθέντα παρέλυσε τῆς καταδίκης λέγων πολλοῖς αὐτὸν τῶν πεπαιδευμένων πρὸς ἀργύριον γενέσθαι δεξιόν.", "st": "35.13"}, {"sp": "N", "t": "ἀποστάντες δὲ ὅμως τοῦ δικαστηρίου πρὸς τὸ κολαστήριον ἀφικνούμεθα. ἔνθα δή, ὦ φιλότης, πολλὰ καὶ ἐλεεινὰ ἦν καὶ ἀκοῦσαι καὶ ἰδεῖν· μαστίγων τε γὰρ ὁμοῦ ψόφος ἠκούετο καὶ οἰμωγὴ τῶν ἐπὶ τοῦ πυρὸς ὀπτωμένων καὶ στρέβλαι καὶ κύφωνες καὶ τροχοί, καὶ ἡ Χίμαιρα ἐσπάραττεν καὶ ὁ Κέρβερος ἐδάρδαπτεν. ἐκολάζοντό τε ἅμα πάντες, βασιλεῖς, δοῦλοι, σατράπαι, πένητες, πλούσιοι, πτωχοί, καὶ μετέμελε πᾶσι τῶν τετολμημένων. ἐνίους δὲ αὐτῶν καὶ ἐγνωρίσαμεν ἰδόντες, ὁπόσοι ἦσαν τῶν ἔναγχος τετελευτηκότων· οἱ δὲ ἐνεκαλύπτοντό τε καὶ ἀπεστρέφοντο, εἰ δὲ καὶ προσβλέποιεν, μάλα δουλοπρεπές τι καὶ κολακευτικόν, καὶ ταῦτα πῶς οἴει βαρεῖς ὄντες καὶ ὑπερόπται παρὰ τὸν βίον; τοῖς μέντοι πένησιν ἡμιτέλεια τῶν κακῶν ἐδίδοτο, καὶ διαναπαυόμενοι πάλιν ἐκολάζοντο. καὶ μὴν κἀκεῖνα εἶδον τὰ μυθώδη, τὸν Ἰξίονα καὶ τὸν Σίσυφον καὶ τὸν Φρύγα Τάνταλον, χαλεπῶς γε ἔχοντα, καὶ τὸν γηγενῆ Τιτυόν, Ἡράκλεις ὅσος· ἔκειτο γοῦν τόπον ἐπέχων ἀγροῦ.", "st": "35.14"}, {"sp": "N", "t": "διελθόντες δὲ καὶ τούτους εἰς τὸ πεδίον εἰσβάλλομεν τὸ Ἀχερούσιον, εὑρίσκομέν τε αὐτόθι τοὺς ἡμιθέους τε καὶ τὰς ἡρωΐνας καὶ τὸν ἄλλον ὅμιλον τῶν νεκρῶν κατὰ ἔθνη καὶ κατὰ φῦλα διαιτωμένους, τοὺς μὲν παλαιούς τινας καὶ εὐρωτιῶντας καὶ ὥς φησιν Ὅμηρος, ἀμενηνούς, τοὺς δ’ ἔτι νεαλεῖς καὶ συνεστηκότας, καὶ μάλιστα τοὺς Αἰγυπτίους αὐτῶν διὰ τὸ πολυαρκὲς τῆς ταριχείας. τὸ μέντοι διαγιγνώσκειν ἕκαστον οὐ πάνυ τι ἦν ῥᾴδιον· ἅπαντες γὰρ ἀτεχνῶς ἀλλήλοις γίγνονται ὅμοιοι τῶν ὀστῶν γεγυμνωμένων. πλὴν ἀλλὰ μόγις τε καὶ διὰ πολλοῦ ἀναθεωροῦντες αὐτοὺς ἐγιγνώσκομεν. ἔκειντο δ’ ἐπ’ ἀλλήλοις ἀμαυροὶ καὶ ἄσημοι καὶ οὐδὲν ἔτι τῶν παρ’ ἡμῖν καλῶν φυλάττοντες. ἀμέλει πολλῶν ἐν ταὐτῷ σκελετῶν κειμένων καὶ πάντων ὁμοίως φοβερόν τι καὶ διάκενον δεδορκότων καὶ γυμνοὺς τοὺς ὀδόντας προφαινόντων, ἠπόρουν πρὸς ἐμαυτὸν ᾧτινι διακρίναιμι τὸν Θερσίτην ἀπὸ τοῦ καλοῦ Νιρέως ἢ τὸν μεταίτην Ἶρον ἀπὸ τοῦ Φαιάκων βασιλέως ἢ Πυρρίαν τὸν μάγειρον ἀπὸ τοῦ Ἀγαμέμνονος. οὐδὲν γὰρ ἔτι τῶν παλαιῶν γνωρισμάτων αὐτοῖς παρέμενεν, ἀλλ’ ὅμοια τὰ ὀστᾶ ἦν, ἄδηλα καὶ ἀνεπίγραφα καὶ ὑπ’ οὐδενὸς ἔτι διακρίνεσθαι δυνάμενα.", "st": "35.15"}, {"sp": "N", "t": "τοιγάρτοι ἐκεῖνα ὁρῶντί μοι ἐδόκει ὁ τῶν ἀνθρώπων βίος πομπῇ τινι μακρᾷ προσεοικέναι, χορηγεῖν δὲ καὶ διατάττειν ἕκαστα ἡ Τύχη, διάφορα καὶ ποικίλα τοῖς πομπευταῖς τὰ σχήματα προσάπτουσα· τὸν μὲν γὰρ λαβοῦσα, εἰ τύχοι, βασιλικῶς διεσκεύασεν, τιάραν τε ἐπιθεῖσα καὶ δορυφόρους παραδοῦσα καὶ τὴν κεφαλὴν στέψασα τῷ διαδήματι, τῷ δὲ οἰκέτου σχῆμα περιέθηκεν· τὸν δέ τινα καλὸν εἶναι ἐκόσμησεν, τὸν δὲ ἄμορφον καὶ γελοῖον παρεσκεύασεν· παντοδαπὴν γάρ, οἶμαι, δεῖ γενέσθαι τὴν θέαν. πολλάκις δὲ καὶ διὰ μέσης τῆς πομπῆς μετέβαλε τὰ ἐνίων σχήματα οὐκ ἐῶσα εἰς τέλος διαπομπεῦσαι ὡς ἐτάχθησαν, ἀλλὰ μεταμφιέσασα τὸν μὲν Κροῖσον ἠνάγκασε τὴν τοῦ οἰκέτου καὶ αἰχμαλώτου σκευὴν ἀναλαβεῖν, τὸν δὲ Μαιάνδριον τέως ἐν τοῖς οἰκέταις πομπεύοντα τὴν τοῦ Πολυκράτους τυραννίδα μετενέδυσε. καὶ μέχρι μέν τινος εἴασε χρῆσθαι τῷ σχήματι· ἐπειδὰν δὲ ὁ τῆς πομπῆς καιρὸς παρέλθῃ, τηνικαῦτα ἕκαστος ἀποδοὺς τὴν σκευὴν καὶ ἀποδυσάμενος τὸ σχῆμα μετὰ τοῦ σώματος ἐγένετο οἷόσπερ ἦν πρὸ τοῦ γενέσθαι, μηδὲν τοῦ πλησίον διαφέρων. ἔνιοι δὲ ὑπ’ ἀγνωμοσύνης, ἐπειδὰν ἀπαιτῇ τὸν κόσμον ἐπιστᾶσα ἡ Τύχη, ἄχθονταί τε καὶ ἀγανακτοῦσιν ὥσπερ οἰκείων τινῶν στερισκόμενοι καὶ οὐχ ἃ πρὸς ὀλίγον ἐχρήσαντο ἀποδιδόντες. οἶμαι δέ σε καὶ τῶν ἐπὶ τῆς σκηνῆς πολλάκις ἑωρακέναι τοὺς τραγικοὺς ὑποκριτὰς τούτους πρὸς τὰς χρείας τῶν δραμάτων ἄρτι μὲν Κρέοντας, ἐνίοτε δὲ Πριάμους γιγνομένους ἢ Ἀγαμέμνονας, καὶ ὁ αὐτός, εἰ τύχοι, μικρὸν ἔμπροσθεν μάλα σεμνῶς τὸ τοῦ Κέκροπος ἢ Ἐρεχθέως σχῆμα μιμησάμενος μετ’ ὀλίγον οἰκέτης προῆλθεν ὑπὸ τοῦ ποιητοῦ κεκελευσμένος. ἤδη δὲ πέρας ἔχοντος τοῦ δράματος ἀποδυσάμενος ἕκαστος αὐτῶν τὴν χρυσόπαστον ἐκείνην ἐσθῆτα καὶ τὸ προσωπεῖον ἀποθέμενος καὶ καταβὰς ἀπὸ τῶν ἐμβατῶν πένης καὶ ταπεινὸς περίεισιν, οὐκέτ’ Ἀγαμέμνων ὁ Ἀτρέως οὐδὲ Κρέων ὁ Μενοικέως, ἀλλὰ Πῶλος Χαρικλέους Σουνιεὺς ὀνομαζόμενος ἢ Σάτυρος Θεογείτονος Μαραθώνιος. τοιαῦτα καὶ τὰ τῶν ἀνθρώπων πράγματά ἐστιν, ὡς τότε μοι ὁρῶντι ἔδοξεν.", "st": "35.16"}, {"sp": "N", "t": "<em>Φίλος.<\/em> εἰπέ μοι, ὦ Μένιππε, οἱ δὲ τοὺς πολυτελεῖς τούτους καὶ ὑψηλοὺς τάφους ἔχοντες ὑπὲρ γῆς καὶ στήλας καὶ εἰκόνας καὶ ἐπιγράμματα οὐδὲν τιμιώτεροι παρ’ αὐτοῖς εἰσι τῶν ἰδιωτῶν νεκρῶν;", "st": "35.17"}, {"sp": "N", "t": "<em>Μένιππος.<\/em> ληρεῖς, ὦ οὗτος· εἰ γοῦν ἐθεάσω τὸν Μαύσωλον αὐτόν, — λέγω δὲ τὸν Κᾶρα, τὸν ἐκ τοῦ τάφου περιβόητον — εὖ οἶδα ὅτι οὐκ ἂν ἐπαύσω γελῶν, οὕτω ταπεινὸς ἔρριπτο ἐν παραβύστῳ που λανθάνων ἐν τῷ λοιπῷ δήμῳ τῶν νεκρῶν, ἐμοὶ δοκεῖν, τοσοῦτον ἀπολαύων τοῦ μνήματος, παρ’ ὅσον ἐβαρύνετο τηλικοῦτον ἄχθος ἐπικείμενος· ἐπειδὰν γάρ, ὦ ἑταῖρε, ὁ Αἰακὸς ἀπομετρήσῃ ἑκάστῳ τὸν τόπον, — δίδωσι δὲ τὸ μέγιστον οὐ πλέον ποδός — ἀνάγκη ἀγαπῶντα κατακεῖσθαι πρὸς τὸ μέτρον συνεσταλμένον. πολλῷ δ’ ἂν οἶμαι μᾶλλον ἐγέλασας, εἰ ἐθεάσω τοὺς παρ’ ἡμῖν βασιλέας καὶ σατράπας πτωχεύοντας παρ’ αὐτοῖς καὶ ἤτοι ταριχοπωλοῦντας ὑπ’ ἀπορίας ἢ τὰ πρῶτα διδάσκοντας γράμματα καὶ ὑπὸ τοῦ τυχόντος ὑβριζομένους καὶ κατὰ κόρρης παιομένους ὥσπερ τῶν ἀνδραπόδων τὰ ἀτιμότατα. Φίλιππον γοῦν τὸν Μακεδόνα ἐγὼ θεασάμενος οὐδὲ κρατεῖν ἐμαυτοῦ δυνατὸς ἦν· ἐδείχθη δέ μοι ἐν γωνίᾳ τινὶ μισθοῦ ἀκούμενος τὰ σαθρὰ τῶν ὑποδημάτων. πολλοὺς δὲ καὶ ἄλλους ἦν ἰδεῖν ἐν ταῖς τριόδοις μεταιτοῦντας, Ξέρξας λέγω καὶ Δαρείους καὶ Πολυκράτας.", "st": "35.17"}, {"sp": "N", "t": "<em>Φίλος.<\/em> ἄτοπα διηγῇ τὰ περὶ τῶν βασιλέων καὶ μικροῦ δεῖν ἄπιστα. τί δὲ ὁ Σωκράτης ἔπραττεν καὶ Διογένης καὶ εἴ τις ἄλλος τῶν σοφῶν;", "st": "35.18"}, {"sp": "N", "t": "<em>Μένιππος.<\/em> ὁ μὲν Σωκράτης κἀκεῖ περίεισιν διελέγχων ἅπαντας· σύνεστι δ’ αὐτῷ Παλαμήδης καὶ Ὀδυσσεὺς καὶ Νέστωρ καὶ εἴ τις ἄλλος λάλος νεκρός. ἔτι μέντοι ἐπεφύσητο αὐτῷ καὶ διῳδήκει ἐκ τῆς φαρμακοποσίας τὰ σκέλη. ὁ δὲ βέλτιστος Διογένης παροικεῖ μὲν Σαρδαναπάλλῳ τῷ Ἀσσυρίῳ καὶ Μίδᾳ τῷ Φρυγὶ καὶ ἄλλοις τισὶ τῶν πολυτελῶν· ἀκούων δὲ οἰμωζόντων αὐτῶν καὶ τὴν παλαιὰν τύχην ἀναμετρουμένων γελᾷ τε καὶ τέρπεται, καὶ τὰ πολλὰ ὕπτιος κατακείμενος ᾄδει μάλα τραχείᾳ καὶ ἀπηνεῖ τῇ φωνῇ τὰς οἰμωγὰς αὐτῶν ἐπικαλύπτων, ὥστε ἀνιᾶσθαι τοὺς ἄνδρας καὶ διασκέπτεσθαι μετοικεῖν οὐ φέροντας τὸν Διογένην.", "st": "35.18"}, {"sp": "N", "t": "<em>Φίλος.<\/em> ταυτὶ μὲν ἱκανῶς· τί δὲ τὸ ψήφισμα ἦν, ὅπερ ἐν ἀρχῇ ἔλεγες κεκυρῶσθαι κατὰ τῶν πλουσίων;", "st": "35.19"}, {"sp": "N", "t": "<em>Μένιππος.<\/em> εὖ γε ὑπέμνησας· οὐ γὰρ οἶδ’ ὅπως περὶ τούτου λέγειν προθέμενος πάμπολυ ἀπεπλανήθην τοῦ λόγου.", "st": "35.19"}, {"sp": "N", "t": "διατρίβοντος γάρ μου παρ’ αὐτοῖς προὔθεσαν οἱ πρυτάνεις ἐκκλησίαν περὶ τῶν κοινῇ συμφερόντων· ἰδὼν οὖν πολλοὺς συνθέοντας ἀναμίξας ἐμαυτὸν τοῖς νεκροῖς εὐθὺς εἷς καὶ αὐτὸς ἦν τῶν ἐκκλησιαστῶν. διῳκήθη μὲν οὖν καὶ ἄλλα, τελευταῖον δὲ τὸ περὶ τῶν πλουσίων· ἐπεὶ γὰρ αὐτῶν κατηγόρητο πολλὰ καὶ δεινά, βία καὶ ἀλαζονεία καὶ ὑπεροψία καὶ ἀδικία, τέλος ἀναστάς τις τῶν δημαγωγῶν ἀνέγνω ψήφισμα τοιοῦτον.", "st": "35.19"}, {"sp": "N", "t": "<em>Ψήφισμα<\/em>", "st": "35.20"}, {"sp": "N", "t": "“ἐπειδὴ πολλὰ καὶ παράνομα οἱ πλούσιοι δρῶσι παρὰ τὸν βίον ἁρπάζοντες καὶ βιαζόμενοι καὶ πάντα τρόπον τῶν πενήτων καταφρονοῦντες,", "st": "35.20"}, {"sp": "N", "t": "δεδόχθω τῇ βουλῇ καὶ τῷ δήμῳ, ἐπειδὰν ἀποθάνωσι, τὰ μὲν σώματα αὐτῶν κολάζεσθαι καθάπερ καὶ τὰ τῶν ἄλλων πονηρῶν, τὰς δὲ ψυχὰς ἀναπεμφθείσας ἄνω εἰς τὸν βίον καταδύεσθαι εἰς τοὺς ὄνους, ἄχρις ἂν ἐν τῷ τοιούτῳ διαγάγωσι μυριάδας ἐτῶν πέντε καὶ εἴκοσιν, ὄνοι ἐξ ὄνων γιγνόμενοι καὶ ἀχθοφοροῦντες καὶ ὑπὸ τῶν πενήτων ἐλαυνόμενοι, τοὐντεῦθεν δὲ λοιπὸν ἐξεῖναι αὐτοῖς ἀποθανεῖν.", "st": "35.20"}, {"sp": "N", "t": "εἶπε τὴν γνώμην Κρανίων Σκελετίωνος Νεκυσιεὺς φυλῆς Ἀλιβαντίδος.”", "st": "35.20"}, {"sp": "N", "t": "Τούτου ἀναγνωσθέντος τοῦ ψηφίσματος ἐπεψήφισαν μὲν αἱ ἀρχαί, ἐπεχειροτόνησε δὲ τὸ πλῆθος καὶ ἐβριμήσατο ἡ Βριμὼ καὶ ὑλάκτησεν ὁ Κέρβερος· οὕτω γὰρ ἐντελῆ γίγνεται καὶ κύρια τὰ ἐγνωσμένα.", "st": "35.20"}, {"sp": "N", "t": "ταῦτα μὲν δή σοι τὰ ἐν τῇ ἐκκλησίᾳ. ἐγὼ δέ, οὗπερ ἀφίγμην ἕνεκα, τῷ Τειρεσίᾳ προσελθὼν ἱκέτευον αὐτὸν τὰ πάντα διηγησάμενος εἰπεῖν πρός με ποῖόν τινα ἡγεῖται τὸν ἄριστον βίον. ὁ δὲ γελάσας — ἔστι δὲ τυφλόν τι γερόντιον καὶ ὠχρὸν καὶ λεπτόφωνον — “Ὦ τέκνον,” φησί, “τήν μὲν αἰτίαν οἶδά σοι τῆς ἀπορίας ὅτι παρὰ τῶν σοφῶν ἐγένετο οὐ ταὐτὰ γιγνωσκόντων ἑαυτοῖς· ἀτὰρ οὐ θέμις λέγειν πρὸς σέ· ἀπείρηται γὰρ ὑπὸ τοῦ Ῥαδαμάνθυος.” “μηδαμῶς,” ἔφην, “ὦ πατέριον, ἀλλ’ εἰπὲ καὶ μὴ περιίδῃς με σοῦ τυφλότερον περιιόντα ἐν τῷ βίῳ.” ὁ δὲ δή με ἀπαγαγὼν καὶ πολὺ τῶν ἄλλων ἀποσπάσας ἤρεμα προσκύψας πρὸς τὸ οὖς φησίν, “ὁ τῶν ἰδιωτῶν ἄριστος βίος, καὶ σωφρονέστερος παυσάμενος τοῦ μετεωρολογεῖν καὶ τέλη καὶ ἀρχὰς ἐπισκοπεῖν καὶ καταπτύσας τῶν σοφῶν τούτων συλλογισμῶν καὶ τὰ τοιαῦτα λῆρον ἡγησάμενος τοῦτο μόνον ἐξ ἅπαντος θηράσῃ, ὅπως τὸ παρὸν εὖ θέμενος παραδράμῃς γελῶν τὰ πολλὰ καὶ περὶ μηδὲν ἐσπουδακώς.”<br>ὣς εἰπὼν πάλιν ὦρτο κατ’ ἀσφοδελὸν λειμῶνα.", "st": "35.21"}, {"sp": "N", "t": "ἐγὼ δὲ — καὶ γὰρ ἤδη ὀψὲ ἦν — “ἄγε δή, ὦ Μιθροβαρζάνη,” φημί, “τί διαμέλλομεν καὶ οὐκ ἄπιμεν αὖθις εἰς τὸν βίον;” ὁ δὲ πρὸς ταῦτα, “θάρρει,” φησίν, “ὦ Μένιππε· ταχεῖαν γάρ σοι καὶ ἀπράγμονα ὑποδείξω ἀτραπόν.” καὶ δὴ ἀγαγών με πρός τι χωρίον τοῦ ἄλλου ζοφερώτερον δείξας τῇ χειρὶ πόρρωθεν ἀμαυρὸν καὶ λεπτὸν ὥσπερ διὰ κλειθρίας φῶς εἰσρέον, “ἐκεῖνο,” ἔφη, “ἐστὶν τὸ ἱερὸν τὸ Τροφωνίου, κἀκεῖθεν κατίασιν οἱ ἀπὸ Βοιωτίας. ταύτην οὖν ἄνιθι καὶ εὐθὺς ἔσῃ ἐπὶ τῆς Ἑλλάδος.” ἡσθεὶς δὲ τοῖς εἰρημένοις ἐγὼ καὶ τὸν μάγον ἀσπασάμενος χαλεπῶς μάλα διὰ τοῦ στομίου ἀνερπύσας οὐκ οἶδ’ ὅπως ἐν Λεβαδείᾳ γίγνομαι.", "st": "35.22"}, {"sp": "HDR", "t": "Περὶ Πένθους"}, {"sp": "N", "t": "ἄξιόν γε παρατηρεῖν τὰ ὑπὸ τῶν πολλῶν ἐν τοῖς πένθεσι γιγνόμενα καὶ λεγόμενα καὶ τὰ ὑπὸ τῶν παραμυθουμένων δῆθεν αὐτοὺς αὖθις λεγόμενα, καὶ ὡς ἀφόρητα ἡγοῦνται τὰ συμβαίνοντα σφίσι τε αὐτοῖς οἱ ὀδυρόμενοι καὶ ἐκείνοις οὓς ὀδύρονται, οὐ μὰ τὸν Πλούτωνα καὶ Φερσεφόνην κατ’ οὐδὲν ἐπιστάμενοι σαφῶς οὔτε εἰ πονηρὰ ταῦτα καὶ λύπης ἄξια οὔτε εἰ τοὐναντίον ἡδέα καὶ βελτίω τοῖς παθοῦσι, νόμῳ δὲ καὶ συνηθείᾳ τὴν λύπην ἐπιτρέποντες. ἐπειδὰν τοίνυν ἀποθάνῃ τις, οὕτω ποιοῦσιν — μᾶλλον δὲ πρότερον εἰπεῖν βούλομαι ἅστινας περὶ αὐτοῦ τοῦ θανάτου δόξας ἔχουσιν· οὕτω γὰρ ἔσται φανερὸν οὗτινος ἕνεκα τὰ περιττὰ ἐκεῖνα ἐπιτηδεύουσιν.", "st": "36.1"}, {"sp": "N", "t": "ὁ μὲν δὴ πολὺς ὅμιλος, οὓς ἰδιώτας οἱ σοφοὶ καλοῦσιν, Ὁμήρῳ τε καὶ Ἡσιόδῳ καὶ τοῖς ἄλλοις μυθοποιοῖς περὶ τούτων πειθόμενοι καὶ νόμον θέμενοι τὴν ποίησιν αὐτῶν, τόπον τινα ὑπὸ τῇ γῇ βαθὺν Ἅιδην ὑπειλήφασιν, μέγαν δὲ καὶ πολύχωρον τοῦτον εἶναι καὶ ζοφερὸν καὶ ἀνήλιον, οὐκ οἶδ’ ὅπως αὐτοῖς φωτίζεσθαι δοκοῦντα πρὸς τὸ καὶ καθορᾶν τῶν ἐνόντων ἕκαστον· βασιλεύειν δὲ τοῦ χάσματος ἀδελφὸν τοῦ Διὸς Πλούτωνα κεκλημένον, ὥς μοι τῶν τὰ τοιαῦτα δεινῶν τις ἔλεγε, διὰ τὸ πλουτεῖν τοῖς νεκροῖς τῇ προσηγορίᾳ τετιμημένον. τοῦτον δὲ τὸν Πλούτωνα τὴν παρ’ αὑτῷ πολιτείαν καὶ τὸν κάτω βίον καταστήσασθαι τοιοῦτον· κεκληρῶσθαι μὲν γὰρ αὐτὸν ἄρχειν τῶν ἀποθανόντων, καταδεξάμενον δὲ αὐτοὺς καὶ παραλαβόντα κατέχειν δεσμοῖς ἀφύκτοις, οὐδενὶ τὸ παράπαν τῆς ἄνω ὁδοῦ ὑφιέμενον πλὴν ἐξ ἅπαντος τοῦ αἰῶνος πάνυ ὀλίγων ἐπὶ μεγίσταις αἰτίαις.", "st": "36.2"}, {"sp": "N", "t": "περιρρεῖσθαι δὲ τὴν χώραν αὐτοῦ ποταμοῖς μεγάλοις τε καὶ φοβεροῖς καὶ ἐκ μόνων τῶν ὀνομάτων· Κωκυτοὶ γὰρ καὶ Πυριφλεγέθοντες καὶ τὰ τοιαῦτα κέκληνται. τὸ δὲ μέγιστον, ἡ Ἀχερουσία λίμνη πρόκειται πρώτη δεχομένη τοὺς ἀπαντῶντας, ἣν οὐκ ἔνι διαπλεῦσαι ἢ παρελθεῖν ἄνευ τοῦ πορθμέως· βαθεῖά τε γὰρ περᾶσαι τοῖς ποσὶν καὶ διανήξασθαι πολλή, καὶ ὅλως οὐκ ἂν αὐτὴν διαπταίη οὐδὲ τὰ νεκρὰ τῶν ὀρνέων.", "st": "36.3"}, {"sp": "N", "t": "πρὸς δὲ αὐτῇ τῇ καθόδῳ καὶ πύλῃ οὔσῃ ἀδαμαντίνῃ ἀδελφιδοῦς τοῦ βασιλέως Αἰακὸς ἕστηκε τὴν φρουρὰν ἐπιτετραμμένος καὶ παρ’ αὐτῷ κύων τρικέφαλος μάλα κάρχαρος, τοὺς μὲν ἀφικνουμένους φίλιόν τι καὶ εἰρηνικὸν προσβλέπων, τοὺς δὲ πειρῶντας ἀποδιδράσκειν ὑλακτῶν καὶ τῷ χάσματι δεδιττόμενος.", "st": "36.4"}, {"sp": "N", "t": "περαιωθέντας δὲ τὴν λίμνην εἰς τὸ εἴσω λειμὼν ὑποδέχεται μέγας τῷ ἀσφοδέλῳ κατάφυτος καὶ ποτὸν μνήμης πολέμιον· Λήθης γοῦν διὰ τοῦτο ὠνόμασται. ταῦτα γὰρ ἀμέλει διηγήσαντο τοῖς πάλαι ἐκεῖθεν ἀφιγμένοι Ἄλκηστίς τε καὶ Πρωτεσίλαος οἱ Θετταλοὶ καὶ Θησεὺς ὁ τοῦ Αἰγέως καὶ ὁ τοῦ Ὁμήρου Ὀδυσσεύς, μάλα σεμνοὶ καὶ ἀξιόπιστοι μάρτυρες, ἐμοὶ δοκεῖν οὐ πιόντες τῆς πηγῆς· οὐ γὰρ ἂν ἐμέμνηντο αὐτῶν.", "st": "36.5"}, {"sp": "N", "t": "ὁ μὲν οὖν Πλούτων, ὡς ἐκεῖνοι ἔφασαν, καὶ ἡ Φερσεφόνη δυναστεύουσι καὶ τὴν τῶν ὅλων δεσποτείαν ἔχουσιν, ὑπηρετοῦσι δ’ αὐτοῖς καὶ τὴν ἀρχὴν συνδιαπράττουσιν ὄχλος πολύς, Ἐρινύες τε καὶ Ποιναὶ καὶ Φόβοι καὶ ὁ Ἑρμῆς, οὗτος μέν γε οὐκ ἀεὶ συμπαρών.", "st": "36.6"}, {"sp": "N", "t": "ὕπαρχοι δὲ καὶ σατράπαι καὶ δικασταὶ κάθηνται δύο, Μίνως τε καὶ Ῥαδάμανθυς οἱ Κρῆτες, ὄντες υἱοὶ τοῦ Διός. οὗτοι δὲ τοὺς μὲν ἀγαθοὺς τῶν ἀνδρῶν καὶ δικαίους καὶ κατ’ ἀρετὴν βεβιωκότας, ἐπειδὰν συναλισθῶσι πολλοί, καθάπερ εἰς ἀποικίαν τινὰ πέμπουσιν εἰς τὸ Ἠλύσιον πεδίον τῷ ἀρίστῳ βίῳ συνεσομένους.", "st": "36.7"}, {"sp": "N", "t": "ἂν δέ τινας τῶν πονηρῶν λάβωσι, ταῖς Ἐρινύσι παραδόντες εἰς τὸν τῶν ἀσεβῶν χῶρον εἰσπέμπουσι κατὰ λόγον τῆς ἀδικίας κολασθησομένους. ἔνθα δὴ τί κακῶν οὐ πάσχουσι στρεβλούμενοί τε καὶ καιόμενοι καὶ ὑπὸ γυπῶν ἐσθιόμενοι καὶ τροχῷ συμπεριφερόμενοι καὶ λίθους ἀνακυλίοντες; ὁ μὲν γὰρ Τάνταλος ἐπ’ αὐτῇ τῇ λίμνῃ αὖος ἕστηκεν κινδυνεύων ὑπὸ δίψους ὁ κακοδαίμων ἀποθανεῖν.", "st": "36.8"}, {"sp": "N", "t": "οἱ δὲ τοῦ μέσου βίου, πολλοὶ ὄντες οὗτοι, ἐν τῷ λειμῶνι πλανῶνται ἄνευ τῶν σωμάτων σκιαὶ γενόμενοι καὶ ὑπὸ τῇ ἁφῇ καθάπερ καπνὸς ἀφανιζόμενοι. τρέφονται δὲ ἄρα ταῖς παρ’ ἡμῖν χοαῖς καὶ τοῖς καθαγιζομένοις ἐπὶ τῶν τάφων· ὡς εἴ τῳ μὴ εἴη καταλελειμμένος ὑπὲρ γῆς φίλος ἢ συγγενής, ἄσιτος οὗτος νεκρὸς καὶ λιμώττων ἐν αὐτοῖς πολιτεύεται.", "st": "36.9"}, {"sp": "N", "t": "ταῦτα οὕτως ἰσχυρῶς περιελήλυθε τοὺς πολλοὺς ὥστε ἐπειδάν τις ἀποθάνῃ τῶν οἰκείων, πρῶτα μὲν φέροντες ὀβολὸν εἰς τὸ στόμα κατέθηκαν αὐτῷ, μισθὸν τῷ πορθμεῖ τῆς ναυτιλίας γενησόμενον, οὐ πρότερον ἐξετάσαντες ὁποῖον τὸ νόμισμα νομίζεται καὶ διαχωρεῖ παρὰ τοῖς κάτω, καὶ εἰ δύναται παρ’ ἐκείνοις Ἀττικὸς ἢ Μακεδονικὸς ἢ Αἰγιναῖος ὀβολός, οὐδ’ ὅτι πολὺ κάλλιον ἦν μὴ ἔχειν τὰ πορθμεῖα καταβαλεῖν· οὕτω γὰρ ἂν οὐ παραδεξαμένου τοῦ πορθμέως ἀναπόμπιμοι πάλιν εἰς τὸν βίον ἀφικνοῦντο.", "st": "36.10"}, {"sp": "N", "t": "μετὰ ταῦτα δὲ λούσαντες αὐτούς, ὡς οὐχ ἱκανῆς τῆς κάτω λίμνης λουτρὸν εἶναι τοῖς ἐκεῖ, καὶ μύρῳ τῷ καλλίστῳ χρίσαντες τὸ σῶμα πρὸς δυσωδίαν ἤδη βιαζόμενον καὶ στεφανώσαντες τοῖς ὡραίοις ἄνθεσι προτίθενται λαμπρῶς ἀμφιέσαντες, ἵνα μὴ ῥιγῷεν δῆλον ὅτι παρὰ τὴν ὁδὸν μηδὲ γυμνοὶ βλέποιντο τῷ Κερβέρῳ.", "st": "36.11"}, {"sp": "N", "t": "οἰμωγαὶ δὲ ἐπὶ τούτοις καὶ κωκυτὸς γυναικῶν καὶ παρὰ πάντων δάκρυα καὶ στέρνα τυπτόμενα καὶ σπαραττομένη κόμη καὶ φοινισσόμεναι παρειαί· καί που καὶ ἐσθὴς καταρρήγνυται καὶ κόνις ἐπὶ τῇ κεφαλῇ πάσσεται, καὶ οἱ ζῶντες οἰκτρότεροι τοῦ νεκροῦ· οἱ μὲν γὰρ χαμαὶ κυλινδοῦνται πολλάκις καὶ τὰς κεφαλὰς ἀράττουσι πρὸς τὸ ἔδαφος, ὁ δ’ εὐσχήμων καὶ καλὸς καὶ καθ’ ὑπερβολὴν ἐστεφανωμένος ὑψηλὸς πρόκειται καὶ μετέωρος ὥσπερ εἰς πομπὴν κεκοσμημένος.", "st": "36.12"}, {"sp": "N", "t": "εἶθ’ ἡ μήτηρ ἢ καὶ νὴ Δία ὁ πατὴρ ἐκ μέσων τῶν συγγενῶν προελθὼν καὶ περιχυθεὶς αὐτῷ — προκείσθω γάρ τις νέος καὶ καλός, ἵνα καὶ ἀκμαιότερον τὸ ἐπ’ αὐτῷ δρᾶμα ᾖ — φωνὰς ἀλλοκότους καὶ ματαίας ἀφίησι, πρὸς ἃς ὁ νεκρὸς αὐτὸς ἀποκρίναιτ’ ἄν, εἰ λάβοι φωνήν· φήσει γὰρ ὁ πατὴρ γοερόν τι φθεγγόμενος καὶ παρατείνων ἕκαστον τῶν ὀνομάτων, “τέκνον ἥδιστον, οἴχῃ μοι καὶ τέθνηκας καὶ πρὸ ὥρας ἀνηρπάσθης, μόνον ἐμὲ τὸν ἄθλιον καταλιπών, οὐ γαμήσας, οὐ παιδοποιησάμενος, οὐ στρατευσάμενος, οὐ γεωργήσας, οὐκ εἰς γῆρας ἐλθών· οὐ κωμάσῃ πάλιν οὐδὲ ἐρασθήσῃ, τέκνον, οὐδὲ ἐν συμποσίοις μετὰ τῶν ἡλικιωτῶν μεθυσθήσῃ.”", "st": "36.13"}, {"sp": "N", "t": "ταῦτα δὲ καὶ τὰ τοιαῦτα φήσει οἰόμενος τὸν υἱὸν δεῖσθαι μὲν ἔτι τούτων καὶ ἐπιθυμεῖν καὶ μετὰ τὴν τελευτήν, οὐ δύνασθαι δὲ μετέχειν αὐτῶν. καίτοι τί ταῦτα φημί; πόσοι γὰρ καὶ ἵππους καὶ παλλακίδας, οἱ δὲ καὶ οἰνοχόους ἐπικατέσφαξαν καὶ ἐσθῆτα καὶ τὸν ἄλλον κόσμον συγκατέφλεξαν ἢ συγκατώρυξαν ὡς χρησομένοις ἐκεῖ καὶ ἀπολαύσουσιν αὐτῶν κάτω;", "st": "36.14"}, {"sp": "N", "t": "ὁ δ’ οὖν πρεσβύτης ὁ πενθῶν οὑτωσὶ ταῦτα πάντα ὁπόσα εἴρηκα καὶ ἔτι τούτων πλείονα οὔτε τοῦ παιδὸς ἕνεκα τραγῳδεῖν ἔοικεν — οἶδε γὰρ οὐκ ἀκουσόμενον οὐδ’ ἂν μεῖζον ἐμβοήσῃ τοῦ Στέντορος — οὔτε μὴν αὑτοῦ· φρονεῖν γὰρ οὕτω καὶ γιγνώσκειν ἱκανὸν ἦν καὶ ἄνευ τῆς βοῆς· οὐδεὶς γὰρ δὴ πρὸς ἑαυτὸν δεῖται βοᾶν. λοιπὸν οὖν ἐστιν αὐτὸν τῶν παρόντων ἕνεκα ταῦτα ληρεῖν οὔθ’ ὅ τι πέπονθεν αὐτῷ ὁ παῖς εἰδότα οὔθ’ ὅποι κεχώρηκε, μᾶλλον δὲ οὐδὲ τὸν βίον αὐτὸν ἐξετάσαντα ὁποῖός ἐστιν· οὐ γὰρ ἂν τὴν ἐξ αὐτοῦ μετάστασιν ὥς τι τῶν δεινῶν ἐδυσχέραινεν.", "st": "36.15"}, {"sp": "N", "t": "εἴποι δ’ ἂν οὖν πρὸς αὐτὸν ὁ παῖς παραιτησάμενος τὸν Αἰακὸν καὶ τὸν Ἀϊδωνέα πρὸς ὀλίγον τοῦ στομίου ὑπερκῦψαι καὶ τὸν πατέρα παῦσαι ματαιάζοντα, “ὦ κακόδαιμον ἄνθρωπε, τί κέκραγας; τί δέ μοι παρέχεις πράγματα; παῦσαι τιλλόμενος τὴν κόμην καὶ τὸ πρόσωπον ἐξ ἐπιπολῆς ἀμύσσων. τί μοι λοιδορῇ καὶ ἄθλιον ἀποκαλεῖς καὶ δύσμορον πολύ σου βελτίω καὶ μακαριώτερον γεγενημένον; ἢ τί σοι δεινὸν πάσχειν δοκῶ; ἢ διότι μὴ τοιουτοσὶ γέρων ἐγενόμην οἷος εἶ σύ, φαλακρὸς μὲν τὴν κεφαλήν, τὴν δὲ ὄψιν ἐρρυτιδωμένος, κυφὸς καὶ τὰ γόνατα νωθής, καὶ ὅλως ὑπὸ τοῦ χρόνου σαθρὸς πολλὰς τριακάδας καὶ ὀλυμπιάδας ἀναπλήσας, καὶ τὰ τελευταῖα δὴ ταῦτα παραπαίων ἐπὶ τοσούτων μαρτύρων; ὦ μάταιε, τί σοι χρηστὸν εἶναι δοκεῖ παρὰ τὸν βίον οὗ μηκέτι μεθέξομεν; ἢ τοὺς πότους ἐρεῖς δῆλον ὅτι καὶ τὰ δεῖπνα καὶ ἐσθῆτα καὶ ἀφροδίσια, καὶ δέδιας μὴ τούτων ἐνδεὴς γενόμενος ἀπόλωμαι. οὐκ ἐννοεῖς δὲ ὅτι τὸ μὴ διψῆν τοῦ πιεῖν πολὺ κάλλιον καὶ τὸ μὴ πεινῆν τοῦ φαγεῖν καὶ τὸ μὴ ῥιγοῦν τοῦ ἀμπεχόνης εὐπορεῖν; φέρε τοίνυν, ἐπειδὴ ἔοικας ἀγνοεῖν, διδάξομαί σε θρηνεῖν ἀληθέστερον,”", "st": "36.16"}, {"sp": "N", "t": "καὶ δὴ ἀναλαβὼν ἐξ ὑπαρχῆς βόα, “τέκνον ἄθλιον, οὐκέτι διψήσεις, οὐκέτι πεινήσεις οὐδὲ ῥιγώσεις. οἴχῃ μοι κακοδαίμων ἐκφυγὼν τὰς νόσους, οὐ πυρετὸν ἔτι δεδιώς, οὐ πολέμιον, οὐ τύραννον· οὐκ ἔρως σε ἀνιάσει οὐδὲ συνουσία διαστρέψει, οὐδὲ σπαθήσεις ἐπὶ τούτῳ δὶς ἢ τρὶς τῆς ἡμέρας, ὢ τῆς συμφορᾶς. οὐ καταφρονηθήσῃ γέρων γενόμενος οὐδὲ ὀχληρὸς ἔσῃ τοῖς νέοις βλεπόμενος.”", "st": "36.17"}, {"sp": "N", "t": "ἂν ταῦτα λέγῃς, ὦ πάτερ, οὐκ οἴει πολὺ ἀληθέστερα καὶ γενναιότερα ἐκείνων ἐρεῖν;", "st": "36.18"}, {"sp": "N", "t": "ἀλλ’ ἆρα μὴ τόδε σε ἀνιᾷ, καὶ διανοῇ τὸν παρ’ ἡμῖν ζόφον καὶ τὸ πολὺ σκότος, κᾆτα δέδιας μή σοι ἀποπνιγῶ κατακλεισθεὶς ἐν τῷ μνήματι; χρὴ δὲ πρὸς ταῦτα λογίζεσθαι ὅτι τῶν ὀφθαλμῶν διασαπέντων ἢ καὶ νὴ Δία καέντων μετ’ ὀλίγον, εἴ γε καῦσαί με διεγνώκατε, οὔτε σκότος οὔτε φῶς ὁρᾶν δεησόμεθα.", "st": "36.18"}, {"sp": "N", "t": "καὶ ταῦτα μὲν ἴσως μέτρια· τί δέ με ὁ κωκυτὸς ὑμῶν ὀνίνησι καὶ ἡ πρὸς τὸν αὐλὸν αὕτη στερνοτυπία καὶ ἡ τῶν γυναικῶν περὶ τὸν θρῆνον ἀμετρία; τί δὲ ὁ ὑπὲρ τοῦ τάφου λίθος ἐστεφανωμένος; ἢ τί ὑμῖν δύναται τὸν ἄκρατον ἐπιχεῖν; ἢ νομίζετε καταστάξειν αὐτὸν πρὸς ἡμᾶς καὶ μέχρι τοῦ Ἅιδου διίξεσθαι; τὰ μὲν γὰρ ἐπὶ τῶν καθαγισμῶν καὶ αὐτοὶ ὁρᾶτε, οἶμαι, ὡς τὸ μὲν νοστιμώτατον τῶν παρεσκευασμένων ὁ καπνὸς παραλαβὼν ἄνω εἰς τὸν οὐρανὸν οἴχεται μηδέν τι ἡμᾶς ὀνῆσαν τοὺς κάτω, τὸ δὲ καταλειπόμενον, ἡ κόνις, ἀχρεῖον, ἐκτὸς εἰ μὴ τὴν σποδὸν ἡμᾶς σιτεῖσθαι πεπιστεύκατε. οὐχ οὕτως ἄσπορος οὐδὲ ἄκαρπος ἡ τοῦ Πλούτωνος ἀρχή, οὐδὲ ἐπιλέλοιπεν ἡμᾶς ὁ ἀσφόδελος, ἵνα παρ’ ὑμῶν τὰ σιτία μεταστελλώμεθα. ὥστε μοι νὴ τὴν Τισιφόνην πάλαι δὴ ἐφ’ οἷς ἐποιεῖτε καὶ ἐλέγετε παμμέγεθες ἐπῄει ἀνακαγχάσαι, διεκώλυσε δὲ ἡ ὀθόνη καὶ τὰ ἔρια, οἷς μου τὰς σιαγόνας ἀπεσφίγξατε.", "st": "36.19"}, {"sp": "N", "t": "ὣς ἄρα μιν εἰπόντα τέλος θανάτοιο κάλυψε.", "st": "36.20"}, {"sp": "N", "t": "πρὸς Διός, ἐὰν λέγῃ ταῦτα ὁ νεκρὸς ἐπιστραφείς, ἀνακλίνας αὑτὸν ἐπ’ ἀγκῶνος, οὐκ ἂν οἰόμεθα δικαιότατα ἂν αὐτὸν εἰπεῖν; ἀλλ’ ὅμως οἱ μάταιοι καὶ βοῶσι καὶ μεταστειλάμενοί τινα θρήνων σοφιστὴν πολλὰς συνειλοχότα παλαιὰς συμφορὰς τούτῳ συναγωνιστῇ καὶ χορηγῷ τῆς ἀνοίας καταχρῶνται, ὅπη ἂν ἐκεῖνος ἐξάρχῃ πρὸς τὸ μέλος ἐπαιάζοντες.", "st": "36.20"}, {"sp": "N", "t": "καὶ μέχρι μὲν θρήνων ὁ αὐτὸς ἅπασι νόμος τῆς ἀβελτερίας· τὸ δὲ ἀπὸ τούτου διελόμενοι κατὰ ἔθνη τὰς ταφὰς ὁ μὲν Ἕλλην ἔκαυσεν, ὁ δὲ Πέρσης ἔθαψεν, ὁ δὲ Ἰνδὸς ὑάλῳ περιχρίει, ὁ δὲ Σκύθης κατεσθίει, ταριχεύει δὲ ὁ Αἰγύπτιος· οὗτος μέν γε — λέγω δὲ ἰδών — ξηράνας τὸν νεκρὸν σύνδειπνον καὶ συμπότην ἐποιήσατο. πολλάκις δὲ καὶ δεομένῳ χρημάτων ἀνδρὶ Αἰγυπτίῳ ἔλυσε τὴν ἀπορίαν ἐνέχυρον ἢ ὁ ἀδελφὸς ἢ ὁ πατὴρ ἐν καιρῷ γενόμενος.", "st": "36.21"}, {"sp": "N", "t": "χώματα μὲν γὰρ καὶ πυραμίδες καὶ στῆλαι καὶ ἐπιγράμματα πρὸς ὀλίγον διαρκοῦντα πῶς οὐ περιττὰ καὶ παιδιαῖς προσεοικότα;", "st": "36.22"}, {"sp": "N", "t": "καίτοι καὶ ἀγῶνας ἔνιοι διέθεσαν καὶ λόγους ἐπιταφίους εἶπον ἐπὶ τῶν μνημάτων ὥσπερ συναγορεύοντες ἢ μαρτυροῦντες παρὰ τοῖς κάτω δικασταῖς τῷ νεκρῷ.", "st": "36.23"}, {"sp": "N", "t": "ἐπὶ πᾶσι τούτοις τὸ περίδειπνον, καὶ πάρεισιν οἱ προσήκοντες καὶ τοὺς γονέας παραμυθοῦνται τοῦ τετελευτηκότος καὶ πείθουσι γεύσασθαι, οὐκ ἀηδῶς μὰ Δία οὐδ’ αὐτοὺς ἀναγκαζομένους, ἀλλὰ ἤδη ὑπὸ λιμοῦ τριῶν ἑξῆς ἡμερῶν ἀπηυδηκότας. καί, “μέχρι μὲν τίνος, ὦ οὗτος, ὀδυρόμεθα; ἔασον ἀναπαύσασθαι τοὺς τοῦ μακαρίτου δαίμονας· εἰ δὲ καὶ τὸ παράπαν κλάειν διέγνωκας, αὐτοῦ γε τούτου ἕνεκα χρὴ μὴ ἀπόσιτον εἶναι, ἵνα καὶ διαρκέσῃς πρὸς τοῦ πένθους τὸ μέγεθος.” τότε δὴ τότε ῥαψωδοῦνται πρὸς ἁπάντων δύο τοῦ Ὁμήρου στίχοι·<br>“καὶ γάρ τ’ ἠΰκομος Νιόβη ἐμνήσατο σίτου·”<br>καὶ<br>“γαστέρι δ’ οὔπως ἐστὶ νέκυν πενθῆσαι Ἀχαιούς.”<br>οἱ δὲ ἅπτονται μέν, αἰσχυνόμενοι δὲ τὰ πρῶτα καὶ δεδιότες εἰ φανοῦνται μετὰ τὴν τελευτὴν τῶν φιλτάτων τοῖς ἀνθρωπίνοις πάθεσιν ἐμμένοντες.", "st": "36.24"}, {"sp": "N", "t": "ταῦτα καὶ πολὺ τούτων γελοιότερα εὕροι τις ἂν ἐπιτηρῶν ἐν τοῖς πένθεσι γιγνόμενα διὰ τὸ τοὺς πολλοὺς τὸ μέγιστον τῶν κακῶν τὸν θάνατον οἴεσθαι.", "st": "36.24"}], []);})();
